// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/proxy/Clones.sol";

// internal
import "../../utils/proxy/ProxyReentrancyGuard.sol";
import "../../utils/proxy/ProxyOwned.sol";
import "../../utils/proxy/ProxyPausable.sol";
import "@thales-dao/contracts/contracts/interfaces/IReferrals.sol";
import "@thales-dao/contracts/contracts/interfaces/IMultiCollateralOnOffRamp.sol";
import "@thales-dao/contracts/contracts/interfaces/IStakingThales.sol";
import "@thales-dao/contracts/contracts/interfaces/IPriceFeed.sol";

import "./Ticket.sol";
import "../../interfaces/ISportsAMMV2.sol";
import "../../interfaces/ISportsAMMV2Manager.sol";
import "../../interfaces/ISportsAMMV2RiskManager.sol";
import "../../interfaces/ISportsAMMV2ResultManager.sol";
import "../../interfaces/ISportsAMMV2LiquidityPool.sol";
import "../../interfaces/IWeth.sol";
import "../../interfaces/IProxyBetting.sol";
import "./SportsAMMV2Utils.sol";

/// @title Sports AMM V2 contract
/// @author vladan
contract SportsAMMV2 is Initializable, ProxyOwned, ProxyPausable, ProxyReentrancyGuard {
    /* ========== LIBRARIES ========== */

    using SafeERC20 for IERC20;

    /* ========== CONST VARIABLES ========== */

    uint private constant ONE = 1e18;
    uint private constant MAX_APPROVAL = type(uint256).max;
    // roots per game and type: first 16 bytes of the root, two per storage slot
    bytes32 private constant LOW_HALF_MASK = bytes32(uint256(type(uint128).max));
    bytes32 private constant HIGH_HALF_MASK = ~LOW_HALF_MASK;
    uint private constant PACKED_ROOT_GAME_HEADER = 33; // game (32 bytes) + count (1 byte)
    uint private constant PACKED_ROOT_ENTRY = 18; // typeId (2 bytes) + root (16 bytes)
    // rootPerGame marker of a game served per type: matches no proof, cannot be overwritten
    bytes32 public constant ROOT_PER_GAME_RETIRED = bytes32(uint256(1));
    uint8 private constant NON_SYSTEM_BET = 0;

    /* ========== ERRORS ========== */
    error SBDOutOfRange();
    error IllegalInputAmounts();
    error OnlyDedicatedProcessor();
    error UndefinedRecipient();
    error UnknownTicket();
    error UnsupportedSender();
    error OfframpOnlyDefaultCollateralAllowed();
    error InsuffETHSent();
    error ZeroPriceForCollateral();
    error InsuffReceived();
    error InvalidLength();
    error RootPerGameRetired();
    error InvalidSender();
    error MultiCollatDisabled();
    error OnlyTicketOwner();

    /* ========== STRUCT VARIABLES ========== */
    struct TradeDataInternal {
        uint _buyInAmount;
        uint _expectedPayout;
        uint _additionalSlippage;
        address _recipient;
        bool _isLive;
        address _collateral;
        address _collateralPool;
        uint _collateralPriceInUSD;
        bool _isSGP;
    }

    /* ========== STATE VARIABLES ========== */

    // merkle tree root per game
    mapping(bytes32 => bytes32) public rootPerGame;

    // the default token used for payment
    IERC20 public defaultCollateral;

    // Liquidity pool instance for the given collateral
    mapping(address => address) public liquidityPoolForCollateral;

    // decimals of the default collateral
    uint private defaultCollateralDecimals;

    // manager address
    ISportsAMMV2Manager public manager;

    // risk manager address
    ISportsAMMV2RiskManager public riskManager;

    // result manager address
    ISportsAMMV2ResultManager public resultManager;

    // referrals address
    IReferrals public referrals;

    // ticket mastercopy address
    address public ticketMastercopy;

    // safe box address
    address public safeBox;

    // safe box fee paid on each trade
    uint public safeBoxFee;

    // multi-collateral on/off ramp address
    IMultiCollateralOnOffRamp public multiCollateralOnOffRamp;

    // is multi-collateral enabled
    bool private multicollateralEnabled;

    // staking thales address
    IStakingThales private stakingThales;

    // CL client that processes live requests
    address public liveTradingProcessor;

    // the contract that processes all free bets
    address public freeBetsHolder;

    // support bonus payouts for some collaterals (e.g. THALES)
    mapping(address => uint) public addedPayoutPercentagePerCollateral;

    // support different SB per collateral, namely THALES as a collateral will be directly burned
    mapping(address => address) public safeBoxPerCollateral;

    // the contract that processes betting with StakedTHALES
    address private stakingThalesBettingProxy;

    struct TradeProcessingParams {
        uint _totalQuote;
        uint _payout;
        uint _fees;
        uint _addedPayoutPercentage;
        uint _payoutWithFees;
    }

    // CL client that processes SGP requests
    address public sgpTradingProcessor;

    struct TradeTypeData {
        uint8 _systemBetDenominator;
        bool _isSGP;
        bool _isLive;
    }

    // the contract that can call cashout method
    address public cashoutProcessor;

    // utils contract for offloading code to reduce contract size
    SportsAMMV2Utils public sportsAMMV2Utils;

    // merkle tree roots per game and type, packed: slot = typeId >> 1, even typeId high 16 bytes, odd low 16 bytes
    mapping(bytes32 => mapping(uint16 => bytes32)) internal packedRootsPerGameAndType;

    // declare that it can receive eth
    receive() external payable {}

    /* ========== CONSTRUCTOR ========== */

    /// @notice initialize the storage in the proxy contract with the parameters
    /// @param _owner owner for using the onlyOwner functions
    function initialize(address _owner) public initializer {
        setOwner(_owner);
        initNonReentrant();
    }

    /* ========== EXTERNAL READ FUNCTIONS ========== */

    /// @notice get roots for the list of games
    /// @param _games to return roots for
    function getRootsPerGames(bytes32[] calldata _games) external view returns (bytes32[] memory _roots) {
        uint len = _games.length;
        _roots = new bytes32[](len);

        unchecked {
            for (uint i; i < len; ++i) {
                _roots[i] = rootPerGame[_games[i]];
            }
        }
    }

    /// @notice root of the merkle tree per game and type (first 16 bytes, left-aligned; zero if unset)
    /// @param _game game ID
    /// @param _typeId type ID
    function rootPerGameAndType(bytes32 _game, uint16 _typeId) public view returns (bytes32) {
        bytes32 slot = packedRootsPerGameAndType[_game][_typeId >> 1];
        return (_typeId & 1 == 0) ? slot & HIGH_HALF_MASK : slot << 128;
    }

    /// @notice gets trade quote
    /// @param _tradeData trade data with all market info needed for ticket
    /// @param _buyInAmount ticket buy-in amount
    /// @param _collateral different collateral used for payment
    /// @param _isLive whether this is a live bet
    /// @return totalQuote total ticket quote
    /// @return payout expected payout
    /// @return fees ticket fees
    /// @return amountsToBuy amounts per market
    /// @return buyInAmountInDefaultCollateral buy-in amount in default collateral
    /// @return riskStatus risk status
    function tradeQuote(
        ISportsAMMV2.TradeData[] calldata _tradeData,
        uint _buyInAmount,
        address _collateral,
        bool _isLive
    )
        external
        view
        returns (
            uint totalQuote,
            uint payout,
            uint fees,
            uint[] memory amountsToBuy,
            uint buyInAmountInDefaultCollateral,
            ISportsAMMV2RiskManager.RiskStatus riskStatus
        )
    {
        SportsAMMV2Utils.TradeQuoteCommonParams memory p = _buildTradeQuoteCommonParams(_collateral);
        (totalQuote, payout, fees, amountsToBuy, buyInAmountInDefaultCollateral, riskStatus) = sportsAMMV2Utils
            .tradeQuoteCommon(_tradeData, _buyInAmount, _collateral, _isLive, NON_SYSTEM_BET, p);
    }

    /// @notice gets trade quote
    /// @param _tradeData trade data with all market info needed for ticket
    /// @param _buyInAmount ticket buy-in amount
    /// @param _collateral different collateral used for payment
    /// @param _isLive whether this is a live bet
    /// @param _systemBetDenominator the denominator for system bets
    /// @return totalQuote total ticket quote
    /// @return payout expected payout
    /// @return fees ticket fees
    /// @return amountsToBuy amounts per market
    /// @return buyInAmountInDefaultCollateral buy-in amount in default collateral
    /// @return riskStatus risk status
    function tradeQuoteSystem(
        ISportsAMMV2.TradeData[] calldata _tradeData,
        uint _buyInAmount,
        address _collateral,
        bool _isLive,
        uint8 _systemBetDenominator
    )
        external
        view
        returns (
            uint totalQuote,
            uint payout,
            uint fees,
            uint[] memory amountsToBuy,
            uint buyInAmountInDefaultCollateral,
            ISportsAMMV2RiskManager.RiskStatus riskStatus
        )
    {
        SportsAMMV2Utils.TradeQuoteCommonParams memory p = _buildTradeQuoteCommonParams(_collateral);
        (totalQuote, payout, fees, amountsToBuy, buyInAmountInDefaultCollateral, riskStatus) = sportsAMMV2Utils
            .tradeQuoteCommon(_tradeData, _buyInAmount, _collateral, _isLive, _systemBetDenominator, p);
    }

    function _buildTradeQuoteCommonParams(
        address _collateral
    ) internal view returns (SportsAMMV2Utils.TradeQuoteCommonParams memory) {
        return
            SportsAMMV2Utils.TradeQuoteCommonParams(
                riskManager,
                ISportsAMMV2(address(this)),
                addedPayoutPercentagePerCollateral[_collateral],
                safeBoxFee,
                SportsAMMV2Utils.CollateralParams(
                    address(defaultCollateral),
                    defaultCollateralDecimals,
                    liquidityPoolForCollateral[_collateral],
                    multiCollateralOnOffRamp
                )
            );
    }

    /* ========== EXTERNAL WRITE FUNCTIONS ========== */

    /// @notice make a trade and create a ticket
    /// @param _tradeData trade data with all market info needed for ticket
    /// @param _buyInAmount ticket buy-in amount
    /// @param _expectedQuote expected payout got from quote method
    /// @param _additionalSlippage slippage tolerance
    /// @param _referrer referrer to get referral fee
    /// @param _collateral different collateral used for payment
    /// @param _isEth pay with ETH
    /// @return _createdTicket the address of the created ticket
    function trade(
        ISportsAMMV2.TradeData[] calldata _tradeData,
        uint _buyInAmount,
        uint _expectedQuote,
        uint _additionalSlippage,
        address _referrer,
        address _collateral,
        bool _isEth
    ) external payable nonReentrant notPaused returns (address _createdTicket) {
        _createdTicket = _tradeInternal(
            _tradeData,
            TradeTypeData(NON_SYSTEM_BET, false, false),
            _buyInAmount,
            _expectedQuote,
            _additionalSlippage,
            _referrer,
            _collateral,
            _isEth,
            msg.sender
        );
    }

    /// @notice make a SGP trade and create a ticket
    /// @param _tradeData trade data with all market info needed for ticket
    /// @param _buyInAmount ticket buy-in amount
    /// @param _approvedQuote quote approved by sgpTradingProcessor
    /// @param _referrer referrer to get referral fee
    /// @param _collateral different collateral used for payment
    /// @return _createdTicket the address of the created ticket
    function tradeSGP(
        ISportsAMMV2.TradeData[] calldata _tradeData,
        uint _buyInAmount,
        uint _approvedQuote,
        address _recipient,
        address _referrer,
        address _collateral,
        bool _isLive
    ) external payable nonReentrant notPaused onlyValidRecipient(_recipient) returns (address _createdTicket) {
        if (msg.sender != sgpTradingProcessor) revert OnlyDedicatedProcessor();

        _createdTicket = _tradeInternal(
            _tradeData,
            TradeTypeData(NON_SYSTEM_BET, true, _isLive),
            _buyInAmount,
            _approvedQuote,
            0, //no additional slippage as quote is assigned by CL node
            _referrer,
            _collateral,
            false,
            _recipient
        );
    }

    /// @notice make a trade and create a ticket
    /// @param _tradeData trade data with all market info needed for ticket
    /// @param _buyInAmount ticket buy-in amount
    /// @param _expectedQuote expected payout got from quote method
    /// @param _additionalSlippage slippage tolerance
    /// @param _referrer referrer to get referral fee
    /// @param _collateral different collateral used for payment
    /// @param _isEth pay with ETH
    /// @param _systemBetDenominator minimum number of winning bets for a system bet
    /// @return _createdTicket the address of the created ticket
    function tradeSystemBet(
        ISportsAMMV2.TradeData[] calldata _tradeData,
        uint _buyInAmount,
        uint _expectedQuote,
        uint _additionalSlippage,
        address _referrer,
        address _collateral,
        bool _isEth,
        uint8 _systemBetDenominator
    ) external payable nonReentrant notPaused returns (address _createdTicket) {
        if (_systemBetDenominator <= 1 || _systemBetDenominator >= _tradeData.length) revert SBDOutOfRange();
        _createdTicket = _tradeInternal(
            _tradeData,
            TradeTypeData(_systemBetDenominator, false, false),
            _buyInAmount,
            _expectedQuote,
            _additionalSlippage,
            _referrer,
            _collateral,
            _isEth,
            msg.sender
        );
    }

    /// @notice make a live trade and create a ticket
    /// @param _tradeData trade data with all market info needed for ticket
    /// @param _buyInAmount ticket buy-in amount
    /// @param _expectedQuote expected payout got from LiveTradingProcessor method
    /// @param _recipient different recipient of the ticket
    /// @param _referrer referrer to get referral fee
    /// @param _collateral different collateral used for payment
    /// @return _createdTicket the address of the created ticket
    function tradeLive(
        ISportsAMMV2.TradeData[] calldata _tradeData,
        uint _buyInAmount,
        uint _expectedQuote,
        address _recipient,
        address _referrer,
        address _collateral
    ) external nonReentrant notPaused onlyValidRecipient(_recipient) returns (address _createdTicket) {
        if (msg.sender != liveTradingProcessor) revert OnlyDedicatedProcessor();

        _createdTicket = _tradeInternal(
            _tradeData,
            TradeTypeData(NON_SYSTEM_BET, false, true),
            _buyInAmount,
            _expectedQuote,
            0, //no additional slippage as quote is assigned by CL node
            _referrer,
            _collateral,
            false,
            _recipient
        );
    }

    function _tradeInternal(
        ISportsAMMV2.TradeData[] memory _tradeData,
        TradeTypeData memory _tradeTypeData,
        uint _buyInAmount,
        uint _expectedQuote,
        uint _additionalSlippage,
        address _referrer,
        address _collateral,
        bool _isEth,
        address _recipient
    ) internal returns (address _createdTicket) {
        if (_expectedQuote == 0 || _buyInAmount == 0) revert IllegalInputAmounts();

        _setReferrer(_referrer, _recipient);

        address useLPpool;
        uint collateralPriceInUSD;
        (useLPpool, collateralPriceInUSD, _buyInAmount, _collateral) = _handleCollateral(
            _buyInAmount,
            _collateral,
            _recipient,
            _isEth
        );
        _createdTicket = _trade(
            _tradeData,
            TradeDataInternal(
                _buyInAmount,
                (ONE * _buyInAmount) / _expectedQuote, // quote to expected payout
                _additionalSlippage,
                _recipient,
                _tradeTypeData._isLive,
                _collateral,
                useLPpool,
                collateralPriceInUSD,
                _tradeTypeData._isSGP
            ),
            _tradeTypeData._systemBetDenominator
        );
    }

    /**
     * @notice Resolves a ticket by exercising, canceling, or marking it as lost.
     * @dev
     * - Anyone can call this to exercise a ticket.
     * - Only addresses whitelisted as MARKET_RESOLVING can cancel or mark a ticket as lost.
     * - Uses internal _exerciseTicket logic with the appropriate flags.
     * @param _ticket The address of the ticket to be resolved.
     * @param action The type of resolution action to perform:
     *   - TicketAction.Exercise: Exercise a resolved ticket (no whitelist required)
     *   - TicketAction.Cancel: Cancel the ticket (whitelist required)
     *   - TicketAction.MarkLost: Mark the ticket as lost (whitelist required)
     */
    function handleTicketResolving(
        address _ticket,
        ISportsAMMV2.TicketAction action
    ) external nonReentrant notPaused onlyKnownTickets(_ticket) {
        if (action != ISportsAMMV2.TicketAction.Exercise) {
            if (!manager.isWhitelistedAddress(msg.sender, ISportsAMMV2Manager.Role.MARKET_RESOLVING)) {
                revert UnsupportedSender();
            }
        }

        _exerciseTicket(
            _ticket,
            address(0),
            action == ISportsAMMV2.TicketAction.Cancel,
            action == ISportsAMMV2.TicketAction.MarkLost
        );
    }

    /// @notice exercise specific ticket to an off ramp collateral
    /// @param _ticket ticket address
    /// @param _exerciseCollateral collateral address to off ramp to
    function exerciseTicketOffRamp(
        address _ticket,
        address _exerciseCollateral
    ) external nonReentrant notPaused onlyKnownTickets(_ticket) {
        if (msg.sender != Ticket(_ticket).ticketOwner()) revert OnlyTicketOwner();
        _exerciseTicket(_ticket, _exerciseCollateral, false, false);
    }

    /// @notice Withdraws collateral from a specified Ticket contract and sends it to the target address
    /// @param ticketAddress The address of the Ticket contract
    /// @param recipient The address to receive the withdrawn collateral
    function withdrawCollateralFromTicket(address ticketAddress, address recipient) external onlyOwner {
        // Call withdrawCollateral on the specified Ticket contract
        Ticket(ticketAddress).withdrawCollateral(recipient);
    }

    /// @notice expire provided tickets
    /// @param _tickets array of tickets to be expired
    function expireTickets(address[] calldata _tickets) external onlyOwner {
        unchecked {
            for (uint i; i < _tickets.length; ++i) {
                address ticketAddress = _tickets[i];
                address ticketOwner = Ticket(ticketAddress).ticketOwner();
                if (ticketOwner != freeBetsHolder) {
                    Ticket(ticketAddress).expire(msg.sender);
                    manager.expireKnownTicket(ticketAddress, ticketOwner);
                }
            }
        }
    }

    // ============================
    // CASHOUT (quote-based) additions
    // ============================

    /**
     * @notice Cashout using approved per-leg odds & settled flags.
     * @param _ticket Ticket address.
     * @param approvedOddsPerLeg Approved per-leg implied probs (1e18).
     * @param isLegSettled Settled flags per leg (voided legs => true).
     * @param _recipient Recipient (must be ticket owner).
     */
    function cashoutTicketWithLegOdds(
        address _ticket,
        uint[] calldata approvedOddsPerLeg,
        bool[] calldata isLegSettled,
        address _recipient
    ) external nonReentrant notPaused onlyKnownTickets(_ticket) onlyValidRecipient(_recipient) returns (uint cashoutAmount) {
        if (msg.sender != cashoutProcessor) revert OnlyDedicatedProcessor();
        Ticket ticket = Ticket(_ticket);

        (, uint payoutAfterCashoutFee) = ticket.getCashoutQuoteAndPayout(approvedOddsPerLeg, isLegSettled);
        if (payoutAfterCashoutFee == 0) revert IllegalInputAmounts();

        // Try storing snapshot (new tickets support this, old ones don't)
        try ticket.setCashoutPerLegData(approvedOddsPerLeg, isLegSettled) {} catch {}

        cashoutAmount = ticket.cashout(payoutAfterCashoutFee, _recipient);

        _resolveCashout(_ticket, _recipient, ticket, cashoutAmount);

        emit TicketCashedOut(_ticket, _recipient, cashoutAmount);
    }

    function _resolveCashout(address _ticket, address _recipient, Ticket ticket, uint cashoutAmount) internal {
        IERC20 collateral = ticket.collateral();

        bool isDeferred = _isDeferredTicket(_ticket);
        // For deferred tickets: AMM has no funds — pull everything needed from LP
        if (isDeferred) {
            uint neededFromLP = cashoutAmount + sportsAMMV2Utils.getFees(ticket.buyInAmount(), safeBoxFee);
            ISportsAMMV2LiquidityPool(liquidityPoolForCollateral[address(collateral)]).provideForResolution(
                _ticket,
                neededFromLP
            );
            // Pay user
            if (cashoutAmount > 0) {
                collateral.safeTransfer(_recipient, cashoutAmount);
            }
        }

        // protocol fees (safeBox/referrer), NOT cashout fee
        _handleFees(ticket.buyInAmount(), _recipient, collateral);

        _finalizeTicketResolution(_ticket, _recipient, collateral, true);
    }

    function _finalizeTicketResolution(
        address _ticket,
        address _ticketOwner,
        IERC20 _collateral,
        bool _isUserTheWinner
    ) internal {
        manager.resolveKnownTicket(_ticket, _ticketOwner);
        emit TicketResolved(_ticket, _ticketOwner, _isUserTheWinner);

        // Return unused funds to LP
        ISportsAMMV2LiquidityPool(liquidityPoolForCollateral[address(_collateral)]).transferToPool(
            _ticket,
            _collateral.balanceOf(address(this))
        );
    }

    function _isDeferredTicket(address _ticket) internal view returns (bool) {
        try Ticket(_ticket).isDeferred() returns (bool stored) {
            return stored;
        } catch {
            return false;
        }
    }

    /* ========== INTERNAL FUNCTIONS ========== */

    function _handleCollateral(
        uint _buyInAmount,
        address _collateral,
        address _fromAddress,
        bool _isEth
    ) internal returns (address lqPool, uint collateralPrice, uint buyInAmount, address collateralAfterOnramp) {
        buyInAmount = _buyInAmount;

        // Default collateral path (including address(0) case)
        if (_collateral == address(0) || _collateral == address(defaultCollateral)) {
            collateralAfterOnramp = address(defaultCollateral);
            defaultCollateral.safeTransferFrom(_fromAddress, address(this), _buyInAmount);
        }
        // Non-default collateral path
        else {
            collateralAfterOnramp = _collateral;

            // Handle ETH or ERC20 transfer
            if (_isEth) {
                if (_collateral != multiCollateralOnOffRamp.WETH9() || msg.value < _buyInAmount) revert InsuffETHSent();
                IWeth(_collateral).deposit{value: msg.value}();
            } else {
                IERC20(_collateral).safeTransferFrom(_fromAddress, address(this), _buyInAmount);
            }

            // Check if direct liquidity pool exists for collateral
            lqPool = liquidityPoolForCollateral[_collateral];
            if (lqPool != address(0)) {
                collateralPrice = ISportsAMMV2LiquidityPool(lqPool).getCollateralPrice();
                if (collateralPrice == 0) revert ZeroPriceForCollateral();
            }
            // Handle onramping if no direct pool
            else {
                if (address(multiCollateralOnOffRamp) == address(0)) revert MultiCollatDisabled();

                IERC20(_collateral).approve(address(multiCollateralOnOffRamp), _buyInAmount);
                buyInAmount = multiCollateralOnOffRamp.onramp(_collateral, _buyInAmount);
                if (buyInAmount < multiCollateralOnOffRamp.getMinimumReceived(_collateral, _buyInAmount))
                    revert InsuffReceived();

                collateralAfterOnramp = address(defaultCollateral);
            }
        }

        // Get final liquidity pool
        lqPool = liquidityPoolForCollateral[collateralAfterOnramp];
    }

    function _trade(
        ISportsAMMV2.TradeData[] memory _tradeData,
        TradeDataInternal memory _tradeDataInternal,
        uint8 _systemBetDenominator
    ) internal returns (address) {
        TradeProcessingParams memory processingParams;
        processingParams._addedPayoutPercentage = addedPayoutPercentagePerCollateral[_tradeDataInternal._collateral];

        {
            SportsAMMV2Utils.TradeProcessingResult memory result = sportsAMMV2Utils.calculateTradeQuote(
                _tradeData,
                SportsAMMV2Utils.CalculateTradeParams(
                    _tradeDataInternal._buyInAmount,
                    _tradeDataInternal._expectedPayout,
                    _tradeDataInternal._isLive,
                    _tradeDataInternal._isSGP,
                    processingParams._addedPayoutPercentage,
                    safeBoxFee
                ),
                _systemBetDenominator,
                SportsAMMV2Utils.TradeQuoteParams(
                    riskManager,
                    ISportsAMMV2(address(this)),
                    processingParams._addedPayoutPercentage,
                    safeBoxFee
                )
            );
            processingParams._totalQuote = result._totalQuote;
            processingParams._payout = result._payout;
            processingParams._fees = result._fees;
            processingParams._payoutWithFees = result._payoutWithFees;
            _tradeDataInternal._expectedPayout = result._expectedPayout;
        }

        checkRisksLimits(
            _tradeData,
            processingParams._totalQuote,
            processingParams._payout,
            _tradeDataInternal,
            _systemBetDenominator
        );

        // Clone a ticket
        Ticket.MarketData[] memory markets = _getTicketMarkets(_tradeData, processingParams._addedPayoutPercentage);
        Ticket ticket = Ticket(Clones.clone(ticketMastercopy));

        // 1) Initialize the ticket (unchanged)
        ticket.initialize(
            Ticket.TicketInit(
                markets,
                _tradeDataInternal._buyInAmount,
                processingParams._fees,
                processingParams._totalQuote,
                address(this),
                _tradeDataInternal._recipient,
                IERC20(_tradeDataInternal._collateral),
                (block.timestamp + riskManager.expiryDuration()),
                _tradeDataInternal._isLive,
                _systemBetDenominator,
                _tradeDataInternal._isSGP
            )
        );

        // 2) Track ticket on the manager (unchanged)
        manager.addNewKnownTicket(_tradeData, address(ticket), _tradeDataInternal._recipient);

        // 3) Commit trade to LP
        ISportsAMMV2LiquidityPool collateralPool = ISportsAMMV2LiquidityPool(_tradeDataInternal._collateralPool);

        if (collateralPool.getTicketRound(address(ticket)) == 1) {
            // Default round: deferred collateralization.
            // Only send buyIn to LP for safekeeping. LP does NOT provide profit upfront.
            collateralPool.commitTradeDeferred(address(ticket), _tradeDataInternal._buyInAmount);
            // Setting deferred flag
            ticket.setIsDeferred();
        } else {
            // Non-default round: full collateralization as before.
            collateralPool.commitTrade(address(ticket), processingParams._payoutWithFees - _tradeDataInternal._buyInAmount);
            IERC20(_tradeDataInternal._collateral).safeTransfer(address(ticket), processingParams._payoutWithFees);
        }

        // Store expected payout for validation
        ticket.setExpectedFinalPayout(processingParams._payoutWithFees);

        emit NewTicket(
            markets,
            address(ticket),
            _tradeDataInternal._buyInAmount,
            processingParams._payout,
            _tradeDataInternal._isLive
        );
        emit TicketCreated(
            address(ticket),
            _tradeDataInternal._recipient,
            _tradeDataInternal._buyInAmount,
            processingParams._fees,
            processingParams._payout,
            processingParams._totalQuote,
            _tradeDataInternal._collateral
        );

        return address(ticket);
    }

    // Checks risk and updates Staking Volume
    function checkRisksLimits(
        ISportsAMMV2.TradeData[] memory _tradeData,
        uint _totalQuote,
        uint _payout,
        TradeDataInternal memory _tradeDataInternal,
        uint8 _systemBetDenominator
    ) internal {
        (uint buyInAmountUSD, uint payoutUSD) = sportsAMMV2Utils.checkLimitsWithTransform(
            riskManager,
            _tradeDataInternal._buyInAmount,
            _totalQuote,
            _payout,
            _tradeDataInternal._expectedPayout,
            _tradeDataInternal._additionalSlippage,
            _tradeData.length,
            _tradeDataInternal._collateralPriceInUSD,
            _tradeDataInternal._collateral,
            defaultCollateralDecimals
        );
        riskManager.checkAndUpdateRisks(
            _tradeData,
            buyInAmountUSD,
            payoutUSD,
            _tradeDataInternal._isLive,
            _systemBetDenominator,
            _tradeDataInternal._isSGP
        );
    }

    function _getTicketMarkets(
        ISportsAMMV2.TradeData[] memory _tradeData,
        uint _addedPayoutPercentage
    ) internal pure returns (Ticket.MarketData[] memory markets) {
        uint len = _tradeData.length;
        markets = new Ticket.MarketData[](len);

        for (uint i; i < len; ++i) {
            ISportsAMMV2.TradeData memory marketTradeData = _tradeData[i];
            uint odds = marketTradeData.odds[marketTradeData.position];

            markets[i] = Ticket.MarketData(
                marketTradeData.gameId,
                marketTradeData.sportId,
                marketTradeData.typeId,
                marketTradeData.maturity,
                marketTradeData.status,
                marketTradeData.line,
                marketTradeData.playerId,
                marketTradeData.position,
                (odds * ONE) / ((ONE + _addedPayoutPercentage) - ((_addedPayoutPercentage * odds) / ONE)),
                marketTradeData.combinedPositions[marketTradeData.position]
            );
        }
    }

    function _handleFees(uint _buyInAmount, address _ticketOwner, IERC20 _collateral) internal returns (uint fees) {
        SportsAMMV2Utils.FeeResult memory feeResult = sportsAMMV2Utils.calculateFees(
            _buyInAmount,
            _ticketOwner,
            _collateral.balanceOf(address(this)),
            safeBoxFee,
            freeBetsHolder,
            safeBox,
            safeBoxPerCollateral[address(_collateral)],
            referrals
        );
        fees = feeResult.fees;

        if (feeResult.referrerShare > 0) {
            _collateral.safeTransfer(feeResult.referrer, feeResult.referrerShare);
            emit ReferrerPaid(feeResult.referrer, _ticketOwner, feeResult.referrerShare, _buyInAmount, address(_collateral));
        }
        if (feeResult.safeBoxAmount > 0) {
            _collateral.safeTransfer(feeResult.safeBoxTarget, feeResult.safeBoxAmount);
            emit SafeBoxFeePaid(safeBoxFee, feeResult.safeBoxAmount, address(_collateral));
        }
    }

    function _setReferrer(address _referrer, address _recipient) internal {
        if (_referrer != address(0) && _recipient != address(freeBetsHolder)) referrals.setReferrer(_referrer, _recipient);
    }

    function _exerciseTicket(address _ticket, address _exerciseCollateral, bool _cancelTicket, bool _markLost) internal {
        Ticket ticket = Ticket(_ticket);
        uint userWonAmount;
        if (_markLost) {
            userWonAmount = ticket.markAsLost();
        } else if (_cancelTicket) {
            userWonAmount = ticket.cancel();
        } else {
            userWonAmount = ticket.exercise(_exerciseCollateral);
        }
        IERC20 ticketCollateral = ticket.collateral();
        address ticketOwner = ticket.ticketOwner();

        bool isDeferred = _isDeferredTicket(_ticket);
        // For deferred tickets: AMM has no funds — pull everything needed from LP
        if (isDeferred) {
            uint neededFromLP = userWonAmount +
                (ticket.cancelled() ? 0 : sportsAMMV2Utils.getFees(ticket.buyInAmount(), safeBoxFee));
            ISportsAMMV2LiquidityPool(liquidityPoolForCollateral[address(ticketCollateral)]).provideForResolution(
                _ticket,
                neededFromLP
            );
        }

        if (userWonAmount > 0) {
            if (_exerciseCollateral != address(0) && _exerciseCollateral != address(ticketCollateral)) {
                if (ticketCollateral != defaultCollateral) revert OfframpOnlyDefaultCollateralAllowed();
                IERC20(_exerciseCollateral).safeTransfer(
                    ticketOwner,
                    multiCollateralOnOffRamp.offramp(_exerciseCollateral, userWonAmount)
                );
            } else if (isDeferred) {
                // Deferred: AMM pays user directly (ticket has no funds)
                ticketCollateral.safeTransfer(ticketOwner, userWonAmount);
            }
        }

        if (ticketOwner == freeBetsHolder) {
            IProxyBetting(ticketOwner).confirmTicketResolved(_ticket);
        }

        if (!ticket.cancelled()) {
            _handleFees(ticket.buyInAmount(), ticketOwner, ticketCollateral);
        }

        _finalizeTicketResolution(_ticket, ticketOwner, ticketCollateral, ticket.isUserTheWinner());
    }

    /* ========== SETTERS ========== */

    /// @notice set roots of merkle tree
    /// @param _games game IDs
    /// @param _roots new roots
    function setRootsPerGames(bytes32[] memory _games, bytes32[] memory _roots) external onlyWhitelistedAddresses {
        if (_games.length != _roots.length) revert InvalidLength();
        unchecked {
            for (uint i; i < _games.length; ++i) {
                _setRootForGame(_games[i], _roots[i]);
            }
        }
    }

    /// @notice set root of merkle tree
    /// @param _game game ID
    /// @param _root new root
    function setRootForGame(bytes32 _game, bytes32 _root) external onlyWhitelistedAddresses {
        _setRootForGame(_game, _root);
    }

    function _setRootForGame(bytes32 _game, bytes32 _root) internal {
        if (rootPerGame[_game] == ROOT_PER_GAME_RETIRED) revert RootPerGameRetired();
        rootPerGame[_game] = _root;
        emit GameRootUpdated(_game, _root);
    }

    /// @notice set roots of merkle trees per game and type from a packed blob
    /// @dev per game: game (32 bytes) | count (1 byte, 1..255) | count x [typeId (2 bytes) | first 16 bytes of root];
    /// the blob must be consumed exactly. The first push for a game retires its root per game for good,
    /// so it has to contain every type of the game
    /// @param _data packed roots
    function setPackedRootsPerGamesAndTypes(bytes calldata _data) external onlyWhitelistedAddresses {
        uint len = _data.length;
        uint offset;
        do {
            // length checks precede every calldata read
            if (len - offset < PACKED_ROOT_GAME_HEADER) revert InvalidLength();
            bytes32 game = _loadCalldata(_data, offset);
            uint count = uint8(bytes1(_loadCalldata(_data, offset + 32)));
            offset += PACKED_ROOT_GAME_HEADER;
            if (count == 0 || len - offset < count * PACKED_ROOT_ENTRY) revert InvalidLength();
            if (rootPerGame[game] != ROOT_PER_GAME_RETIRED) _setRootForGame(game, ROOT_PER_GAME_RETIRED);
            for (uint i; i < count; ++i) {
                bytes32 entry = _loadCalldata(_data, offset);
                _setRootForGameAndType(game, uint16(bytes2(entry)), entry << 16);
                offset += PACKED_ROOT_ENTRY;
            }
        } while (offset < len);
        emit PackedRootsUpdated(_data);
    }

    /// @dev 32-byte word of _data at _offset; the caller bounds-checks the bytes it uses
    function _loadCalldata(bytes calldata _data, uint _offset) private pure returns (bytes32 word) {
        assembly {
            word := calldataload(add(_data.offset, _offset))
        }
    }

    /// @dev stores the first 16 bytes of _root in this type's half of the slot, the other half untouched
    function _setRootForGameAndType(bytes32 _game, uint16 _typeId, bytes32 _root) internal {
        uint16 slotIndex = _typeId >> 1;
        bytes32 slot = packedRootsPerGameAndType[_game][slotIndex];
        slot = (_typeId & 1 == 0)
            ? (slot & LOW_HALF_MASK) | (_root & HIGH_HALF_MASK)
            : (slot & HIGH_HALF_MASK) | (_root >> 128);
        packedRootsPerGameAndType[_game][slotIndex] = slot;
    }

    /// @notice sets main addresses
    /// @param _defaultCollateral the default token used for payment
    /// @param _manager manager address
    /// @param _riskManager risk manager address
    /// @param _resultManager result manager address
    /// @param _referrals referrals address
    /// @param _safeBox safeBox address
    function setAddresses(
        IERC20 _defaultCollateral,
        address _manager,
        address _riskManager,
        address _resultManager,
        address _referrals,
        address _safeBox
    ) external onlyOwner {
        defaultCollateral = _defaultCollateral;
        defaultCollateralDecimals = ISportsAMMV2Manager(address(defaultCollateral)).decimals();
        manager = ISportsAMMV2Manager(_manager);
        riskManager = ISportsAMMV2RiskManager(_riskManager);
        resultManager = ISportsAMMV2ResultManager(_resultManager);
        referrals = IReferrals(_referrals);
        safeBox = _safeBox;
        emit AddressesUpdated(_defaultCollateral, _manager, _riskManager, _resultManager, _referrals, _safeBox);
    }

    /**
     * @notice Sets the addresses of various betting processors.
     * @dev This function can only be called by the contract owner.
     * @param _liveTradingProcessor Address of the live trading processor contract.
     * @param _sgpTradingProcessor Address of the single-game parlay trading processor contract.
     * @param _freeBetsHolder Address of the free bets holder contract.
     * @param _cashoutProcessor Address of cashout processor contract.
     */
    function setBettingProcessors(
        address _liveTradingProcessor,
        address _sgpTradingProcessor,
        address _freeBetsHolder,
        address _cashoutProcessor
    ) external onlyOwner {
        liveTradingProcessor = _liveTradingProcessor;
        sgpTradingProcessor = _sgpTradingProcessor;
        freeBetsHolder = _freeBetsHolder;
        cashoutProcessor = _cashoutProcessor;
        emit SetBettingProcessors(liveTradingProcessor, sgpTradingProcessor, freeBetsHolder, cashoutProcessor);
    }

    /// @notice sets new Ticket Mastercopy address
    /// @param _ticketMastercopy new Ticket Mastercopy address
    function setTicketMastercopy(address _ticketMastercopy) external onlyOwner {
        ticketMastercopy = _ticketMastercopy;
        emit TicketMastercopyUpdated(_ticketMastercopy);
    }

    /// @notice sets multi-collateral on/off ramp contract and enable/disable
    /// @param _onOffRamper new multi-collateral on/off ramp address
    function setMultiCollateralOnOffRamp(address _onOffRamper) external onlyOwner {
        _updateApproval(defaultCollateral, address(multiCollateralOnOffRamp), _onOffRamper);
        multiCollateralOnOffRamp = IMultiCollateralOnOffRamp(_onOffRamper);
        emit SetMultiCollateralOnOffRamp(_onOffRamper);
    }

    /// @notice sets different amounts
    /// @param _safeBoxFee safe box fee paid on each trade
    function setAmounts(uint _safeBoxFee) external onlyOwner {
        safeBoxFee = _safeBoxFee;
        emit AmountsUpdated(_safeBoxFee);
    }

    /// @notice Sets parameters related to a collateral asset.
    /// @dev Only updates fields if the new value differs from the stored one.
    /// @param _collateral The collateral token address.
    /// @param _liquidityPool New liquidity pool address (optional, skip if same).
    /// @param _addedPayout New added payout percentage (optional, skip if same).
    /// @param _safeBox New dedicated SafeBox address (optional, skip if same).
    function configureCollateral(
        address _collateral,
        address _liquidityPool,
        uint _addedPayout,
        address _safeBox
    ) external onlyOwner {
        // Liquidity pool update
        if (liquidityPoolForCollateral[_collateral] != _liquidityPool) {
            _updateApproval(IERC20(_collateral), liquidityPoolForCollateral[_collateral], _liquidityPool);
            liquidityPoolForCollateral[_collateral] = _liquidityPool;
        }

        // Added payout percentage update
        addedPayoutPercentagePerCollateral[_collateral] = _addedPayout;

        // SafeBox override update
        safeBoxPerCollateral[_collateral] = _safeBox;

        emit CollateralConfigured(_collateral, _liquidityPool, _addedPayout, _safeBox);
    }

    /// @notice sets the SportsAMMV2Utils contract address
    /// @param _sportsAMMV2Utils new SportsAMMV2Utils address
    function setSportsAMMV2Utils(address _sportsAMMV2Utils) external onlyOwner {
        sportsAMMV2Utils = SportsAMMV2Utils(_sportsAMMV2Utils);
        emit SetSportsAMMV2Utils(_sportsAMMV2Utils);
    }

    function _updateApproval(IERC20 token, address oldSpender, address newSpender) internal {
        if (oldSpender != address(0)) {
            token.approve(oldSpender, 0);
        }

        if (newSpender != address(0)) {
            token.approve(newSpender, MAX_APPROVAL);
        }
    }

    /* ========== MODIFIERS ========== */

    // modifier bodies are inlined at every use site, so checks are delegated to internal functions to reduce contract size

    modifier onlyKnownTickets(address _ticket) {
        _checkKnownTicket(_ticket);
        _;
    }

    modifier onlyWhitelistedAddresses() {
        _checkWhitelistedAddress();
        _;
    }

    modifier onlyValidRecipient(address _recipient) {
        _checkValidRecipient(_recipient);
        _;
    }

    function _checkKnownTicket(address _ticket) internal view {
        if (!manager.isKnownTicket(_ticket)) revert UnknownTicket();
    }

    function _checkWhitelistedAddress() internal view {
        if (!manager.isWhitelistedAddress(msg.sender, ISportsAMMV2Manager.Role.ROOT_SETTING) && msg.sender != owner)
            revert InvalidSender();
    }

    function _checkValidRecipient(address _recipient) internal pure {
        if (_recipient == address(0)) revert UndefinedRecipient();
    }

    /* ========== EVENTS ========== */

    event NewTicket(Ticket.MarketData[] markets, address ticket, uint buyInAmount, uint payout, bool isLive);
    event TicketCreated(
        address ticket,
        address recipient,
        uint buyInAmount,
        uint fees,
        uint payout,
        uint totalQuote,
        address collateral
    );

    event TicketResolved(address ticket, address ticketOwner, bool isUserTheWinner);
    event ReferrerPaid(address refferer, address trader, uint amount, uint volume, address collateral);
    event SafeBoxFeePaid(uint safeBoxFee, uint safeBoxAmount, address collateral);

    event GameRootUpdated(bytes32 game, bytes32 root);
    event PackedRootsUpdated(bytes data);
    event AmountsUpdated(uint safeBoxFee);
    event AddressesUpdated(
        IERC20 defaultCollateral,
        address manager,
        address riskManager,
        address resultManager,
        address referrals,
        address safeBox
    );
    event TicketMastercopyUpdated(address ticketMastercopy);
    event SetMultiCollateralOnOffRamp(address onOffRamper);
    event SetBettingProcessors(
        address liveTradingProcessor,
        address sgpTradingProcessor,
        address freeBetsHolder,
        address cashoutProcessor
    );
    event CollateralConfigured(address collateral, address liquidityPool, uint addedPayout, address safeBox);
    event TicketCashedOut(address indexed ticket, address indexed recipient, uint cashoutAmount);
    event SetSportsAMMV2Utils(address sportsAMMV2Utils);
}

contracts/core/AMM/SportsAMMV2Manager.so.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";

// internal
import "../../utils/libraries/AddressSetLib.sol";
import "../../utils/proxy/ProxyOwned.sol";
import "../../utils/proxy/ProxyPausable.sol";
import "../../interfaces/ISportsAMMV2Manager.sol";
import "../../interfaces/ISportsAMMV2RiskManager.sol";
import "../../interfaces/ITicket.sol";

contract SportsAMMV2Manager is Initializable, ProxyOwned, ProxyPausable {
    using AddressSetLib for AddressSetLib.AddressSet;

    uint private constant COLLATERAL_DEFAULT_DECIMALS = 18;

    address public sportsAMM;

    mapping(address => mapping(ISportsAMMV2Manager.Role => bool)) public whitelistedAddresses;

    // stores active tickets
    AddressSetLib.AddressSet internal knownTickets;

    // stores active tickets per user
    mapping(address => AddressSetLib.AddressSet) internal activeTicketsPerUser;

    // stores resolved tickets per user
    mapping(address => AddressSetLib.AddressSet) internal resolvedTicketsPerUser;

    // stores tickets per game
    mapping(bytes32 => AddressSetLib.AddressSet) internal ticketsPerGame;

    mapping(bytes32 => mapping(uint => mapping(uint => AddressSetLib.AddressSet))) internal ticketsPerMarket;

    // stores whether a given ticket address is a system bet
    mapping(address => bool) public isSystemTicket;

    // stores whether a given ticket address is a SGP bet
    mapping(address => bool) public isSGPTicket;

    // only tickets created after this storage var is created could potentially be cashoutable
    mapping(address => bool) public isTicketPotentiallyCashoutable;

    /* ========== CONSTRUCTOR ========== */

    function initialize(address _owner) external initializer {
        setOwner(_owner);
    }

    /* ========== EXTERNAL FUNCTIONS ========== */

    /// @notice add new ticket to known and active per user, add tickets per game and add tickets per market
    /// @param _tradeData list of games
    /// @param _ticket ticket address
    /// @param _user to update the ticket for
    function addNewKnownTicket(
        ISportsAMMV2.TradeData[] memory _tradeData,
        address _ticket,
        address _user
    ) external onlySportAMMV2 {
        knownTickets.add(_ticket);
        activeTicketsPerUser[_user].add(_ticket);

        for (uint i = 0; i < _tradeData.length; i++) {
            ticketsPerGame[_tradeData[i].gameId].add(_ticket);
            ticketsPerMarket[_tradeData[i].gameId][_tradeData[i].typeId][_tradeData[i].playerId].add(_ticket);
        }

        isSystemTicket[_ticket] = ITicket(_ticket).isSystem();
        isSGPTicket[_ticket] = ITicket(_ticket).isSGP();
        isTicketPotentiallyCashoutable[_ticket] = true;
    }

    /// @notice remove known ticket from active and add as resolved
    /// @param _ticket ticket address
    /// @param _user to update the ticket for
    function resolveKnownTicket(address _ticket, address _user) external onlySportAMMV2 {
        knownTickets.remove(_ticket);
        activeTicketsPerUser[_user].remove(_ticket);

        resolvedTicketsPerUser[_user].add(_ticket);
    }

    /// @notice remove known ticket from active
    /// @param _ticket ticket address
    /// @param _user to update the ticket for
    function expireKnownTicket(address _ticket, address _user) external onlySportAMMV2 {
        knownTickets.remove(_ticket);
        activeTicketsPerUser[_user].remove(_ticket);
    }

    /// @notice remove resolved tickets from user's resolved list (batch)
    /// @param _tickets array of ticket addresses
    /// @param _user user to remove tickets for
    function removeResolvedTickets(address[] calldata _tickets, address _user) external {
        require(
            msg.sender == owner || whitelistedAddresses[msg.sender][ISportsAMMV2Manager.Role.MARKET_RESOLVING],
            "Invalid resolver"
        );
        for (uint i = 0; i < _tickets.length; i++) {
            resolvedTicketsPerUser[_user].remove(_tickets[i]);
        }
    }

    /* ========== EXTERNAL READ FUNCTIONS ========== */

    /// @notice check whether a ticket is known
    /// @param _ticket ticket address
    function isKnownTicket(address _ticket) external view returns (bool) {
        return knownTickets.contains(_ticket);
    }

    /// @notice is provided ticket active
    /// @param _ticket ticket address
    /// @return isActiveTicket true/false
    function isActiveTicket(address _ticket) external view returns (bool) {
        return knownTickets.contains(_ticket);
    }

    /// @notice gets batch of active tickets
    /// @param _index start index
    /// @param _pageSize batch size
    /// @return activeTickets
    function getActiveTickets(uint _index, uint _pageSize) external view returns (address[] memory) {
        return knownTickets.getPage(_index, _pageSize);
    }

    /// @notice gets number of active tickets
    /// @return numOfActiveTickets
    function numOfActiveTickets() external view returns (uint) {
        return knownTickets.elements.length;
    }

    /// @notice gets batch of tickets per market
    /// @param _index start index
    /// @param _pageSize batch size
    /// @param _gameId to get tickets for
    /// @param _typeId to get tickets for
    /// @param _playerId to get tickets for
    /// @return tickets
    function getTicketsPerMarket(
        uint _index,
        uint _pageSize,
        bytes32 _gameId,
        uint _typeId,
        uint _playerId
    ) external view returns (address[] memory) {
        return ticketsPerMarket[_gameId][_typeId][_playerId].getPage(_index, _pageSize);
    }

    /// @notice gets number of tickets per market
    /// @param _gameId to get number of tickets for
    /// @param _typeId to get number of tickets for
    /// @param _playerId to get number of tickets for
    /// @return numOfTickets
    function numOfTicketsPerMarket(bytes32 _gameId, uint _typeId, uint _playerId) external view returns (uint) {
        return ticketsPerMarket[_gameId][_typeId][_playerId].elements.length;
    }

    /// @notice gets batch of active tickets per user
    /// @param _index start index
    /// @param _pageSize batch size
    /// @param _user to get active tickets for
    /// @return activeTickets
    function getActiveTicketsPerUser(uint _index, uint _pageSize, address _user) external view returns (address[] memory) {
        return activeTicketsPerUser[_user].getPage(_index, _pageSize);
    }

    /// @notice gets number of active tickets per user
    /// @param _user to get number of active tickets for
    /// @return numOfActiveTickets
    function numOfActiveTicketsPerUser(address _user) external view returns (uint) {
        return activeTicketsPerUser[_user].elements.length;
    }

    /// @notice gets batch of resolved tickets per user
    /// @param _index start index
    /// @param _pageSize batch size
    /// @param _user to get resolved tickets for
    /// @return resolvedTickets
    function getResolvedTicketsPerUser(uint _index, uint _pageSize, address _user) external view returns (address[] memory) {
        return resolvedTicketsPerUser[_user].getPage(_index, _pageSize);
    }

    /// @notice gets number of resolved tickets per user
    /// @param _user to get number of resolved tickets for
    /// @return numOfResolvedTickets
    function numOfResolvedTicketsPerUser(address _user) external view returns (uint) {
        return resolvedTicketsPerUser[_user].elements.length;
    }

    /// @notice gets batch of tickets per game
    /// @param _index start index
    /// @param _pageSize batch size
    /// @param _gameId to get tickets for
    /// @return resolvedTickets
    function getTicketsPerGame(uint _index, uint _pageSize, bytes32 _gameId) external view returns (address[] memory) {
        return ticketsPerGame[_gameId].getPage(_index, _pageSize);
    }

    /// @notice gets number of tickets per game
    /// @param _gameId to get number of tickets for
    /// @return numOfTickets
    function numOfTicketsPerGame(bytes32 _gameId) external view returns (uint) {
        return ticketsPerGame[_gameId].elements.length;
    }

    /// @notice checks if address is whitelisted
    /// @param _address address to be checked
    /// @return bool
    function isWhitelistedAddress(address _address, ISportsAMMV2Manager.Role _role) external view returns (bool) {
        return whitelistedAddresses[_address][_role];
    }

    /* ========== EXTERNAL READ FUNCTIONS ========== */

    /// @notice pause/unapause provided tickets
    /// @param _tickets array of tickets to be paused/unpaused
    /// @param _paused pause/unpause
    function setPausedTickets(address[] calldata _tickets, bool _paused) external {
        require(
            msg.sender == owner || whitelistedAddresses[msg.sender][ISportsAMMV2Manager.Role.TICKET_PAUSER],
            "Invalid pauser"
        );
        for (uint i = 0; i < _tickets.length; i++) {
            ITicket(_tickets[i]).setPaused(_paused);
        }
    }

    /* ========== SETTERS ========== */

    /// @notice enables whitelist addresses of given array
    /// @param _whitelistedAddresses array of whitelisted addresses
    /// @param _role for which whitelisting is assign/unassigned
    /// @param _flag adding or removing from whitelist (true: add, false: remove)
    function setWhitelistedAddresses(
        address[] calldata _whitelistedAddresses,
        ISportsAMMV2Manager.Role _role,
        bool _flag
    ) external onlyOwner {
        require(_whitelistedAddresses.length > 0, "Whitelisted addresses cannot be empty");
        for (uint256 index = 0; index < _whitelistedAddresses.length; index++) {
            if (whitelistedAddresses[_whitelistedAddresses[index]][_role] != _flag) {
                whitelistedAddresses[_whitelistedAddresses[index]][_role] = _flag;
                emit WhitelistStatusChanged(_whitelistedAddresses[index], _role, _flag);
            }
        }
    }

    /// @notice set the address of SportsAMM
    function setSportsAMM(address _sportsAMM) external onlyOwner {
        sportsAMM = _sportsAMM;
        emit SportAMMChanged(address(_sportsAMM));
    }

    /* ========== MODIFIERS ========== */

    modifier onlySportAMMV2() {
        require(msg.sender == sportsAMM, "Invalid sportsAMM");
        _;
    }
    /* ========== EVENTS ========== */

    event SportAMMChanged(address sportsAMM);
    event WhitelistStatusChanged(address whitelistedAddresses, ISportsAMMV2Manager.Role role, bool flag);
}

contracts/core/AMM/SportsAMMV2RiskManage.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts/utils/cryptography/MerkleProof.sol";

// internal
import "../../utils/proxy/ProxyReentrancyGuard.sol";
import "../../utils/proxy/ProxyOwned.sol";
import "../../utils/proxy/ProxyPausable.sol";

import "../../interfaces/ISportsAMMV2Manager.sol";
import "../../interfaces/ISportsAMMV2RiskManager.sol";
import "../../interfaces/ISportsAMMV2.sol";
import "../../interfaces/ISportsAMMV2ResultManager.sol";

/// @title Sports AMM V2 Risk Manager contract
/// @author vladan
contract SportsAMMV2RiskManager is Initializable, ProxyOwned, ProxyPausable, ProxyReentrancyGuard {
    /* ========== CONST VARIABLES ========== */

    uint public constant DEFAULT_DYNAMIC_LIQUIDITY_CUTOFF_DIVIDER = 2e18;
    uint private constant ONE = 1e18;
    uint public constant DEFAULT_CASHOUT_SAFEBOX_FEE_MULTIPLIER = 4;
    uint public constant DEFAULT_CASHOUT_COOLDOWN = 5 minutes;

    /* ========== ERRORS ========== */
    error InvalidCap();
    error InvalidOdds();
    error InvalidPosition();
    error MarketNotTrading();
    error ExceededMarketPositionRisk();
    error ExceededGameRisk();
    error InvalidCombination();
    error ExceededSGPRisk();
    error InvalidInput();
    error InvalidAddress();
    error MismatchedInputs();
    error EmptyArrays();
    error ExceededMaxCombinations();
    error BadRangeForK();
    error DividerOutOfRange();
    error LowBuyIn();
    error ExceededMaxOdds();
    error ExceededMaxAmount();
    error SlippageTooHigh();
    error ExceededMaxSize();
    error CantParlayFutures();
    error MultiplierTooHigh();

    /* ========== STATE VARIABLES ========== */

    // sports manager contract address
    ISportsAMMV2Manager public manager;

    // result manager address
    ISportsAMMV2ResultManager public resultManager;

    // sports AMM address
    ISportsAMMV2 public sportsAMM;

    // default cap for all sports
    uint public defaultCap;

    // cap per specific sport
    mapping(uint => uint) public capPerSport;

    // cap per all child markets of specific sport
    mapping(uint => uint) public capPerSportChild;

    // cap per type for specific sport
    mapping(uint => mapping(uint => uint)) public capPerSportAndType;

    // cap per specific market
    mapping(bytes32 => mapping(uint => mapping(uint => mapping(int => uint)))) public capPerMarket;

    // default risk multiplier used to calculate total risk on the game
    uint public defaultRiskMultiplier;

    // risk multiplier per sport used to calculate total risk on the game
    mapping(uint => uint) public riskMultiplierPerSport;

    // risk multiplier per game used to calculate total risk on the game
    mapping(bytes32 => uint) public riskMultiplierPerGame;

    // max available cap
    uint public maxCap;

    // max available risk multiplier
    uint public maxRiskMultiplier;

    // time before maturity when to start increasing the liquidity linearly
    mapping(uint => uint) public dynamicLiquidityCutoffTimePerSport;

    // divider on how much liquidity is available before cut off time
    mapping(uint => uint) public dynamicLiquidityCutoffDividerPerSport;

    mapping(uint => mapping(uint => bool)) public liveTradingPerSportAndTypeEnabled;

    mapping(uint => bool) public combiningPerSportEnabled;

    // stores current risk per market type and position, defined with gameId -> typeId -> playerId
    mapping(bytes32 => mapping(uint => mapping(uint => mapping(uint => int)))) public riskPerMarketTypeAndPosition;

    // spent on game (parent market together with all child markets)
    mapping(bytes32 => uint) public spentOnGame;

    // minimum ticket buy-in amount
    uint public minBuyInAmount;

    // maximum ticket size
    uint public maxTicketSize;

    // maximum supported payout amount
    uint public maxSupportedAmount;

    // maximum supported ticket odds
    uint public maxSupportedOdds;

    // the period of time in seconds before a market is matured and begins to be restricted for AMM trading
    uint public minimalTimeLeftToMaturity;

    // the period of time in seconds after maturity when ticket expires
    uint public expiryDuration;

    // divider on how much of cap should be used on live betting
    mapping(uint => uint) public liveCapDividerPerSport;

    // default live cap divider
    uint public defaultLiveCapDivider;

    // store whether a sportId is a futures market type
    mapping(uint16 => bool) public isSportIdFuture;

    // the maximum number of combinations on a system ticket
    uint public maxAllowedSystemCombinations;

    // store whether a sportId is a futures market type
    mapping(uint16 => bool) public sgpOnSportIdEnabled;

    // spent on sgp per game
    mapping(bytes32 => uint) public sgpSpentOnGame;

    // sgp cap divider
    uint public sgpCapDivider;

    // sgp risk per combination
    mapping(bytes32 => uint) public sgpRiskPerCombination;

    // cashout safe box fee multiplier (0 => use DEFAULT_CASHOUT_SAFEBOX_FEE_MULTIPLIER)
    uint public cashoutSafeBoxFeeMultiplier;

    // cashout cooldown in seconds (0 => use DEFAULT_CASHOUT_COOLDOWN)
    uint public cashoutCooldown;

    // quote threshold below which a multi-leg ticket (parlay or system bet) is routed to the default round
    // expressed in 1e18 terms (e.g. 0.02e18 means tickets with 50x+ payout are deferred)
    // 0 = feature disabled
    uint public defaultRoundHighQuoteThreshold;

    /* ========== CONSTRUCTOR ========== */

    function initialize(
        address _owner,
        ISportsAMMV2Manager _manager,
        ISportsAMMV2ResultManager _resultManager,
        uint _defaultCap,
        uint _defaultRiskMultiplier,
        uint _maxCap,
        uint _maxRiskMultiplier
    ) public initializer {
        setOwner(_owner);
        initNonReentrant();
        manager = _manager;
        resultManager = _resultManager;
        defaultCap = _defaultCap;
        defaultRiskMultiplier = _defaultRiskMultiplier;
        maxCap = _maxCap;
        maxRiskMultiplier = _maxRiskMultiplier;
    }

    /* ========== EXTERNAL READ FUNCTIONS ========== */

    /// @notice calculate which cap needs to be applied to the given game
    /// @param _gameId to get cap for
    /// @param _sportId to get cap for
    /// @param _typeId to get cap for
    /// @param _playerId to get cap for
    /// @param _maturity used for dynamic liquidity check
    /// @param _line used for dynamic liquidity check
    /// @param _isLive whether this is a live bet
    /// @return cap cap to use
    function calculateCapToBeUsed(
        bytes32 _gameId,
        uint16 _sportId,
        uint16 _typeId,
        uint24 _playerId,
        int24 _line,
        uint _maturity,
        bool _isLive
    ) external view returns (uint cap) {
        return _calculateCapToBeUsed(_gameId, _sportId, _typeId, _playerId, _line, _maturity, _isLive);
    }

    /// @notice calculate max available total risk on game
    /// @param _gameId to total risk for
    /// @param _sportId to total risk for
    /// @return totalRisk total risk
    function calculateTotalRiskOnGame(
        bytes32 _gameId,
        uint16 _sportId,
        uint _maturity
    ) external view returns (uint totalRisk) {
        (totalRisk, ) = _calculateTotalRiskOnGame(_gameId, _sportId, _maturity);
    }

    /// @notice check risk for ticket
    /// @param _tradeData trade data with all market info needed for ticket
    /// @param _buyInAmount ticket buy-in amount
    /// @param _systemBetDenominator in case of system bets, otherwise 0
    /// @return riskStatus risk status
    /// @return isMarketOutOfLiquidity array of boolean values that indicates if some market is out of liquidity
    function checkRisks(
        ISportsAMMV2.TradeData[] memory _tradeData,
        uint _buyInAmount,
        bool _isLive,
        uint8 _systemBetDenominator
    ) external view returns (ISportsAMMV2RiskManager.RiskStatus riskStatus, bool[] memory isMarketOutOfLiquidity) {
        uint numOfMarkets = _tradeData.length;
        isMarketOutOfLiquidity = new bool[](numOfMarkets);
        bool isFutureOnParlay;
        bool isSystemBet = _systemBetDenominator > 1;

        for (uint i; i < numOfMarkets; ++i) {
            ISportsAMMV2.TradeData memory marketTradeData = _tradeData[i];
            isFutureOnParlay = isSportIdFuture[marketTradeData.sportId] && numOfMarkets > 1;

            if (marketTradeData.odds[marketTradeData.position] == 0 || marketTradeData.odds[marketTradeData.position] >= ONE)
                revert InvalidOdds();

            uint amountToBuy = (ONE * _buyInAmount) / marketTradeData.odds[marketTradeData.position];
            uint marketRiskAmount = amountToBuy - _buyInAmount;
            if (isSystemBet) {
                marketRiskAmount = (marketRiskAmount * ONE * _systemBetDenominator) / (numOfMarkets * ONE);
            }

            if (isFutureOnParlay || _isInvalidCombinationOnTicket(_tradeData, marketTradeData, i)) {
                riskStatus = ISportsAMMV2RiskManager.RiskStatus.InvalidCombination;
            } else if (
                _isRiskPerMarketAndPositionExceeded(marketTradeData, marketRiskAmount, _isLive) ||
                _isRiskPerGameExceeded(marketTradeData, marketRiskAmount)
            ) {
                isMarketOutOfLiquidity[i] = true;
                // only set if no previous status was set
                if (riskStatus == ISportsAMMV2RiskManager.RiskStatus.NoRisk) {
                    riskStatus = ISportsAMMV2RiskManager.RiskStatus.OutOfLiquidity;
                }
            }
        }
    }

    /// @notice check limits for ticket
    /// @param _buyInAmount ticket buy-in amount
    /// @param _totalQuote ticket quote
    /// @param _payout actual payout
    /// @param _expectedPayout expected payout got from quote method
    /// @param _additionalSlippage slippage tolerance
    /// @param _ticketSize number of games in ticket
    function checkLimits(
        uint _buyInAmount,
        uint _totalQuote,
        uint _payout,
        uint _expectedPayout,
        uint _additionalSlippage,
        uint _ticketSize
    ) external view {
        // apply all checks
        if (_buyInAmount < minBuyInAmount) revert LowBuyIn();
        if (_totalQuote < maxSupportedOdds) revert ExceededMaxOdds();
        if ((_payout - _buyInAmount) > maxSupportedAmount) revert ExceededMaxAmount();
        if ((ONE * _expectedPayout) / _payout > ONE + _additionalSlippage) revert SlippageTooHigh();
        if (_ticketSize > maxTicketSize) revert ExceededMaxSize();
    }

    /// @notice returns risk data for given sports and types
    /// @param _sportIds sport IDs to get data for
    /// @param _typeIds type IDs to get data for
    /// @return riskData risk data
    function getRiskData(
        uint[] memory _sportIds,
        uint[] memory _typeIds
    ) external view returns (ISportsAMMV2RiskManager.RiskData[] memory riskData) {
        riskData = new ISportsAMMV2RiskManager.RiskData[](_sportIds.length);

        for (uint i; i < _sportIds.length; ++i) {
            uint sportId = _sportIds[i];

            ISportsAMMV2RiskManager.TypeCap[] memory capPerType = new ISportsAMMV2RiskManager.TypeCap[](_typeIds.length);

            for (uint j = 0; j < _typeIds.length; j++) {
                uint typeId = _typeIds[j];
                capPerType[j] = ISportsAMMV2RiskManager.TypeCap(typeId, capPerSportAndType[sportId][typeId]);
            }

            ISportsAMMV2RiskManager.CapData memory capData = ISportsAMMV2RiskManager.CapData(
                capPerSport[sportId],
                capPerSportChild[sportId],
                capPerType
            );

            ISportsAMMV2RiskManager.DynamicLiquidityData memory dynamicLiquidityData = ISportsAMMV2RiskManager
                .DynamicLiquidityData(
                    dynamicLiquidityCutoffTimePerSport[sportId],
                    dynamicLiquidityCutoffDividerPerSport[sportId]
                );

            riskData[i] = ISportsAMMV2RiskManager.RiskData(
                sportId,
                capData,
                riskMultiplierPerSport[sportId],
                dynamicLiquidityData
            );
        }
    }

    /**
     * @notice Calculates the maximum system bet payout based on trade data, system bet denominator, and buy-in amount.
     * @dev This function computes the payout for a system bet based on the provided data and conditions.
     * @param _tradeData The array of trade data for the markets involved in the bet.
     * @param _systemBetDenominator The system bet denominator to adjust the payout calculation.
     * @param _buyInAmount The amount of collateral staked by the user in the system bet.
     * @param _addedPayoutPercentage The bonus payout in case THALES is used
     * @return systemBetPayout The calculated payout amount based on the input parameters.
     * @return systemBetQuote The calculated quote odds based on the input parameters.
     */
    function getMaxSystemBetPayout(
        ISportsAMMV2.TradeData[] memory _tradeData,
        uint8 _systemBetDenominator,
        uint _buyInAmount,
        uint _addedPayoutPercentage
    ) external view returns (uint systemBetPayout, uint systemBetQuote) {
        uint8[][] memory systemCombinations = generateCombinations(uint8(_tradeData.length), _systemBetDenominator);
        uint totalCombinations = systemCombinations.length;

        if (totalCombinations > maxAllowedSystemCombinations) revert ExceededMaxCombinations();

        uint buyinPerCombination = ((_buyInAmount * ONE) / totalCombinations) / ONE;

        // Loop through each stored combination
        for (uint i; i < totalCombinations; ++i) {
            uint8[] memory currentCombination = systemCombinations[i];

            uint combinationQuote;

            for (uint8 j = 0; j < currentCombination.length; j++) {
                uint8 marketIndex = currentCombination[j];
                uint odds = _tradeData[marketIndex].odds[_tradeData[marketIndex].position];
                odds = (odds * ONE) / ((ONE + _addedPayoutPercentage) - (_addedPayoutPercentage * odds) / ONE);
                combinationQuote = combinationQuote == 0 ? odds : (combinationQuote * odds) / ONE;
            }

            if (combinationQuote > 0) {
                uint combinationPayout = (buyinPerCombination * ONE) / combinationQuote;
                systemBetPayout += combinationPayout;
            }
        }
        systemBetQuote = (ONE * _buyInAmount) / systemBetPayout;
    }

    /// @notice Returns cashout safe box fee multiplier (uses default if unset).
    function getCashoutSafeBoxFeeMultiplier() external view returns (uint) {
        return cashoutSafeBoxFeeMultiplier > 0 ? cashoutSafeBoxFeeMultiplier : DEFAULT_CASHOUT_SAFEBOX_FEE_MULTIPLIER;
    }

    /// @notice Returns cashout cooldown in seconds (uses default if unset).
    function getCashoutCooldown() external view returns (uint) {
        return cashoutCooldown > 0 ? cashoutCooldown : DEFAULT_CASHOUT_COOLDOWN;
    }

    /* ========== SYSTEM BET UTILS ========== */

    /**
     * @notice Generates all unique combinations of size `k` from a set of integers {0, 1, ..., n-1}.
     * @dev Uses `uint8` to reduce gas costs since `n` is guaranteed to be <= 15.
     * @param n The size of the set (must be greater than `k`).
     * @param k The size of each combination (must be greater than 1 and less than `n`).
     * @return combinations A 2D array where each sub-array is a unique combination of `k` integers.
     */
    function generateCombinations(uint8 n, uint8 k) public pure returns (uint8[][] memory) {
        if (k <= 1 || k >= n) revert BadRangeForK();

        // Calculate the number of combinations: n! / (k! * (n-k)!)
        uint combinationsCount = 1;
        for (uint8 i = 0; i < k; ++i) {
            combinationsCount = (combinationsCount * (n - i)) / (i + 1);
        }

        // Initialize combinations array
        uint8[][] memory combinations = new uint8[][](combinationsCount);

        // Generate combinations
        uint8[] memory indices = new uint8[](k);
        for (uint8 i = 0; i < k; ++i) {
            indices[i] = i;
        }

        uint index = 0;

        while (true) {
            // Add the current combination
            uint8[] memory combination = new uint8[](k);
            for (uint8 i = 0; i < k; ++i) {
                combination[i] = indices[i];
            }
            combinations[index] = combination;
            index++;

            // Generate the next combination
            bool done = true;
            for (uint8 i = k; i > 0; i--) {
                if (indices[i - 1] < n - (k - (i - 1))) {
                    indices[i - 1]++;
                    for (uint8 j = i; j < k; j++) {
                        indices[j] = indices[j - 1] + 1;
                    }
                    done = false;
                    break;
                }
            }

            if (done) {
                break;
            }
        }

        return combinations;
    }

    /* ========== EXTERNAL WRITE FUNCTIONS ========== */

    /// @notice check and update risks for ticket
    /// @param _tradeData trade data with all market info needed for ticket
    /// @param _buyInAmount ticket buy-in amount
    /// @param _payout ticket _payout
    /// @param _isLive whether this ticket is live
    /// @param _systemBetDenominator in case of system bets, otherwise 0
    /// @param _isSGP whether this ticket is SGP
    function checkAndUpdateRisks(
        ISportsAMMV2.TradeData[] memory _tradeData,
        uint _buyInAmount,
        uint _payout,
        bool _isLive,
        uint8 _systemBetDenominator,
        bool _isSGP
    ) external onlySportsAMM(msg.sender) {
        uint numOfMarkets = _tradeData.length;
        for (uint i; i < numOfMarkets; ++i) {
            ISportsAMMV2.TradeData memory marketTradeData = _tradeData[i];

            if (isSportIdFuture[marketTradeData.sportId] && _tradeData.length > 1) {
                revert CantParlayFutures();
            }

            uint[] memory odds = marketTradeData.odds;
            uint8 position = marketTradeData.position;

            if (odds.length <= position) revert InvalidPosition();
            if (!_isMarketInAMMTrading(marketTradeData)) revert MarketNotTrading();

            uint amountToBuy = odds[position] == 0 ? 0 : (ONE * _buyInAmount) / odds[position];
            if (amountToBuy > _buyInAmount) {
                uint marketRiskAmount = amountToBuy - _buyInAmount;
                // for system bet, each of the M legs carries a uniform effective stake of (D/M) of the buy-in.
                // Reuse `amountToBuy` (dead after this point) to carry the per-leg effective buy-in derived
                // from the original _buyInAmount. Do NOT mutate _buyInAmount here: it is read on every
                // iteration, so scaling it in place would compound across legs and under-count later legs.
                amountToBuy = _buyInAmount;
                if (_systemBetDenominator > 1) {
                    marketRiskAmount = (marketRiskAmount * ONE * _systemBetDenominator) / (numOfMarkets * ONE);
                    amountToBuy = (_buyInAmount * ONE * _systemBetDenominator) / (numOfMarkets * ONE);
                }

                if (_isRiskPerMarketAndPositionExceeded(marketTradeData, marketRiskAmount, _isLive))
                    revert ExceededMarketPositionRisk();

                if (_isRiskPerGameExceeded(marketTradeData, marketRiskAmount)) revert ExceededGameRisk();

                if (!_isSGP && _isInvalidCombinationOnTicket(_tradeData, marketTradeData, i)) revert InvalidCombination();

                _updateRisk(marketTradeData, marketRiskAmount, amountToBuy, _isLive);
            }
        }
        if (_isSGP) {
            _checkAndUpdateSGPRisk(_tradeData, _payout - _buyInAmount);
        }
    }

    /// @notice verifies the merkle proof against the root per game or the root per game and type
    /// @param _marketTradeData trade data with all market info needed for ticket
    /// @param _rootPerGame root per game to verify against
    function verifyMerkleTree(ISportsAMMV2.TradeData memory _marketTradeData, bytes32 _rootPerGame) external view {
        _verifyMerkleTree(_marketTradeData, _rootPerGame);
    }

    /// @notice Batch verification of multiple market trade data against respective roots
    /// @param _marketTradeData array of trade data with all market info needed for ticket
    /// @param _rootPerGame array of merkle roots per game to verify against
    function batchVerifyMerkleTree(
        ISportsAMMV2.TradeData[] memory _marketTradeData,
        bytes32[] memory _rootPerGame
    ) external view {
        if (_marketTradeData.length != _rootPerGame.length) revert MismatchedInputs();

        for (uint i; i < _marketTradeData.length; ++i) {
            _verifyMerkleTree(_marketTradeData[i], _rootPerGame[i]);
        }
    }

    function _verifyMerkleTree(ISportsAMMV2.TradeData memory _marketTradeData, bytes32 _rootPerGame) internal view {
        bytes32 _rootPerGameAndType = sportsAMM.rootPerGameAndType(_marketTradeData.gameId, _marketTradeData.typeId);
        // either root matches; an unset (zero) root never does. Roots per game and type are 16-byte prefixes:
        // forging one is a 2^128 second-preimage against a root the trader does not influence
        bytes32 computedRoot = MerkleProof.processProof(_marketTradeData.merkleProof, _computeMerkleLeaf(_marketTradeData));
        require(
            (_rootPerGame != 0 && computedRoot == _rootPerGame) ||
                (_rootPerGameAndType != 0 && bytes16(computedRoot) == bytes16(_rootPerGameAndType)),
            "Proof is not valid"
        );
    }

    /// @notice Computes the merkle leaf from trade data
    /// @param _marketTradeData trade data with all market info needed for ticket
    /// @return leaf computed merkle leaf
    function _computeMerkleLeaf(ISportsAMMV2.TradeData memory _marketTradeData) private pure returns (bytes32) {
        // Combined-position markets are disabled. The previous leaf hash
        // packed nested combinedPositions without length prefixes, which
        // allowed re-partitioning of the outer/inner array boundaries
        // while preserving the keccak. Reject any non-empty inner array.
        uint cpOuter = _marketTradeData.combinedPositions.length;
        for (uint i; i < cpOuter; ++i) {
            require(_marketTradeData.combinedPositions[i].length == 0, "Combined markets disabled");
        }
        return
            keccak256(
                abi.encodePacked(
                    _marketTradeData.gameId,
                    uint(_marketTradeData.sportId),
                    uint(_marketTradeData.typeId),
                    _marketTradeData.maturity,
                    uint(_marketTradeData.status),
                    int(_marketTradeData.line),
                    uint(_marketTradeData.playerId),
                    _marketTradeData.odds
                )
            );
    }

    /**
     * @notice Reads the total risk stored for a given Same Game Parlay (SGP) combination.
     * @dev Computes the SGP hash and retrieves the associated risk amount.
     * @param trades The array of `TradeData` structs representing the parlay selections.
     * @return uint The total risk amount associated with the given SGP.
     */
    function getSGPCombinationRisk(ISportsAMMV2.TradeData[] memory trades) external view returns (uint) {
        bytes32 sgpHash = getSGPHash(trades);
        return sgpRiskPerCombination[sgpHash];
    }

    /* ========== INTERNAL FUNCTIONS ========== */

    function _isMarketInAMMTrading(ISportsAMMV2.TradeData memory _marketTradeData) internal view returns (bool isTrading) {
        uint maturity = _marketTradeData.maturity;

        bool isResolved = resultManager.isMarketResolved(
            _marketTradeData.gameId,
            _marketTradeData.typeId,
            _marketTradeData.playerId,
            _marketTradeData.line,
            _marketTradeData.combinedPositions[_marketTradeData.position]
        );
        if (_marketTradeData.status == 0 && !isResolved) {
            if (maturity >= block.timestamp) {
                isTrading = (maturity - block.timestamp) > minimalTimeLeftToMaturity;
            }
        }
    }

    function _isRiskPerMarketAndPositionExceeded(
        ISportsAMMV2.TradeData memory _marketTradeData,
        uint marketRiskAmount,
        bool _isLive
    ) internal view returns (bool) {
        bytes32 gameId = _marketTradeData.gameId;
        uint16 typeId = _marketTradeData.typeId;
        uint24 playerId = _marketTradeData.playerId;

        return
            riskPerMarketTypeAndPosition[gameId][typeId][playerId][_marketTradeData.position] + int(marketRiskAmount) >
            int(
                _calculateCapToBeUsed(
                    gameId,
                    _marketTradeData.sportId,
                    typeId,
                    playerId,
                    _marketTradeData.line,
                    _marketTradeData.maturity,
                    _isLive
                )
            );
    }

    function _isRiskPerGameExceeded(
        ISportsAMMV2.TradeData memory _marketTradeData,
        uint marketRiskAmount
    ) internal view returns (bool) {
        bytes32 gameId = _marketTradeData.gameId;
        (uint totalRisk, ) = _calculateTotalRiskOnGame(gameId, _marketTradeData.sportId, _marketTradeData.maturity);
        return (spentOnGame[gameId] + marketRiskAmount) > totalRisk;
    }

    function _checkAndUpdateSGPRisk(ISportsAMMV2.TradeData[] memory _tradeData, uint marketRiskAmount) internal {
        uint sgpDividerToUse = sgpCapDivider > 0 ? sgpCapDivider : 2;
        uint minCapToBeUsed = type(uint).max;

        for (uint i; i < _tradeData.length; ++i) {
            bytes32 gameId = _tradeData[i].gameId;

            // skip gameIds already processed (dedupe; ticket size is small so O(n^2) is fine)
            bool alreadyProcessed;
            for (uint j; j < i; ++j) {
                if (_tradeData[j].gameId == gameId) {
                    alreadyProcessed = true;
                    break;
                }
            }
            if (alreadyProcessed) continue;

            (uint totalRisk, uint capToBeUsed) = _calculateTotalRiskOnGame(
                gameId,
                _tradeData[i].sportId,
                _tradeData[i].maturity
            );
            // full SGP risk is checked and booked against every game on the ticket,
            // since the house can lose the full payout through each of these games
            if ((sgpSpentOnGame[gameId] + marketRiskAmount) > (totalRisk / sgpDividerToUse)) revert ExceededSGPRisk();
            sgpSpentOnGame[gameId] += marketRiskAmount;

            if (capToBeUsed < minCapToBeUsed) {
                minCapToBeUsed = capToBeUsed;
            }
        }

        // risk for a unique SGP combination cant exceed the most constrained game's moneyline cap / sgpDivider
        bytes32 sgpHash = getSGPHash(_tradeData);
        if ((sgpRiskPerCombination[sgpHash] + marketRiskAmount) > (minCapToBeUsed / sgpDividerToUse))
            revert ExceededSGPRisk();
        sgpRiskPerCombination[sgpHash] += marketRiskAmount;
    }

    function _isInvalidCombinationOnTicket(
        ISportsAMMV2.TradeData[] memory _tradeData,
        ISportsAMMV2.TradeData memory _currentTradaData,
        uint currentIndex
    ) internal view returns (bool isInvalid) {
        for (uint j = currentIndex + 1; j < _tradeData.length; ++j) {
            ISportsAMMV2.TradeData memory tradeDataToCheckAgainst = _tradeData[j];
            if (
                _currentTradaData.gameId == tradeDataToCheckAgainst.gameId &&
                _currentTradaData.sportId == tradeDataToCheckAgainst.sportId
            ) {
                if (
                    !combiningPerSportEnabled[_currentTradaData.sportId] ||
                    _currentTradaData.playerId == tradeDataToCheckAgainst.playerId ||
                    _currentTradaData.playerId == 0 ||
                    tradeDataToCheckAgainst.playerId == 0
                ) {
                    isInvalid = true;
                    break;
                }
            }
        }
    }

    function _updateRisk(
        ISportsAMMV2.TradeData memory _marketTradeData,
        uint marketRiskAmount,
        uint _buyInAmount,
        bool _isLive
    ) internal {
        bytes32 gameId = _marketTradeData.gameId;
        uint16 typeId = _marketTradeData.typeId;
        uint24 playerId = _marketTradeData.playerId;
        uint8 position = _marketTradeData.position;

        uint256 len = _marketTradeData.odds.length;
        bool isBigMarket = len > 32;

        // For live markets we hardcode number of positions to 225. Only write from 0 to position +3, covers 99% of markets.
        // For others (correct score mostly), its enough to just write the risk to the position being bet on.
        uint256 endIndex = _isLive ? (position + 3 > len ? len : position + 3) : len;

        for (uint256 j; j < endIndex; ++j) {
            int currentRisk = riskPerMarketTypeAndPosition[gameId][typeId][playerId][j];

            if (j == position) {
                // Selected position – always add risk
                riskPerMarketTypeAndPosition[gameId][typeId][playerId][j] = currentRisk + int(marketRiskAmount);
            } else {
                // Small markets – keep old behavior (hedge on all positions) OR
                // Big markets – only adjust if there was already some risk
                if (!isBigMarket || currentRisk > 0) {
                    riskPerMarketTypeAndPosition[gameId][typeId][playerId][j] = currentRisk - int(_buyInAmount);
                }
            }
        }

        spentOnGame[gameId] += marketRiskAmount;
    }

    function _calculateRiskMultiplier(bytes32 _gameId, uint16 _sportId) internal view returns (uint gameRisk) {
        gameRisk = riskMultiplierPerGame[_gameId];

        if (gameRisk == 0) {
            uint riskPerSport = riskMultiplierPerSport[_sportId];
            gameRisk = riskPerSport > 0 ? riskPerSport : defaultRiskMultiplier;
        }
    }

    function _calculateCapToBeUsed(
        bytes32 _gameId,
        uint16 _sportId,
        uint16 _typeId,
        uint24 _playerId,
        int24 _line,
        uint _maturity,
        bool _isLive
    ) internal view returns (uint cap) {
        if (_maturity > block.timestamp) {
            cap = capPerMarket[_gameId][_typeId][_playerId][_line] > 0
                ? capPerMarket[_gameId][_typeId][_playerId][_line]
                : capPerMarket[_gameId][_typeId][0][0];
            if (cap == 0) {
                uint sportCap = capPerSport[_sportId];
                sportCap = sportCap > 0 ? sportCap : defaultCap;
                cap = sportCap;

                if (_typeId > 0) {
                    // Check for explicitly set moneyline market cap
                    uint typeCap = capPerSportAndType[_sportId][_typeId];
                    uint moneylineMarketCap = capPerMarket[_gameId][0][0][0];
                    if (moneylineMarketCap > 0) {
                        cap = (moneylineMarketCap / 2 < typeCap || typeCap == 0) ? moneylineMarketCap / 2 : typeCap;
                    } else {
                        cap = typeCap;
                        if (cap == 0) {
                            uint childCap = capPerSportChild[_sportId];
                            cap = childCap > 0 ? childCap : sportCap / 2;
                        }
                    }
                }
            }

            if (_isLive) {
                cap =
                    cap /
                    (
                        liveCapDividerPerSport[_sportId] > 0 ? liveCapDividerPerSport[_sportId] : defaultLiveCapDivider > 0
                            ? defaultLiveCapDivider
                            : 1
                    );
            }

            uint dynamicLiquidityCutoffTime = dynamicLiquidityCutoffTimePerSport[_sportId];
            if (dynamicLiquidityCutoffTime > 0) {
                uint timeToStart = _maturity - block.timestamp;
                uint cutOffLiquidity = (cap * ONE) /
                    (
                        dynamicLiquidityCutoffDividerPerSport[_sportId] > 0
                            ? dynamicLiquidityCutoffDividerPerSport[_sportId]
                            : DEFAULT_DYNAMIC_LIQUIDITY_CUTOFF_DIVIDER
                    );
                if (timeToStart >= dynamicLiquidityCutoffTime) {
                    cap = cutOffLiquidity;
                } else {
                    uint remainingFromCutOff = cap - cutOffLiquidity;
                    cap =
                        cutOffLiquidity +
                        (((dynamicLiquidityCutoffTime - timeToStart) * remainingFromCutOff) / dynamicLiquidityCutoffTime);
                }
            }
        }
    }

    function _calculateTotalRiskOnGame(
        bytes32 _gameId,
        uint16 _sportId,
        uint _maturity
    ) internal view returns (uint totalRisk, uint capToBeUsed) {
        // get cap for parent market
        capToBeUsed = _calculateCapToBeUsed(_gameId, _sportId, 0, 0, 0, _maturity, false);
        totalRisk = (capToBeUsed * _calculateRiskMultiplier(_gameId, _sportId));
    }

