        uint16[] memory _typeIds,
        uint24[] memory _playerIds,
        int24[] memory _lines,
        uint[] memory _capsPerMarket
    ) external onlyWhitelistedAddresses(msg.sender) {
        for (uint i; i < _gameIds.length; ++i) {
