    /**
     * @notice Computes a unique hash for a Same Game Parlay (SGP) using only relevant fields.
     * @dev Extracts `gameId`, `typeId`, and `playerId` from the `TradeData` struct and hashes them.
     * @param trades The array of `TradeData` structs representing the parlay selections.
     * @return bytes32 A unique hash representing the SGP combination.
     */
    function getSGPHash(ISportsAMMV2.TradeData[] memory trades) public pure returns (bytes32) {
        // Sort trades based on (gameId, typeId, playerId and lineId)
        _sortSGPLegs(trades);

        bytes32[] memory gameIds = new bytes32[](trades.length);
        uint16[] memory typeIds = new uint16[](trades.length);
        uint24[] memory playerIds = new uint24[](trades.length);

        for (uint i; i < trades.length; ++i) {
            gameIds[i] = trades[i].gameId;
            typeIds[i] = trades[i].typeId;
            playerIds[i] = trades[i].playerId;
        }

        return keccak256(abi.encode(gameIds, typeIds, playerIds));
    }

    function _sortSGPLegs(ISportsAMMV2.TradeData[] memory trades) internal pure {
        uint256 length = trades.length;
        for (uint256 i = 0; i < length - 1; ++i) {
            for (uint256 j = i + 1; j < length; j++) {
                if (_compareSGPLegs(trades[i], trades[j]) > 0) {
                    // Swap trades[i] and trades[j]
                    (trades[i], trades[j]) = (trades[j], trades[i]);
                }
            }
        }
    }

    function _compareSGPLegs(ISportsAMMV2.TradeData memory a, ISportsAMMV2.TradeData memory b) internal pure returns (int) {
        if (uint256(a.gameId) < uint256(b.gameId)) return -1;
        if (uint256(a.gameId) > uint256(b.gameId)) return 1;
        if (a.typeId < b.typeId) return -1;
        if (a.typeId > b.typeId) return 1;
        if (a.playerId < b.playerId) return -1;
        if (a.playerId > b.playerId) return 1;
        if (a.line < b.line) return -1;
        if (a.line > b.line) return 1;
        return 0;
    }

    /* ========== MODIFIERS ========== */

    modifier onlyWhitelistedAddresses(address sender) {
        require(
            sender == owner || manager.isWhitelistedAddress(sender, ISportsAMMV2Manager.Role.RISK_MANAGING),
            "InvalidSender"
        );
        _;
    }

    modifier onlySportsAMM(address sender) {
        require(sender == address(sportsAMM), "OnlyAMMAllowed");
        _;
    }

    /* ========== EVENTS ========== */

    event SetMaxCapAndMaxRiskMultiplier(uint maxCap, uint maxRiskMultiplier);
    event SetDefaultCapAndDefaultRiskMultiplier(uint defaultCap, uint defaultRiskMultiplier);

    event SetCapPerSport(uint sportId, uint cap);
    event SetCapPerSportChild(uint sportId, uint cap);
    event SetCapPerSportAndType(uint sportId, uint typeId, uint cap);
    event SetCapPerMarket(bytes32 gameId, uint16 typeId, uint24 playerId, int24 line, uint cap);

    event SetRiskMultiplierPerSport(uint sportId, uint riskMultiplier);
    event SetRiskMultiplierPerGame(bytes32 gameId, uint riskMultiplier);

    event SetDynamicLiquidityParams(uint sportId, uint dynamicLiquidityCutoffTime, uint dynamicLiquidityCutoffDivider);
    event SetAddresses(address _manager, address _resultManager, address _sportsAMM);
    event SetLiveTradingPerSportAndTypeEnabled(uint _sportId, uint _typeId, bool _enabled);
    event SetCombiningPerSportEnabled(uint _sportID, bool _enabled);
    event TicketParamsUpdated(
        uint minBuyInAmount,
        uint maxTicketSize,
        uint maxSupportedAmount,
        uint maxSupportedOdds,
        uint maxAllowedSystemCombinations
    );
    event TimesUpdated(uint minimalTimeLeftToMaturity, uint expiryDuration);

    event SetLiveCapDivider(uint _sportId, uint _divider);
    event SetDefaultLiveCapDivider(uint _divider);
    event SetSGPCapDivider(uint _divider);

    event SetIsSportIdFuture(uint16 _sportId, bool _isFuture);
    event SetSGPEnabledOnSport(uint16 _sportId, bool _isEnabled);
    event SetCashoutSafeBoxFeeMultiplier(uint multiplier);
    event SetCashoutCooldown(uint cooldown);
    event DefaultRoundHighQuoteThresholdUpdated(uint threshold);
}

contracts/core/AMM/SportsAMMV2Utils.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "../../interfaces/ISportsAMMV2.sol";
import "../../interfaces/ISportsAMMV2RiskManager.sol";
import "../../interfaces/ISportsAMMV2LiquidityPool.sol";
import "@thales-dao/contracts/contracts/interfaces/IMultiCollateralOnOffRamp.sol";
import "@thales-dao/contracts/contracts/interfaces/IReferrals.sol";

// Local interface to cast collateralSupported as view
interface IViewMultiCollateralOnOffRamp {
    function collateralSupported(address collateral) external view returns (bool);
}

/// @title SportsAMMV2 Utils - stateless helper for offloading computation from SportsAMMV2
/// @author danijel
contract SportsAMMV2Utils {
    uint private constant ONE = 1e18;

    error InvalidPosition();
    error ZeroAmount();
    error IllegalInputAmounts();
    error InsufficientAllowance();
    error InsufficientBalance();
    error LpCollateralPriceZero();
    error OnRampNotSupported();
    error CollateralNotSupported();
    error LowBuyIn();
    error ExceededMaxOdds();
    error ExceededMaxSize();

    struct TradeProcessingResult {
        uint _totalQuote;
        uint _payout;
        uint _fees;
        uint _payoutWithFees;
        uint _expectedPayout;
    }

    struct CalculateTradeParams {
        uint _buyInAmount;
        uint _expectedPayout;
        bool _isLive;
        bool _isSGP;
        uint _addedPayoutPercentage;
        uint _safeBoxFee;
    }

    struct TradeDataQuoteInternal {
        uint _buyInAmount;
        bool _shouldCheckRisks;
        uint _buyInAmountInDefaultCollateral;
        bool _isLive;
        bool _isSGP;
        uint _approvedQuote;
    }

    struct TradeQuoteParams {
        ISportsAMMV2RiskManager _riskManager;
        ISportsAMMV2 _amm;
        uint _addedPayoutPercentage;
        uint _safeBoxFee;
    }

    struct CollateralParams {
        address _defaultCollateral;
        uint _defaultCollateralDecimals;
        address _liquidityPool;
        IMultiCollateralOnOffRamp _multiCollateralOnOffRamp;
    }

    struct TradeQuoteCommonParams {
        ISportsAMMV2RiskManager _riskManager;
        ISportsAMMV2 _amm;
        uint _addedPayoutPercentage;
        uint _safeBoxFee;
        CollateralParams _collateralParams;
    }

    /// @notice Full trade quote with collateral resolution, used by SportsAMMV2 external quote functions
    /// @param _tradeData array of market trade data
    /// @param _buyInAmount buy-in amount in the provided collateral
    /// @param _collateral collateral token address (address(0) for default)
    /// @param _isLive whether this is a live bet
    /// @param _systemBetDenominator system bet denominator (0 or 1 for non-system bets)
    /// @param _params common parameters including risk manager, AMM reference, and collateral config
    function tradeQuoteCommon(
        ISportsAMMV2.TradeData[] memory _tradeData,
        uint _buyInAmount,
        address _collateral,
        bool _isLive,
        uint8 _systemBetDenominator,
        TradeQuoteCommonParams memory _params
    )
        external
        view
        returns (
            uint totalQuote,
            uint payout,
            uint fees,
            uint[] memory amountsToBuy,
            uint buyInAmountInDefaultCollateral,
            ISportsAMMV2RiskManager.RiskStatus riskStatus
        )
    {
        uint useAmount;
        (useAmount, buyInAmountInDefaultCollateral) = _resolveCollateral(
            _buyInAmount,
            _collateral,
            _params._collateralParams
        );

        TradeQuoteParams memory qp = TradeQuoteParams(
            _params._riskManager,
            _params._amm,
            _params._addedPayoutPercentage,
            _params._safeBoxFee
        );
        (totalQuote, payout, fees, amountsToBuy, riskStatus) = _tradeQuote(
            _tradeData,
            TradeDataQuoteInternal(useAmount, true, buyInAmountInDefaultCollateral, _isLive, false, 0),
            _systemBetDenominator,
            qp
        );
    }

    /// @notice Core trade quote without collateral resolution, used during trade execution
    /// @param _tradeData array of market trade data
    /// @param _tradeDataQuoteInternal internal quote parameters
    /// @param _systemBetDenominator system bet denominator
    /// @param _params quote parameters including risk manager and AMM reference
    function tradeQuote(
        ISportsAMMV2.TradeData[] memory _tradeData,
        TradeDataQuoteInternal memory _tradeDataQuoteInternal,
        uint8 _systemBetDenominator,
        TradeQuoteParams memory _params
    )
        external
        view
        returns (
            uint totalQuote,
            uint payout,
            uint fees,
            uint[] memory amountsToBuy,
            ISportsAMMV2RiskManager.RiskStatus riskStatus
        )
    {
        return _tradeQuote(_tradeData, _tradeDataQuoteInternal, _systemBetDenominator, _params);
    }

    /// @notice Calculates quote for trade execution (prematch and live), called from SportsAMMV2._trade
    /// @param _tradeData array of market trade data
    /// @param _calc trade calculation parameters (buy-in, payout, flags, fees)
    /// @param _systemBetDenominator system bet denominator
    /// @param _params quote parameters including risk manager and AMM reference
    /// @return result processing result with totalQuote, payout, fees, payoutWithFees, and expectedPayout
    function calculateTradeQuote(
        ISportsAMMV2.TradeData[] memory _tradeData,
        CalculateTradeParams memory _calc,
        uint8 _systemBetDenominator,
        TradeQuoteParams memory _params
    ) external view returns (TradeProcessingResult memory result) {
        if (!_calc._isLive) {
            (result._totalQuote, result._payout, result._fees, , ) = _tradeQuote(
                _tradeData,
                TradeDataQuoteInternal(
                    _calc._buyInAmount,
                    false,
                    0,
                    _calc._isLive,
                    _calc._isSGP,
                    _divWithDecimals(_calc._buyInAmount, _calc._expectedPayout)
                ),
                _systemBetDenominator,
                _params
            );
            result._expectedPayout = _calc._expectedPayout;
        } else {
            result = _calculateLiveQuote(_tradeData, _calc, _params);
        }

        result._payoutWithFees = result._payout + result._fees;
    }

    /// @notice Transforms amounts to USD (if non-default collateral) and calls riskManager.checkLimits
    /// @param _riskManager risk manager contract
    /// @param _buyInAmount buy-in amount in collateral
    /// @param _totalQuote total quote
    /// @param _payout expected payout in collateral
    /// @param _expectedPayout expected payout for slippage check
    /// @param _additionalSlippage additional slippage tolerance
    /// @param _ticketSize number of markets in the ticket
    /// @param _collateralPriceInUSD collateral price in USD (0 if default collateral)
    /// @param _collateral collateral token address
    /// @param _defaultCollateralDecimals decimals of the default collateral
    /// @return buyInAmountUSD buy-in amount in USD
    /// @return payoutUSD payout in USD
    function checkLimitsWithTransform(
        ISportsAMMV2RiskManager _riskManager,
        uint _buyInAmount,
        uint _totalQuote,
        uint _payout,
        uint _expectedPayout,
        uint _additionalSlippage,
        uint _ticketSize,
        uint _collateralPriceInUSD,
        address _collateral,
        uint _defaultCollateralDecimals
    ) external view returns (uint buyInAmountUSD, uint payoutUSD) {
        buyInAmountUSD = _buyInAmount;
        payoutUSD = _payout;
        if (_collateralPriceInUSD > 0) {
            uint collateralDecimals = ISportsAMMV2Manager(_collateral).decimals();
            buyInAmountUSD = _transformToUSD(
                _buyInAmount,
                _collateralPriceInUSD,
                collateralDecimals,
                _defaultCollateralDecimals
            );
            payoutUSD = _transformToUSD(_payout, _collateralPriceInUSD, collateralDecimals, _defaultCollateralDecimals);
            _expectedPayout = _transformToUSD(
                _expectedPayout,
                _collateralPriceInUSD,
                collateralDecimals,
                _defaultCollateralDecimals
            );
        }
        _riskManager.checkLimits(buyInAmountUSD, _totalQuote, payoutUSD, _expectedPayout, _additionalSlippage, _ticketSize);
    }

    function _calculateLiveQuote(
        ISportsAMMV2.TradeData[] memory _tradeData,
        CalculateTradeParams memory _calc,
        TradeQuoteParams memory _params
    ) internal view returns (TradeProcessingResult memory result) {
        uint numOfMarkets = _tradeData.length;
        uint maxSupportedOdds = _params._riskManager.maxSupportedOdds();

        if (_calc._isSGP) {
            uint expectedQuote = _divWithDecimals(_calc._buyInAmount, _calc._expectedPayout);
            result._totalQuote =
                (expectedQuote * ONE) /
                ((ONE + _calc._addedPayoutPercentage) - _mulWithDecimals(_calc._addedPayoutPercentage, expectedQuote));
        } else {
            if (numOfMarkets == 1) {
                uint legOdd = _tradeData[0].odds[_tradeData[0].position];
                uint boosted = _applyBonusToOdd(legOdd, _calc._addedPayoutPercentage);
                if (boosted < maxSupportedOdds) boosted = maxSupportedOdds;
                result._totalQuote = boosted;
            } else {
                result._totalQuote = _calculateLiveParlay(_tradeData, _calc, maxSupportedOdds);
            }
        }

        result._payout = _divWithDecimals(_calc._buyInAmount, result._totalQuote);
        result._fees = (_calc._buyInAmount * _params._safeBoxFee) / ONE;
        result._expectedPayout = result._payout;
    }

    function _calculateLiveParlay(
        ISportsAMMV2.TradeData[] memory _tradeData,
        CalculateTradeParams memory _calc,
        uint _minImplied
    ) internal pure returns (uint totalQuote) {
        uint numOfMarkets = _tradeData.length;
        uint baseQuote = 0;
        uint boostedQuote = 0;

        uint approvedBaseQuote = _calc._expectedPayout == 0
            ? 0
            : _divWithDecimals(_calc._buyInAmount, _calc._expectedPayout);

        for (uint i = 0; i < numOfMarkets; ++i) {
            ISportsAMMV2.TradeData memory td = _tradeData[i];
            if (td.odds.length <= td.position) revert InvalidPosition();
            uint legOdd = td.odds[td.position];
            if (legOdd == 0) revert ZeroAmount();

            baseQuote = (baseQuote == 0) ? legOdd : _mulWithDecimals(baseQuote, legOdd);

            uint boostedLeg = _applyBonusToOdd(legOdd, _calc._addedPayoutPercentage);
            boostedQuote = (boostedQuote == 0) ? boostedLeg : _mulWithDecimals(boostedQuote, boostedLeg);
        }

        uint relTol = 1e12; // 1 ppm
        if (approvedBaseQuote == 0) revert IllegalInputAmounts();

        if (boostedQuote < _minImplied) {
            uint diffClamp = _absDiff(_minImplied, approvedBaseQuote);
            if ((diffClamp * ONE) / approvedBaseQuote > relTol) revert IllegalInputAmounts();
        } else {
            uint diffBase = _absDiff(baseQuote, approvedBaseQuote);
            if ((diffBase * ONE) / approvedBaseQuote > relTol) revert IllegalInputAmounts();
        }

        totalQuote = boostedQuote;
        if (totalQuote < _minImplied) totalQuote = _minImplied;
    }

    function _resolveCollateral(
        uint _buyInAmount,
        address _collateral,
        CollateralParams memory _cp
    ) internal view returns (uint useAmount, uint buyInAmountInDefaultCollateral) {
        useAmount = _buyInAmount;
        buyInAmountInDefaultCollateral = _buyInAmount;

        if (_collateral != address(0) && _collateral != _cp._defaultCollateral) {
            if (_cp._liquidityPool == address(0)) {
                buyInAmountInDefaultCollateral = _cp._multiCollateralOnOffRamp.getMinimumReceived(_collateral, _buyInAmount);
                useAmount = buyInAmountInDefaultCollateral;
            } else {
                uint collateralPrice = ISportsAMMV2LiquidityPool(_cp._liquidityPool).getCollateralPrice();
                uint collateralDecimals = ISportsAMMV2Manager(_collateral).decimals();
                buyInAmountInDefaultCollateral = _transformToUSD(
                    _buyInAmount,
                    collateralPrice,
                    collateralDecimals,
                    _cp._defaultCollateralDecimals
                );
            }
        }

        if (useAmount == 0) revert ZeroAmount();
    }

    function _tradeQuote(
        ISportsAMMV2.TradeData[] memory _tradeData,
        TradeDataQuoteInternal memory _q,
        uint8 _systemBetDenominator,
        TradeQuoteParams memory _p
    )
        internal
        view
        returns (
            uint totalQuote,
            uint payout,
            uint fees,
            uint[] memory amountsToBuy,
            ISportsAMMV2RiskManager.RiskStatus riskStatus
        )
    {
        uint numOfMarkets = _tradeData.length;
        amountsToBuy = new uint[](numOfMarkets);
        uint maxSupportedOdds = _p._riskManager.maxSupportedOdds();
        bool isSystemBet = _systemBetDenominator > 1;

        for (uint i; i < numOfMarkets; ++i) {
            ISportsAMMV2.TradeData memory marketTradeData = _tradeData[i];

            _p._riskManager.verifyMerkleTree(marketTradeData, _p._amm.rootPerGame(marketTradeData.gameId));

            if (marketTradeData.odds.length <= marketTradeData.position) revert InvalidPosition();

            uint marketOdds = marketTradeData.odds[marketTradeData.position];
            marketOdds =
                (marketOdds * ONE) /
                ((ONE + _p._addedPayoutPercentage) - _mulWithDecimals(_p._addedPayoutPercentage, marketOdds));

            amountsToBuy[i] = _divWithDecimals(_q._buyInAmount, marketOdds) - _q._buyInAmount;
            if (isSystemBet) {
                amountsToBuy[i] = (amountsToBuy[i] * ONE * _systemBetDenominator) / (numOfMarkets * ONE);
            }
            totalQuote = totalQuote == 0 ? marketOdds : _mulWithDecimals(totalQuote, marketOdds);
        }
        if (totalQuote != 0) {
            if (isSystemBet) {
                (payout, totalQuote) = _p._riskManager.getMaxSystemBetPayout(
                    _tradeData,
                    _systemBetDenominator,
                    _q._buyInAmount,
                    _p._addedPayoutPercentage
                );
            } else {
                if (_q._isSGP) {
                    totalQuote = _q._approvedQuote;
                    totalQuote =
                        (totalQuote * ONE) /
                        ((ONE + _p._addedPayoutPercentage) - _mulWithDecimals(_p._addedPayoutPercentage, totalQuote));
                }
                payout = _divWithDecimals(_q._buyInAmount, totalQuote);
            }
            if (totalQuote < maxSupportedOdds) {
                totalQuote = maxSupportedOdds;
                payout = _divWithDecimals(_q._buyInAmount, totalQuote);
            }

            fees = (_q._buyInAmount * _p._safeBoxFee) / ONE;

            if (_q._shouldCheckRisks) {
                bool[] memory isMarketOutOfLiquidity;
                (riskStatus, isMarketOutOfLiquidity) = _p._riskManager.checkRisks(
                    _tradeData,
                    _q._buyInAmountInDefaultCollateral,
                    _q._isLive,
                    _systemBetDenominator
                );

                unchecked {
                    for (uint i; i < numOfMarkets; ++i) {
                        if (isMarketOutOfLiquidity[i]) amountsToBuy[i] = 0;
                    }
                }

                if (riskStatus != ISportsAMMV2RiskManager.RiskStatus.NoRisk) {
                    totalQuote = payout = 0;
                }
            }
        }
    }

    function _transformToUSD(
        uint _amountInCollateral,
        uint _collateralPriceInUSD,
        uint _collateralDecimals,
        uint _defaultCollateralDecimals
    ) internal pure returns (uint amountInUSD) {
        amountInUSD = _mulWithDecimals(_amountInCollateral, _collateralPriceInUSD);
        if (_collateralDecimals < _defaultCollateralDecimals) {
            amountInUSD = amountInUSD * 10 ** (_defaultCollateralDecimals - _collateralDecimals);
        } else if (_collateralDecimals > _defaultCollateralDecimals) {
            amountInUSD = amountInUSD / 10 ** (_collateralDecimals - _defaultCollateralDecimals);
        }
    }

    struct FeeResult {
        uint fees;
        uint referrerShare;
        uint safeBoxAmount;
        address referrer;
        address safeBoxTarget;
    }

    /// @notice Computes fee distribution: referrer share and safe box amount
    /// @param _buyInAmount buy-in amount
    /// @param _ticketOwner ticket owner address
    /// @param _ammBalance current AMM balance of the collateral
    /// @param _safeBoxFee safe box fee rate
    /// @param _freeBetsHolder free bets holder address
    /// @param _safeBox default safe box address
    /// @param _safeBoxPerCollateral per-collateral safe box override (address(0) for default)
    /// @param _referrals referrals contract
    /// @return result fee result with amounts and target addresses for transfers
    function calculateFees(
        uint _buyInAmount,
        address _ticketOwner,
        uint _ammBalance,
        uint _safeBoxFee,
        address _freeBetsHolder,
        address _safeBox,
        address _safeBoxPerCollateral,
        IReferrals _referrals
    ) external view returns (FeeResult memory result) {
        result.referrer = _referrals.sportReferrals(_ticketOwner);
        uint referrerShare;

        if (result.referrer != address(0) && _ticketOwner != _freeBetsHolder) {
            uint referrerFeeByTier = _referrals.getReferrerFee(result.referrer);
            if (referrerFeeByTier > 0) {
                referrerShare = _mulWithDecimals(_buyInAmount, referrerFeeByTier);
                if (_ammBalance >= referrerShare) {
                    result.referrerShare = referrerShare;
                    _ammBalance -= referrerShare;
                }
            }
        }

        result.fees = (_buyInAmount * _safeBoxFee) / ONE;
        if (result.fees > referrerShare) {
            uint safeBoxAmount = result.fees - referrerShare;
            if (_ammBalance >= safeBoxAmount) {
                result.safeBoxAmount = safeBoxAmount;
                result.safeBoxTarget = _safeBoxPerCollateral != address(0) ? _safeBoxPerCollateral : _safeBox;
            }
        }
    }

    function checkTradeLimits(
        address _requester,
        uint _buyInAmount,
        address _collateral,
        uint _expectedQuote,
        uint _ticketSize,
        ISportsAMMV2 _sportsAMM
    ) external view {
        ISportsAMMV2RiskManager riskManager = _sportsAMM.riskManager();

        if (_expectedQuote < riskManager.maxSupportedOdds()) revert ExceededMaxOdds();
        if (_ticketSize > riskManager.maxTicketSize()) revert ExceededMaxSize();

        address defaultCollateral = address(_sportsAMM.defaultCollateral());
        address buyInCollateral = _collateral == address(0) ? defaultCollateral : _collateral;

        if (IERC20(buyInCollateral).allowance(_requester, address(_sportsAMM)) < _buyInAmount)
            revert InsufficientAllowance();
        if (IERC20(buyInCollateral).balanceOf(_requester) < _buyInAmount) revert InsufficientBalance();

        uint buyInAmountUSD;

        if (_collateral == address(0) || _collateral == defaultCollateral) {
            // Default collateral path (including address(0) case)
            buyInAmountUSD = _buyInAmount;
        } else {
            // Non-default collateral path

            // Check if direct liquidity pool exists for collateral
            address lqPool = _sportsAMM.liquidityPoolForCollateral(_collateral);
            if (lqPool != address(0)) {
                uint collateralPriceInUSD = ISportsAMMV2LiquidityPool(lqPool).getCollateralPrice();
                if (collateralPriceInUSD == 0) revert LpCollateralPriceZero();

                buyInAmountUSD = _transformToUSD(
                    _buyInAmount,
                    collateralPriceInUSD,
                    ISportsAMMV2Manager(_collateral).decimals(),
                    ISportsAMMV2Manager(defaultCollateral).decimals()
                );
            } else {
                // onramping path
                IMultiCollateralOnOffRamp multiCollateralOnOffRamp = _sportsAMM.multiCollateralOnOffRamp();
                if (address(multiCollateralOnOffRamp) == address(0)) revert OnRampNotSupported();
                if (!IViewMultiCollateralOnOffRamp(address(multiCollateralOnOffRamp)).collateralSupported(_collateral))
                    revert CollateralNotSupported();

                buyInAmountUSD = multiCollateralOnOffRamp.getMinimumReceived(_collateral, _buyInAmount);
            }
        }

        if (buyInAmountUSD < riskManager.minBuyInAmount()) revert LowBuyIn();
    }

    /* ========== PURE MATH HELPERS ========== */

    /// @notice Divides with 18-decimal precision: (ONE * _dividend) / _divisor
    function divWithDecimals(uint _dividend, uint _divisor) external pure returns (uint) {
        return _divWithDecimals(_dividend, _divisor);
    }

    /// @notice Multiplies with 18-decimal precision: (_firstMul * _secondMul) / ONE
    function mulWithDecimals(uint _firstMul, uint _secondMul) external pure returns (uint) {
        return _mulWithDecimals(_firstMul, _secondMul);
    }

    /// @notice Applies bonus payout percentage to an odd: odd / ((1 + a) - a * odd)
    function applyBonusToOdd(uint odd, uint addedPayoutPercentage) external pure returns (uint) {
        return _applyBonusToOdd(odd, addedPayoutPercentage);
    }

    /// @notice Returns the absolute difference between two uints
    function absDiff(uint a, uint b) external pure returns (uint) {
        return _absDiff(a, b);
    }

    /// @notice Calculates fees: (_buyInAmount * _safeBoxFee) / ONE
    function getFees(uint _buyInAmount, uint _safeBoxFee) external pure returns (uint) {
        return (_buyInAmount * _safeBoxFee) / ONE;
    }

    function _divWithDecimals(uint _dividend, uint _divisor) private pure returns (uint) {
        return (ONE * _dividend) / _divisor;
    }

    function _mulWithDecimals(uint _firstMul, uint _secondMul) private pure returns (uint) {
        return (_firstMul * _secondMul) / ONE;
    }

    function _applyBonusToOdd(uint odd, uint addedPayoutPercentage) private pure returns (uint) {
        return (odd * ONE) / ((ONE + addedPayoutPercentage) - _mulWithDecimals(addedPayoutPercentage, odd));
    }

    function _absDiff(uint a, uint b) private pure returns (uint) {
        return a >= b ? (a - b) : (b - a);
    }
}

contracts/core/AMM/Ticket.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
// internal
import "../../interfaces/ISportsAMMV2Manager.sol";
import "../../interfaces/ISportsAMMV2.sol";

contract Ticket {
    using SafeERC20 for IERC20;
    uint private constant ONE = 1e18;

    enum Phase {
        Trading,
        Maturity,
        Expiry
    }

    struct MarketData {
        bytes32 gameId;
        uint16 sportId;
        uint16 typeId;
        uint maturity;
        uint8 status;
        int24 line;
        uint24 playerId;
        uint8 position;
        uint odd;
        ISportsAMMV2.CombinedPosition[] combinedPositions;
    }

    struct TicketInit {
        MarketData[] _markets;
        uint _buyInAmount;
        uint _fees;
        uint _totalQuote;
        address _sportsAMM;
        address _ticketOwner;
        IERC20 _collateral;
        uint _expiry;
        bool _isLive;
        uint8 _systemBetDenominator;
        bool _isSGP;
    }

    ISportsAMMV2 public sportsAMM;
    address public ticketOwner;
    IERC20 public collateral;

    uint public buyInAmount;
    uint public fees;
    uint public totalQuote;
    uint public numOfMarkets;
    uint public expiry;
    uint public createdAt;

    bool public resolved;
    bool public paused;
    bool public initialized;
    bool public cancelled;

    bool public isLive;

    mapping(uint => MarketData) public markets;

    uint public finalPayout;

    bool public isSystem;

    uint8 public systemBetDenominator;

    bool public isSGP;

    bool public isMarkedAsLost;

    uint public expectedFinalPayout;

    bool public cashedOut;
    uint public cashoutPayout;

    /// @notice True for default-round (cross-round) tickets using deferred collateralization.
    ///         Set by AMM at creation; immutable after that.
    bool public isDeferred;

    // Snapshot of approved cashout odds at the moment of cashout
    mapping(uint => uint) private cashoutOddsPerLeg;

    // Whether the leg was already settled when cashout happened
    mapping(uint => bool) private cashoutWasSettledPerLeg;

    /* ========== CONSTRUCTOR and INITIALIZERS========== */

    /// @notice initialize the ticket contract
    /// @param params all parameters for Init
    function initialize(TicketInit calldata params) external {
        require(!initialized, "Ticket already initialized");
        initialized = true;
        sportsAMM = ISportsAMMV2(params._sportsAMM);
        numOfMarkets = params._markets.length;
        for (uint i = 0; i < numOfMarkets; i++) {
            markets[i] = params._markets[i];
        }
        buyInAmount = params._buyInAmount;
        fees = params._fees;
        totalQuote = params._totalQuote;
        ticketOwner = params._ticketOwner;
        collateral = params._collateral;
        expiry = params._expiry;
        isLive = params._isLive;
        createdAt = block.timestamp;
        systemBetDenominator = params._systemBetDenominator;
        isSystem = systemBetDenominator > 0;
        isSGP = params._isSGP;
    }

    /**
     * @notice Sets the expected final payout amount for this ticket.
     * @dev
     * - Can only be called by the SportsAMM contract.
     * - This value represents the total amount of collateral (including fees)
     *   that was initially funded to the ticket upon creation.
     * - Used later in `exercise()` to prevent manipulation or overfunding attacks,
     *   ensuring payout calculations rely only on the original committed collateral
     *   and not on the current token balance of the contract.
     * - Once set, this value should remain constant throughout the ticket lifecycle.
     *
     * @param amount The total expected collateral amount that should be held by this ticket.
     *               Must include both user buy-in and fees.
     *
     * Emits a {ExpectedFinalPayoutSet} event.
     */
    function setExpectedFinalPayout(uint amount) external onlyAMM {
        expectedFinalPayout = amount;
        emit ExpectedFinalPayoutSet(amount);
    }

    /// @notice Mark this ticket as deferred (default-round, no upfront LP collateral).
    /// @dev Called once by the AMM immediately after commitTradeDeferred.
    function setIsDeferred() external onlyAMM {
        isDeferred = true;
    }

    /* ========== EXTERNAL READ FUNCTIONS ========== */

    /// @notice checks if the user lost the ticket
    /// @return isTicketLost true/false
    function isTicketLost() public view returns (bool) {
        if (isMarkedAsLost) {
            return true;
        } else {
            uint lostMarketsCount = 0;
            for (uint i = 0; i < numOfMarkets; i++) {
                (bool isMarketResolved, bool isWinningMarketPosition) = sportsAMM
                    .resultManager()
                    .isMarketResolvedAndPositionWinning(
                        markets[i].gameId,
                        markets[i].typeId,
                        markets[i].playerId,
                        markets[i].line,
                        markets[i].position,
                        markets[i].combinedPositions
                    );
                if (isMarketResolved && !isWinningMarketPosition) {
                    if (!isSystem) {
                        return true;
                    } else {
                        lostMarketsCount++;
                        if (lostMarketsCount > (numOfMarkets - systemBetDenominator)) {
                            return true;
                        }
                    }
                }
            }
            return false;
        }
    }

    /// @notice checks are all markets of the ticket resolved
    /// @return areAllMarketsResolved true/false
    function areAllMarketsResolved() public view returns (bool) {
        for (uint i = 0; i < numOfMarkets; i++) {
            if (
                !sportsAMM.resultManager().isMarketResolved(
                    markets[i].gameId,
                    markets[i].typeId,
                    markets[i].playerId,
                    markets[i].line,
                    markets[i].combinedPositions
                )
            ) {
                return false;
            }
        }
        return true;
    }

    /**
     * @notice Returns whether a specific leg (market) of this ticket is resolved onchain.
     * @dev
     * - Uses the SportsAMM ResultManager as the source of truth.
     * - Intended for cashout flows where slippage checks should apply only to
     *   legs that are still pending (unresolved).
     * - Reverts if `_marketIndex` is out of bounds.
     *
     * @param _marketIndex Index of the leg/market in this ticket (0..numOfMarkets-1).
     * @return isResolved True if the underlying market is resolved, false otherwise.
     */
    function isLegResolved(uint _marketIndex) external view returns (bool isResolved) {
        require(_marketIndex < numOfMarkets, "Invalid market index");

        MarketData memory m = markets[_marketIndex];

        isResolved = sportsAMM.resultManager().isMarketResolved(m.gameId, m.typeId, m.playerId, m.line, m.combinedPositions);
    }

    /**
     * @notice Returns whether a specific leg of the ticket is voided (cancelled).
     * @dev Queries the ResultManager for cancellation status of the leg’s market position.
     *      Reverts if `_marketIndex` is out of bounds.
     * @param _marketIndex Index of the leg (0..numOfMarkets-1).
     * @return True if the leg is cancelled/voided, false otherwise.
     */
    function isLegVoided(uint _marketIndex) external view returns (bool) {
        require(_marketIndex < numOfMarkets, "Invalid market index");
        MarketData memory m = markets[_marketIndex];
        return
            sportsAMM.resultManager().isCancelledMarketPosition(
                m.gameId,
                m.typeId,
                m.playerId,
                m.line,
                m.position,
                m.combinedPositions
            );
    }

    /**
     * @notice Returns the stored odd for a given leg (market) on this ticket.
     * @dev Safer than relying on the autogenerated mapping getter because MarketData contains a dynamic array.
     * @param _marketIndex Index of the leg/market in this ticket (0..numOfMarkets-1).
     * @return odd Stored odd (18 decimals implied probability).
     */
    function getMarketOdd(uint _marketIndex) external view returns (uint odd) {
        require(_marketIndex < numOfMarkets, "Invalid market index");
        return markets[_marketIndex].odd;
    }

    /// @notice checks if the user won the ticket
    /// @return hasUserWon true/false
    function isUserTheWinner() external view returns (bool hasUserWon) {
        hasUserWon = _isUserTheWinner();
    }

    /// @notice checks if the ticket ready to be exercised
    /// @return isExercisable true/false
    function isTicketExercisable() public view returns (bool isExercisable) {
        isExercisable = !resolved && (areAllMarketsResolved() || isTicketLost());
    }

    /// @notice gets current phase of the ticket
    /// @return phase ticket phase
    function phase() public view returns (Phase) {
        return
            isTicketExercisable() || resolved ? ((expiry < block.timestamp) ? Phase.Expiry : Phase.Maturity) : Phase.Trading;
    }

    /// @notice gets combined positions of the game
    /// @return combinedPositions game combined positions
    function getCombinedPositions(
        uint _marketIndex
    ) public view returns (ISportsAMMV2.CombinedPosition[] memory combinedPositions) {
        return markets[_marketIndex].combinedPositions;
    }

    /// @notice return the payout for this ticket
    /// @return systemBetPayout the payout for this ticket
    function getSystemBetPayout() external view returns (uint systemBetPayout) {
        systemBetPayout = _getSystemBetPayout();
    }

    /**
     * @notice Computes the cashout quote, payout after fee, and fee amount.
     * @dev Uses `approvedOddsPerLeg` for pending legs and stored odds for settled
     *      (or 1 for voided) legs. Applies cashout fee as
     *      `safeBoxFee * cashoutFeeMultiplier`.
     * @param approvedOddsPerLeg Approved per-leg implied probabilities (1e18).
     * @param isLegSettled Flags indicating whether each leg is settled.
     * @return cashoutQuote Combined implied probability for cashout.
     * @return payoutAfterFee Cashout payout after fee deduction.
     */
    function getCashoutQuoteAndPayout(
        uint[] calldata approvedOddsPerLeg,
        bool[] calldata isLegSettled
    ) external view returns (uint cashoutQuote, uint payoutAfterFee) {
        uint legs = numOfMarkets;
        require(approvedOddsPerLeg.length == legs && isLegSettled.length == legs, "Invalid leg arrays length");

        (uint origProbTotal, uint liveProbTotal, uint remainingLegs, bool cashoutable) = _cashoutProbTotals(
            approvedOddsPerLeg,
            isLegSettled
        );

        if (!cashoutable || origProbTotal == 0) {
            return (0, 0);
        }

        // 1) Fair cashout multiplier (before vig): ratio = live/orig
        uint ratio = (liveProbTotal * ONE) / origProbTotal; // 1e18

        // 2) Compound vig: keepMultiplier = (1 - v)^n
        uint keepMultiplier = _cashoutKeepMultiplier(remainingLegs);

        cashoutQuote = (ratio * keepMultiplier) / ONE; // 1e18
        payoutAfterFee = (buyInAmount * cashoutQuote) / ONE;
    }

    /**
     * @notice Returns stored cashout data for all legs.
     * @return approvedOddsPerLeg Approved odds used for each leg during cashout
     * @return wasSettledPerLeg Whether each leg was settled at the time of cashout
     */
    function getCashoutPerLegData()
        external
        view
        returns (uint[] memory approvedOddsPerLeg, bool[] memory wasSettledPerLeg)
    {
        require(cashedOut, "Ticket not cashed out");

        uint legs = numOfMarkets;

        approvedOddsPerLeg = new uint[](legs);
        wasSettledPerLeg = new bool[](legs);

        for (uint i; i < legs; ++i) {
            approvedOddsPerLeg[i] = cashoutOddsPerLeg[i];
            wasSettledPerLeg[i] = cashoutWasSettledPerLeg[i];
        }
    }

    function _cashoutProbTotals(
        uint[] calldata approvedOddsPerLeg,
        bool[] calldata isLegSettled
    ) internal view returns (uint origProbTotal, uint liveProbTotal, uint remainingLegs, bool cashoutable) {
        uint legs = numOfMarkets;

        origProbTotal = ONE;
        liveProbTotal = ONE;
        remainingLegs = 0;

        ISportsAMMV2ResultManager resultManager = sportsAMM.resultManager();

        for (uint i = 0; i < legs; ++i) {
            MarketData memory m = markets[i];

            bool cancelledPos = resultManager.isCancelledMarketPosition(
                m.gameId,
                m.typeId,
                m.playerId,
                m.line,
                m.position,
                m.combinedPositions
            );

            bool resolvedMarket = resultManager.isMarketResolved(
                m.gameId,
                m.typeId,
                m.playerId,
                m.line,
                m.combinedPositions
            );

            // Settled = resolved OR cancelled
            require(isLegSettled[i] == (resolvedMarket || cancelledPos), "Invalid isLegSettled");

            // -------- ORIGINAL contribution (void legs omitted) --------
            uint origLegProb = cancelledPos ? ONE : m.odd;
            require(origLegProb > 0, "Invalid stored odd");
            origProbTotal = (origProbTotal * origLegProb) / ONE;

            // -------- LIVE contribution --------
            uint liveLegProb;

            if (cancelledPos) {
                // voided leg omitted from remaining risk
                liveLegProb = ONE;
            } else if (resolvedMarket) {
                // resolved: if losing -> not cashoutable
                bool isWinning = resultManager.isWinningMarketPosition(
                    m.gameId,
                    m.typeId,
                    m.playerId,
                    m.line,
                    m.position,
                    m.combinedPositions
                );

                if (!isWinning) {
                    return (0, 0, 0, false);
                }

                // already won leg => omitted from remaining risk
                liveLegProb = ONE;
            } else {
                // pending leg => live approved prob
                liveLegProb = approvedOddsPerLeg[i];
                require(liveLegProb > 0, "Invalid approved odd");
                remainingLegs++;
            }

            liveProbTotal = (liveProbTotal * liveLegProb) / ONE;
        }

        cashoutable = true;
    }

    function _cashoutKeepMultiplier(uint remainingLegs) internal view returns (uint keepMultiplier) {
        uint safeBoxFee = sportsAMM.safeBoxFee(); // 1e18 fraction (e.g. 0.01e18)
        uint multiplier = sportsAMM.riskManager().getCashoutSafeBoxFeeMultiplier(); // e.g. 5
        uint perLegVig = safeBoxFee * multiplier; // 1e18 fraction (e.g. 0.05e18)
        require(perLegVig < ONE, "Invalid vig");

        uint oneMinusV = ONE - perLegVig;

        keepMultiplier = ONE;
        for (uint k = 0; k < remainingLegs + 1; ++k) {
            keepMultiplier = (keepMultiplier * oneMinusV) / ONE;
        }
    }

    /* ========== EXTERNAL WRITE FUNCTIONS ========== */

    /// @notice exercise ticket
    function exercise(address _exerciseCollateral) external onlyAMM notPaused returns (uint) {
        bool isExercisable = isTicketExercisable();
        require(isExercisable, "Ticket not exercisable yet");
        require(expectedFinalPayout > 0, "Expected final payout not set");

        uint payoutWithFees = expectedFinalPayout;
        uint payout = payoutWithFees - fees;
        bool isCancelled = false;

        ISportsAMMV2ResultManager resultManager = sportsAMM.resultManager();

        if (_isUserTheWinner()) {
            finalPayout = payout;
            isCancelled = true;
            for (uint i = 0; i < numOfMarkets; i++) {
                bool isCancelledMarketPosition = resultManager.isCancelledMarketPosition(
                    markets[i].gameId,
                    markets[i].typeId,
                    markets[i].playerId,
                    markets[i].line,
                    markets[i].position,
                    markets[i].combinedPositions
                );
                if (isCancelledMarketPosition) {
                    if (isSGP) {
                        isCancelled = true;
                        break;
                    }
                    finalPayout = (finalPayout * markets[i].odd) / ONE;
                } else {
                    isCancelled = false;
                }
            }

            finalPayout = isCancelled ? buyInAmount : (isSystem ? _getSystemBetPayout() : finalPayout);

            // Only transfer if non-deferred ticket
            if (!isDeferred) {
                collateral.safeTransfer(
                    _exerciseCollateral == address(0) || _exerciseCollateral == address(collateral)
                        ? address(ticketOwner)
                        : address(sportsAMM),
                    finalPayout
                );
            }
        }

        // Send any remaining ticket balance to AMM
        uint balance = collateral.balanceOf(address(this));
        if (balance != 0) {
            collateral.safeTransfer(address(sportsAMM), balance);
        }

        _resolve(!isTicketLost(), isCancelled);
        return finalPayout;
    }

    /// @notice cash out the ticket for a given amount (amount is computed/validated in AMM)
    /// @dev callable only by AMM; resolves the ticket immediately
    function cashout(uint _cashoutAmount, address _recipient) external onlyAMM notPaused returns (uint) {
        require(!resolved, "Ticket already resolved");
        require(_cashoutAmount > 0, "Invalid cashout amount");
        require(_recipient != address(0), "Invalid recipient");
        require(expectedFinalPayout > 0, "Expected final payout not set");
        require(phase() == Phase.Trading, "Not in trading phase");
        require(!isSystem && !isSGP, "Not possible for System bets or SGPs");
        require(block.timestamp >= createdAt + sportsAMM.riskManager().getCashoutCooldown(), "Not possible during cooldown");

        // Hard rule: cannot cashout if already lost (same as AMM check, defense-in-depth)
        require(!isTicketLost(), "Ticket lost");

        // Cap: don't allow paying more than max user payout (expectedFinalPayout includes fees)
        uint cap = expectedFinalPayout > fees ? (expectedFinalPayout - fees) : 0;
        require(_cashoutAmount <= cap, "Cashout exceeds cap");

        cashoutPayout = _cashoutAmount;
        finalPayout = _cashoutAmount;
        cashedOut = true;

        // Only transfer if non-deferred ticket
        if (!isDeferred) {
            // Pay user
            collateral.safeTransfer(_recipient, _cashoutAmount);
        }

        // Send remainder back to AMM (same behavior as exercise/cancel)
        uint balance = collateral.balanceOf(address(this));
        if (balance != 0) {
            collateral.safeTransfer(address(sportsAMM), balance);
        }

        // Resolve as "not cancelled" (cashout is its own thing)
        _resolve(true, false);

        emit CashedOut(_recipient, _cashoutAmount);

        return _cashoutAmount;
    }

    /**
     * @notice Stores the approved cashout odds and settled flags per leg.
     * @dev Callable only by AMM. Intended to be called immediately before successful cashout.
     * @param _approvedOddsPerLeg Approved cashout odds per leg.
     * @param _isLegSettled Whether each leg was settled at cashout time.
     */
    function setCashoutPerLegData(
        uint[] calldata _approvedOddsPerLeg,
        bool[] calldata _isLegSettled
    ) external onlyAMM notPaused {
        require(!resolved, "Ticket already resolved");

        uint legs = numOfMarkets;
        require(_approvedOddsPerLeg.length == legs, "Invalid approved odds length");
        require(_isLegSettled.length == legs, "Invalid settled flags length");

        for (uint i = 0; i < legs; ++i) {
            cashoutOddsPerLeg[i] = _approvedOddsPerLeg[i];
            cashoutWasSettledPerLeg[i] = _isLegSettled[i];
        }
    }

    /// @notice expire ticket
    function expire(address _beneficiary) external onlyAMM {
        require(phase() == Phase.Expiry, "Ticket not in expiry phase");
        require(!resolved, "Can't expire resolved ticket");
        emit Expired(_beneficiary);
        _selfDestruct(_beneficiary);
    }

    /// @notice cancel the ticket
    function cancel() external onlyAMM notPaused returns (uint) {
        finalPayout = buyInAmount;

        // Only transfer if non-deferred ticket
        if (!isDeferred) {
            collateral.safeTransfer(address(ticketOwner), finalPayout);
        }

        uint balance = collateral.balanceOf(address(this));
        if (balance != 0) {
            collateral.safeTransfer(address(sportsAMM), balance);
        }

        _resolve(true, true);
        return finalPayout;
    }

    /// @notice mark the ticket as lost
    function markAsLost() external onlyAMM notPaused returns (uint) {
        uint balance = collateral.balanceOf(address(this));
        if (balance != 0) {
            collateral.safeTransfer(address(sportsAMM), balance);
        }

        _resolve(false, false);
        isMarkedAsLost = true;
        return 0;
    }

    /// @notice withdraw collateral from the ticket
    function withdrawCollateral(address recipient) external onlyAMM {
        collateral.safeTransfer(recipient, collateral.balanceOf(address(this)));
    }

    /* ========== INTERNAL FUNCTIONS ========== */

    function _resolve(bool _hasUserWon, bool _cancelled) internal {
        resolved = true;
        cancelled = _cancelled;
        emit Resolved(_hasUserWon, _cancelled);
    }

    function _selfDestruct(address beneficiary) internal {
        uint balance = collateral.balanceOf(address(this));
        if (balance != 0) {
            collateral.safeTransfer(beneficiary, balance);
        }
    }

    function _isUserTheWinner() internal view returns (bool hasUserWon) {
        if (areAllMarketsResolved()) {
            hasUserWon = !isTicketLost();
        }
    }

    /* ========== SETTERS ========== */

    function setPaused(bool _paused) external {
        require(msg.sender == address(sportsAMM.manager()), "Invalid sender");
        if (paused == _paused) return;
        paused = _paused;
        emit PauseUpdated(_paused);
    }

    /* ========== SYSTEM BET UTILS ========== */

    function _getSystemBetPayout() internal view returns (uint systemBetPayout) {
        if (isSystem) {
            uint8[][] memory systemCombinations = sportsAMM.riskManager().generateCombinations(
                uint8(numOfMarkets),
                systemBetDenominator
            );
            uint totalCombinations = systemCombinations.length;
            uint buyinPerCombination = ((buyInAmount * ONE) / totalCombinations) / ONE;

            bool[] memory winningMarkets = new bool[](numOfMarkets);
            bool[] memory cancelledMarkets = new bool[](numOfMarkets);

            for (uint i = 0; i < numOfMarkets; i++) {
                if (
                    !sportsAMM.resultManager().isMarketResolved(
                        markets[i].gameId,
                        markets[i].typeId,
                        markets[i].playerId,
                        markets[i].line,
                        markets[i].combinedPositions
                    )
                ) {
                    return 0;
                }
                winningMarkets[i] = sportsAMM.resultManager().isWinningMarketPosition(
                    markets[i].gameId,
                    markets[i].typeId,
                    markets[i].playerId,
                    markets[i].line,
                    markets[i].position,
                    markets[i].combinedPositions
                );

                cancelledMarkets[i] = sportsAMM.resultManager().isCancelledMarketPosition(
                    markets[i].gameId,
                    markets[i].typeId,
                    markets[i].playerId,
                    markets[i].line,
                    markets[i].position,
                    markets[i].combinedPositions
                );
            }

            // Loop through each stored combination
            for (uint i = 0; i < totalCombinations; i++) {
                uint8[] memory currentCombination = systemCombinations[i];

                uint combinationQuote = ONE;

                for (uint j = 0; j < currentCombination.length; j++) {
                    uint8 marketIndex = currentCombination[j];
                    if (winningMarkets[marketIndex]) {
                        if (!cancelledMarkets[marketIndex]) {
                            combinationQuote = (combinationQuote * markets[marketIndex].odd) / ONE;
                        }
                    } else {
                        combinationQuote = 0;
                        break;
                    }
                }

                if (combinationQuote > 0) {
                    uint combinationPayout = (buyinPerCombination * ONE) / combinationQuote;
                    systemBetPayout += combinationPayout;
                }
            }

            uint maxPayout = (buyInAmount * ONE) / totalQuote;
            if (systemBetPayout > maxPayout) {
                systemBetPayout = maxPayout;
            }
        }
    }

    /* ========== MODIFIERS ========== */

    modifier onlyAMM() {
        require(msg.sender == address(sportsAMM), "Only the AMM may perform these methods");
        _;
    }

    modifier notPaused() {
        require(!paused, "Market paused");
        _;
    }

    /* ========== EVENTS ========== */

    event Resolved(bool isUserTheWinner, bool cancelled);
    event Expired(address beneficiary);
    event PauseUpdated(bool paused);
    event ExpectedFinalPayoutSet(uint amount);
    event CashedOut(address recipient, uint amount);
}

