contracts/core/Cashout/CashoutProcessor..content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

// external
import "@chainlink/contracts/src/v0.8/ChainlinkClient.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/Strings.sol";

// internal
import "../../interfaces/ISportsAMMV2.sol";
import "../../interfaces/ISportsAMMV2Manager.sol";
import "../../core/AMM/Ticket.sol";

/**
 * @title CashoutProcessor
 * @notice Chainlink-powered cashout gatekeeper for SportsAMMV2 tickets using per-leg odds.
 * @dev
 * High-level flow:
 * 1) User calls {requestCashout} supplying:
 *    - `expectedOddsPerLeg`: user-expected implied probabilities per leg (18 decimals).
 *    - `isLegResolved`: user-asserted resolved/pending flags per leg.
 *    - `additionalSlippage`: max allowed decrease vs expected odds for *pending* legs (18-decimal percentage).
 * 2) Contract validates the ticket is cashout-eligible and that the user did not lie about leg status / settled odds.
 * 3) Contract submits a Chainlink request to an offchain adapter to compute `approvedOddsPerLeg` and an allow/deny flag.
 * 4) Oracle calls {fulfillCashout}:
 *    - re-checks leg status / settled odds again (defense-in-depth),
 *    - enforces per-leg slippage for pending legs,
 *    - then calls `sportsAMM.cashoutTicketWithLegOdds(...)` if allowed.
 *
 * Security model notes:
 * - Uses Chainlink's `recordChainlinkFulfillment` to restrict fulfill calls to the configured oracle + requestId.
 * - Reverts on `_allow=false` to avoid executing AMM cashout.
 * - Enforces a maximum oracle execution delay (`maxAllowedExecutionDelay`) to reduce stale quote risk.
 * - Stores request data to allow UIs and indexers to display the request/response details.
 */
contract CashoutProcessor is ChainlinkClient, Ownable, Pausable {
    using Chainlink for Chainlink.Request;
    using SafeERC20 for IERC20;

    /// @dev 18-decimal fixed-point scalar (also used as "1.0" for implied probability).
    uint private constant ONE = 1e18;

    /// @notice SportsAMM instance used to validate tickets and execute the cashout.
    ISportsAMMV2 public sportsAMM;

    /// @notice Chainlink job spec id used for the cashout quote adapter request.
    bytes32 public jobSpecId;

    /// @notice LINK payment amount for each request (in LINK smallest unit).
    uint public paymentAmount;

    /// @notice Max time (in seconds) allowed between request creation and fulfill execution.
    /// @dev Requests older than `timestampPerRequest + maxAllowedExecutionDelay` are rejected as stale.
    uint public maxAllowedExecutionDelay = 60;

    // ===== Requests =====

    /// @notice Maps requestId => ticket address.
    mapping(bytes32 => address) public requestIdToTicket;

    /// @notice Maps requestId => original requester (ticket owner) address.
    mapping(bytes32 => address) public requestIdToRequester;

    /// @notice Maps requestId => additionalSlippage passed by the requester.
    mapping(bytes32 => uint) public requestIdToAdditionalSlippage;

    /// @dev Maps requestId => expected odds per leg provided by the requester.
    mapping(bytes32 => uint[]) internal _requestIdToExpectedOddsPerLeg;

    /// @dev Maps requestId => resolved flags per leg provided by the requester.
    mapping(bytes32 => bool[]) internal _requestIdToIsLegResolved;

    /// @notice Maps requestId => timestamp at which request was stored (block.timestamp).
    mapping(bytes32 => uint) public timestampPerRequest;

    /// @notice True if request has been fulfilled already.
    mapping(bytes32 => bool) public requestIdFulfilled;

    /// @notice Oracle allow/deny decision per requestId (written in fulfill).
    mapping(bytes32 => bool) public requestIdToFulfillAllowed;

    /// @dev Maps requestId => approved odds per leg returned by oracle (stored for UI/debugging).
    mapping(bytes32 => uint[]) internal _requestIdToApprovedOddsPerLeg;

    /// @notice Monotonic counter for requests (useful for offchain indexing).
    uint public requestCounter;

    /// @notice Maps a sequential counter => requestId.
    mapping(uint => bytes32) public counterToRequestId;

    /// @notice Optional FreeBetsHolder address; tickets owned by this address are not cashoutable.
    address public freeBetsHolder;

    // ===== Errors =====

    /// @notice Request already fulfilled (replay protection).
    error RequestAlreadyFulfilled();

    /// @notice Request exceeded maxAllowedExecutionDelay.
    error RequestTimedOut();

    /// @notice Ticket address is invalid (e.g., zero address).
    error InvalidTicket();

    /// @notice Odds array invalid (e.g., empty or contains zeros where not allowed).
    error InvalidExpectedOdds();

    /// @notice Provided per-leg arrays lengths do not match.
    error InvalidLegArraysLength();

    /// @notice Oracle decided cashout is not allowed.
    error CashoutNotAllowed();

    /// @notice Caller is not the ticket owner.
    error NotOwner();

    /// @notice Ticket fails cashout eligibility checks.
    error TicketNotCashoutable();

    /// @notice User-provided resolved flags do not match onchain status.
    error LegStatusMismatch();

    /// @notice For settled legs, provided odd does not match ticket's stored odd (or ONE for voided legs).
    error SettledLegOddMismatch();

    /// @notice Approved odds exceed expected odds by more than allowed slippage for a pending leg.
    error SlippageTooHigh();

    /**
     * @notice Creates CashoutProcessor and sets initial Chainlink + SportsAMM configuration.
     * @param _link LINK token address for the current network.
     * @param _oracle Chainlink oracle address that will fulfill requests.
     * @param _sportsAMM SportsAMMV2 address that performs the cashout settlement.
     * @param _jobSpecId Chainlink job spec id for the offchain adapter.
     * @param _paymentAmount LINK amount to pay per request.
     */
    constructor(
        address _link,
        address _oracle,
        address _sportsAMM,
        bytes32 _jobSpecId,
        uint _paymentAmount
    ) Ownable(msg.sender) {
        setChainlinkToken(_link);
        setChainlinkOracle(_oracle);

        sportsAMM = ISportsAMMV2(_sportsAMM);
        jobSpecId = _jobSpecId;
        paymentAmount = _paymentAmount;
    }

    // ============================
    // Request
    // ============================

    /**
     * @notice Requests a cashout quote/approval from the Chainlink adapter for a given ticket.
     * @dev
     * Validations performed before sending the oracle request:
     * - Ticket must be non-zero address.
     * - Arrays must be non-empty and have matching lengths.
     * - Caller must be the ticket owner and ticket must be active and cashout-eligible.
     * - Caller must not misrepresent leg status:
     *   - For any leg that is already resolved onchain, `isLegResolved[i]` must be true.
     *   - For resolved legs, `expectedOddsPerLeg[i]` must match the ticket's settled odd
     *     (or ONE if the leg is voided).
     *
     * The oracle request includes per-leg market identifiers and user-provided expectations:
     * `gameIds`, `typeIds`, `playerIds`, `positions`, `lines`, `expectedOddsPerLeg`, `isLegResolved`,
     * plus `additionalSlippage` and `requester`.
     *
     * @param ticket Ticket contract address.
     * @param expectedOddsPerLeg User-expected implied probabilities per leg (18 decimals). Must be > 0 for all legs.
     * @param isLegResolved User-asserted resolved flags per leg (must match onchain `Ticket.isLegResolved(i)`).
     * @param additionalSlippage Max allowed decrease vs expected odds for pending legs (18-decimal percentage).
     * @return requestId The Chainlink request id for the created request.
     */
    function requestCashout(
        address ticket,
        uint[] calldata expectedOddsPerLeg,
        bool[] calldata isLegResolved,
        uint additionalSlippage
    ) external whenNotPaused returns (bytes32 requestId) {
        if (ticket == address(0)) revert InvalidTicket();

        uint legsLen = expectedOddsPerLeg.length;
        if (legsLen == 0) revert InvalidExpectedOdds();
        if (isLegResolved.length != legsLen) revert InvalidLegArraysLength();
        uint ticketLegs = Ticket(ticket).numOfMarkets();
        if (legsLen != ticketLegs) revert InvalidLegArraysLength();

        _assertTicketLooksCashoutable(ticket, msg.sender);

        _verifyLegStatusesAndSettledOdds(ticket, expectedOddsPerLeg, isLegResolved);

        Chainlink.Request memory req = buildChainlinkRequest(jobSpecId, address(this), this.fulfillCashout.selector);

        // Adapter expects arrays (build each array in a separate frame to avoid stack-too-deep)
        _addLegArraysToRequest(req, ticket, legsLen, expectedOddsPerLeg, isLegResolved);

        req.addUint("additionalSlippage", additionalSlippage);
        req.add("requester", Strings.toHexString(msg.sender));

        requestId = sendChainlinkRequest(req, paymentAmount);

        _storeRequest(requestId, ticket, msg.sender, additionalSlippage, expectedOddsPerLeg, isLegResolved);

        emit CashoutRequested(msg.sender, requestCounter, requestId, ticket, legsLen, additionalSlippage);
        requestCounter++;
    }

    // ============================
    // Fulfill
    // ============================

    /**
     * @notice Chainlink fulfillment entrypoint that approves/denies and finalizes a cashout.
     * @dev
     * Access control:
     * - Restricted by `recordChainlinkFulfillment(_requestId)` which enforces oracle + requestId validity.
     *
     * Safety checks:
     * - Reverts if request already fulfilled (replay protection).
     * - Reverts if request is stale (older than `maxAllowedExecutionDelay`).
     * - Reverts if returned odds array length mismatches the expected legs length.
     *
     * If `_allow` is false, it stores the result and reverts with {CashoutNotAllowed}.
     *
     * If `_allow` is true, it:
     * - Re-checks leg status/settled odds to ensure nothing changed vs the request snapshot.
     * - Enforces per-leg slippage for pending legs: `approvedOdd >= expectedOdd*(1-slippage)`.
     * - Calls `sportsAMM.cashoutTicketWithLegOdds(...)`.
     *
     * @param _requestId Chainlink request id.
     * @param _allow Whether cashout is approved by the oracle/adaptor.
     * @param _approvedOddsPerLeg Per-leg approved implied probabilities (18 decimals). Must match legs length.
     */
    function fulfillCashout(
        bytes32 _requestId,
        bool _allow,
        uint[] calldata _approvedOddsPerLeg
    ) external whenNotPaused recordChainlinkFulfillment(_requestId) {
        if (requestIdFulfilled[_requestId]) revert RequestAlreadyFulfilled();
        if ((timestampPerRequest[_requestId] + maxAllowedExecutionDelay) <= block.timestamp) revert RequestTimedOut();

        uint legsLen = _requestIdToExpectedOddsPerLeg[_requestId].length;
        if (legsLen == 0) revert InvalidExpectedOdds(); // safety (should never happen)
        if (_approvedOddsPerLeg.length != legsLen) revert InvalidLegArraysLength();

        // also ensure request arrays still match ticket legs
        address ticketAddr = requestIdToTicket[_requestId];
        uint ticketLegs = Ticket(ticketAddr).numOfMarkets();
        if (legsLen != ticketLegs) revert InvalidLegArraysLength();

        requestIdToFulfillAllowed[_requestId] = _allow;
        requestIdFulfilled[_requestId] = true;

        _requestIdToApprovedOddsPerLeg[_requestId] = _approvedOddsPerLeg;

        if (!_allow) revert CashoutNotAllowed();

        _verifyApprovedOddsAndPerLegSlippage(
            ticketAddr,
            _approvedOddsPerLeg,
            _requestIdToExpectedOddsPerLeg[_requestId],
            _requestIdToIsLegResolved[_requestId],
            requestIdToAdditionalSlippage[_requestId]
        );

        sportsAMM.cashoutTicketWithLegOdds(
            ticketAddr,
            _approvedOddsPerLeg,
            _requestIdToIsLegResolved[_requestId],
            requestIdToRequester[_requestId]
        );

        emit CashoutFulfilled(requestIdToRequester[_requestId], _requestId, ticketAddr, _allow, legsLen, block.timestamp);
    }

    // ============================
    // Internal Logic
    // ============================

    /**
     * @dev Persists request metadata and user-provided per-leg arrays for later verification and UI reads.
     * @param requestId Chainlink request id.
     * @param ticket Ticket address.
     * @param requester Original caller.
     * @param additionalSlippage User-provided additional slippage.
     * @param expectedOddsPerLeg User-provided expected odds per leg.
     * @param isLegResolved User-provided resolved flags per leg.
     */
    function _storeRequest(
        bytes32 requestId,
        address ticket,
        address requester,
        uint additionalSlippage,
        uint[] calldata expectedOddsPerLeg,
        bool[] calldata isLegResolved
    ) internal {
        timestampPerRequest[requestId] = block.timestamp;
        requestIdToTicket[requestId] = ticket;
        requestIdToRequester[requestId] = requester;
        requestIdToAdditionalSlippage[requestId] = additionalSlippage;

        _requestIdToExpectedOddsPerLeg[requestId] = expectedOddsPerLeg;
        _requestIdToIsLegResolved[requestId] = isLegResolved;

        counterToRequestId[requestCounter] = requestId;
    }

    /**
     * @dev Ensures ticket meets basic eligibility requirements for cashout.
     * @param ticketAddr Ticket contract address.
     * @param requester Address attempting to cashout (must be ticket owner).
     *
     * Reverts with:
     * - {NotOwner} if requester != ticketOwner.
     * - {TicketNotCashoutable} if ticket is inactive, resolved/lost/SGP/system-bet,
     *   owned by freeBetsHolder, manager marks it as not potentially cashoutable,
     *   or if the ticket odds exceed (or equal) RiskManager.maxSupportedOdds().
     */
    function _assertTicketLooksCashoutable(address ticketAddr, address requester) internal view {
        Ticket t = Ticket(ticketAddr);
        ISportsAMMV2Manager mgr = sportsAMM.manager();

        if (t.ticketOwner() != requester) revert NotOwner();
        if (!mgr.isActiveTicket(ticketAddr)) revert TicketNotCashoutable();

        if (
            t.resolved() ||
            t.isTicketLost() ||
            t.isSGP() ||
            t.systemBetDenominator() > 1 ||
            (freeBetsHolder != address(0) && requester == freeBetsHolder) ||
            !mgr.isTicketPotentiallyCashoutable(ticketAddr) ||
            t.totalQuote() <= sportsAMM.riskManager().maxSupportedOdds()
        ) revert TicketNotCashoutable();
    }

    /**
     * @dev Enforces oracle-approved odds validity, leg-status consistency, and per-leg slippage for pending legs.
     * @param ticketAddr Ticket contract address.
     * @param approved Oracle-approved odds per leg (18 decimals).
     * @param expected User-expected odds per leg (18 decimals).
     * @param isLegResolved User-asserted resolved flags per leg (must still match onchain status).
     * @param slippage Max allowed decrease vs expected for pending legs (18-decimal percentage).
     *
     * Rules per leg:
     * - `approvedOdd` and `expectedOdd` must be non-zero.
     * - Onchain resolved status must still equal `isLegResolved[i]`.
     * - If resolved: approved must match settled odd (or ONE if voided).
     * - If pending: `approvedOdd` must be >= `expectedOdd * (1 - slippage)`.
     */
    function _verifyApprovedOddsAndPerLegSlippage(
        address ticketAddr,
        uint[] calldata approved,
        uint[] memory expected,
        bool[] memory isLegResolved,
        uint slippage
    ) internal view {
        _verifyLegStatusesAndSettledOdds(ticketAddr, approved, isLegResolved);

        uint legs = approved.length;

        for (uint i = 0; i < legs; ++i) {
            uint expectedOdd = expected[i];
            if (expectedOdd == 0) revert InvalidExpectedOdds();

            if (!isLegResolved[i]) {
                uint minApproved = (expectedOdd * (ONE - slippage)) / ONE;
                if (approved[i] < minApproved) revert SlippageTooHigh();
            }
        }
    }

    /**
     * @dev Verifies per-leg resolved status and (if resolved) the settled odd against onchain Ticket data.
     *
     * Requirements per leg `i`:
     * - `odds[i]` must be non-zero.
     * - Onchain `Ticket.isLegResolved(i)` must equal `isLegResolved[i]` (prevents misreporting).
     * - If the leg is resolved:
     *   - if voided => `odds[i]` must equal ONE
     *   - else      => `odds[i]` must equal `Ticket.getMarketOdd(i)`
     *
     * Reverts with:
     * - {InvalidExpectedOdds} if any `odds[i] == 0`.
     * - {LegStatusMismatch} if provided status differs from onchain resolved status.
     * - {SettledLegOddMismatch} if a resolved leg's odd does not match the ticket's settled odd (or ONE for voided).
     *
     * @param ticketAddr Ticket contract address.
     * @param odds Per-leg odds to validate (expected odds during request, or approved odds during fulfill), 18 decimals.
     * @param isLegResolved User-provided resolved flags per leg; must match onchain `Ticket.isLegResolved(i)`.
     */
    function _verifyLegStatusesAndSettledOdds(
        address ticketAddr,
        uint[] memory odds,
        bool[] memory isLegResolved
    ) internal view {
        Ticket t = Ticket(ticketAddr);
        uint legs = odds.length;

        for (uint i = 0; i < legs; ++i) {
            uint odd = odds[i];
            if (odd == 0) revert InvalidExpectedOdds();

            bool resolved = t.isLegResolved(i);
            if (resolved != isLegResolved[i]) revert LegStatusMismatch();

            if (resolved) {
                if (t.isLegVoided(i)) {
                    if (odd != ONE) revert SettledLegOddMismatch();
                } else {
                    if (odd != t.getMarketOdd(i)) revert SettledLegOddMismatch();
                }
            }
        }
    }

    // ============================
    // Adapter array building (stack-safe)
    // ============================

    /**
     * @dev Adds all per-leg arrays required by the adapter to the Chainlink request.
     * @param req Chainlink request object (memory).
     * @param ticketAddr Ticket address.
     * @param legsLen Number of legs in the ticket.
     * @param expectedOddsPerLeg User-expected odds per leg.
     * @param isLegResolved User-asserted resolved flags per leg.
     */
    function _addLegArraysToRequest(
        Chainlink.Request memory req,
        address ticketAddr,
        uint legsLen,
        uint[] calldata expectedOddsPerLeg,
        bool[] calldata isLegResolved
    ) internal view {
        req.addStringArray("gameIds", _buildGameIds(ticketAddr, legsLen));
        req.addStringArray("typeIds", _buildTypeIds(ticketAddr, legsLen));
        req.addStringArray("playerIds", _buildPlayerIds(ticketAddr, legsLen));
        req.addStringArray("positions", _buildPositions(ticketAddr, legsLen));
        req.addStringArray("lines", _buildLines(ticketAddr, legsLen));
        req.addStringArray("expectedOddsPerLeg", _buildExpectedOdds(expectedOddsPerLeg, legsLen));
        req.addStringArray("isLegResolved", _buildIsResolved(isLegResolved, legsLen));
    }

    /// @dev Builds hex-encoded bytes32 gameIds for each leg.
    function _buildGameIds(address ticketAddr, uint legsLen) internal view returns (string[] memory out) {
        Ticket t = Ticket(ticketAddr);
        out = new string[](legsLen);
        for (uint i = 0; i < legsLen; ++i) {
            (bytes32 gid, , , , , , , , ) = t.markets(i);
            out[i] = Strings.toHexString(uint256(gid), 32);
        }
    }

    /// @dev Builds decimal-encoded typeIds for each leg.
    function _buildTypeIds(address ticketAddr, uint legsLen) internal view returns (string[] memory out) {
        Ticket t = Ticket(ticketAddr);
        out = new string[](legsLen);
        for (uint i = 0; i < legsLen; ++i) {
            (, , uint16 typeId, , , , , , ) = t.markets(i);
            out[i] = Strings.toString(uint256(typeId));
        }
    }

    /// @dev Builds decimal-encoded playerIds for each leg.
    function _buildPlayerIds(address ticketAddr, uint legsLen) internal view returns (string[] memory out) {
        Ticket t = Ticket(ticketAddr);
        out = new string[](legsLen);
        for (uint i = 0; i < legsLen; ++i) {
            (, , , , , , uint24 playerId, , ) = t.markets(i);
            out[i] = Strings.toString(uint256(playerId));
        }
    }

    /// @dev Builds decimal-encoded positions for each leg.
    function _buildPositions(address ticketAddr, uint legsLen) internal view returns (string[] memory out) {
        Ticket t = Ticket(ticketAddr);
        out = new string[](legsLen);
        for (uint i = 0; i < legsLen; ++i) {
            (, , , , , , , uint8 position, ) = t.markets(i);
            out[i] = Strings.toString(uint256(position));
        }
    }

    /// @dev Builds string-encoded signed lines for each leg.
    function _buildLines(address ticketAddr, uint legsLen) internal view returns (string[] memory out) {
        Ticket t = Ticket(ticketAddr);
        out = new string[](legsLen);
        for (uint i = 0; i < legsLen; ++i) {
            (, , , , , int24 line, , , ) = t.markets(i);
            out[i] = _intToString(int256(line));
        }
    }

    /// @dev Builds decimal-encoded expected odds per leg.
    function _buildExpectedOdds(
        uint[] calldata expectedOddsPerLeg,
        uint legsLen
    ) internal pure returns (string[] memory out) {
        out = new string[](legsLen);
        for (uint i = 0; i < legsLen; ++i) {
            out[i] = Strings.toString(expectedOddsPerLeg[i]);
        }
    }

    /// @dev Builds "1"/"0" strings representing resolved flags.
    function _buildIsResolved(bool[] calldata isLegResolved, uint legsLen) internal pure returns (string[] memory out) {
        out = new string[](legsLen);
        for (uint i = 0; i < legsLen; ++i) {
            out[i] = isLegResolved[i] ? "1" : "0";
        }
    }

    /// @dev Converts a signed integer to string (base-10), including a leading '-' for negative values.
    function _intToString(int256 value) internal pure returns (string memory) {
        if (value >= 0) return Strings.toString(uint256(value));
        return string(abi.encodePacked("-", Strings.toString(uint256(-value))));
    }

    // ============================
    // Admin
    // ============================

    /**
     * @notice Pauses/unpauses {requestCashout} and {fulfillCashout}.
     * @param _setPausing True to pause, false to unpause.
     */
    function setPaused(bool _setPausing) external onlyOwner {
        _setPausing ? _pause() : _unpause();
    }

    /// @notice withdraw collateral in the contract
    /// @dev Transfers the full balance of `collateral` held by this contract to `recipient`.
    /// @param collateral ERC20 token address to withdraw
    /// @param recipient Address receiving withdrawn collateral
    function withdrawCollateral(address collateral, address recipient) external onlyOwner {
        IERC20(collateral).safeTransfer(recipient, IERC20(collateral).balanceOf(address(this)));
    }

    /**
     * @notice Updates Chainlink + SportsAMM configuration in a single call.
     * @dev Emits {ContextReset}.
     * @param _link New LINK token address.
     * @param _oracle New oracle address.
     * @param _sportsAMM New SportsAMM address.
     * @param _jobSpecId New job spec id.
     * @param _paymentAmount New payment amount.
     */
    function setConfiguration(
        address _link,
        address _oracle,
        address _sportsAMM,
        bytes32 _jobSpecId,
        uint _paymentAmount
    ) external onlyOwner {
        setChainlinkToken(_link);
        setChainlinkOracle(_oracle);
        sportsAMM = ISportsAMMV2(_sportsAMM);
        jobSpecId = _jobSpecId;
        paymentAmount = _paymentAmount;

        emit ContextReset(_link, _oracle, _sportsAMM, _jobSpecId, _paymentAmount);
    }

    /**
     * @notice Sets the maximum oracle execution delay (staleness limit) for fulfillments.
     * @param _maxAllowedExecutionDelay Delay in seconds.
     */
    function setMaxAllowedExecutionDelay(uint _maxAllowedExecutionDelay) external onlyOwner {
        maxAllowedExecutionDelay = _maxAllowedExecutionDelay;
        emit SetMaxAllowedExecutionDelay(_maxAllowedExecutionDelay);
    }

    /**
     * @notice Sets the FreeBetsHolder address; tickets owned by this address are not cashoutable.
     * @param _freeBetsHolder FreeBetsHolder address (set to zero to disable this restriction).
     */
    function setFreeBetsHolder(address _freeBetsHolder) external onlyOwner {
        freeBetsHolder = _freeBetsHolder;
        emit SetFreeBetsHolder(_freeBetsHolder);
    }

    // ============================
    // View helpers (reverted back in)
    // ============================

    /**
     * @notice Returns basic request info for UI/indexers.
     * @param requestId Chainlink request id.
     * @return ticket Ticket address.
     * @return requester Requester address.
     * @return additionalSlippage Additional slippage set by requester.
     * @return ts Timestamp (block.timestamp) when the request was stored.
     * @return fulfilled Whether it has been fulfilled.
     * @return allow Whether the oracle allowed the cashout (only meaningful if fulfilled).
     */
    function getRequestBasics(
        bytes32 requestId
    )
        external
        view
        returns (address ticket, address requester, uint additionalSlippage, uint ts, bool fulfilled, bool allow)
    {
        ticket = requestIdToTicket[requestId];
        requester = requestIdToRequester[requestId];
        additionalSlippage = requestIdToAdditionalSlippage[requestId];
        ts = timestampPerRequest[requestId];
        fulfilled = requestIdFulfilled[requestId];
        allow = requestIdToFulfillAllowed[requestId];
    }

    /**
     * @notice Returns per-leg arrays associated with a request for UI/debugging.
     * @param requestId Chainlink request id.
     * @return expectedOddsPerLeg User-provided expected odds per leg.
     * @return isLegResolved User-provided resolved flags per leg.
     * @return approvedOddsPerLeg Oracle-approved odds per leg (empty until fulfilled).
     */
    function getRequestArrays(
        bytes32 requestId
    )
        external
        view
        returns (uint[] memory expectedOddsPerLeg, bool[] memory isLegResolved, uint[] memory approvedOddsPerLeg)
    {
        expectedOddsPerLeg = _requestIdToExpectedOddsPerLeg[requestId];
        isLegResolved = _requestIdToIsLegResolved[requestId];
        approvedOddsPerLeg = _requestIdToApprovedOddsPerLeg[requestId];
    }

    // ============================
    // Events
    // ============================

    /// @notice Emitted when Chainlink/SportsAMM context is updated.
    event ContextReset(address link, address oracle, address sportsAMM, bytes32 jobSpecId, uint paymentAmount);

    /// @notice Emitted when a cashout request is created.
    event CashoutRequested(
        address indexed requester,
        uint indexed requestCounter,
        bytes32 indexed requestId,
        address ticket,
        uint legs,
        uint additionalSlippage
    );

    /// @notice Emitted when a request is fulfilled (will only be emitted if allow=true and cashout executes).
    event CashoutFulfilled(
        address indexed requester,
        bytes32 indexed requestId,
        address ticket,
        bool allow,
        uint legs,
        uint timestamp
    );

    /// @notice Emitted when maxAllowedExecutionDelay is updated.
    event SetMaxAllowedExecutionDelay(uint delay);

    /// @notice Emitted when freeBetsHolder is updated.
    event SetFreeBetsHolder(address _freeBetsHolder);
}

contracts/core/Casino/Baccarat.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";

import "chainlink-vrf/src/v0.8/vrf/dev/interfaces/IVRFCoordinatorV2Plus.sol";
import "chainlink-vrf/src/v0.8/vrf/dev/libraries/VRFV2PlusClient.sol";

// internal
import "../../utils/proxy/ProxyReentrancyGuard.sol";
import "../../utils/proxy/ProxyOwned.sol";
import "../../utils/proxy/ProxyPausable.sol";
import "@thales-dao/contracts/contracts/interfaces/IPriceFeed.sol";

import "../../interfaces/ISportsAMMV2Manager.sol";
import "../../interfaces/IFreeBetsHolder.sol";
import "@thales-dao/contracts/contracts/interfaces/IReferrals.sol";

/// @title Baccarat
/// @author Overtime
/// @notice Baccarat contract using Chainlink VRF for single-player bets
/// @dev Supports USDC, WETH and OVER collateral, with bankroll reservation per collateral
contract Baccarat is Initializable, ProxyOwned, ProxyPausable, ProxyReentrancyGuard {
    using SafeERC20 for IERC20;

    /* ========== CONSTANTS ========== */

    uint private constant ONE = 1e18;
    uint private constant USDC_UNIT = 1e6;

    /// @notice Minimum allowed bet value expressed in USD, normalized to 18 decimals
    uint public constant MIN_BET_USD = 3e18;

    /// @notice Minimum allowed cancel timeout in seconds
    uint public constant MIN_CANCEL_TIMEOUT = 30;

    /// @notice Default total payout multiplier for winning Banker bets in 1e18 precision
    uint public constant DEFAULT_BANKER_PAYOUT = 195e16; // 1.95x

    /// @notice Minimum allowed total payout multiplier for winning Banker bets in 1e18 precision
    uint public constant MIN_BANKER_PAYOUT = 1e18; // 1.00x

    /// @notice Maximum allowed total payout multiplier for winning Banker bets in 1e18 precision
    uint public constant MAX_BANKER_PAYOUT = 2e18; // 2.00x

    uint8 private constant CARD_RANK_MIN = 1;
    uint8 private constant CARD_RANK_MAX = 13;

    /* ========== ERRORS ========== */

    error InvalidAddress();
    error InvalidSender();
    error InvalidCollateral();
    error InvalidPrice();
    error InvalidAmount();
    error InvalidBetType();
    error InvalidCardRank();
    error InvalidBankerPayoutMultiplier();
    error BetNotFound();
    error BetNotPending();
    error BetNotOwner();
    error CancelTimeoutNotReached();
    error MaxProfitExceeded();
    error InsufficientAvailableLiquidity();

    /* ========== ENUMS ========== */

    /// @notice Supported baccarat bet types
    enum BetType {
        PLAYER,
        BANKER,
        TIE
    }

    /// @notice Final baccarat game result
    enum GameResult {
        PLAYER,
        BANKER,
        TIE
    }

    /// @notice Lifecycle status of a baccarat bet
    enum BetStatus {
        NONE,
        PENDING,
        RESOLVED,
        CANCELLED
    }

    /* ========== STRUCTS ========== */

    /// @notice Stored data for an individual baccarat bet
    /// @param user Address of the bettor
    /// @param collateral Collateral token used for the bet
    /// @param amount Amount staked
    /// @param payout Final payout amount, 0 if lost, original amount if pushed/cancelled
    /// @param requestId Chainlink VRF request id
    /// @param placedAt Timestamp when the bet was placed
    /// @param resolvedAt Timestamp when the bet was resolved or cancelled
    /// @param reservedProfit Reserved house-side profit liability for this bet
    /// @param betType Type of baccarat bet
    /// @param status Current status of the bet
    /// @param result Final baccarat result
    /// @param won Whether the bet won
    /// @param isPush Whether the bet resulted in a push
    /// @param playerTotal Final player total
    /// @param bankerTotal Final banker total
    /// @param cards Array of 6 card values dealt during the game
    struct Bet {
        address user;
        address collateral;
        uint amount;
        uint payout;
        uint requestId;
        uint placedAt;
        uint resolvedAt;
        uint reservedProfit;
        BetType betType;
        BetStatus status;
        GameResult result;
        bool won;
        bool isPush;
        uint8 playerTotal;
        uint8 bankerTotal;
        uint8[6] cards;
        uint bankerMultiplier;
    }

    struct CoreAddresses {
        address owner;
        address manager;
        address priceFeed;
        address vrfCoordinator;
    }

    struct CollateralConfig {
        address usdc;
        address weth;
        address over;
        bytes32 wethPriceFeedKey;
        bytes32 overPriceFeedKey;
    }

    struct VrfConfig {
        uint256 subscriptionId;
        bytes32 keyHash;
        uint32 callbackGasLimit;
        uint16 requestConfirmations;
        bool nativePayment;
    }

    /// @notice Internal struct for game resolution output
    struct ResolveResult {
        GameResult result;
        bool won;
        bool isPush;
        uint payout;
        uint8[6] cards;
        uint8 playerTotal;
        uint8 bankerTotal;
    }

    /* ========== STATE VARIABLES ========== */

    /// @notice Manager contract used for whitelist-based role checks
    ISportsAMMV2Manager public manager;

    /// @notice Price feed used for collateral normalization to USD
    IPriceFeed public priceFeed;

    /// @notice Chainlink VRF coordinator
    IVRFCoordinatorV2Plus public vrfCoordinator;

    /// @notice Supported collateral addresses
    address public usdc;
    address public weth;
    address public over;

    /// @notice Maximum allowed profit per bet in USD, normalized to 18 decimals
    uint public maxProfitUsd;

    /// @notice Timeout after which a pending bet can be cancelled
    uint public cancelTimeout;

    /// @notice Total payout multiplier for winning Banker bets in 1e18 precision
    /// @dev Defaults to DEFAULT_BANKER_PAYOUT if initialize receives 0
    uint public bankerPayoutMultiplier;

    /// @notice Next bet id to assign
    uint public nextBetId;

    /// @notice Chainlink VRF v2.5 subscription id
    uint256 public subscriptionId;

    /// @notice Chainlink VRF key hash / gas lane
    bytes32 public keyHash;

    /// @notice Gas limit for VRF callback execution
    uint32 public callbackGasLimit;

    /// @notice Number of confirmations for VRF request
    uint16 public requestConfirmations;

    /// @notice Whether VRF request is paid in native token
    bool public nativePayment;

    /// @notice Whether a collateral is supported
    mapping(address => bool) public supportedCollateral;

    /// @notice Price feed key per collateral for non-USDC assets
    mapping(address => bytes32) public priceFeedKeyPerCollateral;

    /// @notice Stored bets by bet id
    mapping(uint => Bet) internal _bets;

    /// @notice Maps VRF request id to bet id
    mapping(uint => uint) public requestIdToBetId;

    /// @notice Tracks reserved house-side profit liability for all pending bets per collateral
    mapping(address => uint) public reservedProfitPerCollateral;

    /// @notice Bet IDs per user for history queries
    mapping(address => uint[]) private userBetIds;

    /// @notice Free bets holder contract address
    address public freeBetsHolder;

    /// @notice Whether a bet was placed with a free bet
    mapping(uint => bool) public isFreeBet;

    /// @notice Referrals contract
    IReferrals public referrals;

    /* ========== PUBLIC / EXTERNAL METHODS ========== */

    /// @notice Initializes the baccarat contract
    /// @param core Core protocol addresses
    /// @param collateralConfig Collateral addresses and price feed keys
    /// @param _maxProfitUsd Maximum allowed profit per bet in USD, normalized to 18 decimals
    /// @param _cancelTimeout Timeout after which a pending bet can be cancelled
    /// @param _bankerPayoutMultiplier Total payout multiplier for winning Banker bets in 1e18 precision. Pass 0 to use DEFAULT_BANKER_PAYOUT.
    /// @param vrfConfig Chainlink VRF configuration
    function initialize(
        CoreAddresses calldata core,
        CollateralConfig calldata collateralConfig,
        uint _maxProfitUsd,
        uint _cancelTimeout,
        uint _bankerPayoutMultiplier,
        VrfConfig calldata vrfConfig
    ) external initializer {
        if (
            core.owner == address(0) ||
            core.manager == address(0) ||
            core.priceFeed == address(0) ||
            core.vrfCoordinator == address(0) ||
            collateralConfig.usdc == address(0) ||
            collateralConfig.weth == address(0) ||
            collateralConfig.over == address(0)
        ) {
            revert InvalidAddress();
        }

        setOwner(core.owner);
        initNonReentrant();

        manager = ISportsAMMV2Manager(core.manager);
        priceFeed = IPriceFeed(core.priceFeed);
        vrfCoordinator = IVRFCoordinatorV2Plus(core.vrfCoordinator);

        usdc = collateralConfig.usdc;
        weth = collateralConfig.weth;
        over = collateralConfig.over;

        supportedCollateral[collateralConfig.usdc] = true;
        supportedCollateral[collateralConfig.weth] = true;
        supportedCollateral[collateralConfig.over] = true;

        priceFeedKeyPerCollateral[collateralConfig.weth] = collateralConfig.wethPriceFeedKey;
        priceFeedKeyPerCollateral[collateralConfig.over] = collateralConfig.overPriceFeedKey;

        if (_maxProfitUsd == 0) revert InvalidAmount();
        if (vrfConfig.callbackGasLimit == 0) revert InvalidAmount();

        uint bankerMultiplierToSet = _bankerPayoutMultiplier == 0 ? DEFAULT_BANKER_PAYOUT : _bankerPayoutMultiplier;
        if (bankerMultiplierToSet < MIN_BANKER_PAYOUT || bankerMultiplierToSet > MAX_BANKER_PAYOUT) {
            revert InvalidBankerPayoutMultiplier();
        }

        if (_cancelTimeout < MIN_CANCEL_TIMEOUT) revert InvalidAmount();
        maxProfitUsd = _maxProfitUsd;
        cancelTimeout = _cancelTimeout;
        bankerPayoutMultiplier = bankerMultiplierToSet;

        subscriptionId = vrfConfig.subscriptionId;
        keyHash = vrfConfig.keyHash;
        callbackGasLimit = vrfConfig.callbackGasLimit;
        requestConfirmations = vrfConfig.requestConfirmations;
        nativePayment = vrfConfig.nativePayment;

        nextBetId = 1;
    }

    /// @notice Places a baccarat bet and requests randomness from Chainlink VRF
    function placeBet(
        address collateral,
        uint amount,
        BetType betType,
        address _referrer
    ) external nonReentrant notPaused returns (uint betId, uint requestId) {
        if (!supportedCollateral[collateral]) revert InvalidCollateral();
        IERC20(collateral).safeTransferFrom(msg.sender, address(this), amount);
        _setReferrer(_referrer, msg.sender);
        return _placeBet(msg.sender, collateral, amount, betType, false);
    }

    /// @notice Places a baccarat bet using free bet balance
    function placeBetWithFreeBet(
        address collateral,
        uint amount,
        BetType betType
    ) external nonReentrant notPaused returns (uint betId, uint requestId) {
        if (!supportedCollateral[collateral]) revert InvalidCollateral();
        IFreeBetsHolder(freeBetsHolder).useFreeBet(msg.sender, collateral, amount);
        return _placeBet(msg.sender, collateral, amount, betType, true);
    }

    function _placeBet(
        address user,
        address collateral,
        uint amount,
        BetType betType,
        bool _isFreeBet
    ) internal returns (uint betId, uint requestId) {
        // collateral support already validated by the external wrappers (placeBet / placeBetWithFreeBet)
        if (amount == 0) revert InvalidAmount();

        _validateBetType(betType);

        uint amountUsd = _getUsdValue(collateral, amount);
        if (amountUsd < MIN_BET_USD) revert InvalidAmount();

        uint reservedProfit = _getReservedProfit(amount, betType);
        if (_getUsdValue(collateral, reservedProfit) > maxProfitUsd) revert MaxProfitExceeded();

        reservedProfitPerCollateral[collateral] += amount + reservedProfit;
        if (!_hasEnoughLiquidity(collateral)) {
            reservedProfitPerCollateral[collateral] -= amount + reservedProfit;
            revert InsufficientAvailableLiquidity();
        }

        requestId = _requestRandomWord();
        betId = nextBetId++;

        Bet storage bet = _bets[betId];
        bet.user = user;
        bet.collateral = collateral;
        bet.amount = amount;
        bet.requestId = requestId;
        bet.placedAt = block.timestamp;
        bet.reservedProfit = reservedProfit;
        bet.betType = betType;
        bet.status = BetStatus.PENDING;
        if (betType == BetType.BANKER) {
            bet.bankerMultiplier = bankerPayoutMultiplier;
        }

        if (_isFreeBet) isFreeBet[betId] = true;

        requestIdToBetId[requestId] = betId;
        userBetIds[user].push(betId);

        emit BetPlaced(betId, requestId, user, collateral, amount, betType);
    }

    /// @notice Cancels a pending bet after timeout and refunds the original stake
    /// @param betId Bet id to cancel
    function cancelBet(uint betId) external nonReentrant {
        Bet storage bet = _bets[betId];

        if (bet.status == BetStatus.NONE) revert BetNotFound();
        if (bet.user != msg.sender) revert BetNotOwner();
        if (bet.status != BetStatus.PENDING) revert BetNotPending();
        if (block.timestamp < bet.placedAt + cancelTimeout) revert CancelTimeoutNotReached();

        _cancelBet(betId, false);
    }

    /// @notice Emergency cancels a pending bet and refunds the original stake
    /// @dev Callable by owner or manager role with MARKET_RESOLVING permission
    /// @param betId Bet id to cancel
    function adminCancelBet(uint betId) external onlyResolver nonReentrant {
        Bet storage bet = _bets[betId];

        if (bet.status == BetStatus.NONE) revert BetNotFound();
        if (bet.status != BetStatus.PENDING) revert BetNotPending();

        _cancelBet(betId, true);
    }

    /// @notice Pauses or unpauses the contract using manager-based pauser permissions
    /// @param _paused True to pause, false to unpause
    function setPausedByRole(bool _paused) external onlyPauser {
        if (paused != _paused) {
            paused = _paused;
            if (_paused) {
                lastPauseTime = block.timestamp;
            }
            emit PauseChanged(_paused);
        }
    }

    /// @notice Coordinator-only VRF entrypoint
    /// @param requestId Chainlink VRF request id
    /// @param randomWords Array of VRF random words
    function rawFulfillRandomWords(uint256 requestId, uint256[] calldata randomWords) external nonReentrant {
        if (msg.sender != address(vrfCoordinator)) revert InvalidSender();
        _fulfillRandomWords(requestId, randomWords);
    }

    /* ========== INTERNAL / PRIVATE ========== */

    /// @notice Internal baccarat resolution logic after VRF fulfillment
    /// @param requestId Chainlink VRF request id
    /// @param randomWords Array of VRF random words
    function _fulfillRandomWords(uint256 requestId, uint256[] calldata randomWords) internal {
        uint betId = requestIdToBetId[requestId];
        if (betId == 0) return;

        Bet storage bet = _bets[betId];
        if (bet.status != BetStatus.PENDING) return;

        _resolveBet(betId, bet, randomWords[0]);
    }

    /// @notice Resolves a bet: runs game logic, releases reserves, pays out, stores result, emits event
    /// @param betId Bet id
    /// @param bet Bet storage reference
    /// @param randomWord VRF random word
    function _resolveBet(uint betId, Bet storage bet, uint256 randomWord) internal {
        ResolveResult memory r = _resolveGame(bet.amount, bet.betType, bet.bankerMultiplier, randomWord);

        reservedProfitPerCollateral[bet.collateral] -= bet.amount + bet.reservedProfit;

        // State update before external transfers (CEI)
        bet.result = r.result;
        bet.won = r.won;
        bet.isPush = r.isPush;
        bet.payout = r.payout;
        bet.playerTotal = r.playerTotal;
        bet.bankerTotal = r.bankerTotal;
        bet.cards = r.cards;
        bet.status = BetStatus.RESOLVED;
        bet.resolvedAt = block.timestamp;

        emit BetResolved(betId, bet.requestId, bet.user, r.result, r.won, r.isPush, r.payout, r.playerTotal, r.bankerTotal);

        if (r.payout > 0) {
            if (isFreeBet[betId]) {
                IERC20(bet.collateral).safeTransfer(freeBetsHolder, r.payout);
                IFreeBetsHolder(freeBetsHolder).confirmCasinoBetResolved(bet.user, bet.collateral, r.payout, bet.amount);
            } else {
                IERC20(bet.collateral).safeTransfer(bet.user, r.payout);
            }
        }

        if (!r.won && !r.isPush && !isFreeBet[betId]) {
            _payReferrer(bet.user, bet.collateral, bet.amount);
        }
    }

    /// @notice Resolves a baccarat game from a single random word
    /// @param amount Bet amount
    /// @param betType Type of baccarat bet
    /// @param randomWord VRF random word
    /// @return r Resolution result containing game outcome, cards and totals
    function _resolveGame(
        uint amount,
        BetType betType,
        uint bankerMultiplier,
        uint256 randomWord
    ) internal pure returns (ResolveResult memory r) {
        // Deal initial four cards
        r.cards[0] = _getCardValue(randomWord, 0);
        r.cards[1] = _getCardValue(randomWord, 1);
        r.cards[2] = _getCardValue(randomWord, 2);
        r.cards[3] = _getCardValue(randomWord, 3);

        r.playerTotal = _getHandTotal(r.cards[0], r.cards[2]);
        r.bankerTotal = _getHandTotal(r.cards[1], r.cards[3]);

        // Check for naturals
        if (!_isNatural(r.playerTotal) && !_isNatural(r.bankerTotal)) {
            bool playerDrew = _shouldPlayerDraw(r.playerTotal);
            uint8 playerThirdCard = 0;

            if (playerDrew) {
                r.cards[4] = _getCardValue(randomWord, 4);
                playerThirdCard = r.cards[4];
                r.playerTotal = _getHandTotal3(r.cards[0], r.cards[2], playerThirdCard);
            }

            if (_shouldBankerDraw(r.bankerTotal, playerDrew, playerThirdCard)) {
                r.cards[5] = _getCardValue(randomWord, 5);
                r.bankerTotal = _getHandTotal3(r.cards[1], r.cards[3], r.cards[5]);
            }
        }

        r.result = _getGameResult(r.playerTotal, r.bankerTotal);
        (r.payout, r.won, r.isPush) = _getPayout(amount, betType, bankerMultiplier, r.result);
    }

    function _setReferrer(address _referrer, address _user) internal {
        if (_referrer != address(0) && address(referrals) != address(0)) {
            referrals.setReferrer(_referrer, _user);
        }
    }

    function _payReferrer(address _user, address _collateral, uint _amount) internal {
        if (address(referrals) == address(0)) return;
        address referrer = referrals.referrals(_user);
        if (referrer == address(0)) return;
        uint referrerFee = referrals.getReferrerFee(referrer);
        if (referrerFee == 0) return;
        uint referrerAmount = (_amount * referrerFee) / ONE;
        if (referrerAmount > 0) {
            try IERC20(_collateral).transfer(referrer, referrerAmount) returns (bool ok) {
                if (ok) emit ReferrerPaid(referrer, _user, referrerAmount, _amount, _collateral);
                else emit ReferrerPayoutFailed(referrer, _user, referrerAmount, _amount, _collateral);
            } catch {
                emit ReferrerPayoutFailed(referrer, _user, referrerAmount, _amount, _collateral);
            }
        }
    }

    function _cancelBet(uint betId, bool adminCancelled) internal {
        Bet storage bet = _bets[betId];

        reservedProfitPerCollateral[bet.collateral] -= bet.amount + bet.reservedProfit;

        bet.status = BetStatus.CANCELLED;
        bet.resolvedAt = block.timestamp;

        if (isFreeBet[betId]) {
            bet.payout = 0;
            IERC20(bet.collateral).safeTransfer(freeBetsHolder, bet.amount);
            IFreeBetsHolder(freeBetsHolder).confirmCasinoBetResolved(bet.user, bet.collateral, bet.amount, bet.amount);
        } else {
            bet.payout = bet.amount;
            IERC20(bet.collateral).safeTransfer(bet.user, bet.amount);
        }

        emit BetCancelled(betId, bet.requestId, bet.user, bet.amount, adminCancelled);
    }

    /// @notice Requests one random word from Chainlink VRF
    /// @return requestId Chainlink VRF request id
    function _requestRandomWord() internal returns (uint requestId) {
        requestId = vrfCoordinator.requestRandomWords(
            VRFV2PlusClient.RandomWordsRequest({
                keyHash: keyHash,
                subId: subscriptionId,
                requestConfirmations: requestConfirmations,
                callbackGasLimit: callbackGasLimit,
                numWords: 1,
                extraArgs: VRFV2PlusClient._argsToBytes(VRFV2PlusClient.ExtraArgsV1({nativePayment: nativePayment}))
            })
        );
    }

    /// @notice Checks whether available collateral balance covers all reserved profit
    /// @param collateral Collateral token address
    /// @return True if bankroll is sufficient for the collateral
    function _hasEnoughLiquidity(address collateral) internal view returns (bool) {
        return IERC20(collateral).balanceOf(address(this)) >= reservedProfitPerCollateral[collateral];
    }

    /// @notice Returns the normalized price for a supported collateral
    /// @param collateral Collateral token address
    /// @return Collateral price normalized to 18 decimals
    function _getCollateralPrice(address collateral) internal view returns (uint) {
        if (!supportedCollateral[collateral]) revert InvalidCollateral();

        if (collateral == usdc) {
            return ONE;
        }

        bytes32 currencyKey = priceFeedKeyPerCollateral[collateral];
        if (currencyKey == bytes32(0)) revert InvalidCollateral();

        uint price = priceFeed.rateForCurrency(currencyKey);
        if (price == 0) revert InvalidPrice();

        return price;
    }

    /// @notice Converts collateral amount into USD value normalized to 18 decimals
    /// @param collateral Collateral token address
    /// @param amount Collateral amount
    /// @return USD value normalized to 18 decimals
    function _getUsdValue(address collateral, uint amount) internal view returns (uint) {
        if (collateral == usdc) {
            return (amount * ONE) / USDC_UNIT;
        }

        uint price = _getCollateralPrice(collateral);
        return (amount * price) / ONE;
    }

    /// @notice Validates baccarat bet type
    /// @param betType Baccarat bet type
    function _validateBetType(BetType betType) internal pure {
        if (betType == BetType.PLAYER || betType == BetType.BANKER || betType == BetType.TIE) {
            return;
        }

        revert InvalidBetType();
    }

    /// @notice Returns reserved profit amount in collateral units for a winning bet
    /// @param amount Bet amount
    /// @param betType Baccarat bet type
    /// @return Reserved house-side profit liability
    function _getReservedProfit(uint amount, BetType betType) internal view returns (uint) {
        if (betType == BetType.PLAYER) {
            return amount;
        }

        if (betType == BetType.BANKER) {
            uint payout = (amount * bankerPayoutMultiplier) / ONE;
            return payout - amount;
        }

        if (betType == BetType.TIE) {
            return amount * 8;
        }

        revert InvalidBetType();
    }

    /// @notice Derives a card rank in range 1..13 from a random word and index
    /// @param randomWord VRF random word
    /// @param index Derivation index
    /// @return rank Card rank in range 1..13
    function _getCardRank(uint256 randomWord, uint index) internal pure returns (uint8 rank) {
        rank = uint8((uint256(keccak256(abi.encode(randomWord, index))) % CARD_RANK_MAX) + CARD_RANK_MIN);
    }

    /// @notice Maps a card rank to baccarat card value
    /// @param rank Card rank in range 1..13
    /// @return Card value in baccarat scoring
    function _getBaccaratCardValue(uint8 rank) internal pure returns (uint8) {
        if (rank < CARD_RANK_MIN || rank > CARD_RANK_MAX) revert InvalidCardRank();

        if (rank == 1) {
            return 1;
        }

        if (rank >= 2 && rank <= 9) {
            return rank;
        }

        return 0;
    }

    /// @notice Derives a baccarat card value directly from a random word and index
    /// @param randomWord VRF random word
    /// @param index Derivation index
    /// @return Card value in baccarat scoring
    function _getCardValue(uint256 randomWord, uint index) internal pure returns (uint8) {
        return _getBaccaratCardValue(_getCardRank(randomWord, index));
    }

    /// @notice Returns 2-card hand total modulo 10
    /// @param card1 First card value
    /// @param card2 Second card value
    /// @return Hand total
    function _getHandTotal(uint8 card1, uint8 card2) internal pure returns (uint8) {
        return uint8((card1 + card2) % 10);
    }

    /// @notice Returns 3-card hand total modulo 10
    /// @param card1 First card value
    /// @param card2 Second card value
    /// @param card3 Third card value
    /// @return Hand total
    function _getHandTotal3(uint8 card1, uint8 card2, uint8 card3) internal pure returns (uint8) {
        return uint8((card1 + card2 + card3) % 10);
    }

    /// @notice Returns whether the initial total is a natural
    /// @param total Baccarat hand total
    /// @return True if total is 8 or 9
    function _isNatural(uint8 total) internal pure returns (bool) {
        return total == 8 || total == 9;
    }

    /// @notice Returns whether Player should draw a third card
    /// @param playerTotal Player total after first two cards
    /// @return True if Player draws
    function _shouldPlayerDraw(uint8 playerTotal) internal pure returns (bool) {
        return playerTotal <= 5;
    }

    /// @notice Returns whether Banker should draw a third card
    /// @param bankerTotal Banker total after first two cards
    /// @param playerDrew Whether Player drew a third card
    /// @param playerThirdCard Player third card baccarat value, 0 if Player stood
    /// @return True if Banker draws
    function _shouldBankerDraw(uint8 bankerTotal, bool playerDrew, uint8 playerThirdCard) internal pure returns (bool) {
        if (!playerDrew) {
            return bankerTotal <= 5;
        }

        if (bankerTotal <= 2) return true;
        if (bankerTotal == 3) return playerThirdCard != 8;
        if (bankerTotal == 4) return playerThirdCard >= 2 && playerThirdCard <= 7;
        if (bankerTotal == 5) return playerThirdCard >= 4 && playerThirdCard <= 7;
        if (bankerTotal == 6) return playerThirdCard == 6 || playerThirdCard == 7;

        return false;
    }

    /// @notice Determines final baccarat game result from hand totals
    /// @param playerTotal Final player total
    /// @param bankerTotal Final banker total
    /// @return Final game result
    function _getGameResult(uint8 playerTotal, uint8 bankerTotal) internal pure returns (GameResult) {
        if (playerTotal > bankerTotal) return GameResult.PLAYER;
        if (bankerTotal > playerTotal) return GameResult.BANKER;
        return GameResult.TIE;
    }

    /// @notice Returns final payout, win flag and push flag for a baccarat bet
    /// @param amount Bet amount
    /// @param betType Baccarat bet type
    /// @param result Final game result
    /// @return payout Final payout amount
    /// @return won Whether the bet won
    /// @return isPush Whether the bet pushed
    function _getPayout(
        uint amount,
        BetType betType,
        uint bankerMultiplier,
        GameResult result
    ) internal pure returns (uint payout, bool won, bool isPush) {
        if (betType == BetType.PLAYER) {
            if (result == GameResult.PLAYER) return (amount * 2, true, false);
            if (result == GameResult.TIE) return (amount, false, true);
            return (0, false, false);
        }

        if (betType == BetType.BANKER) {
            if (result == GameResult.BANKER) return ((amount * bankerMultiplier) / ONE, true, false);
            if (result == GameResult.TIE) return (amount, false, true);
            return (0, false, false);
        }

        if (betType == BetType.TIE) {
            if (result == GameResult.TIE) return (amount * 9, true, false);
            return (0, false, false);
        }

        revert InvalidBetType();
    }

    /* ========== GETTERS ========== */

    /// @notice Returns core bet data
    function getBetBase(
        uint betId
    )
        external
        view
        returns (
            address user,
            address collateral,
            uint amount,
            uint payout,
            uint requestId,
            uint placedAt,
            uint resolvedAt,
            uint reservedProfit
        )
    {
        Bet storage b = _bets[betId];
        return (b.user, b.collateral, b.amount, b.payout, b.requestId, b.placedAt, b.resolvedAt, b.reservedProfit);
    }

    /// @notice Returns bet status, result and game details
    function getBetDetails(
        uint betId
    )
        external
        view
        returns (
            BetType betType,
            BetStatus status,
            GameResult result,
            bool won,
            bool isPush,
            uint8[6] memory cards,
            uint8 playerTotal,
            uint8 bankerTotal
        )
    {
        Bet storage b = _bets[betId];
        return (b.betType, b.status, b.result, b.won, b.isPush, b.cards, b.playerTotal, b.bankerTotal);
    }

    /// @notice Returns potential profit in USD for a given bet
    /// @param collateral Collateral token address
    /// @param amount Bet amount
    /// @param betType Baccarat bet type
    /// @return Potential profit in USD normalized to 18 decimals
    function getPotentialProfit(address collateral, uint amount, BetType betType) external view returns (uint) {
        _validateBetType(betType);
        return _getUsdValue(collateral, _getReservedProfit(amount, betType));
    }

    /// @notice Returns total payout in collateral units for a winning bet
    /// @param amount Bet amount
    /// @param betType Baccarat bet type
    /// @return Total payout including original stake
    function getPotentialPayoutCollateral(uint amount, BetType betType) external view returns (uint) {
        _validateBetType(betType);

        if (betType == BetType.PLAYER) {
            return amount * 2;
        }

        if (betType == BetType.BANKER) {
            return (amount * bankerPayoutMultiplier) / ONE;
        }

        return amount * 9;
    }

    /// @notice Returns normalized collateral price
    /// @param collateral Collateral token address
    /// @return Collateral price normalized to 18 decimals
    function getCollateralPrice(address collateral) external view returns (uint) {
        return _getCollateralPrice(collateral);
    }

    /// @notice Returns currently available liquidity for a collateral after reserved profit
    /// @param collateral Collateral token address
    /// @return Available liquidity amount in collateral units
    function getAvailableLiquidity(address collateral) external view returns (uint) {
        if (!supportedCollateral[collateral]) revert InvalidCollateral();
        uint balance = IERC20(collateral).balanceOf(address(this));
        uint reserved = reservedProfitPerCollateral[collateral];
        return balance > reserved ? balance - reserved : 0;
    }

    /// @notice Returns a baccarat card value for a given rank
    /// @param rank Card rank in range 1..13
    /// @return Baccarat card value
    function getBaccaratCardValue(uint8 rank) external pure returns (uint8) {
        return _getBaccaratCardValue(rank);
    }

    /// @notice Returns final baccarat game result from player and banker totals
    /// @param playerTotal Player total
    /// @param bankerTotal Banker total
    /// @return Final game result
    function getGameResult(uint8 playerTotal, uint8 bankerTotal) external pure returns (GameResult) {
        return _getGameResult(playerTotal, bankerTotal);
    }

    /// @notice Returns the number of bets placed by a user
    function getUserBetCount(address user) external view returns (uint) {
        return userBetIds[user].length;
    }

    /// @notice Returns bet IDs for a user's bets with pagination (reverse chronological)
    function getUserBetIds(address user, uint offset, uint limit) external view returns (uint[] memory ids) {
        uint[] storage allIds = userBetIds[user];
        uint len = allIds.length;
        if (offset >= len) return new uint[](0);
        uint remaining = len - offset;
        uint count = remaining < limit ? remaining : limit;
        ids = new uint[](count);
        for (uint i = 0; i < count; i++) {
            ids[i] = allIds[len - 1 - offset - i];
        }
    }

    /// @notice Returns recent bet IDs with pagination (reverse chronological)
    function getRecentBetIds(uint offset, uint limit) external view returns (uint[] memory ids) {
        uint latest = nextBetId - 1;
        if (offset >= latest) return new uint[](0);
        uint start = latest - offset;
        uint count = start < limit ? start : limit;
        ids = new uint[](count);
        for (uint i = 0; i < count; i++) {
            ids[i] = start - i;
        }
    }

    /* ========== SETTERS ========== */

    /// @notice Sets maximum allowed profit per bet in USD
    /// @dev Callable by owner or manager role with RISK_MANAGING permission
    /// @param _maxProfitUsd Maximum profit in USD normalized to 18 decimals
    function setMaxProfitUsd(uint _maxProfitUsd) external onlyRiskManager {
        if (_maxProfitUsd == 0) revert InvalidAmount();
        maxProfitUsd = _maxProfitUsd;
        emit MaxProfitUsdChanged(_maxProfitUsd);
    }

    /// @notice Sets timeout after which pending bets can be cancelled
    /// @dev Callable by owner or manager role with RISK_MANAGING permission
    /// @param _cancelTimeout Timeout in seconds
    function setCancelTimeout(uint _cancelTimeout) external onlyRiskManager {
        if (_cancelTimeout < MIN_CANCEL_TIMEOUT) revert InvalidAmount();
        cancelTimeout = _cancelTimeout;
        emit CancelTimeoutChanged(_cancelTimeout);
    }

    /// @notice Sets total payout multiplier for winning Banker bets
    /// @dev Callable by owner or manager role with RISK_MANAGING permission
    /// @param _bankerPayoutMultiplier Banker payout multiplier in 1e18 precision
    function setBankerPayoutMultiplier(uint _bankerPayoutMultiplier) external onlyRiskManager {
        if (_bankerPayoutMultiplier < MIN_BANKER_PAYOUT || _bankerPayoutMultiplier > MAX_BANKER_PAYOUT) {
            revert InvalidBankerPayoutMultiplier();
        }

        bankerPayoutMultiplier = _bankerPayoutMultiplier;
        emit BankerPayoutMultiplierChanged(_bankerPayoutMultiplier);
    }

    /// @notice Adds or removes a supported collateral
    /// @dev Callable by owner or manager role with RISK_MANAGING permission
    /// @param collateral Collateral token address
    /// @param isSupported Whether the collateral is supported
    function setSupportedCollateral(address collateral, bool isSupported) external onlyRiskManager {
        if (collateral == address(0)) revert InvalidAddress();
        supportedCollateral[collateral] = isSupported;
        emit SupportedCollateralChanged(collateral, isSupported);
    }

    /// @notice Sets price feed key for a collateral
    /// @dev Callable by owner or manager role with RISK_MANAGING permission
    /// @param collateral Collateral token address
    /// @param currencyKey Price feed currency key
    function setPriceFeedKeyPerCollateral(address collateral, bytes32 currencyKey) external onlyRiskManager {
        if (collateral == address(0)) revert InvalidAddress();
        priceFeedKeyPerCollateral[collateral] = currencyKey;
        emit PriceFeedKeyPerCollateralChanged(collateral, currencyKey);
    }

    /// @notice Sets manager contract address
    /// @param _manager Manager contract address
    function setManager(address _manager) external onlyOwner {
        if (_manager == address(0)) revert InvalidAddress();
        manager = ISportsAMMV2Manager(_manager);
        emit ManagerChanged(_manager);
    }

    /// @notice Sets price feed contract address
    /// @param _priceFeed Price feed contract address
    function setPriceFeed(address _priceFeed) external onlyOwner {
        if (_priceFeed == address(0)) revert InvalidAddress();
        priceFeed = IPriceFeed(_priceFeed);
        emit PriceFeedChanged(_priceFeed);
    }

    /// @notice Sets Chainlink VRF coordinator address
    /// @param _vrfCoordinator Chainlink VRF coordinator address
    function setVrfCoordinator(address _vrfCoordinator) external onlyOwner {
        if (_vrfCoordinator == address(0)) revert InvalidAddress();
        vrfCoordinator = IVRFCoordinatorV2Plus(_vrfCoordinator);
        emit VrfCoordinatorChanged(_vrfCoordinator);
    }

    /// @notice Sets the free bets holder contract
    function setFreeBetsHolder(address _freeBetsHolder) external onlyOwner {
        if (_freeBetsHolder == address(0)) revert InvalidAddress();
        freeBetsHolder = _freeBetsHolder;
        emit FreeBetsHolderChanged(_freeBetsHolder);
    }

    /// @notice Sets the referrals contract
    function setReferrals(address _referrals) external onlyOwner {
        if (_referrals == address(0)) revert InvalidAddress();
        referrals = IReferrals(_referrals);
        emit ReferralsChanged(_referrals);
    }

    /// @notice Withdraws collateral from the contract bankroll
    /// @param _collateral The address of the ERC20 token to withdraw
    /// @param _recipient The address of the recipient, defaults to owner if zero address
    /// @param _amount The amount of tokens to withdraw
    function withdrawCollateral(address _collateral, address _recipient, uint _amount) external onlyOwner {
        uint balance = IERC20(_collateral).balanceOf(address(this));
        uint reserved = reservedProfitPerCollateral[_collateral];
        if (_amount > balance || balance - _amount < reserved) revert InsufficientAvailableLiquidity();
        address recipient = _recipient == address(0) ? owner : _recipient;
        IERC20(_collateral).safeTransfer(recipient, _amount);
        emit WithdrawnCollateral(_collateral, recipient, _amount);
    }

    /// @notice Sets Chainlink VRF configuration
    /// @param _subscriptionId Chainlink VRF subscription id
    /// @param _keyHash Chainlink VRF key hash / gas lane
    /// @param _callbackGasLimit Gas limit for callback
    /// @param _requestConfirmations Number of confirmations before VRF fulfillment
    /// @param _nativePayment Whether VRF uses native token payment
    function setVrfConfig(
        uint256 _subscriptionId,
        bytes32 _keyHash,
        uint32 _callbackGasLimit,
        uint16 _requestConfirmations,
        bool _nativePayment
    ) external onlyOwner {
        if (_subscriptionId == 0) revert InvalidAmount();
        if (_keyHash == bytes32(0)) revert InvalidAmount();
        if (_callbackGasLimit == 0) revert InvalidAmount();

        subscriptionId = _subscriptionId;
        keyHash = _keyHash;
        callbackGasLimit = _callbackGasLimit;
        requestConfirmations = _requestConfirmations;
        nativePayment = _nativePayment;

        emit VrfConfigChanged(_subscriptionId, _keyHash, _callbackGasLimit, _requestConfirmations, _nativePayment);
    }

    /* ========== MODIFIERS ========== */

    /// @notice Restricts access to owner or manager addresses whitelisted for risk management
    modifier onlyRiskManager() {
        if (msg.sender != owner && !manager.isWhitelistedAddress(msg.sender, ISportsAMMV2Manager.Role.RISK_MANAGING)) {
            revert InvalidSender();
        }
        _;
    }

    /// @notice Restricts access to owner or manager addresses whitelisted for market resolving
    modifier onlyResolver() {
        if (msg.sender != owner && !manager.isWhitelistedAddress(msg.sender, ISportsAMMV2Manager.Role.MARKET_RESOLVING)) {
            revert InvalidSender();
        }
        _;
    }

    /// @notice Restricts access to owner or manager addresses whitelisted for pausing
    modifier onlyPauser() {
        if (msg.sender != owner && !manager.isWhitelistedAddress(msg.sender, ISportsAMMV2Manager.Role.TICKET_PAUSER)) {
            revert InvalidSender();
        }
        _;
    }

    /* ========== EVENTS ========== */

    /// @notice Emitted when a new bet is placed
    /// @param betId Bet id
    /// @param requestId Chainlink VRF request id
    /// @param user Bettor address
    /// @param collateral Collateral token address
    /// @param amount Bet amount
    /// @param betType Baccarat bet type
    event BetPlaced(
        uint indexed betId,
        uint indexed requestId,
        address indexed user,
        address collateral,
        uint amount,
        BetType betType
    );

    /// @notice Emitted when a bet is resolved
    /// @param betId Bet id
    /// @param requestId Chainlink VRF request id
    /// @param user Bettor address
    /// @param result Final baccarat result
    /// @param won Whether the bet won
    /// @param isPush Whether the bet pushed
    /// @param payout Final payout amount
    /// @param playerTotal Final player total
    /// @param bankerTotal Final banker total
    event BetResolved(
        uint indexed betId,
        uint indexed requestId,
        address indexed user,
        GameResult result,
        bool won,
        bool isPush,
        uint payout,
        uint8 playerTotal,
        uint8 bankerTotal
    );

    /// @notice Emitted when a bet is cancelled
    /// @param betId Bet id
    /// @param requestId Chainlink VRF request id
    /// @param user Bettor address
    /// @param refundedAmount Refunded stake amount
    /// @param adminCancelled Whether the cancellation was admin-triggered
    event BetCancelled(
        uint indexed betId,
        uint indexed requestId,
        address indexed user,
        uint refundedAmount,
        bool adminCancelled
    );

    /// @notice Emitted when maximum profit per bet is changed
    /// @param maxProfitUsd New maximum profit in USD normalized to 18 decimals
    event MaxProfitUsdChanged(uint maxProfitUsd);

    /// @notice Emitted when cancel timeout is changed
    /// @param cancelTimeout New timeout in seconds
    event CancelTimeoutChanged(uint cancelTimeout);

    /// @notice Emitted when banker payout multiplier is changed
    /// @param bankerPayoutMultiplier New banker payout multiplier in 1e18 precision
    event BankerPayoutMultiplierChanged(uint bankerPayoutMultiplier);

    /// @notice Emitted when collateral support is changed
    /// @param collateral Collateral token address
    /// @param supported Whether the collateral is supported
    event SupportedCollateralChanged(address collateral, bool supported);

    /// @notice Emitted when price feed key for a collateral is changed
    /// @param collateral Collateral token address
    /// @param key New price feed key
    event PriceFeedKeyPerCollateralChanged(address collateral, bytes32 key);

    /// @notice Emitted when manager contract is changed
    /// @param manager New manager contract address
    event ManagerChanged(address manager);

    /// @notice Emitted when price feed contract is changed
    /// @param priceFeed New price feed contract address
    event PriceFeedChanged(address priceFeed);

    /// @notice Emitted when VRF coordinator is changed
    /// @param vrfCoordinator New Chainlink VRF coordinator address
    event VrfCoordinatorChanged(address vrfCoordinator);
    event FreeBetsHolderChanged(address freeBetsHolder);
    event ReferralsChanged(address referrals);
    event ReferrerPaid(address indexed referrer, address indexed user, uint amount, uint betAmount, address collateral);
    event ReferrerPayoutFailed(
        address indexed referrer,
        address indexed user,
        uint amount,
        uint betAmount,
        address collateral
    );

    /// @notice Emitted when collateral is withdrawn from the bankroll
    /// @param collateral Collateral token address
    /// @param recipient Recipient address
    /// @param amount Amount withdrawn
    event WithdrawnCollateral(address indexed collateral, address indexed recipient, uint amount);

    /// @notice Emitted when VRF config is changed
    /// @param subscriptionId New Chainlink VRF subscription id
    /// @param keyHash New Chainlink VRF key hash
    /// @param callbackGasLimit New callback gas limit
    /// @param requestConfirmations New request confirmations value
    /// @param nativePayment Whether native payment is enabled
    event VrfConfigChanged(
        uint256 subscriptionId,
        bytes32 keyHash,
        uint32 callbackGasLimit,
        uint16 requestConfirmations,
        bool nativePayment
    );
}

contracts/core/Casino/Blackjack.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";

import "chainlink-vrf/src/v0.8/vrf/dev/interfaces/IVRFCoordinatorV2Plus.sol";
import "chainlink-vrf/src/v0.8/vrf/dev/libraries/VRFV2PlusClient.sol";

// internal
import "../../utils/proxy/ProxyReentrancyGuard.sol";
import "../../utils/proxy/ProxyOwned.sol";
import "../../utils/proxy/ProxyPausable.sol";
import "@thales-dao/contracts/contracts/interfaces/IPriceFeed.sol";

import "../../interfaces/ISportsAMMV2Manager.sol";
import "../../interfaces/IFreeBetsHolder.sol";
import "@thales-dao/contracts/contracts/interfaces/IReferrals.sol";

/// @title Blackjack
/// @author Overtime
/// @notice Single-player blackjack contract using Chainlink VRF for card dealing
/// @dev Supports USDC, WETH and OVER collateral, with bankroll reservation per collateral
contract Blackjack is Initializable, ProxyOwned, ProxyPausable, ProxyReentrancyGuard {
    using SafeERC20 for IERC20;

    /* ========== CONSTANTS ========== */

    uint private constant ONE = 1e18;
    uint private constant USDC_UNIT = 1e6;
    uint private constant BLACKJACK_PAYOUT_NUMERATOR = 3;
    uint private constant BLACKJACK_PAYOUT_DENOMINATOR = 2;
    uint private constant MAX_CARDS = 11;

    /// @notice Highest legal hand total before busting
    uint8 private constant BLACKJACK_TARGET = 21;
    /// @notice Dealer stops drawing once total exceeds this (hits on soft 17 per house rules)
    uint8 private constant DEALER_STAND_THRESHOLD = 17;
    /// @notice Ace can count as 11 when it doesn't bust, else 1 — difference used for soft-ace reduction
    uint8 private constant ACE_HIGH_DELTA = 10;
    /// @notice Value of an Ace when counted high
    uint8 private constant ACE_HIGH_VALUE = 11;
    /// @notice Value of a face card (J/Q/K) and max non-ace pip
    uint8 private constant FACE_CARD_VALUE = 10;
    /// @notice Ace rank in the 1..13 encoding
    uint8 private constant ACE_RANK = 1;
    /// @notice Rank cutoff at which a card becomes a face card (J = 11, Q = 12, K = 13)
    uint8 private constant FACE_CARD_RANK_THRESHOLD = 11;
    /// @notice Number of distinct card ranks (Ace through King)
    uint8 private constant CARD_RANKS = 13;
    /// @notice Bit shift applied to a VRF word to derive a second card from the same word
    uint8 private constant CARD_DERIVATION_SHIFT = 128;

    /// @notice Minimum allowed bet value expressed in USD, normalized to 18 decimals
    uint public constant MIN_BET_USD = 3e18;

    /// @notice Minimum allowed cancel timeout in seconds
    uint public constant MIN_CANCEL_TIMEOUT = 30;

    /* ========== ERRORS ========== */

    error InvalidAddress();
    error InvalidSender();
    error InvalidCollateral();
    error InvalidAmount();
    error HandNotFound();
    error InvalidHandStatus();
    error HandNotOwner();
    error InsufficientAvailableLiquidity();

    /* ========== ENUMS ========== */

    /// @notice Lifecycle status of a blackjack hand
    enum HandStatus {
        NONE,
        AWAITING_DEAL,
        PLAYER_TURN,
        AWAITING_HIT,
        AWAITING_STAND,
        AWAITING_DOUBLE,
        RESOLVED,
        CANCELLED,
        AWAITING_SPLIT
    }

    /// @notice Outcome of a resolved blackjack hand
    enum HandResult {
        NONE,
        PLAYER_BLACKJACK,
        PLAYER_WIN,
        DEALER_WIN,
        PUSH,
        PLAYER_BUST,
        DEALER_BUST
    }

    /// @notice Type of action a VRF request is servicing
    enum VrfAction {
        NONE,
        DEAL,
        HIT,
        STAND,
        DOUBLE_DOWN,
        SPLIT
    }

    /* ========== STRUCTS ========== */

    /// @notice Stored data for an individual blackjack hand
    struct Hand {
        address user;
        address collateral;
        uint amount;
        uint payout;
        uint requestId;
        uint placedAt;
        uint resolvedAt;
        uint reservedProfit;
        HandStatus status;
        HandResult result;
        bool isDoubledDown;
        uint8 playerCardCount;
        uint8 dealerCardCount;
        uint8[11] playerCards;
        uint8[11] dealerCards;
    }

    /// @notice Maps a VRF requestId to its hand and action context
    struct VrfRequest {
        uint handId;
        VrfAction action;
    }

    /// @notice Per-hand split state. Allocated only when a hand is split. Hand 1's data
    /// (cards, amount, result) stays on the parent Hand struct; this holds hand 2's state
    /// plus shared flags. `activeHand` is 1 while the player acts on hand 1, 2 once hand 1
    /// is final (stand/bust/double-resolved)
    struct SplitState {
        uint amount2;
        uint payout2;
        uint8 player2CardCount;
        uint8 activeHand;
        bool isAceSplit;
        bool isDoubled2;
        HandResult result2;
        uint8[11] player2Cards;
    }

    struct CoreAddresses {
        address owner;
        address manager;
        address priceFeed;
        address vrfCoordinator;
    }

    struct CollateralConfig {
        address usdc;
        address weth;
        address over;
        bytes32 wethPriceFeedKey;
        bytes32 overPriceFeedKey;
    }

    struct VrfConfig {
        uint256 subscriptionId;
        bytes32 keyHash;
        uint32 callbackGasLimit;
        uint16 requestConfirmations;
        bool nativePayment;
    }

    /* ========== STATE VARIABLES ========== */

    /// @notice Manager contract used for whitelist-based role checks
    ISportsAMMV2Manager public manager;

    /// @notice Price feed used for collateral normalization to USD
    IPriceFeed public priceFeed;

    /// @notice Chainlink VRF coordinator
    IVRFCoordinatorV2Plus public vrfCoordinator;

    /// @notice Supported collateral addresses
    address public usdc;
    address public weth;
    address public over;

    /// @notice Maximum allowed profit per hand in USD, normalized to 18 decimals
    uint public maxProfitUsd;

    /// @notice Timeout after which a pending hand can be cancelled
    uint public cancelTimeout;

    /// @notice Next hand id to assign
    uint public nextHandId;

    /// @notice Chainlink VRF v2.5 subscription id
    uint256 public subscriptionId;

    /// @notice Chainlink VRF key hash / gas lane
    bytes32 public keyHash;

    /// @notice Gas limit for VRF callback execution
    uint32 public callbackGasLimit;

    /// @notice Number of confirmations for VRF request
    uint16 public requestConfirmations;

    /// @notice Whether VRF request is paid in native token
    bool public nativePayment;

    /// @notice Whether a collateral is supported
    mapping(address => bool) public supportedCollateral;

    /// @notice Price feed key per collateral for non-USDC assets
    mapping(address => bytes32) public priceFeedKeyPerCollateral;

    /// @notice Stored hands by hand id
    mapping(uint => Hand) internal hands;

    /// @notice Maps VRF request id to its context
    mapping(uint => VrfRequest) public vrfRequests;

    /// @notice Tracks reserved house-side profit liability for all pending hands per collateral
    mapping(address => uint) public reservedProfitPerCollateral;

    /// @notice Hand IDs per user for history queries
    mapping(address => uint[]) private userHandIds;

    /// @notice Timestamp of last VRF request per hand (for cancel timeout)
    mapping(uint => uint) public lastRequestAt;

    /// @notice Free bets holder contract address
    address public freeBetsHolder;

    /// @notice Whether a hand was placed with a free bet
    mapping(uint => bool) public isFreeBet;

    /// @notice Referrals contract
    IReferrals public referrals;

    /// @notice Whether a hand has been split. Appended for upgrade safety
    mapping(uint => bool) public isSplit;

    /// @notice Per-hand split state, allocated only when `split()` is called
    mapping(uint => SplitState) internal splitStates;

    /* ========== PUBLIC / EXTERNAL METHODS ========== */

    /// @notice Initializes the blackjack contract
    function initialize(
        CoreAddresses calldata core,
        CollateralConfig calldata collateralConfig,
        uint _maxProfitUsd,
        uint _cancelTimeout,
        VrfConfig calldata vrfConfig
    ) external initializer {
        if (
            core.owner == address(0) ||
            core.manager == address(0) ||
            core.priceFeed == address(0) ||
            core.vrfCoordinator == address(0) ||
            collateralConfig.usdc == address(0) ||
            collateralConfig.weth == address(0) ||
            collateralConfig.over == address(0)
        ) {
            revert InvalidAddress();
        }

        if (_maxProfitUsd == 0) revert InvalidAmount();
        if (vrfConfig.callbackGasLimit == 0) revert InvalidAmount();

        setOwner(core.owner);
        initNonReentrant();

        manager = ISportsAMMV2Manager(core.manager);
        priceFeed = IPriceFeed(core.priceFeed);
        vrfCoordinator = IVRFCoordinatorV2Plus(core.vrfCoordinator);

        usdc = collateralConfig.usdc;
        weth = collateralConfig.weth;
        over = collateralConfig.over;

        supportedCollateral[collateralConfig.usdc] = true;
        supportedCollateral[collateralConfig.weth] = true;
        supportedCollateral[collateralConfig.over] = true;

        priceFeedKeyPerCollateral[collateralConfig.weth] = collateralConfig.wethPriceFeedKey;
        priceFeedKeyPerCollateral[collateralConfig.over] = collateralConfig.overPriceFeedKey;

        if (_cancelTimeout < MIN_CANCEL_TIMEOUT) revert InvalidAmount();
        maxProfitUsd = _maxProfitUsd;
        cancelTimeout = _cancelTimeout;

        subscriptionId = vrfConfig.subscriptionId;
        keyHash = vrfConfig.keyHash;
        callbackGasLimit = vrfConfig.callbackGasLimit;
        requestConfirmations = vrfConfig.requestConfirmations;
        nativePayment = vrfConfig.nativePayment;

        nextHandId = 1;
    }

    /// @notice Places a blackjack bet and requests initial deal from VRF
    /// @param collateral Collateral token address
    /// @param amount Amount of collateral to stake
    /// @return handId Newly created hand id
    /// @return requestId Chainlink VRF request id
    function placeBet(
        address collateral,
        uint amount,
        address _referrer
    ) external nonReentrant notPaused returns (uint handId, uint requestId) {
        _requireSupported(collateral);
        IERC20(collateral).safeTransferFrom(msg.sender, address(this), amount);
        if (_referrer != address(0) && address(referrals) != address(0)) {
            referrals.setReferrer(_referrer, msg.sender);
        }
        return _placeBet(msg.sender, collateral, amount, false);
    }

    /// @notice Places a blackjack bet using free bet balance
    function placeBetWithFreeBet(
        address collateral,
        uint amount
    ) external nonReentrant notPaused returns (uint handId, uint requestId) {
        _requireSupported(collateral);
        IFreeBetsHolder(freeBetsHolder).useFreeBet(msg.sender, collateral, amount);
        return _placeBet(msg.sender, collateral, amount, true);
    }

    function _placeBet(
        address user,
        address collateral,
        uint amount,
        bool _isFreeBet
    ) internal returns (uint handId, uint requestId) {
        // `collateral` already validated by the external wrappers (placeBet / placeBetWithFreeBet)
        if (amount == 0) revert InvalidAmount();

        uint amountUsd = _getUsdValue(collateral, amount);
        if (amountUsd < MIN_BET_USD) revert InvalidAmount();

        // Max profit is blackjack payout (3:2)
        uint potentialProfitCollateral = (amount * BLACKJACK_PAYOUT_NUMERATOR) / BLACKJACK_PAYOUT_DENOMINATOR;
        uint potentialProfitUsd = _getUsdValue(collateral, potentialProfitCollateral);

        if (potentialProfitUsd > maxProfitUsd) revert InvalidAmount();

        _reserveOrRevert(collateral, amount + potentialProfitCollateral);

        requestId = _requestRandomWords(2);

        handId = nextHandId++;
        Hand storage hand = hands[handId];
        hand.user = user;
        hand.collateral = collateral;
        hand.amount = amount;
        hand.placedAt = block.timestamp;
        hand.reservedProfit = potentialProfitCollateral;
        if (_isFreeBet) isFreeBet[handId] = true;
        _registerVrf(handId, hand, requestId, VrfAction.DEAL, HandStatus.AWAITING_DEAL);
        userHandIds[user].push(handId);

        emit HandCreated(handId, requestId, user, collateral, amount);
    }

    /// @notice Requests a hit (one additional card) for a player's hand
    /// @param handId Hand id to hit
    /// @return requestId Chainlink VRF request id
    function hit(uint handId) external nonReentrant notPaused returns (uint requestId) {
        Hand storage hand = hands[handId];

        _requireOwnedPlayerTurn(hand);

        requestId = _requestRandomWords(1);
        _registerVrf(handId, hand, requestId, VrfAction.HIT, HandStatus.AWAITING_HIT);
        emit HitRequested(handId, requestId, msg.sender);
    }

    /// @notice Player stands — dealer reveals hidden card and draws
    /// @param handId Hand id to stand on
    /// @return requestId Chainlink VRF request id
    function stand(uint handId) external nonReentrant notPaused returns (uint requestId) {
        Hand storage hand = hands[handId];

        _requireOwnedPlayerTurn(hand);

        // In split mode, stand on hand 1 just advances to hand 2 — no VRF, no dealer play yet.
        if (isSplit[handId] && splitStates[handId].activeHand == 1) {
            splitStates[handId].activeHand = 2;
            // Reset cancel timeout baseline since no VRF was issued to refresh it naturally.
            lastRequestAt[handId] = block.timestamp;
            emit SplitHandAdvanced(handId, msg.sender);
            return 0;
        }

        requestId = _requestRandomWords(10);
        _registerVrf(handId, hand, requestId, VrfAction.STAND, HandStatus.AWAITING_STAND);
        emit StandRequested(handId, requestId, msg.sender);
    }

    /// @notice Player doubles down — doubles bet, receives one card, then dealer plays
    /// @param handId Hand id to double down on
    /// @return requestId Chainlink VRF request id
    function doubleDown(uint handId) external nonReentrant notPaused returns (uint requestId) {
        Hand storage hand = hands[handId];

        _requireOwnedPlayerTurn(hand);
        if (isFreeBet[handId]) revert InvalidHandStatus();

        bool isSpl = isSplit[handId];
        SplitState storage ss = splitStates[handId];

        // Ace-split hands are one-card-only — never reach PLAYER_TURN for hand 1/2 in that path,
        // so no explicit ace-split check needed here.
        uint activeCardCount;
        uint activeAmount;
        if (isSpl) {
            if (ss.activeHand == 1) {
                activeCardCount = hand.playerCardCount;
                activeAmount = hand.amount;
            } else {
                activeCardCount = ss.player2CardCount;
                activeAmount = ss.amount2;
            }
        } else {
            activeCardCount = hand.playerCardCount;
            activeAmount = hand.amount;
        }
        if (activeCardCount != 2) revert InvalidHandStatus();

        // Transfer matching stake for the doubled hand
        IERC20(hand.collateral).safeTransferFrom(msg.sender, address(this), activeAmount);

        // Reservation bump: doubling a hand adds the new stake (activeAmount) plus the increase in
        // max profit (another activeAmount, as profit cap goes from 1x to 2x of original per-hand stake)
        _reserveOrRevert(hand.collateral, activeAmount * 2);
        hand.reservedProfit += activeAmount;

        if (isSpl) {
            if (ss.activeHand == 1) {
                hand.amount = activeAmount * 2;
                hand.isDoubledDown = true;
                requestId = _requestRandomWords(1); // just the doubled card, no dealer yet
            } else {
                ss.amount2 = activeAmount * 2;
                ss.isDoubled2 = true;
                requestId = _requestRandomWords(11); // card + dealer
            }
        } else {
            hand.amount = activeAmount * 2;
            hand.isDoubledDown = true;
            requestId = _requestRandomWords(11);
        }

        _registerVrf(handId, hand, requestId, VrfAction.DOUBLE_DOWN, HandStatus.AWAITING_DOUBLE);
        emit DoubleDownRequested(handId, requestId, msg.sender, activeAmount);
    }

    /// @notice Splits a starting pair into two hands. User puts up an additional stake equal to
    /// the original. Each hand then plays independently (hit/stand/double). Aces split one card
    /// each and auto-resolve in the same VRF fulfillment (bundled 12-word request)
    /// @param handId Hand id to split
    /// @return requestId Chainlink VRF request id
    function split(uint handId) external nonReentrant notPaused returns (uint requestId) {
        Hand storage hand = hands[handId];
        _requireOwnedPlayerTurn(hand);
        if (hand.playerCardCount != 2) revert InvalidHandStatus();
        if (isSplit[handId]) revert InvalidHandStatus();
        if (isFreeBet[handId]) revert InvalidHandStatus();
        if (_cardValue(hand.playerCards[0]) != _cardValue(hand.playerCards[1])) revert InvalidHandStatus();

        // Pull matching stake for hand 2
        IERC20(hand.collateral).safeTransferFrom(msg.sender, address(this), hand.amount);

        // Update reservation: BJ payout no longer possible, each hand can win 1x.
        // newProfitReservation = 2 * hand.amount (two hands, each capped at 1x profit).
        // Aggregator delta = new stake pulled in (hand.amount) + profit delta (always positive:
        // 2*amount vs amount*3/2).
        uint newReservedProfit = hand.amount * 2;
        uint oldReservedProfit = hand.reservedProfit;
        _reserveOrRevert(hand.collateral, hand.amount + (newReservedProfit - oldReservedProfit));
        hand.reservedProfit = newReservedProfit;

        // Allocate split state
        bool aceSplit = hand.playerCards[0] == ACE_RANK;
        SplitState storage ss = splitStates[handId];
        ss.amount2 = hand.amount;
        ss.activeHand = 1;
        ss.isAceSplit = aceSplit;
        ss.player2Cards[0] = hand.playerCards[1];
        ss.player2CardCount = 1;
        // Clear hand 1's second card slot, reduce count to 1
        hand.playerCards[1] = 0;
        hand.playerCardCount = 1;
        isSplit[handId] = true;

        // 2 words for normal split (one second card per hand).
        // 12 words for ace split: 2 player cards + 1 dealer hidden + 9 dealer draws (auto-resolve).
        uint32 numWords = aceSplit ? 12 : 2;
        requestId = _requestRandomWords(numWords);

        _registerVrf(handId, hand, requestId, VrfAction.SPLIT, HandStatus.AWAITING_SPLIT);
        emit HandSplit(handId, requestId, msg.sender, hand.amount, aceSplit);
    }

    /// @notice Cancels a hand awaiting VRF response after timeout and refunds the stake
    /// @param handId Hand id to cancel
    function cancelHand(uint handId) external nonReentrant {
        Hand storage hand = hands[handId];

        if (hand.status == HandStatus.NONE) revert HandNotFound();
        if (hand.user != msg.sender) revert HandNotOwner();
        _requireCancellable(hand.status, false);
        if (block.timestamp < lastRequestAt[handId] + cancelTimeout) revert InvalidHandStatus();

        _cancelHand(handId, false);
    }

    /// @notice Emergency cancels a pending hand and refunds the stake
    /// @param handId Hand id to cancel
    function adminCancelHand(uint handId) external onlyResolver nonReentrant {
        Hand storage hand = hands[handId];

        if (hand.status == HandStatus.NONE) revert HandNotFound();
        _requireCancellable(hand.status, true);

        _cancelHand(handId, true);
    }

    /// @notice Pauses or unpauses the contract
    /// @param _paused True to pause, false to unpause
    function setPausedByRole(bool _paused) external onlyPauser {
        if (paused != _paused) {
            paused = _paused;
            if (_paused) {
                lastPauseTime = block.timestamp;
            }
            emit PauseChanged(_paused);
        }
    }

    /// @notice Coordinator-only VRF entrypoint
    function rawFulfillRandomWords(uint256 requestId, uint256[] calldata randomWords) external nonReentrant {
        if (msg.sender != address(vrfCoordinator)) revert InvalidSender();
        _fulfillRandomWords(requestId, randomWords);
    }

    /* ========== INTERNAL / PRIVATE ========== */

    /// @notice Routes VRF fulfillment to the appropriate handler
    function _fulfillRandomWords(uint256 requestId, uint256[] calldata randomWords) internal {
        VrfRequest storage req = vrfRequests[requestId];
        uint handId = req.handId;
        if (handId == 0) return;

        Hand storage hand = hands[handId];

        if (req.action == VrfAction.DEAL) {
            _handleDeal(handId, hand, randomWords);
        } else if (req.action == VrfAction.HIT) {
            _handleHit(handId, hand, randomWords);
        } else if (req.action == VrfAction.STAND) {
            _handleStand(handId, hand, randomWords);
        } else if (req.action == VrfAction.DOUBLE_DOWN) {
            _handleDoubleDown(handId, hand, randomWords);
        } else if (req.action == VrfAction.SPLIT) {
            _handleSplit(handId, hand, randomWords);
        }
    }

    /// @notice Handles initial card deal after VRF fulfillment
    function _handleDeal(uint handId, Hand storage hand, uint256[] calldata randomWords) internal {
        if (hand.status != HandStatus.AWAITING_DEAL) return;

        // Derive 4 cards from 2 random words
        uint8 playerCard1 = _deriveCard(randomWords[0], 0);
        uint8 playerCard2 = _deriveCard(randomWords[1], 0);
        uint8 dealerFaceUp = _deriveCard(randomWords[0], 1);
        uint8 dealerHidden = _deriveCard(randomWords[1], 1);

        hand.playerCards[0] = playerCard1;
        hand.playerCards[1] = playerCard2;
        hand.playerCardCount = 2;
        hand.dealerCards[0] = dealerFaceUp;
        hand.dealerCardCount = 1;

        emit CardsDealt(handId, hand.user, playerCard1, playerCard2, dealerFaceUp);

        // Check for player natural blackjack
        bool playerBJ = _isBlackjack(playerCard1, playerCard2);

        if (playerBJ) {
            // Reveal dealer hidden card to check for push
            hand.dealerCards[1] = dealerHidden;
            hand.dealerCardCount = 2;
            _resolveHand(
                handId,
                hand,
                _isBlackjack(dealerFaceUp, dealerHidden) ? HandResult.PUSH : HandResult.PLAYER_BLACKJACK
            );
        } else {
            hand.status = HandStatus.PLAYER_TURN;
        }
    }

    /// @notice Handles a hit card after VRF fulfillment
    function _handleHit(uint handId, Hand storage hand, uint256[] calldata randomWords) internal {
        if (hand.status != HandStatus.AWAITING_HIT) return;

        uint8 newCard = _deriveCard(randomWords[0], 0);
        bool isSpl = isSplit[handId];
        SplitState storage ss = splitStates[handId];

        if (isSpl) {
            uint8 playerValue;
            if (ss.activeHand == 1) {
                hand.playerCards[hand.playerCardCount] = newCard;
                ++hand.playerCardCount;
                (playerValue, ) = _handValue(hand.playerCards, hand.playerCardCount);
                emit PlayerCardDealt(handId, hand.user, newCard, playerValue);

                // Hand 1 is "done" at >= 21 — advance to hand 2 (bust loses, 21 auto-stands)
                if (playerValue >= BLACKJACK_TARGET) {
                    ss.activeHand = 2;
                }
                hand.status = HandStatus.PLAYER_TURN;
            } else {
                ss.player2Cards[ss.player2CardCount] = newCard;
                ++ss.player2CardCount;
                (playerValue, ) = _handValue(ss.player2Cards, ss.player2CardCount);
                emit PlayerCardDealt(handId, hand.user, newCard, playerValue);

                if (playerValue >= BLACKJACK_TARGET) {
                    // Hand 2 done (bust or 21). If BOTH hands busted → resolve (no dealer needed).
                    // Otherwise remain in PLAYER_TURN: the frontend auto-submits stand(), which
                    // triggers the dealer VRF request. We can't request VRF from inside a VRF
                    // callback — Chainlink's coordinator blocks it with its reentrancyLock
                    (uint8 hand1Value, ) = _handValue(hand.playerCards, hand.playerCardCount);
                    if (hand1Value > BLACKJACK_TARGET && playerValue > BLACKJACK_TARGET) {
                        _resolveSplit(handId, hand);
                        return;
                    }
                }
                hand.status = HandStatus.PLAYER_TURN;
            }
        } else {
            hand.playerCards[hand.playerCardCount] = newCard;
            ++hand.playerCardCount;
            (uint8 playerValue, ) = _handValue(hand.playerCards, hand.playerCardCount);
            emit PlayerCardDealt(handId, hand.user, newCard, playerValue);

            if (playerValue > BLACKJACK_TARGET) {
                _resolveHand(handId, hand, HandResult.PLAYER_BUST);
            } else {
                // At 21, frontend auto-submits stand() — can't nest a VRF request from here
                hand.status = HandStatus.PLAYER_TURN;
            }
        }
    }

    /// @notice Handles stand — dealer reveals and draws, then resolves
    function _handleStand(uint handId, Hand storage hand, uint256[] calldata randomWords) internal {
        if (hand.status != HandStatus.AWAITING_STAND) return;

        uint n = randomWords.length;
        uint256[] memory mem = new uint256[](n);
        for (uint i; i < n; ++i) mem[i] = randomWords[i];
        _dealerPlayAndResolveFromMemory(handId, hand, mem);
    }

    /// @notice Handles double down — one player card, then dealer plays
    function _handleDoubleDown(uint handId, Hand storage hand, uint256[] calldata randomWords) internal {
        if (hand.status != HandStatus.AWAITING_DOUBLE) return;

        uint8 newCard = _deriveCard(randomWords[0], 0);
        bool isSpl = isSplit[handId];
        SplitState storage ss = splitStates[handId];

        if (isSpl && ss.activeHand == 1) {
            // Split + double on hand 1: 1 VRF word, deal card, advance to hand 2 regardless of bust.
            hand.playerCards[hand.playerCardCount] = newCard;
            ++hand.playerCardCount;
            (uint8 p1Value, ) = _handValue(hand.playerCards, hand.playerCardCount);
            emit PlayerCardDealt(handId, hand.user, newCard, p1Value);

            ss.activeHand = 2;
            hand.status = HandStatus.PLAYER_TURN;
            return;
        }

        // Non-split, or split + double on hand 2 (11 VRF words).
        uint8 playerValue;
        if (isSpl) {
            ss.player2Cards[ss.player2CardCount] = newCard;
            ++ss.player2CardCount;
            (playerValue, ) = _handValue(ss.player2Cards, ss.player2CardCount);
        } else {
            hand.playerCards[hand.playerCardCount] = newCard;
            ++hand.playerCardCount;
            (playerValue, ) = _handValue(hand.playerCards, hand.playerCardCount);
        }
        emit PlayerCardDealt(handId, hand.user, newCard, playerValue);

        if (!isSpl && playerValue > BLACKJACK_TARGET) {
            _resolveHand(handId, hand, HandResult.PLAYER_BUST);
            return;
        }

        if (isSpl && playerValue > BLACKJACK_TARGET) {
            // Hand 2 busted via double. If hand 1 also busted, skip dealer.
            (uint8 p1Value, ) = _handValue(hand.playerCards, hand.playerCardCount);
            if (p1Value > BLACKJACK_TARGET) {
                _resolveSplit(handId, hand);
                return;
            }
        }

        // Dealer plays using randomWords[1..]. Production requests 11 words (1 player card + 10 dealer).
        uint256 dealerLen = randomWords.length - 1;
        uint256[] memory dealerWords = new uint256[](dealerLen);
        for (uint i; i < dealerLen; ++i) {
            dealerWords[i] = randomWords[i + 1];
        }
        _dealerPlayAndResolveFromMemory(handId, hand, dealerWords);
    }

    /// @notice Handles split fulfillment. Deals a second card to each split hand. For ace-split,
    /// bundles dealer play + resolution into the same fulfillment (one-card rule means the player
    /// has no remaining decisions, so front-running isn't possible)
    function _handleSplit(uint handId, Hand storage hand, uint256[] calldata randomWords) internal {
        if (hand.status != HandStatus.AWAITING_SPLIT) return;

        SplitState storage ss = splitStates[handId];

        // Deal second card to hand 1 and hand 2
        uint8 hand1Card2 = _deriveCard(randomWords[0], 0);
        uint8 hand2Card2 = _deriveCard(randomWords[1], 0);
        hand.playerCards[hand.playerCardCount] = hand1Card2;
        ++hand.playerCardCount;
        ss.player2Cards[ss.player2CardCount] = hand2Card2;
        ++ss.player2CardCount;

        if (ss.isAceSplit) {
            // One-card rule: both hands are final. Play dealer using words 2.. Production requests 12 words
            // (2 player second cards + 10 dealer: 1 hidden + up to 9 draws).
            uint256 dealerLen = randomWords.length - 2;
            uint256[] memory dealerWords = new uint256[](dealerLen);
            for (uint i; i < dealerLen; ++i) {
                dealerWords[i] = randomWords[i + 2];
            }
            _dealerPlayAndResolveFromMemory(handId, hand, dealerWords);
        } else {
            hand.status = HandStatus.PLAYER_TURN;
        }
    }

    /// @notice Reveals dealer hidden card, draws to 17+, then resolves (both single-hand and split)
    function _dealerPlayAndResolveFromMemory(uint handId, Hand storage hand, uint256[] memory randomWords) internal {
        // Reveal dealer hidden card
        uint8 hiddenCard = _deriveCard(randomWords[0], 0);
        hand.dealerCards[hand.dealerCardCount] = hiddenCard;
        ++hand.dealerCardCount;

        // Dealer draws until hard 17+ (hits on soft 17)
        uint wordIdx = 1;
        while (wordIdx < randomWords.length && hand.dealerCardCount < MAX_CARDS) {
            (uint8 dealerValue, bool dealerSoft) = _handValue(hand.dealerCards, hand.dealerCardCount);
            if (dealerValue > DEALER_STAND_THRESHOLD) break;
            if (dealerValue == DEALER_STAND_THRESHOLD && !dealerSoft) break;

            uint8 card = _deriveCard(randomWords[wordIdx], 0);
            hand.dealerCards[hand.dealerCardCount] = card;
            ++hand.dealerCardCount;
            ++wordIdx;
        }

        if (isSplit[handId]) {
            _resolveSplit(handId, hand);
            return;
        }

        (uint8 dv, ) = _handValue(hand.dealerCards, hand.dealerCardCount);
        (uint8 pv, ) = _handValue(hand.playerCards, hand.playerCardCount);
        if (dv > BLACKJACK_TARGET) {
            _resolveHand(handId, hand, HandResult.DEALER_BUST);
        } else if (pv > dv) {
            _resolveHand(handId, hand, HandResult.PLAYER_WIN);
        } else if (pv == dv) {
            _resolveHand(handId, hand, HandResult.PUSH);
        } else {
            _resolveHand(handId, hand, HandResult.DEALER_WIN);
        }
    }

    /// @notice Judges a split hand's result against the dealer (no blackjack payout path)
    function _judgeSplit(uint8 pv, uint8 dv, bool dBust) internal pure returns (HandResult r) {
        if (pv > BLACKJACK_TARGET) r = HandResult.PLAYER_BUST;
        else if (dBust) r = HandResult.DEALER_BUST;
        else if (pv > dv) r = HandResult.PLAYER_WIN;
        else if (pv == dv) r = HandResult.PUSH;
        else r = HandResult.DEALER_WIN;
    }

    /// @notice Returns payout for a split-hand result. No 3:2 BJ payout even on 21 (A+10 post-split)
    function _splitPayout(uint stake, HandResult r) internal pure returns (uint payout) {
        if (r == HandResult.PLAYER_WIN || r == HandResult.DEALER_BUST) payout = stake * 2;
        else if (r == HandResult.PUSH) payout = stake;
        // default 0
    }

    /// @notice Resolves both split hands against the dealer; single payout transfer, single
    /// referrer payment on total loss. Also used for the both-busted path where dealer never
    /// played — PLAYER_BUST short-circuits in `_judgeSplit` before any dealer comparison
    function _resolveSplit(uint handId, Hand storage hand) internal {
        SplitState storage ss = splitStates[handId];
        reservedProfitPerCollateral[hand.collateral] -= hand.amount + ss.amount2 + hand.reservedProfit;

        (uint8 dealerValue, ) = _handValue(hand.dealerCards, hand.dealerCardCount);
        bool dealerBust = dealerValue > BLACKJACK_TARGET;
        (uint8 p1v, ) = _handValue(hand.playerCards, hand.playerCardCount);
        (uint8 p2v, ) = _handValue(ss.player2Cards, ss.player2CardCount);
        HandResult r1 = _judgeSplit(p1v, dealerValue, dealerBust);
        HandResult r2 = _judgeSplit(p2v, dealerValue, dealerBust);
        uint payout1 = _splitPayout(hand.amount, r1);
        uint payout2 = _splitPayout(ss.amount2, r2);
        uint totalPayout = payout1 + payout2;

        // State update before external transfers (CEI)
        hand.result = r1;
        hand.payout = totalPayout;
        ss.result2 = r2;
        ss.payout2 = payout2;
        hand.status = HandStatus.RESOLVED;
        hand.resolvedAt = block.timestamp;

        emit HandResolved(handId, hand.requestId, hand.user, r1, totalPayout);

        if (totalPayout > 0) {
            IERC20(hand.collateral).safeTransfer(hand.user, totalPayout);
        } else {
            _payReferrer(hand.user, hand.collateral, hand.amount + ss.amount2);
        }
    }

    /// @notice Resolves a hand with payout based on result
    function _resolveHand(uint handId, Hand storage hand, HandResult _result) internal {
        reservedProfitPerCollateral[hand.collateral] -= hand.amount + hand.reservedProfit;

        uint payout;
        if (_result == HandResult.PLAYER_BLACKJACK) {
            payout = hand.amount + (hand.amount * BLACKJACK_PAYOUT_NUMERATOR) / BLACKJACK_PAYOUT_DENOMINATOR;
        } else if (_result == HandResult.PLAYER_WIN || _result == HandResult.DEALER_BUST) {
            payout = hand.amount * 2;
        } else if (_result == HandResult.PUSH) {
            payout = hand.amount;
        }

        // State update before external transfers (CEI)
        hand.payout = payout;
        hand.result = _result;
        hand.status = HandStatus.RESOLVED;
        hand.resolvedAt = block.timestamp;

        if (payout > 0) {
            if (isFreeBet[handId]) {
                IERC20(hand.collateral).safeTransfer(freeBetsHolder, payout);
                IFreeBetsHolder(freeBetsHolder).confirmCasinoBetResolved(hand.user, hand.collateral, payout, hand.amount);
            } else {
                IERC20(hand.collateral).safeTransfer(hand.user, payout);
            }
        } else if (!isFreeBet[handId]) {
            _payReferrer(hand.user, hand.collateral, hand.amount);
        }

        emit HandResolved(handId, hand.requestId, hand.user, _result, payout);
    }

    function _payReferrer(address _user, address _collateral, uint _amount) internal {
        if (address(referrals) == address(0)) return;
        address referrer = referrals.referrals(_user);
        if (referrer == address(0)) return;
        uint referrerFee = referrals.getReferrerFee(referrer);
        if (referrerFee == 0) return;
        uint referrerAmount = (_amount * referrerFee) / ONE;
        if (referrerAmount > 0) {
            try IERC20(_collateral).transfer(referrer, referrerAmount) returns (bool ok) {
                if (ok) emit ReferrerPaid(referrer, _user, referrerAmount, _amount, _collateral);
                else emit ReferrerPayoutFailed(referrer, _user, referrerAmount, _amount, _collateral);
            } catch {
                emit ReferrerPayoutFailed(referrer, _user, referrerAmount, _amount, _collateral);
            }
        }
    }

    function _cancelHand(uint handId, bool adminCancelled) internal {
        Hand storage hand = hands[handId];

        // Aggregate refund includes both legs if the hand was split. Free-bet splits are blocked
        // at `split()`, so the free-bet branch can only see a non-split hand (user never added funds)
        uint refund = hand.amount;
        if (isSplit[handId]) {
            refund += splitStates[handId].amount2;
        }

        reservedProfitPerCollateral[hand.collateral] -= refund + hand.reservedProfit;

        hand.status = HandStatus.CANCELLED;
        hand.resolvedAt = block.timestamp;

        if (isFreeBet[handId]) {
            hand.payout = 0;
            IERC20(hand.collateral).safeTransfer(freeBetsHolder, hand.amount);
            IFreeBetsHolder(freeBetsHolder).confirmCasinoBetResolved(hand.user, hand.collateral, hand.amount, hand.amount);
        } else {
            hand.payout = refund;
            IERC20(hand.collateral).safeTransfer(hand.user, refund);
        }

        emit HandCancelled(handId, hand.requestId, hand.user, refund, adminCancelled);
    }

    /// @notice Sets VRF request context on a hand and records the request mapping
    function _registerVrf(uint handId, Hand storage hand, uint requestId, VrfAction action, HandStatus status) internal {
        hand.status = status;
        hand.requestId = requestId;
        lastRequestAt[handId] = block.timestamp;
        vrfRequests[requestId] = VrfRequest({handId: handId, action: action});
    }

    /// @notice Reverts with `InvalidCollateral` if the collateral isn't supported
    function _requireSupported(address collateral) internal view {
        if (!supportedCollateral[collateral]) revert InvalidCollateral();
    }

    /// @notice Asserts the hand exists, is owned by msg.sender, and is currently the player's turn.
    /// Mirrors the 3-check guard used by hit/stand/doubleDown/split
    function _requireOwnedPlayerTurn(Hand storage hand) internal view {
        if (hand.status == HandStatus.NONE) revert HandNotFound();
        if (hand.user != msg.sender) revert HandNotOwner();
        if (hand.status != HandStatus.PLAYER_TURN) revert InvalidHandStatus();
    }

    /// @notice Reverts unless the status is one the cancel path supports. Admin path additionally
    /// accepts PLAYER_TURN so stuck hands between VRF responses can be cleared
    function _requireCancellable(HandStatus s, bool allowPlayerTurn) internal pure {
        if (
            s != HandStatus.AWAITING_DEAL &&
            s != HandStatus.AWAITING_HIT &&
            s != HandStatus.AWAITING_STAND &&
            s != HandStatus.AWAITING_DOUBLE &&
            s != HandStatus.AWAITING_SPLIT &&
            (!allowPlayerTurn || s != HandStatus.PLAYER_TURN)
        ) revert InvalidHandStatus();
    }

    /// @notice Bumps per-collateral reservation by `delta` and reverts with rollback if bankroll insufficient
    function _reserveOrRevert(address collateral, uint delta) internal {
        reservedProfitPerCollateral[collateral] += delta;
        if (IERC20(collateral).balanceOf(address(this)) < reservedProfitPerCollateral[collateral]) {
            reservedProfitPerCollateral[collateral] -= delta;
            revert InsufficientAvailableLiquidity();
        }
    }

    /// @notice Requests random words from Chainlink VRF
    function _requestRandomWords(uint32 numWords) internal returns (uint requestId) {
        requestId = vrfCoordinator.requestRandomWords(
            VRFV2PlusClient.RandomWordsRequest({
                keyHash: keyHash,
                subId: subscriptionId,
                requestConfirmations: requestConfirmations,
                callbackGasLimit: callbackGasLimit,
                numWords: numWords,
                extraArgs: VRFV2PlusClient._argsToBytes(VRFV2PlusClient.ExtraArgsV1({nativePayment: nativePayment}))
            })
        );
    }

    /// @notice Derives a card rank (1-13) from a random word using a shift index
    /// @param word Random word from VRF
    /// @param shiftIndex 0 or 1 to derive different cards from the same word
    /// @return Card rank 1-13 (1=Ace, 2-10, 11=J, 12=Q, 13=K)
    function _deriveCard(uint256 word, uint8 shiftIndex) internal pure returns (uint8) {
        return uint8(((word >> (shiftIndex * CARD_DERIVATION_SHIFT)) % CARD_RANKS) + 1);
    }

    /// @notice Returns the card value for blackjack
    /// @param rank Card rank 1-13
    /// @return Card value (Ace=11, 2-10=face, J/Q/K=10)
    function _cardValue(uint8 rank) internal pure returns (uint8) {
        if (rank == ACE_RANK) return ACE_HIGH_VALUE;
        if (rank >= FACE_CARD_RANK_THRESHOLD) return FACE_CARD_VALUE;
        return rank;
    }

    /// @notice Best hand value (<=21 where possible) plus whether an Ace is still counted as 11
    function _handValue(uint8[11] storage cards, uint8 count) internal view returns (uint8 total, bool soft) {
        uint8 aces;
        for (uint8 i; i < count; ++i) {
            total += _cardValue(cards[i]);
            if (cards[i] == ACE_RANK) ++aces;
        }
        while (total > BLACKJACK_TARGET && aces > 0) {
            total -= ACE_HIGH_DELTA;
            --aces;
        }
        soft = aces > 0;
    }

    /// @notice Returns whether two cards form a natural blackjack
    function _isBlackjack(uint8 card1, uint8 card2) internal pure returns (bool) {
        return _cardValue(card1) + _cardValue(card2) == BLACKJACK_TARGET;
    }

    /// @notice Returns the normalized price for a supported collateral
    function _getCollateralPrice(address collateral) internal view returns (uint) {
        _requireSupported(collateral);

        if (collateral == usdc) {
            return ONE;
        }

        bytes32 currencyKey = priceFeedKeyPerCollateral[collateral];
        if (currencyKey == bytes32(0)) revert InvalidCollateral();

        uint price = priceFeed.rateForCurrency(currencyKey);
        if (price == 0) revert InvalidCollateral();

        return price;
    }

    /// @notice Converts collateral amount into USD value normalized to 18 decimals
    function _getUsdValue(address collateral, uint amount) internal view returns (uint) {
        if (collateral == usdc) {
            return (amount * ONE) / USDC_UNIT;
        }

        uint price = _getCollateralPrice(collateral);
        return (amount * price) / ONE;
    }

    /* ========== GETTERS ========== */

    /// @notice Returns core hand data
    function getHandBase(
        uint handId
    )
        external
        view
        returns (
            address user,
            address collateral,
            uint amount,
            uint payout,
            uint requestId,
            uint placedAt,
            uint resolvedAt,
            uint reservedProfit
        )
    {
        Hand storage h = hands[handId];
        return (h.user, h.collateral, h.amount, h.payout, h.requestId, h.placedAt, h.resolvedAt, h.reservedProfit);
    }

    /// @notice Returns hand status and result details
    function getHandDetails(
        uint handId
    )
        external
        view
        returns (HandStatus status, HandResult result, bool isDoubledDown, uint8 playerCardCount, uint8 dealerCardCount)
    {
        Hand storage h = hands[handId];
        return (h.status, h.result, h.isDoubledDown, h.playerCardCount, h.dealerCardCount);
    }

    /// @notice Returns the maximum potential payout for a bet amount (blackjack 3:2)
    function getMaxPayout(uint amount) external pure returns (uint) {
        return amount + (amount * BLACKJACK_PAYOUT_NUMERATOR) / BLACKJACK_PAYOUT_DENOMINATOR;
    }

    /// @notice Returns normalized collateral price
    function getCollateralPrice(address collateral) external view returns (uint) {
        return _getCollateralPrice(collateral);
    }

    /// @notice Returns currently available liquidity for a collateral after reserved profit
    function getAvailableLiquidity(address collateral) external view returns (uint) {
        _requireSupported(collateral);
        uint balance = IERC20(collateral).balanceOf(address(this));
        uint reserved = reservedProfitPerCollateral[collateral];
        return balance > reserved ? balance - reserved : 0;
    }

    /// @notice Returns the number of hands placed by a user
    function getUserHandCount(address user) external view returns (uint) {
        return userHandIds[user].length;
    }

    /// @notice Returns hand IDs for a user's hands with pagination (reverse chronological)
    function getUserHandIds(address user, uint offset, uint limit) external view returns (uint[] memory ids) {
        uint[] storage allIds = userHandIds[user];
        uint len = allIds.length;
        if (offset >= len) return new uint[](0);
        uint remaining = len - offset;
        uint count = remaining < limit ? remaining : limit;
        ids = new uint[](count);
        for (uint i; i < count; ++i) {
            ids[i] = allIds[len - 1 - offset - i];
        }
    }

    /// @notice Returns recent hand IDs with pagination (reverse chronological)
    function getRecentHandIds(uint offset, uint limit) external view returns (uint[] memory ids) {
        uint latest = nextHandId - 1;
        if (offset >= latest) return new uint[](0);
        uint start = latest - offset;
        uint count = start < limit ? start : limit;
        ids = new uint[](count);
        for (uint i; i < count; ++i) {
            ids[i] = start - i;
        }
    }

    /// @notice Returns player and dealer cards for a hand
    function getHandCards(uint handId) external view returns (uint8[] memory playerCards, uint8[] memory dealerCards) {
        Hand storage h = hands[handId];
        playerCards = new uint8[](h.playerCardCount);
        dealerCards = new uint8[](h.dealerCardCount);
        for (uint8 i; i < h.playerCardCount; ++i) playerCards[i] = h.playerCards[i];
        for (uint8 i; i < h.dealerCardCount; ++i) dealerCards[i] = h.dealerCards[i];
    }

    /// @notice Returns split state for a hand. Caller should first check `isSplit[handId]`
    function getSplitDetails(
        uint handId
    )
        external
        view
        returns (
            uint amount2,
            uint payout2,
            uint8 player2CardCount,
            uint8 activeHand,
            bool isAceSplit,
            bool isDoubled2,
            HandResult result2,
            uint8[] memory player2Cards
        )
    {
        SplitState storage s = splitStates[handId];
        player2Cards = new uint8[](s.player2CardCount);
        for (uint8 i; i < s.player2CardCount; ++i) player2Cards[i] = s.player2Cards[i];
        return (s.amount2, s.payout2, s.player2CardCount, s.activeHand, s.isAceSplit, s.isDoubled2, s.result2, player2Cards);
    }

    /* ========== SETTERS ========== */

    /// @notice Sets risk parameters. Pass zero to skip a field. `_cancelTimeout` below
    /// `MIN_CANCEL_TIMEOUT` is rejected (use 0 to leave it untouched)
    function setRiskParams(uint _maxProfitUsd, uint _cancelTimeout) external onlyRiskManager {
        if (_maxProfitUsd != 0) maxProfitUsd = _maxProfitUsd;
        if (_cancelTimeout != 0) {
            if (_cancelTimeout < MIN_CANCEL_TIMEOUT) revert InvalidAmount();
            cancelTimeout = _cancelTimeout;
        }
        emit RiskParamsChanged(_maxProfitUsd, _cancelTimeout);
    }

    /// @notice Sets a collateral's support flag and price-feed key in one call. Both values are
    /// always written — pass the current values for any field you want to leave unchanged
    function setCollateralConfig(address collateral, bytes32 currencyKey, bool isSupported) external onlyRiskManager {
        if (collateral == address(0)) revert InvalidAddress();
        supportedCollateral[collateral] = isSupported;
        priceFeedKeyPerCollateral[collateral] = currencyKey;
        emit CollateralConfigChanged(collateral, currencyKey, isSupported);
    }

    /// @notice Sets protocol addresses in one call. Pass address(0) for any slot you want to skip.
    /// Note: `freeBetsHolder` and `referrals` cannot be cleared via this path — use a dedicated
    /// re-deployment if you need to detach them
    function setAddresses(
        address _manager,
        address _priceFeed,
        address _vrfCoordinator,
        address _freeBetsHolder,
        address _referrals
    ) external onlyOwner {
        if (_manager != address(0)) manager = ISportsAMMV2Manager(_manager);
        if (_priceFeed != address(0)) priceFeed = IPriceFeed(_priceFeed);
        if (_vrfCoordinator != address(0)) vrfCoordinator = IVRFCoordinatorV2Plus(_vrfCoordinator);
        if (_freeBetsHolder != address(0)) freeBetsHolder = _freeBetsHolder;
        if (_referrals != address(0)) referrals = IReferrals(_referrals);
        emit AddressesChanged(_manager, _priceFeed, _vrfCoordinator, _freeBetsHolder, _referrals);
    }

    /// @notice Withdraws collateral from the contract bankroll
    function withdrawCollateral(address _collateral, address _recipient, uint _amount) external onlyOwner {
        uint balance = IERC20(_collateral).balanceOf(address(this));
        uint reserved = reservedProfitPerCollateral[_collateral];
        if (_amount > balance || balance - _amount < reserved) revert InsufficientAvailableLiquidity();
        address recipient = _recipient == address(0) ? owner : _recipient;
        IERC20(_collateral).safeTransfer(recipient, _amount);
        emit WithdrawnCollateral(_collateral, recipient, _amount);
    }

    /// @notice Sets Chainlink VRF configuration
    function setVrfConfig(
        uint256 _subscriptionId,
        bytes32 _keyHash,
        uint32 _callbackGasLimit,
        uint16 _requestConfirmations,
        bool _nativePayment
    ) external onlyOwner {
        if (_subscriptionId == 0) revert InvalidAmount();
        if (_keyHash == bytes32(0)) revert InvalidAmount();
        if (_callbackGasLimit == 0) revert InvalidAmount();

        subscriptionId = _subscriptionId;
        keyHash = _keyHash;
        callbackGasLimit = _callbackGasLimit;
        requestConfirmations = _requestConfirmations;
        nativePayment = _nativePayment;

        emit VrfConfigChanged(_subscriptionId, _keyHash, _callbackGasLimit, _requestConfirmations, _nativePayment);
    }

    /* ========== MODIFIERS ========== */

    function _requireRole(ISportsAMMV2Manager.Role role) internal view {
        if (msg.sender != owner && !manager.isWhitelistedAddress(msg.sender, role)) {
            revert InvalidSender();
        }
    }

    modifier onlyRiskManager() {
        _requireRole(ISportsAMMV2Manager.Role.RISK_MANAGING);
        _;
    }
    modifier onlyResolver() {
        _requireRole(ISportsAMMV2Manager.Role.MARKET_RESOLVING);
        _;
    }
    modifier onlyPauser() {
        _requireRole(ISportsAMMV2Manager.Role.TICKET_PAUSER);
        _;
    }

    /* ========== EVENTS ========== */

    event HandCreated(uint indexed handId, uint indexed requestId, address indexed user, address collateral, uint amount);

    event CardsDealt(uint indexed handId, address indexed user, uint8 playerCard1, uint8 playerCard2, uint8 dealerFaceUp);

    event HitRequested(uint indexed handId, uint indexed requestId, address indexed user);

    event PlayerCardDealt(uint indexed handId, address indexed user, uint8 card, uint8 handValue);

    event StandRequested(uint indexed handId, uint indexed requestId, address indexed user);

    event SplitHandAdvanced(uint indexed handId, address indexed user);

    event DoubleDownRequested(uint indexed handId, uint indexed requestId, address indexed user, uint additionalAmount);

    event HandSplit(
        uint indexed handId,
        uint indexed requestId,
        address indexed user,
        uint additionalAmount,
        bool isAceSplit
    );

    event HandResolved(uint indexed handId, uint indexed requestId, address indexed user, HandResult result, uint payout);

    event HandCancelled(
        uint indexed handId,
        uint indexed requestId,
        address indexed user,
        uint refundedAmount,
        bool adminCancelled
    );

    event RiskParamsChanged(uint maxProfitUsd, uint cancelTimeout);
    event AddressesChanged(
        address manager,
        address priceFeed,
        address vrfCoordinator,
        address freeBetsHolder,
        address referrals
    );
    event CollateralConfigChanged(address collateral, bytes32 currencyKey, bool supported);
    event ReferrerPaid(address indexed referrer, address indexed user, uint amount, uint betAmount, address collateral);
    event ReferrerPayoutFailed(
        address indexed referrer,
        address indexed user,
        uint amount,
        uint betAmount,
        address collateral
    );
    event WithdrawnCollateral(address indexed collateral, address indexed recipient, uint amount);
    event VrfConfigChanged(
        uint256 subscriptionId,
        bytes32 keyHash,
        uint32 callbackGasLimit,
        uint16 requestConfirmations,
        bool nativePayment
    );
}

contracts/core/Casino/CasinoCoreV2.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";

import "chainlink-vrf/src/v0.8/vrf/dev/interfaces/IVRFCoordinatorV2Plus.sol";
import "chainlink-vrf/src/v0.8/vrf/dev/libraries/VRFV2PlusClient.sol";

// internal
import "../../utils/proxy/ProxyReentrancyGuard.sol";
import "../../utils/proxy/ProxyOwned.sol";
import "../../utils/proxy/ProxyPausable.sol";
import "@thales-dao/contracts/contracts/interfaces/IPriceFeed.sol";
import "@thales-dao/contracts/contracts/interfaces/IReferrals.sol";

import "../../interfaces/ISportsAMMV2Manager.sol";
import "../../interfaces/IFreeBetsHolder.sol";
import "../../interfaces/ICasinoCoreV2.sol";
import "../../interfaces/ICasinoGameCallback.sol";

/// @title CasinoCoreV2
/// @author Overtime
/// @notice Singleton treasury and shared services for the V2 casino games (Three Card Poker,
/// Overtime Hold'em, Plinko, Hi-Lo). Holds USDC/WETH/OVER liquidity, the VRF
/// subscription configuration, the supported-collateral whitelist, and the free-bets / referrals
/// wiring. Registered games call into core for funds movement, randomness, and settlement
/// bookkeeping; core enforces a per-game cumulative-net-loss circuit breaker that auto-pauses
/// the offending game when its running P&L drops below the configured threshold.
/// @dev Existing v1 games (Roulette/Dice/Blackjack/Baccarat/Slots) are NOT migrated here. They
/// continue on their own per-contract bankrolls
contract CasinoCoreV2 is ICasinoCoreV2, Initializable, ProxyOwned, ProxyPausable, ProxyReentrancyGuard {
    using SafeERC20 for IERC20;

    /* ========== CONSTANTS ========== */

    uint private constant ONE = 1e18;
    uint private constant USDC_UNIT = 1e6;

    /// @notice Lower bound on `cancelTimeout` enforced at config time
    uint public constant MIN_CANCEL_TIMEOUT = 30;

    /// @notice Default per-game net-loss circuit breaker if a game has no override (USD, 18-dec)
    uint public constant DEFAULT_MAX_NET_LOSS_PER_GAME_USD = 1000e18;

    /* ========== ERRORS ========== */

    error InvalidAddress();
    error InvalidSender();
    error InvalidCollateral();
    error InvalidPrice();
    error InvalidAmount();
    error InvalidConfig();
    error InsufficientAvailableLiquidity();
    error GameNotRegistered();
    error GameAlreadyRegistered();
    error GameNotActive();
    error GameHasReservations();
    error VrfRequestUnknown();
    error UnderReservation();

    /* ========== STRUCTS ========== */

    struct CoreAddresses {
        address owner;
        address manager;
        address priceFeed;
        address vrfCoordinator;
        address freeBetsHolder;
        address referrals;
    }

    struct CollateralConfig {
        address usdc;
        address weth;
        address over;
        bytes32 wethPriceFeedKey;
        bytes32 overPriceFeedKey;
    }

    struct VrfConfig {
        uint256 subscriptionId;
        bytes32 keyHash;
        uint32 callbackGasLimit;
        uint16 requestConfirmations;
        bool nativePayment;
    }

    /* ========== STATE ========== */

    // --- protocol wiring ---
    ISportsAMMV2Manager public manager;
    IPriceFeed public priceFeed;
    IVRFCoordinatorV2Plus public vrfCoordinator;
    address public override freeBetsHolder;
    IReferrals public referrals;

    // --- canonical collateral addresses (kept for parity with v1 games) ---
    address public override usdc;
    address public override weth;
    address public override over;

    // --- shared risk params ---
    uint public override maxProfitUsd;
    /// @notice Operational SLA — the soonest the operator commits to admin-cancel a stalled
    /// VRF bet, in seconds. Not enforced on-chain anywhere (V2 games removed user-callable
    /// `cancelBet` to close a VRF mempool front-run surface, leaving `adminCancelBet` as the
    /// only path; admin is trusted, no timeout gate). Retained so FE can surface "max wait
    /// before refund" and so future user-callable cancel paths could re-enable the gate without
    /// a storage layout change. Bound by `MIN_CANCEL_TIMEOUT` at config time
    uint public override cancelTimeout;

    // --- VRF v2.5 subscription ---
    uint256 public override subscriptionId;
    bytes32 public override keyHash;
    uint32 public override callbackGasLimit;
    uint16 public override requestConfirmations;
    bool public override nativePayment;

    // --- collateral whitelist + price-feed keys ---
    mapping(address => bool) public override supportedCollateral;
    mapping(address => bytes32) public override priceFeedKeyPerCollateral;

    // --- per-collateral aggregate reservation across all games ---
    // NOTE: despite the name, stores reserved PAYOUT (stake + worst-case profit), not just
    // profit. Every game feeds `reserveOrRevert` the full max-outflow figure. Name is historical
    mapping(address => uint) public override reservedProfitPerCollateral;

    // --- per-game per-collateral reservation (for deregister safety + analytics) ---
    // Same semantics: reserved PAYOUT, not just profit
    mapping(address => mapping(address => uint)) public override reservedProfitPerGame;

    // --- registered games ---
    mapping(address => bool) public override isGameRegistered;
    address[] private _registeredGamesList;
    mapping(address => uint256) private _registeredGameIndex;

    // --- per-game pause + circuit breaker ---
    mapping(address => bool) public override gamePaused;
    mapping(address => bool) public override gameAutoPaused;
    mapping(address => int256) public override houseNetUsd;
    mapping(address => uint256) public override maxNetLossPerGameUsd;

    /// @notice Override of the default circuit-breaker threshold. Mutate via
    /// `setMaxNetLossPerGameUsd` and `setDefaultMaxNetLossPerGameUsd`. Reads should go through
    /// the `_maxNetLossUsd(game)` helper which falls back to the default
    uint256 public override defaultMaxNetLossPerGameUsd;

    // --- VRF dispatch ---
    mapping(uint256 => address) public override requestIdToGame;

    // --- enumerable collateral list (so deregisterGame can check reservations across all
    // configured collaterals, not just the canonical 3). Maintained by setCollateralConfig.
    // Placed here (after `requestIdToGame`) rather than alongside `supportedCollateral` to
    // preserve storage layout compatibility with the original v2 deploy
    address[] private _supportedCollateralsList;
    mapping(address => uint256) private _supportedCollateralIndex;

    // --- per-game override of the global `maxProfitUsd` cap. 0 = no override (fall back to
    // global). Set via `setMaxProfitUsdOverride`. Read via `effectiveMaxProfitUsd(game)` from
    // games at placeBet time. Lets V2 keep a single treasury while letting risk vary across games
    // with very different worst-case payout structures (e.g. HiLo 25x vs Hold'em 102x ante)
    mapping(address => uint256) public override maxProfitUsdOverride;

    // --- per-game min/max bet floor/ceiling in USD-18-dec. 0 = "no override" (use global
    // defaults / no max). Read via `effectiveMinBetUsd(game)` / `effectiveMaxBetUsd(game)`.
    // Lets poker games gate ante size at placement so the soft-cap on payout (driven by
    // `maxProfitUsdOverride`) doesn't have to keep up with arbitrarily-large stakes
    mapping(address => uint256) public override minBetPerGameUsd;
    mapping(address => uint256) public override maxBetPerGameUsd;

    /// @notice Per-collateral sum of stakes from bets that are placed but not yet terminated.
    /// `balanceOf(core) - pendingStakes` is the bankroll genuinely available to back NEW profit
    /// reservations. Without this, `reserveOrRevert` treats unsettled stakes as bankroll and can
    /// briefly over-reserve under concurrent placement. Incremented in `pullFromUser` /
    /// `useFreeBet`; decremented in `recordSettlement` (the single terminal hook every game
    /// invokes — resolve, fold, and cancel paths all funnel through it post-audit fix)
    mapping(address => uint256) public override pendingStakesPerCollateral;

    /* ========== INITIALIZER ========== */

    /// @notice Initializes the treasury. Run once behind a TransparentUpgradeableProxy
    function initialize(
        CoreAddresses calldata core,
        CollateralConfig calldata collateralConfig,
        uint _maxProfitUsd,
        uint _cancelTimeout,
        VrfConfig calldata vrfConfig
    ) external initializer {
        if (
            core.owner == address(0) ||
            core.manager == address(0) ||
            core.priceFeed == address(0) ||
            core.vrfCoordinator == address(0) ||
            core.freeBetsHolder == address(0) ||
            collateralConfig.usdc == address(0) ||
            collateralConfig.weth == address(0) ||
            collateralConfig.over == address(0)
        ) {
            revert InvalidAddress();
        }
        if (_maxProfitUsd == 0) revert InvalidAmount();
        if (_cancelTimeout < MIN_CANCEL_TIMEOUT) revert InvalidAmount();
        if (vrfConfig.callbackGasLimit == 0) revert InvalidAmount();
        // subscriptionId and keyHash are NOT enforced at init time to match the existing
        // casino deployment pattern (test/dev environments often plumb the real values via
        // setVrfConfig post-init). Setter enforces non-zero on subsequent updates

        setOwner(core.owner);
        initNonReentrant();

        manager = ISportsAMMV2Manager(core.manager);
        priceFeed = IPriceFeed(core.priceFeed);
        vrfCoordinator = IVRFCoordinatorV2Plus(core.vrfCoordinator);
        freeBetsHolder = core.freeBetsHolder;
        if (core.referrals != address(0)) referrals = IReferrals(core.referrals);

        usdc = collateralConfig.usdc;
        weth = collateralConfig.weth;
        over = collateralConfig.over;

        supportedCollateral[collateralConfig.usdc] = true;
        supportedCollateral[collateralConfig.weth] = true;
        supportedCollateral[collateralConfig.over] = true;
        priceFeedKeyPerCollateral[collateralConfig.weth] = collateralConfig.wethPriceFeedKey;
        priceFeedKeyPerCollateral[collateralConfig.over] = collateralConfig.overPriceFeedKey;
        _addToCollateralsList(collateralConfig.usdc);
        _addToCollateralsList(collateralConfig.weth);
        _addToCollateralsList(collateralConfig.over);

        maxProfitUsd = _maxProfitUsd;
        cancelTimeout = _cancelTimeout;
        defaultMaxNetLossPerGameUsd = DEFAULT_MAX_NET_LOSS_PER_GAME_USD;

        subscriptionId = vrfConfig.subscriptionId;
        keyHash = vrfConfig.keyHash;
        callbackGasLimit = vrfConfig.callbackGasLimit;
        requestConfirmations = vrfConfig.requestConfirmations;
        nativePayment = vrfConfig.nativePayment;
    }

    /* ========== GAME-FACING METHODS ========== */

    /// @inheritdoc ICasinoCoreV2
    function pullFromUser(address user, address collateral, uint256 amount) external override onlyActiveGame {
        _requireSupported(collateral);
        if (amount == 0) revert InvalidAmount();
        IERC20(collateral).safeTransferFrom(user, address(this), amount);
        pendingStakesPerCollateral[collateral] += amount;
        emit StakePulled(msg.sender, user, collateral, amount);
    }

    /// @inheritdoc ICasinoCoreV2
    function useFreeBet(address user, address collateral, uint256 amount) external override onlyActiveGame {
        _requireSupported(collateral);
        if (amount == 0) revert InvalidAmount();
        IFreeBetsHolder(freeBetsHolder).useFreeBet(user, collateral, amount);
        pendingStakesPerCollateral[collateral] += amount;
        emit FreeBetUsed(msg.sender, user, collateral, amount);
    }

    /// @inheritdoc ICasinoCoreV2
    /// @dev All referrals interactions are try/catch-wrapped. A broken or hostile referrals
    /// contract MUST NOT be able to revert a bet placement / fulfillment — otherwise it could be
    /// used to selectively block losing-bet settlements (an attacker-favorable cancel surface)
    function setReferrer(address referrer, address user) external override onlyActiveGame {
        if (referrer == address(0) || address(referrals) == address(0)) return;
        try referrals.setReferrer(referrer, user) {
            emit ReferrerSet(user, referrer);
        } catch {
            // silent: don't let a broken referrals contract block placeBet
        }
    }

    /// @inheritdoc ICasinoCoreV2
    function requestRandomWords(uint32 numWords) external override onlyActiveGame returns (uint256 requestId) {
        if (numWords == 0) revert InvalidAmount();
        requestId = vrfCoordinator.requestRandomWords(
            VRFV2PlusClient.RandomWordsRequest({
                keyHash: keyHash,
                subId: subscriptionId,
                requestConfirmations: requestConfirmations,
                callbackGasLimit: callbackGasLimit,
                numWords: numWords,
                extraArgs: VRFV2PlusClient._argsToBytes(VRFV2PlusClient.ExtraArgsV1({nativePayment: nativePayment}))
            })
        );
        requestIdToGame[requestId] = msg.sender;
        emit RandomWordsRequested(msg.sender, requestId, numWords);
    }

    /// @inheritdoc ICasinoCoreV2
    /// @dev **Per-bet solvency only.** Checks that the current balance covers THIS single bet's
    /// worst-case payout (= `amount`, which every game sizes to `stake + cappedProfit` or its
    /// `stake × maxMultiplier` equivalent — i.e., the max outflow for the bet). Does NOT check
    /// cumulative `pending + reserved` — the V2 casino is intentionally fractionally reserved
    /// under the assumption that multiple in-flight bets all hitting their max simultaneously
    /// is statistically negligible (probabilities range from 10⁻²⁶ for 3CP Pair Plus SF down to
    /// ~10⁻⁷⁰ for Keno Pick 10).
    ///
    /// Failure mode if the tail event happens: the unlucky-Nth winning settlement's
    /// `safeTransfer` reverts → VRF callback reverts → bet stranded in pending → resolver
    /// recovers via `adminCancelBet` (V2 games removed user-callable cancel for VRF-front-run
    /// reasons; V1 games still allow user cancel after timeout). Operator must monitor
    /// `getAvailableLiquidity` off-chain and top up before bankroll runs dry.
    ///
    /// Reservation accounting is still updated and used by `withdrawCollateral` to block admin
    /// drains while in-flight liability exists
    function reserveOrRevert(address collateral, uint256 amount) external override onlyActiveGame {
        _requireSupported(collateral);
        if (amount == 0) return;
        reservedProfitPerCollateral[collateral] += amount;
        reservedProfitPerGame[msg.sender][collateral] += amount;
        uint256 balance = IERC20(collateral).balanceOf(address(this));
        if (balance < amount) {
            // rollback
            reservedProfitPerCollateral[collateral] -= amount;
            reservedProfitPerGame[msg.sender][collateral] -= amount;
            revert InsufficientAvailableLiquidity();
        }
        emit ReservationChanged(msg.sender, collateral, int256(amount), reservedProfitPerGame[msg.sender][collateral]);
    }

    /// @inheritdoc ICasinoCoreV2
    /// @dev Settle paths must call this BEFORE `payOut` so the payout doesn't overshoot bankroll.
    /// Allowed even when the calling game is paused / auto-paused — pending bets must always be
    /// able to settle. Only requires the game to have ever been registered
    function releaseReservation(address collateral, uint256 amount) external override onlyRegisteredGame {
        if (amount == 0) return;
        if (reservedProfitPerGame[msg.sender][collateral] < amount) revert UnderReservation();
        reservedProfitPerGame[msg.sender][collateral] -= amount;
        reservedProfitPerCollateral[collateral] -= amount;
        emit ReservationChanged(msg.sender, collateral, -int256(amount), reservedProfitPerGame[msg.sender][collateral]);
    }

    /// @inheritdoc ICasinoCoreV2
    /// @dev Free-bet branch: tokens go to FreeBetsHolder first, then `confirmCasinoBetResolved`
    /// is called. The confirm call is wrapped in try/catch — a broken FreeBetsHolder shouldn't
    /// block the settlement (would create a losing-bet cancel surface for free-bet flows). On
    /// confirm failure, tokens are stuck in FBH but the casino settlement completes
    function payOut(
        address user,
        address collateral,
        uint256 amount,
        bool isFreeBet,
        uint256 originalStake
    ) external override onlyRegisteredGame {
        if (amount == 0) return;
        if (isFreeBet) {
            IERC20(collateral).safeTransfer(freeBetsHolder, amount);
            try IFreeBetsHolder(freeBetsHolder).confirmCasinoBetResolved(user, collateral, amount, originalStake) {
                // ok
            } catch {
                emit FreeBetConfirmFailed(msg.sender, user, collateral, amount, originalStake);
            }
        } else {
            IERC20(collateral).safeTransfer(user, amount);
        }
        emit PayoutSent(msg.sender, user, collateral, amount, isFreeBet, originalStake);
    }

    /// @inheritdoc ICasinoCoreV2
    /// @dev EVERY referrals call is try/catch-wrapped. A malicious or broken referrals contract
    /// MUST NOT be able to revert a bet's settlement — that would let an attacker selectively
    /// block losing-bet fulfillments (winning fulfillments don't reach this branch), turning
    /// referrals into an attacker-favorable cancel surface. This was a known V1 audit issue
    function payReferrer(address user, address collateral, uint256 stake) external override onlyRegisteredGame {
        if (address(referrals) == address(0)) return;
        address referrer;
        try referrals.referrals(user) returns (address r) {
            referrer = r;
        } catch {
            return;
        }
        if (referrer == address(0)) return;
        uint256 referrerFee;
        try referrals.getReferrerFee(referrer) returns (uint256 f) {
            referrerFee = f;
        } catch {
            return;
        }
        if (referrerFee == 0) return;
        uint256 referrerAmount = (stake * referrerFee) / ONE;
        if (referrerAmount == 0) return;
        // Low-level call handles both bool-returning (USDC / WETH / OVER) and void-returning
        // (USDT-style) ERC20s without reverting on the inner call. Crucially, `.call` does NOT
        // propagate the revert from a USDC blacklist / sanctioned-address rejection — that
        // preserves the invariant that a hostile referrer choice cannot block a losing-bet
        // settlement (a SafeERC20.safeTransfer here would re-introduce the exploit because it
        // bubbles up the underlying revert)
        (bool success, bytes memory data) = collateral.call(
            abi.encodeWithSelector(IERC20.transfer.selector, referrer, referrerAmount)
        );
        bool transferOk = success && (data.length == 0 || abi.decode(data, (bool)));
        if (transferOk) {
            // Deduct from the breaker gauge so it reflects real house P&L: referrer fee is
            // paid out of core's bankroll on losing bets and would otherwise leave the gauge
            // over-reporting house gains by cumulative fee, delaying auto-pause. Conversion
            // is best-effort — a broken price feed leaves a tiny per-bet drift, never a revert
            (bool conv, uint256 v) = _tryGetUsdValue(collateral, referrerAmount);
            if (conv) houseNetUsd[msg.sender] -= int256(v);
            emit ReferrerPaid(referrer, user, referrerAmount, stake, collateral);
        } else {
            emit ReferrerPayoutFailed(referrer, user, referrerAmount, stake, collateral);
        }
    }

    /// @inheritdoc ICasinoCoreV2
    /// @dev `stake - payout` is the house's per-bet P&L in collateral units (positive when the
    /// house won, negative when the user won). Converted to USD-18-dec and added to the running
    /// gauge. When the gauge falls below `-_maxNetLossUsd(game)`, the game is auto-paused.
    ///
    /// USD conversion goes through `_tryGetUsdValue`, which is non-reverting: if the price feed
    /// reverts (stale / broken) the bet still settles and the breaker simply skips this round.
    /// Letting a price feed revert block VRF callbacks would create a losing-bet cancel surface
    function recordSettlement(address collateral, uint256 stake, uint256 payout) external override onlyRegisteredGame {
        // Decrement pending-stake counter — clamp to zero so in-flight bets placed before this
        // accounting was introduced can still resolve without underflow (their stakes weren't
        // tracked at placement). New bets always satisfy `stake ≤ pending` by construction.
        // Emit `PendingStakesClamped` on the underflow path so off-chain monitoring can detect
        // unexpected drift (would loosen the `withdrawCollateral` over-drain guard)
        uint256 p = pendingStakesPerCollateral[collateral];
        if (stake > p) {
            emit PendingStakesClamped(msg.sender, collateral, stake, p);
            pendingStakesPerCollateral[collateral] = 0;
        } else {
            pendingStakesPerCollateral[collateral] = p - stake;
        }

        int256 deltaUsd;
        if (payout >= stake) {
            (bool ok, uint256 v) = _tryGetUsdValue(collateral, payout - stake);
            if (ok) {
                deltaUsd = -int256(v);
            } else {
                emit SettlementUsdConversionFailed(msg.sender, collateral, stake, payout);
            }
        } else {
            (bool ok, uint256 v) = _tryGetUsdValue(collateral, stake - payout);
            if (ok) {
                deltaUsd = int256(v);
            } else {
                emit SettlementUsdConversionFailed(msg.sender, collateral, stake, payout);
            }
        }
        int256 newNet = houseNetUsd[msg.sender] + deltaUsd;
        houseNetUsd[msg.sender] = newNet;

        uint256 maxLoss = _maxNetLossUsd(msg.sender);
        if (!gameAutoPaused[msg.sender] && newNet < 0 && uint256(-newNet) >= maxLoss) {
            gameAutoPaused[msg.sender] = true;
            emit GameAutoPaused(msg.sender, newNet, maxLoss);
        }

        emit SettlementRecorded(msg.sender, collateral, stake, payout, newNet);
    }

    /* ========== VRF CALLBACK ========== */

    /// @notice Coordinator-only VRF entrypoint. Routes the random words to the game that
    /// requested them via the registered `ICasinoGameCallback` interface
    function rawFulfillRandomWords(uint256 requestId, uint256[] calldata randomWords) external nonReentrant {
        if (msg.sender != address(vrfCoordinator)) revert InvalidSender();
        address game = requestIdToGame[requestId];
        if (game == address(0)) revert VrfRequestUnknown();
        // clear before dispatch to make replays no-ops and to free storage
        delete requestIdToGame[requestId];
        ICasinoGameCallback(game).onVrfFulfilled(requestId, randomWords);
        emit RandomWordsFulfilled(game, requestId);
    }

    /* ========== OWNER / RISK MANAGER ========== */

    /// @notice Registers a new game contract. Reverts on re-register.
    /// @dev Per-game `maxNetLossPerGameUsd[game]` defaults to 0, which `_maxNetLossUsd` reads
    /// as "use `defaultMaxNetLossPerGameUsd`" — no explicit init needed
    function registerGame(address game) external onlyOwner {
        if (game == address(0)) revert InvalidAddress();
        if (isGameRegistered[game]) revert GameAlreadyRegistered();
        isGameRegistered[game] = true;
        _registeredGameIndex[game] = _registeredGamesList.length;
        _registeredGamesList.push(game);
        emit GameRegistered(game);
    }

    /// @notice Removes a game from the registry. Requires zero reservations across EVERY
    /// currently-supported collateral (iterated from `_supportedCollateralsList`). Pause first,
    /// let pending bets settle, then deregister
    /// @dev AUDIT NOTE: this check does NOT cover `pendingStakesPerCollateral` (which is global,
    /// not per-game). Operator MUST also confirm no in-flight VRF requests target this game
    /// before deregistering — otherwise the in-flight callbacks will try to call back into core
    /// (`releaseReservation` / `payOut` / `recordSettlement`), all gated by `onlyRegisteredGame`,
    /// and will revert, stranding the bet AND permanently inflating `pendingStakesPerCollateral`
    /// (which blocks `withdrawCollateral`). Operational workflow: pause the game via
    /// `setGamePaused`, wait for all callbacks to fire (or `adminCancelBet` any stuck ones), THEN
    /// deregister. Considered tracking in-flight VRF per game on-chain; declined as upgrade-unsafe
    /// (would need new storage slots in currently-deployed proxies)
    function deregisterGame(address game) external onlyOwner {
        if (!isGameRegistered[game]) revert GameNotRegistered();
        uint256 nCols = _supportedCollateralsList.length;
        for (uint256 i; i < nCols; ++i) {
            if (reservedProfitPerGame[game][_supportedCollateralsList[i]] != 0) {
                revert GameHasReservations();
            }
        }
        isGameRegistered[game] = false;
        // swap-and-pop on the array
        uint256 idx = _registeredGameIndex[game];
        uint256 lastIdx = _registeredGamesList.length - 1;
        if (idx != lastIdx) {
            address last = _registeredGamesList[lastIdx];
            _registeredGamesList[idx] = last;
            _registeredGameIndex[last] = idx;
        }
        _registeredGamesList.pop();
        delete _registeredGameIndex[game];
        emit GameDeregistered(game);
    }

    /// @notice Per-game pause flag (independent from treasury-wide pause). Either flag blocks
    /// new bets; settlement of in-flight bets is unaffected
    function setGamePaused(address game, bool _paused) external onlyPauser {
        if (gamePaused[game] != _paused) {
            gamePaused[game] = _paused;
            emit GamePauseChanged(game, _paused);
        }
    }

    /// @notice Clears the auto-pause flag and zeroes the running net-loss gauge for a game.
    /// Owner-only — typically called after manual review. Promoted from RISK_MANAGING to OWNER
    /// because reset is the only function that *erases* the loss gauge rather than adjusting
    /// thresholds, so a compromised risk-manager key could otherwise suppress the breaker
    /// indefinitely by resetting after every trip
    function resetGameCircuitBreaker(address game) external onlyOwner {
        gameAutoPaused[game] = false;
        houseNetUsd[game] = 0;
        emit GameCircuitBreakerReset(game);
    }

    /// @notice Sets a per-game override for the circuit-breaker threshold. Pass 0 to revert to
    /// the default.
    /// @dev If the new effective threshold would put an already-losing game past the breaker, the
    /// game is auto-paused immediately rather than waiting for the next `recordSettlement` to
    /// trip it. Closes a window where an operator lowers the cap on a game that's already drifted
    /// negative and a handful of in-flight bets keep playing until the next settlement
    function setMaxNetLossPerGameUsd(address game, uint256 value) external onlyOwner {
        maxNetLossPerGameUsd[game] = value;
        emit MaxNetLossPerGameUsdChanged(game, value);

        if (!gameAutoPaused[game]) {
            int256 net = houseNetUsd[game];
            if (net < 0) {
                uint256 maxLoss = _maxNetLossUsd(game);
                if (uint256(-net) >= maxLoss) {
                    gameAutoPaused[game] = true;
                    emit GameAutoPaused(game, net, maxLoss);
                }
            }
        }
    }

    /// @notice Sets the default per-game circuit-breaker threshold applied to any game without
    /// an override.
    /// @dev When LOWERING the default, sweep registered games: any game using the default (no
    /// per-game override) and already in net loss past the new value is auto-paused immediately.
    /// Closes the same eager-pause gap as `setMaxNetLossPerGameUsd` but scoped to override-less
    /// games. Raising the default skips the sweep — auto-pause is one-way (cleared by
    /// `resetGameCircuitBreaker`), so a higher default can't *un*-pause anything
    function setDefaultMaxNetLossPerGameUsd(uint256 value) external onlyOwner {
        if (value == 0) revert InvalidAmount();
        uint256 prev = defaultMaxNetLossPerGameUsd;
        defaultMaxNetLossPerGameUsd = value;
        emit DefaultMaxNetLossPerGameUsdChanged(value);

        if (value >= prev) return;
        uint256 nGames = _registeredGamesList.length;
        for (uint256 i; i < nGames; ++i) {
            address game = _registeredGamesList[i];
            // Skip games with their own override — they're unaffected by the default
            if (maxNetLossPerGameUsd[game] != 0) continue;
            if (gameAutoPaused[game]) continue;
            int256 net = houseNetUsd[game];
            if (net < 0 && uint256(-net) >= value) {
                gameAutoPaused[game] = true;
                emit GameAutoPaused(game, net, value);
            }
        }
    }

    /// @notice Updates risk params. Pass 0 on a field to leave it untouched
    function setRiskParams(uint _maxProfitUsd, uint _cancelTimeout) external onlyOwner {
        if (_maxProfitUsd != 0) maxProfitUsd = _maxProfitUsd;
        if (_cancelTimeout != 0) {
            if (_cancelTimeout < MIN_CANCEL_TIMEOUT) revert InvalidAmount();
            cancelTimeout = _cancelTimeout;
        }
        emit RiskParamsChanged(_maxProfitUsd, _cancelTimeout);
    }

    /// @notice Sets a per-game override of the global `maxProfitUsd`. Pass 0 to clear the
    /// override and fall back to the global value. Lets the risk manager tune the per-bet
    /// profit cap per game without affecting others — useful when games have very different
    /// worst-case payout multipliers
    function setMaxProfitUsdOverride(address game, uint256 value) external onlyOwner {
        if (game == address(0)) revert InvalidAddress();
        maxProfitUsdOverride[game] = value;
        emit MaxProfitUsdOverrideChanged(game, value);
    }

    /// @notice Returns the effective per-bet profit cap for `game`: the override if set,
    /// otherwise the global `maxProfitUsd`. Games should call this (not `maxProfitUsd()`) at
    /// placeBet to enforce their cap
    function effectiveMaxProfitUsd(address game) external view override returns (uint256) {
        uint256 override_ = maxProfitUsdOverride[game];
        return override_ == 0 ? maxProfitUsd : override_;
    }

    /// @notice Per-game ante floor in USD-18-dec. 0 = "use the game's local default"
    function setMinBetPerGameUsd(address game, uint256 value) external onlyOwner {
        if (game == address(0)) revert InvalidAddress();
        minBetPerGameUsd[game] = value;
        emit MinBetPerGameUsdChanged(game, value);
    }

    /// @notice Per-game ante ceiling in USD-18-dec. 0 = no max
    function setMaxBetPerGameUsd(address game, uint256 value) external onlyOwner {
        if (game == address(0)) revert InvalidAddress();
        maxBetPerGameUsd[game] = value;
        emit MaxBetPerGameUsdChanged(game, value);
    }

    function effectiveMinBetUsd(address game) external view override returns (uint256) {
        return minBetPerGameUsd[game];
    }

    function effectiveMaxBetUsd(address game) external view override returns (uint256) {
        return maxBetPerGameUsd[game];
    }

    /// @notice Inverse of `getUsdValue`. Converts a USD-18-dec amount into native collateral
    /// decimals (6 for USDC, 18 for WETH/OVER). Used by games to derive collateral-denominated
    /// payout caps from the per-game USD profit ceiling. Reverts on unsupported collateral or
    /// missing price
    function collateralFromUsd(address collateral, uint256 usdAmount) external view override returns (uint256) {
        if (usdAmount == 0) return 0;
        _requireSupported(collateral);
        if (collateral == usdc) return usdAmount / 1e12; // 1e18 → 1e6
        uint price = priceFeed.rateForCurrency(priceFeedKeyPerCollateral[collateral]);
        if (price == 0) revert InvalidPrice();
        return (usdAmount * ONE) / price;
    }

    /// @notice Adds, removes, or re-keys a collateral. Both `currencyKey` and `isSupported` are
    /// always written — pass current values for fields you don't want to change. Also maintains
    /// the enumerable collateral list (`_supportedCollateralsList`) used by `deregisterGame`
    function setCollateralConfig(address collateral, bytes32 currencyKey, bool isSupported) external onlyOwner {
        if (collateral == address(0)) revert InvalidAddress();
        bool wasSupported = supportedCollateral[collateral];
        supportedCollateral[collateral] = isSupported;
        priceFeedKeyPerCollateral[collateral] = currencyKey;
        if (isSupported && !wasSupported) {
            _addToCollateralsList(collateral);
        } else if (!isSupported && wasSupported) {
            _removeFromCollateralsList(collateral);
        }
        emit CollateralConfigChanged(collateral, currencyKey, isSupported);
    }

    /// @notice Updates protocol addresses. Pass `address(0)` for any slot you want to skip
    /// @dev AUDIT NOTE: the skip-if-zero pattern means `referrals` cannot be disabled by passing
    /// `address(0)` here. Considered adding a dedicated `setReferrals(address)` that accepts zero;
    /// declined because the existing replace-path (deploy a no-op Referrals stub and repoint) is
    /// sufficient for the rare emergency-disable scenario, and the on-chain `payReferrer` is
    /// already try/catch-wrapped against a misbehaving Referrals contract
    function setAddresses(
        address _manager,
        address _priceFeed,
        address _vrfCoordinator,
        address _freeBetsHolder,
        address _referrals
    ) external onlyOwner {
        if (_manager != address(0)) manager = ISportsAMMV2Manager(_manager);
        if (_priceFeed != address(0)) priceFeed = IPriceFeed(_priceFeed);
        if (_vrfCoordinator != address(0)) vrfCoordinator = IVRFCoordinatorV2Plus(_vrfCoordinator);
        if (_freeBetsHolder != address(0)) freeBetsHolder = _freeBetsHolder;
        if (_referrals != address(0)) referrals = IReferrals(_referrals);
        emit AddressesChanged(_manager, _priceFeed, _vrfCoordinator, _freeBetsHolder, _referrals);
    }

    /// @notice Updates the Chainlink VRF configuration
    function setVrfConfig(
        uint256 _subscriptionId,
        bytes32 _keyHash,
        uint32 _callbackGasLimit,
        uint16 _requestConfirmations,
        bool _nativePayment
    ) external onlyOwner {
        if (_subscriptionId == 0) revert InvalidConfig();
        if (_keyHash == bytes32(0)) revert InvalidConfig();
        if (_callbackGasLimit == 0) revert InvalidConfig();
        subscriptionId = _subscriptionId;
        keyHash = _keyHash;
        callbackGasLimit = _callbackGasLimit;
        requestConfirmations = _requestConfirmations;
        nativePayment = _nativePayment;
        emit VrfConfigChanged(_subscriptionId, _keyHash, _callbackGasLimit, _requestConfirmations, _nativePayment);
    }

    /// @notice Treasury-wide pause. Blocks new bets across every registered game while leaving
    /// in-flight settlement intact
    /// @dev AUDIT NOTE: `ProxyPausable.setPaused(bool)` (owner-only) also writes the same `paused`
    /// slot and emits the same `PauseChanged` event. Considered overriding it to revert OR
    /// restricting unpause to owner-only here (pauser-pause-only / owner-unpause-only "guardian"
    /// pattern); declined because both paths are functionally equivalent in our trust model
    /// (PAUSER role is granted by the manager admin, i.e. owner-controlled) and the asymmetric
    /// trust shape isn't a documented requirement
    function setPausedByRole(bool _paused) external onlyPauser {
        if (paused != _paused) {
            paused = _paused;
            if (_paused) {
                lastPauseTime = block.timestamp;
            }
            emit PauseChanged(_paused);
        }
    }

    /// @notice Withdraws non-reserved, non-pending collateral from the treasury bankroll.
    /// @dev Withdraw uses **cumulative** liability (`reserved + pending`) — unlike
    /// `reserveOrRevert` which only checks per-bet solvency. Asymmetric on purpose: place-time
    /// admits over-commitment because concurrent max-wins are statistically negligible, but
    /// admin withdraws must not be able to drain bankroll out from under in-flight bets
    function withdrawCollateral(address _collateral, address _recipient, uint _amount) external onlyOwner nonReentrant {
        uint balance = IERC20(_collateral).balanceOf(address(this));
        uint reserved = reservedProfitPerCollateral[_collateral];
        uint pending = pendingStakesPerCollateral[_collateral];
        if (_amount > balance || balance - _amount < reserved + pending) revert InsufficientAvailableLiquidity();
        address recipient = _recipient == address(0) ? owner : _recipient;
        IERC20(_collateral).safeTransfer(recipient, _amount);
        emit WithdrawnCollateral(_collateral, recipient, _amount);
    }

    /* ========== VIEWS ========== */

    /// @inheritdoc ICasinoCoreV2
    function gameInactiveReason(address game) external view override returns (GameInactiveReason) {
        if (!isGameRegistered[game]) return GameInactiveReason.NOT_REGISTERED;
        if (paused) return GameInactiveReason.TREASURY_PAUSED;
        if (gamePaused[game]) return GameInactiveReason.GAME_PAUSED;
        if (gameAutoPaused[game]) return GameInactiveReason.AUTO_PAUSED;
        return GameInactiveReason.NONE;
    }

    /// @inheritdoc ICasinoCoreV2
    function getCollateralPrice(address collateral) public view override returns (uint256) {
        return _getCollateralPrice(collateral);
    }

    /// @inheritdoc ICasinoCoreV2
    function getUsdValue(address collateral, uint256 amount) external view override returns (uint256) {
        return _getUsdValue(collateral, amount);
    }

    /// @inheritdoc ICasinoCoreV2
    /// @dev Returns `balance - reserved`, INTENTIONALLY excluding `pendingStakesPerCollateral`.
    /// Pending stakes are user deposits already sitting in `balance`; subtracting them would
    /// require the operator to overfund for the unrealistic worst case of every in-flight bet
    /// cancelling simultaneously. This is the same fractional-reserve philosophy as
    /// `reserveOrRevert`. Asymmetric vs `withdrawCollateral`, which subtracts both because
    /// drains MUST be solvent against all owed funds. FE/ops monitors should use this for
    /// "headroom for new bets" and `withdrawCollateral`'s check for "safe to drain"
    function getAvailableLiquidity(address collateral) external view override returns (uint256) {
        if (!supportedCollateral[collateral]) revert InvalidCollateral();
        uint balance = IERC20(collateral).balanceOf(address(this));
        uint reserved = reservedProfitPerCollateral[collateral];
        return balance > reserved ? balance - reserved : 0;
    }

    /// @inheritdoc ICasinoCoreV2
    function getRegisteredGames() external view override returns (address[] memory) {
        return _registeredGamesList;
    }

    /// @notice Returns every collateral currently in the supported set. Order is not stable
    /// (swap-and-pop on remove). Used by FE/ops; `deregisterGame` iterates this internally
    function getSupportedCollaterals() external view returns (address[] memory) {
        return _supportedCollateralsList;
    }

    /* ========== INTERNAL ========== */

    function _requireSupported(address collateral) internal view {
        if (!supportedCollateral[collateral]) revert InvalidCollateral();
    }

    function _addToCollateralsList(address c) internal {
        _supportedCollateralIndex[c] = _supportedCollateralsList.length;
        _supportedCollateralsList.push(c);
    }

    function _removeFromCollateralsList(address c) internal {
        uint256 idx = _supportedCollateralIndex[c];
        uint256 lastIdx = _supportedCollateralsList.length - 1;
        if (idx != lastIdx) {
            address last = _supportedCollateralsList[lastIdx];
            _supportedCollateralsList[idx] = last;
            _supportedCollateralIndex[last] = idx;
        }
        _supportedCollateralsList.pop();
        delete _supportedCollateralIndex[c];
    }

    function _getCollateralPrice(address collateral) internal view returns (uint256) {
        _requireSupported(collateral);
        if (collateral == usdc) return ONE;
        bytes32 currencyKey = priceFeedKeyPerCollateral[collateral];
        if (currencyKey == bytes32(0)) revert InvalidCollateral();
        uint price = priceFeed.rateForCurrency(currencyKey);
        if (price == 0) revert InvalidPrice();
        return price;
    }

    function _getUsdValue(address collateral, uint256 amount) internal view returns (uint256) {
        if (collateral == usdc) return (amount * ONE) / USDC_UNIT;
        uint price = _getCollateralPrice(collateral);
        return (amount * price) / ONE;
    }

    /// @dev Non-reverting USD-value lookup used by the circuit-breaker P&L gauge. Returns
    /// `(false, 0)` on any failure (unsupported collateral, missing currency key, broken / stale
    /// price feed) so settlement isn't blocked. Replaces the previous `try this.getUsdValue(...)`
    /// self-call which forwarded only 63/64 of remaining gas and exposed the breaker to a 1/64
    /// gas-grief surface
    function _tryGetUsdValue(address collateral, uint256 amount) internal view returns (bool ok, uint256 value) {
        if (collateral == usdc) return (true, (amount * ONE) / USDC_UNIT);
        if (!supportedCollateral[collateral]) return (false, 0);
        bytes32 currencyKey = priceFeedKeyPerCollateral[collateral];
        if (currencyKey == bytes32(0)) return (false, 0);
        try priceFeed.rateForCurrency(currencyKey) returns (uint256 price) {
            if (price == 0) return (false, 0);
            return (true, (amount * price) / ONE);
        } catch {
            return (false, 0);
        }
    }

    function _maxNetLossUsd(address game) internal view returns (uint256) {
        uint256 v = maxNetLossPerGameUsd[game];
        return v == 0 ? defaultMaxNetLossPerGameUsd : v;
    }

    /* ========== MODIFIERS ========== */

    function _requireRole(ISportsAMMV2Manager.Role role) internal view {
        if (msg.sender != owner && !manager.isWhitelistedAddress(msg.sender, role)) revert InvalidSender();
    }

    modifier onlyPauser() {
        _requireRole(ISportsAMMV2Manager.Role.TICKET_PAUSER);
        _;
    }

    /// @notice Strictest gate: caller must be registered AND not paused at ANY layer (treasury /
    /// per-game / auto-pause). Used by new-bet entry points (pullFromUser, requestRandomWords,
    /// reserveOrRevert, useFreeBet, setReferrer)
    modifier onlyActiveGame() {
        if (!isGameRegistered[msg.sender]) revert GameNotRegistered();
        if (paused || gamePaused[msg.sender] || gameAutoPaused[msg.sender]) revert GameNotActive();
        _;
    }

    /// @notice Looser gate: caller must be registered. Pause flags are NOT checked, so in-flight
    /// bets can always settle. Used by settlement-side entry points (releaseReservation, payOut,
    /// recordSettlement, payReferrer)
    modifier onlyRegisteredGame() {
        if (!isGameRegistered[msg.sender]) revert GameNotRegistered();
        _;
    }
}

