// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/// @title CasinoHandsLib
/// @author Overtime
/// @notice Pure, internal-only helpers shared by V2 casino card games. All functions are
/// `internal pure` so they inline into the consuming contract's bytecode at compile time —
/// no separate library deployment, no DELEGATECALL, no storage, no linker reference. The
/// OZ upgrades validator treats inlined library code as part of the consumer's bytecode
/// and does not flag it
/// @dev Card encoding used by every consumer of this library:
///   `card = suit * 13 + rank0_12`, where `suit ∈ [0, 3]` and `rank0_12 ∈ [0, 12]`.
///   Evaluator-internal rank is `rank0_12 + 2` so 2 = deuce, 14 = ace.
///
/// HiLo uses a different on-card layout (`card = rank * 4 + suit`) and intentionally does NOT
/// consume this library — leave HiLo's local `_rank` helper alone
library CasinoHandsLib {
    uint8 internal constant DECK_SIZE = 52;

    /// @dev Bits consumed per Fisher-Yates swap. 16 bits gives < 0.04% bias on any remaining
    /// deck size in [50, 80]. Caller MUST ensure `n × SHUFFLE_SHIFT_BITS ≤ 256` for a single
    /// VRF word (re-seed externally if more swaps are needed — see Keno's bespoke draw)
    uint8 internal constant SHUFFLE_SHIFT_BITS = 16;
    uint64 internal constant SHUFFLE_SHIFT_MASK = 0xFFFF;

    /// @dev Evaluator-internal rank values. 2 = deuce, 14 = ace
    uint8 internal constant RANK_TWO = 2;
    uint8 internal constant RANK_ACE = 14;

    // Hand classes — numeric value matters: higher beats lower regardless of kickers.
    // Same encoding as the consumer contracts
    uint8 internal constant CLASS_HIGH_CARD = 0;
    uint8 internal constant CLASS_PAIR = 1;
    uint8 internal constant CLASS_TWO_PAIR = 2;
    uint8 internal constant CLASS_THREE_OF_A_KIND = 3;
    uint8 internal constant CLASS_STRAIGHT = 4;
    uint8 internal constant CLASS_FLUSH = 5;
    uint8 internal constant CLASS_FULL_HOUSE = 6;
    uint8 internal constant CLASS_FOUR_OF_A_KIND = 7;
    uint8 internal constant CLASS_STRAIGHT_FLUSH = 8;
    uint8 internal constant CLASS_ROYAL_FLUSH = 9;

    /* ========== PAGINATION ========== */

    /// @notice Newest-first paginated read over a per-user bet-ids array. Returns up to `limit`
    /// ids starting `offset` from the back of the array (offset 0 = most recent). Used by every
    /// V2 game's `getUserBetIds` view to avoid duplicating identical boilerplate
    function getUserBetIds(
        uint256[] storage all,
        uint256 offset,
        uint256 limit
    ) internal view returns (uint256[] memory ids) {
        uint256 len = all.length;
        if (offset >= len) return new uint256[](0);
        uint256 remaining = len - offset;
        uint256 count = remaining < limit ? remaining : limit;
        ids = new uint256[](count);
        for (uint256 i; i < count; ++i) {
            ids[i] = all[len - 1 - offset - i];
        }
    }

    /// @notice Newest-first paginated read over a contiguous `[1, nextBetId)` id range. Returns
    /// up to `limit` ids starting `offset` from the latest (offset 0 = newest bet). Caller MUST
    /// ensure `nextBetId` is the per-game counter that starts at 1 and increments per bet — if a
    /// future game starts at 0, `latest = nextBetId - 1` underflows
    function getRecentBetIds(uint256 nextBetId, uint256 offset, uint256 limit) internal pure returns (uint256[] memory ids) {
        uint256 latest = nextBetId - 1;
        if (offset >= latest) return new uint256[](0);
        uint256 start = latest - offset;
        uint256 count = start < limit ? start : limit;
        ids = new uint256[](count);
        for (uint256 i; i < count; ++i) {
            ids[i] = start - i;
        }
    }

    /* ========== DECK / SHUFFLE ========== */

    /// @notice Build a `size`-element deck over [0, 52) skipping any card whose bit is set in
    /// `excludeMask`. Pass `excludeMask = 0` for the full 52-card deck. Loop short-circuits when
    /// `size` slots are filled. Caller MUST pass `size == 52 - popcount(excludeMask)`; mismatched
    /// inputs either silently truncate (size too small) or revert on out-of-bounds write (size
    /// too large) — both are caller bugs, not normal paths
    function initDeck(uint8 size, uint64 excludeMask) internal pure returns (uint8[] memory deck) {
        deck = new uint8[](size);
        uint8 j;
        for (uint8 c; c < DECK_SIZE; ++c) {
            if ((excludeMask & (uint64(1) << c)) != 0) continue;
            deck[j] = c;
            ++j;
            if (j == size) break;
        }
    }

    /// @notice Performs `n` Fisher-Yates swaps on `deck` driven by `word`. The first `n` slots
    /// of `deck` end up containing `n` unique elements drawn uniformly (with ≤ 16/65536 ≈ 0.024%
    /// per-swap bias). Caller MUST ensure `n × SHUFFLE_SHIFT_BITS ≤ 256` so the cursor doesn't
    /// run out of entropy mid-shuffle
    function partialFisherYates(uint8[] memory deck, uint8 n, uint256 word) internal pure {
        uint256 len = deck.length;
        uint256 cursor = word;
        for (uint8 i; i < n; ++i) {
            uint256 remaining = len - i;
            uint256 j = i + ((cursor & SHUFFLE_SHIFT_MASK) % remaining);
            cursor >>= SHUFFLE_SHIFT_BITS;
            uint8 tmp = deck[i];
            deck[i] = deck[j];
            deck[j] = tmp;
        }
    }

    /* ========== BIT / RANK HELPERS ========== */

    /// @notice Brian Kernighan popcount over any uint up to uint256. Callers may pass uint8 /
    /// uint64 / uint128 — Solidity widens implicitly. Returns uint8 because no current caller
    /// counts more than 128 set bits (Keno's drawn-mask popcount is the maximum case)
    function popcount(uint256 x) internal pure returns (uint8 c) {
        unchecked {
            while (x != 0) {
                x &= x - 1;
                ++c;
            }
        }
    }

    /// @notice 5-in-a-row straight detection on a 16-bit rank-presence mask. Returns the
    /// high-card rank of the straight, or 0 if none. Handles the wheel A-2-3-4-5 (returns 5)
    function findStraightTop(uint16 mask) internal pure returns (uint8) {
        for (uint8 step; step <= 8; ++step) {
            uint8 top = RANK_ACE - step;
            uint16 fiveMask = uint16(0x1F) << (top - 4);
            if ((mask & fiveMask) == fiveMask) {
                return top;
            }
        }
        // Wheel: A-2-3-4-5 → top = 5. Bits: A=14 (0x4000), 2..5 (0x3C)
        if ((mask & 0x4000) != 0 && (mask & 0x3C) == 0x3C) {
            return 5;
        }
        return 0;
    }

    /// @notice Returns the top `n` ranks present in `mask`, high to low. Output array length
    /// is exactly `n`; if fewer than `n` bits are set the trailing slots remain at 0
    function topNRanks(uint16 mask, uint8 n) internal pure returns (uint8[] memory out) {
        out = new uint8[](n);
        uint8 idx;
        for (uint8 step; step < 13; ++step) {
            uint8 r = RANK_ACE - step;
            if ((mask & (uint16(1) << r)) != 0) {
                out[idx] = r;
                ++idx;
                if (idx == n) return out;
            }
        }
    }

    /// @notice `topNRanks` with up to 3 ranks first cleared from the mask. Pass 0 for any unused
    /// exclusion slot (rank 0 is not a valid rank in this encoding)
    function topNRanksExcluding(
        uint16 mask,
        uint8 n,
        uint8 ex0,
        uint8 ex1,
        uint8 ex2
    ) internal pure returns (uint8[] memory) {
        uint16 cleared = mask;
        if (ex0 != 0) cleared &= ~(uint16(1) << ex0);
        if (ex1 != 0) cleared &= ~(uint16(1) << ex1);
        if (ex2 != 0) cleared &= ~(uint16(1) << ex2);
        return topNRanks(cleared, n);
    }

    /// @notice Packs a hand value into a single uint256:
    ///   `[class:4][r1:4][r2:4][r3:4][r4:4][r5:4]`. Higher numeric value = stronger hand
    function pack(uint8 class_, uint8 r1, uint8 r2, uint8 r3, uint8 r4, uint8 r5) internal pure returns (uint256) {
        return
            (uint256(class_) << 20) |
            (uint256(r1) << 16) |
            (uint256(r2) << 12) |
            (uint256(r3) << 8) |
            (uint256(r4) << 4) |
            uint256(r5);
    }

    /// @notice Copy a fixed-size 7-card array into a dynamic uint8[] suitable for passing to
    /// `evaluateCards7`. Consumers store hands as `uint8[7] memory` (cheap to build inline) but
    /// the evaluator takes `uint8[] memory` so a 5-card or 7-card variant can share the entry
    function toMemArray7(uint8[7] memory src) internal pure returns (uint8[] memory out) {
        out = new uint8[](7);
        for (uint8 i; i < 7; ++i) out[i] = src[i];
    }

    /* ========== 7-CARD BEST-OF-5 EVALUATOR ========== */

    /// @notice Evaluates a 5–7 card hand and returns the packed best-5 hand value
    /// (`pack(class, r1..r5)`). Encoding: `[class:4][r1:4][r2:4][r3:4][r4:4][r5:4]`.
    /// `class` = 0 (HC) .. 9 (Royal). Padded ranks default to 0. Output orders within the same
    /// class via tie-breaker ranks, so two values can be `<` / `==` / `>` compared directly
    /// @dev Caller MUST pass distinct card indices in [0, 51]. Duplicates silently misclassify
    /// (rankCount/suitCount overcount, flush detection misfires). All current callers feed
    /// `partialFisherYates` output which is duplicate-free by construction; if a future consumer
    /// builds card sets from a different source, the caller is responsible for the precondition
    function evaluateCards7(uint8[] memory cards) internal pure returns (uint256) {
        uint8[15] memory rankCount;
        uint16 rankMask;
        uint16[4] memory suitRankMask;
        uint8[4] memory suitCount;

        for (uint256 i; i < cards.length; ++i) {
            uint8 r = uint8(cards[i] % 13) + RANK_TWO;
            uint8 s = uint8(cards[i] / 13);
            ++rankCount[r];
            ++suitCount[s];
            rankMask |= uint16(1) << r;
            suitRankMask[s] |= uint16(1) << r;
        }

        int8 flushSuit = -1;
        for (uint8 s; s < 4; ++s) {
            if (suitCount[s] >= 5) {
                flushSuit = int8(s);
                break;
            }
        }

        if (flushSuit >= 0) {
            uint16 fmask = suitRankMask[uint8(flushSuit)];
            uint8 sfTop = findStraightTop(fmask);
            if (sfTop > 0) {
                if (sfTop == RANK_ACE) {
                    return pack(CLASS_ROYAL_FLUSH, RANK_ACE, 0, 0, 0, 0);
                }
                return pack(CLASS_STRAIGHT_FLUSH, sfTop, 0, 0, 0, 0);
            }
        }

        uint8 fourRank;
        uint8 firstThree;
        uint8 secondThree;
        uint8 firstPair;
        uint8 secondPair;
        for (uint8 step; step < 13; ++step) {
            uint8 r = RANK_ACE - step;
            if (rankCount[r] == 4) {
                if (fourRank == 0) fourRank = r;
            } else if (rankCount[r] == 3) {
                if (firstThree == 0) firstThree = r;
                else if (secondThree == 0) secondThree = r;
            } else if (rankCount[r] == 2) {
                if (firstPair == 0) firstPair = r;
                else if (secondPair == 0) secondPair = r;
            }
        }

        if (fourRank > 0) {
            uint8 kicker = topNRanksExcluding(rankMask, 1, fourRank, 0, 0)[0];
            return pack(CLASS_FOUR_OF_A_KIND, fourRank, kicker, 0, 0, 0);
        }

        if (firstThree > 0 && (secondThree > 0 || firstPair > 0)) {
            uint8 pairRank = secondThree > firstPair ? secondThree : firstPair;
            return pack(CLASS_FULL_HOUSE, firstThree, pairRank, 0, 0, 0);
        }

        if (flushSuit >= 0) {
            uint8[] memory top5 = topNRanks(suitRankMask[uint8(flushSuit)], 5);
            return pack(CLASS_FLUSH, top5[0], top5[1], top5[2], top5[3], top5[4]);
        }

        uint8 straightTop = findStraightTop(rankMask);
        if (straightTop > 0) {
            return pack(CLASS_STRAIGHT, straightTop, 0, 0, 0, 0);
        }

        if (firstThree > 0) {
            uint8[] memory kickers = topNRanksExcluding(rankMask, 2, firstThree, 0, 0);
            return pack(CLASS_THREE_OF_A_KIND, firstThree, kickers[0], kickers[1], 0, 0);
        }

        if (firstPair > 0 && secondPair > 0) {
            uint8[] memory kickers = topNRanksExcluding(rankMask, 1, firstPair, secondPair, 0);
            return pack(CLASS_TWO_PAIR, firstPair, secondPair, kickers[0], 0, 0);
        }

        if (firstPair > 0) {
            uint8[] memory kickers = topNRanksExcluding(rankMask, 3, firstPair, 0, 0);
            return pack(CLASS_PAIR, firstPair, kickers[0], kickers[1], kickers[2], 0);
        }

        uint8[] memory hc = topNRanks(rankMask, 5);
        return pack(CLASS_HIGH_CARD, hc[0], hc[1], hc[2], hc[3], hc[4]);
    }
}

contracts/core/Casino/Dice.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";

import "chainlink-vrf/src/v0.8/vrf/dev/interfaces/IVRFCoordinatorV2Plus.sol";
import "chainlink-vrf/src/v0.8/vrf/dev/libraries/VRFV2PlusClient.sol";

// internal
import "../../utils/proxy/ProxyReentrancyGuard.sol";
import "../../utils/proxy/ProxyOwned.sol";
import "../../utils/proxy/ProxyPausable.sol";
import "@thales-dao/contracts/contracts/interfaces/IPriceFeed.sol";

import "../../interfaces/ISportsAMMV2Manager.sol";
import "../../interfaces/IFreeBetsHolder.sol";
import "@thales-dao/contracts/contracts/interfaces/IReferrals.sol";

/// @title Dice
/// @author Overtime
/// @notice d20 dice contract using Chainlink VRF for single-player bets
/// @dev Supports USDC, WETH and OVER collateral, with bankroll reservation per collateral
contract Dice is Initializable, ProxyOwned, ProxyPausable, ProxyReentrancyGuard {
    using SafeERC20 for IERC20;

    /* ========== CONSTANTS ========== */

    uint private constant ONE = 1e18;
    uint private constant USDC_UNIT = 1e6;
    uint8 private constant DICE_SIDES = 20;

    /// @notice Minimum allowed bet value expressed in USD, normalized to 18 decimals
    uint public constant MIN_BET_USD = 3e18;

    /// @notice Maximum allowed house edge in 1e18 precision
    uint public constant MAX_HOUSE_EDGE = 5e16; // 5%

    /// @notice Minimum allowed cancel timeout in seconds
    uint public constant MIN_CANCEL_TIMEOUT = 30;

    /* ========== ERRORS ========== */

    error InvalidAddress();
    error InvalidSender();
    error InvalidCollateral();
    error InvalidPrice();
    error InvalidAmount();
    error InvalidBetType();
    error InvalidTarget();
    error InvalidResult();
    error InvalidHouseEdge();
    error BetNotFound();
    error BetNotPending();
    error BetNotOwner();
    error CancelTimeoutNotReached();
    error MaxProfitExceeded();
    error InsufficientAvailableLiquidity();

    /* ========== ENUMS ========== */

    /// @notice Supported dice bet types
    enum BetType {
        ROLL_UNDER,
        ROLL_OVER
    }

    /// @notice Lifecycle status of a dice bet
    enum BetStatus {
        NONE,
        PENDING,
        RESOLVED,
        CANCELLED
    }

    /* ========== STRUCTS ========== */

    /// @notice Stored data for an individual dice bet
    /// @param user Address of the bettor
    /// @param collateral Collateral token used for the bet
    /// @param amount Amount staked
    /// @param payout Final payout amount, 0 if lost, original amount if cancelled
    /// @param requestId Chainlink VRF request id
    /// @param placedAt Timestamp when the bet was placed
    /// @param resolvedAt Timestamp when the bet was resolved or cancelled
    /// @param reservedProfit Reserved house-side profit liability for this bet
    /// @param betType Type of dice bet
    /// @param status Current status of the bet
    /// @param target Encoded target for the chosen bet type
    /// @param result Winning dice result in range 1..20
    /// @param won Whether the bet won
    struct Bet {
        address user;
        address collateral;
        uint amount;
        uint payout;
        uint requestId;
        uint placedAt;
        uint resolvedAt;
        uint reservedProfit;
        BetType betType;
        BetStatus status;
        uint8 target;
        uint8 result;
        bool won;
    }

    struct CoreAddresses {
        address owner;
        address manager;
        address priceFeed;
        address vrfCoordinator;
    }

    struct CollateralConfig {
        address usdc;
        address weth;
        address over;
        bytes32 wethPriceFeedKey;
        bytes32 overPriceFeedKey;
    }

    struct VrfConfig {
        uint256 subscriptionId;
        bytes32 keyHash;
        uint32 callbackGasLimit;
        uint16 requestConfirmations;
        bool nativePayment;
    }

    /* ========== STATE VARIABLES ========== */

    /// @notice Manager contract used for whitelist-based role checks
    ISportsAMMV2Manager public manager;

    /// @notice Price feed used for collateral normalization to USD
    IPriceFeed public priceFeed;

    /// @notice Chainlink VRF coordinator
    IVRFCoordinatorV2Plus public vrfCoordinator;

    /// @notice Supported collateral addresses
    address public usdc;
    address public weth;
    address public over;

    /// @notice Maximum allowed profit per bet in USD, normalized to 18 decimals
    uint public maxProfitUsd;

    /// @notice Timeout after which a pending bet can be cancelled
    uint public cancelTimeout;

    /// @notice House edge in 1e18 precision. Example: 1e16 = 1%
    /// @dev Must be greater than 0 and capped at MAX_HOUSE_EDGE
    uint public houseEdge;

    /// @notice Next bet id to assign
    uint public nextBetId;

    /// @notice Chainlink VRF v2.5 subscription id
    uint256 public subscriptionId;

    /// @notice Chainlink VRF key hash / gas lane
    bytes32 public keyHash;

    /// @notice Gas limit for VRF callback execution
    uint32 public callbackGasLimit;

    /// @notice Number of confirmations for VRF request
    uint16 public requestConfirmations;

    /// @notice Whether VRF request is paid in native token
    bool public nativePayment;

    /// @notice Whether a collateral is supported
    mapping(address => bool) public supportedCollateral;

    /// @notice Price feed key per collateral for non-USDC assets
    mapping(address => bytes32) public priceFeedKeyPerCollateral;

    /// @notice Stored bets by bet id
    mapping(uint => Bet) internal bets;

    /// @notice Maps VRF request id to bet id
    mapping(uint => uint) public requestIdToBetId;

    /// @notice Tracks reserved house-side profit liability for all pending bets per collateral
    mapping(address => uint) public reservedProfitPerCollateral;

    /// @notice Bet IDs per user for history queries
    mapping(address => uint[]) private userBetIds;

    /// @notice Free bets holder contract address
    address public freeBetsHolder;

    /// @notice Whether a bet was placed with a free bet
    mapping(uint => bool) public isFreeBet;

    /// @notice Referrals contract
    IReferrals public referrals;

    /* ========== PUBLIC / EXTERNAL METHODS ========== */

    /// @notice Initializes the dice contract
    /// @param core Core protocol addresses
    /// @param collateralConfig Collateral addresses and price feed keys
    /// @param _maxProfitUsd Maximum allowed profit per bet in USD, normalized to 18 decimals
    /// @param _cancelTimeout Timeout after which a pending bet can be cancelled
    /// @param _houseEdge House edge in 1e18 precision. Example: 1e16 = 1%
    /// @param vrfConfig Chainlink VRF configuration
    function initialize(
        CoreAddresses calldata core,
        CollateralConfig calldata collateralConfig,
        uint _maxProfitUsd,
        uint _cancelTimeout,
        uint _houseEdge,
        VrfConfig calldata vrfConfig
    ) external initializer {
        if (
            core.owner == address(0) ||
            core.manager == address(0) ||
            core.priceFeed == address(0) ||
            core.vrfCoordinator == address(0) ||
            collateralConfig.usdc == address(0) ||
            collateralConfig.weth == address(0) ||
            collateralConfig.over == address(0)
        ) {
            revert InvalidAddress();
        }

        if (_maxProfitUsd == 0) revert InvalidAmount();
        if (_houseEdge == 0 || _houseEdge > MAX_HOUSE_EDGE) revert InvalidHouseEdge();
        if (vrfConfig.callbackGasLimit == 0) revert InvalidAmount();

        setOwner(core.owner);
        initNonReentrant();

        manager = ISportsAMMV2Manager(core.manager);
        priceFeed = IPriceFeed(core.priceFeed);
        vrfCoordinator = IVRFCoordinatorV2Plus(core.vrfCoordinator);

        usdc = collateralConfig.usdc;
        weth = collateralConfig.weth;
        over = collateralConfig.over;

        supportedCollateral[collateralConfig.usdc] = true;
        supportedCollateral[collateralConfig.weth] = true;
        supportedCollateral[collateralConfig.over] = true;

        priceFeedKeyPerCollateral[collateralConfig.weth] = collateralConfig.wethPriceFeedKey;
        priceFeedKeyPerCollateral[collateralConfig.over] = collateralConfig.overPriceFeedKey;

        if (_cancelTimeout < MIN_CANCEL_TIMEOUT) revert InvalidAmount();
        maxProfitUsd = _maxProfitUsd;
        cancelTimeout = _cancelTimeout;
        houseEdge = _houseEdge;

        subscriptionId = vrfConfig.subscriptionId;
        keyHash = vrfConfig.keyHash;
        callbackGasLimit = vrfConfig.callbackGasLimit;
        requestConfirmations = vrfConfig.requestConfirmations;
        nativePayment = vrfConfig.nativePayment;

        nextBetId = 1;
    }

    /// @notice Places a dice bet and requests randomness from Chainlink VRF
    function placeBet(
        address collateral,
        uint amount,
        BetType betType,
        uint8 target,
        address _referrer
    ) external nonReentrant notPaused returns (uint betId, uint requestId) {
        if (!supportedCollateral[collateral]) revert InvalidCollateral();
        IERC20(collateral).safeTransferFrom(msg.sender, address(this), amount);
        _setReferrer(_referrer, msg.sender);
        return _placeBet(msg.sender, collateral, amount, betType, target, false);
    }

    /// @notice Places a dice bet using free bet balance
    function placeBetWithFreeBet(
        address collateral,
        uint amount,
        BetType betType,
        uint8 target
    ) external nonReentrant notPaused returns (uint betId, uint requestId) {
        if (!supportedCollateral[collateral]) revert InvalidCollateral();
        IFreeBetsHolder(freeBetsHolder).useFreeBet(msg.sender, collateral, amount);
        return _placeBet(msg.sender, collateral, amount, betType, target, true);
    }

    function _placeBet(
        address user,
        address collateral,
        uint amount,
        BetType betType,
        uint8 target,
        bool _isFreeBet
    ) internal returns (uint betId, uint requestId) {
        // collateral support already validated by the external wrappers (placeBet / placeBetWithFreeBet)
        if (amount == 0) revert InvalidAmount();
        _validateTarget(betType, target);
        if (_getUsdValue(collateral, amount) < MIN_BET_USD) revert InvalidAmount();

        uint reservedProfit = _getReservedProfit(amount, betType, target);
        if (_getUsdValue(collateral, reservedProfit) > maxProfitUsd) revert MaxProfitExceeded();

        reservedProfitPerCollateral[collateral] += amount + reservedProfit;
        if (!_hasEnoughLiquidity(collateral)) {
            reservedProfitPerCollateral[collateral] -= amount + reservedProfit;
            revert InsufficientAvailableLiquidity();
        }

        requestId = _requestRandomWord();
        betId = nextBetId++;

        Bet storage bet = bets[betId];
        bet.user = user;
        bet.collateral = collateral;
        bet.amount = amount;
        bet.requestId = requestId;
        bet.placedAt = block.timestamp;
        bet.reservedProfit = reservedProfit;
        bet.betType = betType;
        bet.status = BetStatus.PENDING;
        bet.target = target;

        if (_isFreeBet) isFreeBet[betId] = true;

        requestIdToBetId[requestId] = betId;
        userBetIds[user].push(betId);

        emit BetPlaced(betId, requestId, user, collateral, amount, betType, target);
    }

    /// @notice Cancels a pending bet after timeout and refunds the original stake
    /// @param betId Bet id to cancel
    function cancelBet(uint betId) external nonReentrant {
        Bet storage bet = bets[betId];

        if (bet.status == BetStatus.NONE) revert BetNotFound();
        if (bet.user != msg.sender) revert BetNotOwner();
        if (bet.status != BetStatus.PENDING) revert BetNotPending();
        if (block.timestamp < bet.placedAt + cancelTimeout) revert CancelTimeoutNotReached();

        _cancelBet(betId, false);
    }

    /// @notice Emergency cancels a pending bet and refunds the original stake
    /// @dev Callable by owner or manager role with MARKET_RESOLVING permission
    /// @param betId Bet id to cancel
    function adminCancelBet(uint betId) external onlyResolver nonReentrant {
        Bet storage bet = bets[betId];

        if (bet.status == BetStatus.NONE) revert BetNotFound();
        if (bet.status != BetStatus.PENDING) revert BetNotPending();

        _cancelBet(betId, true);
    }

    /// @notice Pauses or unpauses the contract using manager-based pauser permissions
    /// @param _paused True to pause, false to unpause
    function setPausedByRole(bool _paused) external onlyPauser {
        if (paused != _paused) {
            paused = _paused;
            if (_paused) {
                lastPauseTime = block.timestamp;
            }
            emit PauseChanged(_paused);
        }
    }

    /// @notice Coordinator-only VRF entrypoint
    /// @param requestId Chainlink VRF request id
    /// @param randomWords Array of VRF random words
    function rawFulfillRandomWords(uint256 requestId, uint256[] calldata randomWords) external nonReentrant {
        if (msg.sender != address(vrfCoordinator)) revert InvalidSender();
        _fulfillRandomWords(requestId, randomWords);
    }

    /* ========== INTERNAL / PRIVATE ========== */

    /// @notice Internal dice resolution logic after VRF fulfillment
    /// @param requestId Chainlink VRF request id
    /// @param randomWords Array of VRF random words
    function _fulfillRandomWords(uint256 requestId, uint256[] calldata randomWords) internal {
        uint betId = requestIdToBetId[requestId];
        if (betId == 0) {
            return;
        }

        Bet storage bet = bets[betId];

        if (bet.status != BetStatus.PENDING) {
            return;
        }

        uint8 result = uint8((randomWords[0] % DICE_SIDES) + 1);
        bool won = _isWinning(bet.betType, bet.target, result);

        reservedProfitPerCollateral[bet.collateral] -= bet.amount + bet.reservedProfit;

        uint payout = won ? bet.amount + bet.reservedProfit : 0;

        // State update before external transfers (CEI)
        bet.result = result;
        bet.won = won;
        bet.payout = payout;
        bet.status = BetStatus.RESOLVED;
        bet.resolvedAt = block.timestamp;

        emit BetResolved(betId, requestId, bet.user, result, won, payout);

        if (won) {
            if (isFreeBet[betId]) {
                IERC20(bet.collateral).safeTransfer(freeBetsHolder, payout);
                IFreeBetsHolder(freeBetsHolder).confirmCasinoBetResolved(bet.user, bet.collateral, payout, bet.amount);
            } else {
                IERC20(bet.collateral).safeTransfer(bet.user, payout);
            }
        } else if (!isFreeBet[betId]) {
            _payReferrer(bet.user, bet.collateral, bet.amount);
        }
    }

    function _setReferrer(address _referrer, address _user) internal {
        if (_referrer != address(0) && address(referrals) != address(0)) {
            referrals.setReferrer(_referrer, _user);
        }
    }

    function _payReferrer(address _user, address _collateral, uint _amount) internal {
        if (address(referrals) == address(0)) return;
        address referrer = referrals.referrals(_user);
        if (referrer == address(0)) return;
        uint referrerFee = referrals.getReferrerFee(referrer);
        if (referrerFee == 0) return;
        uint referrerAmount = (_amount * referrerFee) / ONE;
        if (referrerAmount > 0) {
            try IERC20(_collateral).transfer(referrer, referrerAmount) returns (bool ok) {
                if (ok) emit ReferrerPaid(referrer, _user, referrerAmount, _amount, _collateral);
                else emit ReferrerPayoutFailed(referrer, _user, referrerAmount, _amount, _collateral);
            } catch {
                emit ReferrerPayoutFailed(referrer, _user, referrerAmount, _amount, _collateral);
            }
        }
    }

    /// @notice Cancels a pending bet, releases reserved liquidity and refunds stake
    /// @param betId Bet id to cancel
    /// @param adminCancelled Whether the cancellation was admin-triggered
    function _cancelBet(uint betId, bool adminCancelled) internal {
        Bet storage bet = bets[betId];

        reservedProfitPerCollateral[bet.collateral] -= bet.amount + bet.reservedProfit;

        bet.status = BetStatus.CANCELLED;
        bet.resolvedAt = block.timestamp;
        bet.won = false;

        if (isFreeBet[betId]) {
            bet.payout = 0;
            IERC20(bet.collateral).safeTransfer(freeBetsHolder, bet.amount);
            IFreeBetsHolder(freeBetsHolder).confirmCasinoBetResolved(bet.user, bet.collateral, bet.amount, bet.amount);
        } else {
            bet.payout = bet.amount;
            IERC20(bet.collateral).safeTransfer(bet.user, bet.amount);
        }

        emit BetCancelled(betId, bet.requestId, bet.user, bet.amount, adminCancelled);
    }

    /// @notice Requests one random word from Chainlink VRF
    /// @return requestId Chainlink VRF request id
    function _requestRandomWord() internal returns (uint requestId) {
        requestId = vrfCoordinator.requestRandomWords(
            VRFV2PlusClient.RandomWordsRequest({
                keyHash: keyHash,
                subId: subscriptionId,
                requestConfirmations: requestConfirmations,
                callbackGasLimit: callbackGasLimit,
                numWords: 1,
                extraArgs: VRFV2PlusClient._argsToBytes(VRFV2PlusClient.ExtraArgsV1({nativePayment: nativePayment}))
            })
        );
    }

    /// @notice Checks whether available collateral balance covers all reserved profit
    /// @param collateral Collateral token address
    /// @return True if bankroll is sufficient for the collateral
    function _hasEnoughLiquidity(address collateral) internal view returns (bool) {
        return IERC20(collateral).balanceOf(address(this)) >= reservedProfitPerCollateral[collateral];
    }

    /// @notice Returns the normalized price for a supported collateral
    /// @param collateral Collateral token address
    /// @return Collateral price normalized to 18 decimals
    function _getCollateralPrice(address collateral) internal view returns (uint) {
        if (!supportedCollateral[collateral]) revert InvalidCollateral();

        if (collateral == usdc) {
            return ONE;
        }

        bytes32 currencyKey = priceFeedKeyPerCollateral[collateral];
        if (currencyKey == bytes32(0)) revert InvalidCollateral();

        uint price = priceFeed.rateForCurrency(currencyKey);
        if (price == 0) revert InvalidPrice();

        return price;
    }

    /// @notice Converts collateral amount into USD value normalized to 18 decimals
    /// @param collateral Collateral token address
    /// @param amount Collateral amount
    /// @return USD value normalized to 18 decimals
    function _getUsdValue(address collateral, uint amount) internal view returns (uint) {
        if (collateral == usdc) {
            return (amount * ONE) / USDC_UNIT;
        }

        uint price = _getCollateralPrice(collateral);
        return (amount * price) / ONE;
    }

    /// @notice Validates encoded target for a given bet type
    /// @param betType Dice bet type
    /// @param target Encoded target value
    function _validateTarget(BetType betType, uint8 target) internal pure {
        if (betType == BetType.ROLL_UNDER) {
            if (target < 2 || target > DICE_SIDES) revert InvalidTarget();
            return;
        }

        if (betType == BetType.ROLL_OVER) {
            if (target < 1 || target >= DICE_SIDES) revert InvalidTarget();
            return;
        }

        revert InvalidBetType();
    }

    /// @notice Returns the number of winning faces for a given dice target
    /// @param betType Dice bet type
    /// @param target Encoded target value
    /// @return Number of winning faces
    function _getWinningFaces(BetType betType, uint8 target) internal pure returns (uint8) {
        if (betType == BetType.ROLL_UNDER) {
            return target - 1;
        }

        if (betType == BetType.ROLL_OVER) {
            return DICE_SIDES - target;
        }

        revert InvalidBetType();
    }

    /// @notice Returns win probability for a given dice target in 1e18 precision
    /// @param betType Dice bet type
    /// @param target Encoded target value
    /// @return Probability normalized to 18 decimals
    function _getWinProbability(BetType betType, uint8 target) internal pure returns (uint) {
        uint8 winningFaces = _getWinningFaces(betType, target);
        return (uint(winningFaces) * ONE) / DICE_SIDES;
    }

    /// @notice Returns total payout multiplier for a given dice target in 1e18 precision
    /// @param betType Dice bet type
    /// @param target Encoded target value
    /// @return Total payout multiplier including original stake
    function _getPayoutMultiplier(BetType betType, uint8 target) internal view returns (uint) {
        uint probability = _getWinProbability(betType, target);
        return ((ONE - houseEdge) * ONE) / probability;
    }

    /// @notice Returns reserved profit amount in collateral units for a winning bet
    /// @param amount Bet amount
    /// @param betType Dice bet type
    /// @param target Encoded target value
    /// @return Reserved house-side profit liability
    function _getReservedProfit(uint amount, BetType betType, uint8 target) internal view returns (uint) {
        uint multiplier = _getPayoutMultiplier(betType, target);
        uint payout = (amount * multiplier) / ONE;
        return payout - amount;
    }

    /// @notice Returns whether a given bet target wins for a dice result
    /// @param betType Dice bet type
    /// @param target Encoded target value
    /// @param result Dice result in range 1..20
    /// @return True if the bet wins
    function _isWinning(BetType betType, uint8 target, uint8 result) internal pure returns (bool) {
        if (betType == BetType.ROLL_UNDER) {
            return result < target;
        }

        if (betType == BetType.ROLL_OVER) {
            return result > target;
        }

        revert InvalidBetType();
    }

    /* ========== GETTERS ========== */

    /// @notice Returns number of winning faces for a given bet
    /// @param betType Dice bet type
    /// @param target Encoded target value
    /// @return Number of winning faces
    function getWinningFaces(BetType betType, uint8 target) external pure returns (uint8) {
        _validateTarget(betType, target);
        return _getWinningFaces(betType, target);
    }

    /// @notice Returns win probability in 1e18 precision for a given bet
    /// @param betType Dice bet type
    /// @param target Encoded target value
    /// @return Probability normalized to 18 decimals
    function getWinProbability(BetType betType, uint8 target) external pure returns (uint) {
        _validateTarget(betType, target);
        return _getWinProbability(betType, target);
    }

    /// @notice Returns total payout multiplier in 1e18 precision for a given bet
    /// @param betType Dice bet type
    /// @param target Encoded target value
    /// @return Total payout multiplier including original stake
    function getPayoutMultiplier(BetType betType, uint8 target) external view returns (uint) {
        _validateTarget(betType, target);
        return _getPayoutMultiplier(betType, target);
    }

    /// @notice Returns potential profit in USD for a given bet
    /// @param collateral Collateral token address
    /// @param amount Bet amount
    /// @param betType Dice bet type
    /// @param target Encoded target value
    /// @return Potential profit in USD normalized to 18 decimals
    function getPotentialProfit(
        address collateral,
        uint amount,
        BetType betType,
        uint8 target
    ) external view returns (uint) {
        _validateTarget(betType, target);
        uint reservedProfit = _getReservedProfit(amount, betType, target);
        return _getUsdValue(collateral, reservedProfit);
    }

    /// @notice Returns total payout in collateral units for a winning bet
    /// @param amount Bet amount
    /// @param betType Dice bet type
    /// @param target Encoded target value
    /// @return Total payout including original stake
    function getPotentialPayoutCollateral(uint amount, BetType betType, uint8 target) external view returns (uint) {
        _validateTarget(betType, target);
        uint multiplier = _getPayoutMultiplier(betType, target);
        return (amount * multiplier) / ONE;
    }

    /// @notice Returns normalized collateral price
    /// @param collateral Collateral token address
    /// @return Collateral price normalized to 18 decimals
    function getCollateralPrice(address collateral) external view returns (uint) {
        return _getCollateralPrice(collateral);
    }

    /// @notice Returns whether a given target wins for a provided dice result
    /// @param betType Dice bet type
    /// @param target Encoded target value
    /// @param result Dice result in range 1..20
    /// @return True if the bet wins
    function isWinningBet(BetType betType, uint8 target, uint8 result) external pure returns (bool) {
        _validateTarget(betType, target);
        if (result < 1 || result > DICE_SIDES) revert InvalidResult();
        return _isWinning(betType, target, result);
    }

    /// @notice Returns currently available liquidity for a collateral after reserved profit
    /// @param collateral Collateral token address
    /// @return Available liquidity amount in collateral units
    function getAvailableLiquidity(address collateral) external view returns (uint) {
        if (!supportedCollateral[collateral]) revert InvalidCollateral();
        uint balance = IERC20(collateral).balanceOf(address(this));
        uint reserved = reservedProfitPerCollateral[collateral];
        return balance > reserved ? balance - reserved : 0;
    }

    /// @notice Returns the number of bets placed by a user
    function getUserBetCount(address user) external view returns (uint) {
        return userBetIds[user].length;
    }

    /// @notice Returns core bet data
    function getBetBase(
        uint betId
    )
        external
        view
        returns (
            address user,
            address collateral,
            uint amount,
            uint payout,
            uint requestId,
            uint placedAt,
            uint resolvedAt,
            uint reservedProfit
        )
    {
        Bet storage b = bets[betId];
        return (b.user, b.collateral, b.amount, b.payout, b.requestId, b.placedAt, b.resolvedAt, b.reservedProfit);
    }

    /// @notice Returns bet game details
    function getBetDetails(
        uint betId
    ) external view returns (BetType betType, BetStatus status, uint8 target, uint8 result, bool won) {
        Bet storage b = bets[betId];
        return (b.betType, b.status, b.target, b.result, b.won);
    }

    /// @notice Returns bet IDs for a user's bets with pagination (reverse chronological)
    function getUserBetIds(address user, uint offset, uint limit) external view returns (uint[] memory ids) {
        uint[] storage allIds = userBetIds[user];
        uint len = allIds.length;
        if (offset >= len) return new uint[](0);
        uint remaining = len - offset;
        uint count = remaining < limit ? remaining : limit;
        ids = new uint[](count);
        for (uint i = 0; i < count; i++) {
            ids[i] = allIds[len - 1 - offset - i];
        }
    }

    /// @notice Returns recent bet IDs with pagination (reverse chronological)
    function getRecentBetIds(uint offset, uint limit) external view returns (uint[] memory ids) {
        uint latest = nextBetId - 1;
        if (offset >= latest) return new uint[](0);
        uint start = latest - offset;
        uint count = start < limit ? start : limit;
        ids = new uint[](count);
        for (uint i = 0; i < count; i++) {
            ids[i] = start - i;
        }
    }

    /* ========== SETTERS ========== */

    /// @notice Sets maximum allowed profit per bet in USD
    /// @dev Callable by owner or manager role with RISK_MANAGING permission
    /// @param _maxProfitUsd Maximum profit in USD normalized to 18 decimals
    function setMaxProfitUsd(uint _maxProfitUsd) external onlyRiskManager {
        if (_maxProfitUsd == 0) revert InvalidAmount();
        maxProfitUsd = _maxProfitUsd;
        emit MaxProfitUsdChanged(_maxProfitUsd);
    }

    /// @notice Sets timeout after which pending bets can be cancelled
    /// @dev Callable by owner or manager role with RISK_MANAGING permission
    /// @param _cancelTimeout Timeout in seconds
    function setCancelTimeout(uint _cancelTimeout) external onlyRiskManager {
        if (_cancelTimeout < MIN_CANCEL_TIMEOUT) revert InvalidAmount();
        cancelTimeout = _cancelTimeout;
        emit CancelTimeoutChanged(_cancelTimeout);
    }

    /// @notice Sets house edge
    /// @dev Callable by owner or manager role with RISK_MANAGING permission
    /// @param _houseEdge House edge in 1e18 precision
    function setHouseEdge(uint _houseEdge) external onlyRiskManager {
        if (_houseEdge == 0 || _houseEdge > MAX_HOUSE_EDGE) revert InvalidHouseEdge();
        houseEdge = _houseEdge;
        emit HouseEdgeChanged(_houseEdge);
    }

    /// @notice Adds or removes a supported collateral
    /// @dev Callable by owner or manager role with RISK_MANAGING permission
    /// @param collateral Collateral token address
    /// @param isSupported Whether the collateral is supported
    function setSupportedCollateral(address collateral, bool isSupported) external onlyRiskManager {
        if (collateral == address(0)) revert InvalidAddress();
        supportedCollateral[collateral] = isSupported;
        emit SupportedCollateralChanged(collateral, isSupported);
    }

    /// @notice Sets price feed key for a collateral
    /// @dev Callable by owner or manager role with RISK_MANAGING permission
    /// @param collateral Collateral token address
    /// @param currencyKey Price feed currency key
    function setPriceFeedKeyPerCollateral(address collateral, bytes32 currencyKey) external onlyRiskManager {
        if (collateral == address(0)) revert InvalidAddress();
        priceFeedKeyPerCollateral[collateral] = currencyKey;
        emit PriceFeedKeyPerCollateralChanged(collateral, currencyKey);
    }

    /// @notice Sets manager contract address
    /// @param _manager Manager contract address
    function setManager(address _manager) external onlyOwner {
        if (_manager == address(0)) revert InvalidAddress();
        manager = ISportsAMMV2Manager(_manager);
        emit ManagerChanged(_manager);
    }

    /// @notice Sets price feed contract address
    /// @param _priceFeed Price feed contract address
    function setPriceFeed(address _priceFeed) external onlyOwner {
        if (_priceFeed == address(0)) revert InvalidAddress();
        priceFeed = IPriceFeed(_priceFeed);
        emit PriceFeedChanged(_priceFeed);
    }

    /// @notice Sets Chainlink VRF coordinator address
    /// @param _vrfCoordinator Chainlink VRF coordinator address
    function setVrfCoordinator(address _vrfCoordinator) external onlyOwner {
        if (_vrfCoordinator == address(0)) revert InvalidAddress();
        vrfCoordinator = IVRFCoordinatorV2Plus(_vrfCoordinator);
        emit VrfCoordinatorChanged(_vrfCoordinator);
    }

    /// @notice Sets the free bets holder contract
    function setFreeBetsHolder(address _freeBetsHolder) external onlyOwner {
        if (_freeBetsHolder == address(0)) revert InvalidAddress();
        freeBetsHolder = _freeBetsHolder;
        emit FreeBetsHolderChanged(_freeBetsHolder);
    }

    /// @notice Sets the referrals contract
    function setReferrals(address _referrals) external onlyOwner {
        if (_referrals == address(0)) revert InvalidAddress();
        referrals = IReferrals(_referrals);
        emit ReferralsChanged(_referrals);
    }

    /// @notice Withdraws collateral from the contract bankroll
    /// @param _collateral The address of the ERC20 token to withdraw
    /// @param _recipient The address of the recipient, defaults to owner if zero address
    /// @param _amount The amount of tokens to withdraw
    function withdrawCollateral(address _collateral, address _recipient, uint _amount) external onlyOwner {
        uint balance = IERC20(_collateral).balanceOf(address(this));
        uint reserved = reservedProfitPerCollateral[_collateral];
        if (_amount > balance || balance - _amount < reserved) revert InsufficientAvailableLiquidity();
        address recipient = _recipient == address(0) ? owner : _recipient;
        IERC20(_collateral).safeTransfer(recipient, _amount);
        emit WithdrawnCollateral(_collateral, recipient, _amount);
    }

    /// @notice Sets Chainlink VRF configuration
    /// @param _subscriptionId Chainlink VRF subscription id
    /// @param _keyHash Chainlink VRF key hash / gas lane
    /// @param _callbackGasLimit Gas limit for callback
    /// @param _requestConfirmations Number of confirmations before VRF fulfillment
    /// @param _nativePayment Whether VRF uses native token payment
    function setVrfConfig(
        uint256 _subscriptionId,
        bytes32 _keyHash,
        uint32 _callbackGasLimit,
        uint16 _requestConfirmations,
        bool _nativePayment
    ) external onlyOwner {
        if (_subscriptionId == 0) revert InvalidAmount();
        if (_keyHash == bytes32(0)) revert InvalidAmount();
        if (_callbackGasLimit == 0) revert InvalidAmount();

        subscriptionId = _subscriptionId;
        keyHash = _keyHash;
        callbackGasLimit = _callbackGasLimit;
        requestConfirmations = _requestConfirmations;
        nativePayment = _nativePayment;

        emit VrfConfigChanged(_subscriptionId, _keyHash, _callbackGasLimit, _requestConfirmations, _nativePayment);
    }

    /* ========== MODIFIERS ========== */

    /// @notice Restricts access to owner or manager addresses whitelisted for risk management
    modifier onlyRiskManager() {
        if (msg.sender != owner && !manager.isWhitelistedAddress(msg.sender, ISportsAMMV2Manager.Role.RISK_MANAGING)) {
            revert InvalidSender();
        }
        _;
    }

    /// @notice Restricts access to owner or manager addresses whitelisted for market resolving
    modifier onlyResolver() {
        if (msg.sender != owner && !manager.isWhitelistedAddress(msg.sender, ISportsAMMV2Manager.Role.MARKET_RESOLVING)) {
            revert InvalidSender();
        }
        _;
    }

    /// @notice Restricts access to owner or manager addresses whitelisted for pausing
    modifier onlyPauser() {
        if (msg.sender != owner && !manager.isWhitelistedAddress(msg.sender, ISportsAMMV2Manager.Role.TICKET_PAUSER)) {
            revert InvalidSender();
        }
        _;
    }

    /* ========== EVENTS ========== */

    /// @notice Emitted when a new bet is placed
    /// @param betId Bet id
    /// @param requestId Chainlink VRF request id
    /// @param user Bettor address
    /// @param collateral Collateral token address
    /// @param amount Bet amount
    /// @param betType Dice bet type
    /// @param target Encoded target value
    event BetPlaced(
        uint indexed betId,
        uint indexed requestId,
        address indexed user,
        address collateral,
        uint amount,
        BetType betType,
        uint8 target
    );

    /// @notice Emitted when a bet is resolved
    /// @param betId Bet id
    /// @param requestId Chainlink VRF request id
    /// @param user Bettor address
    /// @param result Dice result in range 1..20
    /// @param won Whether the bet won
    /// @param payout Final payout amount
    event BetResolved(uint indexed betId, uint indexed requestId, address indexed user, uint8 result, bool won, uint payout);

    /// @notice Emitted when a bet is cancelled
    /// @param betId Bet id
    /// @param requestId Chainlink VRF request id
    /// @param user Bettor address
    /// @param refundedAmount Refunded stake amount
    /// @param adminCancelled Whether the cancellation was admin-triggered
    event BetCancelled(
        uint indexed betId,
        uint indexed requestId,
        address indexed user,
        uint refundedAmount,
        bool adminCancelled
    );

    /// @notice Emitted when maximum profit per bet is changed
    /// @param maxProfitUsd New maximum profit in USD normalized to 18 decimals
    event MaxProfitUsdChanged(uint maxProfitUsd);

    /// @notice Emitted when cancel timeout is changed
    /// @param cancelTimeout New timeout in seconds
    event CancelTimeoutChanged(uint cancelTimeout);

    /// @notice Emitted when house edge is changed
    /// @param houseEdge New house edge in 1e18 precision
    event HouseEdgeChanged(uint houseEdge);

    /// @notice Emitted when collateral support is changed
    /// @param collateral Collateral token address
    /// @param supported Whether the collateral is supported
    event SupportedCollateralChanged(address collateral, bool supported);

    /// @notice Emitted when price feed key for a collateral is changed
    /// @param collateral Collateral token address
    /// @param key New price feed key
    event PriceFeedKeyPerCollateralChanged(address collateral, bytes32 key);

    /// @notice Emitted when manager contract is changed
    /// @param manager New manager contract address
    event ManagerChanged(address manager);

    /// @notice Emitted when price feed contract is changed
    /// @param priceFeed New price feed contract address
    event PriceFeedChanged(address priceFeed);

    /// @notice Emitted when VRF coordinator is changed
    /// @param vrfCoordinator New Chainlink VRF coordinator address
    event VrfCoordinatorChanged(address vrfCoordinator);
    event FreeBetsHolderChanged(address freeBetsHolder);
    event ReferralsChanged(address referrals);
    event ReferrerPaid(address indexed referrer, address indexed user, uint amount, uint betAmount, address collateral);
    event ReferrerPayoutFailed(
        address indexed referrer,
        address indexed user,
        uint amount,
        uint betAmount,
        address collateral
    );

    /// @notice Emitted when collateral is withdrawn from the bankroll
    /// @param collateral Collateral token address
    /// @param recipient Recipient address
    /// @param amount Amount withdrawn
    event WithdrawnCollateral(address indexed collateral, address indexed recipient, uint amount);

    /// @notice Emitted when VRF config is changed
    /// @param subscriptionId New Chainlink VRF subscription id
    /// @param keyHash New Chainlink VRF key hash
    /// @param callbackGasLimit New callback gas limit
    /// @param requestConfirmations New request confirmations value
    /// @param nativePayment Whether native payment is enabled
    event VrfConfigChanged(
        uint256 subscriptionId,
        bytes32 keyHash,
        uint32 callbackGasLimit,
        uint16 requestConfirmations,
        bool nativePayment
    );
}

contracts/core/Casino/HiLo.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";

import "../../utils/proxy/ProxyReentrancyGuard.sol";
import "../../utils/proxy/ProxyOwned.sol";
import "../../utils/proxy/ProxyPausable.sol";

import "../../interfaces/ISportsAMMV2Manager.sol";
import "../../interfaces/ICasinoCoreV2.sol";
import "../../interfaces/ICasinoGameCallback.sol";
import "../../interfaces/ICasinoHiLo.sol";
import "./CasinoHandsLib.sol";

/// @title HiLo
/// @author Overtime
/// @notice "Above/below 8" card-guess run with cashout. Each round the player picks ABOVE or
/// BELOW the rank-6 midpoint (card "8"); a fresh card is drawn from a 52-card deck; correct
/// guesses multiply the running multiplier by a constant factor; wrong guess loses the bet;
/// cashout pays `bet * multiplier`. Drawing card "8" is a push (multiplier unchanged, run continues)
/// @dev No "current card" feeds into the decision — the comparison point is always rank 6. Per-
/// correct-guess factor is constant: `factor = (12 - 13*HE) / 6` in 1e18 precision (≈ 1.96x at
/// HE=2%). Per-bet liability capped by `maxMultiplierE18`. Cards are drawn fresh each guess
/// (no without-replacement tracking)
contract HiLo is ICasinoHiLo, ICasinoGameCallback, Initializable, ProxyOwned, ProxyPausable, ProxyReentrancyGuard {
    /* ========== CONSTANTS ========== */

    uint256 private constant ONE = 1e18;
    uint256 public constant MIN_BET_USD = 3e18;

    uint8 private constant DECK_SIZE = 52;

    /// @notice Reference rank for the above/below decision. Rank 6 is card "8" (rank 0 = "2",
    /// rank 12 = "Ace"). Splits the deck symmetrically: 6 ranks below (2-7), 6 above (9-A), 1
    /// push (8 itself). Probability of correct guess = 6/13 per round
    uint8 private constant MIDPOINT_RANK = 6;
    uint8 private constant WINNING_RANKS_PER_DIRECTION = 6;

    uint256 public constant MIN_HOUSE_EDGE_E18 = 0.02e18;
    uint256 public constant MAX_HOUSE_EDGE_E18 = 0.05e18;

    /// @notice Default per-bet multiplier cap. With a constant ≈1.96x per win, 25x corresponds to
    /// ~5 consecutive wins. Realistic 99th-percentile cashouts sit well below this
    uint256 public constant DEFAULT_MAX_MULTIPLIER_E18 = 25e18;

    /* ========== ERRORS ========== */

    error InvalidAddress();
    error InvalidSender();
    error InvalidAmount();
    error InvalidCollateral();
    error AboveMaxBet();
    error MaxMultiplierReached();
    error MaxProfitExceeded();
    error InvalidHouseEdge();
    error BetNotFound();
    error BetNotOwner();
    error InvalidBetStatus();
    /// @notice Reverted by `makeAction` when an unknown action code is supplied. Defends against
    /// FE / gasless-session bugs that send a stale or out-of-range code; the call reverts
    /// instead of silently no-op'ing past the if/else chain
    error InvalidAction();

    /* ========== STRUCTS ========== */

    struct Bet {
        address user;
        address collateral;
        uint256 amount;
        uint256 payout;
        uint256 placedAt;
        uint256 lastRequestAt;
        uint256 resolvedAt;
        uint256 reserved;
        uint256 requestId;
        uint256 currentMultiplierE18;
        uint8 lastCard; // last drawn card (0..51); 0xFF if no card drawn yet
        uint8 guessCount;
        uint8 correctCount;
        uint8 pushCount;
        Direction pendingDirection;
        BetStatus status;
        Outcome outcome;
        // --- per-turn history (Bet-struct extension; storage-safe append for upgrade) ---
        // Parallel arrays for FE rendering of the full bet history without log scanning.
        // `directions` has one entry per submitted guess (length = `guessCount`). `cards`,
        // `outcomes`, `multipliersE18` have one entry per resolved card (length = `guessCount`
        // when no VRF in flight, or `guessCount - 1` while AWAITING_NEXT_CARD).
        // `multipliersE18[i]` holds the multiplier AFTER turn i (HIT advances; PUSH copies
        // prior; BUST writes the frozen pre-bust value)
        uint8[] directions;
        uint8[] cards;
        uint8[] outcomes; // CardOutcome cast to uint8
        uint256[] multipliersE18;
        // --- free bet flag. Set when stake was pulled from FreeBetsHolder via core.useFreeBet
        // instead of core.pullFromUser. Routes payouts back to FBH on resolve and suppresses
        // referrer payment on BUST (no real loss to user)
        bool isFreeBet;
    }

    /* ========== STATE ========== */

    ICasinoCoreV2 public core;
    ISportsAMMV2Manager public manager;

    uint256 public houseEdgeE18;
    uint256 public maxMultiplierE18;

    uint256 public nextBetId;

    mapping(uint256 => Bet) internal bets;
    mapping(uint256 => uint256) public requestIdToBetId;
    mapping(address => uint256[]) private userBetIds;

    /* ========== INITIALIZER ========== */

    function initialize(address _owner, address _core, address _manager) external initializer {
        if (_owner == address(0) || _core == address(0) || _manager == address(0)) revert InvalidAddress();
        setOwner(_owner);
        initNonReentrant();
        core = ICasinoCoreV2(_core);
        manager = ISportsAMMV2Manager(_manager);
        nextBetId = 1;
        houseEdgeE18 = MIN_HOUSE_EDGE_E18;
        maxMultiplierE18 = DEFAULT_MAX_MULTIPLIER_E18;
    }

    /* ========== PLACE / GUESS / CASHOUT ========== */

    /// @notice Places a HiLo bet and submits the first guess in one transaction. The bet starts
    /// in AWAITING_NEXT_CARD with the first VRF request already in flight. Subsequent rounds use
    /// `makeAction(betId, action)` once the bet returns to PLAYER_TURN
    function placeBet(
        address collateral,
        uint256 amount,
        address referrer,
        Direction firstDirection,
        bool isFreeBet
    ) external override nonReentrant notPaused returns (uint256 betId, uint256 requestId) {
        return _placeBet(collateral, amount, referrer, firstDirection, isFreeBet);
    }

    function _placeBet(
        address collateral,
        uint256 amount,
        address referrer,
        Direction firstDirection,
        bool isFreeBet
    ) internal returns (uint256 betId, uint256 requestId) {
        if (amount == 0) revert InvalidAmount();
        if (!core.supportedCollateral(collateral)) revert InvalidCollateral();
        _checkBetSize(collateral, amount);

        uint256 amountUsd = core.getUsdValue(collateral, amount);
        uint256 worstHouseProfitUsd = (amountUsd * (maxMultiplierE18 - ONE)) / ONE;
        if (worstHouseProfitUsd > core.effectiveMaxProfitUsd(address(this))) revert MaxProfitExceeded();

        if (isFreeBet) {
            core.useFreeBet(msg.sender, collateral, amount);
        } else {
            core.pullFromUser(msg.sender, collateral, amount);
        }
        if (referrer != address(0)) core.setReferrer(referrer, msg.sender);

        uint256 reservation = (amount * maxMultiplierE18) / ONE;
        core.reserveOrRevert(collateral, reservation);

        betId = nextBetId++;
        requestId = core.requestRandomWords(1);

        Bet storage b = bets[betId];
        b.user = msg.sender;
        b.collateral = collateral;
        b.amount = amount;
        b.placedAt = block.timestamp;
        b.lastRequestAt = block.timestamp;
        b.reserved = reservation;
        b.currentMultiplierE18 = ONE; // 1.00x to start
        b.lastCard = 0xFF; // sentinel: no card drawn yet
        b.requestId = requestId;
        b.pendingDirection = firstDirection;
        b.guessCount = 1;
        b.directions.push(uint8(firstDirection));
        b.status = BetStatus.AWAITING_NEXT_CARD;
        b.isFreeBet = isFreeBet;

        requestIdToBetId[requestId] = betId;
        userBetIds[msg.sender].push(betId);

        emit BetPlaced(betId, msg.sender, collateral, amount);
        emit GuessChosen(betId, requestId, msg.sender, firstDirection);
    }

    /// @notice Single-selector mid-game dispatcher. Routes by action code into the internal
    /// helpers — same auth, state machine, and events as the previously-public guess / cashout
    /// functions. Action codes:
    ///   0 = guess ABOVE
    ///   1 = guess BELOW
    ///   2 = cashout
    /// Reverts `InvalidAction` for any other code so a misconfigured FE fails loudly
    /// @dev AUDIT NOTE: `notPaused` here means a mid-game pause traps in-flight winners (e.g.
    /// a user at 15× multiplier can't cashout). Considered exempting settlement actions or adding
    /// a separate `settlementsPaused` flag; declined because `adminCancelBet` is the operator's
    /// escape hatch for stuck bets (full-stake refund, NOT accrued winnings — known trade-off)
    function makeAction(uint256 betId, uint8 action) external override nonReentrant notPaused returns (uint256 requestId) {
        if (action == 0) return _guess(betId, Direction.ABOVE);
        if (action == 1) return _guess(betId, Direction.BELOW);
        if (action == 2) {
            _cashout(betId);
            return 0;
        }
        revert InvalidAction();
    }

    function _guess(uint256 betId, Direction direction) internal returns (uint256 requestId) {
        Bet storage b = bets[betId];
        if (b.status == BetStatus.NONE) revert BetNotFound();
        if (b.user != msg.sender) revert BetNotOwner();
        if (b.status != BetStatus.PLAYER_TURN) revert InvalidBetStatus();

        // Cap reached → no more guesses
        if (b.currentMultiplierE18 >= maxMultiplierE18) revert MaxMultiplierReached();

        b.pendingDirection = direction;
        requestId = core.requestRandomWords(1);
        b.requestId = requestId;
        b.lastRequestAt = block.timestamp;
        b.status = BetStatus.AWAITING_NEXT_CARD;
        ++b.guessCount;
        b.directions.push(uint8(direction));
        requestIdToBetId[requestId] = betId;

        emit GuessChosen(betId, requestId, msg.sender, direction);
    }

    function _cashout(uint256 betId) internal {
        Bet storage b = bets[betId];
        if (b.status == BetStatus.NONE) revert BetNotFound();
        if (b.user != msg.sender) revert BetNotOwner();
        if (b.status != BetStatus.PLAYER_TURN) revert InvalidBetStatus();

        uint256 mult = b.currentMultiplierE18;
        uint256 payout = (b.amount * mult) / ONE;

        core.releaseReservation(b.collateral, b.reserved);
        b.reserved = 0;
        if (payout > 0) {
            core.payOut(b.user, b.collateral, payout, b.isFreeBet, b.amount);
        }
        core.recordSettlement(b.collateral, b.amount, payout);

        b.payout = payout;
        b.outcome = Outcome.CASHED_OUT;
        b.status = BetStatus.RESOLVED;
        b.resolvedAt = block.timestamp;

        emit CashedOut(betId, msg.sender, mult, payout);
        emit BetResolved(betId, msg.sender, Outcome.CASHED_OUT, payout);
    }

    function adminCancelBet(uint256 betId) external override nonReentrant onlyResolver {
        Bet storage b = bets[betId];
        if (b.status == BetStatus.NONE) revert BetNotFound();
        if (b.status != BetStatus.PLAYER_TURN && b.status != BetStatus.AWAITING_NEXT_CARD) revert InvalidBetStatus();
        _cancelBet(betId, true);
    }

    function _cancelBet(uint256 betId, bool adminCancelled) internal {
        Bet storage b = bets[betId];
        // Clear any in-flight VRF mapping so a late callback can't be matched back to this bet.
        // The bet's status check inside `onVrfFulfilled` already guards against double-spend
        // (cancelled bets early-return), but deleting the mapping avoids dangling storage and
        // is required hygiene for AWAITING_NEXT_CARD cancels (HiLo is multi-round, unlike the
        // other games whose cancel paths can only run with no VRF in flight)
        if (b.requestId != 0) delete requestIdToBetId[b.requestId];

        // Refund: original stake (running multiplier doesn't add stake; only the original bet
        // was pulled). Mid-run cancellation forfeits any accumulated multiplier. For free bets,
        // the refund routes back to FBH and credits the user's free-bet balance (reusable)
        core.releaseReservation(b.collateral, b.reserved);
        b.reserved = 0;
        core.payOut(b.user, b.collateral, b.amount, b.isFreeBet, b.amount);
        // Decrement core's pending-stake counter (stake == refund so zero P&L impact on the
        // breaker gauge — cancels don't generate house P&L)
        core.recordSettlement(b.collateral, b.amount, b.amount);
        b.payout = b.amount;
        b.status = BetStatus.CANCELLED;
        b.resolvedAt = block.timestamp;
        emit BetCancelled(betId, b.user, b.amount, adminCancelled);
    }

    /* ========== VRF CALLBACK ========== */

    /// @dev `nonReentrant` defends against malicious-token transfer hooks calling cashout/guess
    /// mid-callback (relevant on the wrong-guess branch where IERC20.transfer to referrer fires)
    function onVrfFulfilled(uint256 requestId, uint256[] calldata randomWords) external override nonReentrant {
        if (msg.sender != address(core)) revert InvalidSender();
        uint256 betId = requestIdToBetId[requestId];
        if (betId == 0) return;
        delete requestIdToBetId[requestId];

        Bet storage b = bets[betId];
        if (b.status != BetStatus.AWAITING_NEXT_CARD) return;

        uint8 newCard = uint8(randomWords[0] % DECK_SIZE);
        uint8 newRank = _rank(newCard);
        Direction dir = b.pendingDirection;

        bool isPush = newRank == MIDPOINT_RANK;
        bool isCorrect = !isPush &&
            ((dir == Direction.ABOVE && newRank > MIDPOINT_RANK) || (dir == Direction.BELOW && newRank < MIDPOINT_RANK));

        b.lastCard = newCard;
        b.cards.push(newCard);

        if (isPush) {
            ++b.pushCount;
            b.outcomes.push(uint8(CardOutcome.PUSH));
            b.multipliersE18.push(b.currentMultiplierE18); // unchanged
            b.status = BetStatus.PLAYER_TURN;
            emit NextCardDealt(betId, b.requestId, b.user, newCard, false, true, b.currentMultiplierE18);
        } else if (isCorrect) {
            ++b.correctCount;
            uint256 factor = _multiplierFactorE18();
            uint256 newMult = (b.currentMultiplierE18 * factor) / ONE;
            if (newMult > maxMultiplierE18) newMult = maxMultiplierE18;
            b.currentMultiplierE18 = newMult;
            b.outcomes.push(uint8(CardOutcome.HIT));
            b.multipliersE18.push(newMult);
            b.status = BetStatus.PLAYER_TURN;
            emit NextCardDealt(betId, b.requestId, b.user, newCard, true, false, newMult);
        } else {
            // Wrong guess — lose. Per-turn history records the pre-bust (frozen) multiplier so
            // FE can render "you were at Nx before busting". Skip referrer payment when the
            // bet was placed with a free bet — the user lost no real funds, so no referral fee
            uint256 frozenMult = b.currentMultiplierE18;
            b.outcomes.push(uint8(CardOutcome.BUST));
            b.multipliersE18.push(frozenMult);
            // CEI: write all terminal-state fields before any external call (defense beyond
            // `nonReentrant` — re-entry would see status=RESOLVED and bounce off the early-return)
            uint256 reserved = b.reserved;
            b.reserved = 0;
            b.outcome = Outcome.WRONG_GUESS;
            b.status = BetStatus.RESOLVED;
            b.resolvedAt = block.timestamp;
            core.releaseReservation(b.collateral, reserved);
            core.recordSettlement(b.collateral, b.amount, 0);
            if (!b.isFreeBet) {
                core.payReferrer(b.user, b.collateral, b.amount);
            }
            emit NextCardDealt(betId, b.requestId, b.user, newCard, false, false, 0);
            emit BetResolved(betId, b.user, Outcome.WRONG_GUESS, 0);
        }
    }

    /* ========== MULTIPLIER ========== */

    /// @inheritdoc ICasinoHiLo
    function multiplierFactorE18() external view override returns (uint256) {
        return _multiplierFactorE18();
    }

    /// @notice Per-correct-guess multiplier factor: `(12 - 13*HE) / 6` in 1e18 precision.
    /// Constant across rounds (no rank dependency in the above/below-8 game).
    /// At HE=2%: (12 - 0.26) / 6 = 1.9567x
    function _multiplierFactorE18() internal view returns (uint256) {
        return (12 * ONE - 13 * houseEdgeE18) / WINNING_RANKS_PER_DIRECTION;
    }

    function _rank(uint8 card) internal pure returns (uint8) {
        return card / 4;
    }

    /// @notice Per-game bet-size gate. `core.effectiveMinBetUsd` / `effectiveMaxBetUsd` overrides
    /// (set via `CasinoCoreV2.setMinBetPerGameUsd` / `setMaxBetPerGameUsd`) take precedence; when
    /// unset (zero), `MIN_BET_USD` is the default floor and there is no explicit max ceiling —
    /// the bet is still capped indirectly by `effectiveMaxProfitUsd` via the `MaxProfitExceeded`
    /// check in `_placeBet`
    function _checkBetSize(address collateral, uint256 amount) internal view {
        uint256 amountUsd = core.getUsdValue(collateral, amount);
        uint256 minBet = core.effectiveMinBetUsd(address(this));
        if (minBet == 0) minBet = MIN_BET_USD;
        if (amountUsd < minBet) revert InvalidAmount();
        uint256 maxBet = core.effectiveMaxBetUsd(address(this));
        if (maxBet != 0 && amountUsd > maxBet) revert AboveMaxBet();
    }

    /* ========== ADMIN ========== */

    /// @dev IN-FLIGHT BETS SEE THE NEW VALUE on subsequent guesses. There is no per-bet
    /// snapshot. Operator must pause the game (`setGamePaused` on core) and let pending bets
    /// settle before retuning. Raising `houseEdgeE18` mid-bet lowers the per-correct-guess
    /// factor for existing bets; lowering raises it. Either way it's user-unexpected
    function setHouseEdge(uint256 newHouseEdgeE18) external onlyOwner {
        if (newHouseEdgeE18 < MIN_HOUSE_EDGE_E18 || newHouseEdgeE18 > MAX_HOUSE_EDGE_E18) revert InvalidHouseEdge();
        houseEdgeE18 = newHouseEdgeE18;
    }

    /// @dev IN-FLIGHT BETS SEE THE NEW CAP. Reservations are sized at place time against the
    /// then-current cap; raising the cap mid-bet under-collateralizes existing bets (cashout
    /// can pay more than reserved). Operator must pause and let pending bets settle before
    /// raising. Lowering is safe (over-reserved) but still changes the user's max upside
    function setMaxMultiplier(uint256 newMaxE18) external onlyOwner {
        if (newMaxE18 < 2e18) revert InvalidAmount();
        maxMultiplierE18 = newMaxE18;
    }

    /// @dev AUDIT NOTE: unguarded against repointing to a malicious core (a compromised owner
    /// could swap to an EvilCore returning attacker-chosen randomness). Considered adding a
    /// registration check (`core.isGameRegistered(address(this))`) or a timelock; declined under
    /// trusted-owner model (multisig protects the key). Re-evaluate if the owner key surface widens
    function setCore(address _core) external onlyOwner {
        if (_core == address(0)) revert InvalidAddress();
        core = ICasinoCoreV2(_core);
    }

    function setManager(address _manager) external onlyOwner {
        if (_manager == address(0)) revert InvalidAddress();
        manager = ISportsAMMV2Manager(_manager);
    }

    function setPausedByRole(bool _paused) external onlyPauser {
        if (paused != _paused) {
            paused = _paused;
            if (_paused) lastPauseTime = block.timestamp;
            emit PauseChanged(_paused);
        }
    }

    /* ========== VIEWS ========== */

    function getBetBase(
        uint256 betId
    )
        external
        view
        override
        returns (
            address user,
            address collateral,
            uint256 amount,
            uint256 payout,
            uint256 placedAt,
            uint256 resolvedAt,
            BetStatus status,
            Outcome outcome
        )
    {
        Bet storage b = bets[betId];
        return (b.user, b.collateral, b.amount, b.payout, b.placedAt, b.resolvedAt, b.status, b.outcome);
    }

    function getBetState(
        uint256 betId
    )
        external
        view
        override
        returns (uint8 lastCard, uint256 currentMultiplierE18, uint8 guessCount, uint8 correctCount, uint8 pushCount)
    {
        Bet storage b = bets[betId];
        return (b.lastCard, b.currentMultiplierE18, b.guessCount, b.correctCount, b.pushCount);
    }

    /// @inheritdoc ICasinoHiLo
    function getBetCards(
        uint256 betId
    )
        external
        view
        override
        returns (uint8[] memory directions, uint8[] memory cards, uint8[] memory outcomes, uint256[] memory multipliersE18)
    {
        Bet storage b = bets[betId];
        return (b.directions, b.cards, b.outcomes, b.multipliersE18);
    }

    function getFullRecord(uint256 betId) external view override returns (FullRecord memory r) {
        Bet storage b = bets[betId];
        r.betId = betId;
        r.user = b.user;
        r.collateral = b.collateral;
        r.amount = b.amount;
        r.payout = b.payout;
        r.placedAt = b.placedAt;
        r.resolvedAt = b.resolvedAt;
        r.status = b.status;
        r.outcome = b.outcome;
        r.lastCard = b.lastCard;
        r.currentMultiplierE18 = b.currentMultiplierE18;
        r.guessCount = b.guessCount;
        r.correctCount = b.correctCount;
        r.pushCount = b.pushCount;
        r.isFreeBet = b.isFreeBet;
        r.lastRequestAt = b.lastRequestAt;
    }

    function getUserBetIds(address user, uint256 offset, uint256 limit) external view override returns (uint256[] memory) {
        return CasinoHandsLib.getUserBetIds(userBetIds[user], offset, limit);
    }

    function getRecentBetIds(uint256 offset, uint256 limit) external view override returns (uint256[] memory) {
        return CasinoHandsLib.getRecentBetIds(nextBetId, offset, limit);
    }

    /* ========== MODIFIERS ========== */

    function _requireRole(ISportsAMMV2Manager.Role role) internal view {
        if (msg.sender != owner && !manager.isWhitelistedAddress(msg.sender, role)) revert InvalidSender();
    }

    modifier onlyResolver() {
        _requireRole(ISportsAMMV2Manager.Role.MARKET_RESOLVING);
        _;
    }
    modifier onlyPauser() {
        _requireRole(ISportsAMMV2Manager.Role.TICKET_PAUSER);
        _;
    }
}

contracts/core/Casino/Keno.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";

import "../../utils/proxy/ProxyReentrancyGuard.sol";
import "../../utils/proxy/ProxyOwned.sol";
import "../../utils/proxy/ProxyPausable.sol";

import "../../interfaces/ISportsAMMV2Manager.sol";
import "../../interfaces/ICasinoCoreV2.sol";
import "../../interfaces/ICasinoGameCallback.sol";
import "../../interfaces/ICasinoKeno.sol";
import "./CasinoHandsLib.sol";

/// @title Keno
/// @author Overtime
/// @notice Single-shot Keno against a fixed 80-number pool. Player picks 1–10 numbers; one VRF
/// word draws 20 unique numbers via partial Fisher-Yates; payout = `bet × paytable[picks][hits]`.
/// Multipliers in 1e18 precision, hard-capped at 300x. Default paytables are strictly monotonic
/// per spot count (every additional hit pays strictly more, except the leading 0-bands)
/// @dev Two storage savers worth flagging:
///   - Picks and drawn numbers are stored as 128-bit bitmasks (numbers 1..80 → bits 0..79)
///   - Paytables sized exactly per spot count (`picks + 1` entries)
contract Keno is ICasinoKeno, ICasinoGameCallback, Initializable, ProxyOwned, ProxyPausable, ProxyReentrancyGuard {
    /* ========== CONSTANTS ========== */

    uint256 private constant ONE = 1e18;

    /// @notice Keno pool size (numbers 1..POOL_SIZE)
    uint8 public constant POOL_SIZE = 80;

    /// @notice Numbers drawn per round
    uint8 public constant DRAW_COUNT = 20;

    /// @notice Min/max picks the player can choose
    uint8 public constant MIN_PICKS = 1;
    uint8 public constant MAX_PICKS = 10;

    /// @notice Default minimum stake in USD (1e18 precision). Overridden when
    /// `core.effectiveMinBetUsd(keno)` is non-zero
    uint256 public constant MIN_BET_USD = 3e18;

    /// @notice Hard cap on any paytable entry. Per-bet liability = `bet × MAX_MULTIPLIER_E18`;
    /// `effectiveMaxProfitUsd(keno)` must clear that liability or `MaxProfitExceeded` reverts.
    /// To preserve the legacy $10 ceiling at deploy time, call
    /// `CasinoCoreV2.setMaxBetPerGameUsd(keno, 10e18)`
    uint256 public constant MAX_MULTIPLIER_E18 = 300e18;

    /// @dev `SHUFFLE_SHIFT_BITS` (16) and `SHUFFLE_SHIFT_MASK` (0xFFFF) live on `CasinoHandsLib`
    /// and are referenced inline. 16 bits per Fisher-Yates swap gives <0.04% bias on any
    /// remaining size in [60, 80]. Need 20 swaps total → 20 × 16 = 320 bits, so we re-hash
    /// the cursor once after consuming all 16 chunks of the first 256-bit word
    uint8 private constant CHUNKS_PER_WORD = 16; // 256 / SHUFFLE_SHIFT_BITS

    /* ========== ERRORS ========== */

    error InvalidAddress();
    error InvalidSender();
    error InvalidAmount();
    error InvalidCollateral();
    error InvalidPicks();
    error AboveMaxBet();
    error PaytableLengthMismatch();
    error MultiplierTooHigh();
    error MaxProfitExceeded();
    error BetNotFound();
    error BetNotOwner();
    error InvalidBetStatus();

    /* ========== STRUCTS ========== */

    struct Bet {
        address user;
        address collateral;
        uint256 amount;
        uint256 payout;
        uint256 placedAt;
        uint256 lastRequestAt;
        uint256 resolvedAt;
        uint256 reserved;
        uint256 requestId;
        uint128 picksMask; // bitmask over [1..80] using bit (n-1)
        uint128 drawnMask; // bitmask of the 20 drawn numbers (set in callback)
        uint256 multiplierE18;
        BetStatus status;
        uint8 picksCount;
        uint8 hits;
        // Stake was pulled from FreeBetsHolder via core.useFreeBet instead of core.pullFromUser.
        // Routes payouts back to FBH on resolve / cancel and skips referrer payment on losses
        bool isFreeBet;
        // Remaining net-profit budget for this bet in collateral units. Sized at placeBet from
        // `effectiveMaxProfitUsd × price`, capped against the worst-case uncapped profit
        // (`amount × (MAX_MULTIPLIER - 1)`). Resolve truncates final payout to stake + this so
        // the per-bet house loss never exceeds the configured USD cap regardless of stake size.
        // Appended at end of struct for storage-safe upgrade
        uint256 profitCapRemaining;
    }

    /* ========== STATE ========== */

    ICasinoCoreV2 public core;
    ISportsAMMV2Manager public manager;

    uint256 public nextBetId;

    mapping(uint256 => Bet) internal bets;
    mapping(uint256 => uint256) public requestIdToBetId;
    mapping(address => uint256[]) private userBetIds;

    /// @notice paytables[picksCount] = multipliers indexed by hit count, length = picksCount + 1
    mapping(uint8 => uint256[]) internal paytables;

    /* ========== INITIALIZER ========== */

    function initialize(address _owner, address _core, address _manager) external initializer {
        if (_owner == address(0) || _core == address(0) || _manager == address(0)) revert InvalidAddress();
        setOwner(_owner);
        initNonReentrant();
        core = ICasinoCoreV2(_core);
        manager = ISportsAMMV2Manager(_manager);
        nextBetId = 1;

        _setDefaultPaytables();
    }

    /// @dev Default paytables calibrated to 1.9%–3.1% edge per spot count. Strictly monotonic
    /// per spot count: every additional hit pays strictly more (except the leading 0-bands of
    /// near-zero-probability low-hit outcomes). Top tier of picks 8–10 reaches the 300x cap;
    /// rare-jackpot probability is vanishingly small (Pick 10 hitting 10 = 1.12e-7), so cap
    /// changes barely move RTP — most RTP comes from the 3–6 hit range.
    ///
    /// Implementation note: leading zero bands are left implicit — Solidity zero-initializes
    /// `new uint256[](n)`, so only the non-zero hit-count multipliers are assigned. Memory
    /// variable `m` is reassigned per pick (old allocation becomes unreachable but Solidity
    /// memory persists for the call; total transient cost is bounded and only paid once at init)
    function _setDefaultPaytables() internal {
        uint256[] memory m;
        // Pick 1:  RTP 98.000% (edge 2.000%)
        m = new uint256[](2);
        m[1] = (392 * ONE) / 100;
        _setDefault(1, m);
        // Pick 2:  RTP 98.101% (edge 1.899%)
        m = new uint256[](3);
        m[1] = ONE;
        m[2] = 10 * ONE;
        _setDefault(2, m);
        // Pick 3:  RTP 97.128% (edge 2.872%)
        m = new uint256[](4);
        m[2] = 2 * ONE;
        m[3] = 50 * ONE;
        _setDefault(3, m);
        // Pick 4:  RTP 97.668% (edge 2.332%)
        m = new uint256[](5);
        m[2] = ONE;
        m[3] = 12 * ONE;
        m[4] = 80 * ONE;
        _setDefault(4, m);
        // Pick 5:  RTP 97.290% (edge 2.710%)
        m = new uint256[](6);
        m[2] = ONE;
        m[3] = 3 * ONE;
        m[4] = 33 * ONE;
        m[5] = 80 * ONE;
        _setDefault(5, m);
        // Pick 6:  RTP 97.942% (edge 2.058%)
        m = new uint256[](7);
        m[2] = ONE;
        m[3] = 2 * ONE;
        m[4] = 8 * ONE;
        m[5] = 55 * ONE;
        m[6] = 100 * ONE;
        _setDefault(6, m);
        // Pick 7:  Top tier 250x (was 100x duplicate). Adds ~0.04% RTP — still ~3% edge
        m = new uint256[](8);
        m[3] = 2 * ONE;
        m[4] = 6 * ONE;
        m[5] = 27 * ONE;
        m[6] = 100 * ONE;
        m[7] = 250 * ONE;
        _setDefault(7, m);
        // Pick 8:  Top tier 300x (was 100x duplicate). Adds ~0.10% RTP — still ~2.2% edge
        m = new uint256[](9);
        m[3] = ONE;
        m[4] = 4 * ONE;
        m[5] = 18 * ONE;
        m[6] = 38 * ONE;
        m[7] = 100 * ONE;
        m[8] = 300 * ONE;
        _setDefault(8, m);
        // Pick 9:  Tail [150, 300] (was [100, 100]). Adds ~0.07% RTP — still ~2.4% edge
        m = new uint256[](10);
        m[3] = ONE;
        m[4] = 3 * ONE;
        m[5] = 7 * ONE;
        m[6] = 20 * ONE;
        m[7] = 70 * ONE;
        m[8] = 150 * ONE;
        m[9] = 300 * ONE;
        _setDefault(9, m);
        // Pick 10: Tail [100, 200, 300] (was [100, 100, 100]). Adds ~0.15% RTP — still ~2.9% edge
        m = new uint256[](11);
        m[3] = ONE;
        m[4] = 2 * ONE;
        m[5] = 4 * ONE;
        m[6] = 11 * ONE;
        m[7] = 38 * ONE;
        m[8] = 100 * ONE;
        m[9] = 200 * ONE;
        m[10] = 300 * ONE;
        _setDefault(10, m);
    }

    function _setDefault(uint8 picksCount, uint256[] memory mults) internal {
        uint256[] storage tbl = paytables[picksCount];
        for (uint256 i; i < mults.length; ++i) {
            tbl.push(mults[i]);
        }
    }

    /* ========== PLACE / CANCEL ========== */

    /// @notice Place a Keno bet. `picks` must be sorted ascending, deduplicated, all in [1, 80].
    /// `isFreeBet=true` pulls the stake from FreeBetsHolder, `false` from the user's wallet.
    /// One VRF word resolves the bet — no `makeAction` because there are no mid-game actions
    function placeBet(
        address collateral,
        uint256 amount,
        uint8[] calldata picks,
        address referrer,
        bool isFreeBet
    ) external override nonReentrant notPaused returns (uint256 betId, uint256 requestId) {
        return _placeBet(collateral, amount, picks, referrer, isFreeBet);
    }

    function _placeBet(
        address collateral,
        uint256 amount,
        uint8[] calldata picks,
        address referrer,
        bool isFreeBet
    ) internal returns (uint256 betId, uint256 requestId) {
        (uint128 picksMask, uint256 reservation, uint256 cappedProfit) = _validateAndReserve(collateral, amount, picks);
        if (isFreeBet) {
            core.useFreeBet(msg.sender, collateral, amount);
        } else {
            core.pullFromUser(msg.sender, collateral, amount);
        }
        if (referrer != address(0)) core.setReferrer(referrer, msg.sender);
        core.reserveOrRevert(collateral, reservation);
        requestId = core.requestRandomWords(1);
        betId = nextBetId++;
        _writeBet(
            betId,
            requestId,
            collateral,
            amount,
            uint8(picks.length),
            picksMask,
            reservation,
            cappedProfit,
            isFreeBet
        );
        emit BetPlaced(betId, requestId, msg.sender, collateral, amount, uint8(picks.length), picksMask);
    }

    /// @notice Validates picks/size, computes the soft-truncated profit budget for this bet, and
    /// returns the reservation (stake + cappedProfit). Mirrors the 3CP/UTH/VideoPoker pattern:
    /// allow any bet size up to `effectiveMaxBetUsd`, then clamp the actual payout at resolve so
    /// the per-bet house loss never exceeds `effectiveMaxProfitUsd`. Previous behaviour
    /// hard-rejected at place time, which capped max bet at `cap / (MAX_MULTIPLIER - 1)` — only
    /// ~$3.34 under a $1000 cap with the 300× multiplier
    function _validateAndReserve(
        address collateral,
        uint256 amount,
        uint8[] calldata picks
    ) internal view returns (uint128 picksMask, uint256 reservation, uint256 cappedProfit) {
        if (amount == 0) revert InvalidAmount();
        if (!core.supportedCollateral(collateral)) revert InvalidCollateral();
        uint256 picksLen = picks.length;
        if (picksLen < MIN_PICKS || picksLen > MAX_PICKS) revert InvalidPicks();
        picksMask = _picksToMask(picks); // enforces sorted+unique+range
        _checkBetSize(collateral, amount);
        // Uncapped worst-case profit = amount × (MAX_MULTIPLIER - 1). Truncate to the per-game
        // USD profit cap (converted to collateral units). Used both for the reservation here
        // and as `profitCapRemaining` at resolve
        uint256 worst = (amount * (MAX_MULTIPLIER_E18 - ONE)) / ONE;
        uint256 capCollateral = core.collateralFromUsd(collateral, core.effectiveMaxProfitUsd(address(this)));
        cappedProfit = worst > capCollateral ? capCollateral : worst;
        // Reservation = stake-back + capped worst-case profit (matches max actual payout)
        reservation = amount + cappedProfit;
    }

    /// @notice Per-game bet-size gate. `core.effectiveMinBetUsd` / `effectiveMaxBetUsd` overrides
    /// (set via `CasinoCoreV2.setMinBetPerGameUsd` / `setMaxBetPerGameUsd`) take precedence; when
    /// unset (zero), `MIN_BET_USD` is the default floor and there is no explicit max ceiling —
    /// the per-bet house loss is then implicitly bounded by the profit-cap soft-truncation in
    /// `onVrfFulfilled`
    function _checkBetSize(address collateral, uint256 amount) internal view {
        uint256 amountUsd = core.getUsdValue(collateral, amount);
        uint256 minBet = core.effectiveMinBetUsd(address(this));
        if (minBet == 0) minBet = MIN_BET_USD;
        if (amountUsd < minBet) revert InvalidAmount();
        uint256 maxBet = core.effectiveMaxBetUsd(address(this));
        if (maxBet != 0 && amountUsd > maxBet) revert AboveMaxBet();
    }

    function _writeBet(
        uint256 betId,
        uint256 requestId,
        address collateral,
        uint256 amount,
        uint8 picksCount,
        uint128 picksMask,
        uint256 reservation,
        uint256 cappedProfit,
        bool isFreeBet
    ) internal {
        Bet storage b = bets[betId];
        b.user = msg.sender;
        b.collateral = collateral;
        b.amount = amount;
        b.placedAt = block.timestamp;
        b.lastRequestAt = block.timestamp;
        b.requestId = requestId;
        b.reserved = reservation;
        b.picksMask = picksMask;
        b.picksCount = picksCount;
        b.status = BetStatus.PENDING;
        b.isFreeBet = isFreeBet;
        b.profitCapRemaining = cappedProfit;
        requestIdToBetId[requestId] = betId;
        userBetIds[msg.sender].push(betId);
    }

    function adminCancelBet(uint256 betId) external override nonReentrant onlyResolver {
        Bet storage b = bets[betId];
        if (b.status == BetStatus.NONE) revert BetNotFound();
        if (b.status != BetStatus.PENDING) revert InvalidBetStatus();
        _cancelBet(betId, true);
    }

    function _cancelBet(uint256 betId, bool adminCancelled) internal {
        Bet storage b = bets[betId];
        if (b.requestId != 0) delete requestIdToBetId[b.requestId];
        core.releaseReservation(b.collateral, b.reserved);
        b.reserved = 0;
        core.payOut(b.user, b.collateral, b.amount, b.isFreeBet, b.amount);
        // Decrement core's pending-stake counter (stake == refund → zero P&L impact)
        core.recordSettlement(b.collateral, b.amount, b.amount);
        b.payout = b.amount;
        b.status = BetStatus.CANCELLED;
        b.resolvedAt = block.timestamp;
        emit BetCancelled(betId, b.user, b.amount, adminCancelled);
    }

    /* ========== VRF CALLBACK ========== */

    /// @dev `nonReentrant` defends against malicious-token transfer hooks re-entering any of
    /// this contract's mutating entries (placeBet / adminCancelBet) mid-payout for a double-spend
    function onVrfFulfilled(uint256 requestId, uint256[] calldata randomWords) external override nonReentrant {
        if (msg.sender != address(core)) revert InvalidSender();
        uint256 betId = requestIdToBetId[requestId];
        if (betId == 0) return;
        delete requestIdToBetId[requestId];

        Bet storage b = bets[betId];
        if (b.status != BetStatus.PENDING) return;

        uint128 drawnMask = _drawNumbers(randomWords[0]);
        uint8 hits = CasinoHandsLib.popcount(drawnMask & b.picksMask);
        uint256 mult = paytables[b.picksCount][hits];
        uint256 payout = (b.amount * mult) / ONE;

        // Soft-cap net profit at the per-bet budget. The paytable's top tier (Pick 8/9/10 at 300×)
        // can produce payouts well above the cap on large stakes; truncating here keeps the
        // per-bet house loss within `effectiveMaxProfitUsd` (matches 3CP/UTH/VideoPoker)
        if (payout > b.amount) {
            uint256 profit = payout - b.amount;
            if (profit > b.profitCapRemaining) profit = b.profitCapRemaining;
            payout = b.amount + profit;
            b.profitCapRemaining -= profit;
        }

        // CEI: write all bet state before any external call so a hostile re-entry (defense
        // beyond `nonReentrant`) would see status=RESOLVED and be blocked by the early-return
        uint256 reserved = b.reserved;
        b.reserved = 0;
        b.drawnMask = drawnMask;
        b.hits = hits;
        b.multiplierE18 = mult;
        b.payout = payout;
        b.status = BetStatus.RESOLVED;
        b.resolvedAt = block.timestamp;

        core.releaseReservation(b.collateral, reserved);

        if (payout > 0) {
            core.payOut(b.user, b.collateral, payout, b.isFreeBet, b.amount);
        }
        core.recordSettlement(b.collateral, b.amount, payout);

        // Skip referrer payment on free bets — user lost no real funds, so no referral fee
        if (payout < b.amount && !b.isFreeBet) {
            core.payReferrer(b.user, b.collateral, b.amount - payout);
        }

        emit BetResolved(betId, b.requestId, b.user, drawnMask, hits, mult, payout);
    }

    /* ========== RNG: DRAW 20 UNIQUE FROM 80 ========== */

    /// @notice Partial Fisher-Yates over a notional [1..80] deck. We need 20 swaps, consuming
    /// 20 × 16 = 320 bits. The first 256-bit VRF word gives 16 chunks; once exhausted, we
    /// re-hash to extend. The rehash is keyed on the ORIGINAL `word` plus a salt counter — NOT
    /// the consumed cursor. After 16 chunks the cursor has been shifted right by exactly 256
    /// bits and equals zero, so `keccak256(abi.encode(cursor))` would be a compile-time
    /// constant and the last 4 swaps would sample fixed deck positions, breaking uniformity
    /// over C(80,20). Binding to `word` keeps every chunk dependent on the VRF output.
    /// Max bias per swap on `remaining ∈ [60, 80]` is ≤ 16/65536 ≈ 0.024%, well below
    /// industry standard
    function _drawNumbers(uint256 word) internal pure returns (uint128 mask) {
        uint8[POOL_SIZE] memory deck;
        for (uint8 i; i < POOL_SIZE; ++i) {
            deck[i] = i + 1; // numbers 1..80
        }
        uint256 cursor = word;
        uint8 chunksLeft = CHUNKS_PER_WORD;
        uint8 rehashes;
        for (uint8 i; i < DRAW_COUNT; ++i) {
            if (chunksLeft == 0) {
                ++rehashes;
                cursor = uint256(keccak256(abi.encode(word, rehashes)));
                chunksLeft = CHUNKS_PER_WORD;
            }
            uint256 remaining = uint256(POOL_SIZE - i);
            uint256 j = uint256(i) + ((cursor & CasinoHandsLib.SHUFFLE_SHIFT_MASK) % remaining);
            cursor >>= CasinoHandsLib.SHUFFLE_SHIFT_BITS;
            --chunksLeft;
            uint8 tmp = deck[i];
            deck[i] = deck[uint8(j)];
            deck[uint8(j)] = tmp;
        }
        for (uint8 i; i < DRAW_COUNT; ++i) {
            mask |= uint128(1) << (deck[i] - 1);
        }
    }

    /// @notice Validates picks are sorted ascending, unique, and in [1, 80]. Returns bitmask
    function _picksToMask(uint8[] calldata picks) internal pure returns (uint128 mask) {
        uint8 prev;
        for (uint256 i; i < picks.length; ++i) {
            uint8 n = picks[i];
            if (n < 1 || n > POOL_SIZE) revert InvalidPicks();
            if (i > 0 && n <= prev) revert InvalidPicks(); // enforces ascending + unique
            mask |= uint128(1) << (n - 1);
            prev = n;
        }
    }

    /* ========== ADMIN: PAYTABLE MANAGEMENT ========== */

    /// @notice Owner can replace a paytable. `multipliers` length must equal picksCount + 1.
    /// @dev IN-FLIGHT BETS SEE THE NEW PAYTABLE. There is no per-bet snapshot. To avoid changing
    /// outcomes on bets already placed, pause the game (`setGamePaused` on core) and let all
    /// pending bets settle before calling this. The 2% house-edge floor and monotonicity are
    /// NOT enforced on-chain — verify off-chain (KenoEdgeSim.js) before submitting
    /// @dev AUDIT NOTE: Plinko enforces an on-chain RTP floor in `_checkRtp` (binomial weights);
    /// Keno's per-pick RTP is hypergeometric (`C(20,k) × C(60,n-k) / C(80,n)`) so an equivalent
    /// guard would require precomputed P(k|n) tables across 10 spot counts × 11 hit counts.
    /// Considered adding it; declined as expensive code-complexity for a setter that fires
    /// rarely. KenoEdgeSim.js plus trusted-owner discipline is the chosen defense
    function setPaytable(uint8 picksCount, uint256[] calldata multipliers) external onlyOwner {
        if (picksCount < MIN_PICKS || picksCount > MAX_PICKS) revert InvalidPicks();
        if (multipliers.length != uint256(picksCount) + 1) revert PaytableLengthMismatch();
        for (uint256 i; i < multipliers.length; ++i) {
            if (multipliers[i] > MAX_MULTIPLIER_E18) revert MultiplierTooHigh();
        }
        delete paytables[picksCount];
        for (uint256 i; i < multipliers.length; ++i) {
            paytables[picksCount].push(multipliers[i]);
        }
        emit PaytableUpdated(picksCount, multipliers);
    }

    /* ========== VIEWS ========== */

    function getBetBase(
        uint256 betId
    )
        external
        view
        override
        returns (
            address user,
            address collateral,
            uint256 amount,
            uint256 payout,
            uint256 placedAt,
            uint256 resolvedAt,
            BetStatus status,
            uint8 picksCount,
            uint8 hits,
            uint128 picksMask,
            uint128 drawnMask,
            uint256 multiplierE18
        )
    {
        Bet storage b = bets[betId];
        return (
            b.user,
            b.collateral,
            b.amount,
            b.payout,
            b.placedAt,
            b.resolvedAt,
            b.status,
            b.picksCount,
            b.hits,
            b.picksMask,
            b.drawnMask,
            b.multiplierE18
        );
    }

    function getFullRecord(uint256 betId) external view override returns (FullRecord memory r) {
        Bet storage b = bets[betId];
        r.betId = betId;
        r.user = b.user;
        r.collateral = b.collateral;
        r.amount = b.amount;
        r.payout = b.payout;
        r.placedAt = b.placedAt;
        r.resolvedAt = b.resolvedAt;
        r.status = b.status;
        r.picksCount = b.picksCount;
        r.hits = b.hits;
        r.picksMask = b.picksMask;
        r.drawnMask = b.drawnMask;
        r.multiplierE18 = b.multiplierE18;
        r.isFreeBet = b.isFreeBet;
        r.lastRequestAt = b.lastRequestAt;
    }

    function getPaytable(uint8 picksCount) external view override returns (uint256[] memory) {
        return paytables[picksCount];
    }

    function getMaxMultiplierE18() external pure override returns (uint256) {
        return MAX_MULTIPLIER_E18;
    }

    function getUserBetIds(address user, uint256 offset, uint256 limit) external view override returns (uint256[] memory) {
        return CasinoHandsLib.getUserBetIds(userBetIds[user], offset, limit);
    }

    function getRecentBetIds(uint256 offset, uint256 limit) external view override returns (uint256[] memory) {
        return CasinoHandsLib.getRecentBetIds(nextBetId, offset, limit);
    }

    /* ========== ADMIN: WIRING + PAUSE ========== */

    /// @dev AUDIT NOTE: unguarded against repointing to a malicious core. Trusted-owner model;
    /// see HiLo.setCore for rationale
    function setCore(address _core) external onlyOwner {
        if (_core == address(0)) revert InvalidAddress();
        core = ICasinoCoreV2(_core);
    }

    function setManager(address _manager) external onlyOwner {
        if (_manager == address(0)) revert InvalidAddress();
        manager = ISportsAMMV2Manager(_manager);
    }

    function setPausedByRole(bool _paused) external onlyPauser {
        if (paused != _paused) {
            paused = _paused;
            if (_paused) lastPauseTime = block.timestamp;
            emit PauseChanged(_paused);
        }
    }

    /* ========== MODIFIERS ========== */

    function _requireRole(ISportsAMMV2Manager.Role role) internal view {
        if (msg.sender != owner && !manager.isWhitelistedAddress(msg.sender, role)) revert InvalidSender();
    }

    modifier onlyResolver() {
        _requireRole(ISportsAMMV2Manager.Role.MARKET_RESOLVING);
        _;
    }
    modifier onlyPauser() {
        _requireRole(ISportsAMMV2Manager.Role.TICKET_PAUSER);
        _;
    }
}

contracts/core/Casino/OvertimeBonusHolde.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";

import "../../utils/proxy/ProxyReentrancyGuard.sol";
import "../../utils/proxy/ProxyOwned.sol";
import "../../utils/proxy/ProxyPausable.sol";

import "../../interfaces/ISportsAMMV2Manager.sol";
import "../../interfaces/ICasinoCoreV2.sol";
import "../../interfaces/ICasinoGameCallback.sol";
import "../../interfaces/ICasinoOvertimeBonusHoldem.sol";
import "./CasinoHandsLib.sol";

/// @title OvertimeBonusHoldem
/// @author Overtime
/// @notice Texas Hold'em Bonus / Casino Hold'em variant vs the dealer. Player posts ANTE
/// (required) + optional BONUS side bet. Pre-flop is "Play 2× or fold"; flop / turn each allow
/// one optional 1× raise or check. The river is a free showdown card (no raise) — the last
/// player decision is on the turn, matching standard Texas Hold'em Bonus. No dealer
/// qualification. ANTE pays 1:1 only when the
/// final player hand is Straight or better; otherwise pushes on player win. Tie pushes all
/// main-game bets. Bonus side bet resolves independently from player + dealer hole cards
///
/// Staged VRF reveals cards only as needed by the upcoming decision — future cards are not in
/// storage before the player commits, so `eth_getStorageAt` peeks can't be used to gain edge
///
/// Locked paytables:
/// - Ante:  1:1 on Straight / Flush / FH / 4K / SF / Royal when player wins; push otherwise
/// - Plays: each (PreFlop 2× / Flop 1× / Turn 1×) pays 1:1 on player win, pushes on
///   tie, loses on dealer win. There is no river raise — the river completes the board for a
///   free showdown
/// - Bonus: AA-vs-AA 499:1 (capped from CoinPoker's 1000:1 to match VP/UTH 500× ceiling) /
///   AA 30:1 / AKs 25:1 / AQs|AJs 20:1 / AK 15:1 / JJ|QQ|KK 10:1 /
///   AQ|AJ 5:1 / 22-TT 3:1
///   Note: header reads as net-odds (":1") because that's how players see paytables. Storage
///   constants are "for 1" — `mult` is total return per unit stake on win, so net win = mult − 1.
///   E.g., header "AA 30:1" ⇔ `BONUS_MULT_AA = 31`, header "AA-vs-AA 499:1" ⇔ `..._AA_VS_AA = 500`
contract OvertimeBonusHoldem is
    ICasinoOvertimeBonusHoldem,
    ICasinoGameCallback,
    Initializable,
    ProxyOwned,
    ProxyPausable,
    ProxyReentrancyGuard
{
    /* ========== CONSTANTS ========== */

    uint256 private constant ONE = 1e18;
    uint256 public constant MIN_BET_USD = 3e18;

    uint8 private constant DECK_SIZE = 52;
    uint8 private constant HOLE_CARDS = 2;
    uint8 private constant FLOP_CARDS = 3;
    uint8 private constant COMMUNITY_CARDS = 5;

    uint8 private constant RANK_TWO = 2;
    uint8 private constant RANK_TEN = 10;
    uint8 private constant RANK_JACK = 11;
    uint8 private constant RANK_QUEEN = 12;
    uint8 private constant RANK_KING = 13;
    uint8 private constant RANK_ACE = 14;

    // Raise sizes (multipliers on ante)
    uint256 private constant PRE_FLOP_PLAY_MULT = 2;
    uint256 private constant POST_FLOP_RAISE_MULT = 1;

    /// @notice Worst-case NET PROFIT per ANTE unit (= total return - total stake-out, in "for 1"):
    ///   - Ante 1:1 win (Flush+) profit = 1× ante     (return 2× - stake 1×)
    ///   - Play 2× stake × 1:1 win profit = 2× ante   (return 4× - stake 2×)
    ///   - Flop 1× stake × 1:1 win profit = 1× ante
    ///   - Turn 1× stake × 1:1 win profit = 1× ante
    /// Total max main-game profit = 5× ante (the river is a free showdown card, not a raise leg).
    /// Bonus side adds up to 499× bonus profit on its own
    uint256 private constant MAX_MAIN_PROFIT_PER_ANTE = 5;

    /// @notice Bonus paytable in "for 1" semantics (totalReturn = stake × mult on win). Anything
    /// not matched loses (mult = 0). Top tier capped at 500× to match the project-wide ceiling
    /// used by VideoPoker (Royal=500) and UTH Blind (Royal=500); the original CoinPoker spec is
    /// "1000:1" but the $1000 per-bet profit cap already truncates above ~333× at $3 stake, so
    /// the displayed-but-unreachable 1000× would be misleading
    uint256 private constant BONUS_MULT_AA_VS_AA = 500;
    uint256 private constant BONUS_MULT_AA = 31;
    uint256 private constant BONUS_MULT_AK_SUITED = 26;
    uint256 private constant BONUS_MULT_AQ_AJ_SUITED = 21;
    uint256 private constant BONUS_MULT_AK_OFF = 16;
    uint256 private constant BONUS_MULT_JJ_QQ_KK = 11;
    uint256 private constant BONUS_MULT_AQ_AJ_OFF = 6;
    uint256 private constant BONUS_MULT_LOW_PAIR = 4; // 22 through 10-10
    uint256 private constant MAX_BONUS_MULT = BONUS_MULT_AA_VS_AA;

    /* ========== ERRORS ========== */

    error InvalidAddress();
    error InvalidSender();
    error InvalidAmount();
    error InvalidCollateral();
    error AboveMaxBet();
    error BetNotFound();
    error BetNotOwner();
    error InvalidBetStatus();
    /// @notice Reverted when `placeBetWithFreeBet` is called with a non-zero `bonusAmount`.
    /// The Bonus side bet's free-bet stake would otherwise be refunded via the FBH split on a
    /// winning main game, paying the user back for a losing-bonus leg as if no loss occurred
    error BonusNotAllowedForFreeBet();
    /// @notice Reverted by `makeAction` when an unknown action code is supplied
    error InvalidAction();

    /* ========== STRUCTS ========== */

    struct Bet {
        address user;
        address collateral;
        uint256 anteAmount;
        uint256 bonusAmount;
        uint256 playAmount; // 2× ante if pre-flop Play taken, 0 if folded pre-flop
        uint256 flopRaise; // 1× ante if raised on flop
        uint256 turnRaise; // 1× ante if raised on turn
        uint256 riverRaise; // 1× ante if raised on river
        uint256 totalPayout;
        uint256 placedAt;
        uint256 lastRequestAt;
        uint256 resolvedAt;
        uint256 reservation;
        uint256 requestId;
        uint8[2] playerHole;
        uint8[5] community;
        uint8[2] dealerHole;
        BetStatus status;
        Outcome outcome;
        // Per-leg payout breakdown (FE rendering)
        uint256 antePayout;
        uint256 bonusPayout;
        uint256 playPayout;
        uint256 flopPayout;
        uint256 turnPayout;
        uint256 riverPayout;
        // Free-bet flag — stake legs pulled from FBH instead of user wallet. All settlements
        // route through FBH; referrer payments suppressed on net loss
        bool isFreeBet;
        // Set true when the player folded at some street. AWAITING_RESOLVE then deals dealer
        // hole only and skips showdown comparison — all main legs already lost
        bool folded;
        // Count of community cards revealed so far (0, 3, 4, or 5). Used by `_onResolve` to
        // build the dealer-hole exclusion mask correctly — `community[i] != 0` is unreliable
        // because card index 0 (2♣) is a legal card
        uint8 communityCount;
        // Per-bet profit cap (collateral units). See `_cappedProfit`
        uint256 profitCapRemaining;
    }

    /* ========== STATE ========== */

    ICasinoCoreV2 public core;
    ISportsAMMV2Manager public manager;

    uint256 public nextBetId;

    mapping(uint256 => Bet) internal bets;
    mapping(uint256 => uint256) public requestIdToBetId;
    mapping(address => uint256[]) private userBetIds;

    /* ========== INITIALIZER ========== */

    function initialize(address _owner, address _core, address _manager) external initializer {
        if (_owner == address(0) || _core == address(0) || _manager == address(0)) revert InvalidAddress();
        setOwner(_owner);
        initNonReentrant();
        core = ICasinoCoreV2(_core);
        manager = ISportsAMMV2Manager(_manager);
        nextBetId = 1;
    }

    /* ========== PLACE BET ========== */

    /// @inheritdoc ICasinoOvertimeBonusHoldem
    function placeBet(
        address collateral,
        uint256 anteAmount,
        uint256 bonusAmount,
        address referrer,
        bool isFreeBet
    ) external override nonReentrant notPaused returns (uint256 betId, uint256 requestId) {
        return _placeBet(collateral, anteAmount, bonusAmount, referrer, isFreeBet);
    }

    function _placeBet(
        address collateral,
        uint256 anteAmount,
        uint256 bonusAmount,
        address referrer,
        bool isFreeBet
    ) internal returns (uint256 betId, uint256 requestId) {
        if (anteAmount == 0) revert InvalidAmount();
        if (!core.supportedCollateral(collateral)) revert InvalidCollateral();
        // Free-bet flow cannot bundle the optional Bonus side bet. The bonus would otherwise be
        // pulled from FBH along with the ante, and on a winning main game its lost stake would
        // be returned to the user via the FBH stake-back split — effectively paying the user
        // back 1:1 for a losing-bonus leg. Disallow rather than add a side-of-totalPay carve-out;
        // matches how TCP's PairPlus is separately settled (no free-bet refund on a losing PP)
        if (isFreeBet && bonusAmount > 0) revert BonusNotAllowedForFreeBet();
        _checkBetSize(collateral, anteAmount, bonusAmount);
        uint256 cappedProfit = _cappedProfit(collateral, anteAmount, bonusAmount);

        // Pull ANTE + BONUS upfront. Raises pull additional stake on demand at each street
        uint256 stakeIn = anteAmount + bonusAmount;
        if (isFreeBet) {
            core.useFreeBet(msg.sender, collateral, stakeIn);
        } else {
            core.pullFromUser(msg.sender, collateral, stakeIn);
        }
        if (referrer != address(0)) core.setReferrer(referrer, msg.sender);

        // Reservation = stakes_pulled_so_far + capped net-profit budget. Raises top up later
        uint256 reservation = stakeIn + cappedProfit;
        core.reserveOrRevert(collateral, reservation);

        requestId = core.requestRandomWords(1);
        betId = nextBetId++;

        Bet storage b = bets[betId];
        b.user = msg.sender;
        b.collateral = collateral;
        b.anteAmount = anteAmount;
        b.bonusAmount = bonusAmount;
        b.placedAt = block.timestamp;
        b.lastRequestAt = block.timestamp;
        b.requestId = requestId;
        b.status = BetStatus.AWAITING_HOLE;
        b.reservation = reservation;
        b.isFreeBet = isFreeBet;
        b.profitCapRemaining = cappedProfit;

        requestIdToBetId[requestId] = betId;
        userBetIds[msg.sender].push(betId);

        emit BetPlaced(betId, requestId, msg.sender, collateral, anteAmount, bonusAmount);
    }

    /* ========== DECISIONS ========== */

    /// @notice Single-selector mid-game dispatcher. Action codes:
    ///   0 = playPreFlop   1 = foldPreFlop
    ///   2 = raiseFlop     3 = checkFlop
    ///   4 = raiseTurn     5 = checkTurn
    /// The turn is the final decision — after it the river completes the board for a free
    /// showdown, so there are no river action codes
    /// @dev AUDIT NOTE: mid-game pause traps in-flight winners; see HiLo.makeAction rationale
    function makeAction(uint256 betId, uint8 action) external override nonReentrant notPaused returns (uint256 requestId) {
        if (action == 0) return _playPreFlop(betId);
        if (action == 1) return _foldPreFlop(betId);
        if (action == 2) return _raiseFlop(betId);
        if (action == 3) return _checkFlop(betId);
        if (action == 4) return _raiseTurn(betId);
        if (action == 5) return _checkTurn(betId);
        revert InvalidAction();
    }

    function _playPreFlop(uint256 betId) internal returns (uint256 requestId) {
        Bet storage b = bets[betId];
        _requireOwnedAt(b, BetStatus.PRE_FLOP_TURN);
        _pullRaiseStake(b, PRE_FLOP_PLAY_MULT);
        b.playAmount = b.anteAmount * PRE_FLOP_PLAY_MULT;
        requestId = _requestVrf(betId, b, BetStatus.AWAITING_FLOP);
        emit PlayedPreFlop(betId, requestId, b.user, b.playAmount);
    }

    function _foldPreFlop(uint256 betId) internal returns (uint256 requestId) {
        Bet storage b = bets[betId];
        _requireOwnedAt(b, BetStatus.PRE_FLOP_TURN);
        // When bonus = 0 the dealer hole is irrelevant (bonus pays nothing, fold means
        // main = 0). Skip the VRF round-trip and settle in this tx. `requestId == 0` is the
        // FE-visible signal that no VRF callback is coming
        if (b.bonusAmount == 0) {
            b.folded = true;
            emit Folded(betId, b.user, BetStatus.PRE_FLOP_TURN);
            _settle(betId, b);
            return 0;
        }
        return _markFoldAndRequestResolve(betId, b);
    }

    function _raiseFlop(uint256 betId) internal returns (uint256 requestId) {
        Bet storage b = bets[betId];
        _requireOwnedAt(b, BetStatus.FLOP_TURN);
        _pullRaiseStake(b, POST_FLOP_RAISE_MULT);
        b.flopRaise = b.anteAmount * POST_FLOP_RAISE_MULT;
        requestId = _requestVrf(betId, b, BetStatus.AWAITING_TURN);
        emit RaisedFlop(betId, requestId, b.user, b.flopRaise);
    }

    function _checkFlop(uint256 betId) internal returns (uint256 requestId) {
        Bet storage b = bets[betId];
        _requireOwnedAt(b, BetStatus.FLOP_TURN);
        requestId = _requestVrf(betId, b, BetStatus.AWAITING_TURN);
        emit CheckedFlop(betId, requestId, b.user);
    }

    /// @dev The turn is the final betting decision. Both raise and check advance straight to
    /// AWAITING_RESOLVE, where the river card is dealt for a free showdown (no river raise). This
    /// removes the +EV "raise-only-when-ahead-with-complete-information" leg that made the game
    /// player-beatable — see `_onResolve`
    function _raiseTurn(uint256 betId) internal returns (uint256 requestId) {
        Bet storage b = bets[betId];
        _requireOwnedAt(b, BetStatus.TURN_TURN);
        _pullRaiseStake(b, POST_FLOP_RAISE_MULT);
        b.turnRaise = b.anteAmount * POST_FLOP_RAISE_MULT;
        requestId = _requestVrf(betId, b, BetStatus.AWAITING_RESOLVE);
        emit RaisedTurn(betId, requestId, b.user, b.turnRaise);
    }

    function _checkTurn(uint256 betId) internal returns (uint256 requestId) {
        Bet storage b = bets[betId];
        _requireOwnedAt(b, BetStatus.TURN_TURN);
        requestId = _requestVrf(betId, b, BetStatus.AWAITING_RESOLVE);
        emit CheckedTurn(betId, requestId, b.user);
    }

    /// @dev Shared fold path: emit, mark, advance to AWAITING_RESOLVE with dealer-hole-only VRF.
    /// Only `foldPreFlop` uses this — post-flop folds were removed because `checkFlop`/`checkTurn`
    /// are free, making any fold after the flop strictly dominated in money EV (lose ante
    /// guaranteed vs free chance to win at showdown)
    function _markFoldAndRequestResolve(uint256 betId, Bet storage b) internal returns (uint256 requestId) {
        BetStatus prior = b.status;
        b.folded = true;
        requestId = _requestVrf(betId, b, BetStatus.AWAITING_RESOLVE);
        emit Folded(betId, b.user, prior);
    }

    /* ========== CANCEL ========== */

    /// @notice Operator-only cancel. Refunds all stakes pulled (ante + bonus + play + any
    /// raises). User cancel was removed to close a VRF-callback front-run surface; stuck bets
    /// are now resolved exclusively via `adminCancelBet`
    function adminCancelBet(uint256 betId) external override nonReentrant onlyResolver {
        Bet storage b = bets[betId];
        if (b.status == BetStatus.NONE) revert BetNotFound();
        if (b.status == BetStatus.RESOLVED || b.status == BetStatus.CANCELLED) revert InvalidBetStatus();
        _cancelBet(betId, true);
    }

    function _cancelBet(uint256 betId, bool adminCancelled) internal {
        Bet storage b = bets[betId];
        if (b.requestId != 0) delete requestIdToBetId[b.requestId];

        // Refund every stake that's been pulled so far. ante + bonus pulled at place, then
        // playAmount/flopRaise/turnRaise/riverRaise on raises
        uint256 refund = b.anteAmount + b.bonusAmount + b.playAmount + b.flopRaise + b.turnRaise + b.riverRaise;

        core.releaseReservation(b.collateral, b.reservation);
        b.reservation = 0;

        core.payOut(b.user, b.collateral, refund, b.isFreeBet, refund);
        core.recordSettlement(b.collateral, refund, refund);

        b.totalPayout = refund;
        b.status = BetStatus.CANCELLED;
        b.resolvedAt = block.timestamp;
        emit BetCancelled(betId, b.user, refund, adminCancelled);
    }

    /* ========== VRF CALLBACK ========== */

    /// @dev `nonReentrant` defends against malicious-token transfer hooks re-entering any of
    /// this contract's mutating entries (placeBet / makeAction / adminCancelBet) mid-payout
    /// for a double-spend
    function onVrfFulfilled(uint256 requestId, uint256[] calldata randomWords) external override nonReentrant {
        if (msg.sender != address(core)) revert InvalidSender();
        uint256 betId = requestIdToBetId[requestId];
        if (betId == 0) return;
        delete requestIdToBetId[requestId];

        Bet storage b = bets[betId];
        uint256 word = randomWords[0];
        BetStatus s = b.status;

        if (s == BetStatus.AWAITING_HOLE) {
            _onHoleDealt(betId, b, word);
        } else if (s == BetStatus.AWAITING_FLOP) {
            _onFlopDealt(betId, b, word);
        } else if (s == BetStatus.AWAITING_TURN) {
            _onTurnDealt(betId, b, word);
        } else if (s == BetStatus.AWAITING_RESOLVE) {
            _onResolve(betId, b, word);
        }
        // any other state: stale callback, ignore
    }

    function _onHoleDealt(uint256 betId, Bet storage b, uint256 word) internal {
        uint8[] memory deck = CasinoHandsLib.initDeck(DECK_SIZE, 0);
        CasinoHandsLib.partialFisherYates(deck, HOLE_CARDS, word);
        b.playerHole[0] = deck[0];
        b.playerHole[1] = deck[1];
        b.status = BetStatus.PRE_FLOP_TURN;
        emit PlayerHoleDealt(betId, b.requestId, b.user, deck[0], deck[1]);
    }

    function _onFlopDealt(uint256 betId, Bet storage b, uint256 word) internal {
        uint64 mask = _holeMask(b);
        uint8[] memory deck = CasinoHandsLib.initDeck(DECK_SIZE - HOLE_CARDS, mask);
        CasinoHandsLib.partialFisherYates(deck, FLOP_CARDS, word);
        b.community[0] = deck[0];
        b.community[1] = deck[1];
        b.community[2] = deck[2];
        b.communityCount = 3;
        b.status = BetStatus.FLOP_TURN;
        emit FlopDealt(betId, b.requestId, b.user, deck[0], deck[1], deck[2]);
    }

    function _onTurnDealt(uint256 betId, Bet storage b, uint256 word) internal {
        uint64 mask = _holeFlopMask(b);
        uint8[] memory deck = CasinoHandsLib.initDeck(DECK_SIZE - HOLE_CARDS - FLOP_CARDS, mask);
        CasinoHandsLib.partialFisherYates(deck, 1, word);
        b.community[3] = deck[0];
        b.communityCount = 4;
        b.status = BetStatus.TURN_TURN;
        emit TurnDealt(betId, b.requestId, b.user, deck[0]);
    }

    function _onResolve(uint256 betId, Bet storage b, uint256 word) internal {
        // Exclusion mask = player hole + however many community cards were dealt before this VRF
        // fired (tracked by `communityCount` since card 0 = 2♣ is a valid card and can't be
        // distinguished from "not dealt" via value alone)
        uint64 mask = _holeMask(b);
        uint8 cc = b.communityCount;
        for (uint8 i; i < cc; ++i) {
            mask |= uint64(1) << b.community[i];
        }

        // Non-folded hands reach resolve straight from the turn decision, so the river (5th
        // community card) has NOT been dealt yet — it is now a free showdown card rather than a
        // raise leg. Deal the remaining board card(s) + the 2 dealer hole cards from a single
        // shuffle: the first `missing` draws complete the board, the next 2 are the dealer hole.
        // Folded hands skip the board (main game already lost; only Bonus needs the dealer hole)
        uint8 missing = b.folded ? 0 : (COMMUNITY_CARDS - cc);
        uint8 deckSize = DECK_SIZE - HOLE_CARDS - cc;
        uint8[] memory deck = CasinoHandsLib.initDeck(deckSize, mask);
        CasinoHandsLib.partialFisherYates(deck, missing + 2, word);

        if (missing > 0) {
            for (uint8 i; i < missing; ++i) {
                b.community[cc + i] = deck[i];
            }
            b.communityCount = cc + missing;
            emit RiverDealt(betId, b.requestId, b.user, b.community[COMMUNITY_CARDS - 1]);
        }

        b.dealerHole[0] = deck[missing];
        b.dealerHole[1] = deck[missing + 1];

        _settle(betId, b);
    }

    /* ========== SETTLEMENT ========== */

    function _settle(uint256 betId, Bet storage b) internal {
        // Bonus: pays from player + dealer hole only (always evaluated)
        uint256 bonusPay = _evaluateBonusPayout(b);

        uint256 stakeOut = _totalStake(b);
        uint256 mainPay = 0;
        Outcome outcome;

        if (b.folded) {
            outcome = Outcome.FOLDED;
            // Main game lost; bonus alone might still pay
        } else {
            // Need to evaluate hands and compare. Build 7-card sets for player and dealer
            uint8[7] memory pSeven;
            uint8[7] memory dSeven;
            for (uint8 i; i < 2; ++i) {
                pSeven[i] = b.playerHole[i];
                dSeven[i] = b.dealerHole[i];
            }
            for (uint8 i; i < 5; ++i) {
                pSeven[i + 2] = b.community[i];
                dSeven[i + 2] = b.community[i];
            }
            uint256 pVal = CasinoHandsLib.evaluateCards7(CasinoHandsLib.toMemArray7(pSeven));
            uint256 dVal = CasinoHandsLib.evaluateCards7(CasinoHandsLib.toMemArray7(dSeven));

            if (pVal > dVal) {
                outcome = Outcome.PLAYER_WIN;
                // Ante: 1:1 on Straight+ (mult=2), push on lower wins (mult=1)
                uint256 anteMult = _antePayoutMult(pVal);
                b.antePayout = b.anteAmount * anteMult;
                b.playPayout = b.playAmount * 2; // 1:1 win (mult=2 in "for 1")
                b.flopPayout = b.flopRaise * 2;
                b.turnPayout = b.turnRaise * 2;
                b.riverPayout = b.riverRaise * 2;
            } else if (pVal < dVal) {
                outcome = Outcome.DEALER_WIN;
                // All main legs lose (paid 0)
            } else {
                outcome = Outcome.TIE;
                // Main legs push (stake-back)
                b.antePayout = b.anteAmount;
                b.playPayout = b.playAmount;
                b.flopPayout = b.flopRaise;
                b.turnPayout = b.turnRaise;
                b.riverPayout = b.riverRaise;
            }
            mainPay = b.antePayout + b.playPayout + b.flopPayout + b.turnPayout + b.riverPayout;
        }

        b.bonusPayout = bonusPay;
        uint256 totalPay = mainPay + bonusPay;

        // Soft-cap net profit. Truncate the variance-heavy Bonus leg first (top tier lives here)
        if (totalPay > stakeOut) {
            uint256 profit = totalPay - stakeOut;
            if (profit > b.profitCapRemaining) {
                uint256 cut = profit - b.profitCapRemaining;
                if (b.bonusPayout >= cut) {
                    b.bonusPayout -= cut;
                    bonusPay = b.bonusPayout;
                } else {
                    cut -= b.bonusPayout;
                    bonusPay = 0;
                    b.bonusPayout = 0;
                    if (b.antePayout >= cut) {
                        b.antePayout -= cut;
                    } else {
                        cut -= b.antePayout;
                        b.antePayout = 0;
                        // Spill into play legs in deterministic order
                        if (b.playPayout >= cut) b.playPayout -= cut;
                        else {
                            cut -= b.playPayout;
                            b.playPayout = 0;
                            if (b.flopPayout >= cut) b.flopPayout -= cut;
                            else {
                                cut -= b.flopPayout;
                                b.flopPayout = 0;
                                if (b.turnPayout >= cut) b.turnPayout -= cut;
                                else {
                                    cut -= b.turnPayout;
                                    b.turnPayout = 0;
                                    // Final leg in the cascade. Invariant is
                                    // `profitCapRemaining ≤ sum_of_leg_profits`, so `cut` should
                                    // always be ≤ b.riverPayout by this point. Guard defensively
                                    // anyway — a future paytable change that breaks the invariant
                                    // would otherwise underflow here and strand the bet in
                                    // AWAITING_RESOLVE until adminCancelBet. Zeroing is the
                                    // mathematically-correct fallback (leg can't go negative)
                                    if (b.riverPayout >= cut) b.riverPayout -= cut;
                                    else {
                                        // Silent-zero fallback — structurally unreachable today.
                                        // Emit residual so off-chain monitoring catches the
                                        // regression if it ever fires
                                        emit CapSpillResidual(betId, cut - b.riverPayout);
                                        b.riverPayout = 0;
                                    }
                                }
                            }
                        }
                    }
                }
            }
            // Recompute `totalPay` from the (possibly-reduced) legs so the emitted/stored
            // breakdown always matches the user-visible total. Mirrors
            // `OvertimeUltimateHoldem._onResolveFulfilled` — using legs as the source of truth
            // bulletproofs the `legSum == totalPay` invariant against a future cascade refactor
            // that could break cut-conservation (legs-as-truth → under-pays defensively;
            // cap-as-truth → over-pays — the worse failure mode)
            totalPay = b.antePayout + b.playPayout + b.flopPayout + b.turnPayout + b.riverPayout + b.bonusPayout;
            uint256 paidProfit = totalPay > stakeOut ? totalPay - stakeOut : 0;
            b.profitCapRemaining -= paidProfit;
            mainPay = totalPay - b.bonusPayout;
            bonusPay = b.bonusPayout;
        }

        // Release reservation & pay
        core.releaseReservation(b.collateral, b.reservation);
        b.reservation = 0;

        if (totalPay > 0) {
            core.payOut(b.user, b.collateral, totalPay, b.isFreeBet, stakeOut);
        }
        core.recordSettlement(b.collateral, stakeOut, totalPay);

        if (totalPay < stakeOut && !b.isFreeBet) {
            core.payReferrer(b.user, b.collateral, stakeOut - totalPay);
        }

        b.outcome = outcome;
        b.totalPayout = totalPay;
        b.status = BetStatus.RESOLVED;
        b.resolvedAt = block.timestamp;

        emit BetResolved(
            betId,
            b.requestId,
            b.user,
            outcome,
            b.dealerHole[0],
            b.dealerHole[1],
            b.antePayout,
            b.bonusPayout,
            mainPay,
            totalPay
        );
    }

    function _totalStake(Bet storage b) internal view returns (uint256) {
        return b.anteAmount + b.bonusAmount + b.playAmount + b.flopRaise + b.turnRaise + b.riverRaise;
    }

    /// @notice Ante paytable: 1:1 on Straight+ when player wins (mult = 2 in "for 1"), push on
    /// lower wins (mult = 1 = stake-back only)
    function _antePayoutMult(uint256 handValue) internal pure returns (uint256) {
        uint8 class_ = uint8(handValue >> 20);
        if (class_ >= CasinoHandsLib.CLASS_STRAIGHT) return 2;
        return 1;
    }

    /// @notice Bonus payout based on player + dealer hole cards. Highest applicable prize wins
    function _evaluateBonusPayout(Bet storage b) internal view returns (uint256) {
        if (b.bonusAmount == 0) return 0;

        // Extract ranks/suits for both holes
        uint8 pr0 = (b.playerHole[0] % 13) + RANK_TWO;
        uint8 pr1 = (b.playerHole[1] % 13) + RANK_TWO;
        uint8 ps0 = b.playerHole[0] / 13;
        uint8 ps1 = b.playerHole[1] / 13;
        uint8 dr0 = (b.dealerHole[0] % 13) + RANK_TWO;
        uint8 dr1 = (b.dealerHole[1] % 13) + RANK_TWO;

        uint256 mult = _bonusMult(pr0, pr1, ps0, ps1, dr0, dr1);
        if (mult == 0) return 0;
        return b.bonusAmount * mult;
    }

    /// @dev Decision tree for the bonus paytable. Highest qualifying tier wins
    function _bonusMult(uint8 pr0, uint8 pr1, uint8 ps0, uint8 ps1, uint8 dr0, uint8 dr1) internal pure returns (uint256) {
        bool playerAA = (pr0 == RANK_ACE && pr1 == RANK_ACE);
        bool dealerAA = (dr0 == RANK_ACE && dr1 == RANK_ACE);
        if (playerAA && dealerAA) return BONUS_MULT_AA_VS_AA;
        if (playerAA) return BONUS_MULT_AA;

        // Suited Ace combos (player only)
        bool suited = (ps0 == ps1);
        uint8 hi = pr0 >= pr1 ? pr0 : pr1;
        uint8 lo = pr0 >= pr1 ? pr1 : pr0;
        bool isPair = (pr0 == pr1);

        if (!isPair && hi == RANK_ACE) {
            if (suited) {
                if (lo == RANK_KING) return BONUS_MULT_AK_SUITED;
                if (lo == RANK_QUEEN || lo == RANK_JACK) return BONUS_MULT_AQ_AJ_SUITED;
            } else {
                if (lo == RANK_KING) return BONUS_MULT_AK_OFF;
                if (lo == RANK_QUEEN || lo == RANK_JACK) return BONUS_MULT_AQ_AJ_OFF;
            }
            return 0;
        }

        // Pair-based tiers
        if (isPair) {
            if (pr0 == RANK_JACK || pr0 == RANK_QUEEN || pr0 == RANK_KING) return BONUS_MULT_JJ_QQ_KK;
            if (pr0 >= RANK_TWO && pr0 <= RANK_TEN) return BONUS_MULT_LOW_PAIR;
        }

        return 0;
    }

    /* ========== HELPERS ========== */

    /// @notice Deck construction, Fisher-Yates shuffle, 7-card hand evaluator, top-N rank
    /// helpers, popcount, and value packing all live in `CasinoHandsLib` (internal pure,
    /// inlined at compile time — no DELEGATECALL, no separate deployment, no storage)

    function _holeMask(Bet storage b) internal view returns (uint64) {
        return (uint64(1) << b.playerHole[0]) | (uint64(1) << b.playerHole[1]);
    }

    function _holeFlopMask(Bet storage b) internal view returns (uint64) {
        return _holeMask(b) | (uint64(1) << b.community[0]) | (uint64(1) << b.community[1]) | (uint64(1) << b.community[2]);
    }

    /* ========== STAKE / SIZING ========== */

    /// @dev Free-bet raises pull additional stake from FBH (not the user's wallet). If the
    /// user's FBH balance is exhausted, every raise tx reverts and the user can only
    /// check/fold from that point (or wait out `cancelTimeout`). FE must gate raise buttons
    /// on remaining FBH balance for free-bet hands — there is no wallet-funded raise path
    function _pullRaiseStake(Bet storage b, uint256 mult) internal {
        uint256 raiseStake = b.anteAmount * mult;
        if (b.isFreeBet) core.useFreeBet(b.user, b.collateral, raiseStake);
        else core.pullFromUser(b.user, b.collateral, raiseStake);
        core.reserveOrRevert(b.collateral, raiseStake);
        b.reservation += raiseStake;
    }

    function _requestVrf(uint256 betId, Bet storage b, BetStatus next) internal returns (uint256 requestId) {
        requestId = core.requestRandomWords(1);
        b.requestId = requestId;
        b.lastRequestAt = block.timestamp;
        b.status = next;
        requestIdToBetId[requestId] = betId;
    }

    /// @notice Per-game bet-size gate. `MIN_BET_USD` floor applies to the required Ante AND, when
    /// present (> 0), the optional Bonus side bet — symmetric floor blocks dust Bonus bets that
    /// produce negligible payouts but still consume the full per-bet gas/VRF overhead. Bonus = 0
    /// still bypasses the check entirely (skip the side bet)
    function _checkBetSize(address collateral, uint256 anteAmount, uint256 bonusAmount) internal view {
        uint256 anteUsd = core.getUsdValue(collateral, anteAmount);
        uint256 minBet = core.effectiveMinBetUsd(address(this));
        if (minBet == 0) minBet = MIN_BET_USD;
        if (anteUsd < minBet) revert InvalidAmount();
        uint256 maxBet = core.effectiveMaxBetUsd(address(this));
        if (maxBet != 0 && anteUsd > maxBet) revert AboveMaxBet();
        if (bonusAmount > 0) {
            uint256 bonusUsd = core.getUsdValue(collateral, bonusAmount);
            if (bonusUsd < minBet) revert InvalidAmount();
            if (maxBet != 0 && bonusUsd > maxBet) revert AboveMaxBet();
        }
    }

    /// @notice Worst-case net profit cap (collateral units). Main game contributes
    /// `MAX_MAIN_PROFIT_PER_ANTE × ante` of profit (5× — see constant doc); bonus contributes
    /// `(MAX_BONUS_MULT - 1) × bonus`. Subtract 1 from bonus mult because the "for 1" multiplier
    /// already includes stake-back, so profit = (mult - 1) × stake. Truncated to per-game USD cap
    function _cappedProfit(address collateral, uint256 anteAmount, uint256 bonusAmount) internal view returns (uint256) {
        uint256 worst = anteAmount * MAX_MAIN_PROFIT_PER_ANTE + bonusAmount * (MAX_BONUS_MULT - 1);
        uint256 capCollateral = core.collateralFromUsd(collateral, core.effectiveMaxProfitUsd(address(this)));
        return worst > capCollateral ? capCollateral : worst;
    }

    /* ========== VIEWS ========== */

    function getBetBase(
        uint256 betId
    )
        external
        view
        override
        returns (
            address user,
            address collateral,
            uint256 anteAmount,
            uint256 bonusAmount,
            uint256 totalPayout,
            uint256 placedAt,
            uint256 resolvedAt,
            BetStatus status,
            Outcome outcome
        )
    {
        Bet storage b = bets[betId];
        return (
            b.user,
            b.collateral,
            b.anteAmount,
            b.bonusAmount,
            b.totalPayout,
            b.placedAt,
            b.resolvedAt,
            b.status,
            b.outcome
        );
    }

    function getFullRecord(uint256 betId) external view override returns (FullRecord memory r) {
        Bet storage b = bets[betId];
        r.betId = betId;
        r.user = b.user;
        r.collateral = b.collateral;
        r.anteAmount = b.anteAmount;
        r.bonusAmount = b.bonusAmount;
        r.playAmount = b.playAmount;
        r.flopRaise = b.flopRaise;
        r.turnRaise = b.turnRaise;
        r.riverRaise = b.riverRaise;
        r.totalPayout = b.totalPayout;
        r.antePayout = b.antePayout;
        r.bonusPayout = b.bonusPayout;
        r.playPayout = b.playPayout;
        r.flopPayout = b.flopPayout;
        r.turnPayout = b.turnPayout;
        r.riverPayout = b.riverPayout;
        r.placedAt = b.placedAt;
        r.resolvedAt = b.resolvedAt;
        r.status = b.status;
        r.outcome = b.outcome;
        r.playerHole = b.playerHole;
        r.community = b.community;
        r.dealerHole = b.dealerHole;
        r.isFreeBet = b.isFreeBet;
        r.lastRequestAt = b.lastRequestAt;
    }

    function getUserBetIds(address user, uint256 offset, uint256 limit) external view override returns (uint256[] memory) {
        return CasinoHandsLib.getUserBetIds(userBetIds[user], offset, limit);
    }

    function getRecentBetIds(uint256 offset, uint256 limit) external view override returns (uint256[] memory) {
        return CasinoHandsLib.getRecentBetIds(nextBetId, offset, limit);
    }

    /* ========== ADMIN ========== */

    /// @dev AUDIT NOTE: unguarded against repointing to a malicious core. Trusted-owner model;
    /// see HiLo.setCore for rationale
    function setCore(address _core) external onlyOwner {
        if (_core == address(0)) revert InvalidAddress();
        core = ICasinoCoreV2(_core);
    }

    function setManager(address _manager) external onlyOwner {
        if (_manager == address(0)) revert InvalidAddress();
        manager = ISportsAMMV2Manager(_manager);
    }

    function setPausedByRole(bool _paused) external onlyPauser {
        if (paused != _paused) {
            paused = _paused;
            if (_paused) lastPauseTime = block.timestamp;
            emit PauseChanged(_paused);
        }
    }

    /* ========== MODIFIERS / INTERNAL GUARDS ========== */

    function _requireOwnedAt(Bet storage b, BetStatus expected) internal view {
        if (b.status == BetStatus.NONE) revert BetNotFound();
        if (b.user != msg.sender) revert BetNotOwner();
        if (b.status != expected) revert InvalidBetStatus();
    }

    function _requireRole(ISportsAMMV2Manager.Role role) internal view {
        if (msg.sender != owner && !manager.isWhitelistedAddress(msg.sender, role)) revert InvalidSender();
    }

    modifier onlyResolver() {
        _requireRole(ISportsAMMV2Manager.Role.MARKET_RESOLVING);
        _;
    }
    modifier onlyPauser() {
        _requireRole(ISportsAMMV2Manager.Role.TICKET_PAUSER);
        _;
    }
}

contracts/core/Casino/OvertimeUltimateHo.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";

import "../../utils/proxy/ProxyReentrancyGuard.sol";
import "../../utils/proxy/ProxyOwned.sol";
import "../../utils/proxy/ProxyPausable.sol";

import "../../interfaces/ISportsAMMV2Manager.sol";
import "../../interfaces/ICasinoCoreV2.sol";
import "../../interfaces/ICasinoGameCallback.sol";
import "../../interfaces/ICasinoOvertimeUltimateHoldem.sol";
import "./CasinoHandsLib.sol";

/// @title OvertimeUltimateHoldem
/// @author Overtime
/// @notice Ultimate Texas Hold'em vs the dealer. Player posts Ante + Blind (equal). Three decision
/// points:
///   1. Pre-flop (see hole only): raise 3× ante OR check
///   2. Post-flop (see flop): raise 2× ante OR check (only if checked pre-flop)
///   3. Post-river (see all community): raise 1× ante OR fold (only if checked through)
///
/// Each decision triggers a separate VRF request so future cards aren't in storage when the player
/// commits (otherwise `eth_getStorageAt` would let players see the river / dealer hole and exploit).
///
/// @dev All funds, randomness, free-bets, and circuit-breaker accounting live in `CasinoCoreV2`.
///
/// Locked paytables (Vegas / Shuffle Master standard rules):
/// - Ante: pays 1:1 on player win, pushes on dealer not qualified, loses on dealer win
/// - Play: resolves on hand comparison regardless of dealer qualification — 1:1 on player win,
///   push on tie, loses on dealer win
/// - Blind (only when player wins, otherwise pushes on tie / loses on dealer win): Royal 500:1 /
///   SF 50:1 / 4oK 10:1 / FH 3:1 / Flush 1:1 / Straight 1:1; less than Straight pushes (Flush
///   dropped from 3:2 → 1:1 for EoR margin).
contract OvertimeUltimateHoldem is
    ICasinoOvertimeUltimateHoldem,
    ICasinoGameCallback,
    Initializable,
    ProxyOwned,
    ProxyPausable,
    ProxyReentrancyGuard
{
    /* ========== CONSTANTS ========== */

    uint256 private constant ONE = 1e18;
    uint256 public constant MIN_BET_USD = 3e18;

    uint8 private constant DECK_SIZE = 52;

    uint8 private constant HOLE_CARDS = 2;
    uint8 private constant FLOP_CARDS = 3;

    // Blind paytable (paid on top of stake when player wins). Below Straight = push (no bonus,
    // but stake returns — handled in resolution code by paying 1× the blind back as "stake-back").
    uint256 private constant BLIND_MULT_ROYAL = 500;
    uint256 private constant BLIND_MULT_STRAIGHT_FLUSH = 50;
    uint256 private constant BLIND_MULT_FOUR_OF_A_KIND = 10;
    uint256 private constant BLIND_MULT_FULL_HOUSE = 3;
    uint256 private constant BLIND_MULT_FLUSH = 1;
    uint256 private constant BLIND_MULT_STRAIGHT = 1;

    // Pre-flop raise multiplier (capped at 3× for EoR floor)
    uint256 private constant PRE_FLOP_RAISE_MULT = 3;
    uint256 private constant POST_FLOP_RAISE_MULT = 2;
    uint256 private constant RIVER_RAISE_MULT = 1;

    // Worst-case total stake-out in ante multiples = ante (1) + blind (1) + max play raise
    // (PRE_FLOP_RAISE_MULT = 3) = 5. Used by `_cappedProfit` to derive worst-case profit as
    // (MAX_PAYOUT_ANTE_MULT - WORST_CASE_STAKE_ANTE_MULT) × ante
    uint256 private constant WORST_CASE_STAKE_ANTE_MULT = 2 + PRE_FLOP_RAISE_MULT;

    // Reservation: worst-case payout at placeBet time.
    //   Player raises 3× pre-flop and hits a Royal AND wins everything:
    //   - Ante side: ante stake-back + 1× win = 2 × ante
    //   - Blind side: blind stake-back + 500× = 501 × blind = 501 × ante (blind == ante)
    //   - Play side:  3 × ante stake-back + 3 × ante win = 6 × ante
    //   Total = 509 × ante
    uint256 private constant MAX_PAYOUT_ANTE_MULT = 509;

    /* ========== ERRORS ========== */

    error InvalidAddress();
    error InvalidSender();
    error InvalidAmount();
    error InvalidCollateral();
    error AboveMaxBet();
    error BetNotFound();
    error BetNotOwner();
    error InvalidBetStatus();
    /// @notice Reverted by `makeAction` when an unknown action code is supplied
    error InvalidAction();

    /* ========== STRUCTS ========== */

    struct Bet {
        address user;
        address collateral;
        uint256 anteAmount; // also = blindAmount (equal by rule)
        uint256 playAmount; // set when player raises (3×, 2×, or 1× ante); 0 if folded/no-raise
        uint256 totalPayout;
        uint256 placedAt;
        uint256 lastRequestAt;
        uint256 resolvedAt;
        uint256 reservation; // single combined reservation (worst-case payout)
        uint256 requestId;
        uint8[2] playerHole;
        uint8[5] community; // [flop0, flop1, flop2, turn, river]
        uint8[2] dealerHole;
        BetStatus status;
        Outcome outcome;
        uint256 antePayout;
        uint256 blindPayout;
        uint256 playPayout;
        // Bet placed with free-bet balance — Ante/Blind at place and raise(s) pulled from FBH.
        // All settlements route through FBH; referrer payments suppressed on loss
        bool isFreeBet;
        // Remaining net-profit budget for this bet in collateral units. Sized at placeBet from
        // `effectiveMaxProfitUsd × price`, capped against the worst-case uncapped profit.
        // Resolve truncates final payout to stakeOut + this. Appended at end for storage-safe
        // upgrade
        uint256 profitCapRemaining;
    }

    /* ========== STATE ========== */

    ICasinoCoreV2 public core;
    ISportsAMMV2Manager public manager;

    uint256 public nextBetId;

    mapping(uint256 => Bet) internal bets;
    mapping(uint256 => uint256) public requestIdToBetId;
    mapping(address => uint256[]) private userBetIds;

    /* ========== INITIALIZER ========== */

    function initialize(address _owner, address _core, address _manager) external initializer {
        if (_owner == address(0) || _core == address(0) || _manager == address(0)) revert InvalidAddress();
        setOwner(_owner);
        initNonReentrant();
        core = ICasinoCoreV2(_core);
        manager = ISportsAMMV2Manager(_manager);
        nextBetId = 1;
    }

    /* ========== PLACE BET ========== */

    /// @notice Places a UTH bet. Pulls Ante + Blind (equal amounts) upfront from FBH (`isFreeBet`)
    /// or the user's wallet, triggers VRF1 for the player's two hole cards. Subsequent raises
    /// pull from the same source — if FBH runs short on a free-bet flow, the next raise reverts
    /// and the user must check (or fold at river)
    function placeBet(
        address collateral,
        uint256 anteAmount,
        address referrer,
        bool isFreeBet
    ) external override nonReentrant notPaused returns (uint256 betId, uint256 requestId) {
        return _placeBet(collateral, anteAmount, referrer, isFreeBet);
    }

    function _placeBet(
        address collateral,
        uint256 anteAmount,
        address referrer,
        bool isFreeBet
    ) internal returns (uint256 betId, uint256 requestId) {
        if (anteAmount == 0) revert InvalidAmount();
        if (!core.supportedCollateral(collateral)) revert InvalidCollateral();
        _checkBetSize(collateral, anteAmount);
        uint256 cappedProfit = _cappedProfit(collateral, anteAmount);

        // Pull Ante + Blind from user / FBH
        uint256 stakeIn = anteAmount * 2;
        if (isFreeBet) {
            core.useFreeBet(msg.sender, collateral, stakeIn);
        } else {
            core.pullFromUser(msg.sender, collateral, stakeIn);
        }
        if (referrer != address(0)) core.setReferrer(referrer, msg.sender);

        // Reservation = stakes_pulled_so_far + capped net-profit budget. Raise paths top this
        // up with the raise amount (covers larger stake-back potential)
        uint256 reservation = stakeIn + cappedProfit;
        core.reserveOrRevert(collateral, reservation);

        requestId = core.requestRandomWords(1);
        betId = nextBetId++;

        Bet storage b = bets[betId];
        b.user = msg.sender;
        b.collateral = collateral;
        b.anteAmount = anteAmount;
        b.placedAt = block.timestamp;
        b.lastRequestAt = block.timestamp;
        b.requestId = requestId;
        b.status = BetStatus.AWAITING_DEAL;
        b.reservation = reservation;
        b.isFreeBet = isFreeBet;
        b.profitCapRemaining = cappedProfit;

        requestIdToBetId[requestId] = betId;
        userBetIds[msg.sender].push(betId);

        emit BetPlaced(betId, requestId, msg.sender, collateral, anteAmount);
    }

    /* ========== DECISION POINTS ========== */

    /// @notice Single-selector mid-game dispatcher. Action codes:
    ///   0 = playPreFlop   — pre-flop raise (3× ante); reveals all community + dealer hole at VRF2
    ///   1 = checkPreFlop  — defer; reveals flop only
    ///   2 = playPostFlop  — post-flop raise (2× ante); reveals turn + river + dealer at VRF3
    ///   3 = checkPostFlop — defer to river
    ///   4 = playRiver     — river raise (1× ante); reveals dealer at VRF4
    ///   5 = fold          — post-river only; forfeits Ante + Blind
    /// @dev AUDIT NOTE: mid-game pause traps in-flight winners; see HiLo.makeAction rationale
    function makeAction(uint256 betId, uint8 action) external override nonReentrant notPaused returns (uint256 requestId) {
        if (action == 0) return _playPreFlop(betId);
        if (action == 1) return _checkPreFlop(betId);
        if (action == 2) return _playPostFlop(betId);
        if (action == 3) return _checkPostFlop(betId);
        if (action == 4) return _playRiver(betId);
        if (action == 5) {
            _fold(betId);
            return 0;
        }
        revert InvalidAction();
    }

    function _playPreFlop(uint256 betId) internal returns (uint256 requestId) {
        Bet storage b = bets[betId];
        _requireOwnedAt(b, BetStatus.PRE_FLOP_TURN);
        _pullPlayStake(b, PRE_FLOP_RAISE_MULT);
        requestId = _requestVrf(betId, b, BetStatus.AWAITING_RESOLVE);
        emit RaisedPreFlop(betId, requestId, b.user, b.playAmount);
    }

    function _checkPreFlop(uint256 betId) internal returns (uint256 requestId) {
        Bet storage b = bets[betId];
        _requireOwnedAt(b, BetStatus.PRE_FLOP_TURN);
        requestId = _requestVrf(betId, b, BetStatus.AWAITING_FLOP);
        emit CheckedPreFlop(betId, requestId, b.user);
    }

    function _playPostFlop(uint256 betId) internal returns (uint256 requestId) {
        Bet storage b = bets[betId];
        _requireOwnedAt(b, BetStatus.POST_FLOP_TURN);
        _pullPlayStake(b, POST_FLOP_RAISE_MULT);
        requestId = _requestVrf(betId, b, BetStatus.AWAITING_RESOLVE);
        emit RaisedPostFlop(betId, requestId, b.user, b.playAmount);
    }

    function _checkPostFlop(uint256 betId) internal returns (uint256 requestId) {
        Bet storage b = bets[betId];
        _requireOwnedAt(b, BetStatus.POST_FLOP_TURN);
        requestId = _requestVrf(betId, b, BetStatus.AWAITING_TURN_RIVER);
        emit CheckedPostFlop(betId, requestId, b.user);
    }

    function _playRiver(uint256 betId) internal returns (uint256 requestId) {
        Bet storage b = bets[betId];
        _requireOwnedAt(b, BetStatus.POST_RIVER_TURN);
        _pullPlayStake(b, RIVER_RAISE_MULT);
        requestId = _requestVrf(betId, b, BetStatus.AWAITING_RESOLVE);
        emit RaisedRiver(betId, requestId, b.user, b.playAmount);
    }

    function _fold(uint256 betId) internal {
        Bet storage b = bets[betId];
        _requireOwnedAt(b, BetStatus.POST_RIVER_TURN);

        // Release the full reservation (game ends here — no payout)
        core.releaseReservation(b.collateral, b.reservation);
        b.reservation = 0;

        // Record loss: stake = ante + blind (+ playAmount for forward-compat — POST_RIVER_TURN
        // is unreachable after a raise today, so playAmount is always 0 here. Including it
        // defensively guards against a future state-machine change that allowed fold-after-raise
        uint256 lostStake = b.anteAmount * 2 + b.playAmount;
        core.recordSettlement(b.collateral, lostStake, 0);
        if (!b.isFreeBet) {
            core.payReferrer(b.user, b.collateral, lostStake);
        }

        b.status = BetStatus.RESOLVED;
        b.outcome = Outcome.FOLDED;
        b.resolvedAt = block.timestamp;
        emit Folded(betId, b.user);
    }

    /* ========== CANCEL ========== */

    /// @notice Operator-only cancel. Refunds all stakes pulled (ante + blind + any raises).
    /// User cancel was removed to close a VRF-callback front-run surface where a user with
    /// mempool access could observe the imminent VRF fulfillment, compute the resolved hand
    /// off-chain, and front-run a losing draw with a cheaper cancel. Stuck bets (stalled VRF
    /// or user walked away mid-decision) are now resolved exclusively via `adminCancelBet`
    function adminCancelBet(uint256 betId) external override nonReentrant onlyResolver {
        Bet storage b = bets[betId];
        if (b.status == BetStatus.NONE) revert BetNotFound();
        if (b.status == BetStatus.RESOLVED || b.status == BetStatus.CANCELLED) revert InvalidBetStatus();
        _cancelBet(betId, true);
    }

    function _cancelBet(uint256 betId, bool adminCancelled) internal {
        Bet storage b = bets[betId];
        // Clear any in-flight VRF mapping so a late callback's mapping lookup is a no-op
        // (status-check would also catch it, but matches the hygiene pattern of the other 4 games)
        if (b.requestId != 0) delete requestIdToBetId[b.requestId];

        // Refund: ante + blind + whatever play stake was pulled. playAmount is 0 unless the
        // player has already committed a raise at some decision point
        uint256 refund = b.anteAmount * 2 + b.playAmount;

        // Release full reservation — no payout happens on cancel
        core.releaseReservation(b.collateral, b.reservation);
        b.reservation = 0;

        // Refund stakes — routes back to FBH if free-bet
        core.payOut(b.user, b.collateral, refund, b.isFreeBet, refund);

        // Decrement core's pending-stake counter (stake == refund → zero P&L impact)
        core.recordSettlement(b.collateral, refund, refund);

        b.totalPayout = refund;
        b.status = BetStatus.CANCELLED;
        b.resolvedAt = block.timestamp;
        emit BetCancelled(betId, b.user, refund, adminCancelled);
    }

    /* ========== VRF CALLBACK ========== */

    /// @inheritdoc ICasinoGameCallback
    /// @dev `nonReentrant` defends against malicious-token transfer hooks re-entering any of
    /// this contract's mutating entries (placeBet / makeAction / adminCancelBet) mid-payout
    /// for a double-spend
    function onVrfFulfilled(uint256 requestId, uint256[] calldata randomWords) external override nonReentrant {
        if (msg.sender != address(core)) revert InvalidSender();
        uint256 betId = requestIdToBetId[requestId];
        if (betId == 0) return;
        delete requestIdToBetId[requestId];

        Bet storage b = bets[betId];
        uint256 word = randomWords[0];
        if (b.status == BetStatus.AWAITING_DEAL) {
            _onPlayerHoleDealt(betId, b, word);
        } else if (b.status == BetStatus.AWAITING_FLOP) {
            _onFlopDealt(betId, b, word);
        } else if (b.status == BetStatus.AWAITING_TURN_RIVER) {
            _onTurnRiverDealt(betId, b, word);
        } else if (b.status == BetStatus.AWAITING_RESOLVE) {
            _onResolveFulfilled(betId, b, word);
        }
        // any other state: stale callback, ignore (mapping already cleared above)
    }

    function _onPlayerHoleDealt(uint256 betId, Bet storage b, uint256 word) internal {
        uint8[] memory deck = CasinoHandsLib.initDeck(DECK_SIZE, 0);
        CasinoHandsLib.partialFisherYates(deck, HOLE_CARDS, word);
        b.playerHole[0] = deck[0];
        b.playerHole[1] = deck[1];
        b.status = BetStatus.PRE_FLOP_TURN;
        emit PlayerHoleDealt(betId, b.requestId, b.user, deck[0], deck[1]);
    }

    function _onFlopDealt(uint256 betId, Bet storage b, uint256 word) internal {
        uint64 mask = _excludeMaskHole(b);
        uint8[] memory deck = CasinoHandsLib.initDeck(DECK_SIZE - HOLE_CARDS, mask);
        CasinoHandsLib.partialFisherYates(deck, FLOP_CARDS, word);
        b.community[0] = deck[0];
        b.community[1] = deck[1];
        b.community[2] = deck[2];
        b.status = BetStatus.POST_FLOP_TURN;
        emit FlopDealt(betId, b.requestId, b.user, deck[0], deck[1], deck[2]);
    }

    function _onTurnRiverDealt(uint256 betId, Bet storage b, uint256 word) internal {
        // Exclude: 2 player hole + 3 flop cards
        uint64 mask = _excludeMaskHole(b) |
            (uint64(1) << b.community[0]) |
            (uint64(1) << b.community[1]) |
            (uint64(1) << b.community[2]);
        uint8[] memory deck = CasinoHandsLib.initDeck(DECK_SIZE - 5, mask);
        CasinoHandsLib.partialFisherYates(deck, 2, word);
        b.community[3] = deck[0];
        b.community[4] = deck[1];
        b.status = BetStatus.POST_RIVER_TURN;
        emit TurnRiverDealt(betId, b.requestId, b.user, deck[0], deck[1]);
    }

    /// @notice Final VRF — deal whatever community cards remain plus dealer hole, then resolve.
    /// Routes by `playAmount` (the raise multiplier identifies the path)
    function _onResolveFulfilled(uint256 betId, Bet storage b, uint256 word) internal {
        // Defensive: every path that sets status=AWAITING_RESOLVE first calls _pullPlayStake,
        // which sets playAmount = ante * mult. A zero playAmount here means a future regression
        // bypassed that — without this guard, playMult would be 0 and silently misroute to the
        // river-raise branch with stale community cards, producing a wrong-hand payout. Revert
        // instead; the bet stays in AWAITING_RESOLVE and is recoverable via adminCancelBet
        if (b.playAmount == 0) revert InvalidBetStatus();

        // playAmount is 3×, 2×, or 1× ante depending on which raise put us in AWAITING_RESOLVE.
        // It uniquely identifies how many cards still need dealing.
        // AUDIT NOTE: integer-division dispatch relies on `playAmount` being exactly
        // `anteAmount × {1, 2, 3}`. INVARIANT: any future code path that sets `b.playAmount`
        // MUST preserve this multiple-of-ante shape, or this branch silently misroutes (the
        // `playAmount == 0` guard above catches the zero-only regression, not wrong-multiplier).
        // Considered storing a dedicated `uint8 raisePath` on Bet; declined because current
        // invariant is enforced by single-author `_pullPlayStake` and a future break is
        // recoverable via `adminCancelBet` (bet stays in AWAITING_RESOLVE, no funds at risk)
        uint256 playMult = b.playAmount / b.anteAmount;
        uint64 mask = _excludeMaskHole(b);
        if (playMult == PRE_FLOP_RAISE_MULT) {
            // Pre-flop raise path: no community dealt → 5 community + 2 dealer = 7 cards
            _dealRemaining(b, mask, word, 7, 0, 5);
        } else if (playMult == POST_FLOP_RAISE_MULT) {
            // Post-flop raise path: flop dealt → 2 community + 2 dealer = 4 cards
            mask |= (uint64(1) << b.community[0]) | (uint64(1) << b.community[1]) | (uint64(1) << b.community[2]);
            _dealRemaining(b, mask, word, 4, 3, 2);
        } else if (playMult == RIVER_RAISE_MULT) {
            // River raise path: all community dealt → 2 dealer cards only
            for (uint8 i; i < 5; ++i) {
                mask |= uint64(1) << b.community[i];
            }
            _dealRemaining(b, mask, word, 2, 5, 0);
        } else {
            // Defensive: only PRE_FLOP / POST_FLOP / RIVER raise paths can reach AWAITING_RESOLVE.
            // Any other playMult means a future regression introduced a new raise multiplier
            // without updating this dispatch — revert rather than misroute the deal
            revert InvalidBetStatus();
        }

        // Resolve
        Resolution memory r = _computeResolution(b);
        uint256 totalPayout = r.antePayout + r.blindPayout + r.playPayout;
        uint256 stakeOut = b.anteAmount * 2 + b.playAmount;

        // Soft-cap net profit. Truncate the variance-heavy Blind side first (Royal 500x lives here)
        if (totalPayout > stakeOut) {
            uint256 profit = totalPayout - stakeOut;
            if (profit > b.profitCapRemaining) {
                uint256 cut = profit - b.profitCapRemaining;
                if (r.blindPayout >= cut) {
                    r.blindPayout -= cut;
                } else {
                    cut -= r.blindPayout;
                    r.blindPayout = 0;
                    // Spill remaining cut into ante/play (rare; would only happen if cap is tiny).
                    // Symmetric guards across all 3 legs defend against future paytable changes
                    // that could rebalance the worst-case math and otherwise underflow this branch
                    if (r.antePayout >= cut) r.antePayout -= cut;
                    else {
                        cut -= r.antePayout;
                        r.antePayout = 0;
                        if (r.playPayout >= cut) r.playPayout -= cut;
                        else {
                            // Silent-zero fallback — structurally unreachable today. Emit residual
                            // so off-chain monitoring catches the regression if it ever fires
                            emit CapSpillResidual(betId, cut - r.playPayout);
                            r.playPayout = 0;
                        }
                    }
                }
            }
            // Recompute `totalPayout` from the (now-reduced) legs so the emitted/stored breakdown
            // always matches the user-visible total. Matches `OvertimeBonusHoldem._settle` —
            // bulletproofs the `legSum == totalPayout` invariant against a future paytable change
            // that breaks the implicit `cut ≤ sum_of_legs` math (the defensive zeroing branches
            // above would otherwise silently leave legs smaller than totalPayout)
            totalPayout = r.antePayout + r.blindPayout + r.playPayout;
            uint256 paidProfit = totalPayout > stakeOut ? totalPayout - stakeOut : 0;
            b.profitCapRemaining -= paidProfit;
        }

        core.releaseReservation(b.collateral, b.reservation);
        b.reservation = 0;

        if (totalPayout > 0) {
            core.payOut(b.user, b.collateral, totalPayout, b.isFreeBet, stakeOut);
        }
        core.recordSettlement(b.collateral, stakeOut, totalPayout);

        if (totalPayout < stakeOut && !b.isFreeBet) {
            core.payReferrer(b.user, b.collateral, stakeOut - totalPayout);
        }

        b.outcome = r.outcome;
        b.antePayout = r.antePayout;
        b.blindPayout = r.blindPayout;
        b.playPayout = r.playPayout;
        b.totalPayout = totalPayout;
        b.status = BetStatus.RESOLVED;
        b.resolvedAt = block.timestamp;

        emit BetResolved(
            betId,
            b.requestId,
            b.user,
            r.outcome,
            b.dealerHole[0],
            b.dealerHole[1],
            r.antePayout,
            r.blindPayout,
            r.playPayout,
            totalPayout
        );
    }

    /// @dev Deal `nCards` from the mask-excluded deck, splitting into `communityCount` community
    /// slots starting at `startCommunityIdx`, then 2 dealer hole cards
    function _dealRemaining(
        Bet storage b,
        uint64 mask,
        uint256 word,
        uint8 nCards,
        uint8 startCommunityIdx,
        uint8 communityCount
    ) internal {
        // popcount(mask) = DECK_SIZE - deckSize
        uint8 deckSize = DECK_SIZE - CasinoHandsLib.popcount(mask);
        uint8[] memory deck = CasinoHandsLib.initDeck(deckSize, mask);
        CasinoHandsLib.partialFisherYates(deck, nCards, word);
        for (uint8 i; i < communityCount; ++i) {
            b.community[startCommunityIdx + i] = deck[i];
        }
        b.dealerHole[0] = deck[communityCount];
        b.dealerHole[1] = deck[communityCount + 1];
    }

    /* ========== RESOLUTION ========== */

    /// @notice Resolution result. Memory-only struct extracted to avoid stack-too-deep
    struct Resolution {
        Outcome outcome;
        uint256 antePayout; // total returned (stake + win) for Ante leg
        uint256 blindPayout; // total returned for Blind leg
        uint256 playPayout; // total returned for Play leg
    }

    function _computeResolution(Bet storage b) internal view returns (Resolution memory r) {
        uint8[7] memory pSeven = [
            b.playerHole[0],
            b.playerHole[1],
            b.community[0],
            b.community[1],
            b.community[2],
            b.community[3],
            b.community[4]
        ];
        uint8[7] memory dSeven = [
            b.dealerHole[0],
            b.dealerHole[1],
            b.community[0],
            b.community[1],
            b.community[2],
            b.community[3],
            b.community[4]
        ];

        uint256 pVal = CasinoHandsLib.evaluateCards7(CasinoHandsLib.toMemArray7(pSeven));
        uint256 dVal = CasinoHandsLib.evaluateCards7(CasinoHandsLib.toMemArray7(dSeven));

        bool dealerQualifies = _dealerQualifies(dVal);

        // Vegas / Shuffle Master standard: dealer-qualification only protects the Ante. Play and
        // Blind always resolve on player-vs-dealer hand comparison. When dealer doesn't qualify,
        // Ante pushes regardless of who has the better hand
        if (!dealerQualifies) {
            r.outcome = Outcome.DEALER_NOT_QUALIFIED;
            r.antePayout = b.anteAmount; // push (the qualifies rule's player benefit)
            if (pVal > dVal) {
                r.playPayout = _playWinPayout(b);
                r.blindPayout = _blindWinPayout(b, pVal);
            } else if (pVal == dVal) {
                r.playPayout = b.playAmount; // push
                r.blindPayout = b.anteAmount; // push
            }
            // pVal < dVal: play and blind both lose (paid 0)
            return r;
        }

        if (pVal > dVal) {
            r.outcome = Outcome.PLAYER_WIN;
            r.antePayout = b.anteAmount * 2; // 1:1 + stake back
            r.playPayout = _playWinPayout(b);
            r.blindPayout = _blindWinPayout(b, pVal);
        } else if (pVal < dVal) {
            r.outcome = Outcome.DEALER_WIN;
            // All three legs lose (paid 0)
        } else {
            r.outcome = Outcome.TIE;
            r.antePayout = b.anteAmount; // push
            r.playPayout = b.playAmount; // push
            r.blindPayout = b.anteAmount; // push (Blind = ante amount)
        }
    }

    /// @notice Play leg pays 1:1 (stake + win) when player wins or dealer doesn't qualify
    function _playWinPayout(Bet storage b) internal view returns (uint256) {
        if (b.playAmount == 0) return 0;
        return b.playAmount * 2;
    }

    /// @notice Blind leg pays per paytable when player wins. Premium hands get a bonus on top of
    /// the stake; non-premium hands push (return stake only)
    function _blindWinPayout(Bet storage b, uint256 handValue) internal view returns (uint256) {
        uint256 mult = _blindPaytableMultiplier(handValue);
        if (mult == 0) {
            // Non-premium hand → push (return stake only, no bonus)
            return b.anteAmount;
        }
        // Stake + (mult × stake) — Blind size == ante size
        return b.anteAmount * (1 + mult);
    }

    function _blindPaytableMultiplier(uint256 handValue) internal pure returns (uint256) {
        uint8 class_ = uint8(handValue >> 20);
        if (class_ == CasinoHandsLib.CLASS_ROYAL_FLUSH) return BLIND_MULT_ROYAL;
        if (class_ == CasinoHandsLib.CLASS_STRAIGHT_FLUSH) return BLIND_MULT_STRAIGHT_FLUSH;
        if (class_ == CasinoHandsLib.CLASS_FOUR_OF_A_KIND) return BLIND_MULT_FOUR_OF_A_KIND;
        if (class_ == CasinoHandsLib.CLASS_FULL_HOUSE) return BLIND_MULT_FULL_HOUSE;
        if (class_ == CasinoHandsLib.CLASS_FLUSH) return BLIND_MULT_FLUSH;
        if (class_ == CasinoHandsLib.CLASS_STRAIGHT) return BLIND_MULT_STRAIGHT;
        return 0; // below Straight → push
    }

    function _dealerQualifies(uint256 handValue) internal pure returns (bool) {
        // UTH dealer needs Pair or better
        uint8 class_ = uint8(handValue >> 20);
        return class_ >= CasinoHandsLib.CLASS_PAIR;
    }

    /* ========== INTERNAL: STAKES + VRF ========== */

    /// @dev Free-bet raises pull additional stake from FBH (not the user's wallet). If the
    /// user's FBH balance is exhausted, every raise tx reverts and the user can only
    /// check/fold from that point (or wait out `cancelTimeout`). FE must gate raise buttons
    /// on remaining FBH balance for free-bet hands — there is no wallet-funded raise path
    function _pullPlayStake(Bet storage b, uint256 mult) internal {
        uint256 playStake = b.anteAmount * mult;
        // += rather than = to defend against a future state-machine change that lets a bet
        // re-enter a *_TURN state after raising — otherwise the first pull would be silently
        // dropped and stuck. Semantically identical today (single raise per bet)
        b.playAmount += playStake;
        if (b.isFreeBet) {
            core.useFreeBet(b.user, b.collateral, playStake);
        } else {
            core.pullFromUser(b.user, b.collateral, playStake);
        }
        // Extend reservation by the raise (covers the larger stake-back potential at resolve).
        // Profit-side cap was reserved at placeBet and is unchanged
        core.reserveOrRevert(b.collateral, playStake);
        b.reservation += playStake;
    }

    function _checkBetSize(address collateral, uint256 anteAmount) internal view {
        uint256 anteUsd = core.getUsdValue(collateral, anteAmount);
        uint256 minBet = core.effectiveMinBetUsd(address(this));
        if (minBet == 0) minBet = MIN_BET_USD;
        if (anteUsd < minBet) revert InvalidAmount();
        uint256 maxBet = core.effectiveMaxBetUsd(address(this));
        if (maxBet != 0 && anteUsd > maxBet) revert AboveMaxBet();
    }

    /// @notice Worst-case net profit for this bet truncated by the per-game USD profit cap,
    /// returned in collateral units. Uncapped worst = (MAX_PAYOUT_ANTE_MULT - WORST_CASE_STAKE_ANTE_MULT) × ante = 504×.
    /// Resolve truncates final payout to stakeOut + `b.profitCapRemaining`
    function _cappedProfit(address collateral, uint256 anteAmount) internal view returns (uint256) {
        uint256 worst = anteAmount * (MAX_PAYOUT_ANTE_MULT - WORST_CASE_STAKE_ANTE_MULT);
        uint256 capCollateral = core.collateralFromUsd(collateral, core.effectiveMaxProfitUsd(address(this)));
        return worst > capCollateral ? capCollateral : worst;
    }

    function _requestVrf(uint256 betId, Bet storage b, BetStatus newStatus) internal returns (uint256 requestId) {
        requestId = core.requestRandomWords(1);
        b.requestId = requestId;
        b.lastRequestAt = block.timestamp;
        b.status = newStatus;
        requestIdToBetId[requestId] = betId;
    }

    /* ========== INTERNAL HELPERS ========== */

    /// @notice Deck construction, Fisher-Yates shuffle, 7-card hand evaluator, top-N rank
    /// helpers, popcount, and value packing all live in `CasinoHandsLib` (internal pure,
    /// inlined at compile time — no DELEGATECALL, no separate deployment, no storage)

    function _excludeMaskHole(Bet storage b) internal view returns (uint64) {
        return (uint64(1) << b.playerHole[0]) | (uint64(1) << b.playerHole[1]);
    }

    function _requireOwnedAt(Bet storage b, BetStatus expected) internal view {
        if (b.status == BetStatus.NONE) revert BetNotFound();
        if (b.user != msg.sender) revert BetNotOwner();
        if (b.status != expected) revert InvalidBetStatus();
    }

    /* ========== VIEWS ========== */

    function getBetBase(
        uint256 betId
    )
        external
        view
        override
        returns (
            address user,
            address collateral,
            uint256 anteAmount,
            uint256 playAmount,
            uint256 totalPayout,
            uint256 placedAt,
            uint256 resolvedAt,
            BetStatus status,
            Outcome outcome
        )
    {
        Bet storage b = bets[betId];
        return (
            b.user,
            b.collateral,
            b.anteAmount,
            b.playAmount,
            b.totalPayout,
            b.placedAt,
            b.resolvedAt,
            b.status,
            b.outcome
        );
    }

    function getBetCards(
        uint256 betId
    ) external view override returns (uint8[2] memory playerHole, uint8[5] memory community, uint8[2] memory dealerHole) {
        Bet storage b = bets[betId];
        return (b.playerHole, b.community, b.dealerHole);
    }

    function getBetPayouts(
        uint256 betId
    ) external view override returns (uint256 antePayout, uint256 blindPayout, uint256 playPayout, uint256 totalPayout) {
        Bet storage b = bets[betId];
        return (b.antePayout, b.blindPayout, b.playPayout, b.totalPayout);
    }

    function getFullRecord(uint256 betId) external view override returns (FullRecord memory r) {
        Bet storage b = bets[betId];
        r.betId = betId;
        r.user = b.user;
        r.collateral = b.collateral;
        r.anteAmount = b.anteAmount;
        r.playAmount = b.playAmount;
        r.totalPayout = b.totalPayout;
        r.antePayout = b.antePayout;
        r.blindPayout = b.blindPayout;
        r.playPayout = b.playPayout;
        r.placedAt = b.placedAt;
        r.resolvedAt = b.resolvedAt;
        r.status = b.status;
        r.outcome = b.outcome;
        r.playerHole = b.playerHole;
        r.community = b.community;
        r.dealerHole = b.dealerHole;
        r.isFreeBet = b.isFreeBet;
        r.lastRequestAt = b.lastRequestAt;
    }

    function getUserBetIds(address user, uint256 offset, uint256 limit) external view override returns (uint256[] memory) {
        return CasinoHandsLib.getUserBetIds(userBetIds[user], offset, limit);
    }

    function getRecentBetIds(uint256 offset, uint256 limit) external view override returns (uint256[] memory) {
        return CasinoHandsLib.getRecentBetIds(nextBetId, offset, limit);
    }

    /* ========== ADMIN ========== */

    /// @dev AUDIT NOTE: unguarded against repointing to a malicious core. Trusted-owner model;
    /// see HiLo.setCore for rationale
    function setCore(address _core) external onlyOwner {
        if (_core == address(0)) revert InvalidAddress();
        core = ICasinoCoreV2(_core);
    }

    function setManager(address _manager) external onlyOwner {
        if (_manager == address(0)) revert InvalidAddress();
        manager = ISportsAMMV2Manager(_manager);
    }

    function setPausedByRole(bool _paused) external onlyPauser {
        if (paused != _paused) {
            paused = _paused;
            if (_paused) lastPauseTime = block.timestamp;
            emit PauseChanged(_paused);
        }
    }

    /* ========== MODIFIERS ========== */

    function _requireRole(ISportsAMMV2Manager.Role role) internal view {
        if (msg.sender != owner && !manager.isWhitelistedAddress(msg.sender, role)) revert InvalidSender();
    }

    modifier onlyResolver() {
        _requireRole(ISportsAMMV2Manager.Role.MARKET_RESOLVING);
        _;
    }
    modifier onlyPauser() {
        _requireRole(ISportsAMMV2Manager.Role.TICKET_PAUSER);
        _;
    }
}

contracts/core/Casino/Plinko.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";

import "../../utils/proxy/ProxyReentrancyGuard.sol";
import "../../utils/proxy/ProxyOwned.sol";
import "../../utils/proxy/ProxyPausable.sol";

import "../../interfaces/ISportsAMMV2Manager.sol";
import "../../interfaces/ICasinoCoreV2.sol";
import "../../interfaces/ICasinoGameCallback.sol";
import "../../interfaces/ICasinoPlinko.sol";
import "./CasinoHandsLib.sol";

/// @title Plinko
/// @author Overtime
/// @notice Single-shot 8-row Plinko. User picks a risk level (LOW/MED/HIGH); one VRF word is
/// consumed; the contract derives the bounce sequence from the word's low 8 bits, where each
/// bit chooses left (0) or right (1). The slot index = popcount(low 8 bits) addresses the
/// risk-specific paytable. Multipliers stored in 1e18 precision
/// @dev All funds, randomness, free-bets, and circuit-breaker accounting live in `CasinoCoreV2`.
///
/// Default paytables are calibrated for ≥2% theoretical house edge (see project memory
/// `casino_edge_floor`). Realized HE is verified by the 100k Monte Carlo sim
contract Plinko is ICasinoPlinko, ICasinoGameCallback, Initializable, ProxyOwned, ProxyPausable, ProxyReentrancyGuard {
    /* ========== CONSTANTS ========== */

    uint256 private constant ONE = 1e18;
    uint256 public constant MIN_BET_USD = 3e18;

    uint8 private constant ROWS = 8;
    uint8 private constant SLOTS = 9; // ROWS + 1

    /// @dev Binomial slot weights for an 8-row Pascal's triangle: C(8, 0..8) = [1, 8, 28, 56, 70,
    /// 56, 28, 8, 1] summing to 2^8 = 256. Used to validate that any paytable's weighted RTP
    /// clears the project-wide 2% house edge floor (≤ 0.98 in 1e18). Weights are inlined per
    /// call site (no constant array support pre-0.8.27) so updates here MUST be mirrored there
    uint256 private constant SLOT_WEIGHTS_DEN = 256;
    uint256 private constant MAX_RTP_E18 = 98e16;

    /* ========== ERRORS ========== */

    error InvalidAddress();
    error InvalidSender();
    error InvalidAmount();
    error InvalidCollateral();
    error InvalidRisk();
    error AboveMaxBet();
    error PaytableLengthMismatch();
    error MaxProfitExceeded();
    error BetNotFound();
    error BetNotOwner();
    error InvalidBetStatus();
    error EdgeFloorBreached();

    /* ========== STRUCTS ========== */

    struct Bet {
        address user;
        address collateral;
        uint256 amount;
        uint256 payout;
        uint256 placedAt;
        uint256 lastRequestAt;
        uint256 resolvedAt;
        uint256 reserved;
        uint256 requestId;
        uint256 multiplierE18;
        BetStatus status;
        Risk risk;
        uint8 slotIndex;
        // Stake was pulled from FreeBetsHolder via core.useFreeBet instead of core.pullFromUser.
        // Routes payouts back to FBH on resolve / cancel and skips referrer payment on losses
        bool isFreeBet;
    }

    /* ========== STATE ========== */

    ICasinoCoreV2 public core;
    ISportsAMMV2Manager public manager;

    uint256 public nextBetId;

    mapping(uint256 => Bet) internal bets;
    mapping(uint256 => uint256) public requestIdToBetId;
    mapping(address => uint256[]) private userBetIds;

    /// @notice paytables[risk] = [mult0, ..., mult8] (length 9)
    mapping(uint8 => uint256[]) internal paytables;

    /// @notice Max multiplier per risk, cached for fast reservation calc
    mapping(uint8 => uint256) internal maxMultiplier;

    /* ========== INITIALIZER ========== */

    function initialize(address _owner, address _core, address _manager) external initializer {
        if (_owner == address(0) || _core == address(0) || _manager == address(0)) revert InvalidAddress();
        setOwner(_owner);
        initNonReentrant();
        core = ICasinoCoreV2(_core);
        manager = ISportsAMMV2Manager(_manager);
        nextBetId = 1;

        _setDefaultPaytables();
    }

    /// @dev Default 8-row paytables calibrated to ≥2% theoretical house edge.
    /// 8-row outcome weights: [1,8,28,56,70,56,28,8,1] (sum = 256)
    function _setDefaultPaytables() internal {
        _setPaytableInternal(uint8(Risk.LOW), [uint256(56e17), 205e16, 105e16, 1e18, 5e17, 1e18, 105e16, 205e16, 56e17]);
        _setPaytableInternal(uint8(Risk.MED), [uint256(13e18), 3e18, 12e17, 7e17, 4e17, 7e17, 12e17, 3e18, 13e18]);
        _setPaytableInternal(uint8(Risk.HIGH), [uint256(29e18), 4e18, 14e17, 3e17, 2e17, 3e17, 14e17, 4e18, 29e18]);
    }

    /// @dev Weighted RTP over binomial slot weights C(8, i); reverts if > 0.98 (2% edge floor)
    function _checkRtp(uint256[SLOTS] memory mults) internal pure {
        uint256 rtp = (mults[0] +
            8 *
            mults[1] +
            28 *
            mults[2] +
            56 *
            mults[3] +
            70 *
            mults[4] +
            56 *
            mults[5] +
            28 *
            mults[6] +
            8 *
            mults[7] +
            mults[8]) / SLOT_WEIGHTS_DEN;
        if (rtp > MAX_RTP_E18) revert EdgeFloorBreached();
    }

    function _setPaytableInternal(uint8 risk, uint256[SLOTS] memory mults) internal {
        _checkRtp(mults);

        uint256[] storage row = paytables[risk];
        uint256 maxM;
        for (uint256 i; i < SLOTS; ++i) {
            row.push(mults[i]);
            if (mults[i] > maxM) maxM = mults[i];
        }
        maxMultiplier[risk] = maxM;
    }

    /* ========== PLACE / CANCEL ========== */

    /// @notice Places a Plinko bet. `isFreeBet=true` pulls the stake from FreeBetsHolder, `false`
    /// from the user's wallet. One VRF word resolves it — no mid-game actions, no user-callable
    /// cancel; stuck bets are recovered via `adminCancelBet` (resolver-only)
    function placeBet(
        address collateral,
        uint256 amount,
        Risk risk,
        address referrer,
        bool isFreeBet
    ) external override nonReentrant notPaused returns (uint256 betId, uint256 requestId) {
        return _placeBet(collateral, amount, risk, referrer, isFreeBet);
    }

    function _placeBet(
        address collateral,
        uint256 amount,
        Risk risk,
        address referrer,
        bool isFreeBet
    ) internal returns (uint256 betId, uint256 requestId) {
        uint256 reservation = _validateAndReserve(collateral, amount, risk);
        if (isFreeBet) {
            core.useFreeBet(msg.sender, collateral, amount);
        } else {
            core.pullFromUser(msg.sender, collateral, amount);
        }
        if (referrer != address(0)) core.setReferrer(referrer, msg.sender);
        core.reserveOrRevert(collateral, reservation);
        requestId = core.requestRandomWords(1);
        betId = nextBetId++;
        _writeBet(betId, requestId, collateral, amount, risk, reservation, isFreeBet);
        emit BetPlaced(betId, requestId, msg.sender, collateral, amount, risk);
    }

    function _validateAndReserve(address collateral, uint256 amount, Risk risk) internal view returns (uint256 reservation) {
        if (amount == 0) revert InvalidAmount();
        if (!core.supportedCollateral(collateral)) revert InvalidCollateral();
        uint256 maxM = maxMultiplier[uint8(risk)];
        if (maxM == 0) revert InvalidRisk();
        _checkBetSize(collateral, amount);
        uint256 amountUsd = core.getUsdValue(collateral, amount);
        if ((amountUsd * (maxM - ONE)) / ONE > core.effectiveMaxProfitUsd(address(this))) revert MaxProfitExceeded();
        reservation = (amount * maxM) / ONE;
    }

    /// @notice Per-game bet-size gate. `core.effectiveMinBetUsd` / `effectiveMaxBetUsd` overrides
    /// (set via `CasinoCoreV2.setMinBetPerGameUsd` / `setMaxBetPerGameUsd`) take precedence; when
    /// unset (zero), `MIN_BET_USD` is the default floor and there is no explicit max ceiling —
    /// the bet is still capped indirectly by `effectiveMaxProfitUsd` via the `MaxProfitExceeded`
    /// check below
    function _checkBetSize(address collateral, uint256 amount) internal view {
        uint256 amountUsd = core.getUsdValue(collateral, amount);
        uint256 minBet = core.effectiveMinBetUsd(address(this));
        if (minBet == 0) minBet = MIN_BET_USD;
        if (amountUsd < minBet) revert InvalidAmount();
        uint256 maxBet = core.effectiveMaxBetUsd(address(this));
        if (maxBet != 0 && amountUsd > maxBet) revert AboveMaxBet();
    }

    function _writeBet(
        uint256 betId,
        uint256 requestId,
        address collateral,
        uint256 amount,
        Risk risk,
        uint256 reservation,
        bool isFreeBet
    ) internal {
        Bet storage b = bets[betId];
        b.user = msg.sender;
        b.collateral = collateral;
        b.amount = amount;
        b.placedAt = block.timestamp;
        b.lastRequestAt = block.timestamp;
        b.requestId = requestId;
        b.reserved = reservation;
        b.risk = risk;
        b.status = BetStatus.PENDING;
        b.isFreeBet = isFreeBet;
        requestIdToBetId[requestId] = betId;
        userBetIds[msg.sender].push(betId);
    }

    function adminCancelBet(uint256 betId) external override nonReentrant onlyResolver {
        Bet storage b = bets[betId];
        if (b.status == BetStatus.NONE) revert BetNotFound();
        if (b.status != BetStatus.PENDING) revert InvalidBetStatus();
        _cancelBet(betId, true);
    }

    function _cancelBet(uint256 betId, bool adminCancelled) internal {
        Bet storage b = bets[betId];
        if (b.requestId != 0) delete requestIdToBetId[b.requestId];
        core.releaseReservation(b.collateral, b.reserved);
        b.reserved = 0;
        core.payOut(b.user, b.collateral, b.amount, b.isFreeBet, b.amount);
        // Decrement core's pending-stake counter (stake == refund → zero P&L impact)
        core.recordSettlement(b.collateral, b.amount, b.amount);
        b.payout = b.amount;
        b.status = BetStatus.CANCELLED;
        b.resolvedAt = block.timestamp;
        emit BetCancelled(betId, b.user, b.amount, adminCancelled);
    }

    /* ========== VRF CALLBACK ========== */

    /// @dev `nonReentrant` defends against malicious-token transfer hooks re-entering any of
    /// this contract's mutating entries (placeBet / adminCancelBet) mid-payout for a double-spend
    function onVrfFulfilled(uint256 requestId, uint256[] calldata randomWords) external override nonReentrant {
        if (msg.sender != address(core)) revert InvalidSender();
        uint256 betId = requestIdToBetId[requestId];
        if (betId == 0) return;
        delete requestIdToBetId[requestId];

        Bet storage b = bets[betId];
        if (b.status != BetStatus.PENDING) return;

        uint8 slot = _slotFromWord(randomWords[0]);
        uint256 mult = paytables[uint8(b.risk)][slot];
        uint256 payout = (b.amount * mult) / ONE;

        // CEI: write all bet state before any external call so a hostile re-entry (defense
        // beyond `nonReentrant`) would see status=RESOLVED and be blocked by the early-return
        uint256 reserved = b.reserved;
        b.reserved = 0;
        b.slotIndex = slot;
        b.multiplierE18 = mult;
        b.payout = payout;
        b.status = BetStatus.RESOLVED;
        b.resolvedAt = block.timestamp;

        core.releaseReservation(b.collateral, reserved);

        if (payout > 0) {
            core.payOut(b.user, b.collateral, payout, b.isFreeBet, b.amount);
        }
        core.recordSettlement(b.collateral, b.amount, payout);

        // Skip referrer payment on free bets — user lost no real funds, so no referral fee
        if (payout < b.amount && !b.isFreeBet) {
            core.payReferrer(b.user, b.collateral, b.amount - payout);
        }

        emit BetResolved(betId, b.requestId, b.user, slot, mult, payout);
    }

    /// @notice Derives the slot index from the VRF word: take low 8 bits, count 1-bits.
    /// Result is in [0, 8] (9 possible slots). Popcount implementation in `CasinoHandsLib`
    /// (Brian Kernighan, inlined at compile time)
    function _slotFromWord(uint256 word) internal pure returns (uint8 slot) {
        slot = CasinoHandsLib.popcount(word & 0xff);
    }

    /* ========== ADMIN: PAYTABLE MANAGEMENT ========== */

    /// @notice Owner can replace a risk-level paytable. `multipliers` length must equal 9.
    /// @dev Enforces the project-wide 2% edge floor: weighted RTP across binomial slot weights
    /// must stay ≤ 0.98 (in 1e18). Prevents a fat-finger paytable update from silently breaking
    /// the edge invariant — owner is trusted but defense-in-depth is cheap here
    function setPaytable(Risk risk, uint256[] calldata multipliers) external onlyOwner {
        if (multipliers.length != SLOTS) revert PaytableLengthMismatch();

        uint256[SLOTS] memory mults;
        for (uint256 i; i < SLOTS; ++i) mults[i] = multipliers[i];
        _checkRtp(mults);

        uint8 r = uint8(risk);
        delete paytables[r];
        uint256 maxM;
        for (uint256 i; i < SLOTS; ++i) {
            paytables[r].push(mults[i]);
            if (mults[i] > maxM) maxM = mults[i];
        }
        maxMultiplier[r] = maxM;
        emit PaytableUpdated(risk, multipliers);
    }

    /* ========== VIEWS ========== */

    function getBetBase(
        uint256 betId
    )
        external
        view
        override
        returns (
            address user,
            address collateral,
            uint256 amount,
            uint256 payout,
            uint256 placedAt,
            uint256 resolvedAt,
            BetStatus status,
            Risk risk,
            uint8 slotIndex,
            uint256 multiplierE18
        )
    {
        Bet storage b = bets[betId];
        return (
            b.user,
            b.collateral,
            b.amount,
            b.payout,
            b.placedAt,
            b.resolvedAt,
            b.status,
            b.risk,
            b.slotIndex,
            b.multiplierE18
        );
    }

    function getFullRecord(uint256 betId) external view override returns (FullRecord memory r) {
        Bet storage b = bets[betId];
        r.betId = betId;
        r.user = b.user;
        r.collateral = b.collateral;
        r.amount = b.amount;
        r.payout = b.payout;
        r.placedAt = b.placedAt;
        r.resolvedAt = b.resolvedAt;
        r.status = b.status;
        r.risk = b.risk;
        r.slotIndex = b.slotIndex;
        r.multiplierE18 = b.multiplierE18;
        r.isFreeBet = b.isFreeBet;
        r.lastRequestAt = b.lastRequestAt;
    }

    function getPaytable(Risk risk) external view override returns (uint256[] memory) {
        return paytables[uint8(risk)];
    }

    function getMaxMultiplierE18(Risk risk) external view override returns (uint256) {
        return maxMultiplier[uint8(risk)];
    }

    function getUserBetIds(address user, uint256 offset, uint256 limit) external view override returns (uint256[] memory) {
        return CasinoHandsLib.getUserBetIds(userBetIds[user], offset, limit);
    }

    function getRecentBetIds(uint256 offset, uint256 limit) external view override returns (uint256[] memory) {
        return CasinoHandsLib.getRecentBetIds(nextBetId, offset, limit);
    }

    /* ========== ADMIN: WIRING + PAUSE ========== */

    /// @dev AUDIT NOTE: unguarded against repointing to a malicious core. Trusted-owner model;
    /// see HiLo.setCore for rationale
    function setCore(address _core) external onlyOwner {
        if (_core == address(0)) revert InvalidAddress();
        core = ICasinoCoreV2(_core);
    }

    function setManager(address _manager) external onlyOwner {
        if (_manager == address(0)) revert InvalidAddress();
        manager = ISportsAMMV2Manager(_manager);
    }

    function setPausedByRole(bool _paused) external onlyPauser {
        if (paused != _paused) {
            paused = _paused;
            if (_paused) lastPauseTime = block.timestamp;
            emit PauseChanged(_paused);
        }
    }

    /* ========== MODIFIERS ========== */

    function _requireRole(ISportsAMMV2Manager.Role role) internal view {
        if (msg.sender != owner && !manager.isWhitelistedAddress(msg.sender, role)) revert InvalidSender();
    }

    modifier onlyResolver() {
        _requireRole(ISportsAMMV2Manager.Role.MARKET_RESOLVING);
        _;
    }
    modifier onlyPauser() {
        _requireRole(ISportsAMMV2Manager.Role.TICKET_PAUSER);
        _;
    }
}

contracts/core/Casino/Roulette.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";

import "chainlink-vrf/src/v0.8/vrf/dev/interfaces/IVRFCoordinatorV2Plus.sol";
import "chainlink-vrf/src/v0.8/vrf/dev/libraries/VRFV2PlusClient.sol";

// internal
import "../../utils/proxy/ProxyReentrancyGuard.sol";
import "../../utils/proxy/ProxyOwned.sol";
import "../../utils/proxy/ProxyPausable.sol";
import "@thales-dao/contracts/contracts/interfaces/IPriceFeed.sol";

import "../../interfaces/ISportsAMMV2Manager.sol";
import "../../interfaces/IFreeBetsHolder.sol";
import "@thales-dao/contracts/contracts/interfaces/IReferrals.sol";

/// @title Roulette
/// @author Overtime
/// @notice European roulette contract using Chainlink VRF for single-player spins
/// @dev Supports USDC, WETH and OVER collateral, with bankroll reservation per collateral
contract Roulette is Initializable, ProxyOwned, ProxyPausable, ProxyReentrancyGuard {
    using SafeERC20 for IERC20;

    /* ========== CONSTANTS ========== */

    uint private constant ONE = 1e18;
    uint private constant USDC_UNIT = 1e6;
    uint private constant WHEEL_SIZE = 37; // 0..36 single-zero (European)

    /// @notice Minimum allowed bet value expressed in USD, normalized to 18 decimals
    uint public constant MIN_BET_USD = 3e18;

    /// @notice Minimum allowed cancel timeout in seconds
    uint public constant MIN_CANCEL_TIMEOUT = 30;

    /// @notice Maximum number of picks (sub-selections) that can be combined in a single bet
    uint public constant MAX_PICKS_PER_BET = 10;

    /* ========== ERRORS ========== */

    error InvalidAddress();
    error InvalidSender();
    error InvalidCollateral();
    error InvalidPrice();
    error InvalidAmount();
    error InvalidBetType();
    error InvalidSelection();
    error BetNotFound();
    error BetNotPending();
    error BetNotOwner();
    error CancelTimeoutNotReached();
    error MaxProfitExceeded();
    error InsufficientAvailableLiquidity();
    error InvalidPickCount();

    /* ========== ENUMS ========== */

    /// @notice Supported roulette bet types for MVP
    enum BetType {
        STRAIGHT,
        RED_BLACK,
        ODD_EVEN,
        LOW_HIGH,
        DOZEN,
        COLUMN
    }

    /// @notice Lifecycle status of a roulette bet
    enum BetStatus {
        NONE,
        PENDING,
        RESOLVED,
        CANCELLED
    }

    /* ========== STRUCTS ========== */

    /// @notice Stored data for an individual roulette bet
    /// @param user Address of the bettor
    /// @param collateral Collateral token used for the bet
    /// @param amount Amount staked
    /// @param payout Final payout amount, 0 if lost, original amount if cancelled
    /// @param requestId Chainlink VRF request id
    /// @param placedAt Timestamp when the bet was placed
    /// @param resolvedAt Timestamp when the bet was resolved or cancelled
    /// @param reservedProfit Reserved house-side profit liability for this bet
    /// @param betType Type of roulette bet
    /// @param status Current status of the bet
    /// @param selection Encoded selection for the chosen bet type
    /// @param result Winning roulette result in range 0..36 (European single-zero)
    /// @param won Whether the bet won
    struct Bet {
        address user;
        address collateral;
        uint amount;
        uint payout;
        uint requestId;
        uint placedAt;
        uint resolvedAt;
        uint reservedProfit;
        BetType betType;
        BetStatus status;
        uint8 selection;
        uint8 result;
        bool won;
    }

    /// @notice User-provided input for one pick inside a bet
    /// @param betType Roulette bet type for this pick
    /// @param selection Encoded selection value for this pick
    /// @param amount Collateral amount staked on this pick
    struct PickInput {
        BetType betType;
        uint8 selection;
        uint amount;
    }

    /// @notice Stored per-pick data for a multi-pick bet (length == 0 for a single-pick bet — the
    /// pick's data lives on the parent Bet struct itself)
    struct Pick {
        BetType betType;
        uint8 selection;
        bool won;
        uint amount;
        uint reservedProfit;
        uint payout;
    }

    struct CoreAddresses {
        address owner;
        address manager;
        address priceFeed;
        address vrfCoordinator;
    }

    struct CollateralConfig {
        address usdc;
        address weth;
        address over;
        bytes32 wethPriceFeedKey;
        bytes32 overPriceFeedKey;
    }

    struct VrfConfig {
        uint256 subscriptionId;
        bytes32 keyHash;
        uint32 callbackGasLimit;
        uint16 requestConfirmations;
        bool nativePayment;
    }

    /* ========== STATE VARIABLES ========== */

    /// @notice Manager contract used for whitelist-based role checks
    ISportsAMMV2Manager public manager;

    /// @notice Price feed used for collateral normalization to USD
    IPriceFeed public priceFeed;

    /// @notice Chainlink VRF coordinator
    IVRFCoordinatorV2Plus public vrfCoordinator;

    /// @notice Supported collateral addresses
    address public usdc;
    address public weth;
    address public over;

    /// @notice Maximum allowed profit per bet in USD, normalized to 18 decimals
    uint public maxProfitUsd;

    /// @notice Timeout after which a pending bet can be cancelled
    uint public cancelTimeout;

    /// @notice Next bet id to assign
    uint public nextBetId;

    /// @notice Chainlink VRF v2.5 subscription id
    uint256 public subscriptionId;

    /// @notice Chainlink VRF key hash / gas lane
    bytes32 public keyHash;

    /// @notice Gas limit for VRF callback execution
    uint32 public callbackGasLimit;

    /// @notice Number of confirmations for VRF request
    uint16 public requestConfirmations;

    /// @notice Whether VRF request is paid in native token
    bool public nativePayment;

    /// @notice Whether a collateral is supported
    mapping(address => bool) public supportedCollateral;

    /// @notice Price feed key per collateral for non-USDC assets
    mapping(address => bytes32) public priceFeedKeyPerCollateral;

    /// @notice Stored bets by bet id
    mapping(uint => Bet) internal bets;

    /// @notice Maps VRF request id to bet id
    mapping(uint => uint) public requestIdToBetId;

    /// @notice Tracks reserved house-side profit liability for all pending bets per collateral
    mapping(address => uint) public reservedProfitPerCollateral;

    /// @notice Bet IDs per user for history queries
    mapping(address => uint[]) private userBetIds;

    /// @notice Free bets holder contract address
    address public freeBetsHolder;

    /// @notice Whether a bet was placed with a free bet
    mapping(uint => bool) public isFreeBet;

    /// @notice Referrals contract
    IReferrals public referrals;

    // ---- Multi-pick storage (appended; must preserve proxy layout above) ----

    /// @notice Per-pick data for multi-pick bets. Empty for single-pick bets (the pick lives on Bet itself)
    mapping(uint => Pick[]) internal picks;

    /* ========== PUBLIC / EXTERNAL METHODS ========== */

    /// @notice Initializes the roulette contract
    /// @param core Core protocol addresses
    /// @param collateralConfig Collateral addresses and price feed keys
    /// @param _maxProfitUsd Maximum allowed profit per bet in USD, normalized to 18 decimals
    /// @param _cancelTimeout Timeout after which a pending bet can be cancelled
    /// @param vrfConfig Chainlink VRF configuration
    function initialize(
        CoreAddresses calldata core,
        CollateralConfig calldata collateralConfig,
        uint _maxProfitUsd,
        uint _cancelTimeout,
        VrfConfig calldata vrfConfig
    ) external initializer {
        if (
            core.owner == address(0) ||
            core.manager == address(0) ||
            core.priceFeed == address(0) ||
            core.vrfCoordinator == address(0) ||
            collateralConfig.usdc == address(0) ||
            collateralConfig.weth == address(0) ||
            collateralConfig.over == address(0)
        ) {
            revert InvalidAddress();
        }

        if (_maxProfitUsd == 0) revert InvalidAmount();
        if (vrfConfig.callbackGasLimit == 0) revert InvalidAmount();

        setOwner(core.owner);
        initNonReentrant();

        manager = ISportsAMMV2Manager(core.manager);
        priceFeed = IPriceFeed(core.priceFeed);
        vrfCoordinator = IVRFCoordinatorV2Plus(core.vrfCoordinator);

        usdc = collateralConfig.usdc;
        weth = collateralConfig.weth;
        over = collateralConfig.over;

        supportedCollateral[collateralConfig.usdc] = true;
        supportedCollateral[collateralConfig.weth] = true;
        supportedCollateral[collateralConfig.over] = true;

        priceFeedKeyPerCollateral[collateralConfig.weth] = collateralConfig.wethPriceFeedKey;
        priceFeedKeyPerCollateral[collateralConfig.over] = collateralConfig.overPriceFeedKey;

        if (_cancelTimeout < MIN_CANCEL_TIMEOUT) revert InvalidAmount();
        maxProfitUsd = _maxProfitUsd;
        cancelTimeout = _cancelTimeout;

        subscriptionId = vrfConfig.subscriptionId;
        keyHash = vrfConfig.keyHash;
        callbackGasLimit = vrfConfig.callbackGasLimit;
        requestConfirmations = vrfConfig.requestConfirmations;
        nativePayment = vrfConfig.nativePayment;

        nextBetId = 1;
    }

    /// @notice Places a single-pick roulette bet and requests randomness from Chainlink VRF
    function placeBet(
        address collateral,
        uint amount,
        BetType betType,
        uint8 selection,
        address _referrer
    ) external nonReentrant notPaused returns (uint betId, uint requestId) {
        if (!supportedCollateral[collateral]) revert InvalidCollateral();
        IERC20(collateral).safeTransferFrom(msg.sender, address(this), amount);
        _setReferrer(_referrer, msg.sender);
        return _placeSingle(msg.sender, collateral, amount, betType, selection, false);
    }

    /// @notice Places a single-pick roulette bet using free bet balance
    function placeBetWithFreeBet(
        address collateral,
        uint amount,
        BetType betType,
        uint8 selection
    ) external nonReentrant notPaused returns (uint betId, uint requestId) {
        if (!supportedCollateral[collateral]) revert InvalidCollateral();
        IFreeBetsHolder(freeBetsHolder).useFreeBet(msg.sender, collateral, amount);
        return _placeSingle(msg.sender, collateral, amount, betType, selection, true);
    }

    /// @notice Places a multi-pick bet with up to MAX_PICKS_PER_BET picks sharing one VRF request
    /// @dev All picks share the same collateral. Per-pick amounts may differ. The worst-case
    /// aggregate profit (max across all 37 wheel outcomes — mutually exclusive picks don't stack)
    /// is validated against maxProfitUsd, and aggregate stake must satisfy MIN_BET_USD.
    /// Duplicate picks are permitted. With a single pick, this behaves identically to placeBet
    /// @return betId The id of the new bet
    /// @return requestId The Chainlink VRF request id
    function placeMultiBet(
        address collateral,
        PickInput[] calldata pickInputs,
        address _referrer
    ) external nonReentrant notPaused returns (uint betId, uint requestId) {
        if (!supportedCollateral[collateral]) revert InvalidCollateral();
        uint totalAmount = _validateAndSum(pickInputs);
        IERC20(collateral).safeTransferFrom(msg.sender, address(this), totalAmount);
        _setReferrer(_referrer, msg.sender);
        return _placeMulti(msg.sender, collateral, pickInputs, totalAmount, false);
    }

    /// @notice Places a multi-pick bet using free bet balance
    function placeMultiBetWithFreeBet(
        address collateral,
        PickInput[] calldata pickInputs
    ) external nonReentrant notPaused returns (uint betId, uint requestId) {
        if (!supportedCollateral[collateral]) revert InvalidCollateral();
        uint totalAmount = _validateAndSum(pickInputs);
        IFreeBetsHolder(freeBetsHolder).useFreeBet(msg.sender, collateral, totalAmount);
        return _placeMulti(msg.sender, collateral, pickInputs, totalAmount, true);
    }

    function _validateAndSum(PickInput[] calldata pickInputs) internal pure returns (uint total) {
        uint n = pickInputs.length;
        if (n == 0 || n > MAX_PICKS_PER_BET) revert InvalidPickCount();
        for (uint i = 0; i < n; i++) {
            total += pickInputs[i].amount;
        }
    }

    function _placeSingle(
        address user,
        address collateral,
        uint amount,
        BetType betType,
        uint8 selection,
        bool _isFreeBet
    ) internal returns (uint betId, uint requestId) {
        if (amount == 0) revert InvalidAmount();
        _validateSelection(betType, selection);

        if (_getUsdValue(collateral, amount) < MIN_BET_USD) revert InvalidAmount();

        uint profit = amount * _getProfitMultiplier(betType);
        if (_getUsdValue(collateral, profit) > maxProfitUsd) revert MaxProfitExceeded();

        reservedProfitPerCollateral[collateral] += amount + profit;
        if (!_hasEnoughLiquidity(collateral)) {
            reservedProfitPerCollateral[collateral] -= amount + profit;
            revert InsufficientAvailableLiquidity();
        }

        requestId = _requestRandomWord();
        betId = nextBetId++;
        bets[betId] = Bet({
            user: user,
            collateral: collateral,
            amount: amount,
            payout: 0,
            requestId: requestId,
            placedAt: block.timestamp,
            resolvedAt: 0,
            reservedProfit: profit,
            betType: betType,
            status: BetStatus.PENDING,
            selection: selection,
            result: 0,
            won: false
        });
        if (_isFreeBet) isFreeBet[betId] = true;
        requestIdToBetId[requestId] = betId;
        userBetIds[user].push(betId);

        emit BetPlaced(betId, requestId, user, collateral, amount, betType, selection);
    }

    function _placeMulti(
        address user,
        address collateral,
        PickInput[] calldata pickInputs,
        uint totalAmount,
        bool _isFreeBet
    ) internal returns (uint betId, uint requestId) {
        uint n = pickInputs.length;
        for (uint i = 0; i < n; i++) {
            PickInput calldata p = pickInputs[i];
            if (p.amount == 0) revert InvalidAmount();
            _validateSelection(p.betType, p.selection);
        }

        uint totalReservedProfit = _worstCaseProfit(pickInputs);

        if (_getUsdValue(collateral, totalAmount) < MIN_BET_USD) revert InvalidAmount();
        if (_getUsdValue(collateral, totalReservedProfit) > maxProfitUsd) revert MaxProfitExceeded();

        reservedProfitPerCollateral[collateral] += totalAmount + totalReservedProfit;
        if (!_hasEnoughLiquidity(collateral)) {
            reservedProfitPerCollateral[collateral] -= totalAmount + totalReservedProfit;
            revert InsufficientAvailableLiquidity();
        }

        requestId = _requestRandomWord();
        betId = nextBetId++;

        // For multi-pick bets, Bet.betType/selection reflect pick 0 as "primary" for UIs; the full
        // pick list lives in picks[betId]. Bet.amount / reservedProfit / payout are aggregates.
        bets[betId] = Bet({
            user: user,
            collateral: collateral,
            amount: totalAmount,
            payout: 0,
            requestId: requestId,
            placedAt: block.timestamp,
            resolvedAt: 0,
            reservedProfit: totalReservedProfit,
            betType: pickInputs[0].betType,
            status: BetStatus.PENDING,
            selection: pickInputs[0].selection,
            result: 0,
            won: false
        });
        if (_isFreeBet) isFreeBet[betId] = true;
        requestIdToBetId[requestId] = betId;
        userBetIds[user].push(betId);

        Pick[] storage dst = picks[betId];
        for (uint i = 0; i < n; i++) {
            PickInput calldata p = pickInputs[i];
            dst.push(
                Pick({
                    betType: p.betType,
                    selection: p.selection,
                    won: false,
                    amount: p.amount,
                    reservedProfit: p.amount * _getProfitMultiplier(p.betType),
                    payout: 0
                })
            );
        }

        emit BetPlaced(betId, requestId, user, collateral, totalAmount, pickInputs[0].betType, pickInputs[0].selection);
        emit MultiBetPlaced(betId, requestId, user, collateral, totalAmount, uint8(n), _isFreeBet);
    }

    /// @notice Cancels a pending bet after timeout and refunds the aggregate stake
    /// @param betId Bet id to cancel
    function cancelBet(uint betId) external nonReentrant {
        Bet storage bet = bets[betId];

        if (bet.status == BetStatus.NONE) revert BetNotFound();
        if (bet.user != msg.sender) revert BetNotOwner();
        if (bet.status != BetStatus.PENDING) revert BetNotPending();
        if (block.timestamp < bet.placedAt + cancelTimeout) revert CancelTimeoutNotReached();

        _cancelBet(betId, false);
    }

    /// @notice Emergency cancels a pending bet and refunds the aggregate stake
    /// @dev Callable by owner or manager role with MARKET_RESOLVING permission
    /// @param betId Bet id to cancel
    function adminCancelBet(uint betId) external onlyResolver nonReentrant {
        Bet storage bet = bets[betId];

        if (bet.status == BetStatus.NONE) revert BetNotFound();
        if (bet.status != BetStatus.PENDING) revert BetNotPending();

        _cancelBet(betId, true);
    }

    /// @notice Pauses or unpauses the contract using manager-based pauser permissions
    /// @param _paused True to pause, false to unpause
    function setPausedByRole(bool _paused) external onlyPauser {
        if (paused != _paused) {
            paused = _paused;
            if (_paused) {
                lastPauseTime = block.timestamp;
            }
            emit PauseChanged(_paused);
        }
    }

    /// @notice Coordinator-only VRF entrypoint
    /// @param requestId Chainlink VRF request id
    /// @param randomWords Array of VRF random words
    function rawFulfillRandomWords(uint256 requestId, uint256[] calldata randomWords) external nonReentrant {
        if (msg.sender != address(vrfCoordinator)) revert InvalidSender();
        _fulfillRandomWords(requestId, randomWords);
    }

    /* ========== INTERNAL / PRIVATE ========== */

    /// @notice Internal roulette resolution logic after VRF fulfillment
    /// @dev Single code path handles both single-pick and multi-pick bets: when picks[betId] is empty
    /// the Bet struct itself describes the only pick; otherwise iterate the stored Pick array
    /// @param requestId Chainlink VRF request id
    /// @param randomWords Array of VRF random words
    function _fulfillRandomWords(uint256 requestId, uint256[] calldata randomWords) internal {
        uint betId = requestIdToBetId[requestId];
        if (betId == 0) return;

        Bet storage bet = bets[betId];
        if (bet.status != BetStatus.PENDING) return;

        uint8 result = uint8(randomWords[0] % WHEEL_SIZE);
        address collateral = bet.collateral;
        address user = bet.user;

        reservedProfitPerCollateral[collateral] -= bet.amount + bet.reservedProfit;

        uint totalPayout;
        bool anyWon;
        Pick[] storage betPicks = picks[betId];
        uint pickCount = betPicks.length;
        if (pickCount == 0) {
            bool won = _isWinning(bet.betType, bet.selection, result);
            if (won) {
                totalPayout = bet.amount + bet.reservedProfit;
                anyWon = true;
            }
        } else {
            for (uint i = 0; i < pickCount; i++) {
                Pick storage p = betPicks[i];
                bool won = _isWinning(p.betType, p.selection, result);
                uint legPayout = 0;
                if (won) {
                    legPayout = p.amount + p.reservedProfit;
                    totalPayout += legPayout;
                    anyWon = true;
                }
                p.won = won;
                p.payout = legPayout;
            }
        }

        // State update before external transfers (CEI)
        bet.result = result;
        bet.won = anyWon;
        bet.payout = totalPayout;
        bet.status = BetStatus.RESOLVED;
        bet.resolvedAt = block.timestamp;

        emit BetResolved(betId, requestId, user, result, anyWon, totalPayout);

        if (totalPayout > 0) {
            if (isFreeBet[betId]) {
                IERC20(collateral).safeTransfer(freeBetsHolder, totalPayout);
                IFreeBetsHolder(freeBetsHolder).confirmCasinoBetResolved(user, collateral, totalPayout, bet.amount);
            } else {
                IERC20(collateral).safeTransfer(user, totalPayout);
            }
        } else if (!isFreeBet[betId]) {
            _payReferrer(user, collateral, bet.amount);
        }
    }

    function _setReferrer(address _referrer, address _user) internal {
        if (_referrer != address(0) && address(referrals) != address(0)) {
            referrals.setReferrer(_referrer, _user);
        }
    }

    function _payReferrer(address _user, address _collateral, uint _amount) internal {
        if (address(referrals) == address(0)) return;
        address referrer = referrals.referrals(_user);
        if (referrer == address(0)) return;
        uint referrerFee = referrals.getReferrerFee(referrer);
        if (referrerFee == 0) return;
        uint referrerAmount = (_amount * referrerFee) / ONE;
        if (referrerAmount > 0) {
            try IERC20(_collateral).transfer(referrer, referrerAmount) returns (bool ok) {
                if (ok) emit ReferrerPaid(referrer, _user, referrerAmount, _amount, _collateral);
                else emit ReferrerPayoutFailed(referrer, _user, referrerAmount, _amount, _collateral);
            } catch {
                emit ReferrerPayoutFailed(referrer, _user, referrerAmount, _amount, _collateral);
            }
        }
    }

    function _cancelBet(uint betId, bool adminCancelled) internal {
        Bet storage bet = bets[betId];

        reservedProfitPerCollateral[bet.collateral] -= bet.amount + bet.reservedProfit;

        bet.status = BetStatus.CANCELLED;
        bet.resolvedAt = block.timestamp;
        bet.won = false;

        if (isFreeBet[betId]) {
            bet.payout = 0;
            IERC20(bet.collateral).safeTransfer(freeBetsHolder, bet.amount);
            IFreeBetsHolder(freeBetsHolder).confirmCasinoBetResolved(bet.user, bet.collateral, bet.amount, bet.amount);
        } else {
            bet.payout = bet.amount;
            IERC20(bet.collateral).safeTransfer(bet.user, bet.amount);
        }

        emit BetCancelled(betId, bet.requestId, bet.user, bet.amount, adminCancelled);
    }

    /// @notice Requests one random word from Chainlink VRF
    /// @return requestId Chainlink VRF request id
    function _requestRandomWord() internal returns (uint requestId) {
        requestId = vrfCoordinator.requestRandomWords(
            VRFV2PlusClient.RandomWordsRequest({
                keyHash: keyHash,
                subId: subscriptionId,
                requestConfirmations: requestConfirmations,
                callbackGasLimit: callbackGasLimit,
                numWords: 1,
                extraArgs: VRFV2PlusClient._argsToBytes(VRFV2PlusClient.ExtraArgsV1({nativePayment: nativePayment}))
            })
        );
    }

    /// @notice Checks whether available collateral balance covers all reserved profit
    /// @param collateral Collateral token address
    /// @return True if bankroll is sufficient for the collateral
    function _hasEnoughLiquidity(address collateral) internal view returns (bool) {
        return IERC20(collateral).balanceOf(address(this)) >= reservedProfitPerCollateral[collateral];
    }

    /// @notice Returns the normalized price for a supported collateral
    /// @param collateral Collateral token address
    /// @return Collateral price normalized to 18 decimals
    function _getCollateralPrice(address collateral) internal view returns (uint) {
        if (!supportedCollateral[collateral]) revert InvalidCollateral();

        if (collateral == usdc) {
            return ONE;
        }

        bytes32 currencyKey = priceFeedKeyPerCollateral[collateral];
        if (currencyKey == bytes32(0)) revert InvalidCollateral();

        uint price = priceFeed.rateForCurrency(currencyKey);
        if (price == 0) revert InvalidPrice();

        return price;
    }

    /// @notice Converts collateral amount into USD value normalized to 18 decimals
    /// @param collateral Collateral token address
    /// @param amount Collateral amount
    /// @return USD value normalized to 18 decimals
    function _getUsdValue(address collateral, uint amount) internal view returns (uint) {
        if (collateral == usdc) {
            return (amount * ONE) / USDC_UNIT;
        }

        uint price = _getCollateralPrice(collateral);
        return (amount * price) / ONE;
    }

    /// @notice Returns profit multiplier for a given roulette bet type
    /// @param betType Roulette bet type
    /// @return Profit multiplier excluding original stake
    function _getProfitMultiplier(BetType betType) internal pure returns (uint) {
        if (betType == BetType.STRAIGHT) return 35;

        if (betType == BetType.RED_BLACK || betType == BetType.ODD_EVEN || betType == BetType.LOW_HIGH) {
            return 1;
        }

        if (betType == BetType.DOZEN || betType == BetType.COLUMN) {
            return 2;
        }

        revert InvalidBetType();
    }

    /// @notice Validates encoded selection for a given bet type
    /// @param betType Roulette bet type
    /// @param selection Encoded selection value
    function _validateSelection(BetType betType, uint8 selection) internal pure {
        if (betType == BetType.STRAIGHT) {
            if (selection > 36) revert InvalidSelection();
            return;
        }

        if (betType == BetType.RED_BLACK || betType == BetType.ODD_EVEN || betType == BetType.LOW_HIGH) {
            if (selection > 1) revert InvalidSelection();
            return;
        }

        if (betType == BetType.DOZEN || betType == BetType.COLUMN) {
            if (selection > 2) revert InvalidSelection();
            return;
        }

        revert InvalidBetType();
    }

    /// @notice Computes the worst-case net house liability across all 37 wheel outcomes
    /// @dev For each possible VRF result (0..36), net liability = sum of winning picks' profit minus
    /// sum of losing picks' stakes (losers' stakes are already collected from the user and offset
    /// the payout). Takes the max across all outcomes, clamped at 0. Matches true reservation need:
    /// mutually exclusive picks (e.g. two dozens) don't stack; losing stakes reduce the required
    /// bankroll reservation
    /// @param pickInputs Per-pick inputs
    /// @return worstCaseProfit Maximum net liability across all 37 possible wheel outcomes
    function _worstCaseProfit(PickInput[] calldata pickInputs) internal pure returns (uint worstCaseProfit) {
        uint n = pickInputs.length;
        uint totalStake;
        for (uint i = 0; i < n; i++) totalStake += pickInputs[i].amount;

        for (uint8 r = 0; r < WHEEL_SIZE; r++) {
            uint winnersProfit;
            uint winnersStake;
            for (uint i = 0; i < n; i++) {
                PickInput calldata p = pickInputs[i];
                if (_isWinning(p.betType, p.selection, r)) {
                    winnersProfit += p.amount * _getProfitMultiplier(p.betType);
                    winnersStake += p.amount;
                }
            }
            uint losersStake = totalStake - winnersStake;
            uint netLiability = winnersProfit > losersStake ? winnersProfit - losersStake : 0;
            if (netLiability > worstCaseProfit) worstCaseProfit = netLiability;
        }
    }

    /// @notice Returns whether a given bet selection wins for a roulette result
    /// @param betType Roulette bet type
    /// @param selection Encoded selection value
    /// @param result Roulette result in range 0..36 (European single-zero)
    /// @return True if the bet wins
    function _isWinning(BetType betType, uint8 selection, uint8 result) internal pure returns (bool) {
        if (betType == BetType.STRAIGHT) {
            return result == selection;
        }

        if (result == 0) {
            return false;
        }

        if (betType == BetType.RED_BLACK) {
            bool isRed = _isRed(result);
            return (selection == 0 && isRed) || (selection == 1 && !isRed);
        }

        if (betType == BetType.ODD_EVEN) {
            bool isEven = result % 2 == 0;
            return (selection == 0 && !isEven) || (selection == 1 && isEven);
        }

        if (betType == BetType.LOW_HIGH) {
            return (selection == 0 && result >= 1 && result <= 18) || (selection == 1 && result >= 19 && result <= 36);
        }

        if (betType == BetType.DOZEN) {
            return
                (selection == 0 && result >= 1 && result <= 12) ||
                (selection == 1 && result >= 13 && result <= 24) ||
                (selection == 2 && result >= 25 && result <= 36);
        }

        if (betType == BetType.COLUMN) {
            uint8 column = uint8((result - 1) % 3);
            return selection == column;
        }

        revert InvalidBetType();
    }

    /// @notice Returns whether a roulette number is red
    /// @param n Roulette number in range 1..36
    /// @return True if the number is red
    function _isRed(uint8 n) internal pure returns (bool) {
        return
            n == 1 ||
            n == 3 ||
            n == 5 ||
            n == 7 ||
            n == 9 ||
            n == 12 ||
            n == 14 ||
            n == 16 ||
            n == 18 ||
            n == 19 ||
            n == 21 ||
            n == 23 ||
            n == 25 ||
            n == 27 ||
            n == 30 ||
            n == 32 ||
            n == 34 ||
            n == 36;
    }

    /* ========== GETTERS ========== */

    /// @notice Returns potential profit in USD for a given bet
    /// @param collateral Collateral token address
    /// @param amount Bet amount
    /// @param betType Roulette bet type
    /// @return Potential profit in USD normalized to 18 decimals
    function getPotentialProfit(address collateral, uint amount, BetType betType) external view returns (uint) {
        uint potentialProfitCollateral = amount * _getProfitMultiplier(betType);
        return _getUsdValue(collateral, potentialProfitCollateral);
    }

    /// @notice Returns total payout in collateral units for a winning bet
    /// @param amount Bet amount
    /// @param betType Roulette bet type
    /// @return Total payout including original stake
    function getPotentialPayoutCollateral(uint amount, BetType betType) external pure returns (uint) {
        return amount + (amount * _getProfitMultiplier(betType));
    }

    /// @notice Returns normalized collateral price
    /// @param collateral Collateral token address
    /// @return Collateral price normalized to 18 decimals
    function getCollateralPrice(address collateral) external view returns (uint) {
        return _getCollateralPrice(collateral);
    }

    /// @notice Returns whether a given selection wins for a provided roulette result
    /// @param betType Roulette bet type
    /// @param selection Encoded selection value
    /// @param result Roulette result in range 0..36 (European single-zero)
    /// @return True if the bet wins
    function isWinningBet(BetType betType, uint8 selection, uint8 result) external pure returns (bool) {
        return _isWinning(betType, selection, result);
    }

    /// @notice Returns currently available liquidity for a collateral after reserved profit
    /// @param collateral Collateral token address
    /// @return Available liquidity amount in collateral units
    function getAvailableLiquidity(address collateral) external view returns (uint) {
        if (!supportedCollateral[collateral]) revert InvalidCollateral();
        uint balance = IERC20(collateral).balanceOf(address(this));
        uint reserved = reservedProfitPerCollateral[collateral];
        return balance > reserved ? balance - reserved : 0;
    }

    /// @notice Returns the number of bets placed by a user
    function getUserBetCount(address user) external view returns (uint) {
        return userBetIds[user].length;
    }

    /// @notice Returns core bet data
    function getBetBase(
        uint betId
    )
        external
        view
        returns (
            address user,
            address collateral,
            uint amount,
            uint payout,
            uint requestId,
            uint placedAt,
            uint resolvedAt,
            uint reservedProfit
        )
    {
        Bet storage b = bets[betId];
        return (b.user, b.collateral, b.amount, b.payout, b.requestId, b.placedAt, b.resolvedAt, b.reservedProfit);
    }

    /// @notice Returns bet game details including the full list of picks
    /// @dev For a single-pick bet, synthesizes a 1-element Pick array from the Bet struct; for a
    /// multi-pick bet, returns the stored picks. `won` is true iff any pick paid out (payout > 0)
    function getBetDetails(
        uint betId
    ) external view returns (Pick[] memory betPicks, BetStatus status, uint8 result, bool won) {
        Bet storage b = bets[betId];
        status = b.status;
        result = b.result;
        won = b.won;
        Pick[] storage stored = picks[betId];
        uint n = stored.length;
        if (n == 0) {
            betPicks = new Pick[](1);
            betPicks[0] = Pick({
                betType: b.betType,
                selection: b.selection,
                won: b.won,
                amount: b.amount,
                reservedProfit: b.reservedProfit,
                payout: b.payout
            });
        } else {
            betPicks = new Pick[](n);
            for (uint i = 0; i < n; i++) {
                betPicks[i] = stored[i];
            }
        }
    }

    /// @notice Returns the number of picks in a bet (always ≥ 1). Single-pick bets report 1
    function getBetPickCount(uint betId) external view returns (uint) {
        uint n = picks[betId].length;
        return n == 0 ? 1 : n;
    }

    /// @notice Returns bet IDs for a user's bets with pagination (reverse chronological)
    function getUserBetIds(address user, uint offset, uint limit) external view returns (uint[] memory ids) {
        uint[] storage allIds = userBetIds[user];
        uint len = allIds.length;
        if (offset >= len) return new uint[](0);
        uint remaining = len - offset;
        uint count = remaining < limit ? remaining : limit;
        ids = new uint[](count);
        for (uint i = 0; i < count; i++) {
            ids[i] = allIds[len - 1 - offset - i];
        }
    }

    /// @notice Returns recent bet IDs with pagination (reverse chronological)
    function getRecentBetIds(uint offset, uint limit) external view returns (uint[] memory ids) {
        uint latest = nextBetId - 1;
        if (offset >= latest) return new uint[](0);
        uint start = latest - offset;
        uint count = start < limit ? start : limit;
        ids = new uint[](count);
        for (uint i = 0; i < count; i++) {
            ids[i] = start - i;
        }
    }

    /// @notice Quotes aggregate stake and worst-case profit for a proposed multi-pick bet
    /// @dev Pure-of-state helper for UIs. `totalProfitCollateral` / `totalProfitUsd` reflect the
    /// worst-case aggregate profit across all 37 wheel outcomes — the exact value the contract
    /// checks against `maxProfitUsd`. The caller compares `totalProfitUsd` against `maxProfitUsd`
    /// and `totalProfitCollateral` against `getAvailableLiquidity` to check acceptability
    /// @return totalAmount Sum of per-pick stakes
    /// @return totalProfitCollateral Worst-case aggregate profit in collateral units
    /// @return totalProfitUsd Worst-case aggregate profit in USD normalized to 18 decimals
    function quoteMultiBet(
        address collateral,
        PickInput[] calldata pickInputs
    ) external view returns (uint totalAmount, uint totalProfitCollateral, uint totalProfitUsd) {
        if (!supportedCollateral[collateral]) revert InvalidCollateral();
        uint n = pickInputs.length;
        if (n == 0 || n > MAX_PICKS_PER_BET) revert InvalidPickCount();
        for (uint i = 0; i < n; i++) {
            _validateSelection(pickInputs[i].betType, pickInputs[i].selection);
            totalAmount += pickInputs[i].amount;
        }
        totalProfitCollateral = _worstCaseProfit(pickInputs);
        totalProfitUsd = _getUsdValue(collateral, totalProfitCollateral);
    }

    /* ========== SETTERS ========== */

    /// @notice Sets maximum allowed profit per bet in USD
    /// @dev Callable by owner or manager role with RISK_MANAGING permission
    /// @param _maxProfitUsd Maximum profit in USD normalized to 18 decimals
    function setMaxProfitUsd(uint _maxProfitUsd) external onlyRiskManager {
        if (_maxProfitUsd == 0) revert InvalidAmount();
        maxProfitUsd = _maxProfitUsd;
        emit MaxProfitUsdChanged(_maxProfitUsd);
    }

    /// @notice Sets timeout after which pending bets can be cancelled
    /// @dev Callable by owner or manager role with RISK_MANAGING permission
    /// @param _cancelTimeout Timeout in seconds
    function setCancelTimeout(uint _cancelTimeout) external onlyRiskManager {
        if (_cancelTimeout < MIN_CANCEL_TIMEOUT) revert InvalidAmount();
        cancelTimeout = _cancelTimeout;
        emit CancelTimeoutChanged(_cancelTimeout);
    }

    /// @notice Adds or removes a supported collateral
    /// @dev Callable by owner or manager role with RISK_MANAGING permission
    /// @param collateral Collateral token address
    /// @param isSupported Whether the collateral is supported
    function setSupportedCollateral(address collateral, bool isSupported) external onlyRiskManager {
        if (collateral == address(0)) revert InvalidAddress();
        supportedCollateral[collateral] = isSupported;
        emit SupportedCollateralChanged(collateral, isSupported);
    }

    /// @notice Sets price feed key for a collateral
    /// @dev Callable by owner or manager role with RISK_MANAGING permission
    /// @param collateral Collateral token address
    /// @param currencyKey Price feed currency key
    function setPriceFeedKeyPerCollateral(address collateral, bytes32 currencyKey) external onlyRiskManager {
        if (collateral == address(0)) revert InvalidAddress();
        priceFeedKeyPerCollateral[collateral] = currencyKey;
        emit PriceFeedKeyPerCollateralChanged(collateral, currencyKey);
    }

    /// @notice Sets manager contract address
    /// @param _manager Manager contract address
    function setManager(address _manager) external onlyOwner {
        if (_manager == address(0)) revert InvalidAddress();
        manager = ISportsAMMV2Manager(_manager);
        emit ManagerChanged(_manager);
    }

    /// @notice Sets price feed contract address
    /// @param _priceFeed Price feed contract address
    function setPriceFeed(address _priceFeed) external onlyOwner {
        if (_priceFeed == address(0)) revert InvalidAddress();
        priceFeed = IPriceFeed(_priceFeed);
        emit PriceFeedChanged(_priceFeed);
    }

    /// @notice Sets Chainlink VRF coordinator address
    /// @param _vrfCoordinator Chainlink VRF coordinator address
    function setVrfCoordinator(address _vrfCoordinator) external onlyOwner {
        if (_vrfCoordinator == address(0)) revert InvalidAddress();
        vrfCoordinator = IVRFCoordinatorV2Plus(_vrfCoordinator);
        emit VrfCoordinatorChanged(_vrfCoordinator);
    }

    /// @notice Sets the free bets holder contract
    function setFreeBetsHolder(address _freeBetsHolder) external onlyOwner {
        if (_freeBetsHolder == address(0)) revert InvalidAddress();
        freeBetsHolder = _freeBetsHolder;
        emit FreeBetsHolderChanged(_freeBetsHolder);
    }

    /// @notice Sets the referrals contract
    function setReferrals(address _referrals) external onlyOwner {
        if (_referrals == address(0)) revert InvalidAddress();
        referrals = IReferrals(_referrals);
        emit ReferralsChanged(_referrals);
    }

    /// @notice Withdraws collateral from the contract bankroll
    /// @param _collateral The address of the ERC20 token to withdraw
    /// @param _recipient The address of the recipient, defaults to owner if zero address
    /// @param _amount The amount of tokens to withdraw
    function withdrawCollateral(address _collateral, address _recipient, uint _amount) external onlyOwner {
        uint balance = IERC20(_collateral).balanceOf(address(this));
        uint reserved = reservedProfitPerCollateral[_collateral];
        if (_amount > balance || balance - _amount < reserved) revert InsufficientAvailableLiquidity();
        address recipient = _recipient == address(0) ? owner : _recipient;
        IERC20(_collateral).safeTransfer(recipient, _amount);
        emit WithdrawnCollateral(_collateral, recipient, _amount);
    }

    /// @notice Sets Chainlink VRF configuration
    /// @param _subscriptionId Chainlink VRF subscription id
    /// @param _keyHash Chainlink VRF key hash / gas lane
    /// @param _callbackGasLimit Gas limit for callback
    /// @param _requestConfirmations Number of confirmations before VRF fulfillment
    /// @param _nativePayment Whether VRF uses native token payment
    function setVrfConfig(
        uint256 _subscriptionId,
        bytes32 _keyHash,
        uint32 _callbackGasLimit,
        uint16 _requestConfirmations,
        bool _nativePayment
    ) external onlyOwner {
        if (_subscriptionId == 0) revert InvalidAmount();
        if (_keyHash == bytes32(0)) revert InvalidAmount();
        if (_callbackGasLimit == 0) revert InvalidAmount();

        subscriptionId = _subscriptionId;
        keyHash = _keyHash;
        callbackGasLimit = _callbackGasLimit;
        requestConfirmations = _requestConfirmations;
        nativePayment = _nativePayment;

        emit VrfConfigChanged(_subscriptionId, _keyHash, _callbackGasLimit, _requestConfirmations, _nativePayment);
    }

    /* ========== MODIFIERS ========== */

    /// @notice Restricts access to owner or manager addresses whitelisted for risk management
    modifier onlyRiskManager() {
        if (msg.sender != owner && !manager.isWhitelistedAddress(msg.sender, ISportsAMMV2Manager.Role.RISK_MANAGING)) {
            revert InvalidSender();
        }
        _;
    }

    /// @notice Restricts access to owner or manager addresses whitelisted for market resolving
    modifier onlyResolver() {
        if (msg.sender != owner && !manager.isWhitelistedAddress(msg.sender, ISportsAMMV2Manager.Role.MARKET_RESOLVING)) {
            revert InvalidSender();
        }
        _;
    }

    /// @notice Restricts access to owner or manager addresses whitelisted for pausing
    modifier onlyPauser() {
        if (msg.sender != owner && !manager.isWhitelistedAddress(msg.sender, ISportsAMMV2Manager.Role.TICKET_PAUSER)) {
            revert InvalidSender();
        }
        _;
    }

    /* ========== EVENTS ========== */

    /// @notice Emitted when a new bet is placed
    /// @param betId Bet id
    /// @param requestId Chainlink VRF request id
    /// @param user Bettor address
    /// @param collateral Collateral token address
    /// @param amount Bet amount
    /// @param betType Roulette bet type
    /// @param selection Encoded selection value
    event BetPlaced(
        uint indexed betId,
        uint indexed requestId,
        address indexed user,
        address collateral,
        uint amount,
        BetType betType,
        uint8 selection
    );

    /// @notice Emitted when a bet is resolved
    /// @param betId Bet id
    /// @param requestId Chainlink VRF request id
    /// @param user Bettor address
    /// @param result Roulette result in range 0..36 (European single-zero)
    /// @param won Whether the bet won
    /// @param payout Final payout amount
    event BetResolved(uint indexed betId, uint indexed requestId, address indexed user, uint8 result, bool won, uint payout);

    /// @notice Emitted when a bet is cancelled
    /// @param betId Bet id
    /// @param requestId Chainlink VRF request id
    /// @param user Bettor address
    /// @param refundedAmount Refunded stake amount
    /// @param adminCancelled Whether the cancellation was admin-triggered
    event BetCancelled(
        uint indexed betId,
        uint indexed requestId,
        address indexed user,
        uint refundedAmount,
        bool adminCancelled
    );

    /// @notice Emitted alongside BetPlaced when a bet includes multiple picks
    /// @dev For single-pick bets, only BetPlaced is emitted. For multi-pick bets, read picks[betId]
    /// or getBetDetails(betId) to retrieve the full pick list
    event MultiBetPlaced(
        uint indexed betId,
        uint indexed requestId,
        address indexed user,
        address collateral,
        uint totalAmount,
        uint8 pickCount,
        bool isFreeBet
    );

    /// @notice Emitted when maximum profit per bet is changed
    /// @param maxProfitUsd New maximum profit in USD normalized to 18 decimals
    event MaxProfitUsdChanged(uint maxProfitUsd);

    /// @notice Emitted when cancel timeout is changed
    /// @param cancelTimeout New timeout in seconds
    event CancelTimeoutChanged(uint cancelTimeout);

    /// @notice Emitted when collateral support is changed
    /// @param collateral Collateral token address
    /// @param supported Whether the collateral is supported
    event SupportedCollateralChanged(address collateral, bool supported);

    /// @notice Emitted when price feed key for a collateral is changed
    /// @param collateral Collateral token address
    /// @param key New price feed key
    event PriceFeedKeyPerCollateralChanged(address collateral, bytes32 key);

    /// @notice Emitted when manager contract is changed
    /// @param manager New manager contract address
    event ManagerChanged(address manager);

    /// @notice Emitted when price feed contract is changed
    /// @param priceFeed New price feed contract address
    event PriceFeedChanged(address priceFeed);

    /// @notice Emitted when VRF coordinator is changed
    /// @param vrfCoordinator New Chainlink VRF coordinator address
    event VrfCoordinatorChanged(address vrfCoordinator);
    event FreeBetsHolderChanged(address freeBetsHolder);
    event ReferralsChanged(address referrals);
    event ReferrerPaid(address indexed referrer, address indexed user, uint amount, uint betAmount, address collateral);
    event ReferrerPayoutFailed(
        address indexed referrer,
        address indexed user,
        uint amount,
        uint betAmount,
        address collateral
    );

    /// @notice Emitted when collateral is withdrawn from the bankroll
    /// @param collateral Collateral token address
    /// @param recipient Recipient address
    /// @param amount Amount withdrawn
    event WithdrawnCollateral(address indexed collateral, address indexed recipient, uint amount);

    /// @notice Emitted when VRF config is changed
    /// @param subscriptionId New Chainlink VRF subscription id
    /// @param keyHash New Chainlink VRF key hash
    /// @param callbackGasLimit New callback gas limit
    /// @param requestConfirmations New request confirmations value
    /// @param nativePayment Whether native payment is enabled
    event VrfConfigChanged(
        uint256 subscriptionId,
        bytes32 keyHash,
        uint32 callbackGasLimit,
        uint16 requestConfirmations,
        bool nativePayment
    );
}

contracts/core/Casino/Slots.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";

import "chainlink-vrf/src/v0.8/vrf/dev/interfaces/IVRFCoordinatorV2Plus.sol";
import "chainlink-vrf/src/v0.8/vrf/dev/libraries/VRFV2PlusClient.sol";

// internal
import "../../utils/proxy/ProxyReentrancyGuard.sol";
import "../../utils/proxy/ProxyOwned.sol";
import "../../utils/proxy/ProxyPausable.sol";
import "@thales-dao/contracts/contracts/interfaces/IPriceFeed.sol";

import "../../interfaces/ISportsAMMV2Manager.sol";
import "../../interfaces/IFreeBetsHolder.sol";
import "@thales-dao/contracts/contracts/interfaces/IReferrals.sol";

/// @title Slots
/// @author Overtime
/// @notice 3-reel slot machine contract using Chainlink VRF
/// @dev Supports USDC, WETH and OVER collateral, with bankroll reservation per collateral
contract Slots is Initializable, ProxyOwned, ProxyPausable, ProxyReentrancyGuard {
    using SafeERC20 for IERC20;

    /* ========== CONSTANTS ========== */

    uint private constant ONE = 1e18;
    uint private constant USDC_UNIT = 1e6;
    uint8 public constant REELS = 3;

    /// @notice Minimum allowed bet value expressed in USD, normalized to 18 decimals
    uint public constant MIN_BET_USD = 3e18;

    /// @notice Maximum allowed house edge in 1e18 precision
    uint public constant MAX_HOUSE_EDGE = 5e16; // 5%

    /// @notice Minimum allowed cancel timeout in seconds
    uint public constant MIN_CANCEL_TIMEOUT = 30;

    /* ========== ERRORS ========== */

    error InvalidAddress();
    error InvalidSender();
    error InvalidCollateral();
    error InvalidPrice();
    error InvalidAmount();
    error InvalidConfig();
    error InvalidHouseEdge();
    error SpinNotFound();
    error SpinNotPending();
    error SpinNotOwner();
    error CancelTimeoutNotReached();
    error MaxProfitExceeded();
    error InsufficientAvailableLiquidity();

    /* ========== ENUMS ========== */

    /// @notice Lifecycle status of a slot spin
    enum SpinStatus {
        NONE,
        PENDING,
        RESOLVED,
        CANCELLED
    }

    /* ========== STRUCTS ========== */

    /// @notice Stored data for an individual slot spin
    struct Spin {
        address user;
        address collateral;
        uint amount;
        uint payout;
        uint requestId;
        uint placedAt;
        uint resolvedAt;
        uint reservedProfit;
        SpinStatus status;
        uint8[3] reels;
        bool won;
    }

    struct CoreAddresses {
        address owner;
        address manager;
        address priceFeed;
        address vrfCoordinator;
    }

    struct CollateralConfig {
        address usdc;
        address weth;
        address over;
        bytes32 wethPriceFeedKey;
        bytes32 overPriceFeedKey;
    }

    struct VrfConfig {
        uint256 subscriptionId;
        bytes32 keyHash;
        uint32 callbackGasLimit;
        uint16 requestConfirmations;
        bool nativePayment;
    }

    /* ========== STATE VARIABLES ========== */

    /// @notice Manager contract used for whitelist-based role checks
    ISportsAMMV2Manager public manager;

    /// @notice Price feed used for collateral normalization to USD
    IPriceFeed public priceFeed;

    /// @notice Chainlink VRF coordinator
    IVRFCoordinatorV2Plus public vrfCoordinator;

    /// @notice Supported collateral addresses
    address public usdc;
    address public weth;
    address public over;

    /// @notice Maximum allowed profit per spin in USD, normalized to 18 decimals
    uint public maxProfitUsd;

    /// @notice Timeout after which a pending spin can be cancelled
    uint public cancelTimeout;

    /// @notice House edge in 1e18 precision. Example: 1e16 = 1%
    uint public houseEdge;

    /// @notice Next spin id to assign
    uint public nextSpinId;

    /// @notice Chainlink VRF v2.5 subscription id
    uint256 public subscriptionId;

    /// @notice Chainlink VRF key hash / gas lane
    bytes32 public keyHash;

    /// @notice Gas limit for VRF callback execution
    uint32 public callbackGasLimit;

    /// @notice Number of confirmations for VRF request
    uint16 public requestConfirmations;

    /// @notice Whether VRF request is paid in native token
    bool public nativePayment;

    /// @notice Whether a collateral is supported
    mapping(address => bool) public supportedCollateral;

    /// @notice Price feed key per collateral for non-USDC assets
    mapping(address => bytes32) public priceFeedKeyPerCollateral;

    /// @notice Stored spins by spin id
    mapping(uint => Spin) internal spins;

    /// @notice Maps VRF request id to spin id
    mapping(uint => uint) public requestIdToSpinId;

    /// @notice Tracks reserved house-side profit liability for all pending spins per collateral
    mapping(address => uint) public reservedProfitPerCollateral;

    /* ========== SLOT CONFIG ========== */

    /// @notice Number of distinct symbols on the reels
    uint8 public symbolCount;

    /// @notice Weights for each symbol (sum defines the distribution)
    uint[] public symbolWeights;

    /// @notice Payout multiplier for 3-of-a-kind per symbol (in 1e18 precision, net of stake)
    mapping(uint8 => uint) public triplePayout;

    /// @notice Maximum payout multiplier (used to calculate reserved profit)
    uint public maxPayoutMultiplier;

    /// @notice Spin IDs per user for history queries
    mapping(address => uint[]) private userSpinIds;

    /// @notice Free bets holder contract address
    address public freeBetsHolder;

    /// @notice Whether a spin was placed with a free bet
    mapping(uint => bool) public isFreeBet;

    /// @notice Referrals contract
    IReferrals public referrals;

    /// @notice Payout multiplier for adjacent 2-of-a-kind per symbol (in 1e18 precision, net of stake)
    /// @dev A pair is first-two-reels or last-two-reels matching (triples are handled separately)
    mapping(uint8 => uint) public pairPayout;

    /// @notice Cached sum of symbolWeights — updated in setSymbols to avoid recomputing per-reel
    uint public symbolWeightsTotal;

    /* ========== PUBLIC / EXTERNAL METHODS ========== */

    /// @notice Initializes the slots contract
    /// @param core Core protocol addresses
    /// @param collateralConfig Collateral addresses and price feed keys
    /// @param _maxProfitUsd Maximum allowed profit per spin in USD, normalized to 18 decimals
    /// @param _cancelTimeout Timeout after which a pending spin can be cancelled
    /// @param _houseEdge House edge in 1e18 precision. Example: 1e16 = 1%
    /// @param _maxPayoutMultiplier Maximum payout multiplier in 1e18 precision
    /// @param vrfConfig Chainlink VRF configuration
    function initialize(
        CoreAddresses calldata core,
        CollateralConfig calldata collateralConfig,
        uint _maxProfitUsd,
        uint _cancelTimeout,
        uint _houseEdge,
        uint _maxPayoutMultiplier,
        VrfConfig calldata vrfConfig
    ) external initializer {
        if (
            core.owner == address(0) ||
            core.manager == address(0) ||
            core.priceFeed == address(0) ||
            core.vrfCoordinator == address(0) ||
            collateralConfig.usdc == address(0) ||
            collateralConfig.weth == address(0) ||
            collateralConfig.over == address(0)
        ) {
            revert InvalidAddress();
        }

        if (_maxProfitUsd == 0) revert InvalidAmount();
        if (_houseEdge == 0 || _houseEdge > MAX_HOUSE_EDGE) revert InvalidHouseEdge();
        if (_maxPayoutMultiplier == 0) revert InvalidAmount();
        if (vrfConfig.callbackGasLimit == 0) revert InvalidAmount();

        setOwner(core.owner);
        initNonReentrant();

        manager = ISportsAMMV2Manager(core.manager);
        priceFeed = IPriceFeed(core.priceFeed);
        vrfCoordinator = IVRFCoordinatorV2Plus(core.vrfCoordinator);

        usdc = collateralConfig.usdc;
        weth = collateralConfig.weth;
        over = collateralConfig.over;

        supportedCollateral[collateralConfig.usdc] = true;
        supportedCollateral[collateralConfig.weth] = true;
        supportedCollateral[collateralConfig.over] = true;

        priceFeedKeyPerCollateral[collateralConfig.weth] = collateralConfig.wethPriceFeedKey;
        priceFeedKeyPerCollateral[collateralConfig.over] = collateralConfig.overPriceFeedKey;

        if (_cancelTimeout < MIN_CANCEL_TIMEOUT) revert InvalidAmount();
        maxProfitUsd = _maxProfitUsd;
        cancelTimeout = _cancelTimeout;
        houseEdge = _houseEdge;
        maxPayoutMultiplier = _maxPayoutMultiplier;

        subscriptionId = vrfConfig.subscriptionId;
        keyHash = vrfConfig.keyHash;
        callbackGasLimit = vrfConfig.callbackGasLimit;
        requestConfirmations = vrfConfig.requestConfirmations;
        nativePayment = vrfConfig.nativePayment;

        nextSpinId = 1;
    }

    /// @notice Places a slot spin and requests randomness from Chainlink VRF
    /// @param collateral Collateral token address
    /// @param amount Amount of collateral to stake
    /// @return spinId Newly created spin id
    /// @return requestId Chainlink VRF request id
    function spin(
        address collateral,
        uint amount,
        address _referrer
    ) external nonReentrant notPaused returns (uint spinId, uint requestId) {
        if (!supportedCollateral[collateral]) revert InvalidCollateral();
        IERC20(collateral).safeTransferFrom(msg.sender, address(this), amount);
        _setReferrer(_referrer, msg.sender);
        return _spin(msg.sender, collateral, amount, false);
    }

    /// @notice Places a slot spin using free bet balance
    /// @param collateral Collateral token address
    /// @param amount Amount of collateral to stake
    /// @return spinId Newly created spin id
    /// @return requestId Chainlink VRF request id
    function spinWithFreeBet(
        address collateral,
        uint amount
    ) external nonReentrant notPaused returns (uint spinId, uint requestId) {
        if (!supportedCollateral[collateral]) revert InvalidCollateral();
        IFreeBetsHolder(freeBetsHolder).useFreeBet(msg.sender, collateral, amount);
        return _spin(msg.sender, collateral, amount, true);
    }

    function _spin(
        address user,
        address collateral,
        uint amount,
        bool _isFreeBet
    ) internal returns (uint spinId, uint requestId) {
        if (symbolCount == 0) revert InvalidConfig();
        // collateral support already validated by the external wrappers (spin / spinWithFreeBet)
        if (amount == 0) revert InvalidAmount();

        uint amountUsd = _getUsdValue(collateral, amount);
        if (amountUsd < MIN_BET_USD) revert InvalidAmount();

        uint reservedProfit = (amount * maxPayoutMultiplier) / ONE;
        uint potentialProfitUsd = _getUsdValue(collateral, reservedProfit);

        if (potentialProfitUsd > maxProfitUsd) revert MaxProfitExceeded();

        reservedProfitPerCollateral[collateral] += amount + reservedProfit;

        if (!_hasEnoughLiquidity(collateral)) {
            reservedProfitPerCollateral[collateral] -= amount + reservedProfit;
            revert InsufficientAvailableLiquidity();
        }

        requestId = _requestRandomWord();

        spinId = nextSpinId++;
        spins[spinId] = Spin({
            user: user,
            collateral: collateral,
            amount: amount,
            payout: 0,
            requestId: requestId,
            placedAt: block.timestamp,
            resolvedAt: 0,
            reservedProfit: reservedProfit,
            status: SpinStatus.PENDING,
            reels: [uint8(0), uint8(0), uint8(0)],
            won: false
        });

        if (_isFreeBet) isFreeBet[spinId] = true;

        requestIdToSpinId[requestId] = spinId;
        userSpinIds[user].push(spinId);

        emit SpinPlaced(spinId, requestId, user, collateral, amount);
    }

    /// @notice Cancels a pending spin after timeout and refunds the original stake
    /// @param spinId Spin id to cancel
    function cancelSpin(uint spinId) external nonReentrant {
        Spin storage s = spins[spinId];

        if (s.status == SpinStatus.NONE) revert SpinNotFound();
        if (s.user != msg.sender) revert SpinNotOwner();
        if (s.status != SpinStatus.PENDING) revert SpinNotPending();
        if (block.timestamp < s.placedAt + cancelTimeout) revert CancelTimeoutNotReached();

        _cancelSpin(spinId, false);
    }

    /// @notice Emergency cancels a pending spin and refunds the original stake
    /// @dev Callable by owner or manager role with MARKET_RESOLVING permission
    /// @param spinId Spin id to cancel
    function adminCancelSpin(uint spinId) external onlyResolver nonReentrant {
        Spin storage s = spins[spinId];

        if (s.status == SpinStatus.NONE) revert SpinNotFound();
        if (s.status != SpinStatus.PENDING) revert SpinNotPending();

        _cancelSpin(spinId, true);
    }

    /// @notice Pauses or unpauses the contract using manager-based pauser permissions
    /// @param _paused True to pause, false to unpause
    function setPausedByRole(bool _paused) external onlyPauser {
        if (paused != _paused) {
            paused = _paused;
            if (_paused) {
                lastPauseTime = block.timestamp;
            }
            emit PauseChanged(_paused);
        }
    }

    /// @notice Coordinator-only VRF entrypoint
    /// @param requestId Chainlink VRF request id
    /// @param randomWords Array of VRF random words
    function rawFulfillRandomWords(uint256 requestId, uint256[] calldata randomWords) external nonReentrant {
        if (msg.sender != address(vrfCoordinator)) revert InvalidSender();
        _fulfillRandomWords(requestId, randomWords);
    }

    /* ========== INTERNAL / PRIVATE ========== */

    /// @notice Internal spin resolution logic after VRF fulfillment
    function _fulfillRandomWords(uint256 requestId, uint256[] calldata randomWords) internal {
        uint spinId = requestIdToSpinId[requestId];
        if (spinId == 0) return;

        Spin storage s = spins[spinId];
        if (s.status != SpinStatus.PENDING) return;

        uint r = randomWords[0];

        uint8 r1 = _roll(uint256(keccak256(abi.encode(r, uint(0)))));
        uint8 r2 = _roll(uint256(keccak256(abi.encode(r, uint(1)))));
        uint8 r3 = _roll(uint256(keccak256(abi.encode(r, uint(2)))));

        s.reels = [r1, r2, r3];

        uint multiplier = _getPayoutMultiplier(r1, r2, r3);

        reservedProfitPerCollateral[s.collateral] -= s.amount + s.reservedProfit;

        uint payout = multiplier > 0 ? s.amount + (s.amount * multiplier) / ONE : 0;

        // State update before external transfers (CEI)
        s.payout = payout;
        s.won = multiplier > 0;
        s.status = SpinStatus.RESOLVED;
        s.resolvedAt = block.timestamp;

        emit SpinResolved(spinId, requestId, s.user, [r1, r2, r3], s.won, payout);

        if (multiplier > 0) {
            if (isFreeBet[spinId]) {
                IERC20(s.collateral).safeTransfer(freeBetsHolder, payout);
                IFreeBetsHolder(freeBetsHolder).confirmCasinoBetResolved(s.user, s.collateral, payout, s.amount);
            } else {
                IERC20(s.collateral).safeTransfer(s.user, payout);
            }
        } else if (!isFreeBet[spinId]) {
            _payReferrer(s.user, s.collateral, s.amount);
        }
    }

    function _setReferrer(address _referrer, address _user) internal {
        if (_referrer != address(0) && address(referrals) != address(0)) {
            referrals.setReferrer(_referrer, _user);
        }
    }

    function _payReferrer(address _user, address _collateral, uint _amount) internal {
        if (address(referrals) == address(0)) return;
        address referrer = referrals.referrals(_user);
        if (referrer == address(0)) return;
        uint referrerFee = referrals.getReferrerFee(referrer);
        if (referrerFee == 0) return;
        uint referrerAmount = (_amount * referrerFee) / ONE;
        if (referrerAmount > 0) {
            try IERC20(_collateral).transfer(referrer, referrerAmount) returns (bool ok) {
                if (ok) emit ReferrerPaid(referrer, _user, referrerAmount, _amount, _collateral);
                else emit ReferrerPayoutFailed(referrer, _user, referrerAmount, _amount, _collateral);
            } catch {
                emit ReferrerPayoutFailed(referrer, _user, referrerAmount, _amount, _collateral);
            }
        }
    }

    function _cancelSpin(uint spinId, bool adminCancelled) internal {
        Spin storage s = spins[spinId];

        reservedProfitPerCollateral[s.collateral] -= s.amount + s.reservedProfit;

        s.status = SpinStatus.CANCELLED;
        s.resolvedAt = block.timestamp;
        s.won = false;

        if (isFreeBet[spinId]) {
            s.payout = 0;
            IERC20(s.collateral).safeTransfer(freeBetsHolder, s.amount);
            IFreeBetsHolder(freeBetsHolder).confirmCasinoBetResolved(s.user, s.collateral, s.amount, s.amount);
        } else {
            s.payout = s.amount;
            IERC20(s.collateral).safeTransfer(s.user, s.amount);
        }

        emit SpinCancelled(spinId, s.requestId, s.user, s.amount, adminCancelled);
    }

    /// @notice Rolls a single reel using weighted random selection
    function _roll(uint r) internal view returns (uint8) {
        uint total = symbolWeightsTotal;
        if (total == 0) {
            // Fallback for the one-time upgrade window before setSymbols is re-called
            for (uint i = 0; i < symbolWeights.length; i++) total += symbolWeights[i];
        }
        uint rand = r % total;

        uint acc;
        for (uint8 i = 0; i < symbolCount; i++) {
            acc += symbolWeights[i];
            if (rand < acc) return i;
        }

        return 0;
    }

    /// @notice Returns the net payout multiplier in 1e18 precision for a given reel result
    /// @dev Triple (3-of-a-kind) supersedes adjacent pair. Pair matches `a==b` or `b==c`.
    ///      Returns 0 if no winning combination; applies house edge to the selected raw payout.
    function _getPayoutMultiplier(uint8 a, uint8 b, uint8 c) internal view returns (uint) {
        uint rawMultiplier;
        if (a == b && b == c) {
            rawMultiplier = triplePayout[a];
        } else if (a == b) {
            rawMultiplier = pairPayout[a];
        } else if (b == c) {
            rawMultiplier = pairPayout[b];
        }
        if (rawMultiplier == 0) return 0;
        return (rawMultiplier * (ONE - houseEdge)) / ONE;
    }

    /// @notice Requests one random word from Chainlink VRF
    function _requestRandomWord() internal returns (uint requestId) {
        requestId = vrfCoordinator.requestRandomWords(
            VRFV2PlusClient.RandomWordsRequest({
                keyHash: keyHash,
                subId: subscriptionId,
                requestConfirmations: requestConfirmations,
                callbackGasLimit: callbackGasLimit,
                numWords: 1,
                extraArgs: VRFV2PlusClient._argsToBytes(VRFV2PlusClient.ExtraArgsV1({nativePayment: nativePayment}))
            })
        );
    }

    /// @notice Checks whether available collateral balance covers all reserved profit
    function _hasEnoughLiquidity(address collateral) internal view returns (bool) {
        return IERC20(collateral).balanceOf(address(this)) >= reservedProfitPerCollateral[collateral];
    }

    /// @notice Returns the normalized price for a supported collateral
    function _getCollateralPrice(address collateral) internal view returns (uint) {
        if (!supportedCollateral[collateral]) revert InvalidCollateral();

        if (collateral == usdc) {
            return ONE;
        }

        bytes32 currencyKey = priceFeedKeyPerCollateral[collateral];
        if (currencyKey == bytes32(0)) revert InvalidCollateral();

        uint price = priceFeed.rateForCurrency(currencyKey);
        if (price == 0) revert InvalidPrice();

        return price;
    }

    /// @notice Converts collateral amount into USD value normalized to 18 decimals
    function _getUsdValue(address collateral, uint amount) internal view returns (uint) {
        if (collateral == usdc) {
            return (amount * ONE) / USDC_UNIT;
        }

        uint price = _getCollateralPrice(collateral);
        return (amount * price) / ONE;
    }

    /* ========== GETTERS ========== */

    /// @notice Returns normalized collateral price
    function getCollateralPrice(address collateral) external view returns (uint) {
        return _getCollateralPrice(collateral);
    }

    /// @notice Returns currently available liquidity for a collateral after reserved profit
    function getAvailableLiquidity(address collateral) external view returns (uint) {
        if (!supportedCollateral[collateral]) revert InvalidCollateral();
        uint balance = IERC20(collateral).balanceOf(address(this));
        uint reserved = reservedProfitPerCollateral[collateral];
        return balance > reserved ? balance - reserved : 0;
    }

    /// @notice Returns the reel results for a resolved spin
    /// @param spinId The ID of the spin
    /// @return The 3 reel symbol indices
    function getSpinReels(uint spinId) external view returns (uint8[3] memory) {
        return spins[spinId].reels;
    }

    /// @notice Returns the symbol weights array
    function getSymbolWeights() external view returns (uint[] memory) {
        return symbolWeights;
    }

    /// @notice Returns core spin data
    function getSpinBase(
        uint spinId
    )
        external
        view
        returns (
            address user,
            address collateral,
            uint amount,
            uint payout,
            uint requestId,
            uint placedAt,
            uint resolvedAt,
            uint reservedProfit
        )
    {
        Spin storage s = spins[spinId];
        return (s.user, s.collateral, s.amount, s.payout, s.requestId, s.placedAt, s.resolvedAt, s.reservedProfit);
    }

    /// @notice Returns spin game details
    function getSpinDetails(uint spinId) external view returns (SpinStatus status, uint8[3] memory reels, bool won) {
        Spin storage s = spins[spinId];
        return (s.status, s.reels, s.won);
    }

    /// @notice Returns the number of spins placed by a user
    function getUserSpinCount(address user) external view returns (uint) {
        return userSpinIds[user].length;
    }

    /// @notice Returns spin IDs for a user's spins with pagination (reverse chronological)
    function getUserSpinIds(address user, uint offset, uint limit) external view returns (uint[] memory ids) {
        uint[] storage allIds = userSpinIds[user];
        uint len = allIds.length;
        if (offset >= len) return new uint[](0);
        uint remaining = len - offset;
        uint count = remaining < limit ? remaining : limit;
        ids = new uint[](count);
        for (uint i = 0; i < count; i++) {
            ids[i] = allIds[len - 1 - offset - i];
        }
    }

    /// @notice Returns recent spin IDs with pagination (reverse chronological)
    function getRecentSpinIds(uint offset, uint limit) external view returns (uint[] memory ids) {
        uint latest = nextSpinId - 1;
        if (offset >= latest) return new uint[](0);
        uint start = latest - offset;
        uint count = start < limit ? start : limit;
        ids = new uint[](count);
        for (uint i = 0; i < count; i++) {
            ids[i] = start - i;
        }
    }

    /* ========== SETTERS ========== */

    /// @notice Sets the symbol configuration
    /// @param _count Number of distinct symbols
    /// @param weights Array of weights for each symbol
    function setSymbols(uint8 _count, uint[] calldata weights) external onlyOwner {
        if (_count == 0 || weights.length != _count) revert InvalidConfig();
        uint total;
        for (uint i = 0; i < weights.length; i++) total += weights[i];
        if (total == 0) revert InvalidConfig();
        symbolCount = _count;
        symbolWeights = weights;
        symbolWeightsTotal = total;
        emit SymbolsChanged(_count, weights);
    }

    /// @notice Sets the payout multiplier for a 3-of-a-kind symbol
    /// @param symbol Symbol index
    /// @param multiplier Payout multiplier in 1e18 precision (net of stake), must be <= maxPayoutMultiplier
    function setTriplePayout(uint8 symbol, uint multiplier) external onlyOwner {
        if (symbol >= symbolCount) revert InvalidConfig();
        if (multiplier > maxPayoutMultiplier) revert InvalidConfig();
        triplePayout[symbol] = multiplier;
        emit TriplePayoutChanged(symbol, multiplier);
    }

    /// @notice Sets the payout multiplier for an adjacent 2-of-a-kind symbol
    /// @param symbol Symbol index
    /// @param multiplier Payout multiplier in 1e18 precision (net of stake), must be <= maxPayoutMultiplier
    function setPairPayout(uint8 symbol, uint multiplier) external onlyOwner {
        if (symbol >= symbolCount) revert InvalidConfig();
        if (multiplier > maxPayoutMultiplier) revert InvalidConfig();
        pairPayout[symbol] = multiplier;
        emit PairPayoutChanged(symbol, multiplier);
    }

    /// @notice Sets maximum allowed profit per spin in USD
    function setMaxProfitUsd(uint _maxProfitUsd) external onlyRiskManager {
        if (_maxProfitUsd == 0) revert InvalidAmount();
        maxProfitUsd = _maxProfitUsd;
        emit MaxProfitUsdChanged(_maxProfitUsd);
    }

    /// @notice Sets timeout after which pending spins can be cancelled
    function setCancelTimeout(uint _cancelTimeout) external onlyRiskManager {
        if (_cancelTimeout < MIN_CANCEL_TIMEOUT) revert InvalidAmount();
        cancelTimeout = _cancelTimeout;
        emit CancelTimeoutChanged(_cancelTimeout);
    }

    /// @notice Sets house edge
    function setHouseEdge(uint _houseEdge) external onlyRiskManager {
        if (_houseEdge == 0 || _houseEdge > MAX_HOUSE_EDGE) revert InvalidHouseEdge();
        houseEdge = _houseEdge;
        emit HouseEdgeChanged(_houseEdge);
    }

    /// @notice Sets maximum payout multiplier (must be >= all existing triplePayout and pairPayout values)
    function setMaxPayoutMultiplier(uint _maxPayoutMultiplier) external onlyRiskManager {
        if (_maxPayoutMultiplier == 0) revert InvalidAmount();
        for (uint8 i = 0; i < symbolCount; i++) {
            if (triplePayout[i] > _maxPayoutMultiplier) revert InvalidConfig();
            if (pairPayout[i] > _maxPayoutMultiplier) revert InvalidConfig();
        }
        maxPayoutMultiplier = _maxPayoutMultiplier;
        emit MaxPayoutMultiplierChanged(_maxPayoutMultiplier);
    }

    /// @notice Adds or removes a supported collateral
    function setSupportedCollateral(address collateral, bool isSupported) external onlyRiskManager {
        if (collateral == address(0)) revert InvalidAddress();
        supportedCollateral[collateral] = isSupported;
        emit SupportedCollateralChanged(collateral, isSupported);
    }

    /// @notice Sets price feed key for a collateral
    function setPriceFeedKeyPerCollateral(address collateral, bytes32 currencyKey) external onlyRiskManager {
        if (collateral == address(0)) revert InvalidAddress();
        priceFeedKeyPerCollateral[collateral] = currencyKey;
        emit PriceFeedKeyPerCollateralChanged(collateral, currencyKey);
    }

    /// @notice Sets manager contract address
    function setManager(address _manager) external onlyOwner {
        if (_manager == address(0)) revert InvalidAddress();
        manager = ISportsAMMV2Manager(_manager);
        emit ManagerChanged(_manager);
    }

    /// @notice Sets price feed contract address
    function setPriceFeed(address _priceFeed) external onlyOwner {
        if (_priceFeed == address(0)) revert InvalidAddress();
        priceFeed = IPriceFeed(_priceFeed);
        emit PriceFeedChanged(_priceFeed);
    }

    /// @notice Sets Chainlink VRF coordinator address
    function setVrfCoordinator(address _vrfCoordinator) external onlyOwner {
        if (_vrfCoordinator == address(0)) revert InvalidAddress();
        vrfCoordinator = IVRFCoordinatorV2Plus(_vrfCoordinator);
        emit VrfCoordinatorChanged(_vrfCoordinator);
    }

    /// @notice Sets the free bets holder contract
    function setFreeBetsHolder(address _freeBetsHolder) external onlyOwner {
        if (_freeBetsHolder == address(0)) revert InvalidAddress();
        freeBetsHolder = _freeBetsHolder;
        emit FreeBetsHolderChanged(_freeBetsHolder);
    }

    /// @notice Sets the referrals contract
    function setReferrals(address _referrals) external onlyOwner {
        if (_referrals == address(0)) revert InvalidAddress();
        referrals = IReferrals(_referrals);
        emit ReferralsChanged(_referrals);
    }

    /// @notice Withdraws collateral from the contract bankroll
    function withdrawCollateral(address _collateral, address _recipient, uint _amount) external onlyOwner {
        uint balance = IERC20(_collateral).balanceOf(address(this));
        uint reserved = reservedProfitPerCollateral[_collateral];
        if (_amount > balance || balance - _amount < reserved) revert InsufficientAvailableLiquidity();
        address recipient = _recipient == address(0) ? owner : _recipient;
        IERC20(_collateral).safeTransfer(recipient, _amount);
        emit WithdrawnCollateral(_collateral, recipient, _amount);
    }

    /// @notice Sets Chainlink VRF configuration
    function setVrfConfig(
        uint256 _subscriptionId,
        bytes32 _keyHash,
        uint32 _callbackGasLimit,
        uint16 _requestConfirmations,
        bool _nativePayment
    ) external onlyOwner {
        if (_subscriptionId == 0) revert InvalidAmount();
        if (_keyHash == bytes32(0)) revert InvalidAmount();
        if (_callbackGasLimit == 0) revert InvalidAmount();

        subscriptionId = _subscriptionId;
        keyHash = _keyHash;
        callbackGasLimit = _callbackGasLimit;
        requestConfirmations = _requestConfirmations;
        nativePayment = _nativePayment;

        emit VrfConfigChanged(_subscriptionId, _keyHash, _callbackGasLimit, _requestConfirmations, _nativePayment);
    }

    /* ========== MODIFIERS ========== */

    modifier onlyRiskManager() {
        if (msg.sender != owner && !manager.isWhitelistedAddress(msg.sender, ISportsAMMV2Manager.Role.RISK_MANAGING)) {
            revert InvalidSender();
        }
        _;
    }

    modifier onlyResolver() {
        if (msg.sender != owner && !manager.isWhitelistedAddress(msg.sender, ISportsAMMV2Manager.Role.MARKET_RESOLVING)) {
            revert InvalidSender();
        }
        _;
    }

    modifier onlyPauser() {
        if (msg.sender != owner && !manager.isWhitelistedAddress(msg.sender, ISportsAMMV2Manager.Role.TICKET_PAUSER)) {
            revert InvalidSender();
        }
        _;
    }

    /* ========== EVENTS ========== */

    event SpinPlaced(uint indexed spinId, uint indexed requestId, address indexed user, address collateral, uint amount);

    event SpinResolved(
        uint indexed spinId,
        uint indexed requestId,
        address indexed user,
        uint8[3] reels,
        bool won,
        uint payout
    );

    event SpinCancelled(
        uint indexed spinId,
        uint indexed requestId,
        address indexed user,
        uint refundedAmount,
        bool adminCancelled
    );

    event SymbolsChanged(uint8 count, uint[] weights);
    event TriplePayoutChanged(uint8 symbol, uint multiplier);
    event PairPayoutChanged(uint8 symbol, uint multiplier);
    event MaxProfitUsdChanged(uint maxProfitUsd);
    event CancelTimeoutChanged(uint cancelTimeout);
    event HouseEdgeChanged(uint houseEdge);
    event MaxPayoutMultiplierChanged(uint maxPayoutMultiplier);
    event SupportedCollateralChanged(address collateral, bool supported);
    event PriceFeedKeyPerCollateralChanged(address collateral, bytes32 key);
    event ManagerChanged(address manager);
    event PriceFeedChanged(address priceFeed);
    event VrfCoordinatorChanged(address vrfCoordinator);
    event FreeBetsHolderChanged(address freeBetsHolder);
    event ReferralsChanged(address referrals);
    event ReferrerPaid(address indexed referrer, address indexed user, uint amount, uint betAmount, address collateral);
    event ReferrerPayoutFailed(
        address indexed referrer,
        address indexed user,
        uint amount,
        uint betAmount,
        address collateral
    );
    event WithdrawnCollateral(address indexed collateral, address indexed recipient, uint amount);
    event VrfConfigChanged(
        uint256 subscriptionId,
        bytes32 keyHash,
        uint32 callbackGasLimit,
        uint16 requestConfirmations,
        bool nativePayment
    );
}

contracts/core/Casino/ThreeCardPoker.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";

import "../../utils/proxy/ProxyReentrancyGuard.sol";
import "../../utils/proxy/ProxyOwned.sol";
import "../../utils/proxy/ProxyPausable.sol";

import "../../interfaces/ISportsAMMV2Manager.sol";
import "../../interfaces/ICasinoCoreV2.sol";
import "../../interfaces/ICasinoGameCallback.sol";
import "../../interfaces/ICasinoThreeCardPoker.sol";
import "./CasinoHandsLib.sol";

/// @title ThreeCardPoker
/// @author Overtime
/// @notice Single-player Three Card Poker against the dealer. Optional Pair Plus side bet.
/// Uses two VRF requests per round so dealer cards are not on-chain (and not exploitable via
/// `eth_getStorageAt`) before the player commits to Play vs Fold.
/// @dev All funds, randomness, free-bets and circuit-breaker accounting live in `CasinoCoreV2`.
/// This contract is pure game logic + lifecycle state.
///
/// Locked paytables (≥2% guaranteed edge):
/// - Ante Bonus: Straight Flush 5:1, Three of a Kind 4:1, Straight 1:1
/// - Pair Plus:  Straight Flush 40:1, Three of a Kind 30:1, Straight 6:1, Flush 4:1, Pair 1:1
contract ThreeCardPoker is
    ICasinoThreeCardPoker,
    ICasinoGameCallback,
    Initializable,
    ProxyOwned,
    ProxyPausable,
    ProxyReentrancyGuard
{
    /* ========== CONSTANTS ========== */

    uint256 private constant ONE = 1e18;

    uint256 public constant MIN_BET_USD = 3e18;

    uint8 private constant DECK_SIZE = 52;
    uint8 private constant CARDS_PER_HAND = 3;

    // Rank index in 2..14 (2 = deuce, 14 = ace)
    uint8 private constant RANK_TWO = 2;
    uint8 private constant RANK_THREE = 3;
    uint8 private constant RANK_QUEEN = 12;
    uint8 private constant RANK_ACE = 14;

    // Dealer qualifier: Q-high or better
    uint8 private constant QUALIFIER_RANK = RANK_QUEEN;

    // Hand classes (numeric value matters: higher class beats lower regardless of kickers)
    uint8 private constant CLASS_HIGH_CARD = 0;
    uint8 private constant CLASS_PAIR = 1;
    uint8 private constant CLASS_FLUSH = 2;
    uint8 private constant CLASS_STRAIGHT = 3;
    uint8 private constant CLASS_THREE_OF_A_KIND = 4;
    uint8 private constant CLASS_STRAIGHT_FLUSH = 5;

    // Ante Bonus paytable (multiples of Ante; not stake-returning, pure bonus)
    uint256 private constant ANTE_BONUS_STRAIGHT_FLUSH = 5;
    uint256 private constant ANTE_BONUS_THREE_OF_A_KIND = 4;
    uint256 private constant ANTE_BONUS_STRAIGHT = 1;

    // Pair Plus paytable (multiples of pair-plus stake; payout = stake * (mult + 1) on win)
    uint256 private constant PAIR_PLUS_STRAIGHT_FLUSH = 40;
    uint256 private constant PAIR_PLUS_THREE_OF_A_KIND = 30;
    uint256 private constant PAIR_PLUS_STRAIGHT = 6;
    uint256 private constant PAIR_PLUS_FLUSH = 4;
    uint256 private constant PAIR_PLUS_PAIR = 1;

    // Reservation: max possible total payout from a single bet at placeBet time.
    //   Ante side max:      ante * (1 + 1 + 5) = 7 * ante     (1 stake-back + 1 Play 1:1 + 5 Ante Bonus SF)
    //   Wait — ante 1:1 is also 1*ante on top of the stake = 2*ante payout. Same for Play.
    //   Recompute:
    //     Ante stake-back + Ante 1:1 win + Play stake-back + Play 1:1 win + Ante Bonus SF (5x)
    //     = ante + ante + ante + ante + 5*ante = 9 * ante
    //   Pair Plus side max: pairPlus * (1 + 40) = 41 * pairPlus
    uint256 private constant MAX_PAYOUT_ANTE_MULT = 9;
    uint256 private constant MAX_PAYOUT_PAIR_PLUS_MULT = 41;

    // Reservation portion released after pair plus settles (the unused PP slice is freed).
    // Worst-case PP payout already released; remaining liability covers ante side only (9*ante).

    /* ========== ERRORS ========== */

    error InvalidAddress();
    error InvalidSender();
    error InvalidAmount();
    error InvalidCollateral();
    error AboveMaxBet();
    error BetNotFound();
    error BetNotOwner();
    error InvalidBetStatus();
    /// @notice Reverted when `placeBetWithFreeBet` is called with a non-zero `pairPlusAmount`.
    /// Without this, a winning PP would credit-back the PP stake via the FBH split, paying the
    /// user as if no free-bet credit had been consumed. Disallow rather than restructure the
    /// settle path
    error PairPlusNotAllowedForFreeBet();
    /// @notice Reverted by `makeAction` when an unknown action code is supplied
    error InvalidAction();

    /* ========== STRUCTS ========== */

    struct Bet {
        address user;
        address collateral;
        uint256 anteAmount;
        uint256 pairPlusAmount;
        uint256 totalPayout;
        uint256 placedAt;
        uint256 lastRequestAt;
        uint256 resolvedAt;
        uint256 reservedAnteSide; // total remaining reservation for this bet (ante + PP); name is legacy from when PP had its own reservation slot
        uint256 requestId;
        uint8[3] playerCards;
        uint8[3] dealerCards;
        BetStatus status;
        Outcome outcome;
        // payout breakdown (for FE clarity, populated as each leg settles)
        uint256 pairPlusPayout;
        uint256 anteBonusPayout;
        uint256 anteAndPlayPayout;
        // Bet placed with free-bet balance — stake (ante+PP at place, Play at play()) pulled
        // from FreeBetsHolder. All settlements route through FBH; referrer payments suppressed
        bool isFreeBet;
        // Remaining net-profit budget for this bet in collateral units. Sized at placeBet from
        // `effectiveMaxProfitUsd × price`, capped against the worst-case uncapped profit.
        // Each settle leg (PP at VRF1, ante+play at VRF2) deducts profit_paid from this budget
        // so the per-hand net loss to the house never exceeds the configured USD cap, regardless
        // of stake size. Appended at end of struct for storage-safe upgrade
        uint256 profitCapRemaining;
    }

    /* ========== STATE ========== */

    ICasinoCoreV2 public core;
    ISportsAMMV2Manager public manager;

    uint256 public nextBetId;

    mapping(uint256 => Bet) internal bets;
    mapping(uint256 => uint256) public requestIdToBetId;
    mapping(address => uint256[]) private userBetIds;

    /* ========== INITIALIZER ========== */

    function initialize(address _owner, address _core, address _manager) external initializer {
        if (_owner == address(0) || _core == address(0) || _manager == address(0)) revert InvalidAddress();
        setOwner(_owner);
        initNonReentrant();
        core = ICasinoCoreV2(_core);
        manager = ISportsAMMV2Manager(_manager);
        nextBetId = 1;
    }

    /* ========== PLACE / PLAY / FOLD ========== */

    /// @notice Places a Three Card Poker bet (Ante required, Pair Plus optional). Triggers VRF1
    /// for player cards. Player and dealer hands are dealt from independent shuffles to keep
    /// dealer cards off-chain until the player commits to Play. `isFreeBet=true` pulls from
    /// FreeBetsHolder (and reverts if pairPlusAmount > 0); `false` from the user's wallet
    function placeBet(
        address collateral,
        uint256 anteAmount,
        uint256 pairPlusAmount,
        address referrer,
        bool isFreeBet
    ) external override nonReentrant notPaused returns (uint256 betId, uint256 requestId) {
        return _placeBet(collateral, anteAmount, pairPlusAmount, referrer, isFreeBet);
    }

    function _placeBet(
        address collateral,
        uint256 anteAmount,
        uint256 pairPlusAmount,
        address referrer,
        bool isFreeBet
    ) internal returns (uint256 betId, uint256 requestId) {
        if (anteAmount == 0) revert InvalidAmount();
        if (!core.supportedCollateral(collateral)) revert InvalidCollateral();
        // Free-bet flow cannot bundle the optional Pair Plus side bet. A winning PP would refund
        // its stake to the user via the FBH split, paying the user back as if no free-bet credit
        // had been consumed on the PP leg. Disallow rather than restructure the PP-settlement
        // path to carve PP out of the originalStake handed to FBH
        if (isFreeBet && pairPlusAmount > 0) revert PairPlusNotAllowedForFreeBet();

        _checkBetSize(collateral, anteAmount, pairPlusAmount);
        uint256 cappedProfit = _cappedProfit(collateral, anteAmount, pairPlusAmount);

        // Pull Ante + Pair Plus — from FBH if free bet, else from user wallet (single approval target)
        if (isFreeBet) {
            core.useFreeBet(msg.sender, collateral, anteAmount + pairPlusAmount);
        } else {
            core.pullFromUser(msg.sender, collateral, anteAmount + pairPlusAmount);
        }

        // Set referrer (no-op if zero / no referrals contract wired)
        if (referrer != address(0)) core.setReferrer(referrer, msg.sender);

        // Reserve worst-case capped payout = stake_total + cappedProfit
        // stake_total = (ante + max-Play=ante) + PP = 2*ante + PP
        uint256 reservation = anteAmount * 2 + pairPlusAmount + cappedProfit;
        core.reserveOrRevert(collateral, reservation);

        // Request VRF1 (player cards)
        requestId = core.requestRandomWords(1);

        betId = nextBetId++;
        Bet storage b = bets[betId];
        b.user = msg.sender;
        b.collateral = collateral;
        b.anteAmount = anteAmount;
        b.pairPlusAmount = pairPlusAmount;
        b.placedAt = block.timestamp;
        b.lastRequestAt = block.timestamp;
        b.requestId = requestId;
        b.status = BetStatus.AWAITING_DEAL;
        b.reservedAnteSide = reservation; // repurposed: total remaining reservation for this bet
        b.profitCapRemaining = cappedProfit;
        b.isFreeBet = isFreeBet;

        requestIdToBetId[requestId] = betId;
        userBetIds[msg.sender].push(betId);

        emit BetPlaced(betId, requestId, msg.sender, collateral, anteAmount, pairPlusAmount);
    }

    /// @notice Single-selector mid-game dispatcher. Action codes:
    ///   0 = play  — commit to Play (pulls another Ante-sized stake, triggers VRF2 for dealer)
    ///   1 = fold  — forfeit Ante (PP already settled at VRF1)
    /// @dev AUDIT NOTE: mid-game pause traps in-flight winners; see HiLo.makeAction rationale
    function makeAction(uint256 betId, uint8 action) external override nonReentrant notPaused returns (uint256 requestId) {
        if (action == 0) return _play(betId);
        if (action == 1) {
            _fold(betId);
            return 0;
        }
        revert InvalidAction();
    }

    function _play(uint256 betId) internal returns (uint256 requestId) {
        Bet storage b = bets[betId];
        _requireOwnedPlayerTurn(b);

        // Pull Play stake (= Ante). Free-bet runs draw the play stake from FBH too; if the
        // remaining FBH balance is insufficient the call reverts and the user must fold instead
        if (b.isFreeBet) {
            core.useFreeBet(b.user, b.collateral, b.anteAmount);
        } else {
            core.pullFromUser(b.user, b.collateral, b.anteAmount);
        }

        requestId = core.requestRandomWords(1);
        b.requestId = requestId;
        b.lastRequestAt = block.timestamp;
        b.status = BetStatus.AWAITING_RESOLVE;
        requestIdToBetId[requestId] = betId;

        emit PlayChosen(betId, requestId, b.user, b.anteAmount);
    }

    function _fold(uint256 betId) internal {
        Bet storage b = bets[betId];
        _requireOwnedPlayerTurn(b);
        _doFold(betId, b);
    }

    function _doFold(uint256 betId, Bet storage b) internal {
        // Release ante-side reservation; ante itself stays in bankroll (forfeit)
        core.releaseReservation(b.collateral, b.reservedAnteSide);
        b.reservedAnteSide = 0;

        // Record settlement: stake = ante (forfeit), payout = 0 → house gains ante in P&L gauge.
        // Pair Plus has its own settlement already recorded in VRF1 fulfill
        core.recordSettlement(b.collateral, b.anteAmount, 0);

        // Best-effort referrer payout — only when the user lost money on the bet as a whole
        // (ante forfeit minus any PP winnings already paid in _onDealFulfilled). Skipped on
        // free bets — user lost no real funds
        if (!b.isFreeBet) {
            uint256 totalStake = b.anteAmount + b.pairPlusAmount;
            uint256 totalPayout = b.pairPlusPayout;
            if (totalPayout < totalStake) {
                core.payReferrer(b.user, b.collateral, totalStake - totalPayout);
            }
        }

        b.status = BetStatus.RESOLVED;
        b.outcome = Outcome.FOLDED;
        b.resolvedAt = block.timestamp;
        emit Folded(betId, b.user);
    }

    /// @notice Operator-only cancel. Refunds whatever stakes have been pulled. User cancel was
    /// removed to close a VRF-callback front-run surface where a user could observe the mempool
    /// VRF2 fulfillment, compute the resolved hand off-chain, and front-run a losing draw with
    /// a cheaper cancel. Stuck bets (stalled VRF or user walked away mid-decision) are now
    /// resolved exclusively via `adminCancelBet` (operator-only). All states except RESOLVED /
    /// CANCELLED are admin-cancellable
    function adminCancelBet(uint256 betId) external override nonReentrant onlyResolver {
        Bet storage b = bets[betId];
        if (b.status == BetStatus.NONE) revert BetNotFound();
        if (b.status == BetStatus.RESOLVED || b.status == BetStatus.CANCELLED) revert InvalidBetStatus();
        _cancelBet(betId, true);
    }

    function _cancelBet(uint256 betId, bool adminCancelled) internal {
        Bet storage b = bets[betId];
        // Clear any in-flight VRF mapping so a late callback's mapping lookup is a no-op
        // (status-check would also catch it, but matches the hygiene pattern of the other 4 games)
        if (b.requestId != 0) delete requestIdToBetId[b.requestId];

        // Refund: stakes still owed to the user.
        // AWAITING_DEAL  → ante + pairPlus (PP not yet settled).
        // PLAYER_TURN    → ante only (PP already settled in VRF1; Play stake not yet pulled).
        // AWAITING_RESOLVE → ante + Play stake (PP already settled in VRF1; do NOT refund pp again
        // or the user double-banks the pp stake on a winning PP / recovers a lost pp on a losing PP).
        uint256 refund = b.anteAmount;
        if (b.status == BetStatus.AWAITING_DEAL) {
            refund += b.pairPlusAmount;
        } else if (b.status == BetStatus.AWAITING_RESOLVE) {
            refund += b.anteAmount;
        }

        // Release whatever reservation is still held for this bet. `reservedAnteSide` now
        // represents the entire remaining reservation (decremented at VRF1 PP settle)
        uint256 reservationToRelease = b.reservedAnteSide;
        b.reservedAnteSide = 0;
        core.releaseReservation(b.collateral, reservationToRelease);

        // Refund stakes — routes back to FBH if this was a free bet (credits user's free-bet
        // balance via confirmCasinoBetResolved, exercised == stake → credit branch)
        core.payOut(b.user, b.collateral, refund, b.isFreeBet, refund);

        // Decrement core's pending-stake counter (stake == refund → zero P&L impact). PP stake
        // was already decremented at VRF1 PP settlement; the `refund` here is exactly the
        // stake still in-flight at this status (ante; ante+pp from AWAITING_DEAL; ante+play
        // from AWAITING_RESOLVE)
        core.recordSettlement(b.collateral, refund, refund);

        // `+=` instead of `=`: in AWAITING_RESOLVE, b.totalPayout already holds the PP payout
        // recorded by VRF1; we want the FE-visible total to reflect both. From AWAITING_DEAL the
        // prior value is 0, so the result is identical to `=`.
        b.totalPayout += refund;
        b.status = BetStatus.CANCELLED;
        b.resolvedAt = block.timestamp;
        emit BetCancelled(betId, b.user, refund, adminCancelled);
    }

    /* ========== VRF CALLBACK ========== */

    /// @inheritdoc ICasinoGameCallback
    /// @dev `nonReentrant` blocks re-entry into THIS contract's own user-facing functions
    /// (placeBet / makeAction / adminCancelBet) during fulfillment, defending against
    /// malicious-token transfer hooks that could otherwise re-enter mid-payout for a double-spend
    function onVrfFulfilled(uint256 requestId, uint256[] calldata randomWords) external override nonReentrant {
        if (msg.sender != address(core)) revert InvalidSender();
        uint256 betId = requestIdToBetId[requestId];
        if (betId == 0) return; // already cancelled / unknown
        delete requestIdToBetId[requestId];

        Bet storage b = bets[betId];
        if (b.status == BetStatus.AWAITING_DEAL) {
            _onDealFulfilled(betId, b, randomWords[0]);
        } else if (b.status == BetStatus.AWAITING_RESOLVE) {
            _onResolveFulfilled(betId, b, randomWords[0]);
        }
        // any other state: stale callback, ignore
    }

    /// @notice VRF1 fulfillment — deal player cards, settle Pair Plus, advance to PLAYER_TURN
    function _onDealFulfilled(uint256 betId, Bet storage b, uint256 word) internal {
        uint8[3] memory pCards = _drawThreeCards(word);
        b.playerCards = pCards;

        // Settle Pair Plus (independent of dealer / fold). PP profit consumes the shared
        // per-bet profit budget. After settle, right-size the reservation to ante-side worst
        // case = 2*ante + min(7*ante, profitCapRemaining) — releases both the PP stake slot
        // and any cap slot no longer reachable by the ante side
        uint256 ppPayout = 0;
        if (b.pairPlusAmount > 0) {
            (uint8 pClass, ) = _evaluate3Card(pCards);
            uint256 ppMult = _pairPlusMultiplier(pClass);
            if (ppMult > 0) {
                uint256 ppProfitRaw = b.pairPlusAmount * ppMult;
                uint256 ppProfit = ppProfitRaw > b.profitCapRemaining ? b.profitCapRemaining : ppProfitRaw;
                ppPayout = b.pairPlusAmount + ppProfit;
                b.profitCapRemaining -= ppProfit;
            }
            uint256 anteMaxProfit = b.anteAmount * (MAX_PAYOUT_ANTE_MULT - 2);
            uint256 anteSideLiability = b.anteAmount *
                2 +
                (anteMaxProfit > b.profitCapRemaining ? b.profitCapRemaining : anteMaxProfit);
            uint256 toRelease = b.reservedAnteSide - anteSideLiability;
            b.reservedAnteSide = anteSideLiability;
            core.releaseReservation(b.collateral, toRelease);
            if (ppPayout > 0) {
                core.payOut(b.user, b.collateral, ppPayout, b.isFreeBet, b.pairPlusAmount);
            }
            // Settlement accounting for Pair Plus leg
            core.recordSettlement(b.collateral, b.pairPlusAmount, ppPayout);
        }

        b.pairPlusPayout = ppPayout;
        b.totalPayout = ppPayout;
        b.status = BetStatus.PLAYER_TURN;

        emit PlayerCardsDealt(betId, b.requestId, b.user, pCards[0], pCards[1], pCards[2], ppPayout);
    }

    /// @notice Outcome computation result. Lives in memory only — extracted to keep
    /// `_onResolveFulfilled` below the stack-too-deep threshold without `viaIR`
    struct Resolution {
        Outcome outcome;
        uint256 anteAndPlayPayout;
        uint256 anteBonusPayout;
    }

    /// @notice VRF2 fulfillment — deal dealer cards (excluding player's), settle Ante / Play /
    /// Ante Bonus and finalize the bet
    function _onResolveFulfilled(uint256 betId, Bet storage b, uint256 word) internal {
        uint8[3] memory dCards = _drawThreeDealerCards(word, b.playerCards);
        b.dealerCards = dCards;

        Resolution memory r = _computeResolution(b.playerCards, dCards, b.anteAmount);
        uint256 stakeOut = b.anteAmount * 2;

        // Apply soft cap on ante-side profit
        uint256 totalSideAPayout = r.anteAndPlayPayout + r.anteBonusPayout;
        if (totalSideAPayout > stakeOut) {
            uint256 profit = totalSideAPayout - stakeOut;
            if (profit > b.profitCapRemaining) profit = b.profitCapRemaining;
            totalSideAPayout = stakeOut + profit;
            b.profitCapRemaining -= profit;
            // Redistribute the truncated profit across the reported per-leg breakdown so
            // r.anteBonusPayout + r.anteAndPlayPayout == totalSideAPayout. anteBonus is the
            // variance-heavy leg (paid even when dealer doesn't qualify), so cap it first; any
            // residual profit flows to anteAndPlay on top of stake-back
            if (r.anteBonusPayout > profit) {
                r.anteBonusPayout = profit;
                r.anteAndPlayPayout = stakeOut;
            } else {
                r.anteAndPlayPayout = stakeOut + profit - r.anteBonusPayout;
            }
        }

        // Release ALL remaining reservation for this bet — VRF2 is the terminal leg
        core.releaseReservation(b.collateral, b.reservedAnteSide);
        b.reservedAnteSide = 0;

        if (totalSideAPayout > 0) {
            core.payOut(b.user, b.collateral, totalSideAPayout, b.isFreeBet, stakeOut);
        }
        core.recordSettlement(b.collateral, stakeOut, totalSideAPayout);

        // Pay referrer only when the user lost money on the bet as a whole — include PP
        // (settled at VRF1) in both stake and payout sums. Play stake equals ante (matched),
        // and we only reach _onResolveFulfilled when the player played, so total stake-out =
        // 2*ante + PP. Skipped on free bets — user lost no real funds
        if (!b.isFreeBet) {
            uint256 totalStake = b.anteAmount * 2 + b.pairPlusAmount;
            uint256 totalPayout = b.pairPlusPayout + totalSideAPayout;
            if (totalPayout < totalStake) {
                core.payReferrer(b.user, b.collateral, totalStake - totalPayout);
            }
        }

        b.outcome = r.outcome;
        b.anteBonusPayout = r.anteBonusPayout;
        b.anteAndPlayPayout = r.anteAndPlayPayout;
        b.totalPayout += totalSideAPayout;
        b.status = BetStatus.RESOLVED;
        b.resolvedAt = block.timestamp;

        emit BetResolved(
            betId,
            b.requestId,
            b.user,
            r.outcome,
            dCards[0],
            dCards[1],
            dCards[2],
            r.anteAndPlayPayout,
            r.anteBonusPayout,
            totalSideAPayout
        );
    }

    function _computeResolution(
        uint8[3] memory pCards,
        uint8[3] memory dCards,
        uint256 anteAmount
    ) internal pure returns (Resolution memory r) {
        (uint8 pClass, uint32 pTie) = _evaluate3Card(pCards);
        (uint8 dClass, uint32 dTie) = _evaluate3Card(dCards);

        // Ante Bonus: pure bonus on top of Ante side, regardless of dealer outcome
        r.anteBonusPayout = _anteBonusMultiplier(pClass) * anteAmount;

        if (!_dealerQualifies(dClass, dTie)) {
            // Ante 1:1, Play push: 2x ante (stake + win) + ante (Play stake-back) = 3x ante
            r.outcome = Outcome.DEALER_NOT_QUALIFIED;
            r.anteAndPlayPayout = anteAmount * 3;
            return r;
        }

        int8 cmp = _compareHands(pClass, pTie, dClass, dTie);
        if (cmp > 0) {
            r.outcome = Outcome.PLAYER_WIN;
            r.anteAndPlayPayout = anteAmount * 4; // ante 2x + play 2x
        } else if (cmp < 0) {
            r.outcome = Outcome.DEALER_WIN;
            // anteAndPlayPayout = 0
        } else {
            r.outcome = Outcome.TIE;
            r.anteAndPlayPayout = anteAmount * 2; // both push
        }
    }

    /* ========== SHUFFLE / DEAL ========== */

    /// @notice Draws 3 unique cards from a 52-card deck via partial Fisher-Yates seeded by `word`
    function _drawThreeCards(uint256 word) internal pure returns (uint8[3] memory out) {
        uint8[] memory deck = CasinoHandsLib.initDeck(DECK_SIZE, 0);
        CasinoHandsLib.partialFisherYates(deck, CARDS_PER_HAND, word);
        out[0] = deck[0];
        out[1] = deck[1];
        out[2] = deck[2];
    }

    /// @notice Draws 3 unique dealer cards from a 49-card deck excluding the 3 player cards
    function _drawThreeDealerCards(uint256 word, uint8[3] memory excluded) internal pure returns (uint8[3] memory out) {
        uint64 mask = (uint64(1) << excluded[0]) | (uint64(1) << excluded[1]) | (uint64(1) << excluded[2]);
        uint8[] memory deck = CasinoHandsLib.initDeck(DECK_SIZE - CARDS_PER_HAND, mask);
        CasinoHandsLib.partialFisherYates(deck, CARDS_PER_HAND, word);
        out[0] = deck[0];
        out[1] = deck[1];
        out[2] = deck[2];
    }

    /* ========== HAND EVALUATION ========== */

    /// @notice Evaluates a 3-card hand. Returns hand class (0..5) and a tie-breaker uint32 that
    /// orders correctly within the same class (higher is better)
    function _evaluate3Card(uint8[3] memory cards) internal pure returns (uint8 class_, uint32 tieBreaker) {
        // ranks 2..14, suits 0..3
        uint8 r0 = uint8(cards[0] % 13) + RANK_TWO;
        uint8 r1 = uint8(cards[1] % 13) + RANK_TWO;
        uint8 r2 = uint8(cards[2] % 13) + RANK_TWO;
        uint8 s0 = uint8(cards[0] / 13);
        uint8 s1 = uint8(cards[1] / 13);
        uint8 s2 = uint8(cards[2] / 13);

        // sort ranks descending into (rHi, rMid, rLo)
        (uint8 rHi, uint8 rMid, uint8 rLo) = _sortDesc3(r0, r1, r2);

        bool isFlush = (s0 == s1 && s1 == s2);

        // straight detection on sorted ranks: consecutive (rHi - rLo == 2) OR ace-low wheel A-2-3
        bool isStraight = false;
        uint8 straightTopRank = rHi;
        if (rHi - rLo == 2 && rHi - rMid == 1) {
            isStraight = true;
        } else if (rHi == RANK_ACE && rMid == RANK_THREE && rLo == RANK_TWO) {
            // ace-low wheel: top card is the 3 for tie-break purposes
            isStraight = true;
            straightTopRank = RANK_THREE;
        }

        // three of a kind
        if (rHi == rLo) {
            class_ = CLASS_THREE_OF_A_KIND;
            tieBreaker = uint32(rHi);
            return (class_, tieBreaker);
        }
        // straight flush
        if (isStraight && isFlush) {
            class_ = CLASS_STRAIGHT_FLUSH;
            tieBreaker = uint32(straightTopRank);
            return (class_, tieBreaker);
        }
        // straight (non-flush)
        if (isStraight) {
            class_ = CLASS_STRAIGHT;
            tieBreaker = uint32(straightTopRank);
            return (class_, tieBreaker);
        }
        // flush (non-straight)
        if (isFlush) {
            class_ = CLASS_FLUSH;
            tieBreaker = (uint32(rHi) << 16) | (uint32(rMid) << 8) | uint32(rLo);
            return (class_, tieBreaker);
        }
        // pair: any two equal (since not all three equal — that'd be 3 of a kind)
        if (rHi == rMid) {
            class_ = CLASS_PAIR;
            tieBreaker = (uint32(rHi) << 8) | uint32(rLo); // pair rank, then kicker
            return (class_, tieBreaker);
        }
        if (rMid == rLo) {
            class_ = CLASS_PAIR;
            tieBreaker = (uint32(rMid) << 8) | uint32(rHi); // pair rank, then kicker
            return (class_, tieBreaker);
        }
        // high card
        class_ = CLASS_HIGH_CARD;
        tieBreaker = (uint32(rHi) << 16) | (uint32(rMid) << 8) | uint32(rLo);
    }

    function _sortDesc3(uint8 a, uint8 b, uint8 c) internal pure returns (uint8 hi, uint8 mid, uint8 lo) {
        // 3-element descending sort
        if (a >= b) {
            if (b >= c) {
                (hi, mid, lo) = (a, b, c);
            } else if (a >= c) {
                (hi, mid, lo) = (a, c, b);
            } else {
                (hi, mid, lo) = (c, a, b);
            }
        } else {
            if (a >= c) {
                (hi, mid, lo) = (b, a, c);
            } else if (b >= c) {
                (hi, mid, lo) = (b, c, a);
            } else {
                (hi, mid, lo) = (c, b, a);
            }
        }
    }

    /// @notice Returns 1 if player hand wins, -1 if dealer wins, 0 if tie
    function _compareHands(uint8 pClass, uint32 pTie, uint8 dClass, uint32 dTie) internal pure returns (int8) {
        if (pClass > dClass) return 1;
        if (pClass < dClass) return -1;
        if (pTie > dTie) return 1;
        if (pTie < dTie) return -1;
        return 0;
    }

    /// @notice Dealer qualifies on Q-high or better. Q-high = HIGH_CARD with top rank >= Q,
    /// or any hand class above HIGH_CARD. For HIGH_CARD, `_evaluate3Card` already encodes the
    /// top rank in bits [16:24] of `tieBreaker` — read it directly instead of recomputing
    /// @dev Relies on `_evaluate3Card` packing the HIGH_CARD tieBreaker as
    /// `(topRank << 16) | (midRank << 8) | loRank`. Bits [16:24] = top rank. If that encoding
    /// is ever changed, update this extraction in lockstep
    function _dealerQualifies(uint8 dClass, uint32 dTie) internal pure returns (bool) {
        if (dClass > CLASS_HIGH_CARD) return true;
        return uint8(dTie >> 16) >= QUALIFIER_RANK;
    }

    /* ========== PAYTABLE LOOKUPS ========== */

    function _anteBonusMultiplier(uint8 class_) internal pure returns (uint256) {
        if (class_ == CLASS_STRAIGHT_FLUSH) return ANTE_BONUS_STRAIGHT_FLUSH;
        if (class_ == CLASS_THREE_OF_A_KIND) return ANTE_BONUS_THREE_OF_A_KIND;
        if (class_ == CLASS_STRAIGHT) return ANTE_BONUS_STRAIGHT;
        return 0;
    }

    function _pairPlusMultiplier(uint8 class_) internal pure returns (uint256) {
        if (class_ == CLASS_STRAIGHT_FLUSH) return PAIR_PLUS_STRAIGHT_FLUSH;
        if (class_ == CLASS_THREE_OF_A_KIND) return PAIR_PLUS_THREE_OF_A_KIND;
        if (class_ == CLASS_STRAIGHT) return PAIR_PLUS_STRAIGHT;
        if (class_ == CLASS_FLUSH) return PAIR_PLUS_FLUSH;
        if (class_ == CLASS_PAIR) return PAIR_PLUS_PAIR;
        return 0;
    }

    /* ========== INTERNAL HELPERS ========== */

    function _requireOwnedPlayerTurn(Bet storage b) internal view {
        if (b.status == BetStatus.NONE) revert BetNotFound();
        if (b.user != msg.sender) revert BetNotOwner();
        if (b.status != BetStatus.PLAYER_TURN) revert InvalidBetStatus();
    }

    /// @notice Per-game bet-size gate. `MIN_BET_USD` floor applies to the required Ante AND, when
    /// present (> 0), the optional Pair Plus side bet — symmetric floor blocks dust PP bets that
    /// produce negligible payouts but still consume the full per-bet gas/VRF overhead. PP = 0
    /// still bypasses the check entirely (skip the side bet). The per-game `effectiveMaxBetUsd`
    /// ceiling caps each leg independently so a user can't sidestep the ante max by loading the
    /// optional PP side with a huge wager
    function _checkBetSize(address collateral, uint256 anteAmount, uint256 pairPlusAmount) internal view {
        uint256 anteUsd = core.getUsdValue(collateral, anteAmount);
        uint256 minBet = core.effectiveMinBetUsd(address(this));
        if (minBet == 0) minBet = MIN_BET_USD;
        if (anteUsd < minBet) revert InvalidAmount();
        uint256 maxBet = core.effectiveMaxBetUsd(address(this));
        if (maxBet != 0 && anteUsd > maxBet) revert AboveMaxBet();
        if (pairPlusAmount > 0) {
            uint256 ppUsd = core.getUsdValue(collateral, pairPlusAmount);
            if (ppUsd < minBet) revert InvalidAmount();
            if (maxBet != 0 && ppUsd > maxBet) revert AboveMaxBet();
        }
    }

    /// @notice Worst-case net profit for this bet truncated by the per-game USD profit cap,
    /// returned in collateral units. Uncapped worst = 7*ante (ante side excl stake-backs) +
    /// 40*PP. Per-leg settle paths deduct profit_paid from `b.profitCapRemaining`
    function _cappedProfit(address collateral, uint256 anteAmount, uint256 pairPlusAmount) internal view returns (uint256) {
        uint256 worst = anteAmount * (MAX_PAYOUT_ANTE_MULT - 2) + pairPlusAmount * (MAX_PAYOUT_PAIR_PLUS_MULT - 1);
        uint256 capUsd = core.effectiveMaxProfitUsd(address(this));
        uint256 capCollateral = core.collateralFromUsd(collateral, capUsd);
        return worst > capCollateral ? capCollateral : worst;
    }

    /* ========== VIEWS ========== */

    function getBetBase(
        uint256 betId
    )
        external
        view
        override
        returns (
            address user,
            address collateral,
            uint256 anteAmount,
            uint256 pairPlusAmount,
            uint256 totalPayout,
            uint256 placedAt,
            uint256 resolvedAt,
            BetStatus status,
            Outcome outcome
        )
    {
        Bet storage b = bets[betId];
        return (
            b.user,
            b.collateral,
            b.anteAmount,
            b.pairPlusAmount,
            b.totalPayout,
            b.placedAt,
            b.resolvedAt,
            b.status,
            b.outcome
        );
    }

    function getBetCards(
        uint256 betId
    ) external view override returns (uint8[3] memory playerCards, uint8[3] memory dealerCards) {
        Bet storage b = bets[betId];
        return (b.playerCards, b.dealerCards);
    }

    function getBetPayouts(
        uint256 betId
    )
        external
        view
        override
        returns (uint256 pairPlusPayout, uint256 anteBonusPayout, uint256 anteAndPlayPayout, uint256 totalPayout)
    {
        Bet storage b = bets[betId];
        return (b.pairPlusPayout, b.anteBonusPayout, b.anteAndPlayPayout, b.totalPayout);
    }

    function getFullRecord(uint256 betId) external view override returns (FullRecord memory r) {
        Bet storage b = bets[betId];
        r.betId = betId;
        r.user = b.user;
        r.collateral = b.collateral;
        r.anteAmount = b.anteAmount;
        r.pairPlusAmount = b.pairPlusAmount;
        r.totalPayout = b.totalPayout;
        r.pairPlusPayout = b.pairPlusPayout;
        r.anteBonusPayout = b.anteBonusPayout;
        r.anteAndPlayPayout = b.anteAndPlayPayout;
        r.placedAt = b.placedAt;
        r.resolvedAt = b.resolvedAt;
        r.status = b.status;
        r.outcome = b.outcome;
        r.playerCards = b.playerCards;
        r.dealerCards = b.dealerCards;
        r.isFreeBet = b.isFreeBet;
        r.lastRequestAt = b.lastRequestAt;
    }

    function getUserBetIds(address user, uint256 offset, uint256 limit) external view override returns (uint256[] memory) {
        return CasinoHandsLib.getUserBetIds(userBetIds[user], offset, limit);
    }

    function getRecentBetIds(uint256 offset, uint256 limit) external view override returns (uint256[] memory) {
        return CasinoHandsLib.getRecentBetIds(nextBetId, offset, limit);
    }

    /* ========== ADMIN ========== */

    /// @dev AUDIT NOTE: unguarded against repointing to a malicious core. Trusted-owner model;
    /// see HiLo.setCore for rationale
    function setCore(address _core) external onlyOwner {
        if (_core == address(0)) revert InvalidAddress();
        core = ICasinoCoreV2(_core);
    }

    function setManager(address _manager) external onlyOwner {
        if (_manager == address(0)) revert InvalidAddress();
        manager = ISportsAMMV2Manager(_manager);
    }

    function setPausedByRole(bool _paused) external onlyPauser {
        if (paused != _paused) {
            paused = _paused;
            if (_paused) lastPauseTime = block.timestamp;
            emit PauseChanged(_paused);
        }
    }

    /* ========== MODIFIERS ========== */

    function _requireRole(ISportsAMMV2Manager.Role role) internal view {
        if (msg.sender != owner && !manager.isWhitelistedAddress(msg.sender, role)) revert InvalidSender();
    }

    modifier onlyResolver() {
        _requireRole(ISportsAMMV2Manager.Role.MARKET_RESOLVING);
        _;
    }
    modifier onlyPauser() {
        _requireRole(ISportsAMMV2Manager.Role.TICKET_PAUSER);
        _;
    }
}

contracts/core/Casino/VideoPoker.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";

import "../../utils/proxy/ProxyReentrancyGuard.sol";
import "../../utils/proxy/ProxyOwned.sol";
import "../../utils/proxy/ProxyPausable.sol";

import "../../interfaces/ISportsAMMV2Manager.sol";
import "../../interfaces/ICasinoCoreV2.sol";
import "../../interfaces/ICasinoGameCallback.sol";
import "../../interfaces/ICasinoVideoPoker.sol";
import "./CasinoHandsLib.sol";

/// @title VideoPoker
/// @author Overtime
/// @notice Jacks-or-Better Video Poker, "for 1" paytable with FH=8 / Flush=5 / Royal=500,
/// single-coin only. Two-VRF flow:
///   1. placeBet — pulls ante, VRF1 deals 5 cards, status → PLAYER_TURN
///   2. draw(holdMask) — VRF2 deals replacement cards for non-held slots, evaluates, resolves
///
/// Reservation: 500 × stake (Royal Flush = 500-for-1 max payout). RTP under optimal play ≈
/// 96.5% / house edge ≈ 3.5%, between standard 1-coin (Royal=250, 96.15%) and 5-coin
/// (Royal=800, 97.30%) variants. See `_paytableMultiplier` for the locked paytable. Pair-of-
/// Jacks rule is enforced in the multiplier lookup, NOT in the evaluator — the evaluator
/// returns CasinoHandsLib.CLASS_PAIR for any pair and the multiplier discriminates by rank
contract VideoPoker is
    ICasinoVideoPoker,
    ICasinoGameCallback,
    Initializable,
    ProxyOwned,
    ProxyPausable,
    ProxyReentrancyGuard
{
    /* ========== CONSTANTS ========== */

    uint256 public constant MIN_BET_USD = 3e18;

    uint8 private constant DECK_SIZE = 52;
    uint8 private constant HAND_SIZE = 5;
    uint8 private constant HOLD_MASK_MAX = 31; // low 5 bits set

    // Hand-class constants and the 5-card evaluator below use the same numerical encoding as
    // `CasinoHandsLib.CLASS_*` so values can flow through the resolved-hand emit / paytable
    // without translation. Reference the lib's `internal constant`s directly (inlined at compile)
    uint8 private constant RANK_TWO = 2;
    uint8 private constant RANK_JACK = 11;
    uint8 private constant RANK_ACE = 14;

    // 8/5 Jacks-or-Better paytable (multipliers on stake; lose otherwise)
    uint256 private constant MULT_ROYAL_FLUSH = 500;
    uint256 private constant MULT_STRAIGHT_FLUSH = 50;
    uint256 private constant MULT_FOUR_OF_A_KIND = 25;
    uint256 private constant MULT_FULL_HOUSE = 8;
    uint256 private constant MULT_FLUSH = 5;
    uint256 private constant MULT_STRAIGHT = 4;
    uint256 private constant MULT_THREE_OF_A_KIND = 3;
    uint256 private constant MULT_TWO_PAIR = 2;
    uint256 private constant MULT_JACKS_OR_BETTER = 1;

    /// @notice Largest paytable multiplier ("for 1" semantics — totalReturn = stake × mult on win,
    /// 0 on loss, stake-back on JoB push at mult=1). Worst-case payout is `stake × 500` (Royal),
    /// so worst-case net profit reservation is `stake × (MAX_PAYOUT_MULT - 1) = 499 × stake`
    uint256 private constant MAX_PAYOUT_MULT = 500;

    /* ========== ERRORS ========== */

    error InvalidAddress();
    error InvalidSender();
    error InvalidAmount();
    error InvalidCollateral();
    error InvalidHoldMask();
    error AboveMaxBet();
    error BetNotFound();
    error BetNotOwner();
    error InvalidBetStatus();

    /* ========== STRUCTS ========== */

    struct Bet {
        address user;
        address collateral;
        uint256 amount;
        uint256 payout;
        uint256 placedAt;
        uint256 lastRequestAt;
        uint256 resolvedAt;
        uint256 reservation;
        uint256 requestId;
        uint8[5] initialCards; // dealt at VRF1 (HAND_SIZE = 5)
        uint8[5] finalCards; // post-draw final 5 cards (== initialCards if all held)
        BetStatus status;
        HandClass handClass;
        uint8 holdMask; // low 5 bits, set on draw()
        uint256 multiplier;
        // Stake was pulled from FreeBetsHolder via core.useFreeBet instead of core.pullFromUser.
        // Routes payouts back to FBH on resolve / cancel and skips referrer payment on losses
        bool isFreeBet;
        // Remaining net-profit budget for this bet in collateral units. Sized at placeBet from
        // `effectiveMaxProfitUsd × price`. Resolve truncates final payout to stake + this.
        // Appended at end of struct for storage-safe upgrade
        uint256 profitCapRemaining;
    }

    /* ========== STATE ========== */

    ICasinoCoreV2 public core;
    ISportsAMMV2Manager public manager;

    uint256 public nextBetId;

    mapping(uint256 => Bet) internal bets;
    mapping(uint256 => uint256) public requestIdToBetId;
    mapping(address => uint256[]) private userBetIds;

    /* ========== INITIALIZER ========== */

    function initialize(address _owner, address _core, address _manager) external initializer {
        if (_owner == address(0) || _core == address(0) || _manager == address(0)) revert InvalidAddress();
        setOwner(_owner);
        initNonReentrant();
        core = ICasinoCoreV2(_core);
        manager = ISportsAMMV2Manager(_manager);
        nextBetId = 1;
    }

    /* ========== PLACE / DRAW / CANCEL ========== */

    /// @notice Single canonical placeBet. `isFreeBet=true` pulls the stake from FreeBetsHolder,
    /// `false` from the user's wallet. Triggers VRF1 to deal the initial 5 cards. The
    /// `draw(betId, holdMask)` selector is the only mid-game action (VP has no `makeAction`
    /// because there's only one decision to dispatch)
    function placeBet(
        address collateral,
        uint256 amount,
        address referrer,
        bool isFreeBet
    ) external override nonReentrant notPaused returns (uint256 betId, uint256 requestId) {
        return _placeBet(collateral, amount, referrer, isFreeBet);
    }

    function _placeBet(
        address collateral,
        uint256 amount,
        address referrer,
        bool isFreeBet
    ) internal returns (uint256 betId, uint256 requestId) {
        if (amount == 0) revert InvalidAmount();
        if (!core.supportedCollateral(collateral)) revert InvalidCollateral();
        _checkBetSize(collateral, amount);
        uint256 cappedProfit = _cappedProfit(collateral, amount);

        if (isFreeBet) {
            core.useFreeBet(msg.sender, collateral, amount);
        } else {
            core.pullFromUser(msg.sender, collateral, amount);
        }
        if (referrer != address(0)) core.setReferrer(referrer, msg.sender);

        // Reservation = stake + cappedProfit (worst-case capped payout)
        uint256 reservation = amount + cappedProfit;
        core.reserveOrRevert(collateral, reservation);

        requestId = core.requestRandomWords(1);
        betId = nextBetId++;

        Bet storage b = bets[betId];
        b.user = msg.sender;
        b.collateral = collateral;
        b.amount = amount;
        b.placedAt = block.timestamp;
        b.lastRequestAt = block.timestamp;
        b.requestId = requestId;
        b.reservation = reservation;
        b.status = BetStatus.AWAITING_DEAL;
        b.isFreeBet = isFreeBet;
        b.profitCapRemaining = cappedProfit;

        requestIdToBetId[requestId] = betId;
        userBetIds[msg.sender].push(betId);

        emit BetPlaced(betId, requestId, msg.sender, collateral, amount);
    }

    /// @notice Gasless-session entry for the only mid-game action VP has. Other V2 games
    /// expose a `makeAction(uint256, uint8)` dispatcher; VP doesn't need the indirection because
    /// there's only one action to dispatch — the FE's Biconomy session allowlists `draw` directly
    /// @dev AUDIT NOTE: mid-game pause traps in-flight winners (e.g. a user with quads dealt
    /// can't claim until unpause); see HiLo.makeAction rationale
    function draw(uint256 betId, uint8 holdMask) external override nonReentrant notPaused returns (uint256 requestId) {
        return _draw(betId, holdMask);
    }

    function _draw(uint256 betId, uint8 holdMask) internal returns (uint256 requestId) {
        Bet storage b = bets[betId];
        if (b.status == BetStatus.NONE) revert BetNotFound();
        if (b.user != msg.sender) revert BetNotOwner();
        if (b.status != BetStatus.PLAYER_TURN) revert InvalidBetStatus();
        if (holdMask > HOLD_MASK_MAX) revert InvalidHoldMask();

        b.holdMask = holdMask;

        // All-hold short-circuit: final hand == initial deal, VRF2 word would go unused.
        // Resolve inline to save the Chainlink request fee + callback latency. `requestId=0`
        // in the emitted event is the sentinel for "no VRF2; bet resolves in this tx"
        if (holdMask == HOLD_MASK_MAX) {
            for (uint8 i; i < HAND_SIZE; ++i) {
                b.finalCards[i] = b.initialCards[i];
            }
            // Clear b.requestId so the BetResolved emit inside _resolve carries 0, matching
            // the DrawRequested(0) sentinel above. Otherwise indexers correlating
            // DrawRequested.requestId → BetResolved.requestId would mismatch on all-hold
            b.requestId = 0;
            emit DrawRequested(betId, 0, b.user, holdMask);
            _resolve(betId, b);
            return 0;
        }

        requestId = core.requestRandomWords(1);
        b.requestId = requestId;
        b.lastRequestAt = block.timestamp;
        b.status = BetStatus.AWAITING_DRAW;
        requestIdToBetId[requestId] = betId;

        emit DrawRequested(betId, requestId, b.user, holdMask);
    }

    function adminCancelBet(uint256 betId) external override nonReentrant onlyResolver {
        Bet storage b = bets[betId];
        if (b.status == BetStatus.NONE) revert BetNotFound();
        if (b.status == BetStatus.RESOLVED || b.status == BetStatus.CANCELLED) revert InvalidBetStatus();
        _cancelBet(betId, true);
    }

    function _cancelBet(uint256 betId, bool adminCancelled) internal {
        Bet storage b = bets[betId];
        core.releaseReservation(b.collateral, b.reservation);
        b.reservation = 0;
        core.payOut(b.user, b.collateral, b.amount, b.isFreeBet, b.amount);
        // Decrement core's pending-stake counter (stake == refund → zero P&L impact)
        core.recordSettlement(b.collateral, b.amount, b.amount);
        b.payout = b.amount;
        b.status = BetStatus.CANCELLED;
        b.resolvedAt = block.timestamp;
        if (b.requestId != 0) delete requestIdToBetId[b.requestId];
        emit BetCancelled(betId, b.user, b.amount, adminCancelled);
    }

    /* ========== VRF CALLBACK ========== */

    /// @dev `nonReentrant` defends against malicious-token transfer hooks re-entering any of
    /// this contract's mutating entries (placeBet / draw / adminCancelBet) mid-payout for a
    /// double-spend
    function onVrfFulfilled(uint256 requestId, uint256[] calldata randomWords) external override nonReentrant {
        if (msg.sender != address(core)) revert InvalidSender();
        uint256 betId = requestIdToBetId[requestId];
        if (betId == 0) return;
        delete requestIdToBetId[requestId];

        Bet storage b = bets[betId];
        uint256 word = randomWords[0];
        if (b.status == BetStatus.AWAITING_DEAL) {
            _onInitialDealt(betId, b, word);
        } else if (b.status == BetStatus.AWAITING_DRAW) {
            _onDrawDealt(betId, b, word);
        }
        // any other state: stale callback, ignore
    }

    function _onInitialDealt(uint256 betId, Bet storage b, uint256 word) internal {
        uint8[] memory deck = CasinoHandsLib.initDeck(DECK_SIZE, 0);
        CasinoHandsLib.partialFisherYates(deck, HAND_SIZE, word);
        for (uint8 i; i < HAND_SIZE; ++i) {
            b.initialCards[i] = deck[i];
        }
        b.status = BetStatus.PLAYER_TURN;
        emit InitialDealRevealed(betId, b.requestId, b.user, deck[0], deck[1], deck[2], deck[3], deck[4]);
    }

    function _onDrawDealt(uint256 betId, Bet storage b, uint256 word) internal {
        // Build the final 5-card hand: held cards stay in place, others come from the remaining
        // 47-card deck via partial Fisher-Yates
        uint8 holdMask = b.holdMask;
        uint8 needed = HAND_SIZE - CasinoHandsLib.popcount(holdMask);

        uint64 excludeMask;
        for (uint8 i; i < HAND_SIZE; ++i) {
            excludeMask |= uint64(1) << b.initialCards[i];
        }

        uint8 deckSize = DECK_SIZE - HAND_SIZE; // 47
        uint8[] memory deck = CasinoHandsLib.initDeck(deckSize, excludeMask);
        if (needed > 0) {
            CasinoHandsLib.partialFisherYates(deck, needed, word);
        }

        uint8 deckCursor;
        for (uint8 i; i < HAND_SIZE; ++i) {
            if ((holdMask >> i) & 1 == 1) {
                b.finalCards[i] = b.initialCards[i];
            } else {
                b.finalCards[i] = deck[deckCursor];
                ++deckCursor;
            }
        }

        _resolve(betId, b);
    }

    /* ========== RESOLUTION ========== */

    function _resolve(uint256 betId, Bet storage b) internal {
        uint8[5] memory finalCards = b.finalCards;
        (uint8 class_, uint8 primaryRank) = _evaluateFive(finalCards);
        uint256 mult = _paytableMultiplier(class_, primaryRank);
        // "For 1" semantics: mult is the total-return multiplier on stake.
        //   JoB pair (mult=1) → totalReturn = stake (push, no profit)
        //   Two Pair (mult=2) → totalReturn = 2×stake (1× net profit)
        //   Royal (mult=500) → totalReturn = 500×stake (499× net profit)
        //   Loss (mult=0) → totalReturn = 0 (stake forfeit)
        uint256 totalReturn = b.amount * mult;

        // Soft-cap net profit against the per-bet budget
        if (totalReturn > b.amount) {
            uint256 profit = totalReturn - b.amount;
            if (profit > b.profitCapRemaining) profit = b.profitCapRemaining;
            totalReturn = b.amount + profit;
            b.profitCapRemaining -= profit;
        }

        core.releaseReservation(b.collateral, b.reservation);
        b.reservation = 0;

        if (totalReturn > 0) {
            core.payOut(b.user, b.collateral, totalReturn, b.isFreeBet, b.amount);
        }
        core.recordSettlement(b.collateral, b.amount, totalReturn);

        // Skip referrer payment on free bets — user lost no real funds, so no referral fee
        if (totalReturn < b.amount && !b.isFreeBet) {
            core.payReferrer(b.user, b.collateral, b.amount - totalReturn);
        }

        b.handClass = HandClass(class_);
        b.multiplier = mult;
        b.payout = totalReturn;
        b.status = BetStatus.RESOLVED;
        b.resolvedAt = block.timestamp;

        emit BetResolved(
            betId,
            b.requestId,
            b.user,
            b.finalCards[0],
            b.finalCards[1],
            b.finalCards[2],
            b.finalCards[3],
            b.finalCards[4],
            HandClass(class_),
            mult,
            totalReturn
        );
    }

    /// @notice Paytable lookup. `primaryRank` is the rank of the pair (for CasinoHandsLib.CLASS_PAIR only) —
    /// used to apply the Jacks-or-Better cut-off. For other classes it's ignored
    function _paytableMultiplier(uint8 class_, uint8 primaryRank) internal pure returns (uint256) {
        if (class_ == CasinoHandsLib.CLASS_ROYAL_FLUSH) return MULT_ROYAL_FLUSH;
        if (class_ == CasinoHandsLib.CLASS_STRAIGHT_FLUSH) return MULT_STRAIGHT_FLUSH;
        if (class_ == CasinoHandsLib.CLASS_FOUR_OF_A_KIND) return MULT_FOUR_OF_A_KIND;
        if (class_ == CasinoHandsLib.CLASS_FULL_HOUSE) return MULT_FULL_HOUSE;
        if (class_ == CasinoHandsLib.CLASS_FLUSH) return MULT_FLUSH;
        if (class_ == CasinoHandsLib.CLASS_STRAIGHT) return MULT_STRAIGHT;
        if (class_ == CasinoHandsLib.CLASS_THREE_OF_A_KIND) return MULT_THREE_OF_A_KIND;
        if (class_ == CasinoHandsLib.CLASS_TWO_PAIR) return MULT_TWO_PAIR;
        if (class_ == CasinoHandsLib.CLASS_PAIR && primaryRank >= RANK_JACK) return MULT_JACKS_OR_BETTER;
        return 0;
    }

    /* ========== HAND EVALUATION (5-card only) ========== */

    /// @notice Evaluates a 5-card hand. Returns `(class_, primaryRank)` where `primaryRank` is
    /// the rank of the pair when class_ == PAIR (used for the Jacks-or-Better cut-off). For
    /// other classes the returned `primaryRank` is the highest meaningful rank in the hand
    function _evaluateFive(uint8[5] memory cards) internal pure returns (uint8 class_, uint8 primaryRank) {
        uint8[15] memory rankCount;
        uint16 rankMask;
        bool flush = true;
        uint8 suit0 = cards[0] / 13;

        for (uint8 i; i < HAND_SIZE; ++i) {
            uint8 r = (cards[i] % 13) + RANK_TWO;
            ++rankCount[r];
            rankMask |= uint16(1) << r;
            if (cards[i] / 13 != suit0) flush = false;
        }

        uint8 straightTop = CasinoHandsLib.findStraightTop(rankMask);

        if (flush && straightTop > 0) {
            if (straightTop == RANK_ACE) {
                return (CasinoHandsLib.CLASS_ROYAL_FLUSH, RANK_ACE);
            }
            return (CasinoHandsLib.CLASS_STRAIGHT_FLUSH, straightTop);
        }

        // Scan ranks high → low for pairs / trips / quads
        uint8 fourRank;
        uint8 threeRank;
        uint8 firstPair;
        uint8 secondPair;
        for (uint8 step; step < 13; ++step) {
            uint8 r = RANK_ACE - step;
            uint8 c = rankCount[r];
            if (c == 4) {
                fourRank = r;
            } else if (c == 3) {
                threeRank = r;
            } else if (c == 2) {
                if (firstPair == 0) firstPair = r;
                else if (secondPair == 0) secondPair = r;
            }
        }

        if (fourRank > 0) {
            return (CasinoHandsLib.CLASS_FOUR_OF_A_KIND, fourRank);
        }
        if (threeRank > 0 && firstPair > 0) {
            return (CasinoHandsLib.CLASS_FULL_HOUSE, threeRank);
        }
        if (flush) {
            return (CasinoHandsLib.CLASS_FLUSH, RANK_ACE);
        }
        if (straightTop > 0) {
            return (CasinoHandsLib.CLASS_STRAIGHT, straightTop);
        }
        if (threeRank > 0) {
            return (CasinoHandsLib.CLASS_THREE_OF_A_KIND, threeRank);
        }
        if (firstPair > 0 && secondPair > 0) {
            return (CasinoHandsLib.CLASS_TWO_PAIR, firstPair);
        }
        if (firstPair > 0) {
            return (CasinoHandsLib.CLASS_PAIR, firstPair);
        }
        return (CasinoHandsLib.CLASS_HIGH_CARD, 0);
    }

    /* ========== HELPERS ========== */

    /// @notice Deck construction, Fisher-Yates shuffle, 5-card straight detection, and popcount
    /// all live in `CasinoHandsLib` (internal pure, inlined at compile time — no DELEGATECALL,
    /// no separate deployment, no storage). `_evaluateFive` itself stays local because its
    /// return shape (class + primary pair rank for Jacks-or-Better cutoff) is VP-specific

    /* ========== VIEWS ========== */

    function getBetBase(
        uint256 betId
    )
        external
        view
        override
        returns (
            address user,
            address collateral,
            uint256 amount,
            uint256 payout,
            uint256 placedAt,
            uint256 resolvedAt,
            BetStatus status,
            HandClass handClass,
            uint8 holdMask,
            uint256 multiplier
        )
    {
        Bet storage b = bets[betId];
        return (
            b.user,
            b.collateral,
            b.amount,
            b.payout,
            b.placedAt,
            b.resolvedAt,
            b.status,
            b.handClass,
            b.holdMask,
            b.multiplier
        );
    }

    function getBetCards(
        uint256 betId
    ) external view override returns (uint8[5] memory initialCards, uint8[5] memory finalCards) {
        Bet storage b = bets[betId];
        return (b.initialCards, b.finalCards);
    }

    function getFullRecord(uint256 betId) external view override returns (FullRecord memory r) {
        Bet storage b = bets[betId];
        r.betId = betId;
        r.user = b.user;
        r.collateral = b.collateral;
        r.amount = b.amount;
        r.payout = b.payout;
        r.placedAt = b.placedAt;
        r.resolvedAt = b.resolvedAt;
        r.status = b.status;
        r.handClass = b.handClass;
        r.holdMask = b.holdMask;
        r.multiplier = b.multiplier;
        r.initialCards = b.initialCards;
        r.finalCards = b.finalCards;
        r.isFreeBet = b.isFreeBet;
        r.lastRequestAt = b.lastRequestAt;
    }

    function getUserBetIds(address user, uint256 offset, uint256 limit) external view override returns (uint256[] memory) {
        return CasinoHandsLib.getUserBetIds(userBetIds[user], offset, limit);
    }

    function getRecentBetIds(uint256 offset, uint256 limit) external view override returns (uint256[] memory) {
        return CasinoHandsLib.getRecentBetIds(nextBetId, offset, limit);
    }

    /* ========== ADMIN ========== */

    /// @dev AUDIT NOTE: unguarded against repointing to a malicious core. Trusted-owner model;
    /// see HiLo.setCore for rationale
    function setCore(address _core) external onlyOwner {
        if (_core == address(0)) revert InvalidAddress();
        core = ICasinoCoreV2(_core);
    }

    function setManager(address _manager) external onlyOwner {
        if (_manager == address(0)) revert InvalidAddress();
        manager = ISportsAMMV2Manager(_manager);
    }

    function setPausedByRole(bool _paused) external onlyPauser {
        if (paused != _paused) {
            paused = _paused;
            if (_paused) lastPauseTime = block.timestamp;
            emit PauseChanged(_paused);
        }
    }

    function _checkBetSize(address collateral, uint256 amount) internal view {
        uint256 amountUsd = core.getUsdValue(collateral, amount);
        uint256 minBet = core.effectiveMinBetUsd(address(this));
        if (minBet == 0) minBet = MIN_BET_USD;
        if (amountUsd < minBet) revert InvalidAmount();
        uint256 maxBet = core.effectiveMaxBetUsd(address(this));
        if (maxBet != 0 && amountUsd > maxBet) revert AboveMaxBet();
    }

    /// @notice Worst-case net profit for this stake truncated by the per-game USD profit cap,
    /// returned in collateral units. Final payout at resolve is `stake + min(actualProfit, this)`
    function _cappedProfit(address collateral, uint256 amount) internal view returns (uint256) {
        uint256 worst = amount * (MAX_PAYOUT_MULT - 1);
        uint256 capCollateral = core.collateralFromUsd(collateral, core.effectiveMaxProfitUsd(address(this)));
        return worst > capCollateral ? capCollateral : worst;
    }

    /* ========== MODIFIERS ========== */

    function _requireRole(ISportsAMMV2Manager.Role role) internal view {
        if (msg.sender != owner && !manager.isWhitelistedAddress(msg.sender, role)) revert InvalidSender();
    }

    modifier onlyResolver() {
        _requireRole(ISportsAMMV2Manager.Role.MARKET_RESOLVING);
        _;
    }
    modifier onlyPauser() {
        _requireRole(ISportsAMMV2Manager.Role.TICKET_PAUSER);
        _;
    }
}

contracts/core/Data/LiveTradingProcessor.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";

import "../../utils/proxy/ProxyOwned.sol";
import "../../utils/proxy/ProxyPausable.sol";
import "../../interfaces/ILiveTradingProcessor.sol";
import "../../interfaces/ISGPTradingProcessor.sol";
import "../../interfaces/IFreeBetsHolder.sol";

contract LiveTradingProcessorData is Initializable, ProxyOwned, ProxyPausable {
    /* ========== STRUCT VARIABLES ========== */

    struct Leg {
        string gameId;
        uint16 sportId;
        uint16 typeId;
        int24 line;
        uint8 position;
        uint24 playerId;
        uint expectedQuote;
    }

    struct RequestData {
        address user;
        bytes32 requestId;
        address ticketId;
        bool isFulfilled;
        uint timestamp;
        uint maturityTimestamp;
        uint buyInAmount;
        uint expectedPayout;
        uint additionalSlippage;
        address referrer;
        address collateral;
        bool isFreeBet;
        Leg[] legs;
    }

    /* ========== STATE VARIABLES ========== */

    ILiveTradingProcessor public liveTradingProcessor;
    IFreeBetsHolder public freeBetsHolder;
    ISGPTradingProcessor public sgpTradingProcessor;

    function initialize(address _owner, ILiveTradingProcessor _liveTradingProcessor) external initializer {
        setOwner(_owner);
        liveTradingProcessor = _liveTradingProcessor;
    }

    /**
     * @notice Retrieves requests data within a paginated range.
     * @dev Fetches requests data in batches.
     * @param _startIndex The starting index for pagination.
     * @param _pageSize The number of entries to fetch in the current page.
     * @return requestsData Requests data.
     */
    function getRequestsData(uint _startIndex, uint _pageSize) external view returns (RequestData[] memory requestsData) {
        uint requestsSize = liveTradingProcessor.requestCounter();
        uint remaining = requestsSize > _startIndex ? requestsSize - _startIndex : 0;
        uint size = _pageSize > remaining ? remaining : _pageSize;

        requestsData = new RequestData[](size);

        for (uint i = 0; i < size; ++i) {
            uint requestIndex = _startIndex + i;
            bytes32 requestId = liveTradingProcessor.counterToRequestId(requestIndex);
            address requester = liveTradingProcessor.requestIdToRequester(requestId);
            address ticketId = liveTradingProcessor.requestIdToTicketId(requestId);
            uint timestampPerRequest = liveTradingProcessor.timestampPerRequest(requestId);
            bool isFreeBet = requester == address(freeBetsHolder);
            bool isLiveParlay = liveTradingProcessor.requestIdIsParlay(requestId);

            requestsData[i] = isLiveParlay
                ? _processParlayTrade(requestId, requester, ticketId, timestampPerRequest, isFreeBet)
                : _processSingleTrade(requestId, requester, ticketId, timestampPerRequest, isFreeBet);
        }
    }

    /**
     * @notice Retrieves latest live and SGP requests data for a specific user within search range.
     * @dev Fetches latest requests data for a specific user by timestamp from live and SGP requests.
     * @param user The address of the user.
     * @param _batchSize The number of latest requests to iterate.
     * @param _maxSize The max number of requests to fetch for a user.
     * @return requestsData Requests data.
     */
    function getLatestRequestsDataPerUser(
        address user,
        uint _batchSize,
        uint _maxSize
    ) external view returns (RequestData[] memory requestsData) {
        RequestData[] memory live = getLatestLiveRequestsDataPerUser(user, _batchSize, _maxSize);
        RequestData[] memory liveSgp = getLatestLiveSGPRequestsDataPerUser(user, _batchSize, _maxSize);

        uint i = 0;
        uint j = 0;
        uint k = 0;

        uint maxLength = live.length + liveSgp.length;
        if (maxLength > _maxSize) {
            maxLength = _maxSize;
        }

        requestsData = new RequestData[](maxLength);

        while (k < maxLength) {
            if (i < live.length && j < liveSgp.length) {
                if (live[i].timestamp >= liveSgp[j].timestamp) {
                    requestsData[k++] = live[i++];
                } else {
                    requestsData[k++] = liveSgp[j++];
                }
            } else if (i < live.length) {
                requestsData[k++] = live[i++];
            } else if (j < liveSgp.length) {
                requestsData[k++] = liveSgp[j++];
            } else {
                break;
            }
        }
    }

    /**
     * @notice Retrieves latest live requests data for a specific user within search range.
     * @dev Fetches latest requests data for a specific user by iterating all requests backwards inside provided range.
     * @param user The address of the user.
     * @param _batchSize The number of latest requests to iterate.
     * @param _maxSize The max number of requests to fetch for a user.
     * @return requestsData Requests data.
     */
    function getLatestLiveRequestsDataPerUser(
        address user,
        uint _batchSize,
        uint _maxSize
    ) public view returns (RequestData[] memory requestsData) {
        uint count = 0;
        uint requestsSize = liveTradingProcessor.requestCounter();

        uint requestsDataSize = requestsSize < _maxSize ? requestsSize : _maxSize;
        requestsData = new RequestData[](requestsDataSize);

        _batchSize = _batchSize > requestsSize ? 0 : requestsSize - _batchSize;
        // iterate backwards in order to fetch most recent data
        for (uint i = requestsSize; i > _batchSize; --i) {
            bytes32 requestId = liveTradingProcessor.counterToRequestId(i - 1);
            address requester = liveTradingProcessor.requestIdToRequester(requestId);
            address ticketId = liveTradingProcessor.requestIdToTicketId(requestId);
            bool isFreeBet = requester == address(freeBetsHolder);
            if (isFreeBet) {
                requester = freeBetsHolder.ticketToUser(ticketId);
            }
            if (requester != user) continue;

            uint timestampPerRequest = liveTradingProcessor.timestampPerRequest(requestId);
            bool isLiveParlay = liveTradingProcessor.requestIdIsParlay(requestId);

            requestsData[count] = isLiveParlay
                ? _processParlayTrade(requestId, requester, ticketId, timestampPerRequest, isFreeBet)
                : _processSingleTrade(requestId, requester, ticketId, timestampPerRequest, isFreeBet);

            ++count;
            if (count == _maxSize) break;
        }
    }

    /**
     * @notice Retrieves latest live SGP requests data for a specific user within search range.
     * @dev Fetches latest requests data for a specific user by iterating all live SGP requests backwards inside provided range.
     * @param user The address of the user.
     * @param _batchSize The number of latest requests to iterate.
     * @param _maxSize The max number of requests to fetch for a user.
     * @return requestsData Requests data.
     */
    function getLatestLiveSGPRequestsDataPerUser(
        address user,
        uint _batchSize,
        uint _maxSize
    ) public view returns (RequestData[] memory requestsData) {
        uint count = 0;
        uint requestsSize = sgpTradingProcessor.requestCounter();

        uint requestsDataSize = requestsSize < _maxSize ? requestsSize : _maxSize;
        requestsData = new RequestData[](requestsDataSize);

        _batchSize = _batchSize > requestsSize ? 0 : requestsSize - _batchSize;
        // iterate backwards in order to fetch most recent data
        for (uint i = requestsSize; i > _batchSize; --i) {
            bytes32 requestId = sgpTradingProcessor.counterToRequestId(i - 1);
            address requester = sgpTradingProcessor.requestIdToRequester(requestId);
            address ticketId = sgpTradingProcessor.requestIdToTicketId(requestId);
            bool isFreeBet = requester == address(freeBetsHolder);
            if (isFreeBet) {
                requester = freeBetsHolder.ticketToUser(ticketId);
            }
            if (requester != user) continue;

            uint timestampPerRequest = sgpTradingProcessor.timestampPerRequest(requestId);
            ISGPTradingProcessor.SGPTradeData memory sgpTradeData = sgpTradingProcessor.getTradeData(requestId);

            if (sgpTradeData._isLive) {
                Leg[] memory legs = new Leg[](sgpTradeData._tradeData.length);
                for (uint j = 0; j < sgpTradeData._tradeData.length; ++j) {
                    ISportsAMMV2.TradeData memory tradeData = sgpTradeData._tradeData[j];
                    legs[j] = Leg({
                        gameId: bytes32ToString(tradeData.gameId),
                        sportId: tradeData.sportId,
                        typeId: tradeData.typeId,
                        line: tradeData.line,
                        position: tradeData.position,
                        playerId: tradeData.playerId,
                        expectedQuote: 0 // no leg quote for SGP
                    });
                }

                requestsData[count] = RequestData({
                    user: requester,
                    requestId: requestId,
                    ticketId: ticketId,
                    isFulfilled: sgpTradingProcessor.requestIdFulfilled(requestId),
                    timestamp: timestampPerRequest,
                    maturityTimestamp: timestampPerRequest + sgpTradingProcessor.maxAllowedExecutionDelay(),
                    buyInAmount: sgpTradeData._buyInAmount,
                    expectedPayout: sgpTradeData._expectedQuote,
                    additionalSlippage: sgpTradeData._additionalSlippage,
                    referrer: sgpTradeData._referrer,
                    collateral: sgpTradeData._collateral,
                    isFreeBet: isFreeBet,
                    legs: legs
                });

                ++count;
                if (count == _maxSize) break;
            }
        }
    }

    function _processSingleTrade(
        bytes32 _requestId,
        address _requester,
        address _ticketId,
        uint _timestampPerRequest,
        bool _isFreeBet
    ) private view returns (RequestData memory) {
        ILiveTradingProcessor.LiveTradeData memory liveTradeData = liveTradingProcessor.getTradeData(_requestId);

        Leg[] memory legs = new Leg[](1);
        legs[0] = Leg({
            gameId: liveTradeData._gameId,
            sportId: liveTradeData._sportId,
            typeId: liveTradeData._typeId,
            line: liveTradeData._line,
            position: liveTradeData._position,
            playerId: liveTradeData._playerId,
            expectedQuote: liveTradeData._expectedQuote
        });

        return
            RequestData({
                user: _requester,
                requestId: _requestId,
                ticketId: _ticketId,
                isFulfilled: liveTradingProcessor.requestIdFulfilled(_requestId),
                timestamp: _timestampPerRequest,
                maturityTimestamp: _timestampPerRequest + liveTradingProcessor.maxAllowedExecutionDelay(),
                buyInAmount: liveTradeData._buyInAmount,
                expectedPayout: liveTradeData._expectedQuote,
                additionalSlippage: liveTradeData._additionalSlippage,
                referrer: liveTradeData._referrer,
                collateral: liveTradeData._collateral,
                isFreeBet: _isFreeBet,
                legs: legs
            });
    }

    function _processParlayTrade(
        bytes32 _requestId,
        address _requester,
        address _ticketId,
        uint _timestampPerRequest,
        bool _isFreeBet
    ) private view returns (RequestData memory) {
        ILiveTradingProcessor.LiveParlayTradeData memory liveParlayTradeData = liveTradingProcessor.getParlayTradeData(
            _requestId
        );

        Leg[] memory legs = new Leg[](liveParlayTradeData.legs.length);
        for (uint j = 0; j < liveParlayTradeData.legs.length; ++j) {
            ILiveTradingProcessor.LiveParlayLeg memory leg = liveParlayTradeData.legs[j];
            legs[j] = Leg({
                gameId: leg.gameId,
                sportId: leg.sportId,
                typeId: leg.typeId,
                line: leg.line,
                position: leg.position,
                playerId: leg.playerId,
                expectedQuote: leg.expectedLegOdd
            });
        }

        return
            RequestData({
                user: _requester,
                requestId: _requestId,
                ticketId: _ticketId,
                isFulfilled: liveTradingProcessor.requestIdFulfilled(_requestId),
                timestamp: _timestampPerRequest,
                maturityTimestamp: _timestampPerRequest + liveTradingProcessor.maxAllowedExecutionDelay(),
                buyInAmount: liveParlayTradeData.buyInAmount,
                expectedPayout: liveParlayTradeData.expectedPayout,
                additionalSlippage: liveParlayTradeData.additionalSlippage,
                referrer: liveParlayTradeData.referrer,
                collateral: liveParlayTradeData.collateral,
                isFreeBet: _isFreeBet,
                legs: legs
            });
    }

    function setLiveTradingProcessor(ILiveTradingProcessor _liveTradingProcessor) external onlyOwner {
        liveTradingProcessor = _liveTradingProcessor;
        emit LiveTradingProcessorChanged(address(_liveTradingProcessor));
    }

    function setFreeBetsHolder(IFreeBetsHolder _freeBetsHolder) external onlyOwner {
        freeBetsHolder = _freeBetsHolder;
        emit FreeBetsHolderChanged(address(_freeBetsHolder));
    }

    function setSGPTradingProcessor(ISGPTradingProcessor _sgpTradingProcessor) external onlyOwner {
        sgpTradingProcessor = _sgpTradingProcessor;
        emit SGPTradingProcessorChanged(address(_sgpTradingProcessor));
    }

    // Helper function to convert bytes32 to string
    function bytes32ToString(bytes32 _bytes32) internal pure returns (string memory) {
        uint8 i = 0;
        while (i < 32 && _bytes32[i] != 0) {
            i++;
        }
        bytes memory bytesArray = new bytes(i);
        for (uint8 j = 0; j < i; j++) {
            bytesArray[j] = _bytes32[j];
        }
        return string(bytesArray);
    }

    event LiveTradingProcessorChanged(address liveTradingProcessor);
    event FreeBetsHolderChanged(address freeBetsHolder);
    event SGPTradingProcessorChanged(address sgpTradingProcessor);
}

contracts/core/Data/SportsAMMV2Data.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";

import "../../utils/proxy/ProxyOwned.sol";
import "../../utils/proxy/ProxyPausable.sol";
import "../../interfaces/ISportsAMMV2.sol";
import "../../interfaces/ISportsAMMV2RiskManager.sol";
import "../../interfaces/ISportsAMMV2Manager.sol";
import "../../interfaces/ISportsAMMV2ResultManager.sol";
import "../../interfaces/IFreeBetsHolder.sol";
import "./../AMM/Ticket.sol";
import "./SportsAMMV2DataUtils.sol";

contract SportsAMMV2Data is Initializable, ProxyOwned, ProxyPausable {
    /* ========== STRUCT VARIABLES ========== */
    struct SportsAMMParameters {
        uint minBuyInAmount;
        uint maxTicketSize;
        uint maxSupportedAmount;
        uint maxSupportedOdds;
        uint safeBoxFee;
        bool paused;
        uint maxAllowedSystemCombinations;
    }

    enum ResultType {
        Unassigned,
        ExactPosition,
        OverUnder,
        CombinedPositions
    }

    /* ========== STATE VARIABLES ========== */

    ISportsAMMV2 public sportsAMM;

    ISportsAMMV2RiskManager public riskManager;

    SportsAMMV2DataUtils public dataUtils;

    function initialize(address _owner, ISportsAMMV2 _sportsAMM, ISportsAMMV2RiskManager _riskManager) external initializer {
        setOwner(_owner);
        sportsAMM = _sportsAMM;
        riskManager = _riskManager;
    }

    /// @notice roots per game and type (first 16 bytes of the root, left-aligned; zero if unset)
    /// @param _games game IDs
    /// @param _typeIds type IDs, one per game
    function getRootsPerGamesAndTypes(
        bytes32[] calldata _games,
        uint16[] calldata _typeIds
    ) external view returns (bytes32[] memory _roots) {
        uint len = _games.length;
        require(len == _typeIds.length, "Invalid length");
        _roots = new bytes32[](len);
        for (uint i; i < len; ++i) {
            _roots[i] = sportsAMM.rootPerGameAndType(_games[i], _typeIds[i]);
        }
    }

    /**
     * @notice Retrieves the parameters used by the SportsAMM contract.
     * @dev Returns a struct containing various configurable parameters for the SportsAMM.
     * @return A `SportsAMMParameters` struct containing:
     * - `minBuyInAmount`: Minimum buy-in amount.
     * - `maxTicketSize`: Maximum size of a single ticket.
     * - `maxSupportedAmount`: Maximum amount supported by the AMM.
     * - `maxSupportedOdds`: Maximum odds supported by the AMM.
     * - `safeBoxFee`: Fee for the safe box.
     * - `paused`: Whether the SportsAMM is currently paused.
     * - `maxAllowedSystemCombinations`: Maximum allowed system combinations.
     */
    function getSportsAMMParameters() external view returns (SportsAMMParameters memory) {
        return
            SportsAMMParameters(
                riskManager.minBuyInAmount(),
                riskManager.maxTicketSize(),
                riskManager.maxSupportedAmount(),
                riskManager.maxSupportedOdds(),
                sportsAMM.safeBoxFee(),
                sportsAMM.paused(),
                riskManager.maxAllowedSystemCombinations()
            );
    }

    /**
     * @notice Retrieves data for the specified tickets.
     * @dev Fetches ticket information for a given array of ticket addresses.
     * @param ticketsArray An array of ticket addresses to retrieve data for.
     * @return An array of `TicketData` containing details for each ticket.
     */
    function getTicketsData(
        address[] calldata ticketsArray
    ) external view returns (SportsAMMV2DataUtils.TicketData[] memory) {
        require(address(dataUtils) != address(0), "DataUtils not set");
        return dataUtils.getTicketsData(sportsAMM, riskManager, ticketsArray);
    }

    /**
     * @notice Batch-reads per-leg states for multiple tickets.
     * @dev Returns one struct per ticket, each holding its own leg arrays.
     *
     * @param tickets Array of Ticket addresses.
     * @return out Array of TicketLegState (same order as input).
     */
    function getTicketLegStatesBatch(
        address[] calldata tickets
    ) external view returns (SportsAMMV2DataUtils.TicketLegState[] memory out) {
        require(address(dataUtils) != address(0), "DataUtils not set");
        return dataUtils.getTicketLegStatesBatch(tickets);
    }

    /**
     * @notice Retrieves active ticket data for a specific user within a paginated range.
     * @dev Fetches data for active tickets, free bets, and staking proxy tickets.
     * @param user The address of the user.
     * @param _startIndex The starting index for pagination.
     * @param _pageSize The number of entries to fetch in the current page.
     * @return ticketsData Active tickets data.
     * @return freeBetsData Free bets data.
     * @return stakingBettingProxyData Staking proxy tickets data.
     */
    function getActiveTicketsDataPerUser(
        address user,
        uint _startIndex,
        uint _pageSize
    )
        external
        view
        returns (
            SportsAMMV2DataUtils.TicketData[] memory ticketsData,
            SportsAMMV2DataUtils.TicketData[] memory freeBetsData,
            SportsAMMV2DataUtils.TicketData[] memory stakingBettingProxyData
        )
    {
        require(address(dataUtils) != address(0), "DataUtils not set");
        address[] memory freeBetsArray = sportsAMM.freeBetsHolder().getActiveTicketsPerUser(_startIndex, _pageSize, user);
        address[] memory ticketsArray = sportsAMM.manager().getActiveTicketsPerUser(_startIndex, _pageSize, user);
        ticketsData = dataUtils.getTicketsData(sportsAMM, riskManager, ticketsArray);
        freeBetsData = dataUtils.getTicketsData(sportsAMM, riskManager, freeBetsArray);
        // Return empty array for stakingBettingProxyData without making any external calls
        stakingBettingProxyData = new SportsAMMV2DataUtils.TicketData[](0);
    }

    /**
     * @notice Retrieves free bets data for a specific user.
     * @dev Fetches free bets data for a given user and collateral addresses.
     * @param user The address of the user.
     * @param collateralAddresses An array of collateral addresses to retrieve free bets data for.
     * @return freeBetsAmountPerCollateral An array of free bets amounts for each collateral address.
     * @return freeBetsExpiryPerCollateral An array of free bets expiries for each collateral address.
     */
    function getFreeBetsDataPerUser(
        address user,
        address[] calldata collateralAddresses
    ) external view returns (uint[] memory freeBetsAmountPerCollateral, uint[] memory freeBetsExpiryPerCollateral) {
        require(address(dataUtils) != address(0), "DataUtils not set");
        return dataUtils.getFreeBetsDataPerUser(sportsAMM.freeBetsHolder(), user, collateralAddresses);
    }

    /**
     * @notice Retrieves resolved ticket data for a specific user within a paginated range.
     * @dev Fetches data for resolved tickets, free bets, and staking proxy tickets.
     * @param user The address of the user.
     * @param _startIndex The starting index for pagination.
     * @param _pageSize The number of entries to fetch in the current page.
     * @return ticketsData Resolved tickets data.
     * @return freeBetsData Free bets data.
     * @return stakingBettingProxyData Staking proxy tickets data.
     */
    function getResolvedTicketsDataPerUser(
        address user,
        uint _startIndex,
        uint _pageSize
    )
        external
        view
        returns (
            SportsAMMV2DataUtils.TicketData[] memory ticketsData,
            SportsAMMV2DataUtils.TicketData[] memory freeBetsData,
            SportsAMMV2DataUtils.TicketData[] memory stakingBettingProxyData
        )
    {
        require(address(dataUtils) != address(0), "DataUtils not set");

        address[] memory freeBetsArray = sportsAMM.freeBetsHolder().getResolvedTicketsPerUser(_startIndex, _pageSize, user);
        address[] memory ticketsArray = sportsAMM.manager().getResolvedTicketsPerUser(_startIndex, _pageSize, user);
        ticketsData = dataUtils.getTicketsData(sportsAMM, riskManager, ticketsArray);
        freeBetsData = dataUtils.getTicketsData(sportsAMM, riskManager, freeBetsArray);
        // Return empty array for stakingBettingProxyData without making any external calls
        stakingBettingProxyData = new SportsAMMV2DataUtils.TicketData[](0);
    }

    /**
     * @notice Retrieves ticket data for a specific game within a paginated range.
     * @dev Fetches ticket information for tickets associated with the given game ID.
     * @param gameId The ID of the game to retrieve tickets for.
     * @param _startIndex The starting index for pagination.
     * @param _pageSize The number of entries to fetch in the current page.
     * @return An array of `TicketData` containing details for the tickets of the specified game.
     */
    function getTicketsDataPerGame(
        bytes32 gameId,
        uint _startIndex,
        uint _pageSize
    ) external view returns (SportsAMMV2DataUtils.TicketData[] memory) {
        require(address(dataUtils) != address(0), "DataUtils not set");

        ISportsAMMV2Manager manager = sportsAMM.manager();
        uint numOfTicketsPerGame = manager.numOfTicketsPerGame(gameId);
        _pageSize = _pageSize > numOfTicketsPerGame ? numOfTicketsPerGame : _pageSize;
        address[] memory ticketsArray = manager.getTicketsPerGame(_startIndex, _pageSize, gameId);
        return dataUtils.getTicketsData(sportsAMM, riskManager, ticketsArray);
    }

    /**
     * @notice Retrieves active game IDs and their associated tickets within a paginated range.
     * @dev Filters only active game IDs and retrieves tickets for each game ID.
     * @param _gameIds An array of game IDs to filter and process.
     * @param _startIndex The starting index for pagination.
     * @param _pageSize The number of entries to fetch in the current page.
     * @return activeGameIds An array of active game IDs.
     * @return numOfTicketsPerGameId An array of ticket counts for each active game ID.
     * @return ticketsPerGameId A 2D array of ticket addresses for each active game ID.
     */
    function getOnlyActiveGameIdsAndTicketsOf(
        bytes32[] calldata _gameIds,
        uint _startIndex,
        uint _pageSize
    )
        external
        view
        returns (bytes32[] memory activeGameIds, uint[] memory numOfTicketsPerGameId, address[][] memory ticketsPerGameId)
    {
        require(address(dataUtils) != address(0), "DataUtils not set");
        return dataUtils.getOnlyActiveGameIdsAndTicketsOf(sportsAMM.manager(), _gameIds, _startIndex, _pageSize);
    }

    /**
     * @notice Retrieves all active game IDs, type IDs, player IDs, and lines for the specified game IDs within a paginated range.
     * @dev Processes active game IDs and tickets, retrieving unique type IDs, player IDs, and market lines.
     * @param _gameIds An array of game IDs to filter and process.
     * @param _startIndex The starting index for pagination.
     * @param _pageSize The number of game IDs to process in the current page.
     * @return finalTicketsInfo An array of TicketMarketInfo containing active market details for the specified game IDs.
     */
    function getAllActiveGameIdsTypeIdsPlayerIdsLinesForGameIds(
        bytes32[] calldata _gameIds,
        uint _startIndex,
        uint _pageSize
    ) external view returns (SportsAMMV2DataUtils.TicketMarketInfo[] memory finalTicketsInfo) {
        require(address(dataUtils) != address(0), "DataUtils not set");
        return
            dataUtils.getAllActiveGameIdsTypeIdsPlayerIdsLinesForGameIds(
                sportsAMM.manager(),
                _gameIds,
                _startIndex,
                _pageSize
            );
    }

    /**
     * @notice Checks if specified markets are resolved.
     * @dev Determines the resolution status of markets by querying the result manager.
     * @param _gameIds An array of game IDs representing the markets.
     * @param _typeIds An array of type IDs associated with the markets.
     * @param _playerIds An array of player IDs associated with the markets.
     * @param _lines An array of market lines for the specified markets.
     * @return resolvedMarkets An array of booleans indicating whether each market is resolved.
     */
    function areMarketsResolved(
        bytes32[] memory _gameIds,
        uint16[] memory _typeIds,
        uint24[] memory _playerIds,
        int24[] memory _lines
    ) external view returns (bool[] memory resolvedMarkets) {
        ISportsAMMV2ResultManager resultManager = sportsAMM.resultManager();
        ISportsAMMV2.CombinedPosition[] memory combinedPositions = new ISportsAMMV2.CombinedPosition[](0);
        if (_gameIds.length == _typeIds.length && _typeIds.length == _playerIds.length) {
            resolvedMarkets = new bool[](_gameIds.length);
            for (uint i = 0; i < _gameIds.length; ++i) {
                uint8 resultType = resultManager.resultTypePerMarketType(_typeIds[i]);
                if (resultType != uint8(ResultType.CombinedPositions)) {
                    resolvedMarkets[i] = resultManager.isMarketResolved(
                        _gameIds[i],
                        _typeIds[i],
                        _playerIds[i],
                        _lines[i],
                        combinedPositions
                    );
                }
            }
        }
    }

    /**
     * @notice Retrieves the results for the specified markets.
     * @dev Queries the result manager for results based on game, type, and player IDs.
     * @param _gameIds An array of game IDs representing the markets.
     * @param _typeIds An array of type IDs associated with the markets.
     * @param _playerIds An array of player IDs associated with the markets.
     * @return resultsForMarkets A 2D array containing market results for each specified market.
     */
    function getResultsForMarkets(
        bytes32[] memory _gameIds,
        uint16[] memory _typeIds,
        uint24[] memory _playerIds
    ) external view returns (int24[][] memory resultsForMarkets) {
        ISportsAMMV2ResultManager resultManager = sportsAMM.resultManager();
        if (_gameIds.length == _typeIds.length && _typeIds.length == _playerIds.length) {
            resultsForMarkets = new int24[][](_gameIds.length);
            for (uint i; i < _gameIds.length; ++i) {
                resultsForMarkets[i] = resultManager.getResultsPerMarket(_gameIds[i], _typeIds[i], _playerIds[i]);
            }
        }
    }

    /**
     * @notice Retrieves whether SGP trading is enabled for each of the given sport IDs.
     * @dev Queries the risk manager for the SGP enabled flag per sport ID.
     * @param _sportIds An array of sport IDs to check.
     * @return areEnabled An array of booleans indicating whether SGP is enabled for each sport ID.
     */
    function getSgpOnSportIdsEnabled(uint16[] calldata _sportIds) external view returns (bool[] memory areEnabled) {
        areEnabled = new bool[](_sportIds.length);
        for (uint i; i < _sportIds.length; ++i) {
            areEnabled[i] = riskManager.sgpOnSportIdEnabled(_sportIds[i]);
        }
    }

    /**
     * @notice Retrieves the amount spent on specified games.
     * @dev Queries the risk manager for the spent amounts for each game ID.
     * @param _gameIds An array of game IDs to calculate the spent amounts for.
     * @return spentAmounts An array of spent amounts corresponding to each game ID.
     */
    function getSpentOnGames(bytes32[] calldata _gameIds) external view returns (uint[] memory spentAmounts) {
        spentAmounts = new uint[](_gameIds.length);
        for (uint i; i < _gameIds.length; ++i) {
            spentAmounts[i] = riskManager.spentOnGame(_gameIds[i]);
        }
    }

    /**
     * @notice Retrieves the risk amounts for specific market positions.
     * @dev This function queries the risk manager to get the risk per market type and position.
     * @param _gameIds An array of game IDs representing the markets.
     * @param _typeIds An array of type IDs representing the types of the markets.
     * @param _playerIds An array of player IDs associated with the markets.
     * @param _positions An array of positions in the markets.
     * @return riskAmounts An array of risk amounts corresponding to the provided market details.
     */
    function getRiskOnMarkets(
        bytes32[] calldata _gameIds,
        uint[] calldata _typeIds,
        uint[] calldata _playerIds,
        uint[] calldata _positions
    ) external view returns (int[] memory riskAmounts) {
        riskAmounts = new int[](_gameIds.length);
        for (uint i; i < _gameIds.length; ++i) {
            riskAmounts[i] = riskManager.riskPerMarketTypeAndPosition(
                _gameIds[i],
                _typeIds[i],
                _playerIds[i],
                _positions[i]
            );
        }
    }

    /**
     * @notice Calculates max stake and available liquidity for each market+position input.
     * @dev Returns two arrays: maxStake and availableLiquidity, both on decimals matching the default collateral.
     * @param inputs Array of market definitions and odds.
     * @return maxStakes Array of maximum stake values.
     * @return availableLiquidity Array of available risk the house is willing to take.
     */
    function getMaxStakeAndLiquidityBatch(
        SportsAMMV2DataUtils.MarketStakeCalculationInput[] calldata inputs
    ) external view returns (uint[] memory maxStakes, uint[] memory availableLiquidity) {
        require(address(dataUtils) != address(0), "DataUtils not set");
        return dataUtils.getMaxStakeAndLiquidityBatch(riskManager, inputs);
    }

    /**
     * @notice Calculates the caps for specific markets based on their details.
     * @dev This function queries the risk manager to determine the cap to be used for each market.
     * @param _gameIds An array of game IDs representing the markets.
     * @param _sportIds An array of sport IDs associated with the markets.
     * @param _typeIds An array of type IDs representing the types of the markets.
     * @param _maturities An array of maturities (timestamps) for the markets.
     * @return caps An array of cap values corresponding to the provided market details.
     */
    function getCapsPerMarkets(
        bytes32[] calldata _gameIds,
        uint16[] calldata _sportIds,
        uint16[] calldata _typeIds,
        uint[] calldata _maturities
    ) external view returns (uint[] memory caps) {
        caps = new uint[](_gameIds.length);
        for (uint i; i < _gameIds.length; ++i) {
            caps[i] = riskManager.calculateCapToBeUsed(_gameIds[i], _sportIds[i], _typeIds[i], 0, 0, _maturities[i], false);
        }
    }

    /**
     * @notice Returns cashout quote and payout data for a ticket.
     * @dev Delegates to Ticket using approved per-leg odds and settled flags.
     *      Applies cashout fee via multiplier (currently hardcoded).
     * @param ticket Ticket address.
     * @param approvedOddsPerLeg Approved per-leg implied probabilities (1e18).
     * @param isLegSettled Flags indicating whether each leg is settled.
     * @return quote Combined implied probability for cashout.
     * @return payoutAfterFee Cashout payout after fee.
     */
    function getCashoutQuoteAndPayout(
        address ticket,
        uint[] calldata approvedOddsPerLeg,
        bool[] calldata isLegSettled
    ) external view returns (uint quote, uint payoutAfterFee) {
        ISportsAMMV2Manager manager = sportsAMM.manager();
        if (!manager.isTicketPotentiallyCashoutable(ticket) || !manager.isActiveTicket(ticket)) {
            return (0, 0);
        }

        return Ticket(ticket).getCashoutQuoteAndPayout(approvedOddsPerLeg, isLegSettled);
    }

    function setAddresses(ISportsAMMV2 _sportsAMM, ISportsAMMV2RiskManager _riskManager) external onlyOwner {
        sportsAMM = _sportsAMM;
        riskManager = _riskManager;
        emit AddressesUpdated(address(_sportsAMM), address(_riskManager));
    }

    function setDataUtils(SportsAMMV2DataUtils _dataUtils) external onlyOwner {
        dataUtils = _dataUtils;
        emit DataUtilsUpdated(address(_dataUtils));
    }

    event AddressesUpdated(address sportsAMM, address riskManager);
    event DataUtilsUpdated(address dataUtils);
}

contracts/core/Data/SportsAMMV2DataUtils.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "../../interfaces/ISportsAMMV2RiskManager.sol";
import "./../AMM/Ticket.sol";
import "../../interfaces/IFreeBetsHolder.sol";
import "../../interfaces/ISportsAMMV2Manager.sol";
import "../../interfaces/ISportsAMMV2.sol";
import "../../interfaces/ISportsAMMV2ResultManager.sol";

contract SportsAMMV2DataUtils {
    struct TicketLegState {
        address ticket;
        bool[] resolved;
        bool[] voided;
        uint[] marketOdds;
    }

    struct MarketStakeCalculationInput {
        bytes32 gameId;
        uint16 sportId;
        uint16 typeId;
        uint24 playerId;
        int24 line;
        uint maturity;
        bool isLive;
        uint8 position;
        uint odds;
    }

    struct TicketMarketInfo {
        bytes32 gameId;
        uint16 typeId;
        uint24 playerId;
        int24 line;
    }

    struct MarketData {
        bytes32 gameId;
        uint16 sportId;
        uint16 typeId;
        uint maturity;
        int24 line;
        uint24 playerId;
        uint8 position;
        uint odd;
        ISportsAMMV2.CombinedPosition[] combinedPositions;
    }

    struct MarketResult {
        ISportsAMMV2ResultManager.MarketPositionStatus status;
        int24[] results;
    }

    struct TicketData {
        address id;
        MarketData[] marketsData;
        MarketResult[] marketsResult;
        address collateral;
        address ticketOwner;
        uint buyInAmount;
        uint fees;
        uint totalQuote;
        uint numOfMarkets;
        uint expiry;
        uint createdAt;
        bool resolved;
        bool paused;
        bool cancelled;
        bool isLost;
        bool isUserTheWinner;
        bool isExercisable;
        uint finalPayout;
        bool isLive;
        bool isSystem;
        uint8 systemBetDenominator;
        bool isSGP;
        bool cashedOut;
        bool isPotentiallyCashoutable;
    }

    function getTicketLegStatesBatch(address[] calldata tickets) external view returns (TicketLegState[] memory out) {
        uint tLen = tickets.length;
        out = new TicketLegState[](tLen);

        for (uint ti; ti < tLen; ++ti) {
            address ticketAddr = tickets[ti];
            Ticket t = Ticket(ticketAddr);
            uint legs = t.numOfMarkets();

            bool[] memory resolved = new bool[](legs);
            bool[] memory voided = new bool[](legs);
            uint[] memory marketOdds = new uint[](legs);

            for (uint li; li < legs; ++li) {
                resolved[li] = t.isLegResolved(li);
                voided[li] = t.isLegVoided(li);
                marketOdds[li] = t.getMarketOdd(li);
            }

            out[ti] = TicketLegState({ticket: ticketAddr, resolved: resolved, voided: voided, marketOdds: marketOdds});
        }
    }

    function getMaxStakeAndLiquidityBatch(
        ISportsAMMV2RiskManager _riskManager,
        MarketStakeCalculationInput[] calldata inputs
    ) external view returns (uint[] memory maxStakes, uint[] memory availableLiquidity) {
        uint len = inputs.length;
        maxStakes = new uint[](len);
        availableLiquidity = new uint[](len);

        for (uint i; i < len; ++i) {
            maxStakes[i] = _calculateMaxStakeAndLiquidity(_riskManager, inputs[i], availableLiquidity, i);
        }
    }

    function _calculateMaxStakeAndLiquidity(
        ISportsAMMV2RiskManager _riskManager,
        MarketStakeCalculationInput calldata input,
        uint[] memory availableLiquidity,
        uint index
    ) internal view returns (uint maxStake) {
        uint cap = _riskManager.calculateCapToBeUsed(
            input.gameId,
            input.sportId,
            input.typeId,
            input.playerId,
            input.line,
            input.maturity,
            input.isLive
        );

        int available = int(cap) -
            _riskManager.riskPerMarketTypeAndPosition(input.gameId, input.typeId, input.playerId, input.position);

        uint availablePerPosition = available > 0 ? uint(available) : 0;
        availableLiquidity[index] = availablePerPosition;

        uint totalGameCap = _riskManager.calculateTotalRiskOnGame(input.gameId, input.sportId, input.maturity);
        uint spent = _riskManager.spentOnGame(input.gameId);

        if (input.odds > 0 && input.odds < 1e18) {
            uint denominator = 1e18 - input.odds;
            uint availablePerGame = totalGameCap > spent ? totalGameCap - spent : 0;
            uint usableLiquidity = availablePerPosition < availablePerGame ? availablePerPosition : availablePerGame;
            maxStake = (usableLiquidity * input.odds) / denominator;
        }
    }

    function getFreeBetsDataPerUser(
        IFreeBetsHolder freeBetsHolder,
        address user,
        address[] calldata collateralAddresses
    ) external view returns (uint[] memory freeBetsAmountPerCollateral, uint[] memory freeBetsExpiryPerCollateral) {
        uint len = collateralAddresses.length;
        freeBetsAmountPerCollateral = new uint[](len);
        freeBetsExpiryPerCollateral = new uint[](len);

        uint upgradeExpiration = freeBetsHolder.freeBetExpirationUpgrade() + freeBetsHolder.freeBetExpirationPeriod();
        uint timestamp = block.timestamp;

        for (uint i; i < len; ++i) {
            address collateral = collateralAddresses[i];

            freeBetsAmountPerCollateral[i] = freeBetsHolder.balancePerUserAndCollateral(user, collateral);

            uint expiration = freeBetsHolder.freeBetExpiration(user, collateral);
            expiration = expiration == 0 ? upgradeExpiration : expiration;

            freeBetsExpiryPerCollateral[i] = expiration > timestamp ? expiration - timestamp : 0;
        }
    }

    function getOnlyActiveGameIdsAndTicketsOf(
        ISportsAMMV2Manager manager,
        bytes32[] calldata _gameIds,
        uint _startIndex,
        uint _pageSize
    )
        external
        view
        returns (bytes32[] memory activeGameIds, uint[] memory numOfTicketsPerGameId, address[][] memory ticketsPerGameId)
    {
        return _getOnlyActiveGameIdsAndTicketsOf(manager, _gameIds, _startIndex, _pageSize);
    }

    function _getOnlyActiveGameIdsAndTicketsOf(
        ISportsAMMV2Manager manager,
        bytes32[] calldata _gameIds,
        uint _startIndex,
        uint _pageSize
    )
        internal
        view
        returns (bytes32[] memory activeGameIds, uint[] memory numOfTicketsPerGameId, address[][] memory ticketsPerGameId)
    {
        _pageSize = _pageSize > _gameIds.length ? _gameIds.length : _pageSize;
        uint[] memory ticketsPerGame = new uint[](_pageSize);
        uint counter;
        for (uint i = _startIndex; i < _pageSize; ++i) {
            uint numOfTicketsPerGame = manager.numOfTicketsPerGame(_gameIds[i]);
            if (numOfTicketsPerGame > 0) {
                counter++;
                ticketsPerGame[i] = numOfTicketsPerGame;
            }
        }
        activeGameIds = new bytes32[](counter);
        numOfTicketsPerGameId = new uint[](counter);
        ticketsPerGameId = new address[][](counter);
        counter = 0;
        for (uint i; i < _gameIds.length; ++i) {
            if (ticketsPerGame[i] > 0) {
                activeGameIds[counter] = _gameIds[i];
                numOfTicketsPerGameId[counter] = ticketsPerGame[i];
                ticketsPerGameId[counter] = manager.getTicketsPerGame(0, ticketsPerGame[i], _gameIds[i]);
                counter++;
            }
        }
    }

    function getAllActiveGameIdsTypeIdsPlayerIdsLinesForGameIds(
        ISportsAMMV2Manager manager,
        bytes32[] calldata _gameIds,
        uint _startIndex,
        uint _pageSize
    ) external view returns (TicketMarketInfo[] memory finalTicketsInfo) {
        bytes32[] memory activeGameIds;
        uint[] memory numOfTicketsPerGameId;
        address[][] memory ticketsPerGameId;

        (activeGameIds, numOfTicketsPerGameId, ticketsPerGameId) = _getOnlyActiveGameIdsAndTicketsOf(
            manager,
            _gameIds,
            _startIndex,
            _pageSize
        );

        uint matchCounter;
        for (uint i; i < activeGameIds.length; ++i) {
            for (uint j; j < numOfTicketsPerGameId[i]; ++j) {
                matchCounter += Ticket(ticketsPerGameId[i][j]).numOfMarkets();
            }
        }

        TicketMarketInfo[] memory ticketsMarkets = new TicketMarketInfo[](matchCounter);
        matchCounter = 0;

        for (uint i; i < activeGameIds.length; ++i) {
            for (uint j; j < numOfTicketsPerGameId[i]; ++j) {
                Ticket ticket = Ticket(ticketsPerGameId[i][j]);
                uint numOfMarkets = ticket.numOfMarkets();

                for (uint t; t < numOfMarkets; ++t) {
                    (bytes32 gameId, , uint16 typeId, , , int24 line, uint24 playerId, , ) = ticket.markets(t);

                    ticketsMarkets[matchCounter].gameId = gameId;
                    ticketsMarkets[matchCounter].typeId = typeId;
                    ticketsMarkets[matchCounter].playerId = playerId;
                    ticketsMarkets[matchCounter].line = line;
                    ++matchCounter;
                }
            }
        }

        (matchCounter, numOfTicketsPerGameId) = _getUniqueTypeIdsPlayerIds(ticketsMarkets);

        finalTicketsInfo = new TicketMarketInfo[](matchCounter);
        matchCounter = 0;

        for (uint i; i < ticketsMarkets.length; ++i) {
            if (numOfTicketsPerGameId[i] == 1) {
                finalTicketsInfo[matchCounter] = ticketsMarkets[i];
                ++matchCounter;
            }
        }
    }

    function _getUniqueTypeIdsPlayerIds(
        TicketMarketInfo[] memory ticketsMarkets
    ) internal pure returns (uint numOfUniqueMatches, uint[] memory uniqueIndexes) {
        bytes32[] memory uniqueHashes = new bytes32[](ticketsMarkets.length);
        uniqueIndexes = new uint[](ticketsMarkets.length);

        for (uint i; i < ticketsMarkets.length; ++i) {
            bytes32 currentHash = keccak256(abi.encode(ticketsMarkets[i]));
            bool isUnique = true;

            for (uint j; j < numOfUniqueMatches; ++j) {
                if (currentHash == uniqueHashes[j]) {
                    isUnique = false;
                    break;
                }
            }

            if (isUnique) {
                uniqueHashes[numOfUniqueMatches] = currentHash;
                uniqueIndexes[i] = 1;
                ++numOfUniqueMatches;
            }
        }
    }

    function getTicketsData(
        ISportsAMMV2 _sportsAMM,
        ISportsAMMV2RiskManager _riskManager,
        address[] calldata ticketsArray
    ) external view returns (TicketData[] memory) {
        return _getTicketsData(_sportsAMM, _riskManager, ticketsArray);
    }

    function _getTicketsData(
        ISportsAMMV2 _sportsAMM,
        ISportsAMMV2RiskManager _riskManager,
        address[] calldata ticketsArray
    ) internal view returns (TicketData[] memory) {
        TicketData[] memory tickets = new TicketData[](ticketsArray.length);
        ISportsAMMV2Manager manager = _sportsAMM.manager();

        for (uint i; i < ticketsArray.length; ++i) {
            Ticket ticket = Ticket(ticketsArray[i]);

            (MarketData[] memory marketsData, MarketResult[] memory marketsResult) = _getTicketMarketsData(
                _sportsAMM,
                ticket
            );
            (bool isSystem, bool isSGP, bool cashedOut, bool isPotentiallyCashoutable) = _getTicketCashoutData(
                _sportsAMM,
                _riskManager,
                ticket,
                manager
            );

            tickets[i] = _buildTicketData(
                ticketsArray[i],
                ticket,
                marketsData,
                marketsResult,
                isSystem,
                isSGP,
                cashedOut,
                isPotentiallyCashoutable
            );
        }

        return tickets;
    }

    function _getTicketMarketsData(
        ISportsAMMV2 _sportsAMM,
        Ticket ticket
    ) internal view returns (MarketData[] memory marketsData, MarketResult[] memory marketsResult) {
        uint numOfMarkets = ticket.numOfMarkets();
        marketsData = new MarketData[](numOfMarkets);
        marketsResult = new MarketResult[](numOfMarkets);

        for (uint j; j < numOfMarkets; ++j) {
            marketsData[j] = _getMarketData(ticket, j);
            marketsResult[j] = _getMarketResult(_sportsAMM, ticket, j);
        }
    }

    function _getTicketCashoutData(
        ISportsAMMV2 _sportsAMM,
        ISportsAMMV2RiskManager _riskManager,
        Ticket ticket,
        ISportsAMMV2Manager manager
    ) internal view returns (bool isSystem, bool isSGP, bool cashedOut, bool isPotentiallyCashoutable) {
        isSystem = manager.isSystemTicket(address(ticket));
        isSGP = manager.isSGPTicket(address(ticket));

        bool createdAfterCashoutDeploy = manager.isTicketPotentiallyCashoutable(address(ticket));
        address ticketOwner = ticket.ticketOwner();

        if (createdAfterCashoutDeploy) {
            cashedOut = ticket.cashedOut();
        }

        bool passedCashoutCooldown = block.timestamp >= ticket.createdAt() + _riskManager.getCashoutCooldown();

        isPotentiallyCashoutable =
            !ticket.resolved() &&
            !ticket.isTicketLost() &&
            !isSGP &&
            !isSystem &&
            createdAfterCashoutDeploy &&
            passedCashoutCooldown &&
            ticket.totalQuote() > _riskManager.maxSupportedOdds() &&
            ticketOwner != address(_sportsAMM.freeBetsHolder());
    }

    function _buildTicketData(
        address ticketAddress,
        Ticket ticket,
        MarketData[] memory marketsData,
        MarketResult[] memory marketsResult,
        bool isSystem,
        bool isSGP,
        bool cashedOut,
        bool isPotentiallyCashoutable
    ) internal view returns (TicketData memory) {
        return
            TicketData(
                ticketAddress,
                marketsData,
                marketsResult,
                address(ticket.collateral()),
                ticket.ticketOwner(),
                ticket.buyInAmount(),
                ticket.fees(),
                ticket.totalQuote(),
                ticket.numOfMarkets(),
                ticket.expiry(),
                ticket.createdAt(),
                ticket.resolved(),
                ticket.paused(),
                ticket.cancelled(),
                ticket.isTicketLost(),
                ticket.isUserTheWinner(),
                ticket.isTicketExercisable(),
                ticket.finalPayout(),
                ticket.isLive(),
                isSystem,
                isSystem ? ticket.systemBetDenominator() : 0,
                isSGP,
                cashedOut,
                isPotentiallyCashoutable
            );
    }

    function _getMarketData(Ticket ticket, uint marketIndex) internal view returns (MarketData memory) {
        (
            bytes32 gameId,
            uint16 sportId,
            uint16 typeId,
            uint maturity,
            ,
            int24 line,
            uint24 playerId,
            uint8 position,
            uint odd
        ) = ticket.markets(marketIndex);

        ISportsAMMV2.CombinedPosition[] memory combinedPositions = ticket.getCombinedPositions(marketIndex);

        return MarketData(gameId, sportId, typeId, maturity, line, playerId, position, odd, combinedPositions);
    }

    function _getMarketResult(
        ISportsAMMV2 _sportsAMM,
        Ticket ticket,
        uint marketIndex
    ) internal view returns (MarketResult memory) {
        (bytes32 gameId, , uint16 typeId, , , int24 line, uint24 playerId, uint8 position, ) = ticket.markets(marketIndex);
        ISportsAMMV2.CombinedPosition[] memory combinedPositions = ticket.getCombinedPositions(marketIndex);
        ISportsAMMV2ResultManager resultManager = _sportsAMM.resultManager();

        return
            MarketResult(
                resultManager.getMarketPositionStatus(gameId, typeId, playerId, line, position, combinedPositions),
                resultManager.getResultsPerMarket(gameId, typeId, playerId)
            );
    }
}

