// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";

import "../../utils/proxy/ProxyOwned.sol";
import "../../utils/proxy/ProxyPausable.sol";
import "./../LiquidityPool/SportsAMMV2LiquidityPool.sol";

contract SportsAMMV2LiquidityPoolData is Initializable, ProxyOwned, ProxyPausable {
    struct LiquidityPoolData {
        address collateral;
        bool started;
        uint maxAllowedDeposit;
        uint round;
        uint totalDeposited;
        uint minDepositAmount;
        uint maxAllowedUsers;
        uint usersCurrentlyInPool;
        bool canCloseCurrentRound;
        bool paused;
        uint roundLength;
        uint allocationCurrentRound;
        uint lifetimePnl;
        uint roundEndTime;
    }

    struct UserLiquidityPoolData {
        uint balanceCurrentRound;
        uint balanceNextRound;
        bool withdrawalRequested;
        uint withdrawalShare;
    }

    struct RoundTicketsData {
        uint totalTickets;
        uint numOfClosedTickets;
        uint numOfPendingTickets;
        address[] pendingTickets;
    }

    function initialize(address _owner) external initializer {
        setOwner(_owner);
    }

    /// @notice getLiquidityPoolData returns liquidity pool data
    /// @param liquidityPool SportsAMMV2LiquidityPool
    /// @return LiquidityPoolData
    function getLiquidityPoolData(SportsAMMV2LiquidityPool liquidityPool) external view returns (LiquidityPoolData memory) {
        uint round = liquidityPool.round();

        return
            LiquidityPoolData(
                address(liquidityPool.collateral()),
                liquidityPool.started(),
                liquidityPool.maxAllowedDeposit(),
                round,
                liquidityPool.totalDeposited(),
                liquidityPool.minDepositAmount(),
                liquidityPool.maxAllowedUsers(),
                liquidityPool.usersCurrentlyInPool(),
                liquidityPool.canCloseCurrentRound(),
                liquidityPool.paused(),
                liquidityPool.roundLength(),
                liquidityPool.allocationPerRound(round),
                liquidityPool.cumulativeProfitAndLoss(round > 0 ? round - 1 : 0),
                liquidityPool.getRoundEndTime(round)
            );
    }

    /// @notice getUserLiquidityPoolData returns user liquidity pool data
    /// @param liquidityPool SportsAMMV2LiquidityPool
    /// @param user address of the user
    /// @return UserLiquidityPoolData
    function getUserLiquidityPoolData(
        SportsAMMV2LiquidityPool liquidityPool,
        address user
    ) external view returns (UserLiquidityPoolData memory) {
        uint round = liquidityPool.round();

        return
            UserLiquidityPoolData(
                liquidityPool.balancesPerRound(round, user),
                liquidityPool.balancesPerRound(round + 1, user),
                liquidityPool.withdrawalRequested(user),
                liquidityPool.withdrawalShare(user)
            );
    }

    /// @notice getCurrentRoundTicketsData returns current round ticket data
    /// @param liquidityPool SportsAMMV2LiquidityPool
    /// @return RoundTicketsData
    function getCurrentRoundTicketsData(
        SportsAMMV2LiquidityPool liquidityPool
    ) external view returns (RoundTicketsData memory) {
        uint round = liquidityPool.round();
        uint numberOfTradingTickets = liquidityPool.getNumberOfTradingTicketsPerRound(round);
        address[] memory tradingTickets = new address[](numberOfTradingTickets);
        address ticket;
        uint counter;
        for (uint i = 0; i < numberOfTradingTickets; i++) {
            ticket = liquidityPool.tradingTicketsPerRound(round, i);
            if (!liquidityPool.ticketAlreadyExercisedInRound(round, ticket)) {
                tradingTickets[i] = ticket;
                ++counter;
            }
        }
        address[] memory pendingTickets = new address[](counter);
        uint j;
        for (uint i = 0; i < numberOfTradingTickets; i++) {
            if (tradingTickets[i] != address(0) && j < counter) {
                pendingTickets[j] = tradingTickets[i];
                ++j;
            }
        }
        return
            RoundTicketsData(
                numberOfTradingTickets,
                (numberOfTradingTickets - pendingTickets.length),
                pendingTickets.length,
                pendingTickets
            );
    }

    /// @notice getCurrentRoundTickets returns current round tickets
    /// @param liquidityPool SportsAMMV2LiquidityPool
    /// @return tickets
    function getCurrentRoundTickets(
        SportsAMMV2LiquidityPool liquidityPool
    ) external view returns (address[] memory tickets) {
        uint round = liquidityPool.round();
        return _getRoundTickets(liquidityPool, round);
    }

    /// @notice getRoundTickets returns round tickets
    /// @param liquidityPool SportsAMMV2LiquidityPool
    /// @param round round to get tickets for
    /// @return tickets
    function getRoundTickets(
        SportsAMMV2LiquidityPool liquidityPool,
        uint round
    ) external view returns (address[] memory tickets) {
        return _getRoundTickets(liquidityPool, round);
    }

    function _getRoundTickets(
        SportsAMMV2LiquidityPool liquidityPool,
        uint round
    ) internal view returns (address[] memory tickets) {
        uint numberOfTradingTickets = liquidityPool.getNumberOfTradingTicketsPerRound(round);
        tickets = new address[](numberOfTradingTickets);
        for (uint i = 0; i < numberOfTradingTickets; i++) {
            tickets[i] = liquidityPool.tradingTicketsPerRound(round, i);
        }
    }
}

contracts/core/FreeBets/FreeBetsHolder.s.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@thales-dao/contracts/contracts/interfaces/IAddressManager.sol";

import "../../interfaces/ISpeedMarketsAMMCreator.sol";
import "../../interfaces/ISpeedMarketsAMM.sol";
import "../../utils/proxy/ProxyOwned.sol";
import "../../utils/proxy/ProxyPausable.sol";
import "../../utils/proxy/ProxyReentrancyGuard.sol";
import "../../utils/libraries/AddressSetLib.sol";

import "../../interfaces/ISportsAMMV2.sol";
import "../../interfaces/ILiveTradingProcessor.sol";
import "../../interfaces/ISGPTradingProcessor.sol";

import "./../AMM/Ticket.sol";

interface ISpeedMarket {
    function isUserWinner() external view returns (bool);
}

contract FreeBetsHolder is Initializable, ProxyOwned, ProxyPausable, ProxyReentrancyGuard {
    using SafeERC20 for IERC20;
    using AddressSetLib for AddressSetLib.AddressSet;

    // Custom errors
    error UnsupportedCollateral();
    error OnlyCallableFromLiveTradingProcessor();
    error UnknownLiveTicket();
    error InsufficientBalance();
    error OnlyCallableFromSGPTradingProcessor();
    error UnknownSGPTicket();
    error SpeedMarketsAMMCreatorNotSet();
    error DirectionsCannotBeEmpty();
    error CallerNotAllowed();
    error UnknownTicket();
    error UnknownActiveTicket();
    error InvalidAddress();
    error FreeBetExpired();
    error FreeBetNotExpired();
    error UnknownSpeedMarketTicketOwner();
    error OnlyCallableFromSpeedMarketsAMMCreator();

    uint private constant MAX_APPROVAL = type(uint256).max;

    ISportsAMMV2 public sportsAMM;

    ILiveTradingProcessor public liveTradingProcessor;

    mapping(address => mapping(address => uint)) public balancePerUserAndCollateral;

    mapping(address => bool) public supportedCollateral;

    mapping(address => address) public ticketToUser;

    mapping(address => uint) public paidPerTicket;

    mapping(bytes32 => address) public liveRequestsPerUser;

    // stores active tickets per user
    mapping(address => AddressSetLib.AddressSet) internal activeTicketsPerUser;

    // stores resolved tickets per user
    mapping(address => AddressSetLib.AddressSet) internal resolvedTicketsPerUser;

    ISGPTradingProcessor public sgpTradingProcessor;

    mapping(bytes32 => address) public sgpRequestsPerUser;

    mapping(address => mapping(address => uint)) public freeBetExpiration;

    uint public freeBetExpirationPeriod;

    uint public freeBetExpirationUpgrade;

    mapping(address => AddressSetLib.AddressSet) internal usersWithFreeBetPerCollateral;

    IAddressManager public addressManager;

    mapping(bytes32 => address) public speedMarketRequestToUser;

    // stores active speed markets per user
    mapping(address => AddressSetLib.AddressSet) internal activeSpeedMarketsPerUser;

    // stores resolved speed markets per user
    mapping(address => AddressSetLib.AddressSet) internal resolvedSpeedMarketsPerUser;

    // stores active chained speed markets per user
    mapping(address => AddressSetLib.AddressSet) internal activeChainedSpeedMarketsPerUser;

    // stores resolved chained speed markets per user
    mapping(address => AddressSetLib.AddressSet) internal resolvedChainedSpeedMarketsPerUser;

    /// @notice Whether an address is a whitelisted casino contract that can call useFreeBet
    mapping(address => bool) public whitelistedCasino;

    /* ========== CONSTRUCTOR ========== */

    function initialize(address _owner, address _sportsAMMV2, address _liveTradingProcessor) external initializer {
        setOwner(_owner);
        initNonReentrant();
        sportsAMM = ISportsAMMV2(_sportsAMMV2);
        liveTradingProcessor = ILiveTradingProcessor(_liveTradingProcessor);
    }

    /// @notice fund a batch of users with free bets in chosen collateral
    function fundBatch(address[] calldata _users, address _collateral, uint _amountPerUser) external notPaused nonReentrant {
        if (!supportedCollateral[_collateral]) revert UnsupportedCollateral();
        IERC20(_collateral).safeTransferFrom(msg.sender, address(this), _amountPerUser * _users.length);
        for (uint256 index; index < _users.length; ++index) {
            address _user = _users[index];
            _fundUser(_user, _collateral, _amountPerUser, msg.sender);
        }
    }

    /// @notice fund a single user with free bets in chosen collateral
    function fund(address _user, address _collateral, uint _amount) external notPaused nonReentrant {
        if (!supportedCollateral[_collateral]) revert UnsupportedCollateral();
        IERC20(_collateral).safeTransferFrom(msg.sender, address(this), _amount);
        _fundUser(_user, _collateral, _amount, msg.sender);
    }

    /// @notice admin method to unallocate free bet that hasn't been used in a while
    function removeUserFunding(
        address _user,
        address _collateral,
        address _receiver
    ) external notPaused nonReentrant onlyOwner {
        _removeUserFunding(_user, _collateral, _receiver);
    }

    /// @notice Removes expired free bet funds from multiple users and transfers them to the owner
    /// @dev This function can be called by anyone, but only works for funds that have passed their expiration time
    /// @param _users Array of user addresses whose expired funds will be removed
    /// @param _collateral The token address of the collateral to be removed
    function removeExpiredUserFunding(address[] calldata _users, address _collateral) external notPaused nonReentrant {
        for (uint256 index; index < _users.length; ++index) {
            address _user = _users[index];
            if (balancePerUserAndCollateral[_user][_collateral] > 0) {
                if (
                    !((freeBetExpiration[_user][_collateral] > 0 &&
                        freeBetExpiration[_user][_collateral] < block.timestamp) ||
                        (freeBetExpiration[_user][_collateral] == 0 &&
                            freeBetExpirationUpgrade + freeBetExpirationPeriod < block.timestamp))
                ) {
                    revert FreeBetNotExpired();
                }
                _removeUserFunding(_user, _collateral, owner);
            }
        }
    }

    /// @notice admin method to unallocate free bets that aren't used in a while
    function removeUserFundingBatch(
        address[] calldata _users,
        address _collateral,
        address _receiver
    ) external notPaused nonReentrant onlyOwner {
        if (!supportedCollateral[_collateral]) revert UnsupportedCollateral();
        for (uint256 index; index < _users.length; ++index) {
            address _user = _users[index];
            _removeUserFunding(_user, _collateral, _receiver);
        }
    }

    function _removeUserFunding(address _user, address _collateral, address _receiver) internal {
        if (!supportedCollateral[_collateral]) revert UnsupportedCollateral();
        uint _amountRemoved = balancePerUserAndCollateral[_user][_collateral];
        uint currentBalance = IERC20(_collateral).balanceOf(address(this));
        if (_amountRemoved > 0 && currentBalance >= _amountRemoved) {
            IERC20(_collateral).safeTransfer(_receiver, _amountRemoved);
        }
        balancePerUserAndCollateral[_user][_collateral] = 0;
        if (usersWithFreeBetPerCollateral[_collateral].contains(_user)) {
            usersWithFreeBetPerCollateral[_collateral].remove(_user);
        }
        emit UserFundingRemoved(_user, _collateral, _receiver, _amountRemoved);
    }

    /// @notice buy a system bet ticket for a user if he has enough free bet in given collateral
    function tradeSystemBet(
        ISportsAMMV2.TradeData[] calldata _tradeData,
        uint _buyInAmount,
        uint _expectedQuote,
        uint _additionalSlippage,
        address _referrer,
        address _collateral,
        uint8 _systemBetDenominator
    ) external notPaused nonReentrant canTrade(msg.sender, _collateral, _buyInAmount) {
        _trade(_tradeData, _buyInAmount, _expectedQuote, _additionalSlippage, _referrer, _collateral, _systemBetDenominator);
    }

    /// @notice buy a ticket for a user if he has enough free bet in given collateral
    function trade(
        ISportsAMMV2.TradeData[] calldata _tradeData,
        uint _buyInAmount,
        uint _expectedQuote,
        uint _additionalSlippage,
        address _referrer,
        address _collateral
    ) external notPaused nonReentrant canTrade(msg.sender, _collateral, _buyInAmount) {
        _trade(_tradeData, _buyInAmount, _expectedQuote, _additionalSlippage, _referrer, _collateral, 0);
    }

    function _trade(
        ISportsAMMV2.TradeData[] calldata _tradeData,
        uint _buyInAmount,
        uint _expectedQuote,
        uint _additionalSlippage,
        address _referrer,
        address _collateral,
        uint8 _systemBetDenominator
    ) internal {
        balancePerUserAndCollateral[msg.sender][_collateral] -= _buyInAmount;
        address _createdTicket;
        if (_systemBetDenominator > 0) {
            _createdTicket = sportsAMM.tradeSystemBet(
                _tradeData,
                _buyInAmount,
                _expectedQuote,
                _additionalSlippage,
                _referrer,
                _collateral,
                false,
                _systemBetDenominator
            );
        } else {
            _createdTicket = sportsAMM.trade(
                _tradeData,
                _buyInAmount,
                _expectedQuote,
                _additionalSlippage,
                _referrer,
                _collateral,
                false
            );
        }
        ticketToUser[_createdTicket] = msg.sender;
        activeTicketsPerUser[msg.sender].add(_createdTicket);
        emit FreeBetTrade(_createdTicket, _buyInAmount, msg.sender, false);
    }

    /// @notice request a live ticket for a user if he has enough free bet in given collateral
    function tradeLive(
        ILiveTradingProcessor.LiveTradeData calldata _liveTradeData
    ) external notPaused canTrade(msg.sender, _liveTradeData._collateral, _liveTradeData._buyInAmount) {
        bytes32 _requestId = liveTradingProcessor.requestLiveTrade(_liveTradeData);
        liveRequestsPerUser[_requestId] = msg.sender;
        emit FreeBetLiveTradeRequested(msg.sender, _liveTradeData._buyInAmount, _requestId);
    }

    /// @notice request a live parlay ticket for a user if he has enough free bet in given collateral
    function tradeLiveParlay(
        ILiveTradingProcessor.LiveParlayTradeData calldata _liveParlayTradeData
    ) external notPaused canTrade(msg.sender, _liveParlayTradeData.collateral, _liveParlayTradeData.buyInAmount) {
        bytes32 _requestId = liveTradingProcessor.requestLiveParlayTrade(_liveParlayTradeData);
        liveRequestsPerUser[_requestId] = msg.sender;
        emit FreeBetLiveParlayTradeRequested(
            msg.sender,
            _liveParlayTradeData.buyInAmount,
            _requestId,
            uint16(_liveParlayTradeData.legs.length)
        );
    }

    /// @notice confirm a live ticket purchase. As live betting is a 2 step approach, the LiveTradingProcessor needs this method as callback so that the correct amount is deducted from the user's balance
    function confirmLiveTrade(
        bytes32 requestId,
        address _createdTicket,
        uint _buyInAmount,
        address _collateral
    ) external notPaused nonReentrant {
        if (msg.sender != address(liveTradingProcessor)) revert OnlyCallableFromLiveTradingProcessor();

        address _user = liveRequestsPerUser[requestId];
        if (_user == address(0)) revert UnknownLiveTicket();

        if (_collateral == address(0)) {
            _collateral = address(sportsAMM.defaultCollateral());
        }

        if (!supportedCollateral[_collateral]) revert UnsupportedCollateral();
        if (balancePerUserAndCollateral[_user][_collateral] < _buyInAmount) revert InsufficientBalance();

        balancePerUserAndCollateral[_user][_collateral] -= _buyInAmount;
        ticketToUser[_createdTicket] = _user;

        activeTicketsPerUser[_user].add(_createdTicket);

        emit FreeBetTrade(_createdTicket, _buyInAmount, _user, true);
    }

    /// @notice request a sgp ticket for a user if he has enough free bet in given collateral
    function tradeSGP(
        ISGPTradingProcessor.SGPTradeData calldata _sgpTradeData
    ) external notPaused canTrade(msg.sender, _sgpTradeData._collateral, _sgpTradeData._buyInAmount) {
        bytes32 _requestId = sgpTradingProcessor.requestSGPTrade(_sgpTradeData);
        sgpRequestsPerUser[_requestId] = msg.sender;
        emit FreeBetSGPTradeRequested(msg.sender, _sgpTradeData._buyInAmount, _requestId);
    }

    /// @notice confirm a SGP ticket purchase. As SGP betting is a 2 step approach, the SGPradingProcessor needs this method as callback so that the correct amount is deducted from the user's balance
    function confirmSGPTrade(
        bytes32 requestId,
        address _createdTicket,
        uint _buyInAmount,
        address _collateral
    ) external notPaused nonReentrant {
        if (msg.sender != address(sgpTradingProcessor)) revert OnlyCallableFromSGPTradingProcessor();

        address _user = sgpRequestsPerUser[requestId];
        if (_user == address(0)) revert UnknownSGPTicket();

        if (_collateral == address(0)) {
            _collateral = address(sportsAMM.defaultCollateral());
        }

        if (!supportedCollateral[_collateral]) revert UnsupportedCollateral();
        if (balancePerUserAndCollateral[_user][_collateral] < _buyInAmount) revert InsufficientBalance();

        balancePerUserAndCollateral[_user][_collateral] -= _buyInAmount;
        ticketToUser[_createdTicket] = _user;

        activeTicketsPerUser[_user].add(_createdTicket);

        emit FreeBetTrade(_createdTicket, _buyInAmount, _user, true);
    }

    /// @notice create a pending speed market for a user if he has enough free bet in given collateral
    function tradeSpeedMarket(
        ISpeedMarketsAMMCreator.SpeedMarketParams calldata _params
    ) external notPaused nonReentrant canTrade(msg.sender, _params.collateral, _params.buyinAmount) {
        address speedMarketsAMMCreator = addressManager.getAddress("SpeedMarketsAMMCreator");
        if (speedMarketsAMMCreator == address(0)) revert SpeedMarketsAMMCreatorNotSet();

        bytes32 _requestId = ISpeedMarketsAMMCreator(speedMarketsAMMCreator).addPendingSpeedMarket(_params);
        speedMarketRequestToUser[_requestId] = msg.sender;
        emit FreeBetSpeedMarketTradeRequested(
            msg.sender,
            _requestId,
            _params.buyinAmount,
            _params.asset,
            _params.strikeTime,
            _params.direction
        );
    }

    /// @notice create a pending chained speed market for a user if he has enough free bet in given collateral
    function tradeChainedSpeedMarket(
        ISpeedMarketsAMMCreator.ChainedSpeedMarketParams calldata _params
    ) external notPaused nonReentrant canTrade(msg.sender, _params.collateral, _params.buyinAmount) {
        address speedMarketsAMMCreator = addressManager.getAddress("SpeedMarketsAMMCreator");
        if (speedMarketsAMMCreator == address(0)) revert SpeedMarketsAMMCreatorNotSet();
        if (_params.directions.length == 0) revert DirectionsCannotBeEmpty();

        bytes32 _requestId = ISpeedMarketsAMMCreator(speedMarketsAMMCreator).addPendingChainedSpeedMarket(_params);
        speedMarketRequestToUser[_requestId] = msg.sender;
        emit FreeBetChainedSpeedMarketTradeRequested(
            msg.sender,
            _requestId,
            _params.buyinAmount,
            _params.asset,
            _params.timeFrame,
            _params.directions.length
        );
    }

    /// @notice confirm a speed or chained speed market trade. Called by SpeedMarketsAMMCreator as callback
    /// @param requestId the request id of the pending speed market
    /// @param _createdMarket the address of the created speed market
    /// @param _collateral the address of the collateral
    /// @param _buyInAmount the buy in amount
    /// @param _isChainedSpeedMarket true if this is a chained speed market
    function confirmSpeedOrChainedSpeedMarketTrade(
        bytes32 requestId,
        address _createdMarket,
        address _collateral,
        uint _buyInAmount,
        bool _isChainedSpeedMarket
    ) external notPaused nonReentrant {
        address speedMarketsAMMCreator = addressManager.getAddress("SpeedMarketsAMMCreator");
        if (msg.sender != speedMarketsAMMCreator) revert OnlyCallableFromSpeedMarketsAMMCreator();
        if (_collateral == address(0)) {
            ISpeedMarketsAMM speedMarketsAMM = ISpeedMarketsAMM(addressManager.getAddress("SpeedMarketsAMM"));
            _collateral = speedMarketsAMM.sUSD();
        }
        if (!supportedCollateral[_collateral]) revert UnsupportedCollateral();

        address _user = speedMarketRequestToUser[requestId];
        if (_user == address(0)) revert UnknownSpeedMarketTicketOwner();

        if (balancePerUserAndCollateral[_user][_collateral] < _buyInAmount) revert InsufficientBalance();

        balancePerUserAndCollateral[_user][_collateral] -= _buyInAmount;
        ticketToUser[_createdMarket] = _user;
        if (_isChainedSpeedMarket) {
            activeChainedSpeedMarketsPerUser[_user].add(_createdMarket);
        } else {
            activeSpeedMarketsPerUser[_user].add(_createdMarket);
        }

        emit FreeBetSpeedTrade(_createdMarket, _buyInAmount, _user);
    }

    /// @notice callback from sportsAMM on ticket exercize if owner is this contract. The net winnings are sent to users while the freebet amount goes to the contract owner
    /// @param _resolvedTicket the address of the resolved ticket
    function confirmTicketResolved(address _resolvedTicket) external {
        if (msg.sender != address(sportsAMM)) revert CallerNotAllowed();
        address _user = ticketToUser[_resolvedTicket];
        if (_user == address(0)) revert UnknownTicket();
        if (!activeTicketsPerUser[_user].contains(_resolvedTicket)) revert UnknownActiveTicket();

        uint _earned;
        uint _exercized = Ticket(_resolvedTicket).finalPayout();
        IERC20 _collateral = Ticket(_resolvedTicket).collateral();
        uint buyInAmount = Ticket(_resolvedTicket).buyInAmount();
        _earned = _resolveMarket(_user, _collateral, _exercized, buyInAmount);

        activeTicketsPerUser[_user].remove(_resolvedTicket);
        resolvedTicketsPerUser[_user].add(_resolvedTicket);

        emit FreeBetTicketResolved(_resolvedTicket, _user, _earned);
    }

    /// @notice callback from SpeedMarketsAMMResolver on speed market resolution. Net winnings are sent to users while the freebet amount goes to the contract owner
    /// @param _resolvedSpeedMarket the address of the resolved speed market
    /// @param _exercized the amount exercised from the speed market
    /// @param _buyInAmount the original buy in amount
    /// @param _collateral the address of the collateral
    /// @param isChained true if this is a chained speed market
    function confirmSpeedMarketResolved(
        address _resolvedSpeedMarket,
        uint _exercized,
        uint _buyInAmount,
        address _collateral,
        bool isChained
    ) external {
        address speedMarketsAMMResolver = addressManager.getAddress("SpeedMarketsAMMResolver");
        if (msg.sender != speedMarketsAMMResolver) revert CallerNotAllowed();
        address _user = ticketToUser[_resolvedSpeedMarket];
        if (_user == address(0)) revert UnknownTicket();
        uint earned;
        if (ISpeedMarket(_resolvedSpeedMarket).isUserWinner()) {
            earned = _resolveMarket(_user, IERC20(_collateral), _exercized, _buyInAmount);
        }
        if (isChained) {
            if (!activeChainedSpeedMarketsPerUser[_user].contains(_resolvedSpeedMarket)) revert UnknownActiveTicket();

            activeChainedSpeedMarketsPerUser[_user].remove(_resolvedSpeedMarket);
            resolvedChainedSpeedMarketsPerUser[_user].add(_resolvedSpeedMarket);
        } else {
            if (!activeSpeedMarketsPerUser[_user].contains(_resolvedSpeedMarket)) revert UnknownActiveTicket();

            activeSpeedMarketsPerUser[_user].remove(_resolvedSpeedMarket);
            resolvedSpeedMarketsPerUser[_user].add(_resolvedSpeedMarket);
        }

        emit FreeBetSpeedMarketResolved(_resolvedSpeedMarket, _user, earned);
    }

    /// @notice admin method to retrieve stuck funds if needed
    function retrieveFunds(IERC20 _collateral, uint _amount) external onlyOwner {
        _collateral.safeTransfer(msg.sender, _amount);
    }

    /* ========== SETTERS ========== */
    /// @notice add or remove a supported collateral for address
    /// @param _collateral the address of the collateral
    /// @param _supported true if the collateral is supported, false otherwise
    /// @param addressToApprove the address to approve
    function addSupportedCollateral(address _collateral, bool _supported, address addressToApprove) external onlyOwner {
        supportedCollateral[_collateral] = _supported;
        if (_supported) {
            IERC20(_collateral).approve(addressToApprove, MAX_APPROVAL);
        } else {
            IERC20(_collateral).approve(addressToApprove, 0);
        }
        emit CollateralSupportChanged(_collateral, _supported, addressToApprove);
    }

    /* ========== GETTERS ========== */
    /// @notice gets batch of active tickets per user
    /// @param _index start index
    /// @param _pageSize batch size
    /// @param _user to get active tickets for
    /// @return activeTickets
    function getActiveTicketsPerUser(uint _index, uint _pageSize, address _user) external view returns (address[] memory) {
        return activeTicketsPerUser[_user].getPage(_index, _pageSize);
    }

    /// @notice gets batch of active speed markets per user
    /// @param _index start index
    /// @param _pageSize batch size
    /// @param _user to get active speed markets for
    /// @return activeSpeedMarkets
    function getActiveSpeedMarketsPerUser(
        uint _index,
        uint _pageSize,
        address _user
    ) external view returns (address[] memory) {
        return activeSpeedMarketsPerUser[_user].getPage(_index, _pageSize);
    }

    /// @notice gets batch of active chained speed markets per user
    /// @param _index start index
    /// @param _pageSize batch size
    /// @param _user to get active chained speed markets for
    /// @return activeChainedSpeedMarkets
    function getActiveChainedSpeedMarketsPerUser(
        uint _index,
        uint _pageSize,
        address _user
    ) external view returns (address[] memory) {
        return activeChainedSpeedMarketsPerUser[_user].getPage(_index, _pageSize);
    }

    /// @notice gets number of active tickets per user
    /// @param _user to get number of active tickets for
    /// @return numOfActiveTickets
    function numOfActiveTicketsPerUser(address _user) external view returns (uint) {
        return activeTicketsPerUser[_user].elements.length;
    }

    /// @notice gets number of active speed markets per user
    /// @param _user to get number of active speed markets for
    /// @return numOfActiveSpeedMarkets
    function numOfActiveSpeedMarketsPerUser(address _user) external view returns (uint) {
        return activeSpeedMarketsPerUser[_user].elements.length;
    }

    /// @notice gets number of active chained speed markets per user
    /// @param _user to get number of active speed markets for
    /// @return numOfActiveChainedSpeedMarkets
    function numOfActiveChainedSpeedMarketsPerUser(address _user) external view returns (uint) {
        return activeChainedSpeedMarketsPerUser[_user].elements.length;
    }

    /// @notice gets batch of resolved tickets per user
    /// @param _index start index
    /// @param _pageSize batch size
    /// @param _user to get resolved tickets for
    /// @return resolvedTickets
    function getResolvedTicketsPerUser(uint _index, uint _pageSize, address _user) external view returns (address[] memory) {
        return resolvedTicketsPerUser[_user].getPage(_index, _pageSize);
    }

    /// @notice gets batch of resolved speed markets per user
    /// @param _index start index
    /// @param _pageSize batch size
    /// @param _user to get resolved speed markets for
    /// @return resolvedSpeedMarkets
    function getResolvedSpeedMarketsPerUser(
        uint _index,
        uint _pageSize,
        address _user
    ) external view returns (address[] memory) {
        return resolvedSpeedMarketsPerUser[_user].getPage(_index, _pageSize);
    }

    /// @notice gets batch of resolved speed markets per user
    /// @param _index start index
    /// @param _pageSize batch size
    /// @param _user to get resolved speed markets for
    /// @return resolvedSpeedMarkets
    function getResolvedChainedSpeedMarketsPerUser(
        uint _index,
        uint _pageSize,
        address _user
    ) external view returns (address[] memory) {
        return resolvedChainedSpeedMarketsPerUser[_user].getPage(_index, _pageSize);
    }

    /// @notice gets number of resolved tickets per user
    /// @param _user to get number of resolved tickets for
    /// @return numOfResolvedTickets
    function numOfResolvedTicketsPerUser(address _user) external view returns (uint) {
        return resolvedTicketsPerUser[_user].elements.length;
    }

    /// @notice gets number of resolved speed markets per user
    /// @param _user to get number of resolved speed markets for
    /// @return numOfResolvedSpeedMarkets
    function numOfResolvedSpeedMarketsPerUser(address _user) external view returns (uint) {
        return resolvedSpeedMarketsPerUser[_user].elements.length;
    }

    /// @notice gets number of resolved speed markets per user
    /// @param _user to get number of resolved speed markets for
    /// @return numOfResolvedSpeedMarkets
    function numOfResolvedChainedSpeedMarketsPerUser(address _user) external view returns (uint) {
        return resolvedChainedSpeedMarketsPerUser[_user].elements.length;
    }

    /// @notice checks if a free bet is valid
    /// @param _user the address of the user
    /// @param _collateral the address of the collateral
    /// @return isValid true if the free bet is valid, false otherwise
    /// @return timeToExpiration the time to expiration of the free bet, 0 if the free bet is not valid
    function isFreeBetValid(address _user, address _collateral) external view returns (bool isValid, uint timeToExpiration) {
        (isValid, timeToExpiration) = _isFreeBetValidAndTimeToExpiration(_user, _collateral);
    }

    /// @notice get users with free bet per collateral
    /// @param _collateral the address of the collateral
    /// @param _index the start index
    /// @param _pageSize the page size
    /// @return users
    function getUsersWithFreeBetPerCollateral(
        address _collateral,
        uint _index,
        uint _pageSize
    ) external view returns (address[] memory) {
        return usersWithFreeBetPerCollateral[_collateral].getPage(_index, _pageSize);
    }

    /// @notice get number of users with free bet per collateral
    /// @param _collateral the address of the collateral
    /// @return number of users
    function numOfUsersWithFreeBetPerCollateral(address _collateral) external view returns (uint) {
        return usersWithFreeBetPerCollateral[_collateral].elements.length;
    }

    /// @notice Get users with free bet per collateral, the free bet amount, if it's valid and the time to expiration
    /// @param _collateral the address of the collateral
    /// @param _index the start index
    /// @param _pageSize the page size
    /// @return allUsers
    /// @return freeBetAmounts
    /// @return isValid
    /// @return timeToExpiration
    function getUsersFreeBetDataPerCollateral(
        address _collateral,
        uint _index,
        uint _pageSize
    )
        external
        view
        returns (
            address[] memory allUsers,
            uint[] memory freeBetAmounts,
            bool[] memory isValid,
            uint[] memory timeToExpiration
        )
    {
        if (_pageSize > usersWithFreeBetPerCollateral[_collateral].elements.length) {
            _pageSize = usersWithFreeBetPerCollateral[_collateral].elements.length;
        }
        allUsers = new address[](_pageSize);
        isValid = new bool[](_pageSize);
        freeBetAmounts = new uint[](_pageSize);
        timeToExpiration = new uint[](_pageSize);
        for (uint i; i < _pageSize; ++i) {
            address user = usersWithFreeBetPerCollateral[_collateral].elements[_index + i];
            (isValid[i], timeToExpiration[i]) = _isFreeBetValidAndTimeToExpiration(user, _collateral);
            allUsers[i] = user;
            freeBetAmounts[i] = balancePerUserAndCollateral[user][_collateral];
        }
    }

    /* ========== SETTERS ========== */
    /// @notice sets the LiveTradingProcessor contract address
    /// @param _liveTradingProcessor the address of Live Trading Processor contract
    function setLiveTradingProcessor(address _liveTradingProcessor) external onlyOwner {
        if (_liveTradingProcessor == address(0)) revert InvalidAddress();
        liveTradingProcessor = ILiveTradingProcessor(_liveTradingProcessor);
        emit SetLiveTradingProcessor(_liveTradingProcessor);
    }

    /// @notice sets the SGPTradingProcessor contract address
    /// @param _sgpTradingProcessor the address of SGP Trading Processor contract
    function setSGPTradingProcessor(address _sgpTradingProcessor) external onlyOwner {
        if (_sgpTradingProcessor == address(0)) revert InvalidAddress();
        sgpTradingProcessor = ISGPTradingProcessor(_sgpTradingProcessor);
        emit SetSGPTradingProcessor(_sgpTradingProcessor);
    }

    /// @notice sets the Sports AMM contract address
    /// @param _sportsAMM the address of Sports AMM contract
    function setSportsAMM(address _sportsAMM) external onlyOwner {
        if (_sportsAMM == address(0)) revert InvalidAddress();
        sportsAMM = ISportsAMMV2(_sportsAMM);
        emit SetSportsAMM(_sportsAMM);
    }

    /// @notice sets the free bet expiration period
    /// @param _freeBetExpirationPeriod the new free bet expiration period
    function setFreeBetExpirationPeriod(uint _freeBetExpirationPeriod, uint _freeBetExpirationUpgrade) external onlyOwner {
        freeBetExpirationPeriod = _freeBetExpirationPeriod;
        freeBetExpirationUpgrade = _freeBetExpirationUpgrade == 0 ? block.timestamp : _freeBetExpirationUpgrade;
        emit SetFreeBetExpirationPeriod(_freeBetExpirationPeriod, _freeBetExpirationUpgrade);
    }

    /// @notice sets the free bet expiration for a user
    /// @param _user the address of the user
    /// @param _collateral the address of the collateral
    /// @param _freeBetExpiration the new free bet expiration
    function setUserFreeBetExpiration(address _user, address _collateral, uint _freeBetExpiration) external onlyOwner {
        freeBetExpiration[_user][_collateral] = _freeBetExpiration;
    }

    /// @notice sets the users with free bet per collateral
    /// @param _users the addresses of the users
    /// @param _collateral the address of the collateral
    function setUsersWithAlreadyFundedFreeBetPerCollateral(
        address[] calldata _users,
        address _collateral
    ) external onlyOwner {
        for (uint i; i < _users.length; ++i) {
            usersWithFreeBetPerCollateral[_collateral].add(_users[i]);
        }
    }

    /// @notice sets the Address Manager contract address
    /// @param _addressManager the address of Address Manager contract
    function setAddressManager(address _addressManager) external onlyOwner {
        if (_addressManager == address(0)) revert InvalidAddress();
        addressManager = IAddressManager(_addressManager);
        emit SetAddressManager(_addressManager);
    }

    /* ========== INTERNAL FUNCTIONS ========== */

    function _resolveMarket(
        address _user,
        IERC20 _collateral,
        uint _exercized,
        uint _buyInAmount
    ) internal returns (uint earned) {
        if (_exercized > 0) {
            if (_exercized > _buyInAmount) {
                _collateral.safeTransfer(owner, _buyInAmount);
                earned = _exercized - _buyInAmount;
                if (earned > 0) {
                    _collateral.safeTransfer(_user, earned);
                }
            } else {
                balancePerUserAndCollateral[_user][address(_collateral)] += _exercized;
            }
        }
    }

    function _fundUser(address _user, address _collateral, uint _amount, address _sender) internal {
        usersWithFreeBetPerCollateral[_collateral].add(_user);
        balancePerUserAndCollateral[_user][_collateral] += _amount;
        freeBetExpiration[_user][_collateral] = block.timestamp + freeBetExpirationPeriod;
        emit UserFunded(_user, _collateral, _amount, _sender);
    }

    function _isFreeBetValidAndTimeToExpiration(
        address _user,
        address _collateral
    ) internal view returns (bool isValid, uint timeToExpiration) {
        if (supportedCollateral[_collateral] && balancePerUserAndCollateral[_user][_collateral] > 0) {
            uint expirationDate = freeBetExpiration[_user][_collateral] > 0
                ? freeBetExpiration[_user][_collateral]
                : freeBetExpirationUpgrade + freeBetExpirationPeriod;
            isValid = expirationDate > block.timestamp;
            timeToExpiration = isValid ? expirationDate - block.timestamp : 0;
        }
    }

    function _isFreeBetValid(address _user, address _collateral) internal view returns (bool) {
        return
            freeBetExpiration[_user][_collateral] > block.timestamp ||
            (freeBetExpiration[_user][_collateral] == 0 &&
                freeBetExpirationUpgrade + freeBetExpirationPeriod > block.timestamp);
    }

    /* ========== CASINO ========== */

    /// @notice Called by whitelisted casino contracts to consume a user's free bet
    /// @dev Validates balance, expiry, and caller whitelist. Transfers tokens to caller.
    function useFreeBet(address _user, address _collateral, uint _amount) external nonReentrant {
        if (!whitelistedCasino[msg.sender]) revert CallerNotAllowed();
        if (!supportedCollateral[_collateral]) revert UnsupportedCollateral();
        if (balancePerUserAndCollateral[_user][_collateral] < _amount) revert InsufficientBalance();
        if (!_isFreeBetValid(_user, _collateral)) revert FreeBetExpired();

        balancePerUserAndCollateral[_user][_collateral] -= _amount;

        IERC20(_collateral).safeTransfer(msg.sender, _amount);

        emit FreeBetUsedByCasino(_user, _collateral, _amount, msg.sender);
    }

    /// @notice Called by whitelisted casino contracts after a free-bet bet is resolved or cancelled.
    /// @dev Caller must have already transferred `_exercized` of `_collateral` to this contract.
    /// Win (exercized > stake): stake forwarded to owner, profit to user wallet.
    /// Push / cancel (0 < exercized <= stake): user's free-bet balance is credited so it can be reused.
    function confirmCasinoBetResolved(
        address _user,
        address _collateral,
        uint _exercized,
        uint _stake
    ) external nonReentrant {
        if (!whitelistedCasino[msg.sender]) revert CallerNotAllowed();
        if (_exercized == 0) return;

        uint earned;
        if (_exercized > _stake) {
            IERC20(_collateral).safeTransfer(owner, _stake);
            earned = _exercized - _stake;
            if (earned > 0) {
                IERC20(_collateral).safeTransfer(_user, earned);
            }
        } else {
            balancePerUserAndCollateral[_user][_collateral] += _exercized;
        }

        emit CasinoBetResolved(msg.sender, _user, _collateral, _exercized, _stake, earned);
    }

    /// @notice Sets whether an address is a whitelisted casino contract
    function setWhitelistedCasino(address _casino, bool _enabled) external onlyOwner {
        if (_casino == address(0)) revert InvalidAddress();
        whitelistedCasino[_casino] = _enabled;
        emit WhitelistedCasinoChanged(_casino, _enabled);
    }

    /* ========== MODIFIERS ========== */
    modifier canTrade(
        address _user,
        address _collateral,
        uint _amount
    ) {
        if (!supportedCollateral[_collateral]) revert UnsupportedCollateral();
        if (balancePerUserAndCollateral[_user][_collateral] < _amount) revert InsufficientBalance();
        if (!_isFreeBetValid(_user, _collateral)) revert FreeBetExpired();
        _;
    }

    /* ========== EVENTS ========== */
    event SetSportsAMM(address sportsAMM);
    event SetLiveTradingProcessor(address liveTradingProcessor);
    event SetSGPTradingProcessor(address sgpTradingProcessor);
    event SetAddressManager(address addressManager);
    event UserFunded(address user, address collateral, uint amount, address funder);
    event FreeBetTrade(address createdTicket, uint buyInAmount, address user, bool isLive);
    event FreeBetSpeedTrade(address createdSpeedMarket, uint buyInAmount, address user);
    event CollateralSupportChanged(address collateral, bool supported, address addressToApprove);
    event FreeBetTicketResolved(address ticket, address user, uint earned);
    event FreeBetSpeedMarketResolved(address speedMarket, address user, uint earned);
    event FreeBetLiveTradeRequested(address user, uint buyInAmount, bytes32 requestId);
    event FreeBetLiveParlayTradeRequested(address user, uint buyInAmount, bytes32 requestId, uint16 legsCount);
    event FreeBetSGPTradeRequested(address user, uint buyInAmount, bytes32 requestId);
    event FreeBetSpeedMarketTradeRequested(
        address user,
        bytes32 requestId,
        uint buyInAmount,
        bytes32 asset,
        uint64 strikeTime,
        ISpeedMarketsAMMCreator.Direction direction
    );
    event FreeBetChainedSpeedMarketTradeRequested(
        address user,
        bytes32 requestId,
        uint buyInAmount,
        bytes32 asset,
        uint64 timeFrame,
        uint directionsCount
    );
    event UserFundingRemoved(address _user, address _collateral, address _receiver, uint _amount);
    event SetFreeBetExpirationPeriod(uint freeBetExpirationPeriod, uint freeBetExpirationUpgrade);
    event UpdateMaxApprovalSpeedMarketsAMM(address collateral);
    event FreeBetUsedByCasino(address indexed user, address indexed collateral, uint amount, address indexed casino);
    event WhitelistedCasinoChanged(address indexed casino, bool enabled);
    event CasinoBetResolved(
        address indexed casino,
        address indexed user,
        address indexed collateral,
        uint exercized,
        uint stake,
        uint earned
    );
}

contracts/core/LiquidityPool/SportsAMMV2.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts-upgradeable/utils/PausableUpgradeable.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/proxy/Clones.sol";

import "../../utils/proxy/ProxyReentrancyGuard.sol";
import "../../utils/proxy/ProxyOwned.sol";

import "@thales-dao/contracts/contracts/interfaces/IPriceFeed.sol";
import "@thales-dao/contracts/contracts/interfaces/IAddressManager.sol";

import "./SportsAMMV2LiquidityPoolRound.sol";

import "../AMM/Ticket.sol";
import "../../interfaces/ISportsAMMV2Manager.sol";
import "../../interfaces/ISportsAMMV2.sol";
import "../../interfaces/ISportsAMMV2RiskManager.sol";

contract SportsAMMV2LiquidityPool is Initializable, ProxyOwned, PausableUpgradeable, ProxyReentrancyGuard {
    /* ========== CUSTOM ERRORS ========== */

    error LPHasStarted();
    error CantStartWithoutDeposits();
    error CantDepositDirectlyAsDefaultLP();
    error MaxUsersReached();
    error PoolNotStarted();
    error ZeroAmount();
    error AmountExceedsUtilRate();
    error InvalidRound();
    error OnlyDefaultRound();
    error TicketNotInCurrentRound();
    error ArraysLengthsMustMatch();
    error TicketIndexMustBeGreaterThan0();
    error TicketNotFoundInInputArray();
    error InvalidWithdrawalValue();
    error CantCloseRound();
    error RoundClosingNotPrepared();
    error AllUsersProcessed();
    error BatchSizeZero();
    error NotAllUsersProcessed();
    error DefaultLPNotSet();
    error RoundPoolMastercopyNotSet();
    error RoundAlreadyClosed();
    error TicketNotInRound();
    error TicketAlreadyExercised();
    error TicketAlreadyResolved();
    error TicketNotFound();
    error ZeroAddress();
    error CantChangeAfterPoolStart();
    error UtilRateTooHigh();
    error SafeBoxImpactTooHigh();
    error CantDepositDuringWithdrawalRequested();
    error AmountExceedsLPCap();
    error AmountLessThanMinDeposit();
    error WithdrawalAlreadyRequested();
    error NothingToWithdraw();
    error CantWithdrawWhenDepositedForNextRound();
    error OnlyFromAMM();
    error NotAllowedWhenRoundClosingPrepared();
    error InvalidSender();

    /* ========== LIBRARIES ========== */

    using SafeERC20 for IERC20;

    /* ========== STRUCT DEFINITION ========== */

    struct InitParams {
        address _owner;
        address _sportsAMM;
        address _addressManager;
        IERC20 _collateral;
        uint _roundLength;
        uint _maxAllowedDeposit;
        uint _minDepositAmount;
        uint _maxAllowedUsers;
        uint _utilizationRate;
        address _safeBox;
        uint _safeBoxImpact;
        bytes32 _collateralKey;
    }

    /* ========== CONSTANTS ========== */

    uint private constant ONE = 1e18;
    uint private constant ONE_PERCENT = 1e16;
    uint private constant MAX_APPROVAL = type(uint256).max;
    uint private constant MAX_CURSOR_MOVES_PER_BATCH = 1000;
    uint private constant DEFAULT_ROUND = 1;

    /* ========== STATE VARIABLES ========== */

    ISportsAMMV2 public sportsAMM;
    IERC20 public collateral;

    bool public started;

    uint public round;
    uint public roundLength;
    // actually second round, as first one is default for mixed round and never closes
    uint public firstRoundStartTime;

    mapping(uint => address) public roundPools;

    mapping(uint => address[]) public usersPerRound;
    mapping(uint => mapping(address => bool)) public userInRound;
    mapping(uint => mapping(address => uint)) public balancesPerRound;
    mapping(uint => uint) public allocationPerRound;

    mapping(address => bool) public withdrawalRequested;
    mapping(address => uint) public withdrawalShare;

    mapping(uint => address[]) public tradingTicketsPerRound;
    mapping(uint => mapping(address => bool)) public isTradingTicketInARound;
    mapping(uint => mapping(address => bool)) public ticketAlreadyExercisedInRound;
    mapping(address => uint) public roundPerTicket;

    mapping(uint => uint) public profitAndLossPerRound;
    mapping(uint => uint) public cumulativeProfitAndLoss;

    uint public maxAllowedDeposit;
    uint public minDepositAmount;
    uint public maxAllowedUsers;
    uint public usersCurrentlyInPool;

    address public defaultLiquidityProvider;

    address public poolRoundMastercopy;

    uint public totalDeposited;

    bool public roundClosingPrepared;
    uint public usersProcessedInRound;

    uint public utilizationRate;

    address public safeBox;
    uint public safeBoxImpact;

    IAddressManager public addressManager;

    bytes32 public collateralKey;

    mapping(uint => uint) public nextExerciseIndexPerRound;

    /* ========== CONSTRUCTOR ========== */

    function initialize(InitParams calldata params) external initializer {
        setOwner(params._owner);
        initNonReentrant();
        sportsAMM = ISportsAMMV2(params._sportsAMM);
        addressManager = IAddressManager(params._addressManager);

        collateral = params._collateral;
        collateralKey = params._collateralKey;
        roundLength = params._roundLength;

        _setMaxAllowedDeposit(params._maxAllowedDeposit);
        _setMinDepositAmount(params._minDepositAmount);
        _setMaxAllowedUsers(params._maxAllowedUsers);

        _setUtilizationRate(params._utilizationRate);
        _setSafeBoxParams(params._safeBox, params._safeBoxImpact);

        collateral.approve(params._sportsAMM, MAX_APPROVAL);
        round = DEFAULT_ROUND;
    }

    /* ========== EXTERNAL WRITE FUNCTIONS ========== */

    /// @notice start pool and begin round #2
    function start() external onlyOwner {
        if (started) revert LPHasStarted();
        if (allocationPerRound[2] == 0) revert CantStartWithoutDeposits();

        firstRoundStartTime = block.timestamp;
        round = 2;

        address roundPool = _getOrCreateRoundPool(2);
        SportsAMMV2LiquidityPoolRound(roundPool).updateRoundTimes(firstRoundStartTime, getRoundEndTime(2));

        started = true;
        emit PoolStarted();
    }

    /// @notice deposit funds from user into pool for the next round
    /// @param amount value to be deposited
    function deposit(uint amount) external canDeposit(amount) nonReentrant whenNotPaused roundClosingNotPrepared {
        _deposit(amount);
    }

    /// @notice deposit funds from user into pool for the next round
    /// @param amount value to be deposited
    function _deposit(uint amount) internal {
        uint nextRound = round + 1;
        address roundPool = _getOrCreateRoundPool(nextRound);
        collateral.safeTransferFrom(msg.sender, roundPool, amount);

        if (msg.sender == defaultLiquidityProvider) revert CantDepositDirectlyAsDefaultLP();

        // new user enters the pool
        if (balancesPerRound[round][msg.sender] == 0 && balancesPerRound[nextRound][msg.sender] == 0) {
            if (usersCurrentlyInPool >= maxAllowedUsers) revert MaxUsersReached();
            usersPerRound[nextRound].push(msg.sender);
            usersCurrentlyInPool = usersCurrentlyInPool + 1;
        }

        balancesPerRound[nextRound][msg.sender] += amount;

        allocationPerRound[nextRound] += amount;
        totalDeposited += amount;

        emit Deposited(msg.sender, amount, round);
    }

    /// @notice get collateral amount needed for trade and store ticket as trading in the round
    /// @param ticket to trade
    /// @param amount amount to get
    function commitTrade(address ticket, uint amount) external nonReentrant whenNotPaused onlyAMM roundClosingNotPrepared {
        if (!started) revert PoolNotStarted();
        if (amount == 0) revert ZeroAmount();
        uint ticketRound = getTicketRound(ticket);
        roundPerTicket[ticket] = ticketRound;
        address liquidityPoolRound = _getOrCreateRoundPool(ticketRound);
        if (ticketRound == round) {
            collateral.safeTransferFrom(liquidityPoolRound, address(sportsAMM), amount);
            if (
                collateral.balanceOf(liquidityPoolRound) <
                (allocationPerRound[round] - ((allocationPerRound[round] * utilizationRate) / ONE))
            ) revert AmountExceedsUtilRate();
        } else if (ticketRound > round) {
            uint poolBalance = collateral.balanceOf(liquidityPoolRound);
            if (poolBalance >= amount) {
                collateral.safeTransferFrom(liquidityPoolRound, address(sportsAMM), amount);
            } else {
                uint differenceToLPAsDefault = amount - poolBalance;
                _depositAsDefault(differenceToLPAsDefault, liquidityPoolRound, ticketRound);
                collateral.safeTransferFrom(liquidityPoolRound, address(sportsAMM), amount);
            }
        } else {
            if (ticketRound != DEFAULT_ROUND) revert InvalidRound();
            _provideAsDefault(amount);
        }
        tradingTicketsPerRound[ticketRound].push(ticket);
        isTradingTicketInARound[ticketRound][ticket] = true;
    }

    /// @notice Track a default-round ticket without pulling profit from LP.
    ///         AMM sends buyIn to defaultLiquidityProvider for safekeeping.
    /// @param ticket the ticket to track
    /// @param buyInAmount the user's buy-in to deposit into LP
    function commitTradeDeferred(
        address ticket,
        uint buyInAmount
    ) external nonReentrant whenNotPaused onlyAMM roundClosingNotPrepared {
        if (!started) revert PoolNotStarted();
        if (buyInAmount == 0) revert ZeroAmount();
        if (getTicketRound(ticket) != DEFAULT_ROUND) revert OnlyDefaultRound();
        roundPerTicket[ticket] = DEFAULT_ROUND;
        _getOrCreateRoundPool(DEFAULT_ROUND);

        // Take buyIn from AMM and deposit into defaultLiquidityProvider
        collateral.safeTransferFrom(address(sportsAMM), defaultLiquidityProvider, buyInAmount);

        tradingTicketsPerRound[DEFAULT_ROUND].push(ticket);
        isTradingTicketInARound[DEFAULT_ROUND][ticket] = true;
    }

    /// @notice Pull funds from defaultLiquidityProvider to AMM for ticket resolution.
    ///         Only for default-round tickets with deferred collateralization.
    /// @param ticket the ticket being resolved
    /// @param amount the amount to pull from LP to AMM
    function provideForResolution(address ticket, uint amount) external whenNotPaused onlyAMM {
        uint ticketRound = getTicketRound(ticket);
        if (ticketRound != DEFAULT_ROUND) revert OnlyDefaultRound();
        if (amount == 0) revert ZeroAmount();
        collateral.safeTransferFrom(defaultLiquidityProvider, address(sportsAMM), amount);
    }

    /// @notice transfer collateral amount from AMM to LP (ticket liquidity pool round)
    /// @param _ticket to trade
    function transferToPool(address _ticket, uint _amount) external whenNotPaused roundClosingNotPrepared onlyAMM {
        uint ticketRound = getTicketRound(_ticket);

        // if this is a past round, but not the default one, then we send the funds to the current round
        if (ticketRound > DEFAULT_ROUND && ticketRound < round) {
            ticketRound = round;
        }
        if (_amount > 0) {
            address liquidityPoolRound = ticketRound <= DEFAULT_ROUND
                ? defaultLiquidityProvider
                : _getOrCreateRoundPool(ticketRound);
            collateral.safeTransferFrom(address(sportsAMM), liquidityPoolRound, _amount);
        }
        if (isTradingTicketInARound[ticketRound][_ticket]) {
            ticketAlreadyExercisedInRound[ticketRound][_ticket] = true;
        }
    }

    /// @notice migrate ticket to next round
    /// @param _ticket ticket to migrate
    /// @param _newRound new round (0 for next round)
    /// @param _ticketIndexInRound index of ticket in round (use 0 to perform automatic lookup through the round array)
    function migrateTicketToAnotherRound(
        address _ticket,
        uint _newRound,
        uint _ticketIndexInRound
    ) external onlyWhitelistedAddresses(msg.sender) roundClosingNotPrepared {
        uint ticketRound = getTicketRound(_ticket);
        if (ticketRound != round) revert TicketNotInCurrentRound();
        _migrateTicketToNewRound(_ticket, _newRound == 0 ? round + 1 : _newRound, _ticketIndexInRound);
    }

    /// @notice migrate batch of tickets to another round
    /// @param _tickets batch of tickets to migrate
    /// @param _newRound new round (0 for next round)
    /// @param _ticketsIndexInRound index of tickets in round (use 0 to perform automatic lookup through the round array)
    function migrateBatchOfTicketsToAnotherRound(
        address[] memory _tickets,
        uint _newRound,
        uint[] memory _ticketsIndexInRound
    ) external onlyWhitelistedAddresses(msg.sender) roundClosingNotPrepared {
        _newRound = _newRound == 0 ? round + 1 : _newRound;
        if (_ticketsIndexInRound.length == 0) {
            for (uint i; i < _tickets.length; i++) {
                _migrateTicketToNewRound(_tickets[i], _newRound, 0);
            }
        } else {
            if (_tickets.length != _ticketsIndexInRound.length) revert ArraysLengthsMustMatch();
            uint tradingTicketsLength = tradingTicketsPerRound[round].length;
            for (uint i = 0; i < _tickets.length; i++) {
                if (_ticketsIndexInRound[i] == 0) revert TicketIndexMustBeGreaterThan0();
                // check if the ticket index has not been migrated yet
                if (_ticketsIndexInRound[i] < tradingTicketsLength - i) {
                    _migrateTicketToNewRound(_tickets[i], _newRound, _ticketsIndexInRound[i]);
                } else {
                    // if the ticket index has been migrated, find the new index
                    // the new index is one of the ticket indexes in the _ticketsIndexInRound array
                    uint n;
                    bool found = false;
                    while (n < _ticketsIndexInRound.length) {
                        if (tradingTicketsPerRound[round][_ticketsIndexInRound[n]] == _tickets[i]) {
                            found = true;
                            break;
                        }
                        ++n;
                    }
                    if (!found) revert TicketNotFoundInInputArray();
                    _migrateTicketToNewRound(_tickets[i], _newRound, _ticketsIndexInRound[n]);
                }
            }
        }
    }

    /// @notice request withdrawal from the LP
    function withdrawalRequest() external nonReentrant whenNotPaused roundClosingNotPrepared {
        _processWithdrawalRequest(msg.sender);
    }

    /// @notice request withdrawal on behalf of a user (owner only)
    /// @param _user the user to request withdrawal for
    function withdrawalRequestOnBehalf(address _user) external onlyOwner nonReentrant roundClosingNotPrepared {
        _processWithdrawalRequest(_user);
    }

    function _processWithdrawalRequest(address _user) internal {
        _checkCanWithdraw(_user);
        if (totalDeposited > balancesPerRound[round][_user]) {
            totalDeposited -= balancesPerRound[round][_user];
        } else {
            totalDeposited = 0;
        }
        usersCurrentlyInPool = usersCurrentlyInPool - 1;
        withdrawalRequested[_user] = true;
        emit WithdrawalRequested(_user);
    }

    /// @notice request partial withdrawal from the LP
    /// @param _share the percentage the user is wihdrawing from his total deposit
    function partialWithdrawalRequest(uint _share) external nonReentrant whenNotPaused roundClosingNotPrepared {
        _checkCanWithdraw(msg.sender);
        if (_share < ONE_PERCENT * 10 || _share > ONE_PERCENT * 90) revert InvalidWithdrawalValue();

        uint toWithdraw = (balancesPerRound[round][msg.sender] * _share) / ONE;
        if (totalDeposited > toWithdraw) {
            totalDeposited -= toWithdraw;
        } else {
            totalDeposited = 0;
        }

        withdrawalRequested[msg.sender] = true;
        withdrawalShare[msg.sender] = _share;
        emit WithdrawalRequested(msg.sender);
    }

    /// @notice prepare round closing - exercise tickets and ensure there are no tickets left unresolved, handle SB profit and calculate PnL
    function prepareRoundClosing() external nonReentrant whenNotPaused roundClosingNotPrepared {
        // do this first to move the cursor if needed
        exerciseTicketsReadyToBeExercised();

        if (!canCloseCurrentRound()) revert CantCloseRound();

        address roundPool = roundPools[round];
        // final balance is the final amount of collateral in the round pool
        uint currentBalance = collateral.balanceOf(roundPool);

        // send profit reserved for SafeBox if positive round
        if (currentBalance > allocationPerRound[round]) {
            uint safeBoxAmount = ((currentBalance - allocationPerRound[round]) * safeBoxImpact) / ONE;
            collateral.safeTransferFrom(roundPool, safeBox, safeBoxAmount);
            currentBalance = currentBalance - safeBoxAmount;
            emit SafeBoxSharePaid(safeBoxImpact, safeBoxAmount);
        }

        // calculate PnL

        // if no allocation for current round
        if (allocationPerRound[round] == 0) {
            profitAndLossPerRound[round] = 1 ether;
        } else {
            profitAndLossPerRound[round] = (currentBalance * ONE) / allocationPerRound[round];
        }

        roundClosingPrepared = true;

        emit RoundClosingPrepared(round);
    }

    /// @notice process round closing batch - update balances and handle withdrawals
    /// @param _batchSize size of batch
    function processRoundClosingBatch(uint _batchSize) external nonReentrant whenNotPaused {
        if (!roundClosingPrepared) revert RoundClosingNotPrepared();
        if (usersProcessedInRound >= usersPerRound[round].length) revert AllUsersProcessed();
        if (_batchSize == 0) revert BatchSizeZero();

        address roundPool = roundPools[round];

        uint endCursor = usersProcessedInRound + _batchSize;
        if (endCursor > usersPerRound[round].length) {
            endCursor = usersPerRound[round].length;
        }
        for (uint i = usersProcessedInRound; i < endCursor; i++) {
            address user = usersPerRound[round][i];
            uint balanceAfterCurRound = (balancesPerRound[round][user] * profitAndLossPerRound[round]) / ONE;
            if (!withdrawalRequested[user] && (profitAndLossPerRound[round] > 0)) {
                balancesPerRound[round + 1][user] = balancesPerRound[round + 1][user] + balanceAfterCurRound;
                usersPerRound[round + 1].push(user);
            } else {
                if (withdrawalShare[user] > 0) {
                    uint amountToClaim = (balanceAfterCurRound * withdrawalShare[user]) / ONE;
                    collateral.safeTransferFrom(roundPool, user, amountToClaim);
                    emit Claimed(user, amountToClaim);
                    withdrawalRequested[user] = false;
                    withdrawalShare[user] = 0;
                    usersPerRound[round + 1].push(user);
                    balancesPerRound[round + 1][user] = balanceAfterCurRound - amountToClaim;
                } else {
                    balancesPerRound[round + 1][user] = 0;
                    collateral.safeTransferFrom(roundPool, user, balanceAfterCurRound);
                    withdrawalRequested[user] = false;
                    emit Claimed(user, balanceAfterCurRound);
                }
            }
            usersProcessedInRound = usersProcessedInRound + 1;
        }

        emit RoundClosingBatchProcessed(round, _batchSize);
    }

    /// @notice close current round and begin next round - calculate cumulative PnL
    function closeRound() external nonReentrant whenNotPaused {
        if (!roundClosingPrepared) revert RoundClosingNotPrepared();
        if (usersProcessedInRound != usersPerRound[round].length) revert NotAllUsersProcessed();
        // set for next round to false
        roundClosingPrepared = false;

        address roundPool = roundPools[round];

        // always claim for defaultLiquidityProvider
        if (balancesPerRound[round][defaultLiquidityProvider] > 0) {
            uint balanceAfterCurRound = (balancesPerRound[round][defaultLiquidityProvider] * profitAndLossPerRound[round]) /
                ONE;
            collateral.safeTransferFrom(roundPool, defaultLiquidityProvider, balanceAfterCurRound);
            emit Claimed(defaultLiquidityProvider, balanceAfterCurRound);
        }

        if (round == 2) {
            cumulativeProfitAndLoss[round] = profitAndLossPerRound[round];
        } else {
            cumulativeProfitAndLoss[round] = (cumulativeProfitAndLoss[round - 1] * profitAndLossPerRound[round]) / ONE;
        }

        // start next round
        ++round;

        //add all carried over collateral
        allocationPerRound[round] += collateral.balanceOf(roundPool);

        totalDeposited = allocationPerRound[round] - balancesPerRound[round][defaultLiquidityProvider];

        address roundPoolNewRound = _getOrCreateRoundPool(round);

        collateral.safeTransferFrom(roundPool, roundPoolNewRound, collateral.balanceOf(roundPool));

        usersProcessedInRound = 0;

        emit RoundClosed(round - 1, profitAndLossPerRound[round - 1]);
    }

    /// @notice iterate all tickets in the current round and exercise those ready to be exercised
    function exerciseTicketsReadyToBeExercised() public roundClosingNotPrepared whenNotPaused {
        _exerciseTicketsReadyToBeExercised(round);
    }

    /// @notice iterate all tickets in the default round and exercise those ready to be exercised
    function exerciseDefaultRoundTicketsReadyToBeExercised() external whenNotPaused {
        _exerciseTicketsReadyToBeExercised(DEFAULT_ROUND);
    }

    /// @notice iterate all tickets in the current round and exercise those ready to be exercised (batch)
    /// @param _batchSize number of tickets to be processed
    function exerciseTicketsReadyToBeExercisedBatch(
        uint _batchSize
    ) external nonReentrant whenNotPaused roundClosingNotPrepared {
        _exerciseTicketsReadyToBeExercisedBatch(_batchSize, round);
    }

    /// @notice iterate all default round tickets in the current round and exercise those ready to be exercised (batch)
    /// @param _batchSize number of tickets to be processed
    function exerciseDefaultRoundTicketsReadyToBeExercisedBatch(
        uint _batchSize
    ) external nonReentrant whenNotPaused roundClosingNotPrepared {
        _exerciseTicketsReadyToBeExercisedBatch(_batchSize, DEFAULT_ROUND);
    }

    /* ========== EXTERNAL READ FUNCTIONS ========== */

    /// @notice whether the user is currently LPing
    /// @param _user to check
    /// @return isUserInLP whether the user is currently LPing
    function isUserLPing(address _user) external view returns (bool isUserInLP) {
        isUserInLP =
            (balancesPerRound[round][_user] > 0 || balancesPerRound[round + 1][_user] > 0) &&
            (!withdrawalRequested[_user] || withdrawalShare[_user] > 0);
    }

    /// @notice return the price of the pool collateral
    function getCollateralPrice() public view returns (uint) {
        return IPriceFeed(addressManager.getAddress("PriceFeed")).rateForCurrency(collateralKey);
    }

    /// @notice get the pool address for the ticket
    /// @param _ticket to check
    /// @return roundPool the pool address for the ticket
    function getTicketPool(address _ticket) external view returns (address roundPool) {
        roundPool = roundPools[getTicketRound(_ticket)];
    }

    /// @notice checks if all conditions are met to close the round
    /// @return bool
    function canCloseCurrentRound() public view returns (bool) {
        if (!started || block.timestamp < getRoundEndTime(round)) {
            return false;
        }

        Ticket ticket;
        address ticketAddress;

        uint len = tradingTicketsPerRound[round].length;
        uint cursor = nextExerciseIndexPerRound[round];

        for (uint i = cursor; i < len; ++i) {
            ticketAddress = tradingTicketsPerRound[round][i];
            if (!ticketAlreadyExercisedInRound[round][ticketAddress]) {
                ticket = Ticket(ticketAddress);
                if (!ticket.areAllMarketsResolved()) {
                    return false;
                }
            }
        }
        return true;
    }

    /// @notice iterate all tickets in the current round and return true if at least one can be exercised
    /// @return bool
    function hasTicketsReadyToBeExercised() external view returns (bool) {
        return _hasTicketsReadyToBeExercised(round);
    }

    /// @notice iterate all tickets in the default round and return true if at least one can be exercised
    /// @return bool
    function hasDefaultRoundTicketsReadyToBeExercised() external view returns (bool) {
        return _hasTicketsReadyToBeExercised(DEFAULT_ROUND);
    }

    function _hasTicketsReadyToBeExercised(uint _round) internal view returns (bool) {
        Ticket ticket;
        address ticketAddress;

        uint len = tradingTicketsPerRound[_round].length;
        uint cursor = nextExerciseIndexPerRound[_round];

        // Only check from the current cursor onward
        for (uint i = cursor; i < len; i++) {
            ticketAddress = tradingTicketsPerRound[_round][i];
            if (!ticketAlreadyExercisedInRound[_round][ticketAddress]) {
                ticket = Ticket(ticketAddress);
                if (ticket.isTicketExercisable() && !ticket.isUserTheWinner()) {
                    return true;
                }
            }
        }
        return false;
    }

    /// @notice return multiplied PnLs between rounds
    /// @param _roundA round number from
    /// @param _roundB round number to
    /// @return uint
    function cumulativePnLBetweenRounds(uint _roundA, uint _roundB) public view returns (uint) {
        return (cumulativeProfitAndLoss[_roundB] * profitAndLossPerRound[_roundA]) / cumulativeProfitAndLoss[_roundA];
    }

    /// @notice return the start time of the passed round
    /// @param _round number
    /// @return uint the start time of the given round
    function getRoundStartTime(uint _round) public view returns (uint) {
        return firstRoundStartTime + (_round - 2) * roundLength;
    }

    /// @notice return the end time of the passed round
    /// @param _round number
    /// @return uint the end time of the given round
    function getRoundEndTime(uint _round) public view returns (uint) {
        return firstRoundStartTime + (_round - 1) * roundLength;
    }

    /// @notice return the round to which a ticket belongs to
    /// @param _ticket to get the round for
    /// @return ticketRound the min round which the ticket belongs to
    function getTicketRound(address _ticket) public view returns (uint ticketRound) {
        ticketRound = roundPerTicket[_ticket];
        if (ticketRound == 0) {
            Ticket ticket = Ticket(_ticket);
            ISportsAMMV2RiskManager rm = ISportsAMMV2RiskManager(addressManager.getAddress("SportsAMMV2RiskManager"));
            uint numOfMarkets = ticket.numOfMarkets();

            // High-quote multi-leg tickets (parlays and system bets) always go to the default round
            uint threshold = rm.defaultRoundHighQuoteThreshold();
            if (threshold > 0 && numOfMarkets > 1 && ticket.totalQuote() < threshold) {
                ticketRound = DEFAULT_ROUND;
            } else {
                uint maturity;
                uint16 sportId;

                for (uint i = 0; i < numOfMarkets; i++) {
                    (, sportId, , maturity, , , , , ) = ticket.markets(i);
                    bool isFuture = rm.isSportIdFuture(sportId);
                    if (maturity > firstRoundStartTime && !isFuture) {
                        if (i == 0) {
                            ticketRound = (maturity - firstRoundStartTime) / roundLength + 2;
                        } else {
                            // if ticket is cross rounds, use the default round
                            if (((maturity - firstRoundStartTime) / roundLength + 2) != ticketRound) {
                                ticketRound = DEFAULT_ROUND;
                                break;
                            }
                        }
                    } else {
                        ticketRound = DEFAULT_ROUND;
                        break;
                    }
                }
            }
        }
    }

    /// @notice return the count of users in current round
    /// @return uint the count of users in current round
    function getUsersCountInCurrentRound() external view returns (uint) {
        return usersPerRound[round].length;
    }

    /// @notice return the number of tickets in current rount
    /// @return numOfTickets the number of tickets in urrent rount
    function getNumberOfTradingTicketsPerRound(uint _round) external view returns (uint numOfTickets) {
        numOfTickets = tradingTicketsPerRound[_round].length;
    }

    /// @notice Get the index of a ticket in a specific round's trading tickets array
    /// @param _ticket The address of the ticket to find
    /// @param _round The round number to search in
    /// @param _startIndex The starting index to search from
    /// @param _endIndex The ending index to search until
    /// @return index The index of the ticket if found, otherwise returns _endIndex
    /// @return found Whether the ticket was found
    function getTicketIndexInTicketRound(
        address _ticket,
        uint _round,
        uint _startIndex,
        uint _endIndex
    ) external view returns (uint index, bool found) {
        uint finalIndex = tradingTicketsPerRound[_round].length > _endIndex
            ? _endIndex
            : tradingTicketsPerRound[_round].length;
        for (uint i = _startIndex; i < finalIndex; ++i) {
            if (tradingTicketsPerRound[_round][i] == _ticket) {
                return (i, true);
            }
        }
        return (_endIndex, false);
    }

    /* ========== INTERNAL FUNCTIONS ========== */

    function _exerciseTicketsReadyToBeExercisedBatch(uint _batchSize, uint _roundNumber) internal {
        if (_batchSize == 0) revert BatchSizeZero();

        uint len = tradingTicketsPerRound[_roundNumber].length;
        uint cursor = nextExerciseIndexPerRound[_roundNumber];
        uint cursorMoves;

        // 0) Pre-compaction: skip already exercised tickets, up to 1000 moves
        while (
            cursor < len &&
            ticketAlreadyExercisedInRound[_roundNumber][tradingTicketsPerRound[_roundNumber][cursor]] &&
            cursorMoves < MAX_CURSOR_MOVES_PER_BATCH
        ) {
            unchecked {
                ++cursor;
                ++cursorMoves;
            }
        }

        // ✅ Early exit if we spent this batch just moving the cursor
        if (cursorMoves >= MAX_CURSOR_MOVES_PER_BATCH) {
            nextExerciseIndexPerRound[_roundNumber] = cursor;
            return;
        }

        uint processed;

        // 1) Process at most _batchSize *exercised* tickets starting from the current cursor
        for (uint i = cursor; i < len && processed < _batchSize; ++i) {
            if (_exerciseTicket(_roundNumber, tradingTicketsPerRound[_roundNumber][i])) {
                unchecked {
                    ++processed;
                }
            }
        }

        // 2) Post-compaction: move cursor again, up to the same remaining allowance
        while (
            cursor < len &&
            ticketAlreadyExercisedInRound[_roundNumber][tradingTicketsPerRound[_roundNumber][cursor]] &&
            cursorMoves < MAX_CURSOR_MOVES_PER_BATCH
        ) {
            unchecked {
                ++cursor;
                ++cursorMoves;
            }
        }

        nextExerciseIndexPerRound[_roundNumber] = cursor;
    }

    function _exerciseTicketsReadyToBeExercised(uint _roundNumber) internal {
        uint len = tradingTicketsPerRound[_roundNumber].length;
        uint cursor = nextExerciseIndexPerRound[_roundNumber];

        // 0) Pre-compaction: skip over any tickets that were marked exercised
        // since last time (e.g. via transferToPool or batch calls)
        while (cursor < len && ticketAlreadyExercisedInRound[_roundNumber][tradingTicketsPerRound[_roundNumber][cursor]]) {
            unchecked {
                ++cursor;
            }
        }

        // 1) Process from the (updated) cursor onward
        for (uint i = cursor; i < len; ++i) {
            _exerciseTicket(_roundNumber, tradingTicketsPerRound[_roundNumber][i]);
        }

        // 2) Post-compaction: some tickets starting at `cursor` may now be exercised;
        // move cursor forward over that newly-exercised prefix.
        while (cursor < len && ticketAlreadyExercisedInRound[_roundNumber][tradingTicketsPerRound[_roundNumber][cursor]]) {
            unchecked {
                ++cursor;
            }
        }

        nextExerciseIndexPerRound[_roundNumber] = cursor;
    }

    function _exerciseTicket(uint _roundNumber, address ticketAddress) internal returns (bool exercised) {
        if (!ticketAlreadyExercisedInRound[_roundNumber][ticketAddress]) {
            Ticket ticket = Ticket(ticketAddress);
            bool isWinner = ticket.isUserTheWinner();

            bool isSystemExercisable = false;
            bool isSystem = false;
            if (_roundNumber > 1) {
                isSystem = ticket.isSystem();
            }
            // in case round needs to be closed, ensure all system bets are exercised too, as there could be money in those that needs to be returned to LP rounds
            if (isSystem && block.timestamp > getRoundEndTime(_roundNumber)) {
                isSystemExercisable = true;
            }
            if (ticket.isTicketExercisable() && (!isWinner || isSystemExercisable)) {
                sportsAMM.handleTicketResolving(ticketAddress, ISportsAMMV2.TicketAction.Exercise);
            }
            if ((isWinner && !isSystem) || ticket.resolved()) {
                ticketAlreadyExercisedInRound[_roundNumber][ticketAddress] = true;
                exercised = true;
            }
        }
    }

    function _depositAsDefault(uint _amount, address _roundPool, uint _round) internal {
        if (defaultLiquidityProvider == address(0)) revert DefaultLPNotSet();

        collateral.safeTransferFrom(defaultLiquidityProvider, _roundPool, _amount);

        balancesPerRound[_round][defaultLiquidityProvider] += _amount;
        allocationPerRound[_round] += _amount;

        emit Deposited(defaultLiquidityProvider, _amount, _round);
    }

    function _provideAsDefault(uint _amount) internal {
        if (defaultLiquidityProvider == address(0)) revert DefaultLPNotSet();

        collateral.safeTransferFrom(defaultLiquidityProvider, address(sportsAMM), _amount);

        balancesPerRound[DEFAULT_ROUND][defaultLiquidityProvider] += _amount;
        allocationPerRound[DEFAULT_ROUND] += _amount;

        emit Deposited(defaultLiquidityProvider, _amount, DEFAULT_ROUND);
    }

    function _getOrCreateRoundPool(uint _round) internal returns (address roundPool) {
        roundPool = roundPools[_round];
        if (roundPool == address(0)) {
            if (_round == DEFAULT_ROUND) {
                roundPools[_round] = defaultLiquidityProvider;
                roundPool = defaultLiquidityProvider;
            } else {
                if (poolRoundMastercopy == address(0)) revert RoundPoolMastercopyNotSet();
                SportsAMMV2LiquidityPoolRound newRoundPool = SportsAMMV2LiquidityPoolRound(
                    Clones.clone(poolRoundMastercopy)
                );
                newRoundPool.initialize(
                    address(this),
                    collateral,
                    _round,
                    getRoundEndTime(_round - 1),
                    getRoundEndTime(_round)
                );
                roundPool = address(newRoundPool);
                roundPools[_round] = roundPool;
                emit RoundPoolCreated(_round, roundPool);
            }
        }
    }

    function _migrateTicketToNewRound(address _ticket, uint _newRound, uint _ticketIndexInRound) internal {
        if (_newRound <= round && _newRound != DEFAULT_ROUND) revert RoundAlreadyClosed();
        uint ticketRound = getTicketRound(_ticket);
        if (ticketRound != round) revert TicketNotInRound();
        if (!isTradingTicketInARound[ticketRound][_ticket]) revert TicketNotInCurrentRound();
        if (ticketAlreadyExercisedInRound[ticketRound][_ticket]) revert TicketAlreadyExercised();
        if (Ticket(_ticket).resolved()) revert TicketAlreadyResolved();

        // removing from old round
        delete isTradingTicketInARound[ticketRound][_ticket];
        _removeTicketFromRound(ticketRound, _ticket, _ticketIndexInRound);

        // transfer funds from new pool to old pool
        address oldLiquidityPoolRound = _getOrCreateRoundPool(ticketRound);
        address newLiquidityPoolRound = _getOrCreateRoundPool(_newRound);
        uint transferAmountNewToOld = collateral.balanceOf(_ticket) - Ticket(_ticket).buyInAmount();
        uint newPoolBalance = collateral.balanceOf(newLiquidityPoolRound);
        if (transferAmountNewToOld > newPoolBalance) {
            uint differenceToLPAsDefault = transferAmountNewToOld - newPoolBalance;
            _depositAsDefault(differenceToLPAsDefault, newLiquidityPoolRound, _newRound);
        }
        collateral.safeTransferFrom(newLiquidityPoolRound, oldLiquidityPoolRound, transferAmountNewToOld);

        // adding ticket to new round
        roundPerTicket[_ticket] = _newRound;
        isTradingTicketInARound[_newRound][_ticket] = true;
        tradingTicketsPerRound[_newRound].push(_ticket);
        emit TicketMigratedToNextRound(_ticket, ticketRound, _newRound);
    }

    function _removeTicketFromRound(uint _round, address _ticket, uint _ticketIndexInRound) internal {
        // if _ticketIndexInRound is 0, we need to find the ticket in the round and remove it
        // lookup is performed by iterating through the array
        bool found;
        if (_ticketIndexInRound == 0) {
            for (uint i; i < tradingTicketsPerRound[_round].length; ++i) {
                if (tradingTicketsPerRound[_round][i] == _ticket) {
                    found = true;
                    _ticketIndexInRound = i;
                    break;
                }
            }
        } else {
            found =
                _ticketIndexInRound < tradingTicketsPerRound[_round].length &&
                tradingTicketsPerRound[_round][_ticketIndexInRound] == _ticket;
        }
        if (!found) revert TicketNotFound();

        // adjust cursor if needed so we don't skip anything
        uint cursor = nextExerciseIndexPerRound[_round];
        if (_ticketIndexInRound < cursor) {
            nextExerciseIndexPerRound[_round] = _ticketIndexInRound;
        }

        tradingTicketsPerRound[_round][_ticketIndexInRound] = tradingTicketsPerRound[_round][
            tradingTicketsPerRound[_round].length - 1
        ];
        tradingTicketsPerRound[_round].pop();
    }

    /* ========== SETTERS ========== */

    /// @notice Pause/unpause LP
    /// @param _setPausing true/false
    function setPaused(bool _setPausing) external onlyOwner {
        _setPausing ? _pause() : _unpause();
    }

    /// @notice Set _poolRoundMastercopy
    /// @param _poolRoundMastercopy to clone round pools from
    function setPoolRoundMastercopy(address _poolRoundMastercopy) external onlyOwner {
        if (_poolRoundMastercopy == address(0)) revert ZeroAddress();
        poolRoundMastercopy = _poolRoundMastercopy;
        emit PoolRoundMastercopyChanged(poolRoundMastercopy);
    }

    /// @notice Set max allowed deposit
    /// @param _maxAllowedDeposit Deposit value
    function setMaxAllowedDeposit(uint _maxAllowedDeposit) external onlyOwner {
        _setMaxAllowedDeposit(_maxAllowedDeposit);
    }

    /// @notice Set min allowed deposit
    /// @param _minDepositAmount Deposit value
    function setMinAllowedDeposit(uint _minDepositAmount) external onlyOwner {
        _setMinDepositAmount(_minDepositAmount);
    }

    /// @notice Set _maxAllowedUsers
    /// @param _maxAllowedUsers Deposit value
    function setMaxAllowedUsers(uint _maxAllowedUsers) external onlyOwner {
        _setMaxAllowedUsers(_maxAllowedUsers);
    }

    // ==================== INTERNAL HELPERS ====================

    function _setMaxAllowedDeposit(uint _maxAllowedDeposit) internal {
        maxAllowedDeposit = _maxAllowedDeposit;
        emit MaxAllowedDepositChanged(_maxAllowedDeposit);
    }

    function _setMinDepositAmount(uint _minDepositAmount) internal {
        minDepositAmount = _minDepositAmount;
        emit MinAllowedDepositChanged(_minDepositAmount);
    }

    function _setMaxAllowedUsers(uint _maxAllowedUsers) internal {
        maxAllowedUsers = _maxAllowedUsers;
        emit MaxAllowedUsersChanged(_maxAllowedUsers);
    }

    /// @notice Set SportsAMM contract
    /// @param _sportsAMM SportsAMM address
    function setSportsAMM(ISportsAMMV2 _sportsAMM) external onlyOwner {
        if (address(_sportsAMM) == address(0)) revert ZeroAddress();
        if (address(sportsAMM) != address(0)) {
            collateral.approve(address(sportsAMM), 0);
        }
        sportsAMM = _sportsAMM;
        collateral.approve(address(sportsAMM), MAX_APPROVAL);
        emit SportAMMChanged(address(_sportsAMM));
    }

    /// @notice Set defaultLiquidityProvider wallet
    /// @param _defaultLiquidityProvider default liquidity provider
    function setDefaultLiquidityProvider(address _defaultLiquidityProvider) external onlyOwner {
        if (_defaultLiquidityProvider == address(0)) revert ZeroAddress();
        defaultLiquidityProvider = _defaultLiquidityProvider;
        emit DefaultLiquidityProviderChanged(_defaultLiquidityProvider);
    }

    /// @notice Set length of rounds
    /// @param _roundLength Length of a round in seconds
    function setRoundLength(uint _roundLength) external onlyOwner {
        if (started) revert CantChangeAfterPoolStart();
        roundLength = _roundLength;
        emit RoundLengthChanged(_roundLength);
    }

    /// @notice set utilization rate parameter
    /// @param _utilizationRate value as percentage
    function setUtilizationRate(uint _utilizationRate) external onlyOwner {
        _setUtilizationRate(_utilizationRate);
    }

    /// @notice set SafeBox params
    /// @param _safeBox where to send a profit reserved for protocol from each round
    /// @param _safeBoxImpact how much is the SafeBox percentage
    function setSafeBoxParams(address _safeBox, uint _safeBoxImpact) external onlyOwner {
        _setSafeBoxParams(_safeBox, _safeBoxImpact);
    }

    function _setUtilizationRate(uint _utilizationRate) internal {
        if (_utilizationRate > ONE) revert UtilRateTooHigh();
        utilizationRate = _utilizationRate;
        emit UtilizationRateChanged(_utilizationRate);
    }

    function _setSafeBoxParams(address _safeBox, uint _safeBoxImpact) internal {
        if (_safeBoxImpact > ONE) revert SafeBoxImpactTooHigh();
        safeBox = _safeBox;
        safeBoxImpact = _safeBoxImpact;
        emit SetSafeBoxParams(_safeBox, _safeBoxImpact);
    }

    function _checkCanWithdraw(address _user) internal view {
        if (!started) revert PoolNotStarted();
        if (withdrawalRequested[_user]) revert WithdrawalAlreadyRequested();
        if (balancesPerRound[round][_user] == 0) revert NothingToWithdraw();
        if (balancesPerRound[round + 1][_user] != 0) revert CantWithdrawWhenDepositedForNextRound();
    }

    /* ========== MODIFIERS ========== */

    modifier canDeposit(uint amount) {
        if (withdrawalRequested[msg.sender]) revert CantDepositDuringWithdrawalRequested();
        if (totalDeposited + amount > maxAllowedDeposit) revert AmountExceedsLPCap();
        if (balancesPerRound[round][msg.sender] == 0 && balancesPerRound[round + 1][msg.sender] == 0) {
            if (amount < minDepositAmount) revert AmountLessThanMinDeposit();
        }
        _;
    }

    modifier onlyAMM() {
        if (msg.sender != address(sportsAMM)) revert OnlyFromAMM();
        _;
    }

    modifier roundClosingNotPrepared() {
        if (roundClosingPrepared) revert NotAllowedWhenRoundClosingPrepared();
        _;
    }

    modifier onlyWhitelistedAddresses(address sender) {
        if (sender != owner && !sportsAMM.manager().isWhitelistedAddress(sender, ISportsAMMV2Manager.Role.MARKET_RESOLVING))
            revert InvalidSender();
        _;
    }

    /* ========== EVENTS ========== */

    event PoolStarted();
    event RoundPoolCreated(uint round, address roundPool);
    event Deposited(address user, uint amount, uint round);
    event WithdrawalRequested(address user);

    event SafeBoxSharePaid(uint safeBoxShare, uint safeBoxAmount);
    event RoundClosingPrepared(uint round);
    event Claimed(address user, uint amount);
    event RoundClosingBatchProcessed(uint round, uint batchSize);
    event RoundClosed(uint round, uint roundPnL);

    event PoolRoundMastercopyChanged(address newMastercopy);
    event SportAMMChanged(address sportAMM);
    event DefaultLiquidityProviderChanged(address newProvider);

    event RoundLengthChanged(uint roundLength);
    event MaxAllowedDepositChanged(uint maxAllowedDeposit);
    event MinAllowedDepositChanged(uint minAllowedDeposit);
    event MaxAllowedUsersChanged(uint maxAllowedUsersChanged);
    event UtilizationRateChanged(uint utilizationRate);
    event SetSafeBoxParams(address safeBox, uint safeBoxImpact);

    event TicketMigratedToNextRound(address ticket, uint oldRound, uint newRound);
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";

contract SportsAMMV2LiquidityPoolRound {
    /* ========== LIBRARIES ========== */
    using SafeERC20 for IERC20;

    /* ========== STATE VARIABLES ========== */

    // the adddress of the LP contract
    address public liquidityPool;

    // the adddress of collateral that LP accepts
    IERC20 public collateral;

    // the round number
    uint public round;

    // the round start time
    uint public roundStartTime;

    // the round end time
    uint public roundEndTime;

    // initialized flag
    bool public initialized;

    /* ========== CONSTRUCTOR ========== */

    /// @notice initialize the storage in the contract with the parameters
    /// @param _liquidityPool the adddress of the LP contract
    /// @param _collateral the adddress of collateral that LP accepts
    /// @param _round the round number
    /// @param _roundStartTime the round start time
    /// @param _roundEndTime the round end time
    function initialize(
        address _liquidityPool,
        IERC20 _collateral,
        uint _round,
        uint _roundStartTime,
        uint _roundEndTime
    ) external {
        require(!initialized, "Already initialized");
        initialized = true;
        liquidityPool = _liquidityPool;
        collateral = _collateral;
        round = _round;
        roundStartTime = _roundStartTime;
        roundEndTime = _roundEndTime;
        collateral.approve(_liquidityPool, type(uint256).max);
    }

    /// @notice update round times
    /// @param _roundStartTime the round start time
    /// @param _roundEndTime the round end time
    function updateRoundTimes(uint _roundStartTime, uint _roundEndTime) external onlyLiquidityPool {
        roundStartTime = _roundStartTime;
        roundEndTime = _roundEndTime;
        emit RoundTimesUpdated(_roundStartTime, _roundEndTime);
    }

    modifier onlyLiquidityPool() {
        require(msg.sender == liquidityPool, "Only LP may perform this method");
        _;
    }

    event RoundTimesUpdated(uint roundStartTime, uint roundEndTime);
}

contracts/core/LiveTrading/LiveTradingPr.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

// external
import "@chainlink/contracts/src/v0.8/ChainlinkClient.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/utils/Strings.sol";

import "../../interfaces/ISportsAMMV2.sol";
import "../../interfaces/IFreeBetsHolder.sol";
import "../../interfaces/ILiveTradingProcessor.sol";
import "../../core/AMM/SportsAMMV2Utils.sol";

contract LiveTradingProcessor is ChainlinkClient, Ownable, Pausable {
    using Chainlink for Chainlink.Request;
    using SafeERC20 for IERC20;

    uint private constant ONE = 1e18;
    uint private constant ODDS_LEN = 225;

    ISportsAMMV2 public sportsAMM;

    address public freeBetsHolder;

    bytes32 public jobSpecId; // single job
    uint public paymentAmount;

    bytes32 public parlayJobSpecId; // parlay job

    uint public maxAllowedExecutionDelay = 60;

    // ===== Singles =====
    mapping(bytes32 => ILiveTradingProcessor.LiveTradeData) public requestIdToTradeData;

    // ===== Parlays =====
    mapping(bytes32 => ILiveTradingProcessor.LiveParlayTradeData) public requestIdToParlayTradeData;
    mapping(bytes32 => bool) public requestIdIsParlay;

    // ===== Common =====
    mapping(bytes32 => address) public requestIdToRequester;
    mapping(bytes32 => bool) public requestIdToFulfillAllowed;
    mapping(bytes32 => bool) public requestIdFulfilled;
    mapping(bytes32 => uint) public timestampPerRequest;

    uint public requestCounter;
    mapping(uint => bytes32) public counterToRequestId;

    mapping(bytes32 => address) public requestIdToTicketId;

    /// @notice Constructor for LiveTradingProcessor.
    /// @dev Sets Chainlink token/oracle, SportsAMM reference, job specs and payment amount.
    /// @param _link LINK token address used for Chainlink payments
    /// @param _oracle Chainlink oracle address
    /// @param _sportsAMM SportsAMMV2 contract address
    /// @param _jobSpecId Job spec id for SINGLE live verification requests
    /// @param _parlayJobSpecId Job spec id for PARLAY live verification requests
    /// @param _paymentAmount LINK payment amount per request
    constructor(
        address _link,
        address _oracle,
        address _sportsAMM,
        bytes32 _jobSpecId,
        bytes32 _parlayJobSpecId,
        uint _paymentAmount
    ) Ownable(msg.sender) {
        setChainlinkToken(_link);
        setChainlinkOracle(_oracle);
        sportsAMM = ISportsAMMV2(_sportsAMM);

        jobSpecId = _jobSpecId;
        paymentAmount = _paymentAmount;

        parlayJobSpecId = _parlayJobSpecId;
    }

    /// @notice requestLiveTrade (SINGLE)
    /// @dev Sends a Chainlink request for live trade verification for a single market.
    ///      Stores request metadata for later fulfillment and emits LiveTradeRequested.
    /// @param _liveTradeData LiveTradeData describing the trade to be verified/executed
    /// @return requestId Chainlink request id
    function requestLiveTrade(
        ILiveTradingProcessor.LiveTradeData calldata _liveTradeData
    ) external whenNotPaused returns (bytes32 requestId) {
        require(
            sportsAMM.riskManager().liveTradingPerSportAndTypeEnabled(_liveTradeData._sportId, _liveTradeData._typeId),
            "Live trading not enabled on _sportId"
        );

        SportsAMMV2Utils(sportsAMM.sportsAMMV2Utils()).checkTradeLimits(
            msg.sender,
            _liveTradeData._buyInAmount,
            _liveTradeData._collateral,
            _liveTradeData._expectedQuote,
            1,
            sportsAMM
        );

        Chainlink.Request memory req = buildChainlinkRequest(jobSpecId, address(this), this.fulfillLiveTrade.selector);

        req.add("mode", "single");

        req.add("gameId", _liveTradeData._gameId);
        req.addUint("sportId", _liveTradeData._sportId);
        req.addUint("typeId", _liveTradeData._typeId);
        req.addInt("line", _liveTradeData._line);
        req.addUint("position", _liveTradeData._position);
        req.addUint("buyInAmount", _liveTradeData._buyInAmount);
        req.addUint("expectedQuote", _liveTradeData._expectedQuote);
        req.addUint("additionalSlippage", _liveTradeData._additionalSlippage);
        req.addUint("playerId", _liveTradeData._playerId);

        // requester & collateral included for adapter-side logging/validation
        req.add("requester", Strings.toHexString(msg.sender));
        req.add("collateral", Strings.toHexString(_liveTradeData._collateral));

        requestId = sendChainlinkRequest(req, paymentAmount);

        timestampPerRequest[requestId] = block.timestamp;
        requestIdToTradeData[requestId] = _liveTradeData;
        requestIdToRequester[requestId] = msg.sender;
        requestIdIsParlay[requestId] = false;

        counterToRequestId[requestCounter] = requestId;

        emit LiveTradeRequested(
            msg.sender,
            requestCounter,
            requestId,
            stringToBytes32(_liveTradeData._gameId),
            _liveTradeData._sportId,
            _liveTradeData._typeId,
            _liveTradeData._line,
            _liveTradeData._position,
            _liveTradeData._buyInAmount,
            _liveTradeData._expectedQuote,
            _liveTradeData._collateral
        );
        requestCounter++;
    }

    /// @notice requestLiveParlayTrade (PARLAY)
    /// @dev Sends a Chainlink request for live trade verification for a parlay (multi-leg) trade.
    ///      Validates that:
    ///        - parlay has > 1 leg
    ///        - live trading is enabled for each leg's (sportId, typeId)
    ///      Stores request metadata for later fulfillment and emits LiveParlayTradeRequested.
    /// @param _parlay LiveParlayTradeData describing the parlay to be verified/executed
    /// @return requestId Chainlink request id
    function requestLiveParlayTrade(
        ILiveTradingProcessor.LiveParlayTradeData calldata _parlay
    ) external whenNotPaused returns (bytes32 requestId) {
        uint legsLen = _parlay.legs.length;
        require(legsLen > 1, "Parlay must have > 1 leg");

        for (uint i = 0; i < legsLen; ++i) {
            ILiveTradingProcessor.LiveParlayLeg calldata leg = _parlay.legs[i];
            require(
                sportsAMM.riskManager().liveTradingPerSportAndTypeEnabled(leg.sportId, leg.typeId),
                "Live trading not enabled on leg"
            );
        }

        SportsAMMV2Utils(sportsAMM.sportsAMMV2Utils()).checkTradeLimits(
            msg.sender,
            _parlay.buyInAmount,
            _parlay.collateral,
            _parlay.expectedPayout,
            legsLen,
            sportsAMM
        );

        Chainlink.Request memory req = buildChainlinkRequest(
            parlayJobSpecId,
            address(this),
            this.fulfillLiveTradeParlay.selector
        );

        req.add("mode", "parlay");

        // Chainlink request payload: arrays are provided as string arrays to be adapter-friendly.
        string[] memory gameIds = new string[](legsLen);
        string[] memory sportIds = new string[](legsLen);
        string[] memory typeIds = new string[](legsLen);
        string[] memory lines = new string[](legsLen);
        string[] memory positions = new string[](legsLen);
        string[] memory expectedLegOdds = new string[](legsLen);
        string[] memory playerIds = new string[](legsLen);

        for (uint i = 0; i < legsLen; ++i) {
            ILiveTradingProcessor.LiveParlayLeg calldata leg = _parlay.legs[i];
            gameIds[i] = leg.gameId;
            sportIds[i] = Strings.toString(uint256(leg.sportId));
            typeIds[i] = Strings.toString(uint256(leg.typeId));
            lines[i] = _intToString(int256(leg.line));
            positions[i] = Strings.toString(uint256(leg.position));
            expectedLegOdds[i] = Strings.toString(uint256(leg.expectedLegOdd));
            playerIds[i] = Strings.toString(uint256(leg.playerId));
        }

        req.addStringArray("gameIds", gameIds);
        req.addStringArray("sportIds", sportIds);
        req.addStringArray("typeIds", typeIds);
        req.addStringArray("lines", lines);
        req.addStringArray("positions", positions);
        req.addStringArray("expectedLegOdds", expectedLegOdds);
        req.addStringArray("playerIds", playerIds);

        req.addUint("buyInAmount", _parlay.buyInAmount);
        req.addUint("expectedQuote", _parlay.expectedPayout);
        req.addUint("additionalSlippage", _parlay.additionalSlippage);

        req.add("requester", Strings.toHexString(msg.sender));
        req.add("collateral", Strings.toHexString(_parlay.collateral));

        requestId = sendChainlinkRequest(req, paymentAmount);

        timestampPerRequest[requestId] = block.timestamp;
        requestIdToParlayTradeData[requestId] = _parlay;
        requestIdToRequester[requestId] = msg.sender;
        requestIdIsParlay[requestId] = true;

        counterToRequestId[requestCounter] = requestId;

        emit LiveParlayTradeRequested(msg.sender, requestCounter, requestId, uint16(legsLen), _parlay.buyInAmount);
        requestCounter++;
    }

    // ============================
    // Fulfill methods
    // ============================

    /// @notice fulfillLiveTrade (SINGLE)
    /// @dev Chainlink callback for single live trade verification.
    ///      Requirements:
    ///        - request not already fulfilled
    ///        - request not timed out (timestampPerRequest + maxAllowedExecutionDelay)
    ///        - request must not be a parlay
    ///        - slippage constraint satisfied
    ///      If `_allow` is true, executes `sportsAMM.tradeLive(...)` for a single TradeData entry.
    /// @param _requestId Chainlink request id being fulfilled
    /// @param _allow Whether the trade is allowed after verification
    /// @param _approvedQuote Approved quote (odds) for the selected position
    function fulfillLiveTrade(
        bytes32 _requestId,
        bool _allow,
        uint _approvedQuote
    ) external whenNotPaused recordChainlinkFulfillment(_requestId) {
        require(!requestIdFulfilled[_requestId], "Request ID already fulfilled");
        require((timestampPerRequest[_requestId] + maxAllowedExecutionDelay) > block.timestamp, "Request timed out");
        require(!requestIdIsParlay[_requestId], "Request is parlay");

        ILiveTradingProcessor.LiveTradeData memory lTradeData = requestIdToTradeData[_requestId];
        address requester = requestIdToRequester[_requestId];

        // Ensure approved quote respects additional slippage bound relative to expected quote.
        require(
            ((ONE * _approvedQuote) / lTradeData._expectedQuote) <= (ONE + lTradeData._additionalSlippage),
            "Slippage too high"
        );

        if (_allow) {
            ISportsAMMV2.TradeData[] memory tradeData = new ISportsAMMV2.TradeData[](1);
            tradeData[0] = _buildTradeDataSingle(lTradeData, _approvedQuote);

            _executeTrade(
                _requestId,
                requester,
                tradeData,
                lTradeData._buyInAmount,
                _approvedQuote,
                lTradeData._referrer,
                lTradeData._collateral
            );
        }

        requestIdToFulfillAllowed[_requestId] = _allow;
        requestIdFulfilled[_requestId] = true;

        emit LiveTradeFulfilled(
            requester,
            _requestId,
            _allow,
            stringToBytes32(lTradeData._gameId),
            lTradeData._sportId,
            lTradeData._typeId,
            lTradeData._line,
            lTradeData._position,
            lTradeData._buyInAmount,
            _approvedQuote,
            lTradeData._collateral,
            block.timestamp,
            lTradeData._playerId
        );
    }

    /// @notice fulfillLiveTradeParlay (PARLAY)
    /// @dev Chainlink callback for parlay live trade verification.
    ///      Requirements:
    ///        - request not already fulfilled
    ///        - request not timed out (timestampPerRequest + maxAllowedExecutionDelay)
    ///        - request must be a parlay
    ///        - legsLen > 1 and approvedLegOdds length must match legsLen
    ///        - slippage constraint satisfied vs expectedPayout
    ///      If `_allow` is true, executes `sportsAMM.tradeLive(...)` for TradeData[] of length legsLen.
    /// @param _requestId Chainlink request id being fulfilled
    /// @param _allow Whether the trade is allowed after verification
    /// @param _approvedQuote Approved quote for the overall parlay payout
    /// @param _approvedLegOdds Approved odds per leg (must match legs length)
    function fulfillLiveTradeParlay(
        bytes32 _requestId,
        bool _allow,
        uint _approvedQuote,
        uint[] calldata _approvedLegOdds
    ) external whenNotPaused recordChainlinkFulfillment(_requestId) {
        require(!requestIdFulfilled[_requestId], "Request ID already fulfilled");
        require((timestampPerRequest[_requestId] + maxAllowedExecutionDelay) > block.timestamp, "Request timed out");
        require(requestIdIsParlay[_requestId], "Request is not parlay");

        ILiveTradingProcessor.LiveParlayTradeData memory pTrade = requestIdToParlayTradeData[_requestId];
        address requester = requestIdToRequester[_requestId];
        uint legsLen = pTrade.legs.length;

        require(legsLen > 1, "Parlay must have > 1 leg");
        require(_approvedLegOdds.length == legsLen, "Bad leg odds length");

        // Ensure approved quote respects additional slippage bound relative to expected payout.
        require(((ONE * _approvedQuote) / pTrade.expectedPayout) <= (ONE + pTrade.additionalSlippage), "Slippage too high");

        if (_allow) {
            ISportsAMMV2.TradeData[] memory tradeData = new ISportsAMMV2.TradeData[](legsLen);
            for (uint i = 0; i < legsLen; ++i) {
                tradeData[i] = _buildTradeDataParlayLeg(pTrade.legs[i], _approvedLegOdds[i]);
            }

            _executeTrade(
                _requestId,
                requester,
                tradeData,
                pTrade.buyInAmount,
                _approvedQuote,
                pTrade.referrer,
                pTrade.collateral
            );
        }

        requestIdToFulfillAllowed[_requestId] = _allow;
        requestIdFulfilled[_requestId] = true;

        emit LiveParlayTradeFulfilled(requester, _requestId, _allow, uint16(legsLen), pTrade.buyInAmount, _approvedQuote);
    }

    // ============================
    // Internal helpers
    // ============================

    /// @notice Executes a verified live trade via SportsAMM and performs post-trade confirmation if required.
    /// @dev Stores the created ticket address for the request id and optionally confirms via FreeBetsHolder.
    /// @param _requestId Chainlink request id associated with the trade
    /// @param requester Original requester that initiated the trade request
    /// @param tradeData TradeData array to pass to SportsAMMV2.tradeLive (len=1 for singles, len>1 for parlays)
    /// @param buyInAmount Buy-in amount for the trade
    /// @param approvedQuote Approved quote (overall payout) returned by the verifier
    /// @param referrer Referrer address (if any)
    /// @param collateral Collateral token used for the trade
    function _executeTrade(
        bytes32 _requestId,
        address requester,
        ISportsAMMV2.TradeData[] memory tradeData,
        uint buyInAmount,
        uint approvedQuote,
        address referrer,
        address collateral
    ) internal {
        address _createdTicket = sportsAMM.tradeLive(tradeData, buyInAmount, approvedQuote, requester, referrer, collateral);
        requestIdToTicketId[_requestId] = _createdTicket;

        if (requester == freeBetsHolder) {
            IFreeBetsHolder(freeBetsHolder).confirmLiveTrade(_requestId, _createdTicket, buyInAmount, collateral);
        }
    }

    /// @notice Builds TradeData for a single-leg live trade.
    /// @dev Creates ODDS_LEN-sized odds array with only selected position set to approvedLegOdd.
    /// @param lTradeData Original live trade data requested by the user
    /// @param approvedLegOdd Approved odd for the selected position
    /// @return td TradeData struct to be passed to SportsAMMV2.tradeLive
    function _buildTradeDataSingle(
        ILiveTradingProcessor.LiveTradeData memory lTradeData,
        uint approvedLegOdd
    ) internal view returns (ISportsAMMV2.TradeData memory td) {
        bytes32[] memory merkleProofs;

        uint[] memory odds = new uint[](ODDS_LEN);
        odds[lTradeData._position] = approvedLegOdd;

        ISportsAMMV2.CombinedPosition[][] memory comPositions = new ISportsAMMV2.CombinedPosition[][](ODDS_LEN);

        td = ISportsAMMV2.TradeData(
            stringToBytes32(lTradeData._gameId),
            lTradeData._sportId,
            lTradeData._typeId,
            block.timestamp + 60,
            0,
            lTradeData._line,
            lTradeData._playerId,
            odds,
            merkleProofs,
            lTradeData._position,
            comPositions
        );
    }

    /// @notice Builds TradeData for a single parlay leg.
    /// @dev Creates ODDS_LEN-sized odds array with only leg.position set to approvedLegOdd.
    /// @param leg Parlay leg parameters
    /// @param approvedLegOdd Approved odd for this specific leg/position
    /// @return td TradeData struct to be passed to SportsAMMV2.tradeLive
    function _buildTradeDataParlayLeg(
        ILiveTradingProcessor.LiveParlayLeg memory leg,
        uint approvedLegOdd
    ) internal view returns (ISportsAMMV2.TradeData memory td) {
        bytes32[] memory merkleProofs;

        uint[] memory odds = new uint[](ODDS_LEN);
        odds[leg.position] = approvedLegOdd;

        ISportsAMMV2.CombinedPosition[][] memory comPositions = new ISportsAMMV2.CombinedPosition[][](ODDS_LEN);

        td = ISportsAMMV2.TradeData(
            stringToBytes32(leg.gameId),
            leg.sportId,
            leg.typeId,
            block.timestamp + 60,
            0,
            leg.line,
            leg.playerId,
            odds,
            merkleProofs,
            leg.position,
            comPositions
        );
    }

    /// @notice withdraw collateral in the contract
    /// @dev Transfers the full balance of `collateral` held by this contract to `recipient`.
    /// @param collateral ERC20 token address to withdraw
    /// @param recipient Address receiving withdrawn collateral
    function withdrawCollateral(address collateral, address recipient) external onlyOwner {
        IERC20(collateral).safeTransfer(recipient, IERC20(collateral).balanceOf(address(this)));
    }

    //////////// SETTERS

    /// @notice pause live trading
    /// @dev Pauses or unpauses contract functions protected by whenNotPaused.
    /// @param _setPausing whether to pause or unpause
    function setPaused(bool _setPausing) external onlyOwner {
        _setPausing ? _pause() : _unpause();
    }

    /// @notice Configuration setter
    /// @dev Updates Chainlink and SportsAMM configuration, including both single and parlay job spec ids.
    /// @param _link LINK token address used for Chainlink payments
    /// @param _oracle Chainlink oracle address
    /// @param _sportsAMM SportsAMMV2 contract address
    /// @param _jobSpecId Job spec id for SINGLE live verification requests
    /// @param _parlayJobSpecId Job spec id for PARLAY live verification requests
    /// @param _paymentAmount LINK payment amount per request
    function setConfiguration(
        address _link,
        address _oracle,
        address _sportsAMM,
        bytes32 _jobSpecId,
        bytes32 _parlayJobSpecId,
        uint _paymentAmount
    ) external onlyOwner {
        setChainlinkToken(_link);
        setChainlinkOracle(_oracle);
        sportsAMM = ISportsAMMV2(_sportsAMM);

        jobSpecId = _jobSpecId;
        parlayJobSpecId = _parlayJobSpecId;
        paymentAmount = _paymentAmount;

        emit ContextReset(_link, _oracle, _sportsAMM, _jobSpecId, _parlayJobSpecId, _paymentAmount);
    }

    /// @notice sets the FreeBetsHolder address, required for handling ticket claiming via FreeBetsHolder
    /// @param _freeBetsHolder FreeBetsHolder contract address
    function setFreeBetsHolder(address _freeBetsHolder) external onlyOwner {
        freeBetsHolder = _freeBetsHolder;
        emit SetFreeBetsHolder(_freeBetsHolder);
    }

    /// @notice setMaxAllowedExecutionDelay
    /// @dev Sets maximum allowed buffer for the Chainlink request to be executed.
    /// @param _maxAllowedExecutionDelay maximum allowed buffer in seconds
    function setMaxAllowedExecutionDelay(uint _maxAllowedExecutionDelay) external onlyOwner {
        maxAllowedExecutionDelay = _maxAllowedExecutionDelay;
        emit SetMaxAllowedExecutionDelay(_maxAllowedExecutionDelay);
    }

    //// GETTERS

    /// @notice gets trade data struct for specified request ID (singles)
    /// @param requestId request ID
    /// @return liveTradeData Stored LiveTradeData for requestId
    function getTradeData(bytes32 requestId) external view returns (ILiveTradingProcessor.LiveTradeData memory) {
        return requestIdToTradeData[requestId];
    }

    /// @notice gets parlay trade data struct for specified request ID (parlays)
    /// @param requestId request ID
    /// @return parlayTradeData Stored LiveParlayTradeData for requestId
    function getParlayTradeData(bytes32 requestId) external view returns (ILiveTradingProcessor.LiveParlayTradeData memory) {
        return requestIdToParlayTradeData[requestId];
    }

    //// UTILITY

    /// @notice Converts a string into bytes32 by taking the first 32 bytes.
    /// @dev Returns 0x0 for empty strings. Used for gameId conversions.
    function stringToBytes32(string memory source) internal pure returns (bytes32 result) {
        bytes memory tempEmptyStringTest = bytes(source);
        if (tempEmptyStringTest.length == 0) {
            return 0x0;
        }
        assembly {
            result := mload(add(source, 32))
        }
    }

    /// @notice Converts signed integer into string representation.
    /// @dev Used for encoding negative lines in Chainlink request arrays.
    function _intToString(int256 value) internal pure returns (string memory) {
        if (value >= 0) {
            return Strings.toString(uint256(value));
        }
        return string(abi.encodePacked("-", Strings.toString(uint256(-value))));
    }

    /////// EVENTS

    event ContextReset(
        address _link,
        address _oracle,
        address _sportsAMM,
        bytes32 _jobSpecId,
        bytes32 _parlayJobSpecId,
        uint _paymentAmount
    );

    event LiveTradeRequested(
        address requester,
        uint requestCounter,
        bytes32 requestId,
        bytes32 _gameId,
        uint16 _sportId,
        uint16 _typeId,
        int24 _line,
        uint8 _position,
        uint _buyInAmount,
        uint _expectedQuote,
        address _collateral
    );

    event LiveTradeFulfilled(
        address requester,
        bytes32 requestId,
        bool _allow,
        bytes32 _gameId,
        uint16 _sportId,
        uint16 _typeId,
        int24 _line,
        uint8 _position,
        uint _buyInAmount,
        uint _expectedQuote,
        address _collateral,
        uint timestamp,
        uint24 playerId
    );

    event LiveParlayTradeRequested(
        address requester,
        uint requestCounter,
        bytes32 requestId,
        uint16 legsCount,
        uint buyInAmount
    );

    event LiveParlayTradeFulfilled(
        address requester,
        bytes32 requestId,
        bool _allow,
        uint16 legsCount,
        uint buyInAmount,
        uint approvedQuote
    );

    event SetMaxAllowedExecutionDelay(uint _maxAllowedExecutionDelay);
    event SetFreeBetsHolder(address _freeBetsHolder);
}

