// SPDX-License-Identifier: MIT

pragma solidity ^0.8.0;

// external
import "@chainlink/contracts/src/v0.8/ChainlinkClient.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

import "../../interfaces/ISportsAMMV2.sol";
import "../../interfaces/ISportsAMMV2ResultManager.sol";

contract ChainlinkResolver is ChainlinkClient, Ownable, Pausable {
    using Chainlink for Chainlink.Request;
    using SafeERC20 for IERC20;

    uint private constant ONE = 1e18;

    ISportsAMMV2 public sportsAMM;
    ISportsAMMV2ResultManager public resultManager;

    bytes32 public jobSpecId;

    uint public paymentAmount;

    IERC20 public linkToken;

    mapping(bytes32 => bool) public requestIdFulfilled;

    struct MarketResolveData {
        bytes32 requestId;
        string[] _gameIds;
        string[] _typeIds;
        string[] _playerIds;
    }

    mapping(bytes32 => MarketResolveData) public requestIdToMarketResolveData;

    uint public requestCounter;
    mapping(uint => bytes32) public counterToRequestId;

    constructor(
        address _link,
        address _oracle,
        address _sportsAMM,
        address _resultManager,
        bytes32 _jobSpecId,
        uint _paymentAmount
    ) Ownable(msg.sender) {
        setChainlinkToken(_link);
        setChainlinkOracle(_oracle);
        linkToken = IERC20(_link);
        sportsAMM = ISportsAMMV2(_sportsAMM);
        resultManager = ISportsAMMV2ResultManager(_resultManager);
        jobSpecId = _jobSpecId;
        paymentAmount = _paymentAmount;
    }

    /// @notice requestMarketResolving
    /// @param _sportId sports id
    /// @param _date date on which game/games are played
    /// @param _gameIds for which to request resolving
    /// @param _typeIds for which to request resolving
    /// @param _playerIds for which to request resolving
    function requestMarketResolving(
        uint256 _sportId,
        uint256 _date,
        string[] calldata _gameIds,
        string[] calldata _typeIds,
        string[] calldata _playerIds
    ) external whenNotPaused {
        require(
            _gameIds.length > 0 && _gameIds.length == _typeIds.length && _typeIds.length == _playerIds.length,
            "Requested data has to be of same length"
        );
        Chainlink.Request memory req;

        req = buildChainlinkRequest(jobSpecId, address(this), this.fulfillMarketResolve.selector);

        req.addUint("date", _date);
        req.addUint("sportId", _sportId);
        req.addStringArray("gameIds", _gameIds);
        req.addStringArray("typeIds", _typeIds);
        req.addStringArray("playerIds", _playerIds);

        _putLink(msg.sender, paymentAmount);

        bytes32 requestId = sendChainlinkRequest(req, paymentAmount);

        MarketResolveData memory data = MarketResolveData(requestId, _gameIds, _typeIds, _playerIds);
        requestIdToMarketResolveData[requestId] = data;

        counterToRequestId[requestCounter++] = requestId;

        emit MarketResolvingRequested(msg.sender, _gameIds, _typeIds, _playerIds);
    }

    /// @notice fulfillMarketResolve
    /// @param _requestId which is being responded to
    /// @param _results to use for resolving
    function fulfillMarketResolve(
        bytes32 _requestId,
        int24[][] calldata _results
    ) external whenNotPaused recordChainlinkFulfillment(_requestId) {
        //might be redundant as already done by Chainlink Client, but making double sure
        require(!requestIdFulfilled[_requestId], "Request ID already fulfilled");

        MarketResolveData memory marketData = requestIdToMarketResolveData[_requestId];

        bytes32[] memory _gameIds = new bytes32[](marketData._gameIds.length);
        uint16[] memory _typeIds = new uint16[](marketData._typeIds.length);
        uint24[] memory _playerIds = new uint24[](marketData._playerIds.length);

        require(_results.length == _gameIds.length, "Results not of same length as requested");

        for (uint i = 0; i < marketData._gameIds.length; i++) {
            _gameIds[i] = stringToBytes32(marketData._gameIds[i]);
            _typeIds[i] = uint16(st2num(marketData._typeIds[i]));
            _playerIds[i] = uint24(st2num(marketData._playerIds[i]));
        }

        resultManager.setResultsPerMarkets(_gameIds, _typeIds, _playerIds, _results);

        requestIdFulfilled[_requestId] = true;

        emit FulfillMarketResolveCall(_requestId, marketData._gameIds, marketData._typeIds, marketData._playerIds, _results);
    }

    /* ========== INTERNALS ========== */

    function _putLink(address _sender, uint _payment) internal {
        linkToken.safeTransferFrom(_sender, address(this), _payment);
    }

    function stringToBytes32(string memory source) internal pure returns (bytes32 result) {
        bytes memory tempEmptyStringTest = bytes(source);
        if (tempEmptyStringTest.length == 0) {
            return 0x0;
        }
        assembly {
            result := mload(add(source, 32))
        }
    }

    function st2num(string memory numString) internal pure returns (uint) {
        uint val = 0;
        bytes memory stringBytes = bytes(numString);
        for (uint i = 0; i < stringBytes.length; i++) {
            uint exp = stringBytes.length - i;
            bytes1 ival = stringBytes[i];
            uint8 uval = uint8(ival);
            uint jval = uval - uint(0x30);
            val += (uint(jval) * (10 ** (exp - 1)));
        }
        return val;
    }

    //////////// SETTERS

    /// @notice pause resolving
    /// @param _setPausing whether to pause or unpause
    function setPaused(bool _setPausing) external onlyOwner {
        _setPausing ? _pause() : _unpause();
    }

    /// @notice setConfiguration
    /// @param _link paymentAmount token
    /// @param _oracle CL node that will execute the requests
    /// @param _sportsAMM address
    /// @param _resultManager address
    /// @param _jobSpecId CL node job spec ID
    /// @param _paymentAmount amount of paymentAmount token for each request
    function setConfiguration(
        address _link,
        address _oracle,
        address _sportsAMM,
        address _resultManager,
        bytes32 _jobSpecId,
        uint _paymentAmount
    ) external onlyOwner {
        setChainlinkToken(_link);
        setChainlinkOracle(_oracle);
        linkToken = IERC20(_link);
        sportsAMM = ISportsAMMV2(_sportsAMM);
        resultManager = ISportsAMMV2ResultManager(_resultManager);
        jobSpecId = _jobSpecId;
        paymentAmount = _paymentAmount;

        emit ContextReset(_link, _oracle, _sportsAMM, _resultManager, _jobSpecId, _paymentAmount);
    }

    /////// EVENTS
    event ContextReset(
        address _link,
        address _oracle,
        address _sportsAMM,
        address _resultManager,
        bytes32 _jobSpecId,
        uint _paymentAmount
    );
    event MarketResolvingRequested(address requester, string[] _gameIds, string[] _typeIds, string[] _playerIds);
    event FulfillMarketResolveCall(
        bytes32 requestId,
        string[] _gameIds,
        string[] _typeIds,
        string[] _playerIds,
        int24[][] _results
    );
}

contracts/core/Resolving/ResolveBlocker..content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "../../utils/proxy/ProxyOwned.sol";
import "../../utils/proxy/ProxyPausable.sol";
import "../../utils/proxy/ProxyReentrancyGuard.sol";

import "../../interfaces/ISportsAMMV2Data.sol";
import "../../interfaces/ISportsAMMV2Manager.sol";
import "./../AMM/Ticket.sol";

contract ResolveBlocker is Initializable, ProxyOwned, ProxyPausable, ProxyReentrancyGuard {
    /// @notice The interface for accessing sports AMM data
    ISportsAMMV2Data public sportsAMMData;

    /// @notice The interface for the sports AMM manager
    ISportsAMMV2Manager public manager;

    /// @notice Mapping to track if a game is blocked for resolution
    /// @dev Maps gameId to a boolean indicating if the game is blocked
    mapping(bytes32 => bool) public gameIdBlockedForResolution;
    /// @dev Maps gameId to the reason for blocking the game
    mapping(bytes32 => string) public gameIdBlockReason;
    /// @notice Mapping to track if a game has been unblocked by an admin
    /// @dev Maps gameId to a boolean indicating if the game was unblocked by an admin
    mapping(bytes32 => bool) public gameIdUnblockedByAdmin;

    /* ========== CONSTRUCTOR ========== */

    /// @notice Initializes the contract with the owner, SportsAMMV2Data, and manager addresses
    /// @param _owner The address of the contract owner
    /// @param _sportsAMMV2Data The address of the SportsAMMV2Data contract
    /// @param _manager The address of the manager contract
    function initialize(address _owner, address _sportsAMMV2Data, address _manager) external initializer {
        setOwner(_owner);
        initNonReentrant();
        sportsAMMData = ISportsAMMV2Data(_sportsAMMV2Data);
        manager = ISportsAMMV2Manager(_manager);
    }

    /// @notice Retrieves the blocked and unblocked status for a list of game IDs
    /// @param gameIds An array of game IDs to check
    /// @return blockedGames An array of booleans indicating if each game is blocked
    /// @return unblockedByAdmin An array of booleans indicating if each game is unblocked by admin
    function getGamesBlockedForResolution(
        bytes32[] memory gameIds
    ) external view returns (bool[] memory blockedGames, bool[] memory unblockedByAdmin, string[] memory blockReason) {
        blockedGames = new bool[](gameIds.length);
        unblockedByAdmin = new bool[](gameIds.length);
        blockReason = new string[](gameIds.length);
        for (uint i = 0; i < gameIds.length; i++) {
            blockedGames[i] = gameIdBlockedForResolution[gameIds[i]];
            unblockedByAdmin[i] = gameIdUnblockedByAdmin[gameIds[i]];
            blockReason[i] = gameIdBlockReason[gameIds[i]];
        }
    }

    /// @notice Checks if an address is whitelisted for unblocking games
    /// @param _address The address to check
    /// @return True if the address is whitelisted, false otherwise
    function isWhitelistedForUnblock(address _address) external view returns (bool) {
        return
            owner == _address ||
            manager.isWhitelistedAddress(_address, ISportsAMMV2Manager.Role.TICKET_PAUSER) ||
            manager.isWhitelistedAddress(_address, ISportsAMMV2Manager.Role.MARKET_RESOLVING);
    }

    /// @notice Blocks a list of games for resolution
    /// @param _gameIds An array of game IDs to block
    /// @param _reason The reason for blocking the games
    function blockGames(bytes32[] memory _gameIds, string memory _reason) external onlyWhitelistedForBlock {
        _blockGames(_gameIds, _reason, true);
        emit GamesBlockedForResolution(_gameIds, _reason);
    }

    /// @notice Unblocks a list of games for resolution
    /// @param _gameIds An array of game IDs to unblock
    function unblockGames(bytes32[] memory _gameIds) external onlyWhitelistedForUnblock {
        _blockGames(_gameIds, "", false);
        emit GamesUnblockedForResolution(_gameIds);
    }

    /// @notice Internal function to block or unblock games
    /// @param _gameIds An array of game IDs to block or unblock
    /// @param _blockGame A boolean indicating whether to block (true) or unblock (false) the games
    function _blockGames(bytes32[] memory _gameIds, string memory _reason, bool _blockGame) internal {
        for (uint i = 0; i < _gameIds.length; i++) {
            if (!_blockGame && gameIdBlockedForResolution[_gameIds[i]]) {
                gameIdUnblockedByAdmin[_gameIds[i]] = true;
            } else if (_blockGame && gameIdUnblockedByAdmin[_gameIds[i]]) {
                gameIdUnblockedByAdmin[_gameIds[i]] = false;
            }
            gameIdBlockedForResolution[_gameIds[i]] = _blockGame;
            if (bytes(_reason).length > 0) {
                gameIdBlockReason[_gameIds[i]] = _reason;
            }
        }
    }

    /// @notice Sets the Sports AMM Manager contract address
    /// @param _manager The address of Sports AMM Manager contract
    function setManager(address _manager) external onlyOwner {
        require(_manager != address(0), "Invalid address");
        manager = ISportsAMMV2Manager(_manager);
        emit SetManager(_manager);
    }

    /// @notice Sets the Sports AMM Data contract address
    /// @param _sportsAMMData The address of Sports AMM Data contract
    function setSportsAMMData(address _sportsAMMData) external onlyOwner {
        require(_sportsAMMData != address(0), "Invalid address");
        sportsAMMData = ISportsAMMV2Data(_sportsAMMData);
        emit SetSportsAMMData(_sportsAMMData);
    }

    /* ========== MODIFIERS ========== */
    /// @notice Modifier to ensure only whitelisted addresses can unblock games
    modifier onlyWhitelistedForUnblock() {
        require(
            msg.sender == owner ||
                manager.isWhitelistedAddress(msg.sender, ISportsAMMV2Manager.Role.TICKET_PAUSER) ||
                manager.isWhitelistedAddress(msg.sender, ISportsAMMV2Manager.Role.MARKET_RESOLVING),
            "Invalid sender"
        );
        _;
    }

    /// @notice Modifier to ensure only whitelisted addresses can block games
    modifier onlyWhitelistedForBlock() {
        require(
            msg.sender == owner ||
                manager.isWhitelistedAddress(msg.sender, ISportsAMMV2Manager.Role.TICKET_PAUSER) ||
                manager.isWhitelistedAddress(msg.sender, ISportsAMMV2Manager.Role.MARKET_RESOLVING),
            "Invalid sender"
        );
        _;
    }

    /* ========== EVENTS ========== */
    /// @notice Emitted when the Sports AMM Data contract address is set
    event SetSportsAMMData(address sportsAMMData);
    /// @notice Emitted when the Sports AMM Manager contract address is set
    event SetManager(address manager);
    /// @notice Emitted when games are blocked for resolution
    event GamesBlockedForResolution(bytes32[] gameIds, string reason);
    /// @notice Emitted when games are unblocked for resolution
    event GamesUnblockedForResolution(bytes32[] gameIds);
}

contracts/core/Resolving/SportsAMMV2Resu.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/utils/cryptography/MerkleProof.sol";
import "@openzeppelin/contracts/proxy/Clones.sol";

// internal
import "../../utils/proxy/ProxyReentrancyGuard.sol";
import "../../utils/proxy/ProxyOwned.sol";
import "../../utils/proxy/ProxyPausable.sol";
import "../../utils/libraries/AddressSetLib.sol";

import "@thales-dao/contracts/contracts/interfaces/IReferrals.sol";
import "@thales-dao/contracts/contracts/interfaces/IMultiCollateralOnOffRamp.sol";
import "@thales-dao/contracts/contracts/interfaces/IStakingThales.sol";

import "../AMM//Ticket.sol";
import "../../interfaces/ISportsAMMV2.sol";
import "../../interfaces/ISportsAMMV2Manager.sol";
import "../../interfaces/ISportsAMMV2RiskManager.sol";
import "../../interfaces/ISportsAMMV2ResultManager.sol";
import "../../interfaces/ISportsAMMV2LiquidityPool.sol";

/// @title Sports AMM V2 contract
/// @author vladan
contract SportsAMMV2ResultManager is Initializable, ProxyOwned, ProxyPausable, ProxyReentrancyGuard {
    enum ResultType {
        Unassigned,
        ExactPosition,
        OverUnder,
        CombinedPositions,
        Spread
    }

    enum OverUnderType {
        Over,
        Under
    }

    /* ========== CONST VARIABLES ========== */

    uint private constant ONE = 1e18;
    uint private constant MAX_APPROVAL = type(uint256).max;

    int24 public constant CANCEL_ID = -9999;

    /* ========== STATE VARIABLES ========== */

    // manager address
    ISportsAMMV2Manager public manager;

    // stores market results, market defined with gameId -> typeId -> playerId
    mapping(bytes32 => mapping(uint => mapping(uint => int24[]))) public resultsPerMarket;

    // indicates are results set for market, market defined with gameId -> typeId -> playerId
    mapping(bytes32 => mapping(uint => mapping(uint => bool))) public areResultsPerMarketSet;

    // indicates is game cancelled (parent market together with all child markets)
    mapping(bytes32 => bool) public isGameCancelled;

    // indicates is market explicitly cancelled, market defined with gameId -> typeId -> playerId -> line
    mapping(bytes32 => mapping(uint => mapping(uint => mapping(int => bool)))) public isMarketExplicitlyCancelled;

    // stores result type per market type
    mapping(uint => ResultType) public resultTypePerMarketType;

    // the address that can resolve markets
    address public chainlinkResolver;

    // number of tickets to exercise on game resolution
    uint public numOfTicketsToExerciseOnGameResolution;

    /* ========== CONSTRUCTOR ========== */

    /// @param _manager the address of manager
    function initialize(address _owner, ISportsAMMV2Manager _manager) public initializer {
        setOwner(_owner);
        initNonReentrant();
        manager = _manager;
    }

    /* ========== EXTERNAL READ FUNCTIONS ========== */

    /// @notice is specific market resolved
    /// @param _gameId game ID
    /// @param _typeId type ID
    /// @param _playerId player ID (0 if not player props game)
    /// @param _line line
    /// @return isResolved true/false
    function isMarketResolved(
        bytes32 _gameId,
        uint16 _typeId,
        uint24 _playerId,
        int24 _line,
        ISportsAMMV2.CombinedPosition[] memory combinedPositions
    ) external view returns (bool isResolved) {
        isResolved = _isMarketResolved(_gameId, _typeId, _playerId, _line, combinedPositions);
    }

    /// @notice is specific market cancelled
    /// @param _gameId game ID
    /// @param _typeId type ID
    /// @param _playerId player ID (0 if not player props game)
    /// @param _line line
    /// @return isCancelled true/false
    function isMarketCancelled(
        bytes32 _gameId,
        uint16 _typeId,
        uint24 _playerId,
        int24 _line,
        ISportsAMMV2.CombinedPosition[] memory combinedPositions
    ) external view returns (bool isCancelled) {
        if (isGameCancelled[_gameId]) {
            isCancelled = true;
        } else {
            ResultType resultType = resultTypePerMarketType[_typeId];
            if (resultType == ResultType.CombinedPositions) {
                isCancelled = true;
                for (uint i = 0; i < combinedPositions.length; i++) {
                    ISportsAMMV2.CombinedPosition memory combinedPosition = combinedPositions[i];
                    bool isCombinedPositionMarketCancelled = _isMarketCancelled(
                        _gameId,
                        combinedPosition.typeId,
                        0,
                        combinedPosition.line
                    );
                    if (!isCombinedPositionMarketCancelled) {
                        isCancelled = false;
                        break;
                    }
                }
            } else {
                isCancelled = _isMarketCancelled(_gameId, _typeId, _playerId, _line);
            }
        }
    }

    /**
     * @notice Retrieves the status of a specific market position for a given game and player.
     * @param _gameId The identifier of the game.
     * @param _typeId The type of the market.
     * @param _playerId The identifier of the player.
     * @param _line The line associated with the market position.
     * @param _position The position index within the market.
     * @param _combinedPositions An array of combined positions related to the market.
     * @return status The status of the market position (e.g., Active, Cancelled, Resolved).
     */
    function getMarketPositionStatus(
        bytes32 _gameId,
        uint16 _typeId,
        uint24 _playerId,
        int24 _line,
        uint _position,
        ISportsAMMV2.CombinedPosition[] memory _combinedPositions
    ) external view returns (ISportsAMMV2ResultManager.MarketPositionStatus status) {
        return _getMarketPositionStatus(_gameId, _typeId, _playerId, _line, _position, _combinedPositions);
    }

    /**
     * @notice Checks if a specific market position is a winning position.
     * @param _gameId The identifier of the game.
     * @param _typeId The type of the market.
     * @param _playerId The identifier of the player.
     * @param _line The line associated with the market position.
     * @param _position The position index within the market.
     * @param _combinedPositions An array of combined positions related to the market.
     * @return bool True if the position is winning, otherwise false.
     */
    function isWinningMarketPosition(
        bytes32 _gameId,
        uint16 _typeId,
        uint24 _playerId,
        int24 _line,
        uint _position,
        ISportsAMMV2.CombinedPosition[] memory _combinedPositions
    ) external view returns (bool) {
        return _isWinningMarketPosition(_gameId, _typeId, _playerId, _line, _position, _combinedPositions);
    }

    /**
     * @notice Checks if a specific market position has been cancelled.
     * @param _gameId The identifier of the game.
     * @param _typeId The type of the market.
     * @param _playerId The identifier of the player.
     * @param _line The line associated with the market position.
     * @param _position The position index within the market.
     * @param _combinedPositions An array of combined positions related to the market.
     * @return isCancelled True if the position is cancelled, otherwise false.
     */
    function isCancelledMarketPosition(
        bytes32 _gameId,
        uint16 _typeId,
        uint24 _playerId,
        int24 _line,
        uint _position,
        ISportsAMMV2.CombinedPosition[] memory _combinedPositions
    ) external view returns (bool isCancelled) {
        ISportsAMMV2ResultManager.MarketPositionStatus marketPositionStatus = _getMarketPositionStatus(
            _gameId,
            _typeId,
            _playerId,
            _line,
            _position,
            _combinedPositions
        );
        return marketPositionStatus == ISportsAMMV2ResultManager.MarketPositionStatus.Cancelled;
    }

    /**
     * @notice Retrieves the results for a specific market.
     * @param _gameId The identifier of the game.
     * @param _typeId The type of the market.
     * @param _playerId The identifier of the player.
     * @return results An array of integers representing the results of the market.
     */
    function getResultsPerMarket(
        bytes32 _gameId,
        uint16 _typeId,
        uint24 _playerId
    ) external view returns (int24[] memory results) {
        return resultsPerMarket[_gameId][_typeId][_playerId];
    }

    /**
     * @notice Checks if the market is resolved and if a specific position is a winning one.
     * @param _gameId The identifier of the game.
     * @param _typeId The type of the market.
     * @param _playerId The identifier of the player.
     * @param _line The line associated with the market position.
     * @param _position The position index within the market.
     * @param _combinedPositions An array of combined positions related to the market.
     * @return isResolved True if the market is resolved, otherwise false.
     * @return isWinning True if the position is winning, otherwise false.
     */
    function isMarketResolvedAndPositionWinning(
        bytes32 _gameId,
        uint16 _typeId,
        uint24 _playerId,
        int24 _line,
        uint _position,
        ISportsAMMV2.CombinedPosition[] memory _combinedPositions
    ) external view returns (bool isResolved, bool isWinning) {
        (isResolved, isWinning) = _isMarketResolvedAndPositionWinning(
            _gameId,
            _typeId,
            _playerId,
            _line,
            _position,
            _combinedPositions
        );
    }

    /* ========== EXTERNAL WRITE FUNCTIONS ========== */

    /// @notice set result for specific markets and exercise losing tickets (up to numOfTicketsToExerciseOnGameResolution)
    /// @param _gameIds game IDs to set results for
    /// @param _typeIds type IDs to set results for
    /// @param _playerIds player IDs to set results for
    /// @param _results market results
    function setResultsPerMarkets(
        bytes32[] memory _gameIds,
        uint16[] memory _typeIds,
        uint24[] memory _playerIds,
        int24[][] memory _results
    ) external onlyWhitelistedAddresses(msg.sender) {
        require(
            _gameIds.length == _typeIds.length &&
                _typeIds.length == _playerIds.length &&
                _playerIds.length == _results.length,
            "Incorrect params"
        );
        ISportsAMMV2 sportsAMM = ISportsAMMV2(manager.sportsAMM());
        uint numOfTicketsToExercise = numOfTicketsToExerciseOnGameResolution;
        for (uint i; i < _gameIds.length; i++) {
            bytes32 gameId = _gameIds[i];
            //skip cancelled games
            if (isGameCancelled[gameId]) {
                continue;
            }

            uint16 typeId = _typeIds[i];
            uint24 playerId = _playerIds[i];
            int24[] memory results = _results[i];
            if (results[0] == CANCEL_ID) {
                _cancelMarket(gameId, typeId, playerId, 0);
            } else {
                ResultType resultType = resultTypePerMarketType[typeId];
                require(resultType != ResultType.Unassigned, "Result type not set");
                if (!areResultsPerMarketSet[gameId][typeId][playerId]) {
                    resultsPerMarket[gameId][typeId][playerId] = results;
                    areResultsPerMarketSet[gameId][typeId][playerId] = true;
                    if (numOfTicketsToExercise > 0) {
                        address[] memory marketTickets = manager.getTicketsPerMarket(
                            0,
                            numOfTicketsToExerciseOnGameResolution,
                            gameId,
                            typeId,
                            playerId
                        );
                        numOfTicketsToExercise = _exerciseLosingTickets(marketTickets, numOfTicketsToExercise, sportsAMM);
                    }
                    emit ResultsPerMarketSet(gameId, typeId, playerId, results);
                }
            }
        }
    }

    /// @notice cancel specific games
    /// @param _gameIds game IDs to cancel
    function cancelGames(bytes32[] memory _gameIds) external onlyWhitelistedAddresses(msg.sender) {
        for (uint i; i < _gameIds.length; i++) {
            bytes32 gameId = _gameIds[i];
            _cancelGame(gameId);
        }
    }

    /// @notice cancel specific game
    /// @param _gameId game ID to cancel
    function cancelGame(bytes32 _gameId) external onlyWhitelistedAddresses(msg.sender) {
        _cancelGame(_gameId);
    }

    function _cancelGame(bytes32 _gameId) internal {
        require(!isGameCancelled[_gameId], "Game already cancelled");
        isGameCancelled[_gameId] = true;
        emit GameCancelled(_gameId);
    }

    /// @notice cancel specific markets
    /// @param _gameIds game IDs to cancel
    /// @param _typeIds type IDs to cancel
    /// @param _playerIds player IDs to cancel
    function cancelMarkets(
        bytes32[] memory _gameIds,
        uint16[] memory _typeIds,
        uint24[] memory _playerIds,
        int24[] memory _lines
    ) external onlyWhitelistedAddresses(msg.sender) {
        require(
            _gameIds.length == _typeIds.length && _typeIds.length == _playerIds.length && _playerIds.length == _lines.length,
            "Incorrect params"
        );
        for (uint i; i < _gameIds.length; i++) {
            bytes32 gameId = _gameIds[i];
            uint16 typeId = _typeIds[i];
            uint24 playerId = _playerIds[i];
            int24 line = _lines[i];
            _cancelMarket(gameId, typeId, playerId, line);
        }
    }

    /// @notice cancel specific markets
    /// @param _gameId game ID to cancel
    /// @param _typeId type ID to cancel
    /// @param _playerId player ID to cancel
    /// @param _line player ID to cancel
    function cancelMarket(
        bytes32 _gameId,
        uint16 _typeId,
        uint24 _playerId,
        int24 _line
    ) external onlyWhitelistedAddresses(msg.sender) {
        _cancelMarket(_gameId, _typeId, _playerId, _line);
    }

    /// @notice cancel specific markets
    /// @param _gameId game ID to cancel
    /// @param _typeId type ID to cancel
    /// @param _playerId player IDs to cancel
    function _cancelMarket(bytes32 _gameId, uint16 _typeId, uint24 _playerId, int24 _line) internal {
        require(!_isMarketCancelled(_gameId, _typeId, _playerId, _line), "Market already cancelled");
        isMarketExplicitlyCancelled[_gameId][_typeId][_playerId][_line] = true;
        emit MarketExplicitlyCancelled(_gameId, _typeId, _playerId, _line);
    }

    /// @notice set result types for specific markets
    /// @param _marketTypeIds market type IDs to set result type for
    /// @param _resultTypes result types to set
    function setResultTypesPerMarketTypes(uint16[] memory _marketTypeIds, uint[] memory _resultTypes) external onlyOwner {
        require(_marketTypeIds.length == _resultTypes.length, "Incorrect params");
        for (uint i; i < _marketTypeIds.length; i++) {
            uint16 marketTypeId = _marketTypeIds[i];
            uint resultType = _resultTypes[i];

            require(
                resultType > uint(ResultType.Unassigned) && resultType <= uint(ResultType.Spread),
                "Invalid result type"
            );
            resultTypePerMarketType[marketTypeId] = ResultType(resultType);
            emit ResultTypePerMarketTypeSet(marketTypeId, resultType);
        }
    }

    /* ========== INTERNAL FUNCTIONS ========== */

    function _isMarketResolvedInternal(
        bytes32 _gameId,
        uint16 _typeId,
        uint24 _playerId,
        int24 _line
    ) internal view returns (bool) {
        return areResultsPerMarketSet[_gameId][_typeId][_playerId] || _isMarketCancelled(_gameId, _typeId, _playerId, _line);
    }

    function _isMarketCancelled(
        bytes32 _gameId,
        uint16 _typeId,
        uint24 _playerId,
        int24 _line
    ) internal view returns (bool) {
        return
            isGameCancelled[_gameId] ||
            isMarketExplicitlyCancelled[_gameId][_typeId][_playerId][_line] ||
            isMarketExplicitlyCancelled[_gameId][_typeId][_playerId][0];
    }

    function _getMarketPositionStatus(
        bytes32 _gameId,
        uint16 _typeId,
        uint24 _playerId,
        int24 _line,
        uint position,
        ISportsAMMV2.CombinedPosition[] memory combinedPositions
    ) internal view returns (ISportsAMMV2ResultManager.MarketPositionStatus status) {
        ResultType resultType = resultTypePerMarketType[_typeId];
        return
            resultType == ResultType.CombinedPositions
                ? _getMarketCombinedPositionsStatus(_gameId, combinedPositions)
                : _getMarketSinglePositionStatus(_gameId, _typeId, _playerId, _line, position);
    }

    function _getMarketSinglePositionStatus(
        bytes32 _gameId,
        uint16 _typeId,
        uint24 _playerId,
        int24 _line,
        uint position
    ) internal view returns (ISportsAMMV2ResultManager.MarketPositionStatus status) {
        if (_isMarketCancelled(_gameId, _typeId, _playerId, _line)) {
            return ISportsAMMV2ResultManager.MarketPositionStatus.Cancelled;
        }

        if (areResultsPerMarketSet[_gameId][_typeId][_playerId]) {
            int24[] memory marketResults = resultsPerMarket[_gameId][_typeId][_playerId];
            ResultType resultType = resultTypePerMarketType[_typeId];

            for (uint i = 0; i < marketResults.length; i++) {
                int marketResult = marketResults[i];
                if (resultType == ResultType.OverUnder || resultType == ResultType.Spread) {
                    if (marketResult == _line) {
                        return ISportsAMMV2ResultManager.MarketPositionStatus.Cancelled;
                    } else {
                        OverUnderType winningPosition = resultType == ResultType.Spread
                            ? (marketResult < _line ? OverUnderType.Over : OverUnderType.Under)
                            : (marketResult > _line ? OverUnderType.Over : OverUnderType.Under);
                        if (uint(winningPosition) == position) {
                            return ISportsAMMV2ResultManager.MarketPositionStatus.Winning;
                        }
                    }
                } else {
                    if (marketResult == int(position)) {
                        return ISportsAMMV2ResultManager.MarketPositionStatus.Winning;
                    }
                }
            }

            return ISportsAMMV2ResultManager.MarketPositionStatus.Losing;
        }

        return ISportsAMMV2ResultManager.MarketPositionStatus.Open;
    }

    function _getMarketCombinedPositionsStatus(
        bytes32 _gameId,
        ISportsAMMV2.CombinedPosition[] memory combinedPositions
    ) internal view returns (ISportsAMMV2ResultManager.MarketPositionStatus status) {
        bool hasCancelledPosition = false;
        bool hasOpenPosition = false;

        for (uint i = 0; i < combinedPositions.length; i++) {
            ISportsAMMV2.CombinedPosition memory combinedPosition = combinedPositions[i];
            ISportsAMMV2ResultManager.MarketPositionStatus combinedPositionStatus = _getMarketSinglePositionStatus(
                _gameId,
                combinedPosition.typeId,
                0,
                combinedPosition.line,
                combinedPosition.position
            );
            if (combinedPositionStatus == ISportsAMMV2ResultManager.MarketPositionStatus.Losing) {
                return ISportsAMMV2ResultManager.MarketPositionStatus.Losing;
            }
            if (!hasCancelledPosition) {
                hasCancelledPosition = combinedPositionStatus == ISportsAMMV2ResultManager.MarketPositionStatus.Cancelled;
            }
            if (!hasOpenPosition) {
                hasOpenPosition = combinedPositionStatus == ISportsAMMV2ResultManager.MarketPositionStatus.Open;
            }
        }

        return
            hasCancelledPosition
                ? ISportsAMMV2ResultManager.MarketPositionStatus.Cancelled
                : (
                    hasOpenPosition
                        ? ISportsAMMV2ResultManager.MarketPositionStatus.Open
                        : ISportsAMMV2ResultManager.MarketPositionStatus.Winning
                );
    }

    function _exerciseLosingTickets(
        address[] memory _tickets,
        uint _numOfTicketsToExercise,
        ISportsAMMV2 sportsAMM
    ) internal returns (uint numOfTicketsToExercise) {
        numOfTicketsToExercise = _numOfTicketsToExercise;
        for (uint i; i < _tickets.length; i++) {
            if (numOfTicketsToExercise == 0) {
                break;
            }
            Ticket ticket = Ticket(_tickets[i]);
            if (ticket.isTicketExercisable() && !ticket.isUserTheWinner()) {
                sportsAMM.handleTicketResolving(address(ticket), ISportsAMMV2.TicketAction.Exercise);
                numOfTicketsToExercise--;
            }
        }
    }

    function _isMarketResolved(
        bytes32 _gameId,
        uint16 _typeId,
        uint24 _playerId,
        int24 _line,
        ISportsAMMV2.CombinedPosition[] memory combinedPositions
    ) internal view returns (bool isResolved) {
        if (isGameCancelled[_gameId]) {
            isResolved = true;
        } else {
            ResultType resultType = resultTypePerMarketType[_typeId];
            if (resultType == ResultType.CombinedPositions) {
                isResolved = true;
                for (uint i = 0; i < combinedPositions.length; i++) {
                    ISportsAMMV2.CombinedPosition memory combinedPosition = combinedPositions[i];
                    bool isCombinedPositionMarketResolved = _isMarketResolvedInternal(
                        _gameId,
                        combinedPosition.typeId,
                        0,
                        combinedPosition.line
                    );
                    if (!isCombinedPositionMarketResolved) {
                        isResolved = false;
                        break;
                    }
                }
            } else {
                isResolved = _isMarketResolvedInternal(_gameId, _typeId, _playerId, _line);
            }
        }
    }

    function _isMarketResolvedAndPositionWinning(
        bytes32 _gameId,
        uint16 _typeId,
        uint24 _playerId,
        int24 _line,
        uint _position,
        ISportsAMMV2.CombinedPosition[] memory _combinedPositions
    ) internal view returns (bool isResolved, bool isWinning) {
        isResolved = _isMarketResolved(_gameId, _typeId, _playerId, _line, _combinedPositions);
        ISportsAMMV2ResultManager.MarketPositionStatus marketPositionStatus = _getMarketPositionStatus(
            _gameId,
            _typeId,
            _playerId,
            _line,
            _position,
            _combinedPositions
        );
        isWinning =
            marketPositionStatus == ISportsAMMV2ResultManager.MarketPositionStatus.Winning ||
            marketPositionStatus == ISportsAMMV2ResultManager.MarketPositionStatus.Cancelled;
    }

    function _isWinningMarketPosition(
        bytes32 _gameId,
        uint16 _typeId,
        uint24 _playerId,
        int24 _line,
        uint _position,
        ISportsAMMV2.CombinedPosition[] memory _combinedPositions
    ) internal view returns (bool) {
        ISportsAMMV2ResultManager.MarketPositionStatus marketPositionStatus = _getMarketPositionStatus(
            _gameId,
            _typeId,
            _playerId,
            _line,
            _position,
            _combinedPositions
        );
        return
            marketPositionStatus == ISportsAMMV2ResultManager.MarketPositionStatus.Winning ||
            marketPositionStatus == ISportsAMMV2ResultManager.MarketPositionStatus.Cancelled;
    }

    modifier onlyWhitelistedAddresses(address sender) {
        require(
            sender == owner ||
                sender == chainlinkResolver ||
                manager.isWhitelistedAddress(sender, ISportsAMMV2Manager.Role.MARKET_RESOLVING),
            "Invalid sender"
        );
        _;
    }

    /* ========== SETTERS ========== */

    /// @notice sets the sports manager contract address
    /// @param _manager the address of sports manager contract
    function setSportsManager(address _manager) external onlyOwner {
        require(_manager != address(0), "Invalid address");
        manager = ISportsAMMV2Manager(_manager);
        emit SetSportsManager(_manager);
    }

    /// @notice sets the address of a contract that can resolve markets via chainlink node
    /// @param _chainlinkResolver the address of chainlink node client
    function setChainlinkResolver(address _chainlinkResolver) external onlyOwner {
        require(_chainlinkResolver != address(0), "Invalid address");
        chainlinkResolver = _chainlinkResolver;
        emit SetChainlinkResolver(_chainlinkResolver);
    }

    /// @notice sets the number of tickets to automatically exercise when resolving games
    /// @param _numOfTicketsToExercise the maximum number of tickets to exercise per game resolution
    function setNumOfTicketsToExerciseOnGameResolution(uint _numOfTicketsToExercise) external onlyOwner {
        numOfTicketsToExerciseOnGameResolution = _numOfTicketsToExercise;
        emit SetNumOfTicketsToExerciseOnGameResolution(_numOfTicketsToExercise);
    }

    /* ========== EVENTS ========== */

    event ResultsPerMarketSet(bytes32 gameId, uint16 typeId, uint24 playerId, int24[] result);
    event GameCancelled(bytes32 gameId);
    event MarketExplicitlyCancelled(bytes32 gameId, uint16 typeId, uint24 playerId, int24 line);
    event ResultTypePerMarketTypeSet(uint16 marketTypeId, uint resultType);

    event SetSportsManager(address manager);
    event SetChainlinkResolver(address resolver);
    event SetNumOfTicketsToExerciseOnGameResolution(uint numOfTicketsToExercise);
}

contracts/core/SGPTrading/SGPTradingProc.content:
// SPDX-License-Identifier: MIT

pragma solidity ^0.8.0;

// external
import "@chainlink/contracts/src/v0.8/ChainlinkClient.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/utils/Strings.sol";

import "../../interfaces/ISportsAMMV2.sol";
import "../../interfaces/IFreeBetsHolder.sol";
import "../../interfaces/ISGPTradingProcessor.sol";
import "../../core/AMM/SportsAMMV2Utils.sol";

contract SGPTradingProcessor is ChainlinkClient, Ownable, Pausable {
    using Strings for uint;
    using Strings for int256;
    using Strings for uint8;
    using Chainlink for Chainlink.Request;
    using SafeERC20 for IERC20;

    uint private constant ONE = 1e18;

    ISportsAMMV2 public sportsAMM;

    address public freeBetsHolder;

    bytes32 public jobSpecId;

    uint public paymentAmount;

    uint public maxAllowedExecutionDelay = 60;

    mapping(bytes32 => ISGPTradingProcessor.SGPTradeData) public requestIdToTradeData;
    mapping(bytes32 => address) public requestIdToRequester;
    mapping(bytes32 => bool) public requestIdToFulfillAllowed;
    mapping(bytes32 => bool) public requestIdFulfilled;
    mapping(bytes32 => uint) public timestampPerRequest;

    uint public requestCounter;
    mapping(uint => bytes32) public counterToRequestId;
    mapping(bytes32 => address) public requestIdToTicketId;

    constructor(
        address _link,
        address _oracle,
        address _sportsAMM,
        bytes32 _jobSpecId,
        uint _paymentAmount
    ) Ownable(msg.sender) {
        setChainlinkToken(_link);
        setChainlinkOracle(_oracle);
        sportsAMM = ISportsAMMV2(_sportsAMM);
        jobSpecId = _jobSpecId;
        paymentAmount = _paymentAmount;
    }

    /// @notice requests SGP trade
    /// @param _sgpTradeData for which to request a SGP trade
    function requestSGPTrade(
        ISGPTradingProcessor.SGPTradeData calldata _sgpTradeData
    ) external whenNotPaused returns (bytes32 requestId) {
        require(_sgpTradeData._tradeData.length > 1, "SGP not possible for a single game");

        ISportsAMMV2RiskManager riskManager = sportsAMM.riskManager();
        bool hasSameGamePair;
        for (uint i = 0; i < _sgpTradeData._tradeData.length; ++i) {
            require(
                riskManager.sgpOnSportIdEnabled(_sgpTradeData._tradeData[i].sportId),
                "SGP trading not enabled on _sportId"
            );

            if (!hasSameGamePair) {
                for (uint j = i + 1; j < _sgpTradeData._tradeData.length; ++j) {
                    if (_sgpTradeData._tradeData[i].gameId == _sgpTradeData._tradeData[j].gameId) {
                        hasSameGamePair = true;
                        break;
                    }
                }
            }
        }
        require(hasSameGamePair, "SGP requires at least two legs on the same game");

        SportsAMMV2Utils(sportsAMM.sportsAMMV2Utils()).checkTradeLimits(
            msg.sender,
            _sgpTradeData._buyInAmount,
            _sgpTradeData._collateral,
            _sgpTradeData._expectedQuote,
            _sgpTradeData._tradeData.length,
            sportsAMM
        );

        if (!_sgpTradeData._isLive) {
            // **Verify Merkle Proofs**
            _verifyMerkleProofs(_sgpTradeData._tradeData);
        }

        // **Process trade data**
        (
            string[] memory sportIds,
            string[] memory gameIds,
            string[] memory typeIds,
            string[] memory playerIds,
            string[] memory lines,
            string[] memory positions
        ) = _processTradeData(_sgpTradeData._tradeData);

        // **Create Chainlink request**
        Chainlink.Request memory req = buildChainlinkRequest(jobSpecId, address(this), this.fulfillSGPTrade.selector);

        req.addStringArray("sportIds", sportIds);
        req.addStringArray("gameIds", gameIds);
        req.addStringArray("typeIds", typeIds);
        req.addStringArray("playerIds", playerIds);
        req.addStringArray("positions", positions);
        req.addStringArray("lines", lines);
        req.addUint("buyInAmount", _sgpTradeData._buyInAmount);
        req.addUint("expectedQuote", _sgpTradeData._expectedQuote);
        req.addUint("additionalSlippage", _sgpTradeData._additionalSlippage);
        req.add("isLive", _sgpTradeData._isLive ? "true" : "false");
        req.add("requester", Strings.toHexString(msg.sender));

        requestId = sendChainlinkRequest(req, paymentAmount);
        timestampPerRequest[requestId] = block.timestamp;
        requestIdToTradeData[requestId] = _sgpTradeData;
        requestIdToRequester[requestId] = msg.sender;

        counterToRequestId[requestCounter] = requestId;

        emit SGPTradeRequested(msg.sender, requestCounter, requestId, _sgpTradeData);
        requestCounter++;
    }

    /// @notice Verifies Merkle proofs for the given trade data
    /// @param tradeData The trade data array
    function _verifyMerkleProofs(ISportsAMMV2.TradeData[] calldata tradeData) internal view {
        uint numOfMarkets = tradeData.length;
        bytes32[] memory gameIdsBytes = new bytes32[](numOfMarkets);

        for (uint i; i < numOfMarkets; ++i) {
            gameIdsBytes[i] = tradeData[i].gameId;
        }

        sportsAMM.riskManager().batchVerifyMerkleTree(tradeData, sportsAMM.getRootsPerGames(gameIdsBytes));
    }

    /// @notice Processes trade data and returns formatted arrays
    /// @param tradeData The trade data array
    /// @return sportIds Formatted sport IDs
    /// @return gameIds Formatted game IDs as strings
    /// @return typeIds Formatted type IDs
    /// @return playerIds Formatted player IDs
    /// @return lines Formatted lines
    /// @return positions Formatted positions
    function _processTradeData(
        ISportsAMMV2.TradeData[] calldata tradeData
    )
        internal
        pure
        returns (
            string[] memory sportIds,
            string[] memory gameIds,
            string[] memory typeIds,
            string[] memory playerIds,
            string[] memory lines,
            string[] memory positions
        )
    {
        uint numOfMarkets = tradeData.length;
        sportIds = new string[](numOfMarkets);
        gameIds = new string[](numOfMarkets);
        typeIds = new string[](numOfMarkets);
        playerIds = new string[](numOfMarkets);
        lines = new string[](numOfMarkets);
        positions = new string[](numOfMarkets);

        for (uint i = 0; i < numOfMarkets; ++i) {
            ISportsAMMV2.TradeData memory marketTradeData = tradeData[i];

            sportIds[i] = uint256(marketTradeData.sportId).toString();
            gameIds[i] = bytes32ToString(marketTradeData.gameId);
            typeIds[i] = uint256(marketTradeData.typeId).toString();
            playerIds[i] = uint256(marketTradeData.playerId).toString();
            lines[i] = int256(marketTradeData.line).toStringSigned();
            positions[i] = uint256(marketTradeData.position).toString();
        }
    }

    /// @notice fulfillSGPTrade
    /// @param _requestId which is being fulfilled
    /// @param _allow whether the sgp trade should go through
    /// @param _approvedQuote what will be the actual payout
    function fulfillSGPTrade(
        bytes32 _requestId,
        bool _allow,
        uint _approvedQuote
    ) external whenNotPaused recordChainlinkFulfillment(_requestId) {
        //might be redundant as already done by Chainlink Client, but making double sure
        require(!requestIdFulfilled[_requestId], "Request ID already fulfilled");
        require((timestampPerRequest[_requestId] + maxAllowedExecutionDelay) > block.timestamp, "Request timed out");

        ISGPTradingProcessor.SGPTradeData memory sgpTradeData = requestIdToTradeData[_requestId];
        if (sgpTradeData._isLive) {
            // Align live markets trade data with risk manager requirements
            for (uint i = 0; i < sgpTradeData._tradeData.length; ++i) {
                sgpTradeData._tradeData[i].status = 0;
                sgpTradeData._tradeData[i].maturity = block.timestamp + 60;
            }
        }
        address requester = requestIdToRequester[_requestId];

        require(
            ((ONE * _approvedQuote) / sgpTradeData._expectedQuote) <= (ONE + sgpTradeData._additionalSlippage),
            "Slippage too high"
        );

        if (_allow) {
            address _createdTicket = sportsAMM.tradeSGP(
                sgpTradeData._tradeData,
                sgpTradeData._buyInAmount,
                _approvedQuote,
                requester,
                sgpTradeData._referrer,
                sgpTradeData._collateral,
                sgpTradeData._isLive
            );
            requestIdToTicketId[_requestId] = _createdTicket;

            if (requester == freeBetsHolder) {
                IFreeBetsHolder(freeBetsHolder).confirmSGPTrade(
                    _requestId,
                    _createdTicket,
                    sgpTradeData._buyInAmount,
                    sgpTradeData._collateral
                );
            }
        }
        requestIdToFulfillAllowed[_requestId] = _allow;
        requestIdFulfilled[_requestId] = true;

        emit SGPTradeFulfilled(requester, _requestId, _allow, sgpTradeData, _approvedQuote, block.timestamp);
    }

    /// @notice withdraw collateral in the contract
    /// @param collateral the collateral address
    /// @param recipient the recipient of the collateral
    function withdrawCollateral(address collateral, address recipient) external onlyOwner {
        IERC20(collateral).safeTransfer(recipient, IERC20(collateral).balanceOf(address(this)));
    }

    //////////// SETTERS

    /// @notice pause sgp trading
    /// @param _setPausing whether to pause or unpause
    function setPaused(bool _setPausing) external onlyOwner {
        _setPausing ? _pause() : _unpause();
    }

    /// @notice setConfiguration
    /// @param _link paymentAmount token
    /// @param _oracle CL node that will execute the requests
    /// @param _sportsAMM address
    /// @param _jobSpecId CL node job spec ID
    /// @param _paymentAmount amount of paymentAmount token for each request
    function setConfiguration(
        address _link,
        address _oracle,
        address _sportsAMM,
        bytes32 _jobSpecId,
        uint _paymentAmount
    ) external onlyOwner {
        setChainlinkToken(_link);
        setChainlinkOracle(_oracle);
        sportsAMM = ISportsAMMV2(_sportsAMM);
        jobSpecId = _jobSpecId;
        paymentAmount = _paymentAmount;
        emit ContextReset(_link, _oracle, _sportsAMM, _jobSpecId, _paymentAmount);
    }

    /// @notice sets the FreeBetsHolder address, required for handling ticket claiming via FreeBetsHolder
    function setFreeBetsHolder(address _freeBetsHolder) external onlyOwner {
        freeBetsHolder = _freeBetsHolder;
        emit SetFreeBetsHolder(_freeBetsHolder);
    }

    /// @notice setMaxAllowedExecutionDelay
    /// @param _maxAllowedExecutionDelay maximum allowed buffer for the CL request to be executed, defaulted at 60 seconds
    function setMaxAllowedExecutionDelay(uint _maxAllowedExecutionDelay) external onlyOwner {
        maxAllowedExecutionDelay = _maxAllowedExecutionDelay;
        emit SetMaxAllowedExecutionDelay(_maxAllowedExecutionDelay);
    }

    //////////// GETTERS

    /// @notice gets trade data struct for specified request ID
    /// @param _requestId request ID
    /// @return sgpTradeData Stored SGPTradeData for request ID
    function getTradeData(bytes32 _requestId) external view returns (ISGPTradingProcessor.SGPTradeData memory) {
        return requestIdToTradeData[_requestId];
    }

    //// UTILITY

    // Helper function to convert bytes32 to string
    function bytes32ToString(bytes32 _bytes32) internal pure returns (string memory) {
        uint8 i = 0;
        while (i < 32 && _bytes32[i] != 0) {
            i++;
        }
        bytes memory bytesArray = new bytes(i);
        for (uint8 j = 0; j < i; j++) {
            bytesArray[j] = _bytes32[j];
        }
        return string(bytesArray);
    }

    /////// EVENTS
    event ContextReset(address _link, address _oracle, address _sportsAMM, bytes32 _jobSpecId, uint _paymentAmount);
    event SGPTradeRequested(
        address requester,
        uint requestCounter,
        bytes32 requestId,
        ISGPTradingProcessor.SGPTradeData sgpTradeData
    );
    event SGPTradeFulfilled(
        address requester,
        bytes32 requestId,
        bool _allow,
        ISGPTradingProcessor.SGPTradeData sgpTradeData,
        uint _approvedQuote,
        uint timestamp
    );
    event SetMaxAllowedExecutionDelay(uint _maxAllowedExecutionDelay);
    event SetFreeBetsHolder(address _freeBetsHolder);
}

contracts/core/StakingThalesBetting/Stak.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@thales-dao/contracts/contracts/interfaces/IStakingThales.sol";

import "../../utils/proxy/ProxyOwned.sol";
import "../../utils/proxy/ProxyPausable.sol";
import "../../utils/proxy/ProxyReentrancyGuard.sol";
import "../../utils/libraries/AddressSetLib.sol";

import "../../interfaces/ISportsAMMV2.sol";
import "../../interfaces/ILiveTradingProcessor.sol";

import "./../AMM/Ticket.sol";

contract StakingThalesBettingProxy is Initializable, ProxyOwned, ProxyPausable, ProxyReentrancyGuard {
    using SafeERC20 for IERC20;
    using AddressSetLib for AddressSetLib.AddressSet;

    uint private constant MAX_APPROVAL = type(uint256).max;

    ISportsAMMV2 public sportsAMM;

    ILiveTradingProcessor public liveTradingProcessor;

    IStakingThales public stakingThales;

    IERC20 public stakingCollateral;

    mapping(address => address) public ticketToUser;

    mapping(bytes32 => address) public liveRequestsPerUser;

    // stores active tickets per user
    mapping(address => AddressSetLib.AddressSet) internal activeTicketsPerUser;

    // stores resolved tickets per user
    mapping(address => AddressSetLib.AddressSet) internal resolvedTicketsPerUser;

    /* ========== CONSTRUCTOR ========== */

    function initialize(
        address _owner,
        address _sportsAMMV2,
        address _liveTradingProcessor,
        address _stakingThales,
        address _stakingToken
    ) external initializer {
        setOwner(_owner);
        initNonReentrant();
        sportsAMM = ISportsAMMV2(_sportsAMMV2);
        liveTradingProcessor = ILiveTradingProcessor(_liveTradingProcessor);
        stakingThales = IStakingThales(_stakingThales);
        stakingCollateral = IERC20(_stakingToken);
        stakingCollateral.approve(_stakingThales, MAX_APPROVAL);
        stakingCollateral.approve(_sportsAMMV2, MAX_APPROVAL);
        stakingCollateral.approve(_liveTradingProcessor, MAX_APPROVAL);
    }

    /// @notice buy a system bet ticket for a user if he has enough staked tokens
    function tradeSystemBet(
        ISportsAMMV2.TradeData[] calldata _tradeData,
        uint _buyInAmount,
        uint _expectedQuote,
        uint _additionalSlippage,
        address _referrer,
        uint8 _systemBetDenominator
    ) external notPaused nonReentrant {
        _trade(_tradeData, _buyInAmount, _expectedQuote, _additionalSlippage, _referrer, _systemBetDenominator);
    }

    /// @notice buy a ticket for a user if he has enough staked tokens
    function trade(
        ISportsAMMV2.TradeData[] calldata _tradeData,
        uint _buyInAmount,
        uint _expectedQuote,
        uint _additionalSlippage,
        address _referrer
    ) external notPaused nonReentrant {
        _trade(_tradeData, _buyInAmount, _expectedQuote, _additionalSlippage, _referrer, 0);
    }

    function _trade(
        ISportsAMMV2.TradeData[] calldata _tradeData,
        uint _buyInAmount,
        uint _expectedQuote,
        uint _additionalSlippage,
        address _referrer,
        uint8 _systemBetDenominator
    ) internal {
        // signal decrease of stakingAmount
        stakingThales.decreaseAndTransferStakedThales(msg.sender, _buyInAmount);
        address _createdTicket;
        if (_systemBetDenominator > 0) {
            _createdTicket = sportsAMM.tradeSystemBet(
                _tradeData,
                _buyInAmount,
                _expectedQuote,
                _additionalSlippage,
                _referrer,
                address(stakingCollateral),
                false,
                _systemBetDenominator
            );
        } else {
            _createdTicket = sportsAMM.trade(
                _tradeData,
                _buyInAmount,
                _expectedQuote,
                _additionalSlippage,
                _referrer,
                address(stakingCollateral),
                false
            );
        }
        ticketToUser[_createdTicket] = msg.sender;
        activeTicketsPerUser[msg.sender].add(_createdTicket);
        emit StakingTokensTrade(_createdTicket, _buyInAmount, msg.sender, false);
    }

    /// @notice request a live ticket for a user if he has enough staked tokens
    function tradeLive(ILiveTradingProcessor.LiveTradeData calldata _liveTradeData) external notPaused {
        require(_liveTradeData._collateral == address(stakingCollateral), "Use Staking collateral for live trade");
        bytes32 _requestId = liveTradingProcessor.requestLiveTrade(_liveTradeData);
        liveRequestsPerUser[_requestId] = msg.sender;
        emit StakingTokensLiveTradeRequested(msg.sender, _liveTradeData._buyInAmount, _requestId);
    }

    /// @notice pre-confirm a live ticket purchase by transfering funds from the staking contract to this contract
    function preConfirmLiveTrade(bytes32 requestId, uint _buyInAmount) external notPaused nonReentrant {
        require(msg.sender == address(liveTradingProcessor), "Only callable from LiveTradingProcessor");
        address _user = liveRequestsPerUser[requestId];
        require(_user != address(0), "Unknown live ticket");
        // signal decrease of stakingAmount
        stakingThales.decreaseAndTransferStakedThales(_user, _buyInAmount);
    }

    /// @notice confirm a live ticket purchase. As live betting is a 2 step approach, the LiveTradingProcessor needs this method as callback so that the correct amount is deducted from the this contract balance
    function confirmLiveTrade(bytes32 requestId, address _createdTicket, uint _buyInAmount) external notPaused nonReentrant {
        require(msg.sender == address(liveTradingProcessor), "Only callable from LiveTradingProcessor");
        address _user = liveRequestsPerUser[requestId];
        require(_user != address(0), "Unknown live ticket");

        ticketToUser[_createdTicket] = _user;

        activeTicketsPerUser[_user].add(_createdTicket);

        emit StakingTokensTrade(_createdTicket, _buyInAmount, _user, true);
    }

    /// @notice callback from sportsAMM on ticket exercize if owner is this contract. The net winnings are sent to the user's staked balance on the staking contract
    function confirmTicketResolved(address _resolvedTicket) external {
        require(msg.sender == address(sportsAMM), "Only allowed from SportsAMM");

        address _user = ticketToUser[_resolvedTicket];
        require(_user != address(0), "Unknown ticket");
        require(activeTicketsPerUser[_user].contains(_resolvedTicket), "Unknown active ticket");

        uint _exercized = Ticket(_resolvedTicket).finalPayout();
        if (_exercized > 0) {
            stakingThales.increaseAndTransferStakedThales(_user, _exercized);
        }
        emit StakingTokensTicketResolved(_resolvedTicket, _user, _exercized);

        activeTicketsPerUser[_user].remove(_resolvedTicket);
        resolvedTicketsPerUser[_user].add(_resolvedTicket);
    }

    /// @notice admin method to retrieve stuck funds if needed
    function retrieveFunds(IERC20 _collateral, uint _amount) external onlyOwner {
        _collateral.safeTransfer(msg.sender, _amount);
    }

    /* ========== GETTERS ========== */
    /// @notice gets batch of active tickets per user
    /// @param _index start index
    /// @param _pageSize batch size
    /// @param _user to get active tickets for
    /// @return activeTickets
    function getActiveTicketsPerUser(uint _index, uint _pageSize, address _user) external view returns (address[] memory) {
        return activeTicketsPerUser[_user].getPage(_index, _pageSize);
    }

    /// @notice gets number of active tickets per user
    /// @param _user to get number of active tickets for
    /// @return numOfActiveTickets
    function numOfActiveTicketsPerUser(address _user) external view returns (uint) {
        return activeTicketsPerUser[_user].elements.length;
    }

    /// @notice gets batch of resolved tickets per user
    /// @param _index start index
    /// @param _pageSize batch size
    /// @param _user to get resolved tickets for
    /// @return resolvedTickets
    function getResolvedTicketsPerUser(uint _index, uint _pageSize, address _user) external view returns (address[] memory) {
        return resolvedTicketsPerUser[_user].getPage(_index, _pageSize);
    }

    /// @notice gets number of resolved tickets per user
    /// @param _user to get number of resolved tickets for
    /// @return numOfResolvedTickets
    function numOfResolvedTicketsPerUser(address _user) external view returns (uint) {
        return resolvedTicketsPerUser[_user].elements.length;
    }

    /* ========== SETTERS ========== */

    /// @notice sets new StakingThales address
    /// @param _stakingThales new staking thales address
    function setStakingThales(address _stakingThales) external onlyOwner {
        if (address(stakingThales) != address(0) && address(stakingCollateral) != address(0)) {
            stakingCollateral.approve(address(stakingThales), 0);
        }
        stakingThales = IStakingThales(_stakingThales);
        if (_stakingThales != address(0) && address(stakingCollateral) != address(0)) {
            stakingCollateral.approve(_stakingThales, MAX_APPROVAL);
        }
        emit SetStakingThales(_stakingThales);
    }

    /// @notice sets new SportsAMM
    /// @param _sportsAMM new sportsAMM address
    function setSportsAMM(address _sportsAMM) external onlyOwner {
        if (address(sportsAMM) != address(0) && address(stakingCollateral) != address(0)) {
            stakingCollateral.approve(address(sportsAMM), 0);
        }
        sportsAMM = ISportsAMMV2(_sportsAMM);
        if (_sportsAMM != address(0) && address(stakingCollateral) != address(0)) {
            stakingCollateral.approve(_sportsAMM, MAX_APPROVAL);
        }
        emit SetSportsAMM(_sportsAMM);
    }

    /// @notice sets new LiveTradingProcessor
    /// @param _liveTradingProcessor new liveTradingProcessor address
    function setLiveTradingProcessor(address _liveTradingProcessor) external onlyOwner {
        if (address(liveTradingProcessor) != address(0) && address(stakingCollateral) != address(0)) {
            stakingCollateral.approve(address(liveTradingProcessor), 0);
        }
        liveTradingProcessor = ILiveTradingProcessor(_liveTradingProcessor);
        if (_liveTradingProcessor != address(0) && address(stakingCollateral) != address(0)) {
            stakingCollateral.approve(_liveTradingProcessor, MAX_APPROVAL);
        }
        emit SetLiveTradingProcessor(_liveTradingProcessor);
    }

    /// @notice sets new Staking collateral
    /// @param _stakingCollateral new stakingCollateral address
    function setStakingCollateral(address _stakingCollateral) external onlyOwner {
        if (address(stakingCollateral) != address(0)) {
            stakingCollateral.approve(address(stakingThales), 0);
            stakingCollateral.approve(address(sportsAMM), 0);
            stakingCollateral.approve(address(liveTradingProcessor), 0);
        }
        stakingCollateral = IERC20(_stakingCollateral);
        if (_stakingCollateral != address(0)) {
            stakingCollateral.approve(address(stakingThales), MAX_APPROVAL);
            stakingCollateral.approve(address(sportsAMM), MAX_APPROVAL);
            stakingCollateral.approve(address(liveTradingProcessor), MAX_APPROVAL);
        }
        emit SetStakingCollateral(_stakingCollateral);
    }

    /* ========== EVENTS ========== */

    event StakingTokensTrade(address createdTicket, uint buyInAmount, address user, bool isLive);
    event StakingTokensTicketResolved(address ticket, address user, uint earned);
    event StakingTokensLiveTradeRequested(address user, uint buyInAmount, bytes32 requestId);
    event SetStakingThales(address stakingThales);
    event SetSportsAMM(address sportsAMM);
    event SetLiveTradingProcessor(address liveTradingProcessor);
    event SetStakingCollateral(address stakingCollateral);
}

contracts/interfaces/ICasinoCoreV2.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/// @title ICasinoCoreV2
/// @author Overtime
/// @notice Treasury + shared services used by every V2 casino game. Holds liquidity, VRF config,
/// supported collateral, free-bets and referrals wiring, plus a per-game P&L circuit breaker.
/// Games are registered by the owner and call into this contract for funds, randomness, and
/// settlement bookkeeping. Existing v1 games are NOT migrated — they keep their own balances
interface ICasinoCoreV2 {
    /* ========== ENUMS ========== */

    /// @notice Reasons a game may be inactive for new bets
    enum GameInactiveReason {
        NONE,
        NOT_REGISTERED,
        TREASURY_PAUSED,
        GAME_PAUSED,
        AUTO_PAUSED
    }

    /* ========== EVENTS ========== */

    event GameRegistered(address indexed game);
    event GameDeregistered(address indexed game);
    event GamePauseChanged(address indexed game, bool paused);
    event GameAutoPaused(address indexed game, int256 houseNetUsd, uint256 maxNetLossUsd);
    event GameCircuitBreakerReset(address indexed game);
    event MaxNetLossPerGameUsdChanged(address indexed game, uint256 value);
    event DefaultMaxNetLossPerGameUsdChanged(uint256 value);

    event CollateralConfigChanged(address indexed collateral, bytes32 currencyKey, bool supported);
    event RiskParamsChanged(uint256 maxProfitUsd, uint256 cancelTimeout);
    event MaxProfitUsdOverrideChanged(address indexed game, uint256 value);
    event MinBetPerGameUsdChanged(address indexed game, uint256 value);
    event MaxBetPerGameUsdChanged(address indexed game, uint256 value);
    event AddressesChanged(
        address manager,
        address priceFeed,
        address vrfCoordinator,
        address freeBetsHolder,
        address referrals
    );
    event VrfConfigChanged(
        uint256 subscriptionId,
        bytes32 keyHash,
        uint32 callbackGasLimit,
        uint16 requestConfirmations,
        bool nativePayment
    );
    event WithdrawnCollateral(address indexed collateral, address indexed recipient, uint256 amount);

    event StakePulled(address indexed game, address indexed user, address indexed collateral, uint256 amount);
    event FreeBetUsed(address indexed game, address indexed user, address indexed collateral, uint256 amount);
    event ReservationChanged(address indexed game, address indexed collateral, int256 delta, uint256 totalReserved);
    event PayoutSent(
        address indexed game,
        address indexed user,
        address indexed collateral,
        uint256 amount,
        bool isFreeBet,
        uint256 originalStake
    );
    event SettlementRecorded(
        address indexed game,
        address indexed collateral,
        uint256 stake,
        uint256 payout,
        int256 newHouseNetUsd
    );
    /// @notice Emitted when `recordSettlement` would underflow `pendingStakesPerCollateral`
    /// and clamps to zero instead. Expected during the migration window for in-flight bets
    /// placed before pending-stake tracking was introduced; outside that window it indicates
    /// accounting drift in the calling game (settled `stake` exceeds what was pulled). Off-chain
    /// monitoring should alert if this fires unexpectedly — drift makes `withdrawCollateral`'s
    /// safety floor (`reserved + pending`) too loose, loosening the over-drain guard
    event PendingStakesClamped(address indexed game, address indexed collateral, uint256 stake, uint256 pendingBefore);
    event RandomWordsRequested(address indexed game, uint256 indexed requestId, uint32 numWords);
    event RandomWordsFulfilled(address indexed game, uint256 indexed requestId);

    event ReferrerSet(address indexed user, address indexed referrer);
    event ReferrerPaid(address indexed referrer, address indexed user, uint256 amount, uint256 stake, address collateral);
    event ReferrerPayoutFailed(
        address indexed referrer,
        address indexed user,
        uint256 amount,
        uint256 stake,
        address collateral
    );

    /// @notice Emitted when `confirmCasinoBetResolved` reverts on the FreeBetsHolder during a
    /// payout. The token transfer to FBH already happened — funds are stuck in FBH but the
    /// casino settlement completes
    event FreeBetConfirmFailed(
        address indexed game,
        address indexed user,
        address indexed collateral,
        uint256 amount,
        uint256 originalStake
    );

    /// @notice Emitted when `recordSettlement` couldn't convert collateral to USD (price feed
    /// reverted). The settlement bookkeeping still completes; the circuit-breaker gauge is
    /// not updated for this round
    event SettlementUsdConversionFailed(address indexed game, address indexed collateral, uint256 stake, uint256 payout);

    /* ========== GAME-FACING METHODS (only callable by registered active games) ========== */

    /// @notice Pulls `amount` of `collateral` from `user` into core. User must have approved core
    function pullFromUser(address user, address collateral, uint256 amount) external;

    /// @notice Routes a free-bet draw through core to the FreeBetsHolder
    function useFreeBet(address user, address collateral, uint256 amount) external;

    /// @notice Optionally records a referrer for a user before placing a bet
    function setReferrer(address referrer, address user) external;

    /// @notice Requests `numWords` random words from Chainlink VRF for the calling game.
    /// Treasury is the registered consumer; callback is dispatched back to the calling game
    function requestRandomWords(uint32 numWords) external returns (uint256 requestId);

    /// @notice Bumps the calling game's reservation for `collateral` by `amount`. Reverts if
    /// the resulting total reservation exceeds available bankroll
    function reserveOrRevert(address collateral, uint256 amount) external;

    /// @notice Releases `amount` from the calling game's reservation for `collateral`
    function releaseReservation(address collateral, uint256 amount) external;

    /// @notice Sends `amount` of `collateral` to `user`, or to FreeBetsHolder if `isFreeBet`
    /// @dev `originalStake` is forwarded to FreeBetsHolder.confirmCasinoBetResolved
    function payOut(address user, address collateral, uint256 amount, bool isFreeBet, uint256 originalStake) external;

    /// @notice Pays the user's referrer (if any), best-effort. Skipped on free-bet flows
    function payReferrer(address user, address collateral, uint256 stake) external;

    /// @notice Records a settled bet's stake and payout for circuit-breaker accounting.
    /// Triggers auto-pause if the calling game's running net loss exceeds its threshold
    function recordSettlement(address collateral, uint256 stake, uint256 payout) external;

    /* ========== PUBLIC VIEWS ========== */

    function isGameRegistered(address game) external view returns (bool);

    function gameInactiveReason(address game) external view returns (GameInactiveReason);

    function getCollateralPrice(address collateral) external view returns (uint256);

    function getUsdValue(address collateral, uint256 amount) external view returns (uint256);

    function collateralFromUsd(address collateral, uint256 usdAmount) external view returns (uint256);

    function getAvailableLiquidity(address collateral) external view returns (uint256);

    function reservedProfitPerCollateral(address collateral) external view returns (uint256);

    function reservedProfitPerGame(address game, address collateral) external view returns (uint256);

    function houseNetUsd(address game) external view returns (int256);

    function maxNetLossPerGameUsd(address game) external view returns (uint256);

    function gamePaused(address game) external view returns (bool);

    function gameAutoPaused(address game) external view returns (bool);

    function getRegisteredGames() external view returns (address[] memory);

    function freeBetsHolder() external view returns (address);

    function maxProfitUsd() external view returns (uint256);

    function maxProfitUsdOverride(address game) external view returns (uint256);

    function effectiveMaxProfitUsd(address game) external view returns (uint256);

    function minBetPerGameUsd(address game) external view returns (uint256);

    function maxBetPerGameUsd(address game) external view returns (uint256);

    function effectiveMinBetUsd(address game) external view returns (uint256);

    function effectiveMaxBetUsd(address game) external view returns (uint256);

    function cancelTimeout() external view returns (uint256);

    function supportedCollateral(address collateral) external view returns (bool);

    function usdc() external view returns (address);

    function weth() external view returns (address);

    function over() external view returns (address);

    function subscriptionId() external view returns (uint256);

    function keyHash() external view returns (bytes32);

    function callbackGasLimit() external view returns (uint32);

    function requestConfirmations() external view returns (uint16);

    function nativePayment() external view returns (bool);

    function priceFeedKeyPerCollateral(address collateral) external view returns (bytes32);

    function defaultMaxNetLossPerGameUsd() external view returns (uint256);

    function requestIdToGame(uint256 requestId) external view returns (address);

    function pendingStakesPerCollateral(address collateral) external view returns (uint256);
}

contracts/interfaces/ICasinoGameCallback.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/// @title ICasinoGameCallback
/// @author Overtime
/// @notice Callback surface every game registered with `CasinoCoreV2` must implement.
/// Core dispatches VRF fulfillments to the originating game through this interface
interface ICasinoGameCallback {
    /// @notice Called by `CasinoCoreV2` once Chainlink VRF returns. Implementations must gate
    /// on `msg.sender == address(core)` to prevent spoofed fulfillments
    /// @param requestId Chainlink VRF request id
    /// @param randomWords Random words returned by VRF
    function onVrfFulfilled(uint256 requestId, uint256[] calldata randomWords) external;
}

contracts/interfaces/ICasinoHiLo.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/// @title ICasinoHiLo
/// @author Overtime
/// @notice Above/below 8 card-guess run with cashout. Each round the player picks ABOVE or
/// BELOW the rank-6 midpoint (card "8"); a fresh card is drawn from a 52-card deck; correct
/// guesses multiply the running multiplier by a constant factor; wrong guess loses the bet;
/// cashout pays `bet * multiplier`. Drawing card "8" is a push (mult unchanged, run continues)
interface ICasinoHiLo {
    enum BetStatus {
        NONE,
        PLAYER_TURN,
        AWAITING_NEXT_CARD,
        RESOLVED,
        CANCELLED
    }

    enum Outcome {
        NONE,
        CASHED_OUT,
        WRONG_GUESS
    }

    enum Direction {
        ABOVE, // bet that next card's rank > MIDPOINT_RANK (i.e., card 9 or higher)
        BELOW // bet that next card's rank < MIDPOINT_RANK (i.e., card 7 or lower)
    }

    /// @notice Per-turn outcome stored alongside the drawn card. NONE only exists for the
    /// default-zero readability of the storage slot — never written
    enum CardOutcome {
        NONE,
        HIT, // correct guess: multiplier advanced
        PUSH, // drew the midpoint card (8): multiplier unchanged, run continues
        BUST // wrong guess: bet resolved, multiplier frozen at pre-bust value in `multipliersE18`
    }

    /// @notice Full Hi-Lo record. For the per-turn history (directions / cards / outcomes /
    /// multipliers per turn), call `getBetCards(betId)` directly — kept off this struct so reads
    /// stay bounded. Two reads per bet for the full picture, but each is a single staticcall
    struct FullRecord {
        uint256 betId;
        address user;
        address collateral;
        uint256 amount;
        uint256 payout;
        uint256 placedAt;
        uint256 resolvedAt;
        BetStatus status;
        Outcome outcome;
        uint8 lastCard; // last drawn card; 0xFF if no card has been drawn yet
        uint256 currentMultiplierE18;
        uint8 guessCount;
        uint8 correctCount;
        uint8 pushCount;
        bool isFreeBet;
        uint256 lastRequestAt;
    }

    event BetPlaced(uint256 indexed betId, address indexed user, address collateral, uint256 amount);

    event GuessChosen(uint256 indexed betId, uint256 indexed requestId, address indexed user, Direction direction);

    event NextCardDealt(
        uint256 indexed betId,
        uint256 indexed requestId,
        address indexed user,
        uint8 newCard,
        bool wasCorrect,
        bool wasPush,
        uint256 newMultiplierE18
    );

    event CashedOut(uint256 indexed betId, address indexed user, uint256 multiplierE18, uint256 payout);

    event BetResolved(uint256 indexed betId, address indexed user, Outcome outcome, uint256 payout);

    event BetCancelled(uint256 indexed betId, address indexed user, uint256 refundAmount, bool adminCancelled);

    /// @notice Places a HiLo bet and submits the first guess in a single transaction. The bet
    /// starts in AWAITING_NEXT_CARD with the first VRF request already in flight. Subsequent
    /// rounds use `makeAction(betId, action)` once the bet returns to PLAYER_TURN.
    /// `isFreeBet=true` pulls the stake from FreeBetsHolder, `false` from the user's wallet
    function placeBet(
        address collateral,
        uint256 amount,
        address referrer,
        Direction firstDirection,
        bool isFreeBet
    ) external returns (uint256 betId, uint256 requestId);

    /// @notice Single-selector mid-game dispatcher. Action codes:
    ///   0 = guess ABOVE
    ///   1 = guess BELOW
    ///   2 = cashout
    function makeAction(uint256 betId, uint8 action) external returns (uint256 requestId);

    function adminCancelBet(uint256 betId) external;

    function getBetBase(
        uint256 betId
    )
        external
        view
        returns (
            address user,
            address collateral,
            uint256 amount,
            uint256 payout,
            uint256 placedAt,
            uint256 resolvedAt,
            BetStatus status,
            Outcome outcome
        );

    function getBetState(
        uint256 betId
    )
        external
        view
        returns (uint8 lastCard, uint256 currentMultiplierE18, uint8 guessCount, uint8 correctCount, uint8 pushCount);

    /// @notice Returns the full per-turn history for `betId`. The four arrays are parallel and
    /// aligned (one entry per resolved card), except `directions` which has one entry per
    /// submitted guess: while VRF for the latest guess is in flight, `directions.length ==
    /// cards.length + 1`. The bust branch writes the pre-bust (frozen) multiplier so the FE can
    /// render "you were at Nx before busting"
    function getBetCards(
        uint256 betId
    )
        external
        view
        returns (
            uint8[] memory directions,
            uint8[] memory cards,
            uint8[] memory outcomes, // CardOutcome cast to uint8
            uint256[] memory multipliersE18
        );

    /// @notice Constant per-correct-guess multiplier factor: `(12 - 13*HE) / 6` in 1e18 precision
    function multiplierFactorE18() external view returns (uint256);

    function getUserBetIds(address user, uint256 offset, uint256 limit) external view returns (uint256[] memory);

    function getRecentBetIds(uint256 offset, uint256 limit) external view returns (uint256[] memory);

    /// @notice One-shot full record reader. Per-turn history is intentionally not bundled here —
    /// call `getBetCards(betId)` for that
    function getFullRecord(uint256 betId) external view returns (FullRecord memory);

    function nextBetId() external view returns (uint256);
}

