// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/// @title ICasinoKeno
/// @author Overtime
/// @notice Single-shot Keno: 80-number pool, 20 numbers drawn per round, player picks 1–10
/// numbers before the draw. Payout is `bet × paytable[picksCount][hits]` where `hits` is the
/// overlap between the player's picks and the 20 drawn numbers. Multipliers stored in 1e18
/// precision and capped at 100x. Per-bet liability is bounded by both the multiplier cap and
/// a $10 max bet, giving a hard $1000 ceiling per bet
interface ICasinoKeno {
    enum BetStatus {
        NONE,
        PENDING,
        RESOLVED,
        CANCELLED
    }

    /// @notice Full Keno record
    struct FullRecord {
        uint256 betId;
        address user;
        address collateral;
        uint256 amount;
        uint256 payout;
        uint256 placedAt;
        uint256 resolvedAt;
        BetStatus status;
        uint8 picksCount;
        uint8 hits;
        uint128 picksMask; // bitmask of player's picks (numbers 1..80 → bits 0..79)
        uint128 drawnMask; // bitmask of the 20 drawn numbers (set when status == RESOLVED)
        uint256 multiplierE18;
        bool isFreeBet;
        uint256 lastRequestAt;
    }

    event BetPlaced(
        uint256 indexed betId,
        uint256 indexed requestId,
        address indexed user,
        address collateral,
        uint256 amount,
        uint8 picksCount,
        uint128 picksMask
    );

    event BetResolved(
        uint256 indexed betId,
        uint256 indexed requestId,
        address indexed user,
        uint128 drawnMask,
        uint8 hits,
        uint256 multiplierE18,
        uint256 payout
    );

    event BetCancelled(uint256 indexed betId, address indexed user, uint256 refundAmount, bool adminCancelled);

    event PaytableUpdated(uint8 indexed picksCount, uint256[] multipliersE18);

    /// @notice Places a Keno bet. `picks` must be a sorted, deduplicated array of 1..80,
    /// length 1..10. One VRF word resolves the bet. `isFreeBet=true` pulls the stake from
    /// FreeBetsHolder; `false` from the user's wallet. Single canonical entry
    function placeBet(
        address collateral,
        uint256 amount,
        uint8[] calldata picks,
        address referrer,
        bool isFreeBet
    ) external returns (uint256 betId, uint256 requestId);

    function adminCancelBet(uint256 betId) external;

    function getBetBase(
        uint256 betId
    )
        external
        view
        returns (
            address user,
            address collateral,
            uint256 amount,
            uint256 payout,
            uint256 placedAt,
            uint256 resolvedAt,
            BetStatus status,
            uint8 picksCount,
            uint8 hits,
            uint128 picksMask,
            uint128 drawnMask,
            uint256 multiplierE18
        );

    function getPaytable(uint8 picksCount) external view returns (uint256[] memory multipliersE18);

    function getMaxMultiplierE18() external view returns (uint256);

    function getUserBetIds(address user, uint256 offset, uint256 limit) external view returns (uint256[] memory);

    function getRecentBetIds(uint256 offset, uint256 limit) external view returns (uint256[] memory);

    /// @notice One-shot full record reader
    function getFullRecord(uint256 betId) external view returns (FullRecord memory);

    function nextBetId() external view returns (uint256);
}

contracts/interfaces/ICasinoOvertimeBonu.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/// @title ICasinoOvertimeBonusHoldem
/// @author Overtime
/// @notice Texas Hold'em Bonus / Casino Hold'em variant against the dealer. Mandatory ANTE +
/// optional BONUS side bet. Pre-flop is "Play 2× or fold"; each later street allows one optional
/// 1× raise or check. No dealer qualification. ANTE pays 1:1 only on Straight+, otherwise pushes
interface ICasinoOvertimeBonusHoldem {
    /* ========== ENUMS ========== */

    enum BetStatus {
        NONE,
        AWAITING_HOLE,
        PRE_FLOP_TURN,
        AWAITING_FLOP,
        FLOP_TURN,
        AWAITING_TURN,
        TURN_TURN,
        // AWAITING_RIVER / RIVER_TURN are no longer reachable for new bets — the river raise was
        // removed (river is now a free showdown card dealt in _onResolve). The values are RETAINED
        // (not deleted) so enum ordinals of the later states and any persisted `status` of
        // in-flight bets stay stable across the upgrade. Do not renumber
        AWAITING_RIVER,
        RIVER_TURN,
        AWAITING_RESOLVE,
        RESOLVED,
        CANCELLED
    }

    enum Outcome {
        NONE,
        FOLDED,
        PLAYER_WIN,
        DEALER_WIN,
        TIE
    }

    /* ========== STRUCTS ========== */

    /// @notice Full bet record returned by `getFullRecord`. Per-leg payout breakdown lets FE
    /// render exactly how each stake leg settled
    struct FullRecord {
        uint256 betId;
        address user;
        address collateral;
        uint256 anteAmount;
        uint256 bonusAmount;
        uint256 playAmount; // 2× ante if pre-flop Play taken, else 0 (folded pre-flop)
        uint256 flopRaise; // 1× ante if raised on flop
        uint256 turnRaise; // 1× ante if raised on turn
        uint256 riverRaise; // 1× ante if raised on river
        uint256 totalPayout;
        uint256 antePayout;
        uint256 bonusPayout;
        uint256 playPayout;
        uint256 flopPayout;
        uint256 turnPayout;
        uint256 riverPayout;
        uint256 placedAt;
        uint256 resolvedAt;
        BetStatus status;
        Outcome outcome;
        uint8[2] playerHole;
        uint8[5] community; // [flop0, flop1, flop2, turn, river]
        uint8[2] dealerHole;
        bool isFreeBet;
        uint256 lastRequestAt;
    }

    /* ========== EVENTS ========== */

    event BetPlaced(
        uint256 indexed betId,
        uint256 indexed requestId,
        address indexed user,
        address collateral,
        uint256 anteAmount,
        uint256 bonusAmount
    );

    event PlayerHoleDealt(uint256 indexed betId, uint256 indexed requestId, address indexed user, uint8 hole0, uint8 hole1);

    event PlayedPreFlop(uint256 indexed betId, uint256 indexed requestId, address indexed user, uint256 playAmount);

    event FlopDealt(
        uint256 indexed betId,
        uint256 indexed requestId,
        address indexed user,
        uint8 flop0,
        uint8 flop1,
        uint8 flop2
    );

    event RaisedFlop(uint256 indexed betId, uint256 indexed requestId, address indexed user, uint256 raiseAmount);
    event CheckedFlop(uint256 indexed betId, uint256 indexed requestId, address indexed user);

    event TurnDealt(uint256 indexed betId, uint256 indexed requestId, address indexed user, uint8 turn);
    event RaisedTurn(uint256 indexed betId, uint256 indexed requestId, address indexed user, uint256 raiseAmount);
    event CheckedTurn(uint256 indexed betId, uint256 indexed requestId, address indexed user);

    // The river is a free showdown card (no raise leg), dealt during resolve — no Raised/Checked
    // river events. RiverDealt still fires from `_onResolve` when the board is completed
    event RiverDealt(uint256 indexed betId, uint256 indexed requestId, address indexed user, uint8 river);

    event Folded(uint256 indexed betId, address indexed user, BetStatus stage);

    event BetResolved(
        uint256 indexed betId,
        uint256 indexed requestId,
        address indexed user,
        Outcome outcome,
        uint8 dealer0,
        uint8 dealer1,
        uint256 antePayout,
        uint256 bonusPayout,
        uint256 mainPayout,
        uint256 totalPayout
    );

    event BetCancelled(uint256 indexed betId, address indexed user, uint256 refund, bool adminCancelled);

    /// @notice Emitted when the cap-spill cascade can't absorb the full `cut` from the leg
    /// payouts and the final leg is zero-clamped, losing `residual` from the cut. Structurally
    /// unreachable today (`cut ≤ totalPay` always); firing indicates a future regression in
    /// the `profitCapRemaining` accounting that off-chain monitoring should alert on
    event CapSpillResidual(uint256 indexed betId, uint256 residual);

    /* ========== STATE-CHANGING ========== */

    /// @notice Places a BH bet. `isFreeBet=true` pulls Ante + Bonus from FBH; `false` from the
    /// user's wallet. Bonus must be zero when `isFreeBet` is true
    /// (reverts `BonusNotAllowedForFreeBet`)
    function placeBet(
        address collateral,
        uint256 anteAmount,
        uint256 bonusAmount,
        address referrer,
        bool isFreeBet
    ) external returns (uint256 betId, uint256 requestId);

    /// @notice Single-selector mid-game dispatcher. Action codes:
    ///   0 = playPreFlop    1 = foldPreFlop
    ///   2 = raiseFlop      3 = checkFlop
    ///   4 = raiseTurn      5 = checkTurn
    ///   6 = raiseRiver     7 = checkRiver
    /// No fold post-flop: `check*` is free, so any post-flop fold is strictly dominated in money
    /// EV (lose ante guaranteed vs free chance to win at showdown). Use check at every post-flop
    /// street; raise to commit additional stake
    function makeAction(uint256 betId, uint8 action) external returns (uint256 requestId);

    function adminCancelBet(uint256 betId) external;

    /* ========== VIEWS ========== */

    function getBetBase(
        uint256 betId
    )
        external
        view
        returns (
            address user,
            address collateral,
            uint256 anteAmount,
            uint256 bonusAmount,
            uint256 totalPayout,
            uint256 placedAt,
            uint256 resolvedAt,
            BetStatus status,
            Outcome outcome
        );

    function getFullRecord(uint256 betId) external view returns (FullRecord memory);

    function getUserBetIds(address user, uint256 offset, uint256 limit) external view returns (uint256[] memory);

    function getRecentBetIds(uint256 offset, uint256 limit) external view returns (uint256[] memory);

    function nextBetId() external view returns (uint256);
}

