    function paused() external view returns (bool);

    function cashoutTicketWithLegOdds(
        address _ticket,
        uint[] calldata approvedOddsPerLeg,
        bool[] calldata isLegSettled,
        address _recipient
    ) external returns (uint cashoutAmount);
}

